local P = LoreForeverPacks.Begin("LoreForever_Lang_zhCN")
P.entries["quest:332"] = {n="酒店的广告",s="“酒馆广告”是雷纳多·加林纳在暴风城Trade District分发的一项简短的宣传差事。他用一张可以免费领取一瓶其家族运河旁店面所售陈年葡萄酒的代金券来吸引路人。这让我们得以从日常生活的角度，一窥这座重建后的首都在贸易和小型企业方面的繁荣景象。",h="“酒馆广告”是雷纳多·加林纳在暴风城Trade...",kw={"运河","加林纳酒庄","黑皮诺","雷纳多·加林纳","苏泽塔·加林纳","trade district","酒馆广告","酒票"},ang={["faction:Alliance"]="即使在战争动荡和国王失踪的时期，暴风城繁忙的Trade District依然维持着一个活跃的本地奢侈品和进口商品市场。",["profession:Cooking"]="加林纳家族分发的黑皮诺等美酒，是东部王国各地酒馆所制作丰盛餐点的绝佳搭配。",["race:Human"]="对于在暴风城重建家园的人类来说，运河沿岸出现的家族经营酒庄是城市复苏的慰藉之兆。"},sec={{t="运河的滋味",b="尽管冒险者们常常忙于应对军事威胁和政治阴谋，但暴风城的日常生活却围绕着繁忙的商业活动展开。雷纳多·加林纳走在Trade District的鹅卵石路上，推销着他与妹妹苏泽塔共同经营的小店——加林纳酒庄。为了吸引口渴的游客和当地居民，他会分发宣传单，持有宣传单的人可以免费品尝葡萄酒。"},{t="黑皮诺陈酿",b="加林纳家族提供的奖品是一瓶他们著名的黑皮诺。顾客拿着票据来到运河水道附近的酒庄入口，苏泽塔·加林纳会准备好将酒递给他们。她坚信，只要抿上一口他们的招牌酒，任何新客都会变成忠实的老主顾。"}},faq={{q="加林纳酒庄位于何处？",a="加林纳酒庄坐落在暴风城的Trade District，紧邻风景优美的运河边缘，距离雷纳多·加林纳的宣传路线不远。",al={"加林纳酒庄位置","苏泽塔·加林纳位置","酒馆广告任务交还地点"}},{q="雷纳多和苏泽塔·加林纳是谁？",a="雷纳多和苏泽塔·加林纳是一对在暴风城经营独立酒庄的兄妹。雷纳多在街上四处游荡，用宣传单推销他们的生意；而苏泽塔则负责照看店面柜台并倒酒。",al={"加林纳一家是谁","雷纳多·加林纳","苏泽塔·加林纳背景故事"}},{q="这张票可以换取什么酒？",a="一瓶加林纳家族著名的黑皮诺，这是该店的招牌红酒，雷纳多希望它能将新客变成忠实的老主顾。",al={"黑皮诺葡萄酒","奖励什么葡萄酒","暴风城黑皮诺"}},{q="雷纳多为什么要发放免费的葡萄酒兑换券？",a="这是经典的街头营销手段。雷纳多利用他们珍贵存货的免费试饮，将客流吸引到他们运河边的店里，并以此在暴风城的市民中建立起回头客基础。",al={"为什么免费送酒","酒馆宣传票用途"}},{q="这个差事有任何危险或战斗吗？",a="没有。这项差事仅仅包括从雷纳多那里拿一张宣传票，然后穿过Trade District安全的街道，走一小段路去店面找苏泽塔。",al={"酒馆广告任务危险吗","葡萄酒任务战斗"}},{q="加林纳酒庄还卖其他商品吗？",a="苏泽塔备有一些普通的葡萄酒和含酒精饮料，供口渴的旅行者、休息中的卫兵以及需要补货的当地酒馆供应商选购。",al={"苏泽塔还卖什么","加林纳酒庄饮品"}}},fp="16,202,21.251.0,22.241.0,36.99.0,35.155.0,31.87.0,43.107.0,46.148.0,41.116.0"}
P.entries["quest:333"] = {n="哈兰需要供货",s="暴风城的商人哈兰·巴格雷发现，由于人们对坚固衣物和护甲的需求激增，他的货架已被抢购一空。他并不了解城墙外正在酝酿的冲突，于是派出一名信使，带着一份紧急布料订单前往运河裁缝店，送交给雷玛·施涅德。",h="暴风城的商人哈兰·巴格雷发现，由于人们对坚固衣物和护甲的需求激增，他的货架已被抢购一空。他并不了解城墙外正在酝酿的冲突，于是派出一名信使，带着一份紧急布料订单前往运河裁缝店，送交给雷玛·施涅德。",kw={"巴格雷","运河","布料","哈兰","雷玛","补给","施涅德","暴风城","裁缝"},ang={["faction:Alliance"]="在瓦里安·乌瑞恩国王缺席的情况下，暴风城购物者中弥漫的静默恐慌，暗示了联盟心脏地带日益增长的不安。",["profession:Tailoring"]="这次差事让我们得以一窥暴风城纺织工业的日常物流，即小型运河作坊如何为大型商业店铺供货。",["race:Human"]="暴风城的工人阶级工匠对他们的统治者保持警惕，怀疑贵族们对普通市民隐瞒了迫在眉睫的危险。"},sec={{t="坚固衣物的抢购潮",b="在暴风城的繁华商业区，像哈兰·巴格雷这样的店主发现库存正在以惊人的速度减少。普通市民和四处游历的冒险者都在抢购加固的外衣、旅行装和战备护甲。在哈兰看来，王国的人民似乎在为严冬或寒冷的季节做准备，但如此巨大的销售量还是让他的商店库存告急，急需成品布料。"},{t="运河边的疑问",b="为了补充货架，巴格雷派了一名跑腿穿过城市的水道，前往运河裁缝店，将订单送交给裁缝雷玛·施涅德。虽然雷玛对生意兴隆感到高兴，但这种对防护装备的突然抢购让她感到不安。整个王国弥漫着紧张的传言，这位裁缝不禁怀疑暴风城的贵族议会是否在向平民隐瞒战争爆发的消息。"}},faq={{q="哈兰·巴格雷是谁？",a="哈兰·巴格雷是暴风城的一名服装商人和店主。他的生意依赖于当地的裁缝，以维持其店内针织品和旅行服饰的库存。",al={"哈兰·巴格雷","哈兰是谁","巴格雷 暴风城"}},{q="雷玛·施涅德是谁？",a="雷玛·施涅德是一位专业的裁缝，在暴风城的运河裁缝店工作。她和丈夫科尔贝特一起，为城里的商人们供应新缝制的布料和服饰。",al={"雷玛·施涅德","裁缝雷玛","运河裁缝店"}},{q="为什么哈兰的衣服快卖光了？",a="市民和旅行者正在以异常高的数量购买护甲和耐用的衣物。哈兰开玩笑说，人们的举动就像严冬将至一样，尽管真正的起因是王国边境日益增长的动荡和危险。",al={"为什么布料短缺","为什么购买护甲","哈兰生意兴隆"}},{q="为什么雷玛·施涅德怀疑贵族？",a="雷玛觉得在没有官方宣战的情况下，普通民众突然把自己武装起来是很不正常的。由于国王瓦里安·乌瑞恩不在城中，贵族议会掌控着王室事务，她担心贵族阶层在向公众隐瞒即将到来的战争。",al={"雷玛 贵族","暴风城贵族隐瞒战争","为何怀疑贵族"}},{q="运河裁缝店在哪里？",a="运河裁缝店坐落在穿过暴风城的水道旁，位置便利地处于各大城区之间，便于商人们送货。",al={"运河裁缝店位置","雷玛·施涅德在哪里","运河裁缝店在哪里"}},{q="布料订单送达后会发生什么？",a="收到订单后，雷玛让她的丈夫科尔贝特·施涅德将另一批针织品运过城市，送给狮王之傲旅店（Lionheart Armory）的哈兰。科尔贝特在回店的路上还在崔亚斯奶酪店停下来买了一点零食。",al={"科尔贝特·施涅德的行程","科尔贝特做什么","雷玛的丈夫"}}},fp="23,240,23.276.0,23.337.0,21.135.0,22.205.0,38.221.0,43.269.0,47.156.0,50.232.0"}
P.entries["quest:334"] = {n="萨尔曼的针线包",s="“送给萨尔曼的包裹”是在暴风城的大街小巷中穿梭的一项简单差事。一位焦急的母亲，雷玛·施涅德，请求过往的旅行者将她粗心的学徒儿子遗忘的裁缝工具送到位于法师区（Mage Quarter）的拉尔森裁缝店。",h="“送给萨尔曼的包裹”是在暴风城的大街小巷中穿梭的一项简单差事。一位焦急的母亲，雷玛·施涅德，请求过往的旅行者将她粗心的学徒儿子遗忘的裁缝工具送到位于法师区（Mage Quarter）的拉尔森裁缝店。",kw={"学徒","裁缝店","拉尔森","mage quarter","雷玛","施涅德","缝纫工具包","暴风城","萨尔曼"},ang={["faction:Alliance"]="在暴风城要塞的高层政治之下，普通的市民和工匠们让这座都城得以穿衣、吃饭，并维持着日常运转。",["profession:Tailoring"]="每一位伟大的裁缝都是从底层做起的：缝补衣边、按住针脚，并试图从拉尔森裁缝店的学徒杂务中溜出去。"},sec={{t="母亲的差事",b="在暴风城日复一日的忙碌中，并非每一项任务都与对抗豺狼人或揭露迪菲亚兄弟会的阴谋有关。雷玛·施涅德很担心儿子萨尔曼·斯涅德的生计，她发现儿子出门时走得太匆忙，落下了他的剪刀和针线。担心他会因此耽误学徒工作，她恳求一位冒险者把这套工具送到城对面的工作坊里去。"},{t="勉强的学徒",b="拉尔森裁缝店坐落在法师区（Mage Quarter）深处，距离高耸的法师塔并不远。在拿到工具后，萨尔曼·斯涅德透露他是故意把剪刀留在家里的——这是他为了逃避日常杂务、去玩上一整天而策划的诡计。然而，随着母亲的介入，他下午的自由时光化为泡影，只能被迫回到缝纫台前。"}},faq={{q="谁发布了“送给萨尔曼的包裹”任务？",a="雷玛·施涅德发布了这个任务。她正在寻找能够把缝纫工具包送到她儿子手中的人，她儿子在城另一头的法师区（Mage Quarter）工作。",al={"谁发布任务","雷玛·施涅德任务","任务发布者"}},{q="萨尔曼·斯涅德在哪里？",a="萨尔曼·斯涅德位于暴风城法师区（Mage Quarter）的拉尔森裁缝店内。这家店位于法师区更深处，靠近通往法师塔的道路。",al={"萨尔曼位置","萨尔曼在哪里","寻找萨尔曼"}},{q="萨尔曼真的是不小心忘记带工具了吗？",a="雷玛认为是萨尔曼走得太匆忙没带工具包，所以请求你把它带给他。",al={"萨尔曼是否忘记了","萨尔曼为何留下工具","萨尔曼偷懒"}},{q="萨尔曼在哪个店铺当学徒？",a="萨尔曼在拉尔森裁缝店当裁缝学徒，这是一家位于暴风城法师区（Mage Quarter）的服装店，由拉尔森家族经营。",al={"萨尔曼在哪里工作","拉尔森裁缝店","萨尔曼为谁工作"}},{q="为什么雷玛·施涅德会请求冒险者帮忙？",a="雷玛认为如果失去了工具包，她儿子的学徒生涯将会受到威胁。由于自己无法离开工作岗位，她便向那些可能正要前往法师区（Mage Quarter）的过路冒险者寻求帮助。",al={"为何请求玩家","雷玛的帮助"}},{q="送出缝纫工具包后会发生什么？",a="萨尔曼收下了他的工具，并回去继续帮拉尔森一家做针线活。",al={"任务奖励","送给萨尔曼的包裹之后","萨尔曼的反应"}}},fp="19,179,17.193.0,22.236.1,41.101.0,37.111.0,50.86.1,38.123.0,51.173.0,46.69.1"}
P.entries["quest:335"] = {n="名酿",s="在暴风城Slaughtered Lamb阴暗的深处，黑爪加尔德斯正策划着针对城中贵族的阴谋。一位好奇的贵族，Wishock勋爵，威胁要揭露酒馆下方的术士聚集地，迫使他们暗中收集稀有而强大的试剂来消除这一威胁。",h="在暴风城Slaughtered Lamb阴暗的深处，黑爪加尔德斯正策划着针对城中贵族的阴谋。一位好奇的贵族，Wishock勋爵，威胁要揭露酒馆下方的术士聚集地，迫使他们暗中收集稀有而强大的试剂来消除这一威胁。",kw={"夜色镇","贵族议会","麝鼠根","slaughtered lamb","巨石水坝","蒂罗亚之泪","wishock","加尔德斯"},ang={["class:Warlock"]="Slaughtered Lamb下方的地下室是你在暴风城的避风港。协助加尔德斯可以保护你们暗影之道的兄弟姐妹免受王国那所谓的正义贵族的窥探。",["faction:Alliance"]="在瓦里安·乌瑞恩国王失踪期间，贵族议会内部的政治斗争达到了顶峰，内部丑闻对城市的稳定构成了特别的威胁。",["profession:Herbalism"]="蒂罗亚之泪和麝鼠根代表了稀有且特殊的植物，它们只在那些因残酷历史或纯净水流而形成的地区茁壮生长。"},sec={{t="来自贵族的威胁",b="在Mage Quarter的街道之下，以Slaughtered Lamb为基地的术士结社享受着岌岌可危的秘密状态。但这层秘密正受到Wishock勋爵的威胁，作为贵族议会的一员，他察觉到了在这座城市下方涌动的黑暗魔法。Wishock开始游说其他同僚进行全面调查，这将会招致城卫兵和王室对结社的关注。"},{t="阴影中的药剂",b="为了避免与暴风城的统治阶级发生公开冲突，黑爪加尔德斯设计了一种隐秘的药剂，以确保Wishock勋爵永远无暇他顾。这种药剂的配制需要从东部王国的各个遥远角落采集稀有的植物成分：一种来自暮色森林的苍白花朵——蒂罗亚之泪，以及从巨石水坝下方采摘的沉水麝鼠根。"}},faq={{q="Wishock勋爵是谁？",a="Wishock勋爵是暴风城贵族议会的一名贵族。在发现了隐藏在Mage Quarter下方的术士活动迹象后，他开始向议会施压，要求进行正式调查。",al={"wishock勋爵","wishock勋爵是谁"}},{q="黑爪加尔德斯是谁？",a="加尔德斯是一位在暴风城Slaughtered Lamb酒馆下方的地下室中活动的资深术士。他致力于保护城中的术士帮派免遭当局的发现和清洗。",al={"加尔德斯","黑爪加尔德斯","黑爪加尔德斯是谁"}},{q="蒂罗亚之泪产自哪里？",a="蒂罗亚之泪是一种娇嫩的白花，生长在暮色森林夜色镇郊外杂草丛生的斯塔文庄园中。",al={"蒂罗亚之泪位置","蒂罗亚之泪","蒂罗亚之泪在哪"}},{q="麝鼠根在哪里可以找到？",a="麝鼠根只生长在湿地，即巨石水坝下方倾泻而下的巨大瀑布的最底部湿地区域。",al={"麝鼠根位置","麝鼠根","麝鼠根怎么获得"}},{q="为什么暴风城政府还没有发现这些术士？",a="术士在暴风城深受信徒怀疑，因此Slaughtered Lamb下的结社将他们的修炼隐藏在地下，避开城卫兵和贵族的视线。Wishock勋爵只是刚刚察觉到这一点。",al={"暴风城术士秘密","术士为何隐藏","术士是否非法"}},{q="加尔德斯打算用这些试剂配制什么？",a="加尔德斯声称这种药剂会让Wishock勋爵“无暇他顾”，从而使调查停滞不前。他究竟想对这位贵族做什么，只有在药剂准备好之后才会揭晓。",al={"这种药剂是什么","药剂用途","为什么要配制药剂"}}},fp="12,156,24.304.0,27.311.1,20.186.0,33.170.0,40.130.0,33.128.0,67.202.0,53.158.1"}
P.entries["quest:336"] = {n="名酿",s="“高贵的佳酿”是一场精心策划的阴谋的高潮，它源自暴风城Slaughtered Lamb下方的阴暗地窖。在黑爪加尔德斯的指使下，一名不知情或毫不在意的信使将一种名为黑爪烈酒的强力药剂送到了位于皇家要塞内的鲍雷斯·维沙克公爵手中。",h="“高贵的佳酿”是一场精心策划的阴谋的高潮，它源自暴风城Slaughtered...",kw={"鲍雷斯·维沙克","黑爪烈酒","请愿者大厅","高贵的佳酿","slaughtered lamb","stormwind keep","加尔德斯"},sec={{t="高贵的伪君子",b="鲍雷斯·维沙克公爵是一位经常出入Stormwind Keep内请愿者大厅的贵族，他总是自命不凡地宣扬王国的未来。然而，在他贵族式的姿态下隐藏着一个Slaughtered Lamb常客皆知的公开秘密：每到夜晚，维沙克就会光顾酒馆的楼上房间，豪饮买醉，并欠下巨额从未结清的酒账。更令酒馆无法容忍的是，他白天还到处请愿，试图彻底关闭这家酒馆。"},{t="致死的敬酒",b="黑爪加尔德斯，一名潜伏在酒馆下方黑暗角落里的术士，决定以一种永久的方式清偿维沙克的债务。他酿造了一种特殊的饮品——黑爪烈酒，并声称它“劲儿很大”。当这杯冒着泡沫的酒杯在请愿者大厅被递到那傲慢的公爵面前时，他错把信使当成了普通的仆人，随手扔出一枚铜币作为打赏，随后贪婪地一饮而尽，片刻之后便倒地身亡，死在了要塞大厅之中。"}},faq={{q="黑爪加尔德斯是谁？",a="黑爪加尔德斯是一名术士，隶属于在暴风城Mage Quarter的Slaughtered Lamb下方隐秘墓穴中活动的暗影结社。他在城市卫兵的视野之外进行着危险的秘密行动。",al={"黑爪加尔德斯是谁","黑爪加尔德斯","谁发布的任务"}},{q="为什么黑爪加尔德斯要针对维沙克公爵？",a="维沙克是一个酗酒的伪君子，他晚上在Slaughtered Lamb的楼上饮酒作乐却从不付账，白天却在请愿者大厅要求当局关闭这家酒馆。",al={"为什么要杀维沙克","维沙克的动机","为什么下毒"}},{q="哪里可以找到维沙克公爵？",a="鲍雷斯·维沙克公爵经常在请愿者大厅徘徊，那是Stormwind Keep内的一个前厅，贵族和市民们聚集在那里向王国摄政者请愿。",al={"维沙克公爵的位置","维沙克在哪里","请愿者大厅的维沙克"}},{q="维沙克公爵是如何收到这杯酒的？",a="维沙克把信使误认为是仆人，便将这杯烈酒当作解渴的饮料接了过去，并随手扔出一枚铜币将信使打发走。",al={"维沙克会死吗","维沙克的死","这种烈酒有什么用"}},{q="送酒会引起卫兵的注意吗？",a="交付过程被视为普通的仆人送酒，信使无需与卫兵发生冲突即可继续执行任务。",al={"卫兵会攻击吗","我在暴风城被通缉了吗","下毒的后果"}},{q="这次投递之后是什么任务？",a="任务将继续进行，名为“你服务得很好”，玩家需要回到Slaughtered Lamb下方找黑爪加尔德斯复命。",al={"what comes next","高贵的佳酿任务之后","下一个任务"}}},fp="12,156,17.267.0,14.291.1,33.208.0,37.182.1,28.158.0,39.111.1,56.123.1,33.116.1"}
P.entries["quest:3361"] = {n="逃难者的困境",s="诺莫瑞根被穴居人和辐射摧毁后，流离失所的侏儒逃进了丹莫罗冰雪覆盖的荒野之中。在安威玛尔外，一位名叫菲利克斯的工程师在惊慌撤离时，他赖以生存的财物和工具被霜鬃巨魔拾荒者抢走了。",h="诺莫瑞根被穴居人和辐射摧毁后，流离失所的侏儒逃进了丹莫罗冰雪覆盖的荒野之中。在安威玛尔外，一位名叫菲利克斯的工程师在惊慌撤离时，他赖以生存的财物和工具被霜鬃巨魔拾荒者抢走了。",kw={"安威玛尔","一桶螺栓","寒脊山谷","菲利克斯","霜鬃","诺莫瑞根","辐射"},ang={["profession:Engineering"]="没有哪个自尊的工匠能眼睁睁看着拾荒者抢走那些耗尽一生心血收集来的精密螺栓、卡尺和工具箱。",["race:Dwarf"]="寒脊山脉保护了你们的同胞数个世纪；帮助侏儒难民在安威玛尔站稳脚跟，是对铁炉堡和诺莫瑞根之间古老盟约的尊重。",["race:Gnome"]="这个任务浓缩了你们族人所面临的惨痛悲剧：在失去了毒气弥漫、背叛丛生的奇妙家园后，普通的技工现在不得不恳求陌生人从粗鲁的巨魔手中夺回基本的工具。"},sec={{t="逃离诺莫瑞根",b="当潜地穴居人占领了高科技城市诺莫瑞根时，大工匠Gelbin Mekkatorque和他的顾问授权释放了放射性气体，试图绝望地消灭入侵者。这一计策产生了灾难性的后果，数千名无辜者惨死，幸存者变异成了毫无理智的麻风侏儒，迫使剩下的居民在丹莫罗展开了疯狂的大逃亡。"},{t="雪地里的拾荒者",b="逃离的工程师和技工们带走了他们能保住的所有珍贵工具和蓝图。然而，诺莫瑞根和寒脊山谷之间的冰冷山路被当地的霜鬃巨魔所占据。当菲利克斯艰难地向安威玛尔的避难所跋涉时，霜鬃掠夺者抢走了他的工具箱、锁箱和一桶螺栓，并将它们运到了镇子西南方的营地里。"}},faq={{q="菲利克斯是谁？",a="菲利克斯是一位侏儒工程师，他侥幸逃过了诺莫瑞根那场放射性毁灭浩劫。由于缺乏战斗技能来应对丹莫罗的危险，他躲在安威玛尔附近，试图找回被盗的设备。",al={"菲利克斯","菲利克斯是谁","菲利克斯 安威玛尔"}},{q="诺莫瑞根为什么会受到辐射？",a="在一次突如其来的穴居人入侵期间，侏儒当局释放了不稳定的放射性气体，旨在消灭这些怪物。然而，这些气体反而污染了城市的通风系统，杀死了或是导致大部分居民变异，使得这座首都城市变得无法居住。",al={"诺莫瑞根发生了什么","诺莫瑞根辐射","诺莫瑞根的陷落"}},{q="是谁偷了菲利克斯的财物？",a="霜鬃巨魔抢走了他的工具箱、锁箱和一桶螺栓。这些当地的巨魔经常在丹莫罗的山路上伏击旅行者，并将抢来的废料和装备运回安威玛尔西南方的简陋营地。",al={"谁偷了螺栓","谁拿了菲利克斯的东西","霜鬃巨魔"}},{q="流离失所的侏儒在哪里寻求庇护？",a="许多侏儒逃过丹莫罗前往矮人王国铁炉堡，而另一些人则在丹莫罗各处的安威玛尔和卡拉诺斯等较小的定居点寻求临时避难。",al={"侏儒住在哪里","侏儒难民","侏儒定居点"}},{q="为什么一桶螺栓如此重要？",a="对于一位流亡的侏儒技工来说，工具、特制螺丝和机械螺栓就是他们的全部生计。没有合适的装备，流亡的工程师就无法从事他们的职业、制作防御工事或在流亡中重建生活。",al={"为什么是螺栓","菲利克斯 螺栓"}},{q="霜鬃巨魔对寒脊山谷构成了什么威胁？",a="霜鬃部族长期居住在丹莫罗严酷的山峰上。随着近期穴居人的爆发以及诺莫瑞根撤离时的混乱，这些巨魔变得更加猖獗，不断袭击补给线并伏击旅行者。",al={"丹莫罗的巨魔","霜鬃威胁","霜鬃营地"}}},fx={["0b2d3aab"]={q="菲利克斯为什么想要拿回自己的物品？",a="菲利克斯逃离遭受辐射污染的诺莫瑞根时，身上几乎只剩衣服，失去了赖以维生和谋生的最后一点家当。没有自己的箱子、盒子和工具，他在安威玛尔无依无靠，既无法重建生活，也无法继续手艺，只能作为难民度日。",al={"菲利克斯的动机","菲利克斯为什么需要这个","菲利克斯的物品"}},["48f90e68"]={q="菲利克斯为什么不能自己取回物品？",a="菲利克斯只是个普通的技工和流离失所的难民，并非冒险者或士兵。他害怕危机四伏的荒野，也不是带走他装备的霜鬃巨魔的对手，不能冒险独自闯入他们的营地。",al={"菲利克斯为什么不自己拿东西","菲利克斯为什么需要我","菲利克斯为什么找我帮忙"}},["6a13a14f"]={q="菲利克斯的盒子和箱子里有什么？",a="菲利克斯的箱子和盒子里装着他逃离诺莫瑞根灾难时设法收拾的个人物品和专用工具。对于一个远离家乡、流离失所的工匠来说，这些容器里装着他重新开始所需的一切。",al={"菲利克斯的盒子","菲利克斯的箱子","菲利克斯的箱子里有什么"}}},fp="20,206,26.299.0,22.354.0,25.201.0,29.233.0,29.194.0,43.135.0,42.212.0,61.203.0"}
P.entries["quest:3362"] = {n="灌木谷",s="位于加基森的特兰雷克想要进入灌木谷，但那里的奇异野兽让他望而却步。清理掉一些灌木，特兰雷克或许会考虑回去。",h="位于加基森的特兰雷克想要进入灌木谷，但那里的奇异野兽让他望而却步。清理掉一些灌木，特兰雷克或许会考虑回去。",kw={"仙人掌","加基森","扭曲的灌木","根塑者","塔纳利斯","灌木","特兰雷克","灌木谷"},sec={{t="危险的峡谷",b="灌木谷位于加基森西南方，特兰雷克称那是个极其危险的地方。他不相信那里的奇异野兽——扭曲的灌木和灌木根塑者，因为数量太多，他不敢回去。"},{t="清理灌木",b="特兰雷克想要清理掉八只扭曲的灌木和八只灌木根塑者。有一个条件：特兰雷克想近距离观察山谷里的仙人掌，所以必须保留一部分仙人掌完好无损。"}},faq={{q="谁请求协助清理灌木谷？",a="位于加基森的特兰雷克。",al={"任务发布者","特兰雷克位置","谁提供灌木谷任务"}},{q="灌木谷在哪里？",a="它位于加基森西南方。",al={"灌木谷位置","峡谷在哪里","寻找塔纳利斯的峡谷"}},{q="需要清理哪些生物？",a="八只扭曲的灌木和八只灌木根塑者。",al={"目标","要杀什么","哪些灌木"}},{q="为什么特兰雷克要求保留一些完好的仙人掌？",a="特兰雷克想要近距离观察山谷里的仙人掌，所以必须保留一部分完好无损。",al={"特兰雷克动机","为什么去峡谷","对仙人掌的兴趣"}}},fp="19,185,18.240.0,26.213.0,43.30.0,29.32.0,34.63.0,60.108.0"}
P.entries["quest:3364"] = {n="热酒快递",s="“滚烫的晨酿配送”是一项在寒脊山谷中进行的匆忙差事，必须在滚烫的饮品被山间的霜雪冻凉之前送达。诺里斯·激流将这项配送任务托付给了一位冒险者，以确保德南·弗卡特能喝到热气腾腾的晨酿。",h="“滚烫的晨酿配送”是一项在寒脊山谷中进行的匆忙差事，必须在滚烫的饮品被山间的霜雪冻凉之前送达。诺里斯·激流将这项配送任务托付给了一位冒险者，以确保德南·弗卡特能喝到热气腾腾的晨酿。",kw={"安威玛尔","寒脊山谷","丹莫罗","德南·弗卡特","晨酿","诺里斯·激流"},ang={["profession:Cooking"]="在恰当的温度下提供饮品是真正的烹饪礼仪，尤其是在丹莫罗严酷的零度以下环境中。",["race:Dwarf"]="每个矮人都明白在冰冷的空气中喝凉掉的饮品是何等悲剧，这使得横穿山谷的奔波成为了一件纯粹的原则问题。"},sec={{t="与严霜竞速",b="丹莫罗刺骨的严寒毁掉了许多热食，晨酿也不例外。在完成了给格瑞林·白须的配送后，诺里斯·激流意识到自己没有足够的时间在晨酿冻成难以下咽的冰渣前，将其送到安威玛尔。为了不让客户失望，他向任何愿意冒雪前行的敏捷旅者寻求帮助。"},{t="一杯热饮的代价",b="德南·弗卡特驻守在安威玛尔温暖的山中大厅里，他对自己的茶点非常讲究。凉掉的晨酿绝对不行。将热气腾腾的饮品完好送达，能让这位疲惫的矮人从职责中获得片刻急需的休息，尽管诺里斯还是希望他那心爱的马克杯能完好无损地归还。"}},faq={{q="德南·弗卡特是谁？",a="德南·弗卡特是一位居住在寒脊山谷安威玛尔地下大厅里的矮人。他依靠诺里斯·激流的本地配送来获取热腾腾的晨酿。",al={"德南·弗卡特","谁是德南","弗卡特"}},{q="为什么配送必须这么快？",a="寒脊山谷冰冻的高山气候导致热饮迅速冷却。德南专门要求滚烫的晨酿，按照矮人的标准，冷掉的麦酒或茶水都被视为毁掉了。",al={"为什么限时","晨酿计时器","为什么要匆忙"}},{q="诺里斯·激流是谁？",a="诺里斯·激流是一位驻守在寒脊山谷雪径上的矮人。他负责当地营地之间的配送工作，包括给格瑞林·白须和安威玛尔的工人们送去饮品。",al={"诺里斯·激流","诺里斯","谁是诺里斯"}},{q="什么是晨酿？",a="晨酿是一种温暖提神的矮人清晨饮品，专为抵御丹莫罗山峰的冰冷严寒并为强壮的山地工人补充体力而酿造。",al={"什么是晨酿","晨酿传说"}},{q="安威玛尔位于哪里？",a="安威玛尔位于诺里斯哨位正东北方，开凿在寒脊山谷的山岩之中，为年轻的登山者和工匠提供躲避暴风雪的住所。",al={"安威玛尔在哪","安威玛尔位置","寻找安威玛尔"}},{q="诺里斯想要回那个杯子吗？",a="是的。德南享用完热腾腾的晨酿后，会交还空容器，以便将其送回寒脊山谷交给诺里斯。",al={"归还马克杯","带回马克杯","诺里斯的杯子"}}},fp="26,157,24.205.0,23.249.0,24.120.0,41.133.0,23.187.0,17.141.0,26.155.0,28.94.0"}
P.entries["quest:3365"] = {n="归还酒杯",s="在丹莫罗的积雪中送完滚烫的晨露酒后，还有最后一项跑腿任务：归还空杯子。德南·弗卡特会让你跑回寒脊山谷，将诺里斯的杯子还给诺里斯·激流。这虽然只是举手之劳，但酒水商对此非常感激。",h="在丹莫罗的积雪中送完滚烫的晨露酒后，还有最后一项跑腿任务：归还空杯子。德南·弗卡特会让你跑回寒脊山谷，将诺里斯的杯子还给诺里斯·激流。这虽然只是举手之劳，但酒水商对此非常感激。",kw={"归还杯子","丹莫罗","德南·弗卡特","卡拉诺斯","晨露酒","诺里斯·激流","啤酒杯"},ang={["profession:Cooking"]="任何合格的厨师或酿酒师都知道，如果不把餐具清点归还到厨房，优质的服务就不算结束。",["race:Dwarf"]="每个矮人都知道，私吞酒馆老板的酒杯很快就会引发斗殴；归还诺里斯的杯子是基本的矮人礼节。"},sec={{t="酒馆礼仪",b="在丹莫罗寒风刺骨的环境中提供滚烫的晨露酒可不是件容易的事。当德南·弗卡特喝完这杯热酒暖好身子后，这个空酒杯不能随便扔在雪地里。矮人的好客之道建立在相互尊重的基础上，如果让好好的餐具弄丢了，那以后可就别想再喝上酒了。"},{t="杯子可不是长在树上的",b="回到寒脊山谷就能完成诺里斯·激流的送货任务。正如诺里斯经常提醒那些健忘的送货员那样，坚固的饮具可不是长在树上的——尤其是在矮人故乡这种冰天雪地的岩崖间。将空杯子完好无损地送回去，能让冒险者在当地社区建立起可靠的名声。"}},faq={{q="这个跑腿任务是谁发布的？",a="在你于丹莫罗将刚酿好的晨露酒交给德南·弗卡特后，他就会立即给你这个任务。",al={"任务发布者","谁发布了归还杯子的任务","德南·弗卡特任务"}},{q="我要把杯子还给谁？",a="你需要把空杯子还给诺里斯·激流，他会在丹莫罗的寒脊山谷四处游荡，兜售他的晨露酒。",al={"我该把杯子带到哪里","谁收回杯子","诺里斯的位置"}},{q="归还杯子有时间限制吗？",a="没有。虽然最初运送烫手的晨露酒有严格的计时器以保持酒温，但归还空杯子可以按照你自己的节奏进行。",al={"这个任务有时间限制吗","杯子计时器","我需要赶紧回去吗"}},{q="为什么诺里斯这么看重一个空杯子？",a="在丹莫罗，高质量的杯子和啤酒杯是贵重的酒具。正如诺里斯所言，杯子不是长在树上的，酒馆可经不起每个过路的送货员都把酒具弄丢。",al={"为什么诺里斯想要回杯子","杯子的重要性"}},{q="哪个任务直接引出这个任务？",a="这个跑腿任务是“烫手的晨露酒”的直接后续，在你让德南喝下你带来的饮料那一刻起就开始了。",al={"前置任务","归还杯子之前是什么任务"}},{q="在哪里可以找到德南·弗卡特？",a="德南·弗卡特是一位布甲和皮甲商人，就在寒脊山谷开凿在山体中的定居点安威玛尔内。",al={"德南的位置","德南在哪里"}}},fp="18,130,28.195.0,24.218.0,23.122.0,27.105.0,40.160.0,46.172.0,40.104.0,36.130.0"}
P.entries["quest:3367"] = {n="苏塔拉之石",s="杜里奥斯·裂石在灼热峡谷受了重伤，头晕目眩，感觉天旋地转，且体内正在出血。他说他必须回到铁炉堡，并恳求你的帮助，送他回去。",h="杜里奥斯·裂石在灼热峡谷受了重伤，头晕目眩，感觉天旋地转，且体内正在出血。他说他必须回到铁炉堡，并恳求你的帮助，送他回去。",kw={"杜里奥斯·裂石","铁炉堡","灼热峡谷","烧焦的信","石坝小径","suntara stones"},sec={{t="求援",b="杜里奥斯呻吟着说他受了重伤。他感到头晕目眩，天旋地转，并且体内正在出血。他唯一的愿望就是回到铁炉堡，并请求你帮助他完成这段旅程。"},{t="通往石坝小径之路",b="道路在石坝小径前戛然而止。杜里奥斯在那里中弹身亡，他随身携带的一封信掉在地上，被烧焦了。"}},faq={{q="杜里奥斯·裂石是谁？",a="杜里奥斯·裂石在灼热峡谷受了重伤，需要帮助才能回到铁炉堡。",al={"杜里奥斯是谁","杜里奥斯·裂石","灼热峡谷受伤的矮人"}},{q="杜里奥斯要去哪里？",a="他想回到铁炉堡。",al={"杜里奥斯的目的地","杜里奥斯要去哪","杜里奥斯护送地点"}},{q="杜里奥斯的情况如何？",a="他受了重伤，头晕目眩，体内正在出血，感觉天旋地转。",al={"杜里奥斯的状况","杜里奥斯受伤了吗","为什么杜里奥斯需要帮助"}}},fp="14,188,15.204.0,20.135.1,26.94.0,29.34.0,28.95.0"}
P.entries["quest:3368"] = {n="苏塔拉之石",s="一封多里奥斯掉落的烧焦的信是写给他兄弟的。信中提到桑塔拉之石是真实存在的，而且落入了黑铁矮人手中，他们的首领拉索里克之黑利用这些石头蕴含的力量奴役了多里奥斯的挖掘队。这封信是寄给铁炉堡探险者大厅的索里奥斯馆长的，而你正是将它送达的人。",h="一封多里奥斯掉落的烧焦的信是写给他兄弟的。信中提到桑塔拉之石是真实存在的，而且落入了黑铁矮人手中，他们的首领拉索里克之黑利用这些石头蕴含的力量奴役了多里奥斯的挖掘队。这封信是寄给铁炉堡探险者大厅的索里奥斯馆长的，而你正是...",kw={"大熔炉","多里奥斯","hall of explorers","铁炉堡","拉索里克之黑","黑曜石","灼热峡谷","烧焦的信","桑塔拉之石","索里奥斯"},sec={{t="死者的信",b="在信中，多里奥斯写道，如果他的兄弟读到这封信，那么他已经不在人世了。桑塔拉之石确实存在，而且被黑铁矮人掌控。他们的首领拉索里克之黑利用这些石头蕴含的力量奴役了多里奥斯的挖掘队。挖掘队被带到了大熔炉，他们的心智受到扭曲，日夜不停地劳作，只为了完成一种被称为“黑曜石”的东西。多里奥斯恳求他的兄弟帮帮他们，这是他最后的愿望，并请求厚待送信之人。"},{t="索里奥斯收到消息",b="当信被送达时，索里奥斯啜泣不已。随后他擦干脸庞，以圣光之名起誓，多里奥斯的遗愿一定会实现。"}},faq={{q="谁写了那封烧焦的信？",a="多里奥斯写给他的兄弟的，作为他死后传达的信息。",al={"谁写的信","烧焦信件的作者","多里奥斯的信"}},{q="索里奥斯住在哪里？",a="索里奥斯馆长就在铁炉堡的探险者大厅里。",al={"索里奥斯在哪里","索里奥斯馆长位置","索里奥斯 探险者大厅"}},{q="多里奥斯的挖掘队发生了什么事？",a="信中说拉索里克之黑和黑铁矮人正在利用这些石头奴役他们。他们被带到了大熔炉。",al={"挖掘队发生了什么","多里奥斯挖掘队","大熔炉奴隶矿工"}},{q="被奴役的团队在做什么？",a="信中说他们的心智受到扭曲，日夜不停地劳作，去完成一种被称为“黑曜石”的东西。",al={"什么是黑曜石","大熔炉挖掘工程","黑铁矮人黑曜石计划"}},{q="谁是拉索里克之黑？",a="信中提到他是黑铁矮人的首领，他们掌握着桑塔拉之石，并利用其力量奴役了多里奥斯的团队。",al={"拉索里克是谁","拉索里克之黑","灼热峡谷黑铁矮人领袖"}},{q="这与之前的“桑塔拉之石”任务有何联系？",a="这紧接在第一个“桑塔拉之石”任务之后，当时多里奥斯被射中，这封信就是从他身上掉落的。这封信需要被送到铁炉堡。",al={"前置任务桑塔拉之石","桑塔拉之石系列任务"}}},fp="14,334,21.458.0,22.134.1,28.72.0,26.67.0,42.124.0,37.104.0,26.127.0,48.133.0"}
P.entries["quest:3369"] = {n="在噩梦中",s="“噩梦之中”是一个部落任务，要求冒险者将一件令人不安的圣物——噩梦碎片，带给雷霆崖长者高地的大德鲁伊哈缪尔·符文图腾。这块碎片最初是作为哀嚎洞穴中发光的碎片被发现的，它揭示了一种深深的不安腐化正在渗入翡翠梦境。",h="“噩梦之中”是一个部落任务，要求冒险者将一件令人不安的圣物——噩梦碎片，带给雷霆崖长者高地的大德鲁伊哈缪尔·符文图腾。这块碎片最初是作为哀嚎洞穴中发光的碎片被发现的，它揭示了一种深深的不安腐化正在渗入翡翠梦境。",kw={"长者高地","翡翠梦境","菲拉·古风","发光的碎片","哈缪尔·符文图腾","噩梦之中","噩梦碎片","雷霆崖","哀嚎洞穴"},ang={["class:Druid"]="对于德鲁伊来说，这块碎片是翡翠梦境原始神圣性受到破坏的令人震惊的证据，证实了在塞纳里奥圈子中蔓延的腐化传言。",["faction:Horde"]="运送这块碎片可以维护卡利姆多中部的精神福祉，证明部落在遏制从贫瘠之地蔓延出来的真菌和梦境腐化方面发挥着关键作用。",["race:Tauren"]="回到大德鲁伊哈缪尔·符文图腾身边，强调了牛头人德鲁伊在塞纳里奥议会中日益突出的地位，因为他们正与暗夜精灵导师并肩对抗古老的宇宙威胁。"},sec={{t="令人不安的发现",b="在检查了从哀嚎洞穴深处取回的奇怪水晶后，菲拉·古风意识到它是由翡翠梦境的纯净精华构成的。然而，居住在其中的幻象却是黑暗而混乱的，它所携带的特征不是宁静的沉睡，而是一场清醒的噩梦。出于对这种惊人预兆的谨慎，她将碎片托付给你，并指示你去寻找雷霆崖最受尊敬的德鲁伊长者，大德鲁伊哈缪尔·符文图腾。"},{t="梦境中的秘密",b="当你在长者高地向哈缪尔·符文图腾展示噩梦碎片时，他那惯常的镇定在窥视碎片内部时动摇了。面对翡翠梦境正在分崩离析成为噩梦的有形证据，这位大德鲁伊谨慎地选择了他的言辞。他坚定地建议保持谨慎，警告说这些微妙的事情远非普通旅行者所能理解，并默默下定决心去调查威胁着这片沉睡领域的隐形苦难。"}},faq={{q="什么是噩梦碎片？",a="噩梦碎片是在哀嚎洞穴中回收的发光碎片，菲拉·古风在检查后将其托付给你。虽然它是用翡翠梦境的纯净精神精华锻造而成的，但它携带了一种邪恶、扭曲的幻象，表明梦境中某些地方出了大问题。",al={"什么是噩梦碎片","发光的噩梦碎片","菲拉发现了什么"}},{q="菲拉·古风是谁？",a="菲拉·古风是一位博学的牛头人德鲁伊，位于贫瘠之地俯瞰哀嚎洞穴的山坡上。她研究从被腐化的绿洲洞穴中出现的异常现象，并在发现危险圣物时派遣部落信使前往寻找哈缪尔·符文图腾。",al={"菲拉·古风","谁给了我这个任务","任务发布者"}},{q="我在哪里可以找到大德鲁伊哈缪尔·符文图腾？",a="大德鲁伊哈缪尔·符文图腾居住在长者高地，这是雷霆崖的高地台地之一。他通常站在德鲁伊圆环中，与他的塞纳里奥议会的同僚们在一起。",al={"哈缪尔在哪里","哈缪尔·符文图腾位置","长者高地哈缪尔"}},{q="为什么哈缪尔想把碎片保密？",a="翡翠梦境是自然和沉睡德鲁伊的神圣避难所。有形证据表明它正在被扭曲成噩梦，这可能会在塞纳里奥议会中引起广泛恐慌，并破坏卡利姆多各地脆弱的精神恢复工作，促使哈缪尔呼吁保持沉默。",al={"为什么要保密","哈缪尔的秘密","哈缪尔为什么隐藏碎片"}},{q="联盟有这个任务的版本吗？",a="是的。当部落的勇士将噩梦碎片交给雷霆崖的大德鲁伊哈缪尔·符文图腾时，调查哀嚎洞穴的联盟玩家会被指引将他们的碎片带过大海前往达纳苏斯，并将其交给塞纳里奥议会的德鲁伊玛斯雷·驭熊者。",al={"联盟版本","噩梦之中的联盟任务","联盟可以做这个任务吗"}},{q="这与哀嚎洞穴有什么关系？",a="该碎片起源于哀嚎洞穴内，德鲁伊纳拉雷克斯在那里进入了深层恍惚状态，试图将地下泉水引入贫瘠之地。纳拉雷克斯的沉睡并没有治愈这片土地，反而扭曲成了一场清醒的噩梦，使洞穴中的动物群发生变异，并渗入像这样的水晶碎片中。",al={"与哀嚎洞穴的联系","与纳拉雷克斯的联系","这与纳拉雷克斯有什么关系"}}},fp="13,240,22.356.0,21.360.1,28.281.0,22.255.0,45.172.0,48.259.0,47.252.0,44.279.0"}
P.entries["quest:337"] = {n="一本破旧的历史书",s="这本书是从暮色森林受污染的土壤和怪物巢穴中回收的，上面盖有暴风城Royal Library的官方印章。这本书题为《暴风城历史》，在第一次战争后的王国重建之前就已遗失。归还它将为首席图书管理员米尔顿·西弗找回一本失落的编年史，并开启一项保护南部人类历史的行动。",h="这本书是从暮色森林受污染的土壤和怪物巢穴中回收的，上面盖有暴风城Royal...",kw={"古老历史书籍","暮色森林","米尔顿·西弗","保护知识","南海镇","stormwind keep","暴风城图书馆","暴风城历史"},ang={["class:Mage"]="奥术学者们明白，古代图书馆中的知识如果遗留在荒野中，极易受到腐朽和忽视的影响。",["faction:Alliance"]="回收战前文献可以修复在第一次战争的破坏中幸存下来的暴风城失落遗产碎片。",["race:Human"]="对于南方的人类来说，从荒野中找回文字记录是重建被旧部落粉碎的文化的重要一步。"},sec={{t="第一次战争的遗物",b="这本沾满泥土的书籍是在游荡于暮色森林的敌对亡灵和野蛮食人魔中发现的，它是暴风城毁灭前那个时代为数不多幸存的文物之一。在它的扉页上盖有王国图书馆的正式印章，它在几十年前——部落洗劫首都之前——被借出，并被认为在南部的陷落中永远遗失了。"},{t="恢复被遗忘的史册",b="当把这本书带回位于Stormwind Keep内Royal Library的米尔顿·西弗那里时，它被认定为注定要进入Rare Books档案室的无价之宝。在闹鬼的荒野中暴露多年，书页已经严重受损，这次发现促使西弗去寻找更多失落的知识，并将目光投向了北方的南海镇，那是距离奥特兰克废墟及其荒废图书馆最近的城镇。"}},faq={{q="在哪里可以找到这本书？",a="这本书由游荡在暮色森林的各种敌对生物掉落，最常见的是出没于墓地和田野的亡灵，或者是占据南部山丘的食人魔。",al={"哪里可以找到古老历史书籍","书籍掉落地点","暮色森林历史书籍"}},{q="我应该把书交给谁？",a="你需要把这本书还给米尔顿·西弗，他是位于Stormwind Keep内Royal Library的首席图书管理员。",al={"任务交还地点","我应该在哪里交任务","米尔顿·西弗位置"}},{q="为什么这本书保存状况如此糟糕？",a="这本书是在第一次战争和暴风城被洗劫之前借出的。它在暮色森林的荒野中存活了几十年，经受了泥土、腐烂以及流浪拾荒者和怪物的摧残。",al={"为什么它上面有泥","为什么破损了"}},{q="归还这本书会引发其他任务吗？",a="是的。米尔顿·西弗会派你前往希尔斯布莱德丘陵的南海镇，去见博学者迪布斯，他可以指引你找到仍然散落在奥特兰克废墟中的书籍。",al={"what comes next","后续任务","书籍任务线"}},{q="为什么米尔顿·西弗如此看重这本特定的书？",a="因为最初的王国在第一次战争中被夷为平地，在城市焚毁后几乎没有原始的历史记录幸存下来。回收战前真正的文献有助于学者们重建王国的过去。",al={"为什么这本书很重要","暴风城历史的重要性"}},{q="部落玩家可以完成这个任务吗？",a="不能。这本书属于暴风城的Royal Library，只能由Stormwind Keep内的联盟图书管理员接收。",al={"部落版本","这是联盟专属吗"}}},fp="19,265,24.316.0,26.343.0,25.134.0,27.92.0,39.188.0,45.159.0,60.171.0,38.114.0"}
P.entries["quest:3370"] = {n="在噩梦中",s="在发现一块奇怪的发光的碎片后，菲拉·古风意识到这件神器中蕴含着被黑暗幻象污染的翡翠梦境纯粹精华。她派遣一名冒险者前往达纳苏斯，将这件令人不安的遗物直接交给塞纳里奥议会的德鲁伊长者们。",h="在发现一块奇怪的发光的碎片后，菲拉·古风意识到这件神器中蕴含着被黑暗幻象污染的翡翠梦境纯粹精华。她派遣一名冒险者前往达纳苏斯，将这件令人不安的遗物直接交给塞纳里奥议会的德鲁伊长者们。",kw={"塞纳里奥议会","塞纳里奥区","达纳苏斯","翡翠梦境","菲拉·古风","发光的碎片","在梦魇中","玛斯雷·驭熊者","噩梦碎片"},ang={["class:Druid"]="对于德鲁伊来说，这个任务揭示了神圣的翡翠梦境并非他们被教导去交流的那片未受触碰的圣所，暗示着深刻的内部危险。",["faction:Alliance"]="联盟冒险者将这件遗物带入达纳苏斯中心，让暗夜精灵领导层得以窥见正在世界表面之下蔓延的腐蚀的早期迹象。",["race:NightElf"]="暗夜精灵崇敬着玛法里奥·怒风所居住的沉睡领域；在梦境精华中发现一个醒着的梦魇，这直接打击了他们精神遗产的核心。"},sec={{t="令人不安的启示",b="从哀嚎洞穴深处回收的那块发光的碎片证明了它远比普通的水晶更危险。在检查之后，菲拉·古风将其鉴定为翡翠梦境最纯粹精华的化身。然而，这块石头并没有映照出自然世界那郁郁葱葱的和谐，反而扭曲着展现出令人不安、充满恐惧的幻象。菲拉被她所见到的景象震惊了，她拒绝亲自深入调查，并坚称必须将这块碎片安全地移交给塞纳里奥议会内部的高层领导。"},{t="塞纳里奥区的低语",b="在达纳苏斯，这件遗物被呈交给了塞纳里奥区的一位资深德鲁伊，玛斯雷·驭熊者。玛斯雷最初带着平静的好奇心迎接了它，但在注视碎片核心的瞬间，他明显变得不安起来。他意识到困扰贫瘠之地的腐蚀与翡翠梦境深处的动荡有着直接的联系，于是迅速制止了进一步的讨论。这位德鲁伊长者警告说，如此恐怖的异常现象并非普通人所能知晓，随即悄悄收管了这块噩梦碎片，以研究那正在逼近的阴影。"}},faq={{q="什么是噩梦碎片？",a="噩梦碎片是翡翠梦境精华的结晶碎片，最初是被发现的一块神秘的发光碎片。它不仅没有映照出自然的和谐，反而散发着黑暗的幻象和腐蚀性的力量，揭示出一种邪恶的存在已经开始入侵梦境。",al={"什么是噩梦碎片","发光的碎片背景故事","翡翠梦境碎片"}},{q="菲拉·古风是谁？",a="菲拉·古风是一位研究自然知识的牛头人德鲁伊，专门负责检查在荒野中发现的奇怪遗物。在意识到这块发光碎片的真实且恐怖的起源后，她指引旅行者前往达纳苏斯寻求更高阶德鲁伊权威的帮助。",al={"菲拉·古风","菲拉是谁"}},{q="玛斯雷·驭熊者是谁？",a="玛斯雷·驭熊者是塞纳里奥议会的一位德鲁伊训练师长者，驻扎在达纳苏斯的塞纳里奥区。他担任经验丰富的导师，并负责调查影响自然和翡翠梦境的严重精神威胁。",al={"玛斯雷·驭熊者","达纳苏斯的驭熊者","玛斯雷是谁"}},{q="为什么玛斯雷对这块碎片如此保密？",a="翡翠梦境被尊为由绿龙军团和沉睡的德鲁伊们所指引的原始、不可侵犯的自然领域。证据表明该领域正遭受梦魇腐蚀的折磨，这代表了一场深重的精神危机，塞纳里奥议会不愿将其公之于众。",al={"为何保密","玛斯雷隐藏了什么","为什么玛斯雷不愿交谈"}},{q="这个任务链从哪里开始？",a="故事线始于“发光的碎片”，这是一件在哀嚎洞穴的尽头从吞噬者穆坦努斯身上掉落的物品。该碎片被带给学者，他们最终将其不祥的起源追溯到了达纳苏斯或雷霆崖。",al={"在梦魇中前置任务","这是从哪里开始的","如何获得在梦魇中"}},{q="部落玩家有相应的任务吗？",a="是的。虽然联盟英雄向达纳苏斯的玛斯雷·驭熊者汇报，但部落勇士会将他们的发现带到雷霆崖长者高地的哈缪尔·符文图腾那里，并发现关于翡翠梦境的同样令人不安的消息。",al={"部落版本","在梦魇中有部落任务吗","在梦魇中部落"}}},fp="13,144,22.386.0,32.435.1,28.232.1,22.215.0,29.200.0,47.270.1,34.197.0,42.231.0"}
P.entries["quest:3372"] = {n="释放他们",s="一位垂死的考古学家在灼热峡谷恳求你解放那些即便躯体早已崩坏，仍被太阳之力的能量驱使着不断劳作的受害者。一切的关键就在太阳之力的祭坛上，而必须被放置在那上面的遗物正由暮光之锤守护着。",h="一位垂死的考古学家在灼热峡谷恳求你解放那些即便躯体早已崩坏，仍被太阳之力的能量驱使着不断劳作的受害者。一切的关键就在太阳之力的祭坛上，而必须被放置在那上面的遗物正由暮光之锤守护着。",kw={"太阳之力的祭坛","垂死的考古学家","神秘的古器","解放他们","灼热峡谷","熔渣之池","暮光之锤"},sec={{t="垂死的请求",b="在倒下之前，考古学家恳求你解放他们。他们的身体已经垮了，但太阳之力的力量却驱使着他们继续劳作。这位考古学家说，关键就在太阳之力的祭坛上。"},{t="太阳之力的祭坛",b="向西北方向前进，前往洞穴上方的山丘。暮光之锤的崇拜者们在那里守护着一件被称为神秘的古器的遗物。从他们手中夺回它，并带到熔渣之池，将其放置在太阳之力的祭坛上。"}},faq={{q="是谁请求帮助完成“解放他们”？",a="灼热峡谷中一位垂死的考古学家，他在提出请求后便倒下了。",al={"任务发布者","谁发布了解放他们","垂死的考古学家"}},{q="神秘的古器位于何处？",a="暮光之锤的崇拜者在灼热峡谷的西北象限，即洞穴上方的山丘中守护着它。",al={"神秘的古器位置","遗物在哪里","暮光之锤的崇拜者"}},{q="古器必须被送往何处？",a="必须将其带到熔渣之池，并放置在太阳之力的祭坛上。",al={"太阳之力的祭坛位置","祭坛在哪里","我应该把古器带到哪里"}},{q="为什么受害者无法安息？",a="那位考古学家说，太阳之力的能量驱使着他们继续劳作，即便他们的躯体早已无法支撑。",al={"为什么要解放他们","他们发生了什么","太阳之力的力量"}}},fp="12,276,12.212.0,20.212.0,36.69.0,41.109.0,37.62.0,35.114.0"}
P.entries["quest:3374"] = {n="伊兰尼库斯精华",s="你接触了伊瑟拉巨龙军团的誓言石，伊萨里奥斯的声音直接在你脑海中响起。承担这项重任意味着帮助伊瑟拉巨龙军团净化伊兰尼库斯堕落的灵魂，而第一个牺牲就是将那颗束缚着伊兰尼库斯残存自由意志的宝石交给伊萨里奥斯。伊萨里奥斯正在悲伤沼泽等待着你。",h="你接触了伊瑟拉巨龙军团的誓言石，伊萨里奥斯的声音直接在你脑海中响起。承担这项重任意味着帮助伊瑟拉巨龙军团净化伊兰尼库斯堕落的灵魂，而第一个牺牲就是将那颗束缚着伊兰尼库斯残存自由意志的宝石交给伊萨里奥斯。伊萨里奥斯正在悲伤...",kw={"枷锁精华","伊兰尼库斯","绿龙军团","伊萨里奥斯","誓言石","悲伤沼泽","伊瑟拉"},sec={{t="石中之音",b="通过誓言石，伊萨里奥斯告诉你，接受这项重任意味着帮助伊瑟拉巨龙军团净化伊兰尼库斯堕落的灵魂。伊萨里奥斯预料到你们二人将做出许多牺牲，而第一个牺牲就是交出那颗束缚着伊兰尼库斯残存自由意志的宝石。誓言石和伊兰尼库斯的枷锁精华必须被带给身处悲伤沼泽的伊萨里奥斯，在那里，你将做出是否帮助巨龙军团的抉择。"},{t="做出抉择",b="伊萨里奥斯在另一个十字路口迎接你，并询问你做出了什么抉择。一旦抉择做出，伊萨里奥斯会说你到目前为止的选择都是正确的，而你接下来的行动将决定这一切是否会继续下去。"}},faq={{q="伊萨里奥斯是谁？",a="伊萨里奥斯通过伊瑟拉巨龙军团的誓言石与你的心智交流，他正在悲伤沼泽等待，寻求净化伊兰尼库斯堕落的灵魂。",al={"伊萨里奥斯是谁","伊萨里奥斯的职责","谁发出了讯息"}},{q="什么是伊兰尼库斯的枷锁精华？",a="它是束缚着伊兰尼库斯残存自由意志的宝石。伊萨里奥斯要求你将其作为第一个牺牲交出来。",al={"伊兰尼库斯的枷锁精华","什么是束缚宝石","伊兰尼库斯的精华"}},{q="此任务之前发生了什么？",a="它是伊兰尼库斯的精华任务的第一步，任务名称相同。",al={"前置任务","上一步"}},{q="你要把誓言石和精华带到哪里？",a="带到悲伤沼泽找伊萨里奥斯，在那里你将决定是否帮助巨龙军团。",al={"去哪交誓言石","伊萨里奥斯在哪里","任务上交地点"}}},fp="23,340,25.453.0,13.226.1,16.163.0,40.128.0,28.74.0,48.87.0"}
P.entries["quest:3376"] = {n="刺鬃酋长",s="“击碎利牙！”是卫兵维萨罗·风羽在红云台地发布的一项决定性的成人礼。为了保障牛头人家园免受持续不断的袭击，年轻的勇士们会被派往东部的刺刃峡谷，击杀利牙酋长棘鬃。消灭棘背野猪人的酋长，将给那些蚕食莫高雷的野猪人以沉重的打击。",h="“击碎利牙！”是卫兵维萨罗·风羽在红云台地发布的一项决定性的成人礼。为了保障牛头人家园免受持续不断的袭击，年轻的勇士们会被派往东部的刺刃峡谷，击杀利牙酋长棘鬃。消灭棘背野猪人的酋长，将给那些蚕食莫高雷的野猪人以沉重的打击...",kw={"刺刃","棘背","莫高雷","纳拉其","野猪人","红云台地","利牙","棘鬃","风羽"},ang={["class:Hunter"]="对于猎人来说，这个任务是最初的终极考验：追踪一个拥有自己的狡猾、武器和反击意图的猎物。",["faction:Horde"]="通过处决利牙酋长，部落的盟友们展示了他们致力于稳定莫高雷并为新结识的牛头人兄弟们保卫和平领土的决心。",["race:Tauren"]="击杀利牙酋长棘鬃是年轻牛头人在离开纳拉其营地前要进行的最终试炼之一，以此证明他们拥有保卫部族免受敌对邻居侵扰的决心。"},sec={{t="血染的家园",b="红云台地那青草茵茵的高地长久以来一直是一处宁静的避风港，年轻的牛头人在这里学习狩猎的传统，并感悟大地母亲的恩泽。然而，这份宁静正不断受到挑战。在其东面坐落着刺刃峡谷，那是一条布满荆棘的深谷，被充满敌意的棘背野猪人部族所占据。野猪人视牛头人为窃取神圣土地的入侵者，不断向那些试图在莫高雷建立安稳生活的牛头人部族发动无休止的袭击。"},{t="棘鬃的威胁",b="对台地的持续攻击并非毫无目的的疯狂行径，而是在利牙酋长棘鬃那残暴领导下的有组织行动。棘鬃栖身于峡谷深处一个加固过的临时村落里，指挥着他的战士和地卜师对抗舒哈鲁。卫兵维萨罗·风羽意识到，只要这名酋长还活着，棘背野猪人的袭击就不会停止，因此她命令一位有志向的英雄闯入峡谷，击杀棘鬃，并带回他被斩下的头颅作为证明。"},{t="狩猎的课程",b="对于年轻的牛头人及其盟友而言，狩猎利牙不仅仅是一次简单的处决——更是一次通往严酷生存现实的启蒙。正如卫兵维萨罗·风羽所教导的那样，狩猎野兽能让人学会耐心，但猎杀一个同样狡猾且会反击的敌人则是在考验勇气、敏锐度和战斗纪律。击倒利牙不仅为死去的族人伸张了正义，也标志着猎人已做好准备，可以前往莫高雷更广阔的平原去闯荡。"}},faq={{q="谁是利牙酋长棘鬃？",a="利牙酋长棘鬃是居住在刺刃峡谷的棘背野猪人的冷酷领袖。在他的指挥下，该部族不断策划对红云台地上牛头人定居点的袭击与骚扰。",al={"谁是利牙","利牙酋长棘鬃背景故事","野猪人酋长是谁"}},{q="在哪里可以找到利牙酋长棘鬃？",a="利牙居住在刺刃峡谷深处，该峡谷位于红云台地的东侧边缘。他从那座坐落在荆棘密布的峡谷内的临时村落中统治着他的部族。",al={"利牙在哪里","利牙位置","如何找到利牙"}},{q="谁发布了“击碎利牙！”这个任务？",a="这个任务由卫兵维萨罗·风羽发布，她是一位经验丰富的牛头人战士，负责守卫红云台地上的纳拉其营地。她要求充满希望的初来者通过消除棘背野猪人的威胁来证明自己的实力。",al={"击碎利牙任务发布者","谁发布击碎利牙任务","卫兵维萨罗·风羽位置"}},{q="为什么棘背野猪人憎恨牛头人？",a="野猪人崇拜他们的半神阿迦玛甘，并誓死捍卫他们宣称拥有的土地。他们视牛头人在莫高雷建立定居点的行为为侵占祖先狩猎场的入侵者。",al={"为什么野猪人要攻击","牛头人与野猪人的冲突","为什么野猪人充满敌意"}},{q="卫兵维萨罗·风羽要求什么样的证明？",a="卫兵维萨罗·风羽要求带回利牙酋长棘鬃的头颅。带回这颗头颅足以证明该领袖已死，并以此给剩下的棘背野猪人以严厉的警告。",al={"我应该带什么给风羽","利牙的证明","利牙任务目标"}},{q="这场狩猎对年轻的牛头人有什么文化意义？",a="在牛头人文化中，真正的成熟来自于理解猎手与猎物之间的平衡。风羽强调，追踪像利牙这样会思考、狡猾的对手，能让年轻的战士领悟到凡人交战的严肃性以及保卫部族的责任。",al={"为什么在背景故事中要杀死利牙","牛头人利牙成人礼","狩猎的意义"}}},fp="16,221,19.311.0,25.372.0,23.302.0,35.169.0,47.159.0,37.194.0,48.175.0,41.132.0,64.223.0"}
P.entries["quest:3377"] = {n="艾露恩祷言",s="萨麦尔·月棘是被困在灼热峡谷一座笼子里的灵魂，他请求你的帮助。多年来，他从未见过访客，因此希望你能先听听他的故事。",h="萨麦尔·月棘是被困在灼热峡谷一座笼子里的灵魂，他请求你的帮助。多年来，他从未见过访客，因此希望你能先听听他的故事。",kw={"黑海岸","艾露恩","月棘","祈祷","忏悔","灼热峡谷","石板","暮光之锤","萨麦尔"},sec={{t="笼中的灵魂",b="萨麦尔·月棘用对艾露恩的赞美向你致意，并说距离上次有人拜访他已经过去许多年了。他询问你是否愿意帮助他，并请求你先听听他的故事。"},{t="萨麦尔的故事",b="萨麦尔曾经是来自黑海岸的一名年轻暗夜精灵，当时他误入了暮光之锤，他们假意与他结交，让他背离了艾露恩。艾露恩的一道幻象将他从追随上古之神的迷梦中唤醒，为了忏悔，他将自己的悲伤铭刻在了一块纯金的石板上，以此作为对艾露恩的祈祷。暮光之锤发现了这块石板，给他打上了亵渎者的烙印并将他处决，他的祈祷也未能完成。如今，他作为一个灵魂被束缚在这个世界上，并被关在笼子里，作为对所有胆敢背叛暮光之锤信仰之人的警告。萨麦尔已经接受了自己的命运，但他表示必须找到那段祈祷文。"}},faq={{q="谁是萨麦尔·月棘？",a="萨麦尔·月棘是困在灼热峡谷一座笼子里的灵魂。他请求你听听他的故事。",al={"谁是萨麦尔","萨麦尔·月棘背景故事","笼中的幽灵是谁"}},{q="萨麦尔向你提出了什么请求？",a="他询问你是否愿意协助他，并希望你先听听他的故事。",al={"萨麦尔想要什么","萨麦尔的请求"}},{q="听完萨麦尔的故事后会发生什么？",a="随后是“艾露恩的祈祷”的第二部分，同样与萨麦尔有关。",al={"艾露恩的祈祷后续步骤","艾露恩的祈祷任务线"}}},fp="15,164,18.190.0,13.599.1,25.92.0,28.65.0,39.60.0"}
P.entries["quest:3378"] = {n="艾露恩祷言",s="萨麦尔·月棘请求你帮他找回他写在金板上的艾露恩祷言。那些崇拜偶像的恶棍身上一定携带着它，萨麦尔希望你把它带给达纳苏斯的阿斯塔利·逐星。",h="萨麦尔·月棘请求你帮他找回他写在金板上的艾露恩祷言。那些崇拜偶像的恶棍身上一定携带着它，萨麦尔希望你把它带给达纳苏斯的阿斯塔利·逐星。",kw={"阿斯塔利·逐星","达纳苏斯","金板","艾露恩祷言","灼热峡谷","temple of the moon","萨麦尔·月棘"},sec={{t="失落的祷言",b="萨麦尔的信仰虽然重燃，但他表示，考虑到他过去对这个世界及其居民所犯下的无数恶行，这已无足轻重。他并不奢求救赎。他唯一的要求就是让这段祷言被聆听，因此他派你去从偶像崇拜者手中夺回那块金板，并将其送往达纳苏斯的阿斯塔利·逐星手中。"},{t="在Temple of the Moon",b="在Temple of the Moon，阿斯塔利·逐星告诉你，今晚艾露恩对你报以微笑，因为你亲手将一个迷途的灵魂带回了她的身边。她对你的善行表示感谢。"}},faq={{q="萨麦尔·月棘是谁？",a="萨麦尔·月棘是请求你寻找他写给艾露恩的祷言的人。在对世界犯下无数恶行之后，他的信仰重燃了。",al={"萨麦尔·月棘背景故事","谁发布了艾露恩祷言任务","萨麦尔"}},{q="祷言是刻在什么上面的？",a="萨麦尔的祷言被刻在一块金板上，他认为某个崇拜偶像的恶棍携带着它。",al={"艾露恩祷言物品","金板","什么是祷言"}},{q="祷言应该交给谁？",a="交给达纳苏斯的阿斯塔利·逐星，她在Temple of the Moon。",al={"谁接收艾露恩祷言","阿斯塔利·逐星","我该把祷言带到哪里"}},{q="萨麦尔是否期望得到对他过去的宽恕？",a="不。他说他绝不奢求救赎，但他必须让这段祷言被聆听。",al={"萨麦尔想要宽恕吗","萨麦尔救赎"}}},fp="15,201,15.349.0,25.186.1,25.161.0,32.110.0,39.75.0,44.82.0"}
P.entries["quest:338"] = {n="荆棘谷的青山",s="巴尼尔·石罐原本受托校对海米特·奈辛瓦里小说手稿，但一阵狂风将散乱的书页吹散到了丛林中。为了让他免受主人的责骂，你需要搜寻荒野，将缺失的页面集齐并整理成四个章节，然后将完成的作品交还给他。",h="巴尼尔·石罐原本受托校对海米特·奈辛瓦里小说手稿，但一阵狂风将散乱的书页吹散到了丛林中。为了让他免受主人的责骂，你需要搜寻荒野，将缺失的页面集齐并整理成四个章节，然后将完成的作品交还给他。",kw={"巴尼尔·石罐","章节","荆棘谷的青山","海米特·奈辛瓦里","手稿","页面","荆棘谷"},sec={{t="散落的手稿",b="在完成“欢迎来到丛林”任务并抵达探险队营地后，巴尼尔·石罐正面临一场灾难。当他正在审阅海米特·奈辛瓦里的小说《荆棘谷的青山》草稿时，一阵突如其来的大风将散乱的书页吹向了荒野。虽然他找回了大部分，但仍有许多书页遗落在灌木丛中。为了不让他的主人发现这次事故，他需要你找回所有丢失的页面，并将它们整理成第一章、第二章、第三章和第四章。"},{t="保存猎人的故事",b="带回四份完整的章节可以让巴尼尔免于与奈辛瓦里发生不愉快的对峙。随着章节被安全收齐，他希望这部修复好的作品能很快出现在世界各地的图书馆中。"}},faq={{q="谁撰写了《荆棘谷的青山》？",a="这部小说是由探险队队长海米特·奈辛瓦里撰写的，他将草稿委托给巴尼尔·石罐进行校对。",al={"荆棘谷的青山作者","谁写了这本书","奈辛瓦里的书"}},{q="页面是如何丢失的？",a="当巴尼尔正在审阅手稿时，一阵强风穿过狩猎营地，将散乱的书页吹散到了整个丛林中。",al={"为什么页面会散落","页面发生了什么","页面是怎么被吹走的"}},{q="完成手稿需要什么？",a="你必须收集散落的页面并将它们整理成四个不同的部分：第一章、第二章、第三章和第四章，然后将整套页面交给巴尼尔。",al={"需要哪些章节","如何完成荆棘谷的青山","手稿要求"}},{q="这个任务来自哪里？",a="在完成“欢迎来到丛林”任务后，巴尼尔会在荆棘谷的探险队营地提供此任务。",al={"荆棘谷的青山前置任务","荆棘谷的青山之前的任务","如何接到这个任务"}},{q="巴尼尔打算如何处理修复后的小说？",a="除了让自己免受奈辛瓦里的愤怒之外，巴尼尔希望完成的手稿最终能分发到世界各地的图书馆中。",al={"为什么要收集页面","书会怎么样","书会去哪里"}}},fp="32,309,22.536.0,28.231.0,43.128.0,24.152.0,40.166.0,36.109.0,54.148.0"}
P.entries["quest:339"] = {n="荆棘谷的青山 - 第一章",s="巴尼尔·石罐正在尝试修复赫米特·奈辛瓦里散落的狩猎手稿《荆棘谷的青山》的开头部分。他需要从丛林各处收集四页丢失的书页，才能将序章部分重新装订在一起。",h="巴尼尔·石罐正在尝试修复赫米特·奈辛瓦里散落的狩猎手稿《荆棘谷的青山》的开头部分。他需要从丛林各处收集四页丢失的书页，才能将序章部分重新装订在一起。",kw={"巴尼尔·石罐","第一章","荆棘谷的青山","赫米特·奈辛瓦里","荆棘谷"},sec={{t="遗失的序章",b="在与你谈论《荆棘谷的青山》之后，巴尼尔·石罐将目光投向了修复这本书的开篇。据这位矮人所说，第一部分为整个故事奠定了基础，并介绍了奈辛瓦里的狩猎队，其中也包括巴尼尔本人。不幸的是，手稿的书页仍然散落在野外，导致合集中缺少了第一页、第四页、第六页和第八页。"},{t="装订第一章",b="一旦你带回了那四页丢失的书页，巴尼尔就能将这位狩猎大师文本的第一部分拼凑成完整的一章。"}},faq={{q="是谁在请求这些书页？",a="巴尼尔·石罐，赫米特·奈辛瓦里的同伴，驻扎在荆棘谷的营地里，他需要这些书页来整理散落的狩猎回忆录。",al={"谁给予第一章任务","巴尼尔·石罐","任务发布者"}},{q="这部分手稿需要哪些书页？",a="巴尼尔需要第一页、第四页、第六页和第八页，才能成功重新整理出该作品的开头部分。",al={"需要什么书页","遗失的书页","哪些书页"}},{q="这部分手稿描述了什么？",a="根据巴尼尔·石罐的说法，它为故事设定了背景，并介绍了奈辛瓦里的狩猎同伴，包括巴尼尔本人。",al={"第一章的内容是什么","手稿内容"}},{q="是什么导致了这一步？",a="这是为了找回《荆棘谷的青山》而进行的更广泛工作的一部分，巴尼尔在其中首次告知了你丢失书页的消息。",al={"前置条件","上一个任务"}}},fp="9,251,24.431.0,25.163.0,30.154.0,55.104.0,49.140.0,25.129.0"}
P.entries["quest:34"] = {n="不速之客",s="“不受欢迎的客人”是湖畔镇的一个本地任务，居民玛蒂·詹罗斯寻求惩罚一头极具破坏力的野猪——贝利格拉布。这头野兽横冲直撞，毁坏了她的花园，踩踏了当季的水仙花，促使她悬赏这头野兽的獠牙。",h="“不受欢迎的客人”是湖畔镇的一个本地任务，居民玛蒂·詹罗斯寻求惩罚一头极具破坏力的野猪——贝利格拉布。这头野兽横冲直撞，毁坏了她的花园，踩踏了当季的水仙花，促使她悬赏这头野兽的獠牙。",kw={"不受欢迎的客人","贝利格拉布","野猪","水仙花","湖畔镇","治安官马瑞斯","玛蒂·詹罗斯","赤脊山"},ang={["class:Hunter"]="贝利格拉布是一头臭名昭著的精英野兽，在湖畔镇西南方游荡，对于任何路过赤脊山的猎人来说，它都是一个显著的追踪和狩猎挑战。",["faction:Alliance"]="帮助玛蒂·詹罗斯保护她的家园和花园，为苦苦挣扎的湖畔镇带来了一丝秩序和慰藉，这里的镇民们本就已经因赤脊山更大的威胁而倍感压力。",["profession:Herbalism"]="玛蒂·詹罗斯最自豪的就是她培育的那片花圃，而贝利格拉布的肆意破坏毁掉了她当季的水仙花，打击了赤脊山脆弱的家庭园艺。"},sec={{t="花园里的麻烦",b="在湖畔镇，当赤脊山上空阴云密布时，玛蒂·詹罗斯正在照料她的宅院。她平静的生活被一个持续存在的本地威胁打破了：一头臭名昭著的暴躁野猪多次侵入她的花园。由于她珍视的一片水仙花被践踏得在这一季无法恢复，这位苦恼的居民转向有能力的旅行者，希望他们能终结这头横行霸道的野兽。"},{t="贝利格拉布的威胁",b="肇事的野兽在当地被称为贝利格拉布，这个贴切的名字是由湖畔镇的城镇卫兵队长，治安官马瑞斯取的。贝利格拉布大部分时间都在镇子西南方的田野灌木丛中拱地觅食。然而，它那贪婪的胃口和胆量经常驱使它极其危险地接近居民住宅，最终导致玛蒂的花坛被彻底毁坏，必须将其彻底清除。"}},faq={{q="谁发布了“不受欢迎的客人”任务？",a="玛蒂·詹罗斯在赤脊山的湖畔镇发布该任务。由于花园不断遭到破坏，她十分苦恼，于是请求路过的冒险者去猎杀这头罪魁祸首。",al={"谁发布不受欢迎的客人","哪里接不受欢迎的客人","玛蒂·詹罗斯任务"}},{q="贝利格拉布是谁，或者是什么？",a="贝利格拉布是一头具有攻击性和破坏力的野猪，因经常恐吓湖畔镇周边的土地而臭名昭著。该镇的当地卫兵队长治安官马瑞斯最初给了这头野兽这个绰号。",al={"贝利格拉布是谁","贝利格拉布是什么","为什么叫贝利格拉布"}},{q="在哪里可以找到贝利格拉布？",a="贝利格拉布大部分时间都在湖畔镇西南方的开阔田野中觅食，尽管它经常流浪到离镇子边界更近的地方，甚至闯入居民的花园。",al={"贝利格拉布位置","贝利格拉布在哪里","寻找贝利格拉布","贝利格拉布在哪里刷新"}},{q="为什么玛蒂·詹罗斯想杀死贝利格拉布？",a="贝利格拉布反复践踏并洗劫了玛蒂·詹罗斯精心照料的花园，彻底毁坏了她的水仙花，导致下一季之前无法重新种植。由于对这种反复发生的破坏感到厌倦，她希望除掉它。",al={"为什么玛蒂想杀掉贝利格拉布","为什么要杀贝利格拉布","贝利格拉布干了什么"}},{q="完成任务需要什么证明？",a="玛蒂·詹罗斯需要贝利格拉布的獠牙作为证明，表明这头威胁性的野兽终于被解决掉了，之后她才会奖励你。",al={"贝利格拉布证明","不受欢迎的客人交任务","带什么给玛蒂·詹罗斯"}},{q="治安官马瑞斯是谁，他和这头野兽有什么联系？",a="治安官马瑞斯是驻扎在湖畔镇的当地治安官。当玛蒂·詹罗斯为她被毁的水仙花寻求个人报复时，马瑞斯则是给这头惹麻烦的野猪取名“贝利格拉布”的人。",al={"谁是治安官马瑞斯","治安官马瑞斯 贝利格拉布"}}},fp="18,262,21.442.0,23.435.0,39.213.0,25.194.0,29.164.0,47.225.0,43.135.0,62.189.0"}
P.entries["quest:340"] = {n="荆棘谷的青山 - 第二章",s="巴尼尔·石罐需要协助来收集海米特·奈辛瓦里那本散落的狩猎手稿的第二部分缺失的书页。他自己已经收集了大部分的羊皮纸，现在正指望荆棘谷的旅人们帮他找回剩余关于豹子和老虎狩猎记录的散页。",h="巴尼尔·石罐需要协助来收集海米特·奈辛瓦里那本散落的狩猎手稿的第二部分缺失的书页。他自己已经收集了大部分的羊皮纸，现在正指望荆棘谷的旅人们帮他找回剩余关于豹子和老虎狩猎记录的散页。",kw={"巴尼尔·石罐","第二章","荆棘谷的青山","奈辛瓦里","书页","豹","荆棘谷","虎"},sec={{t="丛林猫狩猎",b="海米特·奈辛瓦里的手稿散落在荆棘谷各地后，巴尼尔·石罐设法独自找回了许多书页。第二章完全集中于在荒野中追踪豹子和老虎的惊险故事。有四页——第10页、第11页、第14页和第16页——仍然散落在风中或被丛林的居民拿走，导致这部分远征编年史未能完成。"}},faq={{q="是谁在索要这些手稿书页？",a="巴尼尔·石罐，他正在荆棘谷协助奈辛瓦里远征队，请求帮助收集缺失的书页。",al={"谁发布第二章任务","第二章任务发布者","巴尼尔·石罐"}},{q="第二章需要哪些书页？",a="巴尼尔需要第10、11、14和16页来完成第二章的整理。",al={"需要什么书页","第二章书页","第二章书页列表"}},{q="第二章记录了什么故事？",a="第二章记录了追踪并猎杀那些潜伏在荆棘谷的豹子和老虎的故事。",al={"第二章内容","第二章背景知识","荆棘谷的青山第二章内容"}},{q="此请求之前发生了什么？",a="此请求是在巴尼尔最初就那本被称为“荆棘谷的青山”的遗失手稿发出求助后提出的。",al={"前置任务","第二章前置条件","荆棘谷的青山系列任务"}}},fp="10,301,24.424.0,41.126.0,46.78.0,48.113.0,31.124.0"}
P.entries["quest:341"] = {n="荆棘谷的青山 - 第三章",s="巴尼尔·石罐正在荆棘谷尝试重构赫米特·奈辛瓦里的狩猎手稿的第三章。这一章节讲述了埃尔加丁爵士和鲁阿克夫人使用矮人火枪完成的第一次击杀，但是其中有四页书稿被吹散到了丛林各处。",h="巴尼尔·石罐正在荆棘谷尝试重构赫米特·奈辛瓦里的狩猎手稿的第三章。这一章节讲述了埃尔加丁爵士和鲁阿克夫人使用矮人火枪完成的第一次击杀，但是其中有四页书稿被吹散到了丛林各处。",kw={"巴尼尔·石罐","第三章","埃尔加丁","荆棘谷的青山","赫米特·奈辛瓦里","第18页","第20页","第21页","第24页","鲁阿克","荆棘谷"},sec={{t="狩猎记录",b="巴尼尔·石罐认为《荆棘谷的青山》的这一部分是他个人最喜欢的。文中记录了埃尔加丁爵士和鲁阿克夫人的早期事迹，详细描写了他们使用矮人火枪进行的第一次狩猎。这一章的结尾留下了巨大的悬念。"},{t="缺失的书页",b="为了重新拼凑出完整的故事，巴尼尔需要第18、20、21和24页。这些缺失的残页被散落在荒野中，和手稿的其他部分一样被吹到了荆棘谷的各个角落。"}},faq={{q="谁在寻找第三章？",a="巴尼尔·石罐，他在荆棘谷北部的探险队营地校对赫米特·奈辛瓦里的手稿，他正在搜集其缺失的书页。",al={"谁给予第三章任务","第三章任务发放者","巴尼尔·石罐第三章"}},{q="书中的第三章发生了什么？",a="这一章讲述了埃尔加丁爵士和鲁阿克夫人使用矮人火枪进行的第一次狩猎，结局留下了一个尚未解决的悬念。",al={"第三章讲了什么","第三章故事","埃尔加丁和鲁阿克"}},{q="完成第三章需要哪些书页？",a="巴尼尔需要第18、20、21和24页才能将第三章拼凑完整。",al={"第三章需要哪些页码","第三章所需书页","第三章书页"}},{q="这个任务的前置条件是什么？",a="这项工作是在名为《荆棘谷的青山》的最初任务之后进行的，在该任务中，巴尼尔首次解释了赫米特·奈辛瓦里手稿丢失的情况。",al={"第三章前置条件","第三章任务前置"}}},fp="11,272,15.263.0,14.205.0,31.154.0,40.138.0,45.77.0,28.157.0"}
P.entries["quest:342"] = {n="荆棘谷的青山 - 第四章",s="巴尼尔·石罐正试图重现赫米特·奈辛瓦里那部著名手稿的精彩结局。找回最后三页书页，就能复原这篇狂野狩猎故事的高潮篇章。",h="巴尼尔·石罐正试图重现赫米特·奈辛瓦里那部著名手稿的精彩结局。找回最后三页书页，就能复原这篇狂野狩猎故事的高潮篇章。",kw={"巴尼尔·石罐","第四章","荆棘谷的青山","赫米特·奈辛瓦里","第二十五页","第二十六页","第二十七页","荆棘谷"},sec={{t="盛大的结局",b="巴尼尔·石罐认为这一部分是整部狩猎文集的重头戏。为了完成第四章的编纂，他需要有人去寻找并带回第二十五、第二十六和第二十七页。一旦从丛林各处收集齐这三页遗失的书页，这部手稿激动人心的结尾终于可以重见天日了。"}},faq={{q="谁想修复第四章？",a="巴尼尔·石罐请求帮助收集散落的书页，以便他能拼凑出赫米特·奈辛瓦里的狩猎之书的结尾。",al={"谁发布第四章任务","第四章任务发布者","谁需要第四章"}},{q="完成第四章需要哪些书页？",a="你需要《荆棘谷的青山》的第二十五、第二十六和第二十七页才能完成第四章。",al={"第四章书页","第四章需要哪些书页","我需要什么书页"}},{q="在这个请求之前发生了什么？",a="这个请求是在巴尼尔·石罐最初要求收集散落的《荆棘谷的青山》书页之后提出的。",al={"第四章前置条件","第四章前续任务"}}},fp="10,200,16.337.0,30.133.0,46.124.0,31.119.0"}
P.entries["quest:343"] = {n="关于坚韧的演讲",s="“谈谈坚韧”是暴风城内的一项联盟差事，由Cathedral Square的克里斯托弗修士发起。克里斯托弗正在准备一篇题为“精神之坚韧”的布道文，他招募了一位冒险者前往Stormwind Keep内的Royal Library，向首席图书管理员米尔顿·西弗索取一本特定的技术书籍。",h="“谈谈坚韧”是暴风城内的一项联盟差事，由Cathedral Square的克里斯托弗修士发起。克里斯托弗正在准备一篇题为“精神之坚韧”的布道文，他招募了一位冒险者前往Stormwind Keep内的Royal...",kw={"克里斯托弗修士","cathedral of light","冶金学","米尔顿·西弗","royal library","谈谈坚韧","stormwind keep","钢铁的应力"},ang={["class:Priest"]="克里斯托弗修士的布道以精神坚韧为主题，深入探讨了暴风城的教士如何通过将世俗的工艺课程与对圣光的虔诚相结合来撰写布道文。",["faction:Alliance"]="这项差事将Cathedral Square的教士与Stormwind Keep的Royal Library直接联系起来，展示了在这座首都城市中维护的市政和学术基础架构。",["profession:Blacksmithing"]="这篇布道文依托于《钢铁的应力》，反映了即使是学术神学家也会从锻造的严酷现实中寻找解释压力下坚韧不拔的依据。"},sec={{t="金属中的隐喻",b="克里斯托弗修士是暴风城Cathedral of Light驻守的牧师之一，他希望能发表一篇关于“精神之坚韧”的布道。克里斯托弗并不打算仅仅引用教会的经文，而是希望通过金属加工工艺来阐释信仰的磨砺与韧性。具体来说，他需要一本名为《钢铁的应力》的论著，以便在布道时引用，他希望这本关于承受压力之道的书籍能引起会众的共鸣。"},{t="皇家书库",b="Stormwind Keep内设有Royal Library，这是暴风城王国的知识、历史和市政文献的核心宝库。由于馆藏涵盖了无数书架和数百年的著作，克里斯托弗指引传令官去找首席图书管理员米尔顿·西弗。西弗以熟记馆藏而自豪，这使他成为在城堡内庞大的金库中寻找晦涩工艺手稿的唯一实际向导。"}},faq={{q="克里斯托弗修士是谁？",a="克里斯托弗修士是一位在暴风城Cathedral Square圣光教会服务的牧师。他经常寻求访客的帮助，为他的教义和布道获取材料及参考资料。",al={"克里斯托弗","谁发布谈谈坚韧","克里斯托弗修士"}},{q="克里斯托弗修士在寻找什么书？",a="他正在寻找一本名为《钢铁的应力》的技术书籍，这是一部关于冶金学的教学著作，他打算将其引用为精神耐力的隐喻。",al={"哪本书","钢铁的应力","克里斯托弗 书籍"}},{q="米尔顿·西弗是谁？",a="米尔顿·西弗是Stormwind Keep内Royal Library的首席图书管理员。他管理着王国浩如烟海的书籍、卷轴和市政记录，对馆藏了如指掌。",al={"米尔顿·西弗","暴风城 图书管理员","首席图书管理员"}},{q="Royal Library在哪里？",a="Royal Library位于Stormwind Keep的东北翼，可以直接通过皇家宫殿的正厅进入。",al={"暴风城 图书馆位置","皇家书库在哪里","暴风要塞图书馆"}},{q="为什么牧师需要一本冶金学书籍？",a="克里斯托弗修士正在撰写一篇题为“精神之坚韧”的布道文。他打算将钢铁在锻造过程中所承受的物理压力，作为人类精神在磨难中如何得到强化的寓言。",al={"为什么是冶金学","为什么是钢铁之书","坚韧 布道"}},{q="米尔顿·西弗立刻就有这本书吗？",a="米尔顿·西弗确认图书馆有关于冶金学的著作，但在有人询问时，他必须核对确切书名并协调搜索工作，从而启动寻找克里斯托弗所需书籍的流程。",al={"西弗有这本书吗","谈谈坚韧 任务交还"}}},fp="21,102,19.253.0,16.228.0,24.189.0,42.139.0,20.166.0,35.113.0,41.170.0,49.142.0"}
P.entries["quest:344"] = {n="帕克斯顿修士",s="帕克斯顿修士是暴风城皇家档案馆派遣冒险者前往北郡修道院执行的一项任务。图书管理员米尔顿·西弗让寻找者去那里追回一本借出的矮人采矿专著，该书一直没有归还到城市的书架上。",h="帕克斯顿修士是暴风城皇家档案馆派遣冒险者前往北郡修道院执行的一项任务。图书管理员米尔顿·西弗让寻找者去那里追回一本借出的矮人采矿专著，该书一直没有归还到城市的书架上。",kw={"帕克斯顿修士","马格鲁夫·布拉贡","米尔顿·西弗","北郡修道院","暴风城图书馆","铁之压力","抄录"},ang={["class:Priest"]="拜访帕克斯顿修士可以一窥北郡教士的学术职责，他们通过辛苦的手工抄写书籍来为圣殿保存知识。",["faction:Alliance"]="这项任务突显了连接暴风城和铁炉堡的文化交流，人类的图书馆积极保存并研究矮人的基础文本。",["profession:Mining"]="你搜寻的目标，马格鲁夫·布拉贡的《铁之压力》，代表了数十年来矮人从卡兹莫丹山脉中直接挖掘出的来之不易的采矿知识。",["race:Dwarf"]="这本被追寻的著作是矮人工艺的结晶，由同行矿工马格鲁夫·布拉贡撰写，其受尊崇程度足以让暴风城的抄写员们垂涎副本。"},sec={{t="借出的书籍",b="当研究人员在暴风城寻找稀有的技术知识时，首席图书管理员米尔顿·西弗经常发现他的藏书散落各处。一本由矮人探矿者马格鲁夫·布拉贡所著的著名冶金技术专著《铁之压力》从首都的书架上失踪了。它并没有在首都丢失，而是几个月前借给了北郡修道院的牧师们进行抄录。"},{t="北郡的抄写员",b="抄录和保存文献的任务落在了帕克斯顿修士身上，他是修道院图书馆的管理员。虽然北郡教士圣殿重视知识，但手工抄写冗长的技术手稿是一项艰苦而缓慢的工作。帕克斯顿因持逾期书籍被当场抓获，他承认自己还没抄完布拉贡的作品，因此耽误了原稿的归还。"}},faq={{q="米尔顿·西弗为什么要派你去北郡修道院？",a="米尔顿·西弗在几个月前将图书馆馆藏的《铁之压力》借给了帕克斯顿修士，以便修道院能制作一份副本。由于一直没有消息，也没有归还手稿，西弗便派你去查看帕克斯顿的进度。",al={"为什么是帕克斯顿修士","书在哪里","米尔顿·西弗的任务"}},{q="帕克斯顿修士是谁？",a="帕克斯顿修士是一位教士，也是北郡修道院图书馆的管理员。他每天都在编目和手工抄写珍贵的书籍，以扩充修道院的本地藏书。",al={"帕克斯顿是谁","帕克斯顿修士的背景故事","北郡的帕克斯顿"}},{q="什么是《铁之压力》？",a="这是一本几十年前由矮人矿工马格鲁夫·布拉贡编写的备受推崇的技术手册，详细记录了他对卡兹莫丹深山中挖掘矿石和冶金压力的见解。",al={"什么是铁之压力","铁之压力书籍","马格鲁夫·布拉贡的书"}},{q="为什么帕克斯顿还没归还这本书？",a="帕克斯顿修士仍在为自己图书馆的书架手工抄写这份手稿。由于手工抄写一部详尽的技术著作需要耗费大量的时间和材料，他在完成之前不愿交出原稿。",al={"为什么逾期","为什么帕克斯顿花了这么长时间","帕克斯顿的拖延"}},{q="在哪里可以找到帕克斯顿修士？",a="帕克斯顿修士住在北郡修道院内，这是北郡教士圣殿的所在地，位于艾尔文森林北部的北郡山谷。",al={"帕克斯顿的位置","哪里可以找到帕克斯顿修士"}},{q="在你与帕克斯顿修士对质后会发生什么？",a="帕克斯顿承认自己扣留了这本书，并解释说如果不补充书写材料，他就无法完成抄录，于是他派你去收集墨水供应。",al={"帕克斯顿之后的下一个任务","帕克斯顿需要什么"}}},fp="14,196,17.308.0,19.296.0,51.209.0,22.143.0,31.203.0,40.183.0,34.139.0,47.128.1"}
P.entries["quest:3441"] = {n="神圣的惩戒",s="卡拉然·温布雷让你在灼热峡谷听听他的故事。他的父亲死在了大熔炉里的生物手中，而暴风城的治安官却不肯理睬。卡拉然寻求复仇，并希望有一位冒险者能替他行事。",h="卡拉然·温布雷让你在灼热峡谷听听他的故事。他的父亲死在了大熔炉里的生物手中，而暴风城的治安官却不肯理睬。卡拉然寻求复仇，并希望有一位冒险者能替他行事。",kw={"大熔炉","黑铁矮人","卡拉然·温布雷","拉格纳罗斯","惩罚","暴风城","复仇","温布雷"},sec={{t="被杀害的父亲",b="卡拉然说，大熔炉里的渣滓杀害了他的父亲。他曾恳求暴风城的治安官提供帮助，但这些请求被置若罔闻。他说，暴风城宁愿不承认这个地区的存在，更不用说派士兵来这里伸张正义了。"},{t="复仇的号召",b="卡拉然想要复仇，就这么简单。除了一个笨拙的侍从外，他孤身一人，而黑铁矮人和拉格纳罗斯的野兽会轻易将他碾碎。他相信一位勇敢的冒险者能够对付大熔炉的住民，并承诺给予帮助他的人梦寐以求的财富。"}},faq={{q="卡拉然·温布雷是谁？",a="卡拉然·温布雷是灼热峡谷的一名男子，他的父亲惨遭杀害，他正在寻求复仇。他身边跟着一名侍从。",al={"卡拉然是谁","卡拉然的故事","卡拉然背景传说"}},{q="为什么卡拉然要寻求报复？",a="卡拉然将他父亲的死归咎于居住在大熔炉里的渣滓，他想要复仇。",al={"为什么叫神圣的惩罚","卡拉然的复仇","卡拉然的父亲发生了什么"}},{q="为什么暴风城不帮助卡拉然？",a="卡拉然说暴风城的治安官无视了他的请求。据他说，暴风城不愿承认世界上的这个地区存在，更不想派遣士兵来这里伸张正义。",al={"暴风城的拒绝","为什么暴风城不提供帮助","暴风城治安官"}},{q="卡拉然提到了哪些威胁？",a="他提到了黑铁矮人和拉格纳罗斯的野兽，并说这两者中的任何一个都能轻易压倒他。",al={"大熔炉里有什么","大熔炉的敌人","卡拉然的敌人"}},{q="卡拉然承诺给予什么回报来换取帮助？",a="他向帮助他的勇敢冒险者承诺给予做梦也想不到的巨大财富。",al={"卡拉然的报酬","卡拉然提供了什么"}}},fp="18,235,14.265.0,20.330.0,25.118.0,35.95.0,34.180.0,34.96.0,47.97.0"}
P.entries["quest:3442"] = {n="无瑕之焰",s="卡拉然·温布雷说你做出了正确的选择，而且必须在最能造成破坏的地方给予打击：四座哨塔。一旦四座哨塔同时起火，我们就能在任何人反应过来之前发动攻势。为了点燃它们，卡拉然需要制作无瑕之火火炬。",h="卡拉然·温布雷说你做出了正确的选择，而且必须在最能造成破坏的地方给予打击：四座哨塔。一旦四座哨塔同时起火，我们就能在任何人反应过来之前发动攻势。为了点燃它们，卡拉然需要制作无瑕之火火炬。",kw={"傀儡机油","烈焰之心","卡拉然·温布雷","灼热峡谷","哨塔","无瑕之火火炬"},sec={{t="准备火炬",b="在完成“神圣的惩罚”之后，卡拉然向你说明了计划：烧毁四座哨塔，以便在敌人反应过来之前发动攻势。点燃它们需要合适的工具，而工具需要材料。如果你能带回四个烈焰之心和四个傀儡机油，卡拉然就会为你制作无瑕之火火炬，他首先指向了这片土地上的傀儡和元素生物。"}},faq={{q="收集这些材料的目的是什么？",a="卡拉然·温布雷需要四个烈焰之心和四个傀儡机油来制作能够点燃那四座哨塔的火炬。",al={"为什么要收集烈焰和机油","无瑕之火的目的","无瑕之火火炬的原因"}},{q="在哪里可以找到所需的组件？",a="卡拉然指引你去灼热峡谷寻找傀儡和元素生物。",al={"在哪里寻找傀儡机油","在哪里寻找烈焰之心","无瑕之火材料位置"}},{q="这一步之前需要做什么？",a="这紧随“神圣的惩罚”之后，在那个任务中你听取了卡拉然·温布雷的故事。",al={"无瑕之火前置条件","无瑕之火之前的任务"}},{q="为什么要烧毁哨塔？",a="卡拉然说那里是最能造成破坏的地方，只要四座塔同时起火，就能在任何人反应过来之前发动攻势。",al={"为什么要烧哨塔","哨塔计划"}}},fp="18,276,19.396.0,50.136.0,42.65.0,28.75.0,27.143.0"}
P.entries["quest:3443"] = {n="铸造火炬杆",s="在完成“无暇之焰”任务后，卡拉然·温布雷说，要容纳无暇之焰，既需要柄也需要外壳，而且必须先有柄。大熔炉里的黑铁奴隶贩子和监工使用附魔瑟银武器，八把镀瑟银匕首可以重铸成一个柄。",h="在完成“无暇之焰”任务后，卡拉然·温布雷说，要容纳无暇之焰，既需要柄也需要外壳，而且必须先有柄。大熔炉里的黑铁奴隶贩子和监工使用附魔瑟银武器，八把镀瑟银匕首可以重铸成一个柄。",kw={"大熔炉","黑铁奴隶贩子","黑铁监工","无暇之焰","卡拉然·温布雷","灼热峡谷","镀瑟银匕首"},sec={{t="附魔合金",b="卡拉然说，要容纳无暇之焰，既需要柄也需要外壳。大熔炉里的黑铁奴隶贩子和监工使用附魔瑟银武器作战，这是一种极其坚固的金属。卡拉然可以将他们的八把镀瑟银匕首拆解，并将这种合金重铸成一个柄。"},{t="伶牙俐齿",b="当你把匕首交给他时，卡拉然没有表示感谢，只是嘲讽了几句。他称你为杰出的苦力，并问你是否想过从事其他职业：侦探、破烂收集者，或者是那些在艾泽拉斯海滩上用金属探测装置梳理沙滩、寻找失落宝藏的傻侏儒。"}},faq={{q="卡拉然为什么需要镀瑟银匕首？",a="卡拉然·温布雷可以拆解它们的合金，并将它们重铸成一个柄，以帮助容纳无暇之焰。",al={"为什么需要匕首","镀瑟银匕首的用途","为什么需要瑟银匕首"}},{q="谁携带所需的匕首？",a="大熔炉里的黑铁奴隶贩子和监工使用附魔瑟银武器作战。",al={"谁掉落匕首","匕首在哪里","谁有瑟银匕首"}},{q="这一步在任务链中处于什么位置？",a="它紧接在“无暇之焰”任务之后，在该任务中，你需要收集无暇之焰火炬的材料。",al={"锻造柄之前是什么任务","任务链位置"}},{q="需要多少把匕首？",a="卡拉然需要八把镀瑟银匕首。",al={"多少把匕首","匕首数量","多少把瑟银匕首"}}},fp="17,292,15.297.0,14.320.1,45.105.0,33.90.0,40.95.0,30.46.0"}
P.entries["quest:3444"] = {n="石环",s="玛尔冯·瑞文斯克曾进入沉没的神庙，并险些没能逃出来。现在，一块刻有蛇形符号的圆形石环正放在玛尔冯位于棘齿城的工坊里，它或许能让玛尔冯告诉你更多信息，你受托去把它取回来。",h="玛尔冯·瑞文斯克曾进入沉没的神庙，并险些没能逃出来。现在，一块刻有蛇形符号的圆形石环正放在玛尔冯位于棘齿城的工坊里，它或许能让玛尔冯告诉你更多信息，你受托去把它取回来。",kw={"玛尔冯·瑞文斯克","棘齿城","蛇形雕像","沉没的神庙","塔纳利斯","石环"},sec={{t="玛尔冯的记忆",b="玛尔冯·瑞文斯克提到，沉没的神庙中潜藏着一种邪恶的力量，会侵蚀每一个踏入其厅堂的人。他当时是在遍布地板的粘液中挣扎逃生的，留下的只有对一个挤满了蛇形雕像的大型圆形房间的记忆。"},{t="棘齿城的石环",b="玛尔冯后来偶然发现了一块看起来带有相同蛇形符号的圆形石头。玛尔冯将其装箱并运往了棘齿城的工坊。去把它取来，玛尔冯或许会有更多的事情要分享。"},{t="当石环归来时",b="看到这块石头，玛尔冯确认这就是他要找的那块，并表示一切都回想起来了。"}},faq={{q="玛尔冯·瑞文斯克是谁？",a="玛尔冯·瑞文斯克就是派遣你去取石环的人。玛尔冯曾经进入过沉没的神庙，并险些没能逃脱。",al={"玛尔冯·瑞文斯克","谁给予石环任务","塔纳利斯任务发放者"}},{q="石环在哪里？",a="它被装箱并运送到了玛尔冯在棘齿城的工坊。",al={"石环在哪里","石环工坊","石环位置"}},{q="玛尔冯为什么要找石环？",a="这块石头上刻有蛇形符号，就像玛尔冯记忆中沉没神庙里那个圆形房间里的雕像一样。拿到它，玛尔冯或许就能说出更多细节。",al={"为什么寻找石环","石环用途"}},{q="玛尔冯在沉没的神庙里发生了什么？",a="玛尔冯几乎找不到出口，只能涉水穿过满地的粘液。他唯一能回想起来的，就是在挤满了蛇形雕像的大型圆形房间里踉跄前行。",al={"玛尔冯沉没的神庙","玛尔冯背景故事"}}},fp="16,219,15.259.0,20.191.0,22.85.1,26.116.0,26.58.0,38.155.0,45.173.0"}
P.entries["quest:3445"] = {n="沉没的神庙",s="安吉拉斯·月风提到了沉没的神庙，那是一个埋藏在地下深处的地方，被某种安吉拉斯所见过的最为强大的力量放置在那里。为了了解更多信息，她指引你去找一个名叫玛尔冯·瑞文斯克的侏儒，据说他最后出现在塔纳利斯。",h="安吉拉斯·月风提到了沉没的神庙，那是一个埋藏在地下深处的地方，被某种安吉拉斯所见过的最为强大的力量放置在那里。为了了解更多信息，她指引你去找一个名叫玛尔冯·瑞文斯克的侏儒，据说他最后出现在塔纳利斯。",kw={"安吉拉斯·月风","菲拉斯","玛尔冯·瑞文斯克","棘齿城","沉没的神庙","塔纳利斯","巨魔遗迹"},sec={{t="被放逐到地下的地方",b="安吉拉斯·月风讲述了一个沉没在地球表面之下深处的地方，那里被比安吉拉斯所见过的一切更为强大的力量所放置：沉没的神庙。欲知详情，请寻找侏儒玛尔冯·瑞文斯克，他像安吉拉斯和特洛亚斯一样，一直在研究世界各地的古老遗迹。玛尔冯离开了棘齿城的家，去调查塔纳利斯的巨魔遗迹，关于他的消息已经断绝许久了。"},{t="玛尔冯的说法",b="当你找到玛尔冯·瑞文斯克时，他说他曾亲眼见过沉没的神庙，并询问你是否想了解更多。他认为你是一个喜欢冒险的人，并说他知道一些可能会让你感兴趣的事情。"}},faq={{q="谁开启了寻找沉没的神庙的任务？",a="安吉拉斯·月风，她讲述了一个沉没在地球深处的地方——沉没的神庙，那里被某种比安吉拉斯所见过的一切更为强大的力量所放置。",al={"沉没的神庙任务发布者","谁发布沉没的神庙任务","安吉拉斯·月风"}},{q="玛尔冯·瑞文斯克是谁？",a="一个像安吉拉斯和特洛亚斯一样，致力于研究世界各地古老遗迹的侏儒。",al={"玛尔冯·瑞文斯克","玛尔冯·瑞文斯克在哪里","玛尔冯是谁"}},{q="玛尔冯·瑞文斯克去了哪里？",a="最后的传言说他离开了自己的家乡棘齿城，前往塔纳利斯调查那里的巨魔遗迹。已经有很长一段时间没有人听到过关于他的消息了。",al={"玛尔冯的位置","在哪里找到玛尔冯","玛尔冯 塔纳利斯"}}},fp="17,231,22.397.0,16.221.1,44.143.0,26.90.0,32.117.0"}
P.entries["quest:345"] = {n="墨水短缺",s="“墨水补给”是联盟的一项跑腿任务，受命于北郡修道院的僧侣抄写员帕克斯顿修士。为了酿造他那种速干墨水，帕克斯顿需要一种特殊的矿物成分，因此他派遣一名冒险者向东前往饱受战火的湖畔镇，去向工头奥斯洛索取瑞斯班矿石。",h="“墨水补给”是联盟的一项跑腿任务，受命于北郡修道院的僧侣抄写员帕克斯顿修士。为了酿造他那种速干墨水，帕克斯顿需要一种特殊的矿物成分，因此他派遣一名冒险者向东前往饱受战火的湖畔镇，去向工头奥斯洛索取瑞斯班矿石。",kw={"帕克斯顿修士","工头奥斯洛","墨水补给","湖畔镇","北郡修道院","赤脊山","瑞斯班矿石","铁之重压"},ang={["class:Priest"]="帕克斯顿修士的这项差事源于克里斯托弗修士关于“精神毅力”的布道，旨在让圣光的信徒们协助教士完成学术职责。",["faction:Alliance"]="这段旅程展现了北郡修道院宁静避世的环境与湖畔镇深陷的前线危机之间那鲜明的对比。",["profession:Mining"]="该任务重点介绍了瑞斯班铁矿，这是一种埋藏在赤脊山高处岩石缝隙中的地方性矿床。"},sec={{t="抄写员的配方",b="帕克斯顿修士对他所从事的文学创作引以为傲，拒绝在《铁之重压》这类重要文献的誊写中使用普通墨水。相反，他酿造了一种以不易晕染且速干著称的定制配方。这种配方唯一的缺陷是如果不加看管，墨水在墨水瓶里就会很快干掉。补充库存需要用到生的瑞斯班铁矿，这是一种产自赤脊山岩石地带的独特矿石。"},{t="围城中的城镇",b="当旅行者带着帕克斯顿那卑微的征用要求抵达湖畔镇时，会发现那里的局势根本容不得他们去满足一位遥远僧侣的愿望。工头奥斯洛监管着镇上忙碌的劳工，他们正忙于加固路障、重建废墟，并全力抵御黑石兽人不断的突袭。奥斯洛既无人手也没耐心去为暴风城的抄写员挖矿，只能让外来者独自闯入危险的瑞斯班洞穴。"}},faq={{q="为什么帕克斯顿修士需要铁矿来制作墨水？",a="帕克斯顿修士使用一种专有配方来制作永不褪色、不会晕染且能迅速干燥的书写墨水。磨碎的瑞斯班铁矿提供了他这种独特墨水所必需的关键矿物颜料和定色特性。",al={"为什么墨水需要铁","帕克斯顿 矿石 墨水","帕克斯顿修士 墨水配方"}},{q="工头奥斯洛是谁？",a="工头奥斯洛是负责湖畔镇民用建筑和修缮工作的总负责人。由于城镇不断受到黑石兽人的压力，他负责指挥沿湖的防御工事和重建工作。",al={"工头奥斯洛","奥斯洛 湖畔镇","奥斯洛是谁"}},{q="帕克斯顿修士把你派到哪里去了？",a="帕克斯顿让你从艾尔文森林出发向东前往赤脊山的核心城镇湖畔镇，去寻找工头奥斯洛。",al={"墨水补给 目的地","奥斯洛在哪里","去哪里做墨水补给任务"}},{q="为什么工头奥斯洛不直接把矿石给你？",a="湖畔镇正面临黑石氏族兽人的猛烈进攻。奥斯洛的团队正全力以赴修复受损建筑并加固城镇防线，根本没有闲暇人手去完成采矿这类跑腿活。",al={"为什么没有矿石","奥斯洛拒绝给矿石","奥斯洛为什么生气"}},{q="帕克斯顿修士试图抄写什么书？",a="他正在誊写一本名为《铁之重压》的著作，但由于之前那批速干墨水在容器里凝固了，导致他的工作被迫中断。",al={"帕克斯顿 书籍","帕克斯顿在抄写什么","铁之重压"}},{q="和工头奥斯洛交谈后会发生什么？",a="奥斯洛会告诉你，如果你想要瑞斯班铁矿，就必须亲自去止水湖北边的危险地带——瑞斯班洞穴挖掘。",al={"墨水补给后的下一个任务","奥斯洛之后做什么","墨水补给 后续"}}},fp="12,126,18.292.0,18.271.0,46.172.0,21.151.0,35.118.0,46.166.0,47.135.0,47.118.0"}
P.entries["quest:3452"] = {n="烈焰之盒",s="在铸造好握柄后，卡拉然·温布雷说火炬还需要最后一件东西。在西北方有一个大型暮光之锤营地，据说那里藏有供奉他们神祇的符记和偶像，卡拉然想要一个拉格纳罗斯符记。",h="在铸造好握柄后，卡拉然·温布雷说火炬还需要最后一件东西。在西北方有一个大型暮光之锤营地，据说那里藏有供奉他们神祇的符记和偶像，卡拉然想要一个拉格纳罗斯符记。",kw={"火焰外壳","卡拉然·温布雷","灼热峡谷","拉格纳罗斯符记","惩戒火炬","暮光之锤"},sec={{t="外壳的部件",b="卡拉然称这是火炬所需的最后一件东西。在西北方的群山之中，据传有一个大型暮光之锤营地，那里存放着供奉他们神祇的符记和偶像，这些东西可能蕴含足够的附魔能量，足以充当魔法外壳。卡拉然要求取回一个拉格纳罗斯符记，并会尝试从中汲取魔法。惩戒火炬还缺一样东西，那就是合适的奥术能量源。"},{t="检查符记",b="这个符记散发着邪恶的魔法气息，卡拉然认为这正是完成工作所需要的。"}},faq={{q="制造火焰外壳需要什么？",a="卡拉然·温布雷要求一个拉格纳罗斯符记，他可以从中汲取魔法来构成外壳。",al={"火焰外壳物品","卡拉然需要什么","需要的符记"}},{q="暮光之锤营地在哪里？",a="卡拉然说，一个大型暮光之锤营地位于西北方的群山中。",al={"暮光之锤位置","邪教营地在哪里","西北群山邪教"}},{q="为什么卡拉然想要拉格纳罗斯符记？",a="暮光之锤的符记和偶像可能带有足够的附魔能量来构成魔法外壳，卡拉然希望从中汲取魔法。",al={"为什么需要拉格纳罗斯符记","拉格纳罗斯符记用途","符记有什么作用"}},{q="这一步在任务链中位于什么位置？",a="它紧接在“铸造握柄”之后，在那个任务里，卡拉然要求用瑟银镀层匕首重铸成握柄。",al={"前序任务","火焰外壳之前的任务"}}},fp="18,247,22.399.0,19.74.1,44.105.0,42.89.0,43.148.0,41.104.0"}
P.entries["quest:3453"] = {n="惩戒火炬",s="在完成“火焰外壳”后，卡拉然·温布雷要求你稍作等待，他需要将碎片拼合在一起，并为火炬附魔。这项工作是一种必须不能被打断的引导法术。",h="在完成“火焰外壳”后，卡拉然·温布雷要求你稍作等待，他需要将碎片拼合在一起，并为火炬附魔。这项工作是一种必须不能被打断的引导法术。",kw={"引导","附魔","卡拉然·温布雷","灼热峡谷","惩戒火炬"},sec={{t="拼合碎片",b="碎片收集齐后，卡拉然需要一点时间将它们拼合，并为火炬施加必要的附魔。这项工作是一种必须不能被打断的引导法术，所以你需要等待卡拉然施法。"},{t="等待结束时",b="过了一会儿，火炬出现在卡拉然面前，他宣布工作完成了。卡拉然补充说，还有最后一件事情需要你去处理。"}},faq={{q="是谁制作了火炬？",a="卡拉然·温布雷将碎片组合在一起并施加附魔，通过引导魔法来完成火炬的制作。",al={"火炬工匠","谁制作了火炬","卡拉然·温布雷的角色"}},{q="这一步之前发生了什么？",a="“火焰外壳”，在那个任务中，你为卡拉然找到了一枚拉格纳罗斯符记，用来制作外壳。",al={"上一个任务","先决条件","我刚做了什么"}},{q="为什么你不能打断卡拉然？",a="卡拉然正在引导法术，他警告你在拼合碎片的过程中不要打断这个过程。",al={"不要打断","引导过程"}}},fp="24,169,18.195.0,18.137.1,21.105.0,33.96.0,35.96.0"}
P.entries["quest:3454"] = {n="惩戒火炬",s="惩戒火炬制作完成后，卡拉然·温布雷说它现在需要绑定一名主人，并让你将其拿起来。",h="惩戒火炬制作完成后，卡拉然·温布雷说它现在需要绑定一名主人，并让你将其拿起来。",kw={"绑定","卡拉然·温布雷","灼热峡谷","惩戒火炬"},sec={{t="烈焰之缚",b="卡拉然说火炬需要绑定到它的主人身上。为了做到这一点，他让你亲自将其拿起。"},{t="在手中燃烧的火炬",b="你双手握住火炬，仇恨与愤怒如潮水般涌过你的全身。"}},faq={{q="是谁让你拿起火炬的？",a="卡拉然·温布雷，他说火炬需要绑定到它的主人身上。",al={"谁给了火炬","火炬任务发布者","卡拉然火炬"}},{q="为什么要拿起火炬？",a="卡拉然说火炬必须绑定到它的主人身上，并让你将其拿起。",al={"为什么拿起火炬","火炬绑定"}},{q="这一步在任务链中处于什么位置？",a="它紧接在之前的“惩戒火炬”步骤之后，在那一步中，你需要等待卡拉然将碎片组合并附魔。",al={"火炬任务链","上一个任务"}}},fp="24,110,17.103.0,17.82.1,32.62.0,31.79.0,40.123.0"}
P.entries["quest:346"] = {n="克里斯托弗的书",s="“回到克里斯托弗处”为克里斯托弗修士寻找那本难以寻获的著作《The Stresses of Iron》画上了句号。在穿越赤脊山去获取用于特殊墨水的矿石，并等待北郡修道院的抄写员完成工作后，The Adventurer终于将这本借出的书带回了暴风城的Cathedral of Light。",h="“回到克里斯托弗处”为克里斯托弗修士寻找那本难以寻获的著作《The Stresses of Iron》画上了句号。在穿越赤脊山去获取用于特殊墨水的矿石，并等待北郡修道院的抄写员完成工作后，The...",kw={"克里斯托弗修士","brother paxton","cathedral square","米尔顿·西弗","北郡修道院","回到克里斯托弗处","暴风城","the stresses of iron"},ang={["class:Priest"]="教会的一项简单差事展示了圣光教会是如何在整个王国中维护、保存和分发关键学术资料的。",["faction:Alliance"]="即使是看似琐碎的学术交流，也依赖于连接Stormwind Keep、北郡和饱受战火的赤脊山之间的安全道路。"},sec={{t="久候的归还",b="驻扎在暴风城Cathedral Square的克里斯托弗修士需要查阅一本名为《The Stresses of Iron》的冶金学专业书籍。为了这本书，信使们奔波于人类领地，先是前往了Stormwind Keep的Royal Library，随后深入北郡修道院。在修道院里，Brother Paxton正忙着手工誊写该书，但由于缺乏制作抄写墨水所需的Rethban ore，进度有所延误。随着矿石被取回且誊写完成，Paxton最终交出了原书，以便将其归还给城市。"},{t="抄写员的辛劳",b="在一个不断受到外界威胁压迫的王国里，北郡修道院的抄写员们所做的静默工作，对于保存市民与精神知识依然至关重要。Brother Paxton请求向Librarian Milton Sheaf致歉，这凸显了修道院的资源是多么匮乏。珍贵的书籍必须在归还给暴风城之前，用富含矿物质的墨水一笔一划地精心复制，这使得一个简单的借书请求变成了一项艰巨的后勤差事。"}},faq={{q="《The Stresses of Iron》这本书讲的是什么？",a="《The Stresses of Iron》是一本关于冶金和金属加工的专著。克里斯托弗修士在Cathedral Square寻求查阅此书以进行研究，而北郡修道院的抄写员则需要一份精确的副本以保存其知识。",al={"什么是stresses of iron","stresses of iron书籍","克里斯托弗在找什么书"}},{q="为什么这本书在北郡修道院？",a="Royal Library将这本书借给了Brother Paxton，以便他能为北郡修道院的档案馆制作一份精美的副本。那里的抄写员通过手工保存重要的文本，但Paxton的进度因缺乏用于制作特殊墨水的Rethban ore而停滞不前。",al={"为什么paxton拿着那本书","为什么它在北郡"}},{q="克里斯托弗修士是谁？",a="克里斯托弗修士是Clergy of the Holy Light的一员，驻扎在暴风城Cathedral of Light外的Cathedral Square。他请求借阅此书，并以圣光的祝福作为回报表示感谢。",al={"克里斯托弗是谁","暴风城的克里斯托弗"}},{q="Milton是谁？",a="Milton Sheaf是居住在Stormwind Keep的Royal Library的首席图书管理员。他最初批准了《The Stresses of Iron》的借阅，并对这本书的长时间迟迟未归感到不耐烦。",al={"图书管理员milton是谁","米尔顿·西弗"}},{q="这个任务链在哪里开始？",a="该任务链始于暴风城的Cathedral Square，由克里斯托弗修士发布的任务“Speaking of Fortitude”开启，随后引导玩家前往Librarian Milton Sheaf处，再前往北郡修道院，最后进入赤脊山，并在回到克里斯托弗处时结束。",al={"如何开始speaking of fortitude","任务链起始"}},{q="这个任务有后续吗？",a="“回到克里斯托弗处”标志着“Speaking of Fortitude”任务线的终结。当你交付《The Stresses of Iron》后，克里斯托弗修士会表达他的感谢并给予圣光的祝福，从而解决此事。",al={"回到克里斯托弗处之后是什么","还有下一个任务吗"}}},fp="18,178,21.367.0,20.305.0,44.196.0,37.202.0,24.194.0,14.155.0,34.222.0,36.159.0"}
P.entries["quest:3462"] = {n="侍卫玛特拉克",s="在完成“惩戒火炬”任务后，卡拉然·温布雷会让你去找他们的信使，随从马特雷克。马特雷克会告诉你这把火炬该如何使用。",h="在完成“惩戒火炬”任务后，卡拉然·温布雷会让你去找他们的信使，随从马特雷克。马特雷克会告诉你这把火炬该如何使用。",kw={"信使","卡拉然·温布雷","灼热峡谷","随从马特雷克","惩戒火炬"},sec={{t="与信使交谈",b="卡拉然·温布雷指引你去找信使随从马特雷克。正是他会向你解释“惩戒火炬”该如何使用。"}},faq={{q="谁指引你去找随从马特雷克？",a="卡拉然·温布雷，他称马特雷克为信使，并让你去听取他的指示。",al={"谁指派随从马特雷克","随从马特雷克任务发布者","谁开启随从马特雷克任务"}},{q="随从马特雷克的职责是什么？",a="马特雷克是卡拉然·温布雷指定的信使，他将指导你如何使用“惩戒火炬”。",al={"随从马特雷克的作用","马特雷克是谁","为什么找马特雷克"}},{q="在与随从马特雷克交谈之前需要做什么？",a="完成“惩戒火炬”，这是任务链中在此之前的一步。",al={"随从马特雷克的前置条件","随从马特雷克之前的任务","马特雷克前置任务"}}},fp="15,154,21.143.0,33.95.0,31.115.0,46.63.0"}
P.entries["quest:3463"] = {n="烧掉它们！",s="侍从马尔特雷克告诉你，灼热峡谷的四座塔楼永远无法被摧毁，但惩戒火炬可以让它们燃烧很长一段时间。当它们燃烧时，没有任何卫兵或哨兵能够守住岗哨，黑铁矮人也将失去他们的第一道防线。",h="侍从马尔特雷克告诉你，灼热峡谷的四座塔楼永远无法被摧毁，但惩戒火炬可以让它们燃烧很长一段时间。当它们燃烧时，没有任何卫兵或哨兵能够守住岗哨，黑铁矮人也将失去他们的第一道防线。",kw={"黑铁","灼热峡谷","哨塔","点燃它们","侍从马尔特雷克","惩戒火炬"},sec={{t="无法被扑灭的烈火",b="火炬点燃的火焰无法被任何元素或力量扑灭。马尔特雷克派你进入北、南、东、西四座哨塔中的每一座，在塔内使用火炬。黑铁矮人在塔楼部署了岗哨，马尔特雷克警告你要小心他们。"},{t="余焰之后",b="当最后一座塔楼燃起大火后，你回到马尔特雷克身边，听到他向一位主人欢呼胜利。欺诈者Velarok现身回应，显露出他是一条黑龙军团的幼龙。他沾沾自喜地说，他的计划非常完美，因为如果黑石军团只是提出要求，你绝不会帮助他们。当马尔特雷克询问现在该如何处置你时，Velarok让他闭嘴：你会活着看到黑石军团入侵峡谷。他让马尔特雷克交出饰品，提到了蜕皮，然后飞向了峡谷。"}},faq={{q="是谁派你去点燃这些塔楼的？",a="是侍从马尔特雷克，他提供了惩戒火炬来完成这项任务。",al={"谁给予点燃它们任务","点燃它们任务给予者","马尔特雷克任务"}},{q="必须点燃哪些塔楼？",a="四座哨塔：北塔、南塔、东塔和西塔。必须进入每一座塔，并在塔内使用火炬。",al={"哪些塔楼","哨塔位置","点燃它们塔楼"}},{q="为什么使用惩戒火炬而不是拆毁塔楼？",a="塔楼是无法被摧毁的。相反，火炬可以让它们燃烧很久，且其火焰无法被任何元素或力量扑灭。",al={"为什么使用火炬","摧毁哨塔"}},{q="在此步骤之前的上一步是什么？",a="与侍从马尔特雷克交谈，他随后会交给你这个任务。",al={"点燃它们前置任务","之前任务"}}},fp="16,269,26.287.0,20.520.1,39.75.0,29.101.0,68.125.0,43.67.0"}
P.entries["quest:347"] = {n="瑞斯班矿石",s="工头奥斯洛指挥冒险者们前往赤脊山的瑞斯班洞穴，取回一种奇异的暗色矿石。虽然这种矿石太软，无法用来锻造结实的护甲或武器，但它独特的色泽使其成为了北郡修道院的抄写员制作特制墨水不可或缺的原料。",h="工头奥斯洛指挥冒险者们前往赤脊山的瑞斯班洞穴，取回一种奇异的暗色矿石。虽然这种矿石太软，无法用来锻造结实的护甲或武器，但它独特的色泽使其成为了北郡修道院的抄写员制作特制墨水不可或缺的原料。",kw={"巴特·瑞斯班","帕克斯顿修士","工头奥斯洛","北郡修道院","赤脊山苦工","瑞斯班洞穴","瑞斯班矿石","铁之压力"},ang={["faction:Alliance"]="这项任务突显了暴风城王国的补给线是多么吃紧，以至于修道院的抄写员不得不依靠四处奔波的冒险者从战区取回基本的书写补给。",["profession:Mining"]="矿工可以用镐直接从洞穴矿脉中提取瑞斯班矿石，而不必从豺狼人苦工手中搜刮零散的原矿。",["race:Human"]="在北郡修道院保存历史手稿是暴风城学者的神圣职责，他们致力于恢复在第一次和第二次战争中遗失的知识。"},sec={{t="奇特的矿石",b="瑞斯班矿石是以其发现者巴特·瑞斯班的名字命名的。与普通的铁矿或铜矿不同，这种矿石在护甲匠的铁砧上几乎没有价值——它熔炼出的金属缺乏锻造坚固武器或板甲所必需的抗拉强度。其真正的价值在于其天然的、暗沉的色泽，修道士和抄写员们将其视为制作浓郁手稿染料的重要色素来源。"},{t="争夺中的洞穴",b="该矿石的主要矿脉位于瑞斯班洞穴内，坐落在赤脊山北部的群山之中。不幸的是，对于湖畔镇的石匠们来说，当地的矿工已经放弃了该洞穴。一群凶猛的赤脊山豺狼人占领了这些隧道，并让豺狼人苦工在岩石矿脉中挖掘，以满足他们自己粗陋的需求。"},{t="守护文字",b="北郡修道院内的一位修道士，帕克斯顿修士，依赖这种色素来复制历史文献。他目前的工作——誊抄一份名为《铁之压力》的论文——因为缺少合适的染料而被迫中断，不得不派遣信使和冒险者深入豺狼人出没的领地，以获取这种原石。"}},faq={{q="瑞斯班矿石有什么用途？",a="虽然它在熔炼后质地太脆，无法锻造耐用的武器或护甲，但其暗沉的色泽使其成为墨水和染料的绝佳基础色素。北郡修道院的帕克斯顿修士等抄写员依靠它来润色和誊抄历史手稿。",al={"为什么我们需要瑞斯班矿石","瑞斯班矿石的用途","瑞斯班矿石有什么用"}},{q="巴特·瑞斯班是谁？",a="巴特·瑞斯班是最初发现赤脊山北部山区暗色矿脉的探险家和勘探者，这种矿石和瑞斯班洞穴的名字都来源于他。",al={"谁发现了瑞斯班矿石","巴特·瑞斯班的背景故事"}},{q="为什么湖畔镇最近没有开采这种矿石？",a="工头奥斯洛和镇上的工人们正忙于防守湖畔镇，抵御黑石兽人的入侵。更糟糕的是，赤脊山豺狼人搬进了瑞斯班洞穴，强迫平民矿工离开。",al={"为什么奥斯洛不去开采","为什么矿场被遗弃了"}},{q="帕克斯顿修士在抄写什么书？",a="帕克斯顿修士正在勤恳地抄写一本名为《铁之压力》的资料性著作。他需要用瑞斯班矿石制成的深色染料来完成为修道院图书馆誊写的文本。",al={"帕克斯顿在写什么书","帕克斯顿的手稿"}},{q="为什么豺狼人想要这些矿石？",a="赤脊山豺狼人已经让他们的苦工在洞穴各处挖掘。虽然豺狼人很少保留大量的书面记录，但他们垂涎金属矿藏，可以用来制造粗糙的器具、进行贸易，或者仅仅是为了加固他们的山中巢穴以抵御入侵者。",al={"为什么豺狼人在采矿","瑞斯班豺狼人苦工"}},{q="这个任务链接下来会引向何处？",a="一旦帕克斯顿修士收到矿石并完成了墨水的配制，他会指引你回到暴风城，向克里斯托夫汇报你的成功，从而结束北郡抄写员的委托。",al={"瑞斯班矿石之后是什么任务","接下来返回克里斯托夫处"}}},fp="11,190,17.286.0,17.260.0,19.246.0,29.214.0,21.177.0,44.191.0,36.133.0,27.170.0,38.181.1"}
P.entries["quest:348"] = {n="荆棘谷热疫",s="在藏宝海湾，芬·菲兹拉克患上了荆棘谷热，这是一种致命的病毒。他说唯一的解药是被称为“野蛮者莫克”的难以捉摸的白兽的心脏，他还说自己快要死了。",h="在藏宝海湾，芬·菲兹拉克患上了荆棘谷热，这是一种致命的病毒。他说唯一的解药是被称为“野蛮者莫克”的难以捉摸的白兽的心脏，他还说自己快要死了。",kw={"藏宝海湾","芬·菲兹拉克","莫克的心脏","野蛮者莫克","荆棘谷热","荆棘谷","巫医安巴格瓦"},sec={{t="绝望的解药",b="芬·菲兹拉克语无伦次，日渐虚弱，确信自己得了荆棘谷热。他说唯一的解药就是吃掉野蛮者莫克的心脏，那是一只难以捉摸的白兽。只有巫医安巴格瓦能召唤这只生物，芬让你去南部海角的隐秘洞穴——灵魂之穴找安巴格瓦。"},{t="回到芬的身边",b="当莫克的心脏落入芬手中后，他的体力开始恢复。他醒来时对身处之地感到困惑，当得知这里是藏宝海湾时，他谈起了一个奇怪的梦。但虚弱感仍挥之不去。"}},faq={{q="芬·菲兹拉克患了什么病？",a="芬说他得了荆棘谷热，这是一种致命的病毒。它让他感到寒冷和神志不清，他以为自己快要死了。",al={"芬得了什么病","荆棘谷热疾病","芬·菲兹拉克生病"}},{q="需要什么来治愈这种热病？",a="芬说唯一的解药就是吃掉野蛮者莫克的心脏，那是一只难以捉摸的白兽。",al={"如何治愈荆棘谷热","治愈芬·菲兹拉克的方法","莫克的心脏解药"}},{q="巫医安巴格瓦是谁？",a="芬说巫医安巴格瓦是唯一能召唤野蛮者莫克的人。他住在荆棘谷南部海角的一个隐秘洞穴里，也就是灵魂之穴。",al={"安巴格瓦在哪里","谁能召唤莫克","巫医安巴格瓦的作用"}},{q="在哪里可以找到芬·菲兹拉克？",a="芬·菲兹拉克在藏宝海湾。",al={"芬·菲兹拉克的位置","芬·菲兹拉克在哪里","藏宝海湾发热的人"}}},fp="19,180,16.325.0,18.210.1,45.115.0,35.86.0,28.166.0,33.30.0"}
P.entries["quest:3481"] = {n="打开箱子…",s="在完成“点燃它们！”任务后，一个名为黑龙军团宝箱的箱子会在灼热峡谷等你。它看起来是锁着的。",h="在完成“点燃它们！”任务后，一个名为黑龙军团宝箱的箱子会在灼热峡谷等你。它看起来是锁着的。",kw={"黑龙军团宝箱","灼热峡谷","点燃它们","饰品"},sec={{t="锁住的箱子",b="黑龙军团宝箱看起来是锁着的，但你可以将其打开。当灼热峡谷的塔楼燃烧起来后，这个箱子就会出现。"},{t="触碰时",b="这个箱子在你触碰时就会开启，无需钥匙。里面装着一片黑龙军团的鳞片。我不禁在想里面会不会藏着什么干酪，而了解真相的唯一方法就是去看看。"}},faq={{q="什么是黑龙军团宝箱？",a="一个在完成“点燃它们！”后出现在灼热峡谷的箱子。它看起来是锁着的。",al={"什么是黑龙军团宝箱","谁拥有这个箱子","饰品箱子位置"}},{q="在这个箱子之前需要做什么？",a="“点燃它们！”，即针对灼热峡谷塔楼的纵火行动。",al={"饰品前置条件","前置任务","什么任务能引导至饰品"}},{q="任务要求你对这个箱子做什么？",a="打开它。箱子看起来是锁着的，但你需要做的仅仅是打开它。",al={"箱子是锁着的吗","如何打开箱子","如何处理箱子"}}},fp="11,123,14.153.0,13.192.1,44.84.0,28.71.0,40.76.0"}
P.entries["quest:349"] = {n="荆棘谷热疫",s="在荆棘谷的深处，巫医安巴格瓦声称他知道如何引出名为“野蛮的莫克”的野兽。在与灵魂沟通开始之前，这位巫医需要十枚大猩猩獠牙作为祭品。仪式一旦开始，就必须保护这位巨魔免受狂躁丛林野兽的侵害，以此将那头生物引诱出来。",h="在荆棘谷的深处，巫医安巴格瓦声称他知道如何引出名为“野蛮的莫克”的野兽。在与灵魂沟通开始之前，这位巫医需要十枚大猩猩獠牙作为祭品。仪式一旦开始，就必须保护这位巨魔免受狂躁丛林野兽的侵害，以此将那头生物引诱出来。",kw={"大猩猩獠牙","野蛮的莫克","荆棘谷热病","荆棘谷","安巴格瓦","巫医"},sec={{t="野蛮的仪式",b="巫医安巴格瓦掌握着将野蛮的莫克从周围丛林中召唤出来的仪式知识。为了开始吟唱，巫医索要十枚大猩猩獠牙。与灵魂沟通伴随着巨大的风险，因为仪式吟唱会吸引附近其他大猩猩野兽的注意，因此在魔法生效时必须对他进行保护。"}},faq={{q="谁是巫医安巴格瓦？",a="巫医安巴格瓦是荆棘谷的一名巨魔修行者，他声称能与灵魂交谈，以此引诱巨猿“野蛮的莫克”。",al={"安巴格瓦","谁是安巴格瓦","巫医安巴格瓦"}},{q="巫医安巴格瓦开始仪式需要什么？",a="在同意与灵魂沟通之前，这位巫医需要十枚大猩猩獠牙。",al={"大猩猩獠牙任务","安巴格瓦需要什么物品","安巴格瓦的要求"}},{q="为什么要保护巫医？",a="与灵魂沟通会吸引他周围的其他大猩猩野兽。如果被这些野兽淹没，安巴格瓦就无法完成召唤莫克的仪式。",al={"为什么要保护安巴格瓦","保护巫医安巴格瓦","大猩猩野兽仪式"}},{q="谁是野蛮的莫克？",a="野蛮的莫克是一头潜伏在荆棘谷的强大大猩猩野兽，巫医安巴格瓦知道如何召唤它。",al={"莫克","谁是莫克","野蛮的莫克"}}},fp="19,340,23.367.0,28.142.0,48.86.0,38.150.0,23.120.0"}
P.entries["quest:35"] = {n="卫兵托马斯",s="“进一步的担忧”是一项由闪金镇的治安官杜汉派发的联盟信使任务，旨在调查关于水栖生物威胁的传言。治安官派你向东穿过艾尔文森林，去咨询河道旁的卫兵托马斯。这会将你的注意力从镇中心的守卫职责转移到东部边境日益恶化的安全危机上。",h="“进一步的担忧”是一项由闪金镇的治安官杜汉派发的联盟信使任务，旨在调查关于水栖生物威胁的传言。治安官派你向东穿过艾尔文森林，去咨询河道旁的卫兵托马斯。这会将你的注意力从镇中心的守卫职责转移到东部边境日益恶化的安全危机上。",kw={"东部桥梁","艾尔文森林","进一步的担忧","闪金镇","卫兵托马斯","治安官杜汉","鱼人"},ang={["faction:Alliance"]="该任务突显了暴风城王国日益增长的运作裂痕，展示了人类的防御力量在距离首都仅一步之遥的地方是多么薄弱。",["race:Human"]="对于艾尔文森林的人类来说，好斗鱼人的蔓延威胁到了连接闪金镇和湖畔镇的粮仓农场和贸易动脉。"},sec={{t="关注东部路口",b="尽管艾尔文森林中部正饱受强盗和害虫的困扰，但关于水栖生物在河岸边潜行的警人传言已开始流传。驻守闪金镇的治安官杜汉并没有直接忽视这些恐慌。他没有从镇里抽调卫兵，而是派旅行者向东走，去咨询驻守在通往赤脊山河流桥梁上的卫兵托马斯。"},{t="紧缩的防线",b="卫兵托马斯已经在桥头的哨所驻守了一周多，亲眼目睹了闪金镇领导层此前仅能怀疑的情况。具有半智慧的敌对鱼人在艾尔文森林东部的所有水道沿岸建立了营地。由于暴风城的军队不在，且当地守卫被束缚在镇墙和补给线的防守上，像托马斯哨所这样的农村桥头堡在面对这种逼近的危险时，陷入了严重的孤立无援。"}},faq={{q="为什么治安官杜汉要派我去找卫兵托马斯？",a="治安官杜汉收到了关于鱼人潜入东部水道的报告和传言。因为卫兵托马斯已经在艾尔文森林东部的桥上驻守了一周，杜汉依靠他来确认这一威胁是否属实。",al={"为何找卫兵托马斯","杜汉的目的","与托马斯交谈"}},{q="卫兵托马斯驻守在哪里？",a="卫兵托马斯驻守在艾尔文森林最东端跨越河流的木桥上，看守着通往赤脊山的道路。",al={"卫兵托马斯位置","托马斯在哪","东部桥梁守卫"}},{q="卫兵托马斯确认了什么威胁？",a="卫兵托马斯确认，敌对且具有半智慧的鱼人确实已经在艾尔文森林东部的溪流和水道沿岸定居，这对旅行者和附近的农场构成了直接的危险。",al={"鱼人威胁","托马斯发现了什么","东部河流威胁"}},{q="如何找到卫兵托马斯？",a="从闪金镇沿路向东穿过艾尔文森林，到达东部河流上的桥梁，卫兵托马斯就在那里值守。",al={"前往托马斯的捷径","杜汉骑马","前往桥梁"}},{q="为什么暴风城不派军队来帮助东部艾尔文？",a="随着瓦里安·乌瑞恩国王失踪，暴风城的常备军力受到严重限制，资源也从乡村地区被调走。像卫兵托马斯这样的外围哨兵大部分只能依靠过往的冒险者。",al={"暴风城卫兵在哪里","艾尔文为什么没有防御","暴风城军事援助"}},{q="向卫兵托马斯报告后会发生什么？",a="一旦卫兵托马斯确认了鱼人的存在，他会请求你帮忙调查其他巡逻河岸却未归的哨兵的下落。",al={"进一步的担忧后续任务","托马斯后续","失踪的守卫任务"}}},fp="16,161,28.298.0,25.337.0,48.221.0,32.126.0,38.166.0,30.124.0,58.192.0,45.158.0"}
P.entries["quest:350"] = {n="老朋友",s="马迪亚斯·肖尔大师指示一名调查员去暴风城的贸易区寻找一位不同寻常的联络人。由于贵族的腐败使得强大的叛徒可以逃脱常规法律的制裁，这位情报头子不得不勉强求助于城市里最棒的奶酪商的情报网。",h="马迪亚斯·肖尔大师指示一名调查员去暴风城的贸易区寻找一位不同寻常的联络人。由于贵族的腐败使得强大的叛徒可以逃脱常规法律的制裁，这位情报头子不得不勉强求助于城市里最棒的奶酪商的情报网。",kw={"迪菲亚","埃林·提亚斯","莱斯科瓦尔","马尔松","mathias shaw","暴风城","trade district","提亚斯奶酪店"},ang={["class:Rogue"]="马迪亚斯·肖尔和埃林·提亚斯之间那种心照不宣的竞争，展现了暴风城秘密特工内部的分裂状态，在这里，街头层次的线人往往比王室官方的情报部门拥有更好的筹码。",["faction:Alliance"]="这项任务展示了贵族议会的腐败是如何在瓦里安·乌瑞恩国王失踪期间，让暴风城的内部安全陷入瘫痪的。"},sec={{t="凌驾于法律之上",b="在发现格雷戈尔·莱斯科瓦尔勋爵和刺客“静刃”马尔松与迪菲亚潜行者之间存在直接联系后，马迪亚斯·肖尔大师的情报工作陷入了死胡同。随着艾德温·范克里夫在死亡矿井中身亡，巴基尔·斯瑞德在监狱中被除掉，已经没有活着的强盗头目可以出面作证了。此外，莱斯科瓦尔的贵族身份及其广泛的政治关系使他实际上处于皇家卫队的常规司法权和正式的军情七处搜查令之外。"},{t="奶酪商的耳目",b="为了攻破暴风城贵族的防御，肖尔指派他的特工去找埃林·提亚斯，他是贸易区提亚斯奶酪店的老板。虽然他表面上只是一个以进口奶酪块和奶酪轮而闻名全城的喜怒无常的商人，但提亚斯经营着一个不亚于军情七处的独立耳目网络。肖尔很讨厌向他这位前同事求助，但要揭开暴风城要塞内部的叛国阴谋，需要采用非常规的皇家渠道手段。"}},faq={{q="为什么马迪亚斯·肖尔会派你去找一个奶酪商人？",a="埃林·提亚斯远不止是一个简单的奶酪商。虽然他在贸易区入口附近经营着提亚斯奶酪店，但他同时维持着一个触角伸向各处的独立地下情报网。肖尔很讨厌向他寻求帮助，但军情七处需要非常规手段来对付一个超脱于常规执法范围之外的贵族。",al={"为什么要找埃林·提亚斯","为什么要和提亚斯交谈","为什么是奶酪店"}},{q="为什么马迪亚斯·肖尔不能直接逮捕莱斯科瓦尔勋爵？",a="莱斯科瓦尔勋爵是暴风城的一位高级贵族，在贵族议会中关系根深蒂固。肖尔缺乏必要的证词，无法让证据在法律上对一位贵族生效。",al={"为什么不逮捕莱斯科瓦尔","为什么肖尔不能逮捕莱斯科瓦尔","为什么莱斯科瓦尔无法被触动"}},{q="谁是“静刃”马尔松？",a="“静刃”马尔松是一名致命的特工，与迪菲亚阴谋集团紧密合作，并在暴风城廷内与莱斯科瓦尔勋爵保持秘密通讯。",al={"谁是马尔松","静刃马尔松的角色"}},{q="为什么你和提亚斯交谈时，他会提到Deathwing？",a="当被告知涉及迪菲亚潜行者的阴谋时，提亚斯用尖刻的讽刺回应道，嘲讽你下一步是不是要告诉他，早已失踪的黑龙守护巨龙Deathwing还活着，并且正在袭击王国。",al={"为什么提亚斯提到deathwing","提亚斯的deathwing台词","deathwing袭击暴风城"}},{q="和埃林·提亚斯会面后会发生什么？",a="在听取了关于阴谋的全部叙述后，提亚斯开始策划一次对暴风城要塞的秘密潜入，以便在不惊动其余贵族廷臣的情况下将莱斯科瓦尔勋爵逼入绝境。",al={"提亚斯之后的下一个任务","“寻找老友”之后的去向"}},{q="埃林·提亚斯在哪里？",a="埃林·提亚斯可以在他的店铺“提亚斯奶酪店”内找到，该店位于暴风城的贸易区，就在从城市大门进入的主路旁。",al={"提亚斯的位置","提亚斯奶酪店在哪里"}}},fp="21,219,13.387.1,22.404.1,52.263.0,51.164.0,31.159.0,55.204.0,45.190.1,30.111.0"}
P.entries["quest:351"] = {n="寻找OOX-17/TN！",s="当你摆弄一个蛋形金属装置上的旋钮时，它突然启动了，里面传出了一个自称奥格索普的声音。奥格索普的寻回机器人失踪了，他请求你带着信标去找它。",h="当你摆弄一个蛋形金属装置上的旋钮时，它突然启动了，里面传出了一个自称奥格索普的声音。奥格索普的寻回机器人失踪了，他请求你带着信标去找它。",kw={"求救信标","大裂口","寻回机器人","机械鸡","奥格索普","oox-17/tn","塔纳利斯"},sec={{t="蛋里的声音",b="摆弄蛋形装置上的旋钮，它便展开成了一台侏儒机器人装置，里面传出了噼啪作响的声音。说话者自称是奥格索普，并说他的寻回机器人失踪了。奥格索普已经计算出了它坠毁的位置，就在塔纳利斯的大裂口附近，并请求你将信标送到机器人那里。"},{t="在坠毁现场",b="在坠毁现场，你发现那个寻回机器人其实是一只机械鸡。奥格索普说它必须先启动才能飞回藏宝海湾进行修理，于是你把信标放进了它体内。一阵嗡嗡声和机械运转声过后，机器人挣扎着站了起来，奥格索普的声音现在直接从机器人身上传了出来。它虽然能运作，但需要进行大修，而且太重了，你根本搬不动。"}},faq={{q="谁通过装置在与你联系？",a="蛋里传出的声音自称是奥格索普，并说他的寻回机器人失踪了。",al={"奥格索普是谁","谁通过蛋在说话"}},{q="寻回机器人在哪里坠毁了？",a="奥格索普计算出的坐标显示它在塔纳利斯的大裂口附近。",al={"机器人在哪里","oox-17/tn在哪里","我应该把信标带到哪里","大裂口机器人位置"}},{q="信标是做什么用的？",a="奥格索普请求你把信标带给失踪的寻回机器人。",al={"信标有什么用","蛋是什么","为什么要携带信标"}}},fp="15,245,20.337.0,17.382.1,41.97.0,33.74.0,23.68.0"}
P.entries["quest:3512"] = {n="帮助伊兰尼库斯",s="伊萨里奥斯希望找到一种方法，通过宝石与伊兰尼库斯交流。伊兰尼库斯处于生死之间，被困在梦魇编织的网中，而你给予的精华已被严重腐蚀，但仍有一线希望。伊萨里奥斯派你前往遥远的冬泉谷东部。",h="伊萨里奥斯希望找到一种方法，通过宝石与伊兰尼库斯交流。伊兰尼库斯处于生死之间，被困在梦魇编织的网中，而你给予的精华已被严重腐蚀，但仍有一线希望。伊萨里奥斯派你前往遥远的冬泉谷东部。",kw={"伊兰尼库斯","伊萨里奥斯","梦魇","灵语者","悲伤沼泽","阿姆布兰希","冬泉谷"},sec={{t="梦魇彼端的声音",b="伊萨里奥斯解释说，伊兰尼库斯处于生死之间，被扭曲的梦魇所纠缠。你给予的精华已被严重腐蚀，但仍有可能联系到他。为了通过宝石开启对话，伊萨里奥斯派你前往冰雪之地冬泉谷的东部，去寻找他们的一位凡人盟友。"},{t="灵语者",b="这位盟友就是灵语者阿姆布兰希，一个作为死者媒介的人类。伊兰尼库斯并未真正死亡，但伊萨里奥斯相信阿姆布兰希依然能提供帮助。"},{t="阿姆布兰希的条件",b="阿姆布兰希说伊萨里奥斯派你来是明智的，伊兰尼库斯很快就能亲自给出指引。目前，阿姆布兰希无法直接提供帮助。阿姆布兰希愿意运用他的通灵技巧，但首先需要一个不受年老体衰所困扰的人提供协助，因为阿姆布兰希保管的最强大的占卜装置违背了他的意愿被抢走了，没有它，就无法帮助伊兰尼库斯。"}},faq={{q="是谁派遣你踏上这段旅程的？",a="悲伤沼泽的伊萨里奥斯，在你交出伊兰尼库斯的腐蚀精华之后。",al={"谁给予了伊兰尼库斯本人的话任务","伊兰尼库斯任务发布者"}},{q="灵语者阿姆布兰希是谁？",a="一个充当死者媒介的人类，也是伊萨里奥斯的凡人盟友之一。他位于冬泉谷东部。",al={"阿姆布兰希是谁","灵语者阿姆布兰希背景故事"}},{q="伊兰尼库斯被认为已经死了吗？",a="并没有真正死亡。伊兰尼库斯处于生死之间，被困在梦魇编织的网中。",al={"伊兰尼库斯死了吗","伊兰尼库斯的存活状态"}},{q="这一步骤在剧情中处于什么位置？",a="它紧随“伊兰尼库斯的精华”任务的第二步之后，在那一步中，你将装有伊兰尼库斯残留自由意志的宝石交给了伊萨里奥斯。",al={"伊兰尼库斯任务线顺序","伊兰尼库斯本人的话之前发生了什么"}}},fp="22,271,28.312.0,17.164.0,20.402.1,30.88.0,34.115.0,28.97.0,42.135.0"}
P.entries["quest:3513"] = {n="符文卷轴",s="符文卷轴是一份在卡利姆多荒野中发现的、用银色丝带系着的奇异文档。其正式的外观表明这是一份来自边境另一侧暗夜精灵的军事或行政公文。发现它会将部落侦察兵直接引向莫尔杉壁垒，以警告卫兵注意北方的动向。",h="符文卷轴是一份在卡利姆多荒野中发现的、用银色丝带系着的奇异文档。其正式的外观表明这是一份来自边境另一侧暗夜精灵的军事或行政公文。发现它会将部落侦察兵直接引向莫尔杉壁垒，以警告卫兵注意北方的动向。",kw={"灰谷","部落边境","卡德拉克","莫尔杉壁垒","暗夜精灵的卷轴","符文卷轴","贫瘠之地"},ang={["faction:Horde"]="每一条截获的联盟情报都能保护伐木队和守卫通往灰谷门户的边境哨兵。",["race:Orc"]="战歌氏族向灰谷的扩张在很大程度上依赖于莫尔杉壁垒的边境防御，因此暗夜精灵的信件是非常重要的消息。"},sec={{t="一条银色丝带",b="这张卷轴用华丽的银色丝带紧紧缠绕，一眼就能看出它与贫瘠之地常用的粗糙皮革和羊皮纸格格不入。其精细的工艺和笔迹指向了正北方灰谷茂密树冠下的暗夜精灵。在这片每一条山脊和道路都充满争端的领土上，一封被截获的信件对部落的前线部队来说具有极高的战略价值。"},{t="关注北部边境",b="任何有战场直觉的冒险者都会意识到当地指挥部的紧迫性，而不是把卷轴穿过平原送到奥格瑞玛的大酋长手中。在莫尔杉壁垒，就在贫瘠之地的红色泥土向灰谷郁郁葱葱的森林过渡的地方，兽人战士卡德拉克一直监视着边境的入侵行动。将这张卷轴交给这里，能为壁垒的前哨站提供有关暗夜精灵部队调动的重要情报。"}},faq={{q="什么是符文卷轴？",a="这是一份用银色丝带系着的制作精美的正式文档，表明其源自暗夜精灵。它包含了关于他们在贫瘠之地边境的动向或计划的情报。",al={"这个卷轴是什么","符文卷轴背景","银丝带卷轴"}},{q="我应该把卷轴带到哪里？",a="这张卷轴必须被带到莫尔杉壁垒的北部边境岗哨，卡德拉克在那里监视着贫瘠之地与灰谷之间的活动。",al={"在哪里上交符文卷轴","上交卷轴","谁需要这个卷轴"}},{q="卡德拉克是谁？",a="卡德拉克是一名部落侦察兵兼卫兵，驻守在莫尔杉壁垒的一座防御塔上，负责调查来自灰谷的边境威胁。",al={"卡德拉克","塔楼上的兽人"}},{q="为什么暗夜精灵会在贫瘠之地丢下卷轴？",a="暗夜精灵哨兵和侦察兵会定期巡逻灰谷的边境和边缘地带，偶尔会向南推进，以试探部落的防御或伏击前往北方的补给线。",al={"为什么卷轴会在这里","贫瘠之地里的暗夜精灵"}},{q="把卷轴交给卡德拉克后会发生什么？",a="在查看卷轴后，卡德拉克认定其作者是猛禽洞穴的钥匙保管者——树妖林莎瑞尔，并会派你去石爪峰杀死她，并在洞穴里插上一面部落旗帜。",al={"部落存在任务","what comes next"}},{q="为什么这张卷轴对部落很重要？",a="部落与暗夜精灵之间因伐木和边境问题而一直摩擦不断。任何截获的通信都能为莫尔杉壁垒提供防范联盟伏击的预警。",al={"符文卷轴的重要性","部落对卷轴的兴趣"}}},fp="16,208,16.308.0,27.293.0,25.194.0,31.110.0,14.126.0,55.156.0,47.183.0,40.166.0"}
P.entries["quest:3514"] = {n="部落的示威",s="“部落的威慑”是由兽人卡德拉克在贫瘠之地与灰谷边界发动的一次军事打击。在截获了一份信件后，部落派遣一名勇士深入石爪峰，击杀树妖琳萨瑞尔，并将部落旗帜插在猛禽洞穴深处。",h="“部落的威慑”是由兽人卡德拉克在贫瘠之地与灰谷边界发动的一次军事打击。在截获了一份信件后，部落派遣一名勇士深入石爪峰，击杀树妖琳萨瑞尔，并将部落旗帜插在猛禽洞穴深处。",kw={"贫瘠之地","树妖","部落的威慑","卡德拉克","卡德拉克的旗子","琳萨瑞尔","石爪峰","猛禽洞穴","符文卷轴"},ang={["class:Druid"]="对于部落的德鲁伊来说，进军石爪峰去击杀一位塞纳留斯之女的树妖，这体现了阵营忠诚与神圣自然纽带之间痛苦的政治张力。",["faction:Horde"]="保卫贫瘠之地的北部边境对于维持对卡利姆多中部平原的控制，以及保护初生的定居点免受暗夜精灵的侵入至关重要。",["race:Orc"]="兽人们认为卡德拉克的果断攻势是应对领土入侵的唯一合适手段，这展现了力量，而不是给联盟留下任何机动的空间。"},sec={{t="截获的信件",b="卡德拉克守卫着贫瘠之地的北部边界，时刻警惕着联盟和暗夜精灵的入侵。当一名携带符文卷轴的信使被杀后，卡德拉克破译了其中的信息，并查明其源头是驻扎在石爪峰的一位重要树妖：钥匙保管者琳萨瑞尔。卡德拉克没有选择单纯地防守山口，而是采取了强硬的手段，以震慑未来任何试图窥探部落领地的侦察兵。"},{t="洞穴中的反抗",b="这项任务派遣部落战士深入猛禽洞穴，这是一座俯瞰着石爪峰的洞穴要塞。击杀琳萨瑞尔是对当地暗夜精灵协同作战的一次直接打击，而随后的行动则是将卡德拉克的部落旗帜插在洞穴内。通过将他们红色的战旗留在树妖领地的腹地，部落旨在发出明确的信号：任何对贫瘠之地的侵入都将遭到果断的暴力回击。"}},faq={{q="卡德拉克是谁，他为什么要下令进行这次打击？",a="卡德拉克是一位驻扎在贫瘠之地与灰谷之间北部前哨站的兽人战士。为了保护部落土地免受外敌入侵，当他发现有联盟信使穿过附近的山口时，便下令发动了先发制人的报复行动。",al={"卡德拉克","卡德拉克是谁","卡德拉克的目的"}},{q="钥匙保管者琳萨瑞尔是谁？",a="琳萨瑞尔是一位居住在石爪峰顶猛禽洞穴中的树妖首领。正是她写下了被截获信使所携带的那份符文卷轴，协调着联盟和哨兵在山间走廊的行动。",al={"琳萨瑞尔","钥匙保管者琳萨瑞尔","猛禽洞穴首领"}},{q="猛禽洞穴位于哪里？",a="猛禽洞穴是一个位于石爪峰西坡的地下洞穴群，坐落在石爪山脉的高处。",al={"猛禽洞穴位置","猛禽洞穴在哪里","琳萨瑞尔位置"}},{q="插上卡德拉克的旗帜有什么目的？",a="插上旗帜是一种心理警告。卡德拉克要让暗夜精灵和联盟看到那面红色的部落旗帜高悬在他们倒下的领袖之上，确保他们在派遣侦察兵穿过贫瘠之地时会有所顾忌。",al={"为什么要插旗","卡德拉克的旗子","部落旗帜的目的"}},{q="这个任务与“符文卷轴”有什么关联？",a="“部落的威慑”是“符文卷轴”的直接后续。玩家只有在从联盟信使身上发现被截获的羊皮纸并将其交给卡德拉克破译后，才能解锁该任务。",al={"与符文卷轴的联系","前置任务","部落的威慑前置条件"}},{q="为什么部落会担心联盟信使出现在贫瘠之地？",a="贫瘠之地是连接奥格瑞玛、雷霆崖以及周边定居点的重要心脏地带。允许联盟信使和暗夜精灵盟友在山间的缺口处畅通无阻，将会威胁到部落的补给线和边境安全。",al={"贫瘠之地中的联盟","为什么要与树妖作战","贫瘠之地威胁"}}},fp="14,197,21.377.0,19.309.0,48.253.0,32.209.0,31.122.0,46.192.0,50.172.0,65.201.0"}
P.entries["quest:3519"] = {n="需要帮助的朋友",s="“患难之友”是来自埃沃隆的紧急求援。这位年轻的暗夜精灵在幽影谷不幸被毒蜘蛛咬伤。他被致命的野兽Githyiss the Vile击倒，并派遣旅者前去寻找迪兰妮亚·月光，希望能赶在毒性发作前救他一命。",h="“患难之友”是来自埃沃隆的紧急求援。这位年轻的暗夜精灵在幽影谷不幸被毒蜘蛛咬伤。他被致命的野兽Githyiss the Vile击倒，并派遣旅者前去寻找迪兰妮亚·月光，希望能赶在毒性发作前救他一命。",kw={"奥达希尔","迪兰妮亚·月光","吉希斯","埃沃隆","毒素","幽影谷","蜘蛛","泰达希尔"},ang={["class:Druid"]="德鲁伊很早就了解到，当地野生动物的失衡会击倒那些不慎者，这强调了了解并应对自然界毒素的紧迫性。",["race:NightElf"]="对于在奥达希尔下开始训练的年轻卡多雷来说，埃沃隆的困境是一个严峻的提醒：即便是受到庇护的幽影谷枝叶，也不再能免受腐蚀和致命危险的侵袭。"},sec={{t="“鲁莽的冒险”",b="幽影谷茂密的树冠庇护着各式各样的野生动物，但附近的蛛网空洞中却潜藏着更可怕的威胁。埃沃隆无视了此前的警告，冒险太靠近当地的蛛木洞穴，并遭遇了Githyiss the Vile，这只凶残的蜘蛛用毒液迅速击倒了这位年轻的精灵。他头晕目眩，体力衰竭，已完全无法独自前往安全地带。"},{t="“呼唤奥达希尔”",b="为了生存，埃沃隆恳求任何路人赶快回到中心之树奥达希尔，向迪兰妮亚·月光发出警报。迪兰妮亚习惯于照看他，并且熟悉这片山谷的危险，她是他在毒素致命前配制出救命解药的唯一希望。"}},faq={{q="埃沃隆是谁？",a="埃沃隆是一位生活在泰达希尔幽影谷的年轻暗夜精灵。尽管同伴们多次警告，他仍经常徘徊在危险地带，这导致他与Githyiss the Vile发生了险些致命的遭遇。",al={"埃沃隆背景故事","被毒倒的精灵是谁","患难之友的任务发布者"}},{q="是什么袭击了埃沃隆？",a="他被Githyiss the Vile咬伤了，这是一只潜伏在幽影谷蛛洞内、臭名昭著且剧毒无比的蜘蛛。",al={"咬伤埃沃隆的是什么","吉希斯是谁","是哪只蜘蛛让他中毒"}},{q="迪兰妮亚·月光是谁？",a="迪兰妮亚·月光是一位居住在幽影谷奥达希尔的暗夜精灵。她是埃沃隆的好友兼监护人，懂得如何治疗毒伤。",al={"迪兰妮亚的角色","关于埃沃隆该找谁"}},{q="这个任务发生在什么地方？",a="该任务完全发生在幽影谷内，这是坐落在泰达希尔树冠高处、受庇护的暗夜精灵新手谷地。",al={"患难之友的位置","埃沃隆的位置"}},{q="向迪兰妮亚汇报埃沃隆的情况后会发生什么？",a="迪兰妮亚会立即着手准备治疗药物，并派遣冒险者在林地四处搜集酿制解药所需的珍稀试剂，以赶在埃沃隆毒发身亡前救治他。",al={"患难之友后的任务","埃沃隆会被救吗"}},{q="为什么幽影谷里会有致命的蜘蛛？",a="虽然幽影谷被认为是年轻暗夜精灵的安全避风港，但蔓延在泰达希尔上的腐蚀已经使野兽和蛛木蜘蛛等害虫变得异常好斗且具有剧毒。",al={"幽影谷为何有蜘蛛","泰达希尔的蜘蛛腐蚀"}}},fp="16,155,18.221.0,19.223.0,15.182.0,22.100.0,27.165.0,33.105.0,60.180.1,47.194.0"}
P.entries["quest:3520"] = {n="尖啸者的灵魂",s="位于热砂港的叶基亚需要你从菲拉斯的丛林尖啸者身上获取灵魂，这些生物与一位古神有着亲缘关系。你将带着荆棘魔棒前往菲拉斯的中部和南部，叶基亚承诺当你归来时，会向你透露更多关于那位古神的信息。",h="位于热砂港的叶基亚需要你从菲拉斯的丛林尖啸者身上获取灵魂，这些生物与一位古神有着亲缘关系。你将带着荆棘魔棒前往菲拉斯的中部和南部，叶基亚承诺当你归来时，会向你透露更多关于那位古神的信息。",kw={"荆棘魔棒","菲拉斯","尖啸者灵魂","热砂港","塔纳利斯","丛林尖啸者","叶基亚"},sec={{t="菲拉斯的灵魂",b="叶基亚称菲拉斯的丛林尖啸者与一位古神有着亲缘关系，且它们的灵魂与那位古神紧密相连。他交给你一根荆棘魔棒，并将你派往菲拉斯的中部和南部。在倒下的丛林尖啸者身上挥舞荆棘魔棒可以诱出它们的灵魂，触碰灵魂即可收集其精华。你需要收集三个灵魂，并将魔棒和精华带回给叶基亚。"},{t="叶基亚的讲述",b="叶基亚指明那位古神就是哈卡，即夺魂者，它是远古巨魔预言中那位预示着重返世界的死亡之神。对此人们意见不一：有人期待巨魔将迎来荣耀与喜悦，也有人认为那意味着世界末日。叶基亚并不笃信这些神话，但他深知哈卡的精华力量强大，绝不能落入坏人之手。"}},faq={{q="谁发布了这个任务，他在哪里？",a="叶基亚，位于热砂港。",al={"谁发布尖啸者灵魂任务","叶基亚位置","叶基亚在哪里"}},{q="丛林尖啸者在哪里？",a="在菲拉斯的中部和南部。",al={"哪里寻找尖啸者","尖啸者位置","菲拉斯的尖啸者在哪里"}},{q="如何捕捉尖啸者的灵魂？",a="在倒下的丛林尖啸者身上挥舞叶基亚的荆棘魔棒，即可诱出它们的灵魂。触碰灵魂即可收集其精华。",al={"如何获得尖啸者灵魂","使用叶基亚的荆棘魔棒","荆棘魔棒"}},{q="为什么叶基亚需要尖啸者的灵魂？",a="叶基亚声称丛林尖啸者与一位古神有亲缘关系，它们的灵魂与那位古神相连。当你归来时，叶基亚会告诉你更多关于那位古神的事情。",al={"为什么收集尖啸者灵魂","叶基亚的目的"}}},fp="17,241,18.383.0,21.337.1,40.32.0,30.32.0,41.128.0,42.160.0"}
P.entries["quest:3521"] = {n="埃沃隆的解药",s="埃沃隆的解毒剂是幽影谷一项紧急的任务，旨在拯救一名中毒的暗夜精灵侦察兵。通过收集野生蘑菇、百合花和蜘蛛脓液，冒险者们帮助迪兰妮亚·月光在毒液完全发作前调制出一剂解药。",h="埃沃隆的解毒剂是幽影谷一项紧急的任务，旨在拯救一名中毒的暗夜精灵侦察兵。通过收集野生蘑菇、百合花和蜘蛛脓液，冒险者们帮助迪兰妮亚·月光在毒液完全发作前调制出一剂解药。",kw={"奥达希尔","解毒剂","迪兰妮亚·月光","紫蓝色蘑菇","埃沃隆","月牙百合花","幽影谷","黑丝洞","树林蜘蛛的脓液"},ang={["class:Druid"]="利用当地植物制作药剂并中和天然毒素，反映了德鲁伊在野外努力维持的基本平衡。",["profession:Herbalism"]="采集月牙百合花和紫蓝色蘑菇展示了泰达希尔的野生植物在精心处理后所具有的强大药用价值。",["race:NightElf"]="照顾倒下的族人是幽影谷的神圣职责，每一位防御者都是保护这棵新生的世界之树所必需的。"},sec={{t="与毒液的赛跑",b="年轻的埃沃隆在幽影谷的树枝间侦察时，不幸被当地的蛛网林蜘蛛毒牙咬伤。他倒地不起，生命垂危，能否活下来完全取决于奥达希尔的迪兰妮亚·月光所掌握的草药知识。由于这名年轻人的生命正在迅速流逝，她必须尽快准备一种特殊的混合剂，以中和在他血液中肆虐的剧毒。"},{t="幽影谷的试剂",b="迪兰妮亚的配方依赖泰达希尔的修复性植物，并与毒液本身形成平衡。紫蓝色蘑菇——一种南部的格雷尔小鬼所贪婪的植物——提供了土质基底，而从宁静的森林水池中采摘的娇嫩月牙百合花则具有净化特性。为了完成配方，必须从潜伏在黑丝洞附近的蜘蛛身上直接提取样本，即树林蜘蛛的脓液，以便针对它们特有的毒素来定制解药。"}},faq={{q="谁是埃沃隆？",a="埃沃隆是幽影谷的一名年轻暗夜精灵，他不慎靠得太近，遭到了敌对的蛛网林蜘蛛袭击，并被它们致命的毒液击倒。",al={"埃沃隆","谁是埃沃隆","谁中了毒"}},{q="谁发布了“埃沃隆的解毒剂”这个任务？",a="迪兰妮亚·月光，一位驻守在幽影谷奥达希尔大树枝外的侍从，负责发布任务并调制解药。",al={"任务发布者","迪兰妮亚","迪兰妮亚·月光"}},{q="为什么解毒剂需要树林蜘蛛的脓液？",a="在传统的草药疗法中，引入生物自身的体液或毒液成分有助于抵消导致受害者中毒的特定毒素。",al={"为什么需要蜘蛛脓液","树林蜘蛛的脓液用途","蜘蛛毒液治疗"}},{q="在哪里可以找到紫蓝色蘑菇？",a="紫蓝色蘑菇生长在幽影谷各地大树的根部，也可以从南部囤积它们的格雷尔小鬼手中抢夺而来。",al={"在哪里寻找紫蓝色蘑菇","紫蓝色蘑菇位置"}},{q="月牙百合花生长在哪里？",a="月牙百合花开放在奥达希尔西北侧僻静的淡水池边缘。",al={"月牙百合花位置","百合花在哪里"}},{q="蛛网林蜘蛛位于何处？",a="蛛网林蜘蛛栖息在幽影谷的北部森林中，尤其是在黑丝洞阴暗的入口附近。",al={"蛛网林蜘蛛位置","幽影谷蜘蛛位置"}}},fx={["77bb41e6"]={q="迪兰妮亚·月光为什么要你办这件事？",a="迪兰妮亚知道如何调制解药，化解埃沃隆体内流窜的致命毒素。若不尽快救治，他的情况就会恶化。她指望你迅速收集所需的森林材料，赶在为时已晚之前救下他。",al={"迪兰妮亚·月光的动机","为什么要救埃沃隆","为什么要制作解毒剂"}},d7eaa833={q="紫蓝色蘑菇有什么用途？",a="紫蓝色蘑菇是幽影谷大树枝干下生长的本地真菌。迪兰妮亚将它们用作调制解毒剂的主要草药成分，以中和较烈的毒液，并化解侵入埃沃隆体内的毒素。",al={"紫蓝色蘑菇的用途","为什么要紫蓝色蘑菇","紫蓝色蘑菇的背景"}},ece05283={q="月牙百合花有什么用途？",a="月牙百合花是娇嫩的水生花朵，生长在幽影谷宁静的林间池塘旁。迪兰妮亚将它们加入药剂，利用其天然的舒缓功效来对抗剧烈的蜘蛛毒液。",al={"月牙百合花的用途","为什么要月牙百合花","月牙百合花的背景"}}},fp="18,171,20.278.0,22.331.0,15.136.0,39.126.0,40.186.0,35.157.0,31.98.0,38.109.0"}
P.entries["quest:3522"] = {n="埃沃隆的解药",s="这个任务需要冒险者争分夺秒，将刚配好的药剂送到一名中毒的暗夜精灵斥候手中。埃沃隆被困在幽影谷一处蜘蛛出没的洞穴外，他能否获救，完全取决于迪兰妮亚·月光调制的草药药剂是否能在药效失效前送达。",h="这个任务需要冒险者争分夺秒，将刚配好的药剂送到一名中毒的暗夜精灵斥候手中。埃沃隆被困在幽影谷一处蜘蛛出没的洞穴外，他能否获救，完全取决于迪兰妮亚·月光调制的草药药剂是否能在药效失效前送达。",kw={"解毒剂","迪兰妮亚·月光","埃沃隆","幽影谷","泰达希尔","毒液","织木蜘蛛"},ang={["profession:Herbalism"]="药剂的不稳定性质展示了使用原始森林植物所带来的挑战，如果缺乏适当的保存，植物药剂几乎会立刻失去其重要的属性。",["race:NightElf"]="对于在幽影谷接受训练的年轻暗夜精灵来说，营救埃沃隆是一个严峻的提醒，让他们意识到泰达希尔本地野生生物中日益增长的腐蚀和侵略性。"},sec={{t="与时间赛跑",b="迪兰妮亚·月光使用刚采集的毒囊、百合根和风信子真菌调制这种疗伤药剂，但由于其炼金性质不稳定，具有很大的风险。药剂在蒸馏后只能保持五分钟的药效。任何持有药剂瓶的人都必须立即动身，从林地径直冲向北面的高地，绝不能犹豫。"},{t="惯常惹祸",b="埃沃隆被潜伏在幽影谷兽穴和洞穴周围的织木蜘蛛所伤。正如他自己承认的那样，他总是不小心陷入危险，经常依赖迪兰妮亚的草药知识来让他脱离险境。即使在喝下解毒剂后，他的身体依然十分虚弱，令他不得不提防那些仍在阻挡他回家之路的敌对蛛类。"}},faq={{q="为什么解毒剂会有时间限制？",a="迪兰妮亚·月光调制的解毒剂依赖于原始的天然成分和新鲜毒液。其有效的治疗属性在制备后会迅速退化，如果不能在离开她照顾后的五分钟内服用，就会完全失效。",al={"为什么是五分钟","解毒剂计时器","限时任务"}},{q="埃沃隆在哪里？",a="埃沃隆瘫倒在幽影谷北侧洞穴外的岩石边，位于穿过树林的主路以北。",al={"埃沃隆在哪里","埃沃隆位置","找到埃沃隆"}},{q="埃沃隆是怎么中毒的？",a="他被栖息在幽影谷北部边缘的剧毒织木蜘蛛咬伤了，这种极具侵略性的物种在泰达希尔的树根和洞穴周围大量繁殖。",al={"谁毒害了埃沃隆","为什么埃沃隆生病了","埃沃隆中毒"}},{q="埃沃隆喝下解毒剂后会发生什么？",a="虽然毒素被中和了，但埃沃隆仍然过于虚弱和惊恐，无法独自安全旅行，因此他请求帮助清理附近阻挡他返回安全地带的织木蜘蛛。",al={"埃沃隆接下来做什么","埃沃隆服用解毒剂后","埃沃隆后续"}},{q="迪兰妮亚和埃沃隆是什么关系？",a="迪兰妮亚·月光是幽影谷的一位能干的草药师和治疗者，经常将埃沃隆从他的冒险中解救出来。埃沃隆公开承认惹麻烦是他的天性，而迪兰妮亚总是为他收拾烂摊子。",al={"迪兰妮亚和埃沃隆","迪兰妮亚对埃沃隆的意义","他们是朋友吗"}},{q="如果解毒剂在送到他手中之前过期了会怎样？",a="如果这种不稳定的药剂在送达前变质，任务就无法完成。你必须回到幽影谷的迪兰妮亚·月光那里获取新鲜的药剂，重新跑一趟。",al={"解毒剂过期","计时失败","丢失解毒剂"}}},fp="18,198,24.283.0,18.317.0,53.210.0,25.104.0,25.143.0,47.188.1,46.188.0,57.135.0"}
P.entries["quest:3524"] = {n="搁浅的巨兽",s="“冲上岸的遗骸”是一项由温尼斯·布莱葛在奥伯丁发起的调查，代表了Temple of the Moon的利益。黑海岸沿岸发生的大规模巨型海洋生物搁浅事件，引起了达纳苏斯的暗夜精灵祭司阶层的警觉。冒险者们受命驱逐四处搜刮的鱼人，以获取骸骨样本供研究之用。",h="“冲上岸的遗骸”是一项由温尼斯·布莱葛在奥伯丁发起的调查，代表了Temple of the...",kw={"奥伯丁","黑海岸","达纳苏斯","灰雾鱼人","温尼斯·布莱葛","海洋生物的骸骨","temple of the moon","冲上岸的遗骸"},ang={["class:Druid"]="高贵的海洋生物大规模死亡是卡利姆多海岸生态失调的警示信号，需要密切关注。",["class:Priest"]="为The Sisterhood of Elune服务意味着解读精神预兆和自然失衡，这正是温尼斯试图从海洋生物遗骸中破译的内容。",["race:NightElf"]="海岸搁浅事件扰乱了黑海岸微妙的平衡，促使The Sisterhood of Elune直接从达纳苏斯进行干预。"},sec={{t="令人不安的预兆",b="人们早已知道，深海中那些巨大而庄严的生物偶尔会搁浅在黑海岸多雾的浅滩上。然而最近，它们的死亡已不再是悲剧性的异常事件，而演变成了一种不断升级的模式。大量的利维坦巨兽被冲上岸边。对于居住在Temple of the Moon的Elune祭司们来说，这种毫无征兆的大规模搁浅事件不仅被视为一种自然怪象，更被视为威胁北卡利姆多的潜在凶兆。"},{t="浅滩的拾荒者",b="为了弄清这些巨兽为何会冲上沙滩，学者温尼斯·布莱葛被派往奥伯丁港口。她的任务是收集生物样本，并通过角鹰兽运往达纳苏斯进行仔细检查。然而，盘踞在冲浪线上的灰雾鱼人成群结队地占据了这些巨大的尸体，疯狂地搜刮残骸，使得实地研究人员在没有武装保护的情况下无法接近骸骨。"}},faq={{q="为什么巨型海洋生物会冲上黑海岸？",a="确切原因仍在Temple of the Moon的积极调查中。虽然偶尔的搁浅是自然现象，但频率的突然激增让暗夜精灵学者们确信，无尽之海的波涛之下潜藏着更深层的动乱或凶兆。",al={"为什么生物搁浅","海洋生物搁浅","垂死的海洋巨兽"}},{q="温尼斯·布莱葛是谁？",a="温尼斯·布莱葛是一位由Temple of the Moon从达纳苏斯派出的调查员。她驻扎在奥伯丁，负责记录沿海异常现象，并从搁浅的利维坦巨兽身上收集实体样本，送回祭司阶层进行分析。",al={"温尼斯","温尼斯·布莱葛是谁"}},{q="奥伯丁南部的生物躺在哪里？",a="骸骨遗骸位于奥伯丁码头以南不远处的海岸线上。这具巨大的尸体横卧在浪潮中，周围被充满敌意的灰雾鱼人包围并守卫着。",al={"生物位置","海洋生物骸骨位置","搁浅的巨兽在哪里"}},{q="达纳苏斯将如何处理这些海洋生物的骸骨？",a="骸骨通过角鹰兽直接运往达纳苏斯。Temple of the Moon的学者和祭司们会研究骨髓、结构和腐烂迹象，以查明是否是疾病、邪恶魔法或非自然的捕食行为导致该生物搁浅。",al={"为什么要收集骸骨","海洋生物骸骨的用途","达纳苏斯骸骨"}},{q="为什么灰雾鱼人聚集在尸体周围？",a="灰雾部落将搁浅的巨兽视为一种唾手可得的食物、工具和骨制工艺品来源。他们对尸体的领地宣示使得手无寸铁的学者们无法在不冒生命危险的情况下靠近。",al={"鲸鱼处的鱼人","为什么鱼人围着生物"}},{q="这项调查在取回第一批骸骨后就结束了吗？",a="没有。镇南边的尸体只是第一个地点。温尼斯继续她的研究，对黑海岸广阔且雾气笼罩的海岸线上其他死亡的搁浅利维坦进行更深入的调查。",al={"这是一个系列任务吗","冲上岸的遗骸后续"}}},fp="13,240,17.328.0,26.368.0,52.249.0,29.220.0,47.152.0,51.234.0,57.177.0,73.185.0"}
P.entries["quest:353"] = {n="雷矛的包裹",s="在Dwarven District完成工作后，铁匠格里曼德·艾尔莫将一把刚锻造好的斧头托付给旅行者，这把斧头是给巡山人卡尔·雷矛的。运送这个包裹需要穿越北方的群山，前往洛克莫丹的一处铁炉堡哨所。",h="在Dwarven District完成工作后，铁匠格里曼德·艾尔莫将一把刚锻造好的斧头托付给旅行者，这把斧头是给巡山人卡尔·雷矛的。运送这个包裹需要穿越北方的群山，前往洛克莫丹的一处铁炉堡哨所。",kw={"斧头","艾尔莫","格里曼德","卡尔","哨塔","洛克莫丹","巡山人","雷矛"},ang={["faction:Alliance"]="在暴风城和山地哨所之间运送军事物资，展现了人类与矮人之间紧密相连的务实团结。",["profession:Blacksmithing"]="格里曼德·艾尔莫的作品代表了精湛的矮人冶金工艺，其价值之高，以至于山地守卫不惜跨越整个王国来预订他的作品。",["race:Dwarf"]="雷矛氏族在矮人同胞中享有崇高的荣誉，在洛克莫丹荒凉的边境援助一位巡山人兄弟，加深了氏族间的情谊。"},sec={{t="北方之兵",b="雷矛氏族是铁炉堡最受尊崇的氏族之一，以其敏锐的鉴赏力和尚武精神而闻名。当巡山人卡尔·雷矛需要一把新武器来执行巡逻任务时，他找到了位于暴风城Dwarven District的著名铁匠格里曼德·艾尔莫。随着斧头的完成，艾尔莫转向值得信赖的旅行者，委托他们将包裹向北运送，以此架起连接人类首都与矮人边境的桥梁。"},{t="洛克莫丹的守卫",b="巡山人卡尔·雷矛驻扎在洛克莫丹的北部哨塔，守卫着这片深受穴居人流寇和钻地狗头人袭扰的土地。虽然南部人类王国的动荡与匪患传闻不断，但矮人边境也面临着顽固的威胁。收到这把刚淬火的利刃，让卡尔·雷矛拥有了守卫山口所需的优势。"}},faq={{q="谁是巡山人卡尔·雷矛？",a="卡尔·雷矛是一位隶属于受人尊崇的雷矛氏族的铁炉堡巡山人。他目前驻扎在洛克莫丹的北部哨塔，负责防御山谷道路，抵御穴居人的入侵和当地的威胁。",al={"卡尔·雷矛","谁是雷矛","巡山人卡尔·雷矛"}},{q="包裹里装的是什么？",a="包裹里装着一把由暴风城的格里曼德·艾尔莫定制的矮人斧头。巡山人卡尔·雷矛订制这把利刃是为了对付那些入侵洛克莫丹的穴居人和狗头人。",al={"我正在运送什么","雷矛的包裹内容","格里曼德·艾尔莫的武器"}},{q="我该去哪里运送包裹？",a="巡山人卡尔·雷矛驻扎在洛克莫丹的北部哨塔，就在通往北部山区边界的丘陵道路旁。",al={"雷矛在哪里","如何找到巡山人卡尔·雷矛","洛克莫丹哨塔位置"}},{q="为什么洛克莫丹的矮人要从暴风城购买武器？",a="格里曼德·艾尔莫是一位居住在暴风城Dwarven District的高超矮人武器锻造师。雷矛氏族非常看重精良的冶金工艺，尽管路途遥远，卡尔还是特意委托艾尔莫打造了他定制的斧头。",al={"为什么从暴风城购买","为什么是艾尔莫","矮人向人类城市订货"}},{q="这和艾尔莫的任务有什么联系？",a="这次运送直接延续了艾尔莫的任务，是格里曼德·艾尔莫向愿意往返于暴风城和卡兹莫丹等联盟领地之间的冒险者寻求的下一个帮助。",al={"艾尔莫任务线","雷矛的交付任务之前是什么任务","如何开始这个任务"}},{q="旅行者如何从暴风城前往洛克莫丹？",a="旅行者通常会在暴风城的Dwarven District搭乘矿道地铁前往铁炉堡。从铁炉堡的大门出发，东部公路蜿蜒向下，穿过丹莫罗的雪山山口，经过北门小径，最后到达洛克莫丹山谷。",al={"如何前往洛克莫丹","前往卡兹莫丹","矿道地铁去洛克莫丹"}}},fp="20,171,22.290.0,22.315.0,29.189.0,27.152.0,31.151.0,58.192.0,39.123.0,49.189.0"}
P.entries["quest:354"] = {n="阿加曼德家族",s="库勒曼·法席恩，一位曾在此磨坊工作、现居住于布瑞尔的工人，正寻求向贵族阿加曼德家族复仇。在第三次战争期间，法席恩和他的工友们听信了阿加曼德家族的劝说，留下保卫庄园免受天灾军团的侵害。然而，他们与那些固执的雇主一同丧生，而阿加曼德家族的成员随后竟被转化为了巫妖王麾下毫无思想的爪牙。",h="库勒曼·法席恩，一位曾在此磨坊工作、现居住于布瑞尔的工人，正寻求向贵族阿加曼德家族复仇。在第三次战争期间，法席恩和他的工友们听信了阿加曼德家族的劝说，留下保卫庄园免受天灾军团的侵害。然而，他们与那些固执的雇主一同丧生，而...",kw={"阿加曼德","阿加曼德磨坊","布瑞尔","库勒曼·法席恩","家族的死亡","格雷戈尔·阿加曼德","尼莎·阿加曼德","天灾军团","瑟曼·阿加曼德","提瑞斯法林地"},ang={["faction:Horde"]="铲除阿加曼德家族的首领，可以清除那些潜伏在布瑞尔及幽暗城北部入口附近、令人不安的天灾军团指挥官。",["race:Undead"]="这项任务反映了许多被遗忘者对自己凡人时期所承受的深刻个人积怨，展现了洛丹伦陷落所带来的持续创伤，以及对那些将他们推向毁灭之人的怨恨。"},sec={{t="傲慢的遗产",b="在第三次战争摧毁洛丹伦之前，阿加曼德家族是提瑞斯法林地最富有、最具影响力的农业世家。他们广阔的磨坊和肥沃的牧场盛产粮食，雇佣了数十名佃农和磨坊工人。当亡灵天灾在王国肆虐时，阿加曼德家族拒绝逃离或放弃他们的祖产，坚信坚固的石墙和忠诚的工人足以抵御从东方逼近的恐怖灾难。"},{t="忠诚的代价",b="出于对雇主承诺的信任，像库勒曼·法席恩这样忠诚的雇员坚守岗位，保卫庄园。但事实证明，这种防御在天灾军团无情的攻势面前毫无作用。阿加曼德家族及其雇员惨遭屠戮，尸体倒在原地腐烂，随后被转化为了亡灵。虽然法席恩最终通过Sylvanas Windrunner的解放获得了自由，但阿加曼德家族的家长和继承人们却仍被困在巫妖王的精神控制之下，作为毫无意识的天灾哨兵徘徊在废弃的磨坊中。"},{t="痛苦的报复",b="如今住在布瑞尔的库勒曼·法席恩，对那些曾因傲慢而导致他凡人生命终结的旧主人怀有深切的怨恨。为了寻求了结与复仇，他派遣被遗忘者勇士前往阿加曼德磨坊，消灭格雷戈尔、尼莎和瑟曼·阿加曼德。法席恩公开表示，他希望这些旧主人在腐烂的面容之下，还能保留足够的意识，以便在生命彻底终结时感受到恐惧。"}},faq={{q="阿加曼德家族是谁？",a="在洛丹伦陷落之前，阿加曼德家族是提瑞斯法林地最富有、最繁荣的土地所有者家族。他们拥有并经营着庞大的阿加曼德磨坊，雇佣了当地众多的农民和磨坊工人。",al={"阿加曼德家族是谁","阿加曼德背景故事","阿加曼德磨坊历史"}},{q="库勒曼·法席恩为何如此憎恨他们？",a="法席恩生前在他们的磨坊工作。当亡灵天灾降临时，阿加曼德家族说服工人们留下来加固庄园，而不是逃离。法席恩认为，正是他们那种贵族的傲慢，直接导致了他和同伴们的死亡并沦为亡灵。",al={"库勒曼·法席恩的积怨","法席恩为何憎恨阿加曼德家族","法席恩的动机"}},{q="阿加曼德家族加入被遗忘者了吗？",a="没有。与库勒曼·法席恩和其他拥有自由意志的被遗忘者不同，阿加曼德家族从未摆脱巫妖王的控制。他们依然是毫无意识的天灾爪牙，在破败的家族磨坊中游荡。",al={"阿加曼德家族是被遗忘者吗","为何阿加曼德家族是天灾","谁控制着阿加曼德家族"}},{q="需要消灭哪些阿加曼德家族成员？",a="任务要求你搜寻格雷戈尔·阿加曼德、尼莎·阿加曼德和瑟曼·阿加曼德，并从家族庄园收集他们的遗骸，以确认他们已被消灭。",al={"需要击杀谁","阿加曼德目标","哪几个阿加曼德"}},{q="阿加曼德磨坊位于何处？",a="阿加曼德磨坊位于提瑞斯法林地的北部，布瑞尔的西北方。这片曾经肥沃的庄园如今只剩下几座被天灾军团占据的破败风车和农舍。",al={"阿加曼德磨坊在哪里","阿加曼德位置"}},{q="库勒曼·法席恩要怎么处理他们的遗骸？",a="库勒曼索要他们的遗骸纯粹是为了确认他们已被消灭。这些战利品代表了他凡世积怨的了结，也证明了那些曾经让他陷入绝境的傲慢领主们已被彻底终结。",al={"为何收集遗骸","法席恩遗骸"}}},fp="20,279,17.418.0,20.431.0,18.353.0,27.190.0,41.248.0,35.178.0,47.152.0,32.156.0,49.166.0"}
P.entries["quest:355"] = {n="与塞弗伦交谈",s="在解决库勒曼·法席恩于阿加曼德磨坊的私人恩怨后，执政官塞弗伦召集冒险者前往布瑞尔。磨坊里不仅仅有痛苦的家族亡魂，它还代表着布瑞尔北部边境迫在眉睫的天灾威胁。",h="在解决库勒曼·法席恩于阿加曼德磨坊的私人恩怨后，执政官塞弗伦召集冒险者前往布瑞尔。磨坊里不仅仅有痛苦的家族亡魂，它还代表着布瑞尔北部边境迫在眉睫的天灾威胁。",kw={"阿加曼德磨坊","布瑞尔","库勒曼·法席恩","执政官塞弗伦","塞弗伦","家族墓穴","闹鬼的磨坊","提瑞斯法林地"},ang={["faction:Horde"]="布瑞尔代表了幽暗城的第一道防线；从天灾手中保护周边的农田对于部落在洛丹伦北部的统治至关重要。",["race:Undead"]="证明自己在面对盲目天灾时的能力，能让你在布瑞尔迅速获得认可，从自由散工转为在执政官塞弗伦麾下直接参与民事防御。"},sec={{t="从复仇到公民责任",b="库勒曼·法席恩曾寻求向他昔日的邻居——阿加曼德家族报私仇，派遣旅行者向北行进，消灭潜伏在磨坊附近的亡灵。在这些遗骸被处理掉后，库勒曼意识到他的私人仇恨与一个更广泛的战术问题交织在了一起：整个阿加曼德庄园仍然充斥着盲目且具有攻击性的天灾爪牙，就在布瑞尔的家门口。"},{t="执政官的召唤",b="执政官塞弗伦为黑暗女王监管着布瑞尔的民事和军事安全。由于听说有一位冒险者能够深入闹鬼的农田并幸存下来，塞弗伦决定指派这双能干的手去探查瘟疫的根源——古老的阿加曼德家族墓穴本身。"}},faq={{q="为什么库勒曼·法席恩要我去找执政官塞弗伦？",a="库勒曼已经满足了他对复活的阿加曼德家族的复仇，但他知道磨坊里的亡灵威胁着整个布瑞尔。他向负责组织当地防御的执政官塞弗伦报告了你的战斗能力。",al={"为什么要去找塞弗伦","库勒曼·法席恩的推荐","执政官塞弗伦是谁"}},{q="执政官塞弗伦在哪里？",a="执政官塞弗伦驻扎在提瑞斯法林地的布瑞尔，位于布瑞尔城镇大厅内，为被遗忘者处理当地事务。",al={"塞弗伦的位置","执政官塞弗伦在哪里","寻找塞弗伦"}},{q="阿加曼德磨坊构成了什么威胁？",a="磨坊位于布瑞尔以北，那里仍然被盲目的天灾军团彻底占领。如果不加遏制，在田野中徘徊的行尸和不安的灵魂可能会轻易淹没整个城镇。",al={"阿加曼德磨坊的危险","为什么磨坊是个威胁"}},{q="与执政官塞弗伦交谈后会发生什么？",a="塞弗伦将招募你直接突袭阿加曼德家族墓穴，以消除将亡灵束缚在磨坊上的更深层天灾威胁。",al={"塞弗伦之后的下一个任务","塞弗伦想要什么"}},{q="这个任务需要立即回到磨坊吗？",a="这项简短的任务只是一个过渡。你向布瑞尔的塞弗伦报告以完成库勒曼的指引，然后接受进入墓穴的下一个任务。",al={"我需要回到磨坊吗","这个任务只是对话吗"}},{q="布瑞尔为什么要关心阿加曼德家族？",a="生前，阿加曼德家族是提瑞斯法地区富有的磨坊主和显赫的邻居。死后，他们不洁的庄园成为了盲目天灾军团的加固集结地。",al={"阿加曼德的重要性","阿加曼德家族对布瑞尔意味着什么"}}},fp="17,156,28.314.0,21.249.0,55.207.0,37.120.0,38.166.0,51.131.0,59.106.0,45.149.0"}
P.entries["quest:356"] = {n="巡查后方",s="Rear Guard Patrol是一项由亡灵卫兵林奈指派的军事侦察任务，旨在保护提瑞斯法林地东部边界沿线的被遗忘者防线。该任务指示行动人员在巴尼尔农场清理游荡的天灾恐怖生物和徘徊的鬼魂，以防止它们破坏支援亡灵壁垒的补给线。",h="Rear Guard...",kw={"巴尼尔","流血的恐怖","亡灵壁垒","林奈","天灾军团","提瑞斯法","游荡的鬼魂","塞加德"},ang={["faction:Horde"]="坚守提瑞斯法的东部外围确保了部落能在北部的东部王国维持其对抗亡灵军团的立足点。",["race:Undead"]="对于被遗忘者来说，守护亡灵壁垒的后方纯粹是为了生存；击碎天灾军团在巴尼尔农场的存在，能让家园免受巫妖王卷土重来的掌控。"},sec={{t="确保亡灵壁垒的侧翼安全",b="亡灵壁垒是抵御西瘟疫之地的瘟疫和军队侵入提瑞斯法林地的主要屏障。亡灵卫兵林奈负责监督这条前线沿线的后方安全。由于防线无法承担因腹背受敌而分散兵力的风险，任何绕过扼守点的亡灵都必须在切断前线补给线之前被消灭。"},{t="巴尼尔农场的废墟",b="巴尼尔农场曾是提瑞斯法东部的一处农场，在第三次战争中沦为废墟。如今这里已被彻底腐蚀，杂草丛生的田地和坍塌的马厩为入侵的“流血的恐怖”和不安的“游荡的鬼魂”提供了藏身之所。清除该据点可以阻止巫妖王在提瑞斯法内部建立集结地，并能保障部落增援部队的道路安全。"}},faq={{q="为什么这项巡逻任务对亡灵壁垒很重要？",a="亡灵壁垒扼守着通往西瘟疫之地的狭窄边境通道。如果游荡的天灾军团从侧翼包抄该防御工事或在其后方定居，守军将陷入腹背受敌的境地，并失去连接布瑞尔和幽暗城的补给线。",al={"为什么要执行rear guard patrol","亡灵壁垒的重要性","为什么要确保巴尼尔的安全"}},{q="是谁下达了这项任务？",a="驻扎在通往东部瘟疫之地道路附近的军官亡灵卫兵林奈负责指派该巡逻任务，并将成功的报告上报给执行官塞加德。",al={"谁发布了rear guard patrol","亡灵卫兵林奈"}},{q="什么生物出没在巴尼尔农场？",a="这个被腐蚀的农场里爬满了“流血的恐怖”——由死灵法术缝合而成的复生尸体，以及在天灾军团最初征服时死去的昔日居民的“游荡的鬼魂”。",al={"巴尼尔农场的怪物","巴尼尔有什么怪物","流血的恐怖"}},{q="谁是执行官塞加德？",a="执行官塞加德是一位驻扎在布瑞尔的高级被遗忘者亡灵卫兵指挥官，也是亡灵卫兵林奈的上级。",al={"执行官塞加德背景","谁是塞加德"}},{q="为什么被遗忘者不放弃东部边界？",a="放弃亡灵壁垒将使整个提瑞斯法林地和幽暗城的大门直接暴露在从瘟疫之地涌出的无穷无尽的天灾军团面前。",al={"为什么要保卫亡灵壁垒","为什么要在这道边境线上战斗"}}},fp="17,220,28.344.0,29.347.0,45.222.0,24.136.0,42.210.0,23.109.0,55.153.0"}
P.entries["quest:3566"] = {n="奥比斯顿",s="在完成“释放他们”之后，一名垂死的考古学家喘着气说这一切都是个陷阱，并恳求你为了他们和索里奥斯馆长杀了那个叛徒。黑色拉索里克和奥西迪恩都必须死，铁炉堡的索里奥斯馆长需要证明。",h="在完成“释放他们”之后，一名垂死的考古学家喘着气说这一切都是个陷阱，并恳求你为了他们和索里奥斯馆长杀了那个叛徒。黑色拉索里克和奥西迪恩都必须死，铁炉堡的索里奥斯馆长需要证明。",kw={"索里奥斯馆长","垂死的考古学家","铁炉堡","黑色拉索里克","奥西迪恩","拉格纳罗斯","崛起吧，奥西迪恩","灼热峡谷"},sec={{t="临终的恳求",b="这名考古学家几乎无法开口。他们说这一切都是陷阱，请求宽恕，并恳求你为了他们和索里奥斯馆长杀了那个叛徒。黑色拉索里克和奥西迪恩都必须倒下，而铁炉堡的索里奥斯馆长想要其中一人的头颅和另一人的心脏。"},{t="回应的声音",b="多里奥斯出现并嘲笑你们是傻瓜。他利用自己兄弟软弱的感情，诱骗救援者前来，以便从暮光之锤手中夺取最后一块桑塔拉之石。他在灰尘泥挖掘场发现了桑塔拉之石，拉格纳罗斯的力量涌入了他的体内，给了他一个目标。在拉格纳罗斯的意志下，奥西迪恩被制造出来，用以摧毁黑石塔的黑石兽人。作为一名火焰侍僧重获新生后，他取名黑色拉索里克。回到铁炉堡，索里奥斯看到证据后脸色苍白：他自己的兄弟策划了这一切，背叛了他和铁炉堡。索里奥斯担心上古之神在这里依然拥有强大的影响力，如果像他这样高尚的人都能如此轻易地投向拉格纳罗斯，那么谁也不安全。"}},faq={{q="谁给予此任务？",a="一名垂死的考古学家，他恳求你为他和索里奥斯馆长复仇。",al={"任务发布者","谁开始崛起吧奥西迪恩","垂死的考古学家"}},{q="此任务的前置任务是什么？",a="“释放他们”，这是此任务的后续。",al={"前置任务","前置条件","崛起吧奥西迪恩之前的任务线"}},{q="你把证明带给谁？",a="铁炉堡的索里奥斯馆长，他需要头颅和心脏作为证明。",al={"在哪里交任务","找谁交任务","索里奥斯馆长在哪里"}},{q="你被派去击杀谁？",a="两个敌人：一个是名为黑色拉索里克的家伙，另一个是奥西迪恩。",al={"奥西迪恩是谁","拉索里克是谁","目标"}}},fp="15,229,12.287.0,15.719.1,21.63.0,29.33.0,30.80.0,25.57.0"}
P.entries["quest:3567"] = {n="登高",s="玛里可以送你上去，欣赏菲拉斯双塔山之一的景色，但她也给出了警告：这趟旅程是有去无回的。",h="玛里可以送你上去，欣赏菲拉斯双塔山之一的景色，但她也给出了警告：这趟旅程是有去无回的。",kw={"巨像","菲拉斯","玛里","山顶","到顶端","双塔山"},sec={{t="单程票",b="玛里询问你是否想从双塔山之一的顶端欣赏风景，并可以送你上去。玛里还特别提醒你：考虑一下你该怎么下来，因为这是一次单程旅行。"}},faq={{q="谁能把你送到巨像的顶端？",a="玛里可以把你送到双塔山之一，让你欣赏上面的风景。",al={"谁给予到顶端任务","到顶端任务发布者","玛里"}},{q="这趟旅程通往何处？",a="双塔山之一的顶端。",al={"玛里把你送到哪里","目的地","到顶端地点"}},{q="玛里提供回程的方法吗？",a="不提供。玛里警告说这是一次单程旅行，所以你应该考虑好如何下来。",al={"我怎么下来","有回程吗","从双塔山下来的路"}}},fp="10,146,10.224.0,42.74.0,29.40.0,35.91.0"}
P.entries["quest:357"] = {n="巫妖的身份",s="“巫妖的身份”是幽暗城的一个任务，由Magic Quarter的比索·埃斯沙德发布。为了查明一位居住在澈水湖的隐居巫妖的身份，比索派遣了一名使者去窃取该人物的法术书，以评估他的力量和立场。",h="“巫妖的身份”是幽暗城的一个任务，由Magic Quarter的比索·埃斯沙德发布。为了查明一位居住在澈水湖的隐居巫妖的身份，比索派遣了一名使者去窃取该人物的法术书，以评估他的力量和立场。",kw={"比索·埃斯沙德","澈水湖","被遗忘者","magic quarter","死灵法师","sylvanas windrunner","巫妖的法术书","幽暗城"},ang={["class:Mage"]="在Magic Quarter拜访比索·埃斯沙德的法师们，可以看到洛丹伦和达拉然魔法传统的幸存残余，已经被转化为被遗忘者生存的工具。",["faction:Horde"]="招募强大的死灵法师加强了部落的北部边境，以对抗血色十字军和天灾军团的无情攻击。",["race:Undead"]="对于被遗忘者来说，收复独立的亡灵证明了摆脱巫妖王的控制并非孤立的奇迹，同时也为Sylvanas Windrunner的法庭确保了至关重要的死灵力量。"},sec={{t="湖畔隐士",b="在幽暗城以北，澈水湖那迷雾缭绕的水域中，有一位孤独的巫妖在一座小岛上自我放逐。与巫妖王那些毫无思想的傀儡不同，这位死灵法师拥有自己的自由意志，但他却生活在极度的偏执之中。他认定任何靠近他的亡灵都是天灾军团派来将他拖回奴役状态的爪牙，因此会对任何踏上他领地的人释放召唤出的爪牙。"},{t="宝贵的资产",b="有关这名流浪巫妖的消息最终传到了比索·埃斯沙德耳中，这位大魔法师主管着幽暗城的法师们。比索认识到了这样一个实体的战略重要性：Sylvanas Windrunner寻求每一丝魔法造诣和每一股有能力的意志，以增强被遗忘者对抗他们众多敌人的力量。为了评估这名隐士是否可以招募，比索需要他身份的证明以及他的死灵法术专长的证据。"},{t="寻得故友",b="在偷来的法术书被送到Magic Quarter后，比索检查了上面的奥术文字，发现了这名巫妖的真实身份：冈瑟尔·阿坎努斯。在生前，冈瑟尔是一位才华横溢的死灵法师，也是瘟疫蹂躏洛丹伦之前比索的亲密战友。这一发现证实了冈瑟尔不仅是一个独立的灵魂，更是一位老盟友，他那扩展后的死灵力量将极大地造福黑暗女王的国度。"}},faq={{q="是谁派你执行这个任务的？",a="任务由比索·埃斯沙德委派，他是一位驻扎在幽暗城Magic Quarter的高阶且强大的被遗忘者法师。",al={"任务发布者","比索·埃斯沙德位置","谁发布了巫妖的身份任务"}},{q="为什么巫妖会攻击任何接近他的人？",a="这名巫妖凭自己的意志摆脱了巫妖王的控制，但他误以为洛丹伦所有其他的亡灵仍然是被精神控制的天灾爪牙。因此，他命令他的爪牙攻击任何接近他岛屿的人，以捍卫自己的自由。",al={"冈瑟尔为何敌对","为何巫妖进行攻击","澈水湖巫妖敌对"}},{q="巫妖的营地在哪里？",a="他住在澈水湖中心的一座岛屿上，该湖位于提瑞斯法林地，就在洛丹伦废墟和幽暗城的正北方。",al={"巫妖在哪里","澈水湖岛屿","冈瑟尔·阿坎努斯位置"}},{q="为什么Sylvanas Windrunner想要将他纳入被遗忘者麾下？",a="拥有高超魔法天赋的独立亡灵非常罕见。一位能够驾驭强大死亡魔法且拥有自由意志的死灵法师，将为被遗忘者提供对抗天灾军团和血色十字军的关键力量。",al={"为何要招募该巫妖","被遗忘者对冈瑟尔的兴趣","sylvanas windrunner与巫妖"}},{q="这名巫妖究竟是谁？",a="比索揭示了这名巫妖就是冈瑟尔·阿坎努斯，他曾是一名达拉然法师和技艺高超的死灵法师，在第三次战争前曾是比索亲密的战友。",al={"巫妖身份","巫妖是谁","巫妖的真实身份"}},{q="在你交付法术书之后会发生什么？",a="一旦比索确认了冈瑟尔的身份，他会让你带着法术书回到澈水湖，去说服冈瑟尔，让他们相信被遗忘者是真正自由的，并希望欢迎他的加入。",al={"接下来做什么","归还书籍任务","巫妖的身份任务之后"}}},fp="19,157,21.340.0,16.350.0,19.318.1,30.86.0,51.233.0,33.123.0,58.191.0,33.155.1,45.178.1"}
P.entries["quest:358"] = {n="盗墓贼",s="布瑞尔的执政官塞弗伦指派冒险者去清除位于加伦鬼屋西南方万人坑中的腐皮豺狼人。这些亡灵野兽是天灾军团派来挖掘早期瘟疫受害者尸体的，目的是扩充他们的兵力。消灭它们并回收防腐剂不仅能保护死者，还能辅助皇家药剂师学会的研究。",h="布瑞尔的执政官塞弗伦指派冒险者去清除位于加伦鬼屋西南方万人坑中的腐皮豺狼人。这些亡灵野兽是天灾军团派来挖掘早期瘟疫受害者尸体的，目的是扩充他们的兵力。消灭它们并回收防腐剂不仅能保护死者，还能辅助皇家药剂师学会的研究。",kw={"布瑞尔","防腐剂","加伦鬼屋","掘墓者","执政官塞弗伦","万人坑","腐皮","提瑞斯法林地"},ang={["faction:Horde"]="阻止天灾军团的补给行动可以稳固洛丹伦北部，加强部落对抗巫妖王残余势力的立足点。",["race:Undead"]="对于被遗忘者来说，阻止天灾军团复活提瑞斯法的前公民，是为了让他们的同胞免于遭受沦为无脑奴仆的可怕命运。"},sec={{t="亵渎万人坑",b="当亡灵瘟疫最初席卷提瑞斯法林地时，死者的堆积速度远远超过了正常埋葬的速度。在北部地区挖掘了巨大的万人坑，以容纳惊人的死亡人数。直到最近，这些被掩埋的遗骸都免于被复活。然而现在，天灾军团已经在加伦鬼屋西南方的壕沟释放了腐皮豺狼人，派它们去挖掘腐烂的遗骸，以充实巫妖王的军队。"},{t="以其人之道还治其人之身",b="腐皮豺狼人依靠防腐剂维持生命，这是一种能够保存并激活它们腐烂躯体的炼金混合物。通过命令侦察兵消灭这些掘墓者并提取这种液体，执政官塞弗伦同时达成了两个目的：阻止天灾军团搜刮原始尸体，并将宝贵的生物样本直接送给布瑞尔的药剂师们，他们正试图用巫妖王自己的手段来对付他。"}},faq={{q="天灾军团为什么要挖掘万人坑？",a="万人坑中埋葬着瘟疫最初降临提瑞斯法时的大量受害者。天灾军团打算挖掘出这些保存完好的尸体，以复活新的士兵，并扩充他们对抗被遗忘者的军队。",al={"为什么豺狼人在挖掘尸体","天灾军团要尸体做什么","万人坑的目的"}},{q="什么是腐皮豺狼人？",a="它们是被天灾军团奴役的亡灵豺狼人。它们使用炼金防腐剂来保存躯体并获得活力，在加伦鬼屋和邻近的墓地周围担任拾荒者和突击部队。",al={"腐皮豺狼人背景","提瑞斯法的亡灵豺狼人","什么是腐皮豺狼人"}},{q="万人坑在哪里？",a="万人坑位于加伦鬼屋的西南方，提瑞斯法林地的北部丘陵地带，布瑞尔的正北方。",al={"掘墓者在哪里","万人坑位置","加伦鬼屋万人坑"}},{q="被遗忘者要防腐剂做什么？",a="执政官塞弗伦将收集到的防腐剂交给被遗忘者的药剂师，让他们研究天灾军团是如何激活和维持其低级奴仆的，以此寻找在持续战争中可以利用的弱点。",al={"为什么收集防腐剂","防腐剂的用途","防腐剂背景"}},{q="是谁下令处决这些掘墓者的？",a="布瑞尔的被遗忘者监督者，执政官塞弗伦，发布了这份悬赏，旨在保卫提瑞斯法的边界并为药剂师获取有用的试剂。",al={"谁发布了掘墓者的任务","执政官塞弗伦的作用"}},{q="为什么被遗忘者会在意瘟疫受害者的尸体是否被复活？",a="每一具被天灾军团夺取并复活的尸体都会变成服从巫妖王意志的敌方士兵，直接威胁到新近解放的被遗忘者王国。",al={"为什么被遗忘者要保护墓地","为什么在意死尸"}}},fp="12,199,30.372.0,30.301.0,45.153.0,29.199.0,32.111.0,51.189.0,41.154.0,59.140.0"}
P.entries["quest:359"] = {n="亡灵卫兵的职责",s="“被遗忘者的职责”是由布瑞尔的执政官塞弗伦指派的侦察任务，旨在评估提瑞斯法林地东部边缘的天灾军团活动。它揭示了天灾军团潜入亡灵壁垒并威胁当地定居点所带来的持续威胁。",h="“被遗忘者的职责”是由布瑞尔的执政官塞弗伦指派的侦察任务，旨在评估提瑞斯法林地东部边缘的天灾军团活动。它揭示了天灾军团潜入亡灵壁垒并威胁当地定居点所带来的持续威胁。",kw={"巴尼尔农场","布瑞尔","亡灵卫兵林奈","被遗忘者的职责","执政官塞弗伦","天灾军团","亡灵壁垒","提瑞斯法林地"},ang={["faction:Horde"]="保卫提瑞斯法林地免受天灾军团的入侵，可确保部落在北洛丹伦维持一个可靠的立足点。",["race:Undead"]="对天灾军团保持警惕对被遗忘者至关重要，因为沿边境的任何缺口都会直接威胁到布瑞尔和新近宣称主权的幽暗城。"},sec={{t="边境警备",b="执政官塞弗伦负责布瑞尔及其周边乡村的治安，时刻警惕着提瑞斯法林地的东部边界。由于天灾军团在西瘟疫之地肆虐，塞弗伦需要前线哨兵进行持续侦察，以确保这些亡灵恐怖不会在无人察觉的情况下潜入边境。愿意提供协助的旅行者会被派往南方和东部的大道，从亡灵卫兵林奈那里获取一份紧急战术评估。"},{t="前线报告",b="驻扎在路边东部哨所的亡灵卫兵林奈亲眼观察着边境。她的发现证实了执政官的担忧：虽然亡灵壁垒的防御工事成功阻挡了天灾军团的主力部队，但偶尔仍有小股亡灵能够绕过防御。这些游兵散勇已经开始聚集在附近的巴尼尔农场周围，对提瑞斯法林地构成了局部但危险的威胁。"}},faq={{q="谁发布了“被遗忘者的职责”任务？",a="驻扎在布瑞尔的执政官塞弗伦指派旅行者从东部的亡灵卫兵哨所获取最新的侦察报告。",al={"谁发布被遗忘者的职责","谁开始被遗忘者的职责","塞弗伦任务"}},{q="亡灵卫兵林奈是谁？",a="亡灵卫兵林奈驻扎在布瑞尔东部的亡灵卫兵哨站，监视着道路上的动向并守卫通往瘟疫之地的入口。",al={"林奈是谁","亡灵卫兵林奈位置","林奈在哪里"}},{q="什么是亡灵壁垒？",a="亡灵壁垒是分隔提瑞斯法林地与西瘟疫之地的设防边境哨所，驻军旨在防止天灾军团蹂躏被遗忘者的领土。",al={"什么是亡灵壁垒","亡灵壁垒防御","为什么亡灵壁垒很重要"}},{q="天灾军团是从哪里潜入边境的？",a="虽然亡灵壁垒的守军阻挡了天灾军团的大部分兵力，但仍有游散的天灾部队潜入并聚集在哨站东面的巴尼尔农场周围。",al={"提瑞斯法的天灾军团","巴尼尔农场的天灾军团","天灾军团从哪里渗透"}},{q="为什么执政官塞弗伦需要状态报告？",a="执政官塞弗伦需要确保天灾军团无法在提瑞斯法林地站稳脚跟，因此要求亡灵卫兵保持高度警惕。",al={"为什么塞弗伦需要报告","塞弗伦的担忧"}},{q="如何前往亡灵卫兵林奈的哨所？",a="要从布瑞尔前往哨站，旅行者需要沿路向南走，在岔路口向东转，前往提瑞斯法林地的东部地区。",al={"哨站在哪里","如何找到林奈"}}},fp="15,274,23.484.0,22.437.0,36.140.0,25.162.0,20.163.0,43.166.0,48.159.0,43.140.0"}
P.entries["quest:36"] = {n="杂味炖肉",s="西部荒野炖肉最初源于流离失所的定居者与少数坚守家园的农夫之间的邻里互助。由于肆虐的强盗迫使家人放弃了土地，弗娜·法布隆在离开该地区之前，将她珍藏的当地食谱传给了萨尔玛·萨丁。",h="西部荒野炖肉最初源于流离失所的定居者与少数坚守家园的农夫之间的邻里互助。由于肆虐的强盗迫使家人放弃了土地，弗娜·法布隆在离开该地区之前，将她珍藏的当地食谱传给了萨尔玛·萨丁。",kw={"烹饪","农夫法布隆","食谱","萨丁农场","萨尔玛·萨丁","炖肉","弗娜·法布隆","西部荒野"},ang={["profession:Cooking"]="这道菜代表了人类定居者典型的边境烹饪方式，将拾取的草原猎物和耐寒的根茎蔬菜转化为维持生命的食物。",["race:Human"]="这次交付反映了暴风城王国边境的崩溃，普通的农村公民正不断被赶出祖辈的农场，被迫流亡城市。"},sec={{t="传承的食谱",b="法布隆一家的离去凸显了西部荒野乡村日益恶化的崩溃局势。由于迪菲亚盗贼和失控的机械收割机将他们赶出了家庭农场，弗娜和农夫法布隆正在装载马车，准备前往暴风城的城墙后寻求庇护。弗娜不愿让这一家常传统随着农场的荒废而消失，便将她标志性的西部荒野炖肉食谱托付给了邻居萨尔玛·萨丁。"},{t="家园守望",b="萨尔玛·萨丁依然坚守在路边不远处的农舍里，与她的丈夫农夫萨丁一起顽强地抵抗着。收到弗娜的食谱是一个苦乐参半的时刻：虽然这意味着又失去了一位邻居，却也保留了当地农场生活的一项主食。拿着烹饪说明，萨尔玛开始收集必要的乡间食材，以供养那些仍在边境挣扎求生的人们。"}},faq={{q="为什么法布隆一家要离开他们的农场？",a="小偷和强盗已经占领了他们的田地，使他们的土地变得极其危险，无法耕作。弗娜和农夫法布隆正在修理马车，准备逃往安全的暴风城。",al={"法布隆离开原因","法布隆一家离开西部荒野","弗娜为什么打包离开"}},{q="萨尔玛·萨丁是谁？",a="萨尔玛·萨丁是一位居住在萨丁农场的西部荒野定居者，位于法布隆农舍岔路口之后。尽管周围无法无天，她和她的家人仍在努力耕种他们的土地。",al={"萨尔玛是谁","萨尔玛·萨丁背景故事"}},{q="什么是西部荒野炖肉？",a="这是一种传统的、丰盛的地区性菜肴，由西部荒野平原上的原生食材调制而成，长期以来在当地的农户之间广为流传。",al={"什么是西部荒野炖肉","西部荒野炖肉食谱"}},{q="法布隆一家计划去哪里？",a="他们正向北前往安全的暴风城，弗娜的朋友们相信她能在那里安顿下来。",al={"法布隆一家去哪","法布隆的目的地"}},{q="萨丁农场在哪里？",a="萨丁农场位于主路岔路口之外，就在西部荒野法布隆南瓜地以南。",al={"萨丁农场位置","萨尔玛·萨丁在哪里"}},{q="这个任务会奖励实际的烹饪配方吗？",a="将书面说明交给萨尔玛·萨丁只是第一步。要真正制作这道菜，萨尔玛会请求你帮忙寻找锅里所需的乡间食材。",al={"食谱奖励","我能得到西部荒野炖肉食谱吗"}}},fp="13,151,18.332.0,20.254.0,41.158.0,21.210.0,22.142.0,39.114.0,32.107.0,49.134.0"}
P.entries["quest:360"] = {n="向塞弗伦回报",s="“回到执政官身边”是一项在提瑞斯法林地东部边界与布瑞尔镇之间进行紧急侦察的任务。冒险者向布瑞尔东部的亡灵卫兵林奈汇报后，又被派往回去将令人不安的消息直接传达给执政官塞弗伦。这条消息确认了巫妖王的无脑爪牙仍在不断试探这个年轻的被遗忘者国度的边界。",h="“回到执政官身边”是一项在提瑞斯法林地东部边界与布瑞尔镇之间进行紧急侦察的任务。冒险者向布瑞尔东部的亡灵卫兵林奈汇报后，又被派往回去将令人不安的消息直接传达给执政官塞弗伦。这条消息确认了巫妖王的无脑爪牙仍在不断试探这个年...",kw={"布瑞尔","亡灵壁垒","被遗忘者的职责","林奈","天灾军团","塞弗伦","提瑞斯法"},ang={["faction:Horde"]="部落在东部王国的立足点依赖于提瑞斯法林地的稳定，这使得亡灵壁垒的防御对于抵御瘟疫之地的亡灵恐怖势力至关重要。",["race:Undead"]="传递来自亡灵壁垒的情报，让人切身感受到被遗忘者自由的脆弱现实：你所逃离的主人，依然在试图扣响你新家园的大门。"},sec={{t="边境报告",b="从提瑞斯法林地出发向东的道路直接通往西瘟疫之地的凋零废墟，那里正受到天灾军团的毁灭性控制。为了阻止亡灵大军涌入他们新宣布的主权领地，被遗忘者建立了亡灵壁垒——这是一座设防的检查站，由亡灵卫兵林奈这样的严厉哨兵在防线后方的哨站进行监视。在收集了关于东门外敌情的信息后，林奈会派遣信使沿着国王大道向西疾驰返回布瑞尔，以免敌方渗透者利用任何防线漏洞。"},{t="塞弗伦的誓言",b="当执政官塞弗伦在布瑞尔收到这份快报时，这证实了他最担心的事：天灾斥候正在寻找绕过或穿过前线防御圈的路径。对于被遗忘者来说，每一个爬行的食尸鬼和无脑骷髅不仅是军事上的麻烦，更是对他们在洛丹伦沦陷期间所摆脱的奴役的一种提醒。塞弗伦坚定地认为，无论巫妖王的攻势多么无休无止，自由的亡灵永远不会放弃他们新获得的自主权。"}},faq={{q="这份报告来自哪里？",a="这份报告来自驻扎在布瑞尔东部、通往亡灵壁垒道路上的亡灵卫兵岗哨的亡灵卫兵林奈。她收集了关于隔离提瑞斯法与被天灾军团占据的西瘟疫之地的路障情报。",al={"任务来源","谁发送了这份报告","林奈在哪里"}},{q="为什么执政官塞弗伦会对这个消息感到担忧？",a="快报告知塞弗伦，天灾军团已经设法溜过了亡灵壁垒的防御工事。对于布瑞尔的被遗忘者来说，敌人的入侵威胁到了他们初生的城镇，并时刻提醒着他们巫妖王试图夺回他们的野心。",al={"为什么塞弗伦很担心","报告的内容是什么","天灾威胁"}},{q="执政官塞弗伦是谁？",a="执政官塞弗伦是布瑞尔的行政长官。他在市政厅办公，负责监督当地的防御、基础设施以及整个提瑞斯法林地中部新复生的被遗忘者公民的调遣。",al={"塞弗伦背景故事","执政官是谁"}},{q="什么是亡灵壁垒？",a="亡灵壁垒是沿着提瑞斯法林地和西瘟疫之地之间主要通道修建的一座防御前哨站。它是防止天灾军团入侵被遗忘者领地的主要屏障。",al={"亡灵壁垒背景故事","提瑞斯法东部边界"}},{q="为什么被遗忘者如此憎恨天灾军团？",a="被遗忘者曾经是天灾军团的无脑奴仆，生前被屠杀，死后被复活去残杀自己的亲人。在恢复了自由意志后，他们憎恨巫妖王，并害怕再次失去理智而被其控制。",al={"被遗忘者对抗天灾军团","为何憎恨巫妖王"}},{q="这条消息传递的路径是什么？",a="信使沿着亡灵卫兵林奈的哨站出发，沿主路向西行进，穿过提瑞斯法林地中部，直至到达布瑞尔镇中心。",al={"从亡灵壁垒到布瑞尔的路线","通往布瑞尔的道路"}}},fp="24,174,16.417.0,12.331.0,33.193.0,51.197.0,25.174.0,20.152.0,45.188.0,35.147.0"}
P.entries["quest:361"] = {n="未寄出的信件",s="这是一封在阿加曼德磨坊的白骨废墟中发现的、褪色且沾满血迹的信件，收件人是伊维特·法席恩。它揭示了天灾军团横扫洛丹伦时，这对恋人之间悲剧般的离别，也让人们得以窥见被遗忘者在用生命换取不死后，所抛弃的过往。",h="这是一封在阿加曼德磨坊的白骨废墟中发现的、褪色且沾满血迹的信件，收件人是伊维特·法席恩。它揭示了天灾军团横扫洛丹伦时，这对恋人之间悲剧般的离别，也让人们得以窥见被遗忘者在用生命换取不死后，所抛弃的过往。",kw={"阿加曼德","布瑞尔","farthing","信","天灾军团","旅店","瑟曼","未送达","伊维特"},ang={["faction:Horde"]="对于造访布瑞尔的旅行者来说，这块被找回的羊皮纸清晰地展现了被遗忘者种族特有的情感疏离。",["race:Undead"]="这封信体现了被遗忘者凡人记忆与其在希尔瓦娜斯女王治下冷酷、目的明确的生活之间那道尖锐而痛苦的鸿沟。"},sec={{t="一封在沦陷中遗失的信",b="这封由家族族长格雷戈尔·阿加曼德的长子瑟曼·阿加曼德所写、却从未寄出的羊皮纸，在家族庄园化为废墟之前，并未到达它的收件人手中。当亡灵瘟疫吞噬提瑞斯法林地时，瑟曼拒绝抛弃他的祖宅和亲人。在袭击的恐怖之中，他拿起羽毛笔，给在王国化为灰烬前他深爱的伊维特·法席恩写下了最后一封信。"},{t="断裂的羁绊",b="当这封信最终在布瑞尔的恐惧之末旅店交到伊维特·法席恩手中时，它引起了她一段短暂而痛苦的记忆闪回。她记得曾恳求瑟曼和她及她的父亲一起逃离阿加曼德磨坊，她还哀叹瑟曼的兄弟布兰德对他怀有恶意。然而，这种温情转瞬即逝。像许多被遗忘者一样，伊维特坚定起自己的心，抛开了凡人的悔恨，宣称在她的新生活中，爱情已无容身之地。"}},faq={{q="谁写了这封信？",a="这封信是由格雷戈尔·阿加曼德的长子瑟曼·阿加曼德所写。瑟曼与他那受诅咒的家人们一起，在保卫家族磨坊抵御天灾军团的战斗中丧生。",al={"作者","瑟曼·阿加曼德","谁是瑟曼"}},{q="谁是伊维特·法席恩？",a="伊维特·法席恩是一位目前居住在布瑞尔旅店内的被遗忘者。生前，她曾恳求她的恋人瑟曼·阿加曼德与她及她的父亲一起离开阿加曼德磨坊，但他留在了那里陪伴家人。",al={"伊维特","谁是伊维特","收件人"}},{q="这封信是从哪里来的？",a="这封信是从提瑞斯法林地西部阿加曼德磨坊那片荒凉的土地和田野上徘徊的行尸走骨身上拾取的。",al={"在哪里找到信","信件掉落","信件位置"}},{q="瑟曼和伊维特之间发生了什么？",a="他们在第三次战争前是一对恋人。伊维特恳求瑟曼放弃他家族的磨坊并与她一起逃走，但瑟曼选择了忠于亲人，留下来面对瘟疫。",al={"瑟曼与伊维特","伊维特背景故事","他们发生了什么事"}},{q="伊维特读到这封信时做了什么？",a="她短暂地为瑟曼感到悲伤，并诅咒了天灾军团和他的兄弟布兰德，但很快就压抑住了自己的情绪。她坚持认为悔恨是弱者的表现，浪漫在她的被遗忘者存在中没有立足之地。",al={"伊维特反应","伊维特说了什么"}},{q="谁是布兰德·阿加曼德？",a="布兰德是瑟曼的兄弟。据伊维特所述，即便在庄园沦陷于瘟疫之前，布兰德就对瑟曼怀有深深的怨恨和恶意。",al={"布兰德","布兰德·阿加曼德","谁是布兰德"}}},fp="20,232,26.335.0,16.359.1,22.169.0,23.195.0,31.131.0,41.163.0,46.209.1,21.152.0"}
P.entries["quest:362"] = {n="闹鬼的磨坊",s="来自布瑞尔的库勒曼·法席恩寻求向他曾经的土地所有者阿加曼德家族复仇，他要求收集并摧毁这些阴魂不散的亡灵遗骸。这项任务将指引你向北前往阿加曼德磨坊，除掉该庄园尖酸刻薄的小儿子代弗林·阿加曼德。这开启了一场针对那个在瘟疫面前未能保护提瑞斯法普通民众的家族的苦涩血仇。",h="来自布瑞尔的库勒曼·法席恩寻求向他曾经的土地所有者阿加曼德家族复仇，他要求收集并摧毁这些阴魂不散的亡灵遗骸。这项任务将指引你向北前往阿加曼德磨坊，除掉该庄园尖酸刻薄的小儿子代弗林·阿加曼德。这开启了一场针对那个在瘟疫面前...",kw={"阿加曼德磨坊","布瑞尔","库勒曼·法席恩","代弗林·阿加曼德","闹鬼的磨坊","瘟疫","天灾军团","提瑞斯法林地"},ang={["faction:Horde"]="在提瑞斯法协助被遗忘者意味着帮助他们清除布瑞尔和幽暗城边界地区危险的天灾军团残余。",["race:Undead"]="这项任务反映了在洛丹伦陷落后依然存在的深层阶级怨恨，展示了被遗忘者如何对那些未能从瘟疫中保护他们的地主贵族怀有刻骨的仇恨。"},sec={{t="苦涩的收获",b="在第三次战争之前，阿加曼德磨坊曾是提瑞斯法北部的主要粮仓，由一个富有的地主家族拥有。当亡灵天灾席卷洛丹伦时，普通民众指望这些贵族地主能提供安全保障，却最终发现既无庇护也无救赎。库勒曼·法席恩虽然在亡灵状态下幸存了下来，但他心中仍被对曾经效忠的家族的仇恨所吞噬。法席恩并不打算让他们在永恒的折磨中徘徊，而是渴望通过收集并践踏他们的骨骸来获得病态的满足感。"},{t="弟弟",b="代弗林·阿加曼德是瑟曼·阿加曼德的弟弟。生前，代弗林被公认为是一个软弱、恶毒且尖酸刻薄的年轻人，与他温和的哥哥形成了鲜明的对比。当亡灵瘟疫蔓延到磨坊庄园时，代弗林是最早沦为腐化牺牲品的人之一。如今，他失去了生前那点可怜的机灵，只会一边无意识地游荡在通往家族磨坊的北路上，一边喋喋不休地胡言乱语。"}},faq={{q="为什么库勒曼·法席恩想要代弗林的遗骸？",a="库勒曼·法席恩指责富有的阿加曼德家族在天灾横扫洛丹伦时遗弃了他和他的亲人。身为亡灵，他寻求个人复仇，想要收集阿加曼德家族的骨骸，这样他就能把它们陈列在壁炉台上，并亲手将它们碾成粉末。",al={"为什么库勒曼想要骨骸","库勒曼·法席恩的动机","为什么要杀死代弗林"}},{q="去哪里可以找到代弗林·阿加曼德？",a="代弗林游荡在提瑞斯法林地北部，阿加曼德磨坊南侧的道路附近，在那片庄园外围徘徊的亡灵群中疯狂地喋喋不休。",al={"代弗林的位置","寻找代弗林·阿加曼德","代弗林在哪里"}},{q="瘟疫发生前代弗林是什么样的人？",a="据库勒曼·法席恩所说，代弗林是阿加曼德家中那个个子较小、软弱且格外尖酸刻薄的小儿子，与他身材高大、举止温和的哥哥瑟曼截然不同。",al={"代弗林是谁","代弗林·阿加曼德背景故事","代弗林·阿加曼德生前"}},{q="代弗林是属于天灾军团还是被遗忘者？",a="代弗林是天灾军团的一个无脑傀儡。与幽暗城的被遗忘者不同，他从未摆脱巫妖王的控制，而是无意识地徘徊在他家族荒废的土地上。",al={"代弗林是天灾军团吗","代弗林所属阵营"}},{q="还有哪些任务发生在阿加曼德磨坊？",a="任务“家族的死亡”也会指引被遗忘者冒险者前往阿加曼德磨坊消灭剩余的阿加曼德家族成员，因此同时进行这两项任务是很自然的选择。",al={"阿加曼德磨坊任务","代弗林附近的任务"}},{q="交还代弗林的遗骸后会发生什么？",a="在接受这些骨骸后，库勒曼·法席恩会指引你前往布瑞尔与塞文交谈，这将最终引领你深入阿加曼德家族墓穴。",al={"任务后续","闹鬼的磨坊后的任务"}}},fp="17,329,16.397.0,19.336.0,48.209.0,34.149.0,39.154.0,42.171.0,46.149.0,47.133.1"}
P.entries["quest:3625"] = {n="魔化艾萨拉水晶武器",s="在荆棘谷，铸造大师加尔文正在打造一种专门用于击杀强大恶魔的武器。这种锻造工艺会赋予武器“邪咒”的力量，专门用来削弱拉瑟莱克和他的爪牙。",h="在荆棘谷，铸造大师加尔文正在打造一种专门用于击杀强大恶魔的武器。这种锻造工艺会赋予武器“邪咒”的力量，专门用来削弱拉瑟莱克和他的爪牙。",kw={"艾萨拉矿石","诅咒之地","邪能杀手","邪咒","加尔文","亵渎者拉瑟莱克","荆棘谷"},sec={{t="对抗亵渎者的武器",b="加尔文在通往祖尔格拉布的小路南侧工作，他需要耐心的等待。如果催促他锻造，可能会得到一把有瑕疵的利刃、法杖或匕首。一旦锻造完成，这把武器就蕴含了“邪咒”的力量，可以定期释放以削弱拉瑟莱克和他的恶魔部下。这个削弱诅咒的持续时间是不固定的。"}},faq={{q="谁锻造了这些武器？",a="武器是由加尔文锻造的，这位铸造大师位于荆棘谷通往祖尔格拉布的道路南侧。",al={"谁制作了武器","加尔文","谁是铁匠"}},{q="锻造出的武器拥有什么力量？",a="这把武器能够引导“邪咒”，这是一种专门用于削弱恶魔拉瑟莱克及其爪牙的特殊魔法。其削弱效果的持续时间各不相同。",al={"武器有什么作用","邪咒力量","邪咒如何运作"}},{q="武器锻造完成后，接下来该去哪？",a="一旦加尔文完成锻造并将成品交给玩家，任务指引将带你重返诅咒之地。",al={"下一步","接下来去哪里","下一个任务"}}},fp="32,278,28.391.0,25.127.0,39.163.0,55.132.0"}
P.entries["quest:3626"] = {n="返回诅咒之地",s="带着新铸造的武器，你被指引着从荆棘谷返回诅咒之地。部落英雄的灵魂正在等你回来，让你去对付恶魔拉泽里克。",h="带着新铸造的武器，你被指引着从荆棘谷返回诅咒之地。部落英雄的灵魂正在等你回来，让你去对付恶魔拉泽里克。",kw={"诅咒之地","部落英雄的灵魂","魔铁武器","加尔文","拉泽里克","救赎","荆棘谷"},sec={{t="救赎的召唤",b="在你的附魔武器制作完成后，加尔文宣称救赎的时刻已经到来。你带着新制作的武器回到诅咒之地，寻找部落英雄的灵魂。这位幽灵战士问你是否准备好面对拉泽里克和他的爪牙了。"}},faq={{q="谁让你回到诅咒之地的？",a="加尔文指示你带着新锻造的武器回到诅咒之地。",al={"谁发布了这个任务","任务发布者","加尔文"}},{q="你被派去诅咒之地见谁？",a="你被派去再次与部落英雄的灵魂交谈，他正等着你到来，揭示你最后的对决。",al={"我应该把任务交给谁","在哪里交付任务","部落英雄的灵魂"}},{q="在这一步之前要做什么？",a="这一步紧接在“附魔的艾萨拉魔铁武器”之后，在该任务中你完成了特制的武器。",al={"前置任务","必要条件"}},{q="在诅咒之地等待你的敌人是谁？",a="在你回来后，部落英雄的灵魂会问你是否准备好面对拉泽里克和他的爪牙。",al={"我们正在与谁作战","拉泽里克","最终首领"}}},fp="27,203,20.311.0,40.101.0,47.127.0,28.101.0,51.105.0"}
P.entries["quest:363"] = {n="突然醒来",s="“粗鲁的觉醒”是丧钟镇墓穴中新苏醒的被遗忘者所面临的第一个任务。在你摆脱巫妖王的铁腕掌控死而复生后，你被指引着远离焚化炉，并被送往山下，去从暗影牧师萨维斯那里了解你新生活的真相。",h="“粗鲁的觉醒”是丧钟镇墓穴中新苏醒的被遗忘者所面临的第一个任务。在你摆脱巫妖王的铁腕掌控死而复生后，你被指引着远离焚化炉，并被送往山下，去从暗影牧师萨维斯那里了解你新生活的真相。",kw={"丧钟镇","被遗忘者","巫妖王","摩尔多","粗鲁的觉醒","萨维斯","天灾军团","暗影牧师萨维斯","希尔瓦娜斯","提瑞斯法林地","管理员摩尔多"},ang={["class:Priest"]="向暗影牧师萨维斯报到将立刻带你接触被遗忘者的牧师教团，他们重新诠释了在死后依然存在的精神信仰。",["faction:Horde"]="这次觉醒将你置于部落那脆弱的轨道之中，这是一个为了避免共同灭亡而被迫结成的联盟。",["race:Undead"]="这一刻定义了你的重生：摆脱天灾军团的枷锁，在被遗忘者中开创一种愤世嫉俗但自由的存在。"},sec={{t="墓穴的开端",b="在丧钟镇墓穴阴冷潮湿的地下睁开双眼，这对于死后的你来说是一次令人不安的经历。管理员摩尔多负责看守这些新下葬的尸体，将复活者分为两类：一类是找回了自由意志的，另一类则是注定要被送入火坑的。对于许多人来说，从坟墓中爬出来意味着面对腐烂、冰冷的石头和彻底的迷茫，仅仅是因为机缘巧合才从天灾军团的魔爪中逃脱。"},{t="打破冰封王座的掌控",b="在到达教堂之前，新苏醒的亡灵必须认清一个残酷的真相：他们曾经是巫妖王毫无思想的傀儡。正是希尔瓦娜斯·风行者（Lady Sylvanas Windrunner）打破了这种心灵奴役，让残存的曾经的人性得以重新获得独立的思想。从坟墓中站起并前往丧钟镇，标志着你迈出了踏入这个世界的第一步，在这里，无论是活人还是天灾军团都将你视为必须铲除的怪物。"}},faq={{q="我为什么会在墓穴里？",a="你死去了，死于第三次战争的瘟疫或暴力，并被埋葬在提瑞斯法林地。丧钟镇是主要的聚集点，尸体在这里会被监测，以观察他们是找回了理智，还是陷入了无意识的腐烂。",al={"为什么在墓穴","我在哪儿醒来","丧钟镇墓穴"}},{q="管理员摩尔多是谁？",a="摩尔多是丧钟镇墓穴的看守者。他的职责是看管新苏醒者，引导那些保持理智的人前往城镇教堂，并处理那些未能保持神智清醒而复活的亡灵。",al={"管理员摩尔多","摩尔多是谁","管理员"}},{q="摩尔多为什么要提把人扔进火里？",a="并非每一个从坟墓中复活的尸体都能找回自由意志或稳定的思想。那些完全发疯或彻底野性化的亡灵无法融入被遗忘者的社会，因此必须被消灭并焚烧，以防止他们四处肆虐。",al={"焚烧尸体","扔进火里","火葬"}},{q="是谁让我从巫妖王的掌控中解放出来的？",a="女妖之王希尔瓦娜斯·风行者（Lady Sylvanas Windrunner）在巫妖王的力量减弱时，摆脱了他的心灵控制。她将其他拥有自由意志的亡灵聚集在她的旗帜下，建立了被遗忘者，以对抗他们曾经的主人和充满敌意的生者。",al={"谁解放了我","希尔瓦娜斯解放亡灵","我为什么自由"}},{q="暗影牧师萨维斯在哪里？",a="萨维斯位于丧钟镇山脚下受损的教堂内。走出墓穴，顺着鹅卵石小路下山，就能直接到达教堂入口。",al={"寻找萨维斯","萨维斯位置","教堂在哪里"}},{q="被遗忘者在和谁战斗？",a="被遗忘者为了生存进行着两线作战：对抗试图收回或消灭他们的天灾军团，以及拒绝将他们与无脑怪物区分开来的人类狂热者和幸存定居点。",al={"被遗忘者的敌人","我们在和谁打","亡灵的敌人"}}},fp="14,218,17.318.0,38.392.0,21.200.0,24.202.0,52.197.0,32.262.0,38.169.0,38.214.0"}
P.entries["quest:3633"] = {n="地精工程学",s="地精工程学是为那些寻求对爆炸威力和挥发性冲击武器绝对掌控的大师级发明家所准备的专业技艺路线。在高效爆破粉末和无情火力的驱动下，它为复杂的精巧装置提供了一种毫不妥协的毁灭性替代方案。",h="地精工程学是为那些寻求对爆炸威力和挥发性冲击武器绝对掌控的大师级发明家所准备的专业技艺路线。在高效爆破粉末和无情火力的驱动下，它为复杂的精巧装置提供了一种毫不妥协的毁灭性替代方案。",kw={"爆破粉末","炸弹","工程学","炸药","加基森","地精工程学","尼克斯·斯普罗克特斯普林","热砂港"},ang={["profession:Engineering"]="地精工程学是大师级工程师可选择的两大主要专业传统之一，专门专注于挥发性弹药、重型爆炸产量和灾难性的破坏。",["profession:Mining"]="追求地精技艺的工程师严重依赖精炼矿石、爆破粉末和固体岩石，以为其不间断的燃烧弹和炸弹生产提供燃料。"},sec={{t="爆炸的艺术",b="艾泽拉斯的工程学清晰地划分为两种截然不同的哲学，而地精的思想流派几乎完全围绕着剧烈的燃烧。当其他发明家制作精巧的发条机械或微妙的装置时，地精技师们利用爆破粉末的挥发性能量来锻造出具有惊人破坏力的工具。涉足地精工程学领域，就意味着将火焰、弹片和冲击力视为解决实际问题的终极方案。"},{t="挥发性与力量",b="地精工程学传统从不掩饰其危险性。学徒们会直接接触挥发性化合物、重型燃烧弹和各种原型机，这些东西烧掉制造者眉毛的可能性，与夷平敌方路障的可能性不相上下。从业者以最大化产量和原始破坏潜力为荣，欢迎任何重视决定性火力胜过脆弱安全法规的勇敢工程师。"}},faq={{q="什么是地精工程学？",a="地精工程学是一门专门的工程学科，专注于高威力爆炸的哲学与力量。从业者致力于制作强力炸药、炸弹和重型毁灭装置，而不是像他们的侏儒同行那样偏爱精巧的零件。",al={"什么是地精工程学","地精专精","地精工程学任务"}},{q="地精工程学与侏儒工程学有何不同？",a="虽然侏儒工程学围绕着奇异的辅助装置、复杂的精巧制作和发明性的小玩意，但地精工程学完全专注于纯粹的火力、爆破粉末和挥发性的毁灭产量。地精制造的发明以极具侵略性、有效且使用起来本身就具有危险性而闻名。",al={"地精与侏儒工程学","侏儒还是地精工程学","地精与侏儒工程学的区别"}},{q="谁教授地精工程学？",a="地精工程学由地精工程学大师教授，他们会寻找有能力且愿意拥抱这种充满爆炸和爆破粉末的危险技艺的新手。著名的训练师包括加基森的工程师尼克斯·斯普罗克特斯普林，他在传授这门技艺前会先测试有抱负的候选人。",al={"谁教授地精工程学","在哪里学习地精工程学","地精工程学训练师"}},{q="练习地精工程学有危险吗？",a="在地精发明家眼中，危险是生意中必须接受的成本。他们的设计图纸旨在最大化爆炸输出和冲击力，这自然会导致不可预测的故障、突然的爆炸，以及使用者面临的人身风险。",al={"地精工程学危险","地精炸药会爆炸吗","地精工程学安全吗"}},{q="两个阵营都可以学习地精工程学吗？",a="当联盟和部落的工程师在该技艺上达到足够的熟练度后，都可以训练地精工程学。地精技师主要通过热砂港等中立集团进行操作，乐于欢迎任何拥有稳定的双手、足够的金币以及对爆炸力量充满热爱的人。",al={"任何人都能学习地精工程学吗","联盟地精工程学","部落地精工程学"}},{q="为什么工程师会选择地精学科？",a="工匠们追求地精工程学是因为它无可比拟的破坏能力。该学科能制造致命的战斗炸药、迫击炮、地雷和便携式火箭，旨在彻底消灭战场上的对手。",al={"为什么选择地精工程学","地精工程学制造什么","地精工程学物品"}}},fp="18,250,25.303.0,20.320.0,27.213.0,60.251.0,46.234.0,44.219.0,43.276.0,51.211.0"}
P.entries["quest:364"] = {n="无脑的僵尸",s="暗影牧师萨维斯指派新苏醒的被遗忘者去清理在丧钟镇北缘游荡的无脑僵尸和悲伤的僵尸。这些蹒跚而行的尸体是天灾军团的奴仆，他们没有自由意志，完全受巫妖王的支配。",h="暗影牧师萨维斯指派新苏醒的被遗忘者去清理在丧钟镇北缘游荡的无脑僵尸和悲伤的僵尸。这些蹒跚而行的尸体是天灾军团的奴仆，他们没有自由意志，完全受巫妖王的支配。",kw={"丧钟镇","被遗忘者","巫妖王","无脑者","无脑僵尸","天灾军团","暗影牧师萨维斯","悲伤的僵尸"},ang={["class:Priest"]="在暗影牧师萨维斯的麾下服役，让你接触到了被遗忘者所采用的务实且带有暗影色彩的哲学，这取代了那抛弃了他们的圣光。",["faction:Horde"]="像这类奴仆的存在，说明了为什么部落在允许被遗忘者加入之前，会以如此深度的怀疑眼光看待他们。",["race:Undead"]="每一个在村庄外围游荡的僵尸，生前都可能是你的邻居、亲属或朋友，这时刻提醒着你：你所幸免于难的遭遇是什么，以及如果被遗忘者失败会发生什么。"},sec={{t="冰封王座的奴隶",b="并非所有从洛丹伦的土地上爬起来的人都能恢复神智。当巫妖王的力量减弱时，被遗忘者们挣脱了他的精神控制，但仍有无数尸体依然是受他意志束缚的空壳。在丧钟镇北部，这些无脑僵尸和悲伤的僵尸漫无目的地游荡，除了原始的暴力本能外别无他求。对于一个新苏醒的亡灵来说，消灭他们是生存的第一道苦涩考验——通过斩断那些从未获得自由者的枷锁，来证明自己的自主权。"},{t="毁灭即是慈悲",b="尽管暗影牧师萨维斯感叹这些庞大的死者军团无法被招募来加强被遗忘者绝望的斗争，但他们已经无法治愈。这些无脑亡灵是永远破碎的杀戮工具。留着他们游荡只会给丧钟镇带来混乱，并为巫妖王提供现成的炮灰。消灭他们既是战术上的必要，也是对洛丹伦沦陷子民的一种残酷的终结。"}},faq={{q="为什么无脑僵尸不能被招募进被遗忘者阵营？",a="他们缺乏摆脱巫妖王控制的认知能力。暗影牧师萨维斯指出，虽然他们的数量非常可观，但他们的心智已经完全退化。由于他们无法选择加入希尔瓦娜斯女王的麾下，他们依然是必须被肃清的危险天灾军团奴仆。",al={"招募无脑僵尸","为什么要杀死他们","无脑僵尸可以治愈吗","解放僵尸"}},{q="这些僵尸原本是什么人？",a="他们是洛丹伦的前人类居民，在第三次战争中死于亡灵瘟疫。与玩家角色不同，当巫妖王的控制松动时，他们从未找回自己的记忆、个性和个人意识。",al={"无脑者是谁","无脑僵尸的身份","丧钟镇的尸体"}},{q="为什么暗影牧师萨维斯在这里指挥防御？",a="暗影牧师萨维斯负责监管丧钟镇新苏醒亡灵的初步接收和生存状况。他会评估这些新苏醒的被遗忘者是否具备在残酷现实中生存所需的勇气和清晰的思维。",al={"萨维斯是谁","萨维斯在丧钟镇的角色","牧师萨维斯"}},{q="被遗忘者和天灾军团的僵尸有什么区别？",a="自由意志。被遗忘者挣脱了巫妖王的心灵控制，拥有自我决定权、智慧和情感。天灾军团的僵尸只是被巫妖王的恶意直接操纵的空壳。",al={"天灾军团与被遗忘者","被遗忘者与无脑者的区别","为什么有些僵尸是无脑的"}},{q="无脑僵尸对丧钟镇构成威胁吗？",a="是的。他们在村庄北面游荡，其攻击性对刚从墓穴中爬出的新人以及试图组织定居点的被遗忘者牧师构成了直接威胁。",al={"丧钟镇的危险","为什么要清理丧钟镇北部","僵尸威胁"}},{q="这项任务接下来会指向哪里？",a="在证明了自己对抗无脑亡灵的能力后，将承担更多保卫丧钟镇的职责，例如在“嘎嘎作响的牢笼”中清理天灾骷髅，以及在职业训练师处进行初步训练。",al={"无脑者之后的下一个任务","无脑者后续","what comes next"}}},fp="17,203,27.425.0,25.397.0,62.210.0,33.222.0,56.165.0,60.205.0,48.152.0,31.190.0"}
P.entries["quest:365"] = {n="悲伤之地",s="“悲伤的田野”是亡灵卫兵希米尔在丧钟镇以北的道路旁分派的一项早期被遗忘者任务。它要求初出茅庐的冒险者去突袭一处活人农场，为布瑞尔的皇家药剂师学会收集提瑞斯法南瓜。",h="“悲伤的田野”是亡灵卫兵希米尔在丧钟镇以北的道路旁分派的一项早期被遗忘者任务。它要求初出茅庐的冒险者去突袭一处活人农场，为布瑞尔的皇家药剂师学会收集提瑞斯法南瓜。",kw={"药剂师乔汉","布瑞尔","亡灵卫兵希米尔","丧钟镇","悲伤的田野","皇家药剂师学会","血色十字军","提瑞斯法南瓜"},ang={["faction:Horde"]="巩固提瑞斯法林地需要打破人类残留的影响，并拆除血色十字军沿南部道路的势力。",["profession:Herbalism"]="药剂师们非常依赖提瑞斯法扭曲的植物群来配制致命的药剂，这使得当地的每一根根茎和作物都成为了战争的试剂。",["race:Undead"]="这项任务标志着你在丧钟镇之外的第一项军事任务，证明了你愿意剥夺昔日人类同胞的生计，以推动皇家药剂师学会的事业。"},sec={{t="生存课",b="对于刚从丧钟镇墓穴中复活的被遗忘者冒险者来说，踏上提瑞斯法林地雾气弥漫的道路，就是一堂关于敌意的速成课。亡灵卫兵希米尔代表了Sylvanas Windrunner军队务实的恶意：生存意味着夺取活人拥有的东西，并将其用于幽暗城更黑暗的事业中。"},{t="突袭活人",b="突袭的目标是那些试图在丧钟镇以北、道路以西的腐化土地上耕作的人类农夫。在卫兵口中，这些人就像尸体上的霉菌一样侵蚀着这片土地。在附近血色十字军塔楼不安的保护下，这些农民紧守着自己的家园。夺走他们的庄稼不仅能打击他们的补给，还能满足皇家药剂师学会对试剂永无止境的需求。"},{t="学会的补给",b="被窃取的南瓜会被直接送到布瑞尔，交给在那里进行实验研究的药剂师乔汉。皇家药剂师学会经常使用当地的农产品和植物作为炼金药剂、毒药和瘟疫研究的基底，旨在巩固被遗忘者在洛丹伦北部那摇摇欲坠的立足点。"}},faq={{q="是谁发布了“悲伤的田野”任务？",a="任务由亡灵卫兵希米尔发布。他驻守在提瑞斯法林地南部的道路上，就在丧钟镇出口路径的北边。",al={"任务发布者","悲伤的田野任务开启","谁发布悲伤的田野"}},{q="我该把提瑞斯法南瓜送到哪里？",a="你需要把十个南瓜交给位于东边提瑞斯法林地布瑞尔镇的药剂师乔汉。",al={"南瓜上交地点","上交南瓜","悲伤的田野交任务"}},{q="为什么提瑞斯法林地里会有活人农民？",a="这些人类农民是洛丹伦原有居民的残余，他们在第三次战争和天灾瘟疫中幸存了下来。他们顽固地守在附近血色十字军哨所的阴影下，抗拒着被遗忘者的统治。",al={"为什么这里有人类","提瑞斯法活人","为什么亡灵区有人类"}},{q="药剂师乔汉为什么需要南瓜？",a="皇家药剂师学会利用各种植物、腐化的农作物和生物质作为测试剂，以及他们炼金混合物、毒药和实验性瘟疫的基础成分。",al={"为什么要南瓜","南瓜的用途","药剂师乔汉南瓜"}},{q="谁在农场附近巡逻？",a="来自附近瞭望塔的血色十字军狂热者会巡逻到这里，保护人类定居点并试图肃清任何靠近田野的亡灵。",al={"农场附近的血色十字军","谁保护农场"}},{q="“悲伤的田野”之后是什么任务？",a="交还南瓜后，药剂师乔汉会立即发布同名的后续任务，交给你一个涂抹了他最新配方的南瓜，让你送给关押在恐惧之末旅店地窖里的血色十字军俘虏。",al={"后续任务","悲伤的田野后续","悲伤的田野之后的内容"}}},fp="15,165,20.225.0,18.364.0,24.311.1,36.133.0,38.86.0,55.211.0,41.238.0,31.143.0,33.228.0"}
P.entries["quest:366"] = {n="归还书籍",s="比索·埃斯沙德对冈瑟尔·阿坎努斯被窃的法术书施加了附魔，以证明他已重获自由，并试图将他以前在肯瑞托的同僚招募到被遗忘者麾下。将这本书带回冈瑟尔隐居的岛屿后，两人发现这位前法师并非巫妖王的奴仆。",h="比索·埃斯沙德对冈瑟尔·阿坎努斯被窃的法术书施加了附魔，以证明他已重获自由，并试图将他以前在肯瑞托的同僚招募到被遗忘者麾下。将这本书带回冈瑟尔隐居的岛屿后，两人发现这位前法师并非巫妖王的奴仆。",kw={"比索·埃斯沙德","澈水湖","达拉然","冈瑟尔·阿坎努斯","冈瑟尔的居所","冈瑟尔的法术书","肯瑞托","归还法术书","thule ravenclaw","提瑞斯法林地"},ang={["class:Mage"]="这次交流凸显了前肯瑞托法师之间深厚的羁绊，即使在亡灵的帷幕之后，他们依然能识别彼此独特的奥术签名。",["faction:Horde"]="招募像冈瑟尔这样独立的亡灵施法者，增强了幽暗城对抗天灾军团和血色十字军的奥术实力。",["race:Undead"]="冈瑟尔的困境反映了被遗忘者的根本挣扎：从毫无理智的奴役梦魇中醒来，却发现自己面对的是一个孤立且充满敌意的世界。"},sec={{t="奥术墨迹传书",b="在发现澈水湖上的亡灵法师正是他当年的同伴冈瑟尔·阿坎努斯后，比索·埃斯沙德想出了一个绝妙的通讯方法。此前，比索曾下令窃取冈瑟尔的法术书以查明其真实身份，现在他在这本书的页面中编织了一道复杂的魔法。这种附魔并非为了提出要求或进行武装交涉，而是一个奥术签名，证明比索不仅活跃在洛丹伦，而且已经完全摆脱了巫妖王的精神控制。"},{t="达拉然的旧日圈子",b="在第三次战争摧毁洛丹伦之前，比索·埃斯沙德、冈瑟尔·阿坎努斯和Thule Ravenclaw曾是达拉然肯瑞托的同学和朋友。当巫妖王崛起时，他们的道路分道扬镳：Thule背叛了同胞并自愿投靠天灾军团，而比索和冈瑟尔都死于瘟疫。后来，比索在希尔瓦娜斯女王的带领下重获自由。比索原以为冈瑟尔已死或被奴役，当他意识到冈瑟尔也实现了自主的亡灵化时，便急切地想要将他拉拢到被遗忘者阵营中。"},{t="岛上的不信任",b="当被遗忘者出现在他隐居的岛屿时，冈瑟尔起初愤怒地反击，认为任何闯入澈水湖的人都是天灾军团的特务，企图再次奴役他，又或者是那个偷走他魔法书的小偷。当看到他自己的法术书，并感受到比索那种熟悉的魔法共鸣时，这位隐居的法师感到十分惊讶。意识到自己过去的人打破了天灾军团的枷锁，促使冈瑟尔重新审视他绝对孤立的状态。"}},faq={{q="为什么比索要给冈瑟尔的法术书施加附魔？",a="比索在偷来的法术书上施加了带有个人奥术签名的附魔，以向冈瑟尔证明他确实已经摆脱了巫妖王的控制。鉴于冈瑟尔的极度偏执和对天灾军团的憎恨，如果派普通的信使去，很可能会被拒之门外甚至直接被杀。",al={"为何附魔书籍","冈瑟尔的法术书","比索对书籍做了什么"}},{q="冈瑟尔·阿坎努斯死前是谁？",a="冈瑟尔·阿坎努斯曾是达拉然肯瑞托的一名人类法师和学者。在第三次战争之前，他曾与比索·埃斯沙德和Thule Ravenclaw一同学习，最终死于天灾军团的亡灵瘟疫。",al={"冈瑟尔·阿坎努斯是谁","冈瑟尔背景故事","冈瑟尔传说"}},{q="为什么冈瑟尔躲在澈水湖？",a="在摆脱了巫妖王的控制后，冈瑟尔认为他孑然一身。为了避免被天灾军团猎杀并重新奴役，或被生者敌人杀死，他便独自躲藏在澈水湖的一座岛屿上。",al={"为何冈瑟尔在岛上","冈瑟尔的隐居点传说","为何冈瑟尔离开"}},{q="Thule Ravenclaw是谁？",a="Thule Ravenclaw是比索和冈瑟尔在达拉然肯瑞托求学圈子里的第三名成员。与打破枷锁的比索和冈瑟尔不同，Thule自愿留在了天灾军团，成为了一名效忠于巫妖王的亡灵法师，活跃在银松森林。",al={"谁是thule","thule ravenclaw传说","第三个朋友"}},{q="为什么冈瑟尔认为玩家是小偷？",a="早些时候，比索指使被遗忘者冒险者潜入冈瑟尔的圣所并偷走了他的法术书，以便比索验证是谁在湖上进行亡灵法术研究。冈瑟尔准确地认出了带书回来的冒险者就是那个洗劫他的人。",al={"为何冈瑟尔叫我小偷","我偷了冈瑟尔的书吗","被偷的书"}},{q="冈瑟尔会立即加入被遗忘者吗？",a="不会立刻加入。虽然冈瑟尔对比索还活着且拥有自由意志感到震惊，但他对被遗忘者仍持怀疑态度，并需要证明玩家是天灾军团的敌人：通过在岛屿南岸的一个古老祭坛上召唤并消灭天灾特工Lillith Nefara来证明这一点。",al={"冈瑟尔是否加入希尔瓦娜斯","冈瑟尔的立场","冈瑟尔接下来会怎样"}}},fp="15,171,23.308.0,25.468.0,22.329.1,43.201.0,39.204.0,42.202.0,23.190.0,45.210.0,43.237.1"}
P.entries["quest:367"] = {n="新的瘟疫",s="\"The New Plague\"是布瑞尔的一项入门任务，揭示了被遗忘者宏大的战略抱负。药剂师乔汉指派新兵去收集野生黑暗犬的血液，为Sylvanas Windrunner亲自下令研发的一种剧毒病原体奠定基础。",h="\"The New Plague\"是布瑞尔的一项入门任务，揭示了被遗忘者宏大的战略抱负。药剂师乔汉指派新兵去收集野生黑暗犬的血液，为Sylvanas Windrunner亲自下令研发的一种剧毒病原体奠定基础。",kw={"药剂师","阿尔萨斯","布瑞尔","黑暗犬","乔汉","瘟疫","天灾军团","sylvanas","提瑞斯法"},ang={["faction:Horde"]="虽然被遗忘者已经加入了部落，但他们在提瑞斯法林地的炼金术研究完全集中在一种针对诺森德的残酷生物武器上。",["race:Undead"]="这个任务标志着你首次为皇家药剂师学会的主计划做出了直接贡献：制造Sylvanas计划用来对付阿尔萨斯的武器。"},sec={{t="皇家指令",b="在潮湿的布瑞尔村，药剂师乔汉代表皇家药剂师学会工作，执行来自黑暗女王的直接指令。Sylvanas Windrunner已命令她的炼金术士制造一种艾泽拉斯从未见过的疾病。虽然最初的亡灵瘟疫服务于巫妖王，通过屠杀人类并束缚他们的灵魂来达成目的，但这全新的创造旨在彻底消灭阿尔萨斯·米奈希尔，并摧毁他的天灾军团。"},{t="原材料",b="开发一种能够摧毁亡灵的生物武器需要残酷的实验。乔汉认为，本土野兽的血液——首先是游荡在提瑞斯法林地阴暗处的凶猛黑暗犬——具有至关重要的化学特性。通过收集这些受污染的动物血液，乔汉开始分离其中的元素，以测试本土生物的天然韧性和掠食性生物学特征是否能催化一种致命的传染病。"}},faq={{q="新瘟疫的目标是什么？",a="Sylvanas女士指派皇家药剂师学会酿造一种比艾泽拉斯任何其他疾病都更致命的瘟疫。其主要的战略目标是彻底消灭阿尔萨斯和他的天灾军团。",al={"为什么要制造新瘟疫","新瘟疫的目的","瘟疫的作用"}},{q="药剂师乔汉是谁？",a="乔汉是驻扎在布瑞尔镇的皇家药剂师学会的一员。他负责早期的实地实验，测试从提瑞斯法林地本土动物群中收集的生物化合物。",al={"乔汉是谁","药剂师乔汉背景故事"}},{q="为什么乔汉需要黑暗犬的血液？",a="乔汉的研究表明，本土野兽的血液可以作为他炼金配方的关键基础。他需要黑暗犬的血液来在实验室中验证他的初步理论。",al={"为什么要黑暗犬的血液","血液的用途"}},{q="这种瘟疫与天灾军团的瘟疫有何不同？",a="最初的亡灵瘟疫是由巫妖王设计的，旨在屠杀生灵并将他们转化为奴仆。Sylvanas的新瘟疫是专门设计的一种武器，旨在为阿尔萨斯的亡灵军团带来毁灭。",al={"两种瘟疫的区别","天灾瘟疫与被遗忘者瘟疫"}},{q="谁下令制造这种瘟疫的？",a="Sylvanas Windrunner女士直接命令皇家药剂师学会发明它，她认为被遗忘者的炼金术结合新发现的魔法是击败阿尔萨斯的关键。",al={"谁发起的瘟疫研究","谁想要瘟疫"}},{q="收集血液后会发生什么？",a="收集黑暗犬的血液只是一系列持续实验的第一步。乔汉利用这些样本，通过在林地各处进行进一步的实地测试，开始提炼这种病原体。",al={"下一步是什么","瘟疫有效吗"}}},fp="12,183,15.391.0,15.364.0,35.167.0,25.164.0,37.161.0,54.175.0,40.170.0,39.151.0"}
P.entries["quest:368"] = {n="新的瘟疫",s="药剂师乔汉在布瑞尔指派了这项任务，需要从徘徊在提瑞斯法林地海岸的当地邪鳍鱼人身上收集鳞片。皇家药剂师学会旨在利用独特的生物试剂来提炼他们正在研发的新型瘟疫，确保其传播范围能超越零星的受害者，进而吞噬更大规模的人群。",h="药剂师乔汉在布瑞尔指派了这项任务，需要从徘徊在提瑞斯法林地海岸的当地邪鳍鱼人身上收集鳞片。皇家药剂师学会旨在利用独特的生物试剂来提炼他们正在研发的新型瘟疫，确保其传播范围能超越零星的受害者，进而吞噬更大规模的人群。",kw={"新型瘟疫","药剂师乔汉","布瑞尔","鱼人","皇家药剂师学会","提瑞斯法林地","邪鳍鱼人的鳞片"},ang={["faction:Horde"]="被遗忘者将他们的新型瘟疫作为对抗天灾军团的武器，这也是他们为部落共同参与的战争所做出的严酷贡献。",["race:Undead"]="对被遗忘者而言，协助药剂师乔汉是为他们种族的终极武器与防御做出的直接贡献：制造一种专门用于保护其主权领土并消灭敌人的致命瘟疫。"},sec={{t="增强瘟疫",b="毒杀单一目标只是简单的炼金术，但要配制出能横扫整片土地的瘟疫则需要更复杂的成分。药剂师乔汉在布瑞尔的持续研究关键在于制造一种能够自我传播并能在野外存活的疾病。为了设计这种传染性，他将目光转向了提瑞斯法林地的海岸野生生物，认定沿海邪鳍鱼人那强韧的生物机能是原材料的理想来源。"},{t="邪鳍鱼人试剂",b="提瑞斯法林地的北部和西部海岸饱受被称为邪鳍的凶猛鱼人部落侵扰。收割它们的鳞片为乔汉提供了适应潮湿、恶劣环境的有机化合物。通过将鱼人那湿滑且强韧的鳞片加入他研制中的大锅，这位药剂师试图增强皇家药剂师学会新型瘟疫的毒性和环境稳定性。"}},faq={{q="药剂师乔汉的研究目标是什么？",a="乔汉正在代表皇家药剂师学会和Sylvanas Windrunner开发一种新型瘟疫。他的目标远不止制造简单的毒药；他正在研制一种旨在横扫整个人群和土地的传染病，其目标涵盖了生者与天灾军团。",al={"为什么要制造新瘟疫","乔汉研究瘟疫的目的","乔汉在做什么"}},{q="为什么乔汉特别需要鱼人鳞片？",a="乔汉在初步酿制时发现，简单的毒药缺乏有效传播所需的生物复杂性。邪鳍鱼人那坚韧且覆盖粘液的鳞片提供了特定的生物化合物，这是改善瘟疫在野外生存能力和宿主间传播能力所必需的。",al={"为什么要用鱼人鳞片","邪鳍鱼人鳞片的用途","为什么瘟疫需要鳞片"}},{q="邪鳍鱼人在哪里可以找到？",a="邪鳍鱼人居住在提瑞斯法林地的海岸线上，主要集中在与无尽之海接壤的北部海滩以及西部海岸沿岸。",al={"提瑞斯法林地的鱼人在哪","邪鳍鱼人的位置","鱼人刷新点"}},{q="药剂师乔汉听命于谁？",a="药剂师乔汉是皇家药剂师学会的一名成员，这是一个总部位于幽暗城的炼金术公会，直接听命于女王Sylvanas Windrunner。",al={"谁领导药剂师学会","乔汉的上司","皇家药剂师学会领袖"}},{q="这个任务线的下一步是什么？",a="在将邪鳍鱼人鳞片交给乔汉后，他将继续提炼配方，这需要寻找更多的生物成分，并最终对新酿制的毒株进行测试。",al={"what comes next","收集邪鳍鱼人鳞片之后","下一个瘟疫任务"}},{q="被遗忘者是否会因为使用鱼人部位而感到不安？",a="完全不会。皇家药剂师学会以务实和不择手段而闻名，他们会毫不犹豫地从任何当地植物、动物或野兽身上收割其实验所需的生物化学特性。",al={"鱼人炼金术是否危险","为什么要收割鱼人"}}},fp="12,233,24.331.0,21.343.0,49.220.0,48.241.0,40.143.0,37.169.0,42.171.0,52.175.0"}
P.entries["quest:3681"] = {n="圣洁之书",s="《圣洁之书》是一项旨在引导前往铁炉堡的人类圣骑士进行深造的征召令。布兰度尔·铁锤大师要求见习圣骑士南下前往暴风城的Cathedral of Light，在那里由达索瑞恩·拉尔大师指导他们研习神圣的《圣洁之书》进阶课程。",h="《圣洁之书》是一项旨在引导前往铁炉堡的人类圣骑士进行深造的征召令。布兰度尔·铁锤大师要求见习圣骑士南下前往暴风城的Cathedral of Light，在那里由达索瑞恩·拉尔大师指导他们研习神圣的《圣洁之书》进阶课程。",kw={"布兰度尔·铁锤","cathedral of light","达索瑞恩·拉尔","铁炉堡","圣骑士","救赎","暴风城","圣洁之书"},ang={["class:Paladin"]="这项任务标志着你正式从一名普通的武力新兵转变为一名受戒的圣光仆从，能够引导其最深奥的恢复奇迹。",["faction:Alliance"]="暴风城对神圣战士的共同训练，加强了团结铁炉堡与暴风城王国的精神与军事纽带。",["race:Dwarf"]="矮人圣骑士在卡兹莫丹开创了属于自己的光荣传统，即使人类兄弟被召集前往暴风城，他们依然在铁炉堡研习《圣洁之书》。"},sec={{t="来自暴风城的征召",b="当矮人圣骑士在铁炉堡的Hall of Mysteries内刻苦训练时，白银之手的传统依然与人类国度的圣光教会紧密相连。来自暴风城的指令召唤着那些有前途的神圣战士，要求他们直接前往Cathedral of Light，向资深祭司和圣骑士导师们报到。"},{t="前往大教堂之路",b="布兰度尔·铁锤大师能够识别出学员何时已进步到可以探究信仰更深奥秘的程度。无论你是乘坐地下的矿道地铁还是翻越山口向南进发，启程前往暴风城的大教堂区后，达索瑞恩·拉尔都会在那里指导你研习神圣法典并掌握救赎仪式。"}},faq={{q="为什么铁炉堡的训练师要派我去暴风城？",a="暴风城的Cathedral of Light是联盟圣骑士进阶教学的行政中心。布兰度尔·铁锤将有前途的见习圣骑士引荐给达索瑞恩·拉尔大师，以便他们能够进行与神圣《圣洁之书》相关的特定教义试炼。",al={"为什么要去暴风城","为什么要派往达索瑞恩·拉尔处","铁炉堡至暴风城圣骑士"}},{q="布兰度尔·铁锤是谁？",a="布兰度尔·铁锤是一位矮人圣骑士训练师，驻守在铁炉堡Mystic Ward的Hall of Mysteries。他监管着见习者，教导他们武力奉献之道，并在他们与圣光的内在联系成熟时引导他们进行更高阶的学习。",al={"布兰度尔·铁锤","布兰度尔是谁"}},{q="达索瑞恩·拉尔是谁？",a="达索瑞恩·拉尔是一位资深圣骑士训练师兼高级教士，驻守在暴风城的Cathedral of Light内。在将《圣洁之书》托付给他们之前，他会通过严格的精神试炼直接考核那些有志成为圣骑士的人。",al={"达索瑞恩·拉尔","达索瑞恩是谁"}},{q="什么是《圣洁之书》？",a="《圣洁之书》是圣光教会用于教导圣骑士复活、自我牺牲和坚定同情心等庄严仪式的神圣文本与教义手册。",al={"什么是圣洁之书","圣洁之书的含义"}},{q="从铁炉堡前往暴风城最快的方式是什么？",a="最快捷且安全的路线是矿道地铁，这是一项位于铁炉堡Tinker Town内的工程奇迹，它载着旅客直接穿过群山下方，直达暴风城中心。",al={"如何前往暴风城","矿道地铁去暴风城"}},{q="所有联盟圣骑士都需要进行这项试炼吗？",a="不是。这项征召针对的是在暴风城Cathedral of Light跟随达索瑞恩·拉尔研习《圣洁之书》的人类圣骑士。矮人圣骑士则由蒂萨·热炉在铁炉堡开启他们自己的《圣洁之书》试炼。",al={"矮人必须做这个任务吗","圣骑士职业任务要求"}}},fp="16,206,24.219.0,25.284.0,52.200.0,26.231.0,22.192.0,31.174.0,58.159.0,49.183.0"}
P.entries["quest:369"] = {n="新的瘟疫",s="在布瑞尔，药剂师乔汉致力于为被遗忘者研发一种强力的新型生物药剂。通过研究古籍，他发现一种历史上致命的瘟疫通过提瑞斯法东部的夜蛛毒液得以留存，从而引发了一次紧急的回收行动。",h="在布瑞尔，药剂师乔汉致力于为被遗忘者研发一种强力的新型生物药剂。通过研究古籍，他发现一种历史上致命的瘟疫通过提瑞斯法东部的夜蛛毒液得以留存，从而引发了一次紧急的回收行动。",kw={"新瘟疫","药剂师乔汉","布瑞尔","夜蛛","皇家药剂师学会","提瑞斯法林地","毒液","毒蛛峡谷"},ang={["faction:Horde"]="虽然被遗忘者的研究人员欢迎兽人或牛头人盟友的帮助，但他们那些本质残酷的生物实验经常让部落的其他成员感到不安。",["race:Undead"]="对于被遗忘者来说，制造一种原创武器是抵御家门口那些无休止的天灾余孽和血色十字军的唯一持久保障。"},sec={{t="发掘古老的瘟疫",b="在布瑞尔为皇家药剂师学会进行炼金研究时，药剂师乔汉翻阅了大量古籍，寻找更致命的混合剂。他发现了一些关于古老瘟疫的记录，这种瘟疫曾夺走数千人的生命。至关重要的是，文献指出这种致命的病原体通过寄生在提瑞斯法林地的本土蛛形纲动物体内，得以代代相传，这使得它们的毒液成为了一种无价的生物试剂。"},{t="在毒蛛峡谷狩猎",b="为了获得可用的病原体样本，乔汉派遣特工前往提瑞斯法林地的东部。在血色修道院南面坐落着毒蛛峡谷，这是一个迷雾笼罩的洼地，到处都是凶猛的夜蛛。采集者必须深入它们的巢穴提取新鲜的毒腺，以获得完成乔汉实验性药剂所需的最后一种原料。"},{t="调配最终制剂",b="收到采集到的毒液后，乔汉将其与之前收集的试剂一起放入沸腾的坩埚中。随着混合物被煮沸并准备就绪，来自蜘蛛的传染性成分完成了这种化合物的调配，使皇家药剂师学会距离实战测试又近了一步。"}},faq={{q="药剂师乔汉为什么需要蜘蛛毒液？",a="乔汉发现了一份古老的文献，其中描述了一种曾导致数千人死亡的古老瘟疫，其剧毒毒株天然地保存在提瑞斯法夜蛛的毒液中。他打算利用这种传染性成分来调制他的混合药剂。",al={"为什么需要蜘蛛毒液","药剂师乔汉与蜘蛛","蜘蛛毒液的用途"}},{q="凶猛的夜蛛住在哪里？",a="它们栖息在提瑞斯法林地东部的毒蛛峡谷中，就在血色修道院的南面。",al={"夜蛛在哪里","夜蛛位置","毒蛛峡谷位置"}},{q="皇家药剂师学会在此的研究目的是什么？",a="该学会试图合成一种新的致命毒株，能够同时消灭天灾军团和活着的生物，从而巩固被遗忘者在洛丹伦的生存与独立。",al={"为什么要制造新瘟疫","被遗忘者瘟疫的目标","皇家药剂师学会瘟疫"}},{q="药剂师乔汉是谁？",a="乔汉是一位隶属于皇家药剂师学会、驻扎在布瑞尔的被遗忘者研究员。他负责监督当地的化学和生物实验，将黑暗炼金术与从野外采集的提瑞斯法试剂相结合。",al={"乔汉是谁","药剂师乔汉背景"}},{q="毒液采集之后会发生什么？",a="一旦乔汉将毒液煮沸并调配入药剂，他就会准备直接测试这种化合物，以确定由此产生的毒性药剂是否具有预期的致命性。",al={"接下来发生什么","新瘟疫任务后续","新瘟疫之后"}},{q="这是创造了天灾军团的那种瘟疫吗？",a="不。天灾军团传播的是由巫妖王创造的亡灵瘟疫。被遗忘者的药剂师们正在刻意研发一种他们自己设计的、完全不同的生物武器。",al={"这是天灾瘟疫吗","亡灵瘟疫的区别"}}},fp="12,140,29.295.0,25.275.0,29.250.1,45.178.0,44.107.0,65.182.0,25.209.0,42.140.1,49.153.0"}
P.entries["quest:37"] = {n="失踪的卫兵",s="“寻找失踪的卫兵”是一项由艾尔文森林东部大桥的卫兵托马斯委派的调查任务。卫兵罗尔夫和马拉克被派去巡逻河岸，防范鱼人的侵扰，但他们随后失踪，托马斯急需确认他们的命运。",h="“寻找失踪的卫兵”是一项由艾尔文森林东部大桥的卫兵托马斯委派的调查任务。卫兵罗尔夫和马拉克被派去巡逻河岸，防范鱼人的侵扰，但他们随后失踪，托马斯急需确认他们的命运。",kw={"艾尔文森林","寻找失踪的卫兵","卫兵托马斯","被吃了一半的尸体","马拉克","马拉克·斯通","鱼人","罗尔夫"},ang={["class:Paladin"]="缅怀牺牲的守卫并找回他们的个人徽章，能为守护王国边境的士兵带来慰藉与正义。",["faction:Alliance"]="步兵在靠近暴风城的地方惨遭不幸，这凸显了艾尔文森林的外围边界在野兽和鱼人的攻击面前是多么脆弱。"},sec={{t="消失的巡逻队",b="卫兵托马斯站在艾尔文森林的东部交叉路口守望，那里是通往赤脊山的国王之路。当地水域因鱼人的侵扰而变得日益危险。几天前，托马斯派遣了两名暴风城卫兵——罗尔夫和马拉克——沿河岸北上，侦察威胁并清理巢穴。当两名士兵都没有返回时，托马斯不得不接受这样一个事实：某种暴力事件中断了他们的任务。"},{t="残酷的发现",b="沿着河流向北前往石碑湖岸边，就会直接进入鱼人密集的领地。在水边，冒险者发现了一个恐怖的景象：一具被吃了一半的尸体留在泥泞中。在残缺的尸体旁丢弃着一枚刻有“步兵马拉克·斯通”名字的奖章，这证实了一名卫兵的悲惨结局，而罗尔夫的下落仍然不明。"}},faq={{q="是谁发布了这个任务，他们位于哪里？",a="卫兵托马斯负责分配这项任务。他驻扎在艾尔文森林东部边界的河边，守护着通往赤脊山的大桥。",al={"任务发布者","卫兵托马斯在哪里","谁开启寻找失踪的卫兵任务"}},{q="失踪的卫兵是谁？",a="失踪的人是罗尔夫和马拉克，他们是两名暴风城步兵，被卫兵托马斯派去侦察河岸并监视好战的鱼人活动。",al={"艾尔文森林失踪卫兵","罗尔夫和马拉克是谁","失踪卫兵的名字"}},{q="在哪里发现了遗体？",a="步兵马拉克·斯通被吃了一半的遗体躺在卫兵托马斯哨所北部的河东岸，靠近鱼人聚居地的外围。",al={"马拉克尸体在哪里","被吃了一半的尸体位置","失踪卫兵位置"}},{q="是什么杀死了马拉克？",a="马拉克被当地的河流鱼人所淹没并吃掉，这些鱼人已经侵扰了艾尔文森林东部的河岸。",al={"马拉克怎么死的","谁杀了这些卫兵"}},{q="罗尔夫发生了什么事？",a="人们在河边只发现了马拉克的遗体。罗尔夫的命运仍是一个未解之谜，需要进一步深入鱼人营地进行追踪。",al={"罗尔夫在哪里","罗尔夫活下来了吗"}},{q="为什么卫兵被单独派出去？",a="由于暴风城的兵力分散在多个领地，像卫兵托马斯的哨所这样的小型驻军只能依靠最少两人一组的巡逻队来监视荒野边界。",al={"为什么派他们出去","暴风城卫兵短缺"}}},fp="20,92,17.254.0,14.257.1,47.124.0,27.129.0,28.151.1,20.97.1,22.141.1,35.160.0"}
P.entries["quest:370"] = {n="与血色十字军的战争",s="执行官塞加德指派被遗忘者勇士去消灭布瑞尔西南方一座废墟塔楼里的佩林队长及其驻军。利用在丧钟镇回收的情报，被遗忘者旨在击退威胁他们边境的狂热十字军。",h="执行官塞加德指派被遗忘者勇士去消灭布瑞尔西南方一座废墟塔楼里的佩林队长及其驻军。利用在丧钟镇回收的情报，被遗忘者旨在击退威胁他们边境的狂热十字军。",kw={"布瑞尔","佩林队长","执行官阿伦","执行官塞加德","死亡证明","废墟塔楼","血色十字军","血色传教士","血色狂热者","提瑞斯法林地"},ang={["faction:Horde"]="部落在东部王国的立足点依赖于被遗忘者保卫提瑞斯法林地，抵御敌对的人类狂热分子。",["race:Undead"]="对于被遗忘者而言，消灭血色十字军是生存的必要条件；这些狂热分子根本不会区分拥有自由意志的亡灵和天灾军团。"},sec={{t="情报的利用",b="执行官阿伦从丧钟镇的血色十字军手中缴获的文件揭示了他们在提瑞斯法林地的活跃部队动向。执行官塞加德没有坐等这些狂热分子对刚加固的布瑞尔镇发动攻势，而是利用这些截获的情报，策划了针对他们前线指挥官的先发制人的打击。"},{t="废墟塔楼的威胁",b="佩林队长驻扎在布瑞尔西南方的一座破旧瞭望塔里，统领着一支由血色狂热者和传教士组成的部队。从这个据点出发，十字军试图监视被遗忘者的动向，并将势力深入提瑞斯法，因此除掉佩林对于保卫黑暗女王年轻的王国至关重要。"}},faq={{q="佩林队长是谁？",a="佩林队长是一名驻扎在布瑞尔西南方废墟瞭望塔的血色十字军军官，负责指挥一小队正在侵入提瑞斯法林地的狂热者和传教士。",al={"佩林队长","佩林","佩林是谁"}},{q="被遗忘者是从哪里得到关于佩林队长的情报的？",a="执行官阿伦在丧钟镇最初的防御战中回收了关键的十字军文件，其中详细记录了部队的部署和前哨站位置，包括佩林所在的岗位。",al={"塞加德的战略文件","阿伦的文件","丧钟镇血色文件"}},{q="为什么血色传教士和狂热者会出现在提瑞斯法？",a="血色十字军认为所有的亡灵都是必须被根除的憎恶，无论他们是效忠于天灾军团还是被遗忘者。他们的传教士和狂热者深入提瑞斯法发动圣战，试图为生者收复洛丹伦。",al={"为什么血色十字军在提瑞斯法","提瑞斯法血色传教士","血色狂热者"}},{q="这个任务在针对十字军的战役中处于什么位置？",a="这是提瑞斯法反十字军战役的第二步。击杀佩林可以拆除他们当地的侦察据点，随后执行官塞加德将升级针对林地中更大规模营地的行动。",al={"与血色十字军交战任务链","佩林之后是什么"}},{q="这个任务可以和附近的其他任务一起完成吗？",a="可以，它直接与“死亡证明”任务相关联，在该任务中，亡灵卫兵伯吉斯要求收集从同一批十字军身上获取的血色十字军徽记之戒，作为效忠瓦里玛萨斯和黑暗女王的证明。",al={"死亡证明任务相关","佩林任务搭配","布瑞尔塔楼任务"}},{q="执行官塞加德是谁？",a="执行官塞加德是驻扎在布瑞尔的主要军事指挥官，负责保卫提瑞斯法林地，并代表Sylvanas Windrunner指挥战略攻势。",al={"塞加德","布瑞尔执行官塞加德"}}},fp="31,234,23.278.0,30.261.0,23.177.0,58.164.0,53.222.0,62.207.0,58.171.0,23.154.0"}
P.entries["quest:371"] = {n="与血色十字军的战争",s="这次军事行动要求被遗忘者防卫者们向提瑞斯法林地东南部的巴尼尔农场附近的血色十字军营地发起打击。在执行官塞加德的命令下，玩家需要消灭瓦松队长和随行的修士，以阻挠威胁到黑暗女王领地的十字军突袭。",h="这次军事行动要求被遗忘者防卫者们向提瑞斯法林地东南部的巴尼尔农场附近的血色十字军营地发起打击。在执行官塞加德的命令下，玩家需要消灭瓦松队长和随行的修士，以阻挠威胁到黑暗女王领地的十字军突袭。",kw={"阿伦","巴尼尔","布瑞尔","十字军","修士","提瑞斯法","塔楼","瓦松","塞加德"},ang={["class:Priest"]="与血色修士的冲突，将你对暗影和扭曲的神圣之力的掌握，与人类狂热者那教条、顽固的狂热对立起来。",["faction:Horde"]="消灭血色狂热者可以保持通往幽暗城的道路畅通，并确保部落在洛丹伦北部的补给路线安全。",["race:Undead"]="提瑞斯法林地周围清除的每一个十字军岗哨，都能巩固你们新生国家的边境，并保护希尔瓦娜斯女王的领地免受那些活着的净化者的侵害。"},sec={{t="逼近的蚕食",b="随着被遗忘者努力巩固布瑞尔和幽暗城周边的防线，血色十字军仍在该地区的乡间保留着一些防御工事。从执行官阿伦那里汇集到镇上的报告提醒军事指挥部，有一股活跃的十字军正从提瑞斯法林地东南部的一座摇摇欲坠的岗楼中发起侵袭，那里的位置距离废弃的巴尼尔农场近得让人不安。"},{t="切断指挥链",b="执行官塞加德意识到，组织混乱的狂热者远没有协同作战的小队危险，因此将进攻重点放在了他们的战地指挥官身上。通过消灭瓦松队长以及那些用神圣魔法支援他的血色修士，被遗忘者旨在粉碎这支小队的作战凝聚力，并压制人类对附近被遗忘者领地的突袭。"}},faq={{q="是谁下达了这次打击命令？",a="驻扎在布瑞尔镇的执行官塞加德下达了这些命令。他根据执行官阿伦收集并提交的有关巴尼尔农场附近十字军动向的前线情报采取行动。",al={"任务发布者","谁发布了这个任务","塞加德是谁"}},{q="瓦松队长在哪里？",a="瓦松队长和他的血色修士随从驻扎在提瑞斯法林地东南部的一座废弃岗楼里，就在巴尼尔农场的东边。",al={"瓦松位置","瓦松在哪里","血色修士在哪里"}},{q="为什么执行官塞加德特别针对血色修士？",a="血色修士为普通狂热者提供至关重要的魔法和精神支持。除掉这些施法者会使十字军小队失去防御结界和治疗能力，从而使他们的战地行动彻底瘫痪。",al={"为什么要杀修士","血色修士"}},{q="那座废弃的塔楼对布瑞尔构成了什么威胁？",a="这座塔楼为血色十字军提供了高处视野和一个加固的进攻据点。从那里，十字军巡逻队可以轻松伏击被遗忘者的旅人，并破坏通往布瑞尔东部的补给道路。",al={"塔楼威胁","为什么要攻击塔楼","巴尼尔岗楼"}},{q="这在与十字军的更大规模冲突中起到了什么作用？",a="这项任务构成了执行官塞加德战术战役的第三阶段，旨在系统地从提瑞斯法林地清除血色十字军的据点，在狂热者势力围攻幽暗城之前将他们击退。",al={"血色战争任务线","与血色十字军的战争背景"}},{q="瓦松队长被杀后会发生什么？",a="虽然击败瓦松减缓了十字军在提瑞斯法东南部的推进，但执行官塞加德很快便将注意力转向了该地区其他更大的血色十字军防御工事。",al={"下一个任务","瓦松死后发生了什么","瓦松的后续"}}},fp="31,227,22.284.0,29.332.0,23.159.0,32.134.0,60.171.0,48.187.0,61.194.0,43.180.0"}
P.entries["quest:372"] = {n="与血色十字军的战争",s="这项任务是执行官塞加德为保卫提瑞斯法林地、抵御血色十字军入侵而开展的早期战役的高潮。被遗忘者的特工以布瑞尔为基地，受命直接打击越过法奥之墓的一座废弃瞭望塔，目标是梅尔拉赫队长及其私人先锋队。",h="这项任务是执行官塞加德为保卫提瑞斯法林地、抵御血色十字军入侵而开展的早期战役的高潮。被遗忘者的特工以布瑞尔为基地，受命直接打击越过法奥之墓的一座废弃瞭望塔，目标是梅尔拉赫队长及其私人先锋队。",kw={"布瑞尔","梅尔拉赫队长","执行官塞加德","法奥之墓","血色十字军保镖","血色十字军","提瑞斯法林地"},ang={["class:Rogue"]="深入敌后，将指挥官与其周边军队隔离开来，是死亡猎手最典型的工作。",["faction:Horde"]="确保提瑞斯法的周边安全，能够保护部落在东部王国脆弱的立足点。",["race:Undead"]="对于被遗忘者来说，每杀死一名十字军战士，就少了一个否认他们在这片生前故土上生存权利的狂徒。"},sec={{t="先锋队的打击",b="当被遗忘者巩固他们对洛丹伦废墟的控制时，血色十字军正无情地试探着提瑞斯法林地的边界。在法奥之墓后方的提瑞斯法北部，狂热的十字军占据了一座高耸的瞭望塔，并组织突袭队攻击被遗忘者的巡逻队和领地。执行官塞加德没有坐以待毙地等待下一次进攻，而是选择了斩首行动：消灭指挥当地突袭的指挥机构。"},{t="梅尔拉赫队长的据点",b="统领这个北部营地的是梅尔拉赫队长，他是一位绝不妥协的军官，身边始终跟着两名誓死效忠的保镖。梅尔拉赫所处的位置使十字军能够监视沿海道路和周边的树林。击杀他将破坏布瑞尔附近十字军的即时协调能力，化解对希尔瓦娜斯女王初创王国的直接威胁，并迫使这些狂热分子退回到他们更靠东方的坚固防御工事中。"}},faq={{q="梅尔拉赫队长是谁？",a="梅尔拉赫队长是血色十字军的一名战地指挥官，负责监管位于提瑞斯法林地北部、法奥之墓外的一座废弃塔楼中的突袭营地。他率领私人保镖对被遗忘者的领地进行激进的侵扰。",al={"梅尔拉赫","梅尔拉赫队长背景故事","血色十字军队长是谁"}},{q="废弃塔楼在哪里？",a="这座塔楼矗立在提瑞斯法林地的北部荒野中，坐落在法奥之墓墓地后方的悬崖上，俯瞰着北部海岸。",al={"梅尔拉赫位置","塔楼在哪里","法奥之墓塔楼"}},{q="为什么执行官塞加德要除掉梅尔拉赫？",a="梅尔拉赫的部队一直以他们的塔楼基地为据点进行积极的袭击，骚扰被遗忘者军队，并威胁到布瑞尔和幽暗城的安全。塞加德下令暗杀他，以打破十字军在当地的进攻势头。",al={"为什么要杀梅尔拉赫","塞加德的动机"}},{q="这场战斗与对抗阿尔萨斯的更大规模战争有什么联系？",a="执行官塞加德将血色十字军视为一种危险的干扰。清除激进的十字军军官使被遗忘者能够巩固对提瑞斯法的控制，并保存实力以实现他们对巫妖王的最终复仇。",al={"与阿尔萨斯的联系","为什么要提到阿尔萨斯"}},{q="击杀梅尔拉赫能将血色十字军从提瑞斯法清除吗？",a="不能。梅尔拉赫的死亡消灭了一个眼前的突袭小组并减轻了北部对布瑞尔的压力，但十字军在附近仍拥有庞大的据点，包括东部的血色修道院。",al={"血色十字军被打败了吗","他们会离开提瑞斯法吗"}},{q="法奥之墓是什么地方？",a="法奥之墓是提瑞斯法北部一处僻静而庄严的墓地。梅尔拉赫的塔楼就坐落在它后方崎岖的山丘中。",al={"法奥之墓","法奥安息之地"}}},fp="31,176,24.336.0,23.371.0,24.188.0,34.124.0,44.179.0,60.212.0,62.181.0,20.119.0"}
P.entries["quest:373"] = {n="未寄出的信",s="在死亡矿井深处艾德温·范克里夫的尸体上发现的，这封密封的信件是写给暴风城城市建筑师巴隆斯·阿历克斯顿的。这封信揭开了这位迪菲亚潜行者领袖与城市建筑大师之间私人恩怨和历史纠葛的幕布。",h="在死亡矿井深处艾德温·范克里夫的尸体上发现的，这封密封的信件是写给暴风城城市建筑师巴隆斯·阿历克斯顿的。这封信揭开了这位迪菲亚潜行者领袖与城市建筑大师之间私人恩怨和历史纠葛的幕布。",kw={"巴隆斯·阿历克斯顿","cathedral square","市政厅","死亡矿井","迪菲亚","艾德温·范克里夫","石匠工会","未寄出的信"},ang={["class:Rogue"]="范克里夫在潜行者中因其无与伦比的战斗技巧和组织能力而具有传奇色彩；找回他的私人信件，可以让人清醒地看到一个特工的纪律是多么容易变质为自杀式的执念。",["faction:Alliance"]="递交这封信提供了一个关键证据，表明迪菲亚潜行者的威胁不仅仅是地区性的强盗起义，而是一场与暴风城市政管理部门有着深厚联系的有针对性的复仇。",["race:Human"]="对于暴风城的人类来说，这封信揭开了王国重建时遗留的伤疤，证明了困扰西部荒野的强盗行径直接源于他们自己首都内部的政治背叛。"},sec={{t="来自坟墓的信息",b="当艾德温·范克里夫在他位于月溪镇地下的无畏舰上倒下时，他留下的不仅仅是一场失败的叛乱。他的衣服里塞着一封新写好的密封信件。奇怪的是，这位迪菲亚潜行者头目并不是写给他的犯罪副手或幕后出资人，而是写给了他发誓要摧毁的王国中心的一位官员：暴风城城市建筑师巴隆斯·阿历克斯顿。"},{t="往昔的建筑师",b="将这封信带到Cathedral Square的市政厅，揭示了这位建筑师与那个亡命之徒之间共同的过去。在第二次战争后暴风城的宏伟重建过程中，阿历克斯顿曾是范克里夫的同行，他对艾德温死讯感到难以置信。尽管对这位强盗头目陷入无差别的暴力感到恐惧，阿历克斯顿还是承认了他那痛苦抗争的根源：范克里夫是一个被背叛所吞噬的绝不妥协的理想主义者，他的正当不满最终演变成了破坏性的疯狂。"}},faq={{q="我在哪里可以找到未寄出的信？",a="物品“未寄出的信”由艾德温·范克里夫掉落，他是位于西部荒野死亡矿井副本中那艘铁甲船上的最终首领。",al={"未寄出的信掉落","如何获得未寄出的信","谁掉落未寄出的信"}},{q="巴隆斯·阿历克斯顿是谁？",a="巴隆斯·阿历克斯顿是暴风城的城市建筑师。他住在Cathedral Square东北边缘的市政厅建筑内。",al={"巴隆斯·阿历克斯顿位置","巴隆斯·阿历克斯顿在哪里","暴风城城市建筑师"}},{q="艾德温·范克里夫为什么要写信给城市建筑师？",a="范克里夫和阿历克斯顿曾是同事，在第二次战争后共同致力于重建暴风城。即使在成为强盗后，范克里夫依然将阿历克斯顿视为曾经的同行，因为他与石匠工会的工作和背叛有着联系。",al={"为什么要写信给巴隆斯","范克里夫与巴隆斯的关系","给建筑师的信"}},{q="这封信揭示了范克里夫的什么信息？",a="读完信后，阿历克斯顿指出，范克里夫至死仍是一个理想主义者和浪漫主义者，但却被复仇彻底毒害了。范克里夫认为，由于统治阶级的贵族拒绝支付石匠的报酬，他对王国发动的暴力战争是完全正义的。",al={"范克里夫的动机","信里写了什么","信件背景故事"}},{q="在上交这封信之前，我需要完成主要的迪菲亚潜行者任务线吗？",a="不需要。虽然漫长的迪菲亚潜行者任务线会直接引导玩家面对范克里夫，但任何击败他的联盟冒险者都可以拾取并完成“未寄出的信”，无论之前的任务进度如何。",al={"任务前置条件","我可以提前完成未寄出的信吗","我需要完成迪菲亚任务线吗"}},{q="这个任务线接下来会去哪里？",a="将信送达后，阿历克斯顿会指引你前往监狱，审问一名被监禁的迪菲亚潜行者领袖——巴基尔·斯瑞德，他可能知道更多关于范克里夫计划的信息。",al={"未寄出的信之后的任务","雷斯科瓦任务线","巴隆斯·阿历克斯顿之后是什么"}}},fp="17,134,24.212.0,17.455.1,34.105.0,22.114.0,53.216.0,43.202.0,77.135.0,36.160.1"}
P.entries["quest:374"] = {n="死亡证明",s="“死亡证明”是一项由布瑞尔的亡灵卫兵伯吉斯发布的军事指令，旨在削减提瑞斯法林地中血色十字军的兵力。该指令由希尔瓦娜斯·风行者的恐惧魔王副官瓦里玛萨斯下令发起，旨在考验士兵对被遗忘者事业的忠诚。新兵们被要求从战死的十字军身上摘下印戒，作为他们已被剿灭的确凿证据。",h="“死亡证明”是一项由布瑞尔的亡灵卫兵伯吉斯发布的军事指令，旨在削减提瑞斯法林地中血色十字军的兵力。该指令由希尔瓦娜斯·风行者的恐惧魔王副官瓦里玛萨斯下令发起，旨在考验士兵对被遗忘者事业的忠诚。新兵们被要求从战死的十字军身...",kw={"布瑞尔","黑暗女王","亡灵卫兵伯吉斯","执行官塞加德","死亡证明","血色十字军","血色十字军徽记之戒","提瑞斯法林地","瓦里玛萨斯"},ang={["faction:Horde"]="这项任务展现了希尔瓦娜斯政权在北方冷酷无情的总体战思维，其背后有部分由恐惧魔王瓦里玛萨斯在策划。",["race:Undead"]="对于被遗忘者来说，每带回布瑞尔的一枚十字军戒指，就代表少了一个誓要将洛丹伦从自由意志亡灵手中净化的狂热分子。"},sec={{t="恐惧魔王的指令",b="在提瑞斯法林地北部进行的这场战役不仅是为了防御，更是一场协同进行的歼灭战。瓦里玛萨斯，那位投降并向希尔瓦娜斯·风行者宣誓效忠的恐惧魔王，监管着被遗忘者针对生者的大多数侵略性军事行动。他的指令下达给像执行官塞加德这样的指挥官，以及像亡灵卫兵伯吉斯这样的前线军官。伯吉斯明确传达了这一指令：人类被视为必须从洛丹伦清除的害虫，而附近狂热的十字军正是首要目标。"},{t="屠戮的凭证",b="单凭言语无法满足布瑞尔的指挥官们。为了证明对黑暗女王及其副官的服从，士兵必须从被杀死的狂热者手指上直接掠夺血色十字军印戒。这些戒指带有血色十字军的徽记，标志着佩戴者是被遗忘者的死敌。带回一把这样的战利品不仅是十字军战死的无可辩驳的证据，更是展现坚定不移之忠诚的证明。"}},faq={{q="是谁下达了收集这些戒指的任务？",a="驻扎在布瑞尔镇的被遗忘者卫兵，亡灵卫兵伯吉斯下达了该命令。他根据执行官塞加德的报告行事，并遵循瓦里玛萨斯设定的总体军事目标。",al={"谁下达了死亡证明任务","任务发布者","亡灵卫兵伯吉斯任务"}},{q="为什么伯吉斯特别要求血色十字军印戒？",a="血色十字军印戒是十字军已被杀死的无可辩驳的实物证据。它们是狂热者随身携带的个人信物，因此成为了方便且不可否认的战争战利品，用以确认士兵对被遗忘者领导层的忠诚。",al={"为什么要戒指","血色戒指的用途","什么是印戒"}},{q="瓦里玛萨斯是谁，为什么要提到他？",a="瓦里玛萨斯是一位恐惧魔王，在被遗忘者从巫妖王手中获得自由后，他与希尔瓦娜斯·风行者女王结盟。目前他担任幽暗城的首席副官，指挥针对洛丹伦剩余人类聚居点（包括血色十字军）的军事战略。",al={"谁是瓦里玛萨斯","幽暗城的恐惧魔王","为什么是瓦里玛萨斯"}},{q="执行这项任务时，血色十字军位于何处？",a="血色狂热者在提瑞斯法林地各处设有数个武装营地，特别是在林地北部和东部边缘的岗哨、驻军点和前哨站周围。",al={"在哪里找到血色十字军","血色十字军位置","提瑞斯法林地的十字军营地"}},{q="这与执行官塞加德的命令有何联系？",a="执行官塞加德从布瑞尔全面监管针对血色十字军的战役。塞加德指挥新兵破坏十字军的野外势力，而伯吉斯则进一步要求他们上缴个人战利品，作为直接向瓦里玛萨斯和黑暗女王效忠的证明。",al={"与执行官塞加德的关系","与血色十字军开战任务关联"}},{q="为什么被遗忘者领导层对血色十字军如此敌视？",a="血色十字军认为所有亡灵都是注定要被圣火净化的憎恶，他们不区分无脑的亡灵天灾和拥有自由意志的被遗忘者。由于他们积极在自己的边境猎杀被遗忘者，希尔瓦娜斯和她的军官们将他们视为必须被消灭的危险生存威胁。",al={"为什么要与血色十字军战斗","被遗忘者对抗血色十字军","为什么被遗忘者憎恨人类"}}},fx={ad9b8a55={q="亡灵卫兵伯吉斯为什么要杀死血色十字军？",a="亡灵卫兵伯吉斯在布瑞尔前线直接为瓦里玛萨斯和黑暗女王效力。在提瑞斯法林地，血色十字军就在幽暗城门前构成了迫在眉睫的狂热威胁。伯吉斯要将他们彻底铲除，以确保领地安全，并要求你带回能证明他们战败的实物，借此衡量你对被遗忘者事业的忠诚。",al={"伯吉斯的动机","伯吉斯为什么要杀血色十字军","为什么要收集死亡证明"}},a6764d6a={q="这项任务针对哪些血色十字军成员？",a="你奉命对付占据提瑞斯法林地各处营地的狂热血色十字军成员。这些狂热的人类将所有亡灵视为必须彻底消灭的怪物，正积极发动战役，意图收复洛丹伦并消灭被遗忘者。",al={"血色十字军的目标是谁","死亡证明任务的目标","死亡证明任务要杀谁"}}},fp="15,293,28.457.0,19.421.0,44.154.0,60.204.0,43.278.0,54.155.0,50.238.0,65.300.0"}
P.entries["quest:3741"] = {n="希拉里的项链",s="在湖畔镇的码头钓鱼时，年轻的希拉里不慎弄丢了她父亲送给她的珍贵项链。由于父母严禁他们涉足止水湖那险象环生的水域，她的朋友肖恩便请求路过的冒险者潜入湖底找回这件遗失的饰品。",h="在湖畔镇的码头钓鱼时，年轻的希拉里不慎弄丢了她父亲送给她的珍贵项链。由于父母严禁他们涉足止水湖那险象环生的水域，她的朋友肖恩便请求路过的冒险者潜入湖底找回这件遗失的饰品。",kw={"effsee","闪光泥浆","希拉里","止水湖","湖畔镇","项链","nida","赤脊山","肖恩"},ang={["faction:Alliance"]="帮助陷入困境的湖畔镇居民解决细小的个人困难，加强了联盟保护普通平民的承诺，而不仅仅是应对更重大的战略威胁。"},sec={{t="码头的一天",b="湖畔镇的孩子们经常在湖边消磨时光，试图在赤脊山周围日益增长的威胁中过上正常的童年生活。在一次游玩中，年轻的希拉里不小心将她珍贵的项链掉进了止水湖的深处。在徒劳地搜寻了木质码头和岸边之后，她的同伴肖恩转而向有能力的冒险者寻求帮助。"},{t="止水湖的险境",b="镇上的父母严禁孩子们在湖中游泳，这是有充分理由的。止水湖里到处都是好斗的鱼人和潜伏在水面之下的饥饿食人鱼。对于镇上的几个孩子来说，想要捞回掉在湖底闪光泥浆里的物品是不可能的，因此外界的帮助成了找回这份家传礼物的唯一希望。"}},faq={{q="是谁弄丢了项链？",a="这条项链属于居住在湖畔镇的年轻女孩希拉里。这是她父亲送给她的特别礼物，所以丢失项链让她非常难过。",al={"nida是谁","谁弄丢的","项链主人","希拉里是谁"}},{q="为什么肖恩或希拉里不能自己游下去拿回来？",a="由于水面之下潜藏着危险，他们的父母严禁他们在止水湖中游泳。好斗的鱼人和捕食性的食人鱼让湖水对无人看管的孩子来说太危险了。",al={"为什么不自己去拿","为什么孩子不能游泳"}},{q="项链最终掉在了哪里？",a="项链从码头上滑落，沉入了止水湖西侧湖底的一堆闪光泥浆中。",al={"项链位置","项链在哪里","项链掉在哪里了"}},{q="Effsee是谁？",a="Effsee是希拉里的宠物猫，它在湖畔镇陪伴着希拉里，并很高兴地与她一起感谢找回项链的旅行者。",al={"effsee","nida猫","希拉里的猫"}},{q="是谁发起了寻找项链的请求？",a="肖恩是希拉里的朋友，当时正和她一起在码头钓鱼。他代表希拉里去请求旅行者的帮助，因为他知道这份礼物对她来说有多重要。",al={"谁给的任务","肖恩的作用"}},{q="为什么这个任务对湖畔镇很重要？",a="虽然与对抗豺狼人或黑石兽人相比这只是一件小事，但这类小小的帮助能为那些在不断威胁下艰难维持平静生活的家庭带来安慰和正常感。",al={"湖畔镇的重要性","为什么帮助孩子"}}},fp="17,196,18.293.0,24.270.0,22.123.0,58.130.0,30.113.0,14.130.0,44.142.0,39.134.0"}
P.entries["quest:375"] = {n="死亡之寒",s="在布瑞尔镇，一位名叫Gretchen Dedmar的被遗忘者裁缝正在与日益严重的死亡与腐朽所带来的寒冷作斗争。由于担心那逐渐逼近的无心状态会使她无法继续为希尔瓦娜斯女王效力，她请求提供一些简单的材料，好为自己缝制一条温暖的毯子。",h="在布瑞尔镇，一位名叫Gretchen...",kw={"布瑞尔","死亡寒意","粗线","暮色蝙蝠毛皮","gretchen dedmar","无心状态","亡灵瘟疫","提瑞斯法林地"},ang={["profession:Tailoring"]="Gretchen依靠朴素的针线活为生，她曾在希尔瓦娜斯的军队中缝制装尸袋，如今却要把针线用在一条简单的毛皮毯子上。",["race:Undead"]="Gretchen的挣扎对所有被遗忘者而言都是一个严峻的提醒：从巫妖王手中获得解放并不能抵御肉体的腐烂和时刻存在的无心威胁。"},sec={{t="蠕动的寒意",b="对于被遗忘者来说，亡灵状态并非一种永恒不变的静止存在。正如Gretchen Dedmar所描述的那样，残留的亡灵瘟疫就像一条冰冷的毒蛇，在她的体内游走，吸干她肢体的温暖，并威胁着要将她拖入那困扰着提瑞斯法林地中无数游荡尸骸的无心状态。她颤抖的双手使得完成普通的工作几乎成了不可能之事。"},{t="为黑暗女王效力",b="尽管力量日益衰弱，Gretchen依然拒绝放弃她对被遗忘者王国的职责。当希尔瓦娜斯·风行者最初召集那些被解放的亡灵时，Gretchen通过为阵亡的士兵缝制裹尸布和装尸袋做出了自己的贡献。通过收集结实的暮色蝙蝠毛皮和粗线，旅行者们可以帮助她保持双手稳定，从而制作出一条毯子，延续她对被遗忘者事业所做的有效贡献。"}},faq={{q="Gretchen Dedmar是谁？",a="Gretchen Dedmar是一位居住在布瑞尔的被遗忘者。她曾通过为希尔瓦娜斯女王阵亡的部队缝制装尸袋，为新生的被遗忘者战争事业做出过贡献。",al={"gretchen dedmar","gretchen是谁","布瑞尔裁缝任务发布者"}},{q="Gretchen所害怕的“无心状态”是什么？",a="无心状态指的是当亡灵体内残留的意志和通灵能量耗尽时，其身心所经历的腐朽。这会使他们变成如布瑞尔和丧钟镇外那些游荡的野蛮、蹒跚的生物。",al={"什么是无心状态","为什么gretchen在失去理智","被遗忘者变成无心者"}},{q="既然Gretchen已经死了，为什么还会感到寒冷？",a="虽然亡灵的身体缺乏活人的血液循环，但Gretchen感觉到体内的瘟疫像一种压倒性的、冰冷的寒意，这使她的关节僵硬，双手不停颤抖。",al={"亡灵能感觉到寒冷吗","为什么亡灵会感到寒冷","死亡寒意的含义"}},{q="她为什么需要暮色蝙蝠毛皮和粗线？",a="Gretchen需要五张暮色蝙蝠毛皮和粗线来缝制一条厚毯子。她希望增加的温暖能使她颤抖的双手保持灵活，以便她能继续工作。",al={"为什么要暮色蝙蝠毛皮","毯子是做什么用的"}},{q="在哪里可以找到暮色蝙蝠？",a="暮色蝙蝠栖息在布瑞尔和提瑞斯法林地北部周边的树林与空旷林地中。",al={"暮色蝙蝠在哪里","暮色蝙蝠毛皮位置"}},{q="这个任务与布瑞尔的其他职责有联系吗？",a="这是一个旨在帮助布瑞尔一位挣扎中的居民的独立任务，展示了新解放的被遗忘者之间那种安静而私人的挣扎。",al={"死亡寒意的后续","gretchen dedmar任务链"}}},fp="18,214,16.264.0,24.326.0,23.116.0,44.212.0,43.134.0,43.143.0,28.79.0,53.144.0"}
P.entries["quest:376"] = {n="被诅咒者",s="“被诅咒者”是新加入被遗忘者的新兵艾尔雷斯在丧钟镇教堂发布的一项早期任务。艾尔雷斯会用能够保护初生亡灵免受墓地周边危险侵扰的旧装备，来交换制作粗糙衣物和战地绑带所需的材料。",h="“被诅咒者”是新加入被遗忘者的新兵艾尔雷斯在丧钟镇教堂发布的一项早期任务。艾尔雷斯会用能够保护初生亡灵免受墓地周边危险侵扰的旧装备，来交换制作粗糙衣物和战地绑带所需的材料。",kw={"丧钟镇","夜行蝙蝠翼","被遗忘者","新兵艾尔雷斯","食腐狼的爪子","暗影牧师萨维斯","被诅咒者","提瑞斯法林地"},ang={["profession:Tailoring"]="新兵艾尔雷斯突显了洛丹伦战地裁缝的残酷必要性，在那里，翼膜和拾荒得来的兽皮成了干净布料的替代品。",["race:Undead"]="对于刚苏醒的被遗忘者来说，这项任务是对他们族人冷酷务实精神的早期展示，表明生存意味着剥取前人的装备，并依靠这片被瘟疫侵蚀的土地上所能提供的一切来苟活。"},sec={{t="务实的交易",b="苏醒成为亡灵后，虚荣心或多愁善感已无处安放。新兵艾尔雷斯照料着从丧钟镇泥土中源源不断爬出的新晋被遗忘者，她是暗影牧师萨维斯的助手。在照顾受伤的士兵和修补衣物之间，补给物资变得极其匮乏。为了确保新来者在最初的试炼中不会散架，艾尔雷斯派他们前往周边的林地猎杀当地的暮色蝙蝠和食腐狼，并用回收的护甲换取维持营地运作所需的生皮、翅膀和肌腱。"},{t="继承的保护",b="艾尔雷斯提供的护甲远非精良的锻造品；它们是那些未能熬过苏醒期的亡灵留下的二手装备。她那句冷酷的临别赠言——希望这些衣物比前主人穿得更久——反映了被遗忘者生存法则的冷酷计算。在提瑞斯法林地，没有任何东西会被浪费，每一块皮革和生锈的锁甲都至少已经穿过一具尸体了。"}},faq={{q="谁是新兵艾尔雷斯？",a="新兵艾尔雷斯是驻守在丧钟镇教堂的一名侍僧。她担任暗影牧师萨维斯的助手，负责照料受伤的被遗忘者、缝制战地装备，并在新兵被派往危险地区前为他们装备齐全。",al={"新兵艾尔雷斯","谁发布了被诅咒者任务","艾尔雷斯"}},{q="为什么艾尔雷斯需要食腐狼爪和暮色蝙蝠翅膀？",a="丧钟镇缺乏新鲜的原材料供应。艾尔雷斯依靠提瑞斯法林地本地的野生动物，如暮色蝙蝠和食腐狼，来收集制作护甲所需的皮革、肌腱和裁剪碎料，从而修补制服并为受伤的士兵包扎。",al={"为什么需要蝙蝠翅膀","为什么需要食腐狼爪","艾尔雷斯的材料"}},{q="护甲奖励是从哪里来的？",a="这些护甲是从丧钟镇周边先前的冲突中未能幸存的被遗忘者新兵身上剥下来的。艾尔雷斯回收了任何还能使用的装备，以保护下一批刚苏醒的死者。",al={"护甲从何而来","艾尔雷斯护甲的来源"}},{q="这些生物在哪里可以找到？",a="幼年食腐狼和暮色蝙蝠就栖息在丧钟镇的正南方。体型稍大的变种则游荡在向东前往血色十字军哨所的路上。",al={"哪里可以找到食腐狼","暮色蝙蝠在哪里","暮色蝙蝠分布点"}},{q="这项任务如何融入丧钟镇的防御？",a="它提供了最基本的战地准备。暗影牧师萨维斯要求所有新苏醒的被遗忘者去对抗附近的威胁，比如无脑的亡灵和血色十字军，而艾尔雷斯确保他们在出发前穿上结实的护甲。",al={"为什么要完成这个任务","丧钟镇防御"}},{q="帮助新兵艾尔雷斯之后会发生什么？",a="证明自己有能力在当地的野生环境中生存后，便会开启丧钟镇周围的后续任务，包括实现玛拉的遗愿、解决夜行蜘蛛洞穴的蜘蛛肆虐问题，以及在定居点各处回收补给品。",al={"完成被诅咒者后的后续任务","被诅咒者之后有什么任务"}}},fp="10,149,17.355.0,20.215.0,21.156.0,54.169.0,37.118.0,30.119.0,54.174.0,41.190.0"}
P.entries["quest:3765"] = {n="遥远的旅途",s="阿古斯·夜语，一位造访暴风城的暗夜精灵使者，正在寻找有能力的冒险者，希望能跨越无尽之海，前往卡利姆多北部支援他的兄弟。他的兄弟戈沙拉·夜语正在黑海岸研究肆虐的生态腐化，目前急需帮手。",h="阿古斯·夜语，一位造访暴风城的暗夜精灵使者，正在寻找有能力的冒险者，希望能跨越无尽之海，前往卡利姆多北部支援他的兄弟。他的兄弟戈沙拉·夜语正在黑海岸研究肆虐的生态腐化，目前急需帮手。",kw={"阿古斯","奥伯丁","腐化","黑海岸","戈沙拉","夜语","暴风城"},ang={["faction:Alliance"]="这项使命展示了将卡利姆多的暗夜精灵与跨海之外的人类王国暴风城紧密联系在一起的萌芽纽带。",["race:Human"]="前往黑海岸能让身为人类的冒险者第一次瞥见古老的卡多雷文化，这里远离艾尔文森林的石砌城堡。",["race:NightElf"]="对于远离家乡的暗夜精灵来说，阿古斯提醒着人们，卡利姆多北部祖先的森林正遭受着严重的困扰。"},sec={{t="人类首都的使者",b="当暴风城正忙于应对内部动荡和地区不安时，来自遥远卡多雷领地的代表们正徘徊在它那石砌的街道上。阿古斯·夜语来到这里是为了寻找那些愿意放眼人类边境之外的资深勇士。卡多雷是东部王国相对较新的盟友，正式的军事援助非常匮乏，这使得家庭成员和研究人员只能招募任何响应号召的独立勇士。"},{t="黑海岸的召唤",b="阿古斯所指的目的地是奥伯丁，这是一座坐落在黑海岸迷雾笼罩的海岸线上的港口小镇。在那里，他的兄弟戈沙拉正在对一种困扰当地野生动物和植物的阴险瘟疫进行至关重要的研究。响应这一召唤意味着要从暴风城港口出发，跨越无尽之海进行漫长的航行，这将是旅行者第一次真正涉足卡利姆多古老的荒野。"}},faq={{q="阿古斯·夜语是谁？",a="阿古斯·夜语是一位在暴风城逗留的暗夜精灵访客。他担任其家族的某种特使，专门招募经验丰富的联盟冒险者跨海前往黑海岸支援他的兄弟戈沙拉。",al={"阿古斯","阿古斯·夜语","谁发布了“海外的腐化”任务"}},{q="戈沙拉·夜语在哪里？",a="戈沙拉·夜语驻扎在奥伯丁，这是一个位于卡利姆多北部黑海岸西海岸的暗夜精灵定居点。",al={"戈沙拉位置","戈沙拉在哪里","上交“海外的腐化”任务"}},{q="为什么戈沙拉需要帮助？",a="戈沙拉正在调查一种在黑海岸荒野中蔓延的非自然腐化，它正在感染当地的野生动物、水源和植被。他需要资深的勇士来协助收集样本并调查根本原因。",al={"为什么要帮助戈沙拉","黑海岸出了什么问题"}},{q="我该如何从暴风城前往奥伯丁？",a="登上暴风城港口最南端码头的船，它会径直横跨无尽之海，抵达黑海岸的奥伯丁。",al={"如何到达奥伯丁","从暴风城前往黑海岸"}},{q="如果我已经去过黑海岸，还能完成这个任务吗？",a="如果你已经去过奥伯丁，并直接从戈沙拉那里开始了任务“研究腐化”，那么你就无法再从阿古斯那里接取或完成这个介绍性的召唤任务了。",al={"错过了“海外的腐化”任务","还能做“海外的腐化”任务吗"}},{q="阿古斯和戈沙拉是什么关系？",a="阿古斯·夜语和戈沙拉·夜语是兄弟。戈沙拉留在前线研究黑海岸的枯萎病，而阿古斯则跨海来到暴风城寻找有能力的盟友。",al={"阿古斯和戈沙拉","阿古斯和戈沙拉有亲属关系吗"}}},fx={c6dfa232={q="阿古斯·夜语为什么需要你代替他前去？",a="阿古斯专程远渡重洋来到东部王国，招募有能力的盟友。他的兄弟格沙拉在黑海岸遇到了越来越多的麻烦，需要经验丰富的人手；阿古斯则留在繁华的首都，继续请求援助，并寻找愿意长途跋涉、横渡大洋返回的人。",al={"为什么派我去","阿古斯为什么不能去","阿古斯为什么需要冒险者"}}},fp="21,168,29.404.0,21.328.0,26.199.0,39.125.0,28.225.0,41.118.0,51.179.0,52.180.0"}
P.entries["quest:377"] = {n="罪与罚",s="“罪与罚”是源于夜色镇的一个联盟赏金任务，要求对一名关押在暴风城监狱中的盗墓贼进行法外处决。在贵族议会推翻了暮色森林对迪克斯特·瓦德的死刑判决后，议员米尔斯迪普发布了这份契约。执行这次暗杀既满足了当地人的复仇心理，也向首都那漠不关心的贵族阶层发出了严厉的警告。",h="“罪与罚”是源于夜色镇的一个联盟赏金任务，要求对一名关押在暴风城监狱中的盗墓贼进行法外处决。在贵族议会推翻了暮色森林对迪克斯特·瓦德的死刑判决后，议员米尔斯迪普发布了这份契约。执行这次暗杀既满足了当地人的复仇心理，也向首...",kw={"夜色镇","迪克斯特·瓦德","暮色森林","盗墓贼","贵族议会","米尔斯迪普","摩尔本·菲尔","监狱"},ang={["class:Rogue"]="米尔斯迪普的任务是一次厚颜无耻的政治暗杀，需要秘密潜入王室戒备最森严的监狱以绕过皇家法令。",["faction:Alliance"]="该任务揭露了联盟心脏地带内部的严重摩擦，使苦苦挣扎、被忽视的夜色镇边境与遥远且傲慢的贵族议会官僚对立起来。",["race:Human"]="对于南方王国的人类来说，这份契约考验着你的忠诚是属于暴风城那遥远的王座，还是属于在暮色森林坚守阵地的绝望定居者。"},sec={{t="暮色森林的公正被否决",b="暮色森林本已在不断蔓延的恐怖和来自首都的官方冷漠下苦苦挣扎。当迪克斯特·瓦德被抓获，因其从夜色镇墓地挖掘新鲜尸体并贩卖给死灵法师摩尔本·菲尔时，镇上的议会没有表现出丝毫怜悯。艾尔罗·埃伯洛克公爵判处这名盗墓贼斩首之刑。然而，在斧头落下之前，贵族议会介入了，声称瓦德是帝国囚犯，并将他转移到了戒备森严的暴风城监狱。"},{t="对死者的侮辱",b="对于议员米尔斯迪普和夜色镇悲痛的市民来说，将瓦德从行刑者的断头台上救下是一种不可容忍的侮辱。那些高高在上的贵族们在安全的城市里，完全无视了边境家庭所遭受的折磨，他们的逝去亲人竟被送去供奉菲尔的黑暗技艺。由于对暴风城官僚主义干预的失望，米尔斯迪普招募了胆大的雇佣兵潜入暴乱的监狱，在牢房中暗杀瓦德，并割下他的手作为处决的证据。"},{t="致国王的一封信",b="杀死瓦德既是一种政治行为，也是对受害者的告慰。通过下令暗杀一名身处王权锁链之下的重要囚犯，夜色镇议会向暴风城发出了反抗的信息。如果贵族们拒绝保卫暮色森林或尊重其当地法律，那么这个城镇已经表明，它会在摄政王眼皮底下执行属于自己的边境正义。"}},faq={{q="为什么议员米尔斯迪普想要迪克斯特·瓦德死？",a="瓦德因盗掘夜色镇墓地，将刚埋葬的尸体贩卖给死灵法师摩尔本·菲尔而被捕。埃伯洛克公爵判处他斩首，但暴风城的贵族议会却将他强行带走，关进了监狱。",al={"为什么要杀迪克斯特·瓦德","迪克斯特·瓦德做了什么","米尔斯迪普的动机"}},{q="迪克斯特·瓦德在哪里？",a="他被关押在暴风城首都的暴风城监狱深处，位于监狱综合体最左侧的走廊沿线。",al={"迪克斯特·瓦德的位置","瓦德在哪里","如何找到迪克斯特·瓦德"}},{q="为什么暴风城不直接处决迪克斯特·瓦德？",a="贵族议会出于自身未说明的原因声称对瓦德拥有管辖权，从而推翻了夜色镇的当地判决，这激起了暮色森林居民的愤怒，他们感到自己被首都抛弃了。",al={"为什么瓦德被监禁","为什么是监狱而不是处决"}},{q="为什么米尔斯迪普要求瓦德的手作为证明？",a="议员米尔斯迪普需要无可辩驳的物理证据来证明刑罚已在无视贵族议会的情况下得以执行，从而给暮色森林的受害者家庭一个交代。",al={"迪克斯特·瓦德的手掌","为什么要手作为证明"}},{q="摩尔本·菲尔是谁？",a="摩尔本·菲尔是一位徘徊在暮色森林的强大死灵法师，他利用迪克斯特·瓦德之流的无耻之徒所提供的尸体来复活死者并策划黑暗仪式。",al={"菲尔是谁","摩尔本·菲尔的背景故事"}},{q="这个任务揭示了暮色森林与暴风城之间的什么关系？",a="它突显了深层的政治怨恨。暮色森林感到被王座忽视和保护不力，而议会派遣刺客进入首都监狱的意愿表明这种忠诚已经变得多么紧张。",al={"夜色镇与暴风城的政治","暮色森林的怨恨"}}},fx={["9b93eafe"]={q="迪克斯特·瓦德是谁？他为什么在监狱里？",a="迪克斯特·瓦德是个盗墓贼，他从暮色森林的墓地里挖出尸体，卖给了通灵师莫本特·费尔。尽管伊伯洛克领主判处他死刑，罪名是亵渎死者，但贵族议会出面干预，将他押送到暴风城，并把他关进了监狱。",al={"迪克斯特·瓦德是谁","迪克斯特·瓦德为什么在监狱里","迪克斯特·瓦德犯了什么罪"}},["444df616"]={q="米尔斯蒂普为什么需要你杀死瓦德，而不动用当地官员？",a="瓦德被关在暴风城首都深处的监狱里，归暴风城官方管辖。夜色镇的夜巡队忙于保护城镇，抵御逼近的恐怖威胁；当地官员也无法公开派兵攻打王室监狱，否则会引发叛乱。他们需要一名独立的行动者，悄悄执行他们的正义。",al={"夜色镇的卫兵为什么不能杀瓦德","为什么雇冒险者刺杀瓦德","夜色镇为什么需要我"}}},fp="20,297,26.410.0,21.429.0,22.368.1,53.217.0,30.137.0,47.182.0,38.186.0,19.147.0,73.211.0"}
P.entries["quest:378"] = {n="卡姆·深怒",s="这个任务讲述了莫特雷·加玛森对黑铁矮人卡姆·深怒那刻骨铭心的复仇。深怒策划了对萨多尔大桥的袭击，导致包括布莱德·长须的兄弟在内的铜须守卫惨死。莫特雷对暴风城将罪犯关押在监狱的做法感到不满，于是雇佣了一名冒险者深入监狱，去执行矮人的正义。",h="这个任务讲述了莫特雷·加玛森对黑铁矮人卡姆·深怒那刻骨铭心的复仇。深怒策划了对萨多尔大桥的袭击，导致包括布莱德·长须的兄弟在内的铜须守卫惨死。莫特雷对暴风城将罪犯关押在监狱的做法感到不满，于是雇佣了一名冒险者深入监狱，去...",kw={"黑铁战争","深怒","丹莫德","长须","莫特雷·加玛森","罗格","监狱","萨多尔大桥"},ang={["faction:Alliance"]="这项任务突显了暴风城的法律实用主义与铁炉堡在战时对直接复仇的不懈要求之间潜在的紧张关系。",["race:Dwarf"]="对于铜须矮人来说，除掉深怒是一个严肃的偿还血债、缅怀在保卫萨多尔大桥时牺牲的族人的问题。",["race:Human"]="人类冒险者必须直面本国在外交政策上的局限性，绕过暴风城的监狱规定，以满足矮人盟友的正义准则。"},sec={{t="跨越大陆的宿怨",b="湿地北部的边界深受丹莫德的铜须守卫与黑铁矮人叛军之间持续不断的冲突所困。萨多尔大桥遭到袭击时，那次破坏活动导致了宝贵的矮人生命损失，其中包括布莱德·长须的兄弟。罗格搜集的情报显示，卡姆·深怒是这次阴险袭击的幕后策划者。然而，深怒并没有在前线被处决，而是被关押在暴风城监狱中——他被当作政治犯，而非因谋杀罪被处死。"},{t="矮人的复仇与人类法律",b="驻扎在丹莫德的莫特雷·加玛森拒绝让暴风城的政治算计庇护一名战犯。在莫特雷看来，人类的官僚主义将礼节置于血债之上。由于身负职责，必须留在湿地陪伴布莱德·长须，莫特雷便委派值得信赖的勇士深入人类首都，闯入暴乱的监狱，取下深怒的头颅，以此彻底了结这笔家族血债。"}},faq={{q="卡姆·深怒是谁？",a="卡姆·深怒是一名狡诈的黑铁矮人，他策划了针对萨多尔大桥的破坏性袭击。他的计划直接导致了守卫边境通道的铁炉堡矮人遭到屠杀，这使他成为了丹莫德幸存者眼中的头号目标。",al={"深怒","卡姆·深怒背景故事","深怒是谁"}},{q="为什么卡姆·深怒被关押在暴风城监狱而不是铁炉堡？",a="暴风城当局捕获了深怒，并因未公开的政治原因将他关押在监狱。虽然人类领导层更倾向于利用他作为外交或情报筹码，但丹莫德的矮人们认为这令人愤怒的官僚行为剥夺了他们伸张正义的机会。",al={"为什么深怒在监狱里","为什么是监狱犯人"}},{q="为什么莫特雷·加玛森不亲自追捕深怒？",a="莫特雷受荣誉和军事职责所限，必须与布莱德·长须一起驻守在丹莫德，抵御黑铁矮人在湿地北部的不断进攻。他无法放弃防线去南方的暴风城。",al={"为什么莫特雷留守","为什么莫特雷不亲自去"}},{q="萨多尔大桥发生了什么？",a="黑铁部族对连接湿地与阿拉希高地的萨多尔大桥发动了一次处心积虑的袭击。这次攻击切断了联盟关键的补给动脉，并导致几名铜须守卫丧生，其中包括布莱德·长须的兄弟。",al={"萨多尔大桥袭击","萨多尔大桥发生了什么"}},{q="是谁发现了深怒在萨多尔大桥袭击中的角色？",a="一个叫罗格的矮人拼凑出了相关情报，将深怒与萨多尔大桥袭击的计划和实施直接联系了起来，并把证据交给了莫特雷，使他能够要求复仇。",al={"谁发现了深怒","罗格情报"}},{q="暴风城的领导层知道监狱里的这次暗杀行动吗？",a="这份处决令是一次未经批准的矮人复仇行动。莫特雷明确绕过了人类的法律途径，坚信麦格尼国王的士兵在监狱已经陷入混乱骚乱的情况下，完全有权处决这名破坏者。",al={"暴风城是否知道暗杀","处决深怒是否被批准"}}},fp="18,324,26.454.0,33.356.0,20.196.0,65.203.0,55.220.0,34.193.0,57.182.0,73.189.0"}
P.entries["quest:379"] = {n="口渴的比格维兹",s="加基森的首席工程师沙克斯·比格维兹可以为你的工具包提供4711-FTZ电源，但他首先想要喝点东西：五个流沙水袋，可以从镇子东边的流沙游牧民那里获得。",h="加基森的首席工程师沙克斯·比格维兹可以为你的工具包提供4711-FTZ电源，但他首先想要喝点东西：五个流沙水袋，可以从镇子东边的流沙游牧民那里获得。",kw={"4711-ftz","比格维兹","加基森","电源","塔纳利斯","流沙","水袋"},sec={{t="解渴",b="在完成“进入实地”之后，你知道工具包需要一个电源，而加基森的首席工程师沙克斯·比格维兹可以帮忙。代价是一份饮料：五个流沙水袋。比格维兹指引你去找加基森东边的流沙游牧民，建议你直接走过去索要，并想知道结果如何。"},{t="电源的限制",b="一旦交出水袋，你就能得到电源，但它并不是为了科学工具包而制造的。你收集的所有数据最多只能保存两个小时。当你收集到所需数据后，请将其带回给比格维兹进行妥善关闭。如果时间用完，可以获得另一个电源，但需要购买，而不是赠送。"}},faq={{q="谁索要水袋？",a="加基森的首席工程师沙克斯·比格维兹，他想要五个水袋来交换4711-FTZ电源。",al={"谁给予解渴任务","比格维兹任务","加基森工程师水"}},{q="去哪里找流沙水袋？",a="从流沙游牧民那里，他们位于加基森的东边。",al={"哪里有流沙水袋","塔纳利斯游牧民水","流沙水袋位置"}},{q="首席工程师沙克斯·比格维兹提供什么电源？",a="4711-FTZ，你工具包的电源。",al={"比格维兹给什么物品","4711 ftz电源","电源名称"}},{q="这一步之前是什么？",a="它紧接着“进入实地”之后。",al={"解渴前置任务","解渴的上一个任务","进入实地关联"}}},fp="17,211,26.320.0,20.353.1,31.105.0,48.68.0,57.44.0,27.26.0"}
P.entries["quest:38"] = {n="杂味炖肉",s="“西部荒野炖肉”是一道由萨尔玛·萨丁在萨丁农场烹制的丰盛当地食谱。这道菜取材于西部荒野粗犷的野生动物和采集场，代表了该地区农场主们坚韧的生存精神。",h="“西部荒野炖肉”是一道由萨尔玛·萨丁在萨丁农场烹制的丰盛当地食谱。这道菜取材于西部荒野粗犷的野生动物和采集场，代表了该地区农场主们坚韧的生存精神。",kw={"野猪鼻子","鱼人眼球","秋葵","萨丁农场","萨尔玛·萨丁","秃鹫肉","西部荒野","西部荒野炖肉"},ang={["faction:Alliance"]="虽然暴风城的宫廷享受着美酒和精致的禽肉，但联盟的边境哨所依靠这种粗犷的菜肴来维持他们对当地威胁的防御。",["profession:Cooking"]="萨尔玛的这道菜是粗犷边境烹饪的典范，教导有志向的厨师如何将粗糙的野味、刺鼻的猪鼻和不寻常的海岸收获变成一顿滋补的饭菜。",["race:Human"]="对于艾尔文森林保护墙之外的人类来说，像西部荒野炖肉这样的菜肴体现了在这个王国被遗忘的粮仓中艰难求生所必需的毅力和韧性。"},sec={{t="农场主的必需品",b="西部荒野是一片严酷的边境之地，土匪、饥荒和横冲直撞的野兽困扰着这里，使得边境定居者很难享受到暴风城奢华的粮仓。像萨丁一家这样的家庭已经学会了利用土地提供的资源来应付生活。萨尔玛·萨丁的炖肉将许多城里人眼中的害虫或不可食用的残渣，变成了一种能够让劳作的农场工人维持体力的主食。"},{t="生存的配料",b="这份食谱需要一种独特的边境食材混合：当地的秋葵用来使翻滚的肉汤变浓稠，从盘旋的秃鹫身上切下的粗韧肉块，以及在平原上刨食的野猪的鼻子。最著名的莫过于从沿海袭击者身上收集的新鲜鱼人眼球。虽然在艾尔文森林，一想到要吃河兽和食腐鸟类就会让娇嫩的胃感到不适，但西部荒野的厨师们坚信这种奇怪的组合能做出一顿丰盛、滋补的饭菜。"}},faq={{q="为什么食谱里要用鱼人眼球？",a="西部荒野的农民面临着持续的资源短缺，以及海岸和河岸边好斗的鱼人发动的频繁袭击。萨尔玛·萨丁使用新鲜的鱼人眼球来为肉汤增添独特的鲜味和水分，将一种入侵的威胁变成了实用的食物来源。",al={"食物里的鱼人眼球","为什么要吃鱼人","鱼人炖肉"}},{q="萨尔玛·萨丁是谁？",a="萨尔玛·萨丁是一位联盟农场主，和她的丈夫农夫萨丁一起住在西部荒野北部的萨丁农场。她以热情好客和烹饪上的足智多谋而闻名，尽管该地区土匪横行、一片混乱，她依然坚持为过往的旅行者和农场工人提供食物。",al={"萨尔玛","萨尔玛·萨丁背景故事","谁制作西部荒野炖肉"}},{q="秋葵是从哪里来的？",a="秋葵是西部荒野那些举步维艰的农场里少数还能收获的耐寒蔬菜作物之一。它的豆荚在煮沸时会释放天然的汁液，是边境肉汤中必不可少的增稠剂。",al={"哪里可以找到秋葵","萨丁秋葵","秋葵来源"}},{q="西部荒野炖肉算得上是好吃的食物吗？",a="对于暴风城的贵族来说，一碗放了煮野猪鼻子和鱼人眼球的肉汤听起来简直是荒诞可怖。但对于西部荒野那些一贫如洗的农民和疲惫的流浪者来说，这是一顿温暖、饱腹且深受珍视的慰藉之餐。",al={"西部荒野炖肉好吃吗","西部荒野炖肉恶心吗"}},{q="为什么萨丁一家需要冒险者来收集食材？",a="西部荒野现在变得极其危险。野猪、凶猛的秃鹫和敌对的鱼人在田野和海滩上游荡，使得采集工作对于必须留下来保卫家园的普通农民来说太过危险。",al={"为什么要收集食材","为什么萨尔玛需要帮助"}},{q="炖肉里的肉是哪种动物提供的？",a="炖肉主要依靠从盘旋在西部荒野上空的食腐鸟类身上取得的粗韧秃鹫肉，以及在平原上猎取的野猪鼻子。",al={"西部荒野炖肉里有什么肉","西部荒野炖肉用肉"}}},fp="13,176,25.279.0,27.311.0,36.191.0,21.217.0,30.154.0,38.164.0,63.206.0,43.140.0"}
P.entries["quest:380"] = {n="夜行蜘蛛洞穴",s="夜行蜘蛛洞穴是执行官阿伦发布的一个早期任务，目的是清理位于丧钟镇西北方附近一个金矿里的蜘蛛。由于原材料极度匮乏，刚刚建立的被遗忘者需要矿藏的财富来维持他们的聚居地和战争消耗。新复活的招募者们被派往那错综复杂的洞穴，一点一点地清除蜘蛛侵扰。",h="夜行蜘蛛洞穴是执行官阿伦发布的一个早期任务，目的是清理位于丧钟镇西北方附近一个金矿里的蜘蛛。由于原材料极度匮乏，刚刚建立的被遗忘者需要矿藏的财富来维持他们的聚居地和战争消耗。新复活的招募者们被派往那错综复杂的洞穴，一点一...",kw={"丧钟镇","执行官阿伦","被遗忘者","金矿","夜行蜘蛛","夜行蜘蛛洞穴","提瑞斯法林地","幽暗城"},ang={["faction:Horde"]="在提瑞斯法林地建立稳固的资源产地，对于巩固被遗忘者作为部落在北方可靠堡垒的地位至关重要。",["profession:Mining"]="这个洞穴是丧钟镇附近为数不多的金矿来源之一，尽管厚重的蛛网和捕食性的蜘蛛让探矿变得危机四伏。",["race:Undead"]="这项任务凸显了洛丹伦的亡灵们所面临的残酷现实：生存不仅需要向生者和天灾军团复仇，还需要获得金属和金币等世俗物资。"},sec={{t="急需金币的国度",b="对于新复活的被遗忘者来说，生存不仅意味着防御天灾军团和血色十字军。建立一个新生的社会需要原始资源，即便在联盟鼎盛时期，北洛丹伦的黄金等贵金属也十分稀缺。负责丧钟镇行动的执行官阿伦深知，如果没有稳固的财富，被遗忘者根本无法武装、装备自己并站稳脚跟。"},{t="遭受侵扰的矿洞",b="在墓地正西北方坐落着夜行蜘蛛洞穴，这是一个天然洞穴，里面蕴藏着可开采的金矿脉。不幸的是，巨大的蜘蛛群已经占领了这些隧道，深处布满了厚厚的蛛网和致命的毒液。由于缺乏经验丰富的士兵来进行全面清理，阿伦只能依靠新兵来一点点消灭幼年和成年蜘蛛，直到采矿队最终能够烧掉蛛网并提取矿石。"}},faq={{q="亡灵为什么需要金矿？",a="即使身处亡灵状态，被遗忘者也必须为他们的战争提供资金，支付补给费用，并重建提瑞斯法林地各处的聚居地。洛丹伦一直面临自然资源匮乏的困境，要建立一个独立于联盟和天灾军团的新国度，就需要有价值的货币来进行贸易和采购装备。",al={"被遗忘者为什么需要黄金","丧钟镇为什么需要黄金","亡灵金矿"}},{q="执行官阿伦是谁？",a="执行官阿伦是丧钟镇的最高军事长官。他的职责是组织新复活的亡灵并确保周边区域的安全，他指导新兵完成诸如猎杀天灾军团残部、收集补给和开发当地资源等重要任务。",al={"执行官阿伦背景故事","谁发布了夜行蜘蛛洞穴任务","阿伦的角色"}},{q="夜行蜘蛛洞穴位于哪里？",a="该洞穴位于丧钟镇主聚居地和墓地的正西北方，坐落在提瑞斯法林地那隐蔽山谷周边的岩石峭壁中。",al={"夜行蜘蛛洞穴在哪里","丧钟镇蜘蛛洞穴","夜行蜘蛛洞穴位置"}},{q="被遗忘者能在完成这个任务后立即开采黄金吗？",a="不能立即开采。执行官阿伦指出，彻底根除虫害需要数周甚至数月的持续努力，随后还需采矿队用火把烧掉蔓延的蛛网，矿工才能安全地挖掘矿脉。",al={"矿洞清理完毕了吗","他们能得到黄金吗","那些蜘蛛怎么了"}},{q="为什么阿伦不派一整支士兵分队去清理洞穴？",a="丧钟镇的驻军兵力吃紧，既要防范在外围游荡的无脑天灾，又要巡逻警戒血色十字军的斥候。阿伦实在没有多余的人手来派遣正规小队进行虫害治理，只能让新复活的招募者一点点清理矿洞。",al={"为什么派遣新兵","为什么不使用丧钟镇卫兵","阿伦人手不足"}},{q="蜘蛛毒液会伤害亡灵吗？",a="虽然被遗忘者不会像生者那样流血或呼吸，但腐蚀性的蜘蛛毒液依然会灼伤经过防腐处理的血肉，削弱复活肢体的机能。执行官阿伦特别警告新兵，要注意毒液带来的剧烈灼烧感，如果中毒应立即寻求治疗。",al={"毒液会伤害亡灵吗","被遗忘者蜘蛛毒素","被遗忘者免疫毒素吗"}}},fp="18,266,24.435.0,17.406.0,35.278.0,22.219.0,36.140.0,68.202.0,71.258.0,33.233.0"}
P.entries["quest:381"] = {n="血色十字军",s="这项来自执行官阿伦的早期任务，要求刚觉醒的被遗忘者去伏击丧钟镇东南方的一处血色十字军狂热者营地。这是被遗忘者接触他们最狂热、最顽固的敌人之一的阴郁序曲。",h="这项来自执行官阿伦的早期任务，要求刚觉醒的被遗忘者去伏击丧钟镇东南方的一处血色十字军狂热者营地。这是被遗忘者接触他们最狂热、最顽固的敌人之一的阴郁序曲。",kw={"丧钟镇","执行官阿伦","血色臂章","血色皈依者","血色十字军","血色新兵","提瑞斯法林地"},ang={["class:Priest"]="与血色十字军的对抗，迫使被遗忘者牧师面对他们曾经在洛丹伦崇拜的神圣之光是如何被扭曲成狂热仇恨的。",["faction:Horde"]="血色十字军的无情侵略，强调了为什么被遗忘者要寻求部落提供的共同防御与保护。",["race:Undead"]="对于刚复生的被遗忘者来说，这项任务是他们早期的第一课，让他们了解到活人是如何看待他们的：仅仅是应当被彻底消灭的怪物，而不论其是否拥有自由意志。"},sec={{t="狂热的威胁",b="当夜网蜘蛛的直接威胁解除后，执行官阿伦将丧钟镇的注意力转向了另一个迫在眉睫的威胁。一支血色十字军小队在定居点东南方建立了一个立足点。这些狂热分子拒绝承认无意识的天灾军团爪牙与拥有自由意志的被遗忘者之间有任何区别，这意味着他们在边境的存在对刚复生的亡灵构成了生存威胁。"},{t="先发制人的报复",b="深知无法与那些将所有亡灵血肉都视为憎恶的圣教狂热者进行对话，阿伦下令发动先发制人的攻击。冒险者们被派去在营地发展成针对丧钟镇的有组织突击力量之前，消灭其中的血色十字军新兵和皈依者。带回的战利品——他们的红色臂章——是必须以武力在提瑞斯法争取生存的铁证。"}},faq={{q="谁是血色十字军？",a="血色十字军是一个极端的宗教运动，致力于彻底消灭亡灵。在洛丹伦陷落后，他们因悲伤和宗教狂热而陷入疯狂，拒绝区分无意识的天灾军团怪物和拥有自我意识的被遗忘者，试图不加区别地清洗两者。",al={"血色十字军背景故事","什么是血色十字军","血色狂热者"}},{q="为什么血色十字军在丧钟镇附近扎营？",a="丧钟镇是新的被遗忘者复生和聚集的地方。血色十字军建立了一个小型前哨站，旨在监视该地区，伺机偷袭刚复生的亡灵，并集结兵力摧毁这个初生的被遗忘者定居点。",al={"为什么血色十字军在丧钟镇","丧钟镇血色营地"}},{q="为什么被遗忘者选择先发制人而不是谈判？",a="正如执行官阿伦所指出的，十字军被狂热蒙蔽了双眼，认为所有亡灵都是必须消灭的憎恶。他们不会听取理性的建议，也不会与死者谈判，这使得先发制人的屠杀成为唯一可行的防御手段。",al={"被遗忘者能与血色十字军谈判吗","为什么要攻击血色十字军"}},{q="营地里的十字军是什么军阶？",a="营地主要由新兵和受训者组成，具体来说是血色皈依者和血色新兵。尽管他们在十字军的等级体系中地位较低，但他们的狂热使他们对刚复生的被遗忘者构成了危险。",al={"营地里有什么人","血色皈依者和新兵"}},{q="完成这个任务会导致什么？",a="来自布瑞尔执行官阿伦上级的报告显示，一名十字军信使已从血色修道院被派往该营地。这促使执行官阿伦指派你去拦截这名红色信使，以揭露他们的作战计划。",al={"后续任务是什么","血色十字军后续任务线"}},{q="执行官阿伦是谁？",a="执行官阿伦是负责监督丧钟镇安全与防务的主要军事指挥官，指挥刚觉醒的被遗忘者对抗周边的威胁。",al={"阿伦的角色","谁发布了任务"}}},fp="19,205,18.346.0,22.302.0,28.245.0,51.207.0,50.205.0,47.187.0,42.195.1,22.132.0"}
P.entries["quest:382"] = {n="十字军信使",s="执行官阿伦派遣刚复生的被遗忘者去截获一名从血色修道院出发，前往丧钟镇外血色十字军营地的信使。截获这名信使可以在狂热分子巩固其在山谷中的据点前，获取关于当地血色十字军动向的关键情报。这项任务是确保被遗忘者初生的避难所所采取的最早期的进攻行动之一。",h="执行官阿伦派遣刚复生的被遗忘者去截获一名从血色修道院出发，前往丧钟镇外血色十字军营地的信使。截获这名信使可以在狂热分子巩固其在山谷中的据点前，获取关于当地血色十字军动向的关键情报。这项任务是确保被遗忘者初生的避难所所采取...",kw={"布瑞尔","丧钟镇","执行官阿伦","梅文·科尔加尔","红色信使","血色十字军","血色十字军文件","血色修道院","提瑞斯法林地"},ang={["class:Rogue"]="潜入十字军营地刺杀梅文·科尔加尔并窃取密件，是新苏醒的潜行者最典型、最基础的隐秘工作。",["faction:Horde"]="通过拆解丧钟镇边界的血色十字军行动，新兵们保护了部落在东部王国新建立的立足点的北部防线。",["race:Undead"]="截获这名信使，是对那些试图在你还没在洛丹伦站稳脚跟前就第二次处决你的狂热分子的一次沉重打击。"},sec={{t="东方的注视",b="消息在提瑞斯法林地传播得很快，即使是在亡者之中也是如此。布瑞尔的上级向执行官阿伦发出警报，称血色十字军从其位于血色修道院的据点派遣了一名特使前往西方的丧钟镇。虽然十字军在整个洛丹伦都保持着咄咄逼人的态势，但直接派遣一名信使到被遗忘者苏醒之地的边缘，表明他们正在进行有组织的推进，试图在这些刚复生的亡灵组织起有效的防御之前将其彻底消灭。"},{t="拦截信使",b="信使梅文·科尔加尔混入了丧钟镇东部的一个小型血色十字军营地中，身上没有携带任何显眼的纹章。执行官阿伦下达了一次精准打击，旨在刺杀科尔加尔并没收他的密件。剥夺信使的文书可以切断当地狂热分子与其东部总部的战术协调。"},{t="重要的密件",b="翻阅缴获的血色十字军文件，可以发现其中混杂着宣传材料、侦察记录，以及指示狂热分子在废墟之都附近扩大营地的直接命令。最关键的是，这些文件中包含了一张战略地图，上面标明了整个林地内战地指挥官和特工的位置——这是一个价值极高，值得立即送交布瑞尔上级的发现。"}},faq={{q="谁是红色信使？",a="这名信使是梅文·科尔加尔，一名效力于血色十字军的人类信使。他直接从血色修道院被派往此地，向盘踞在丧钟镇附近的狂热分子传达战略命令。",al={"梅文·科尔加尔","谁是梅文·科尔加尔","谁是信使","血色信使身份"}},{q="信使是从哪里来的？",a="他从血色修道院出发，那是位于提瑞斯法林地东北部的血色十字军的大型要塞总部。",al={"科尔加尔从哪里来","信使来源","血色信使来源"}},{q="文件中发现了什么信息？",a="这些密件中包含了侦察摘要、指示十字军在洛丹伦废墟之城附近加固工事的命令，以及一份详细列出了十字军战地指挥官和特工所在位置的战略地图。",al={"血色文件内容","命令是什么","科尔加尔携带了什么"}},{q="这份情报接下来会去哪？",a="执行官阿伦立即通过后续任务“重要情报”将地图和收集到的信息转发给布瑞尔的上级，从而为广大的被遗忘者军队提供整个提瑞斯法地区的可行动目标。",al={"文件怎么处理","去哪递交血色文件","重要情报任务"}},{q="为什么血色十字军要侵入到离丧钟镇这么近的地方？",a="血色十字军认为所有的亡灵都是必须被不加区分地消灭的畸形。丧钟镇是刚获得自由的亡灵最初从坟墓中爬出来的地方，这使它成为狂热分子试图在被遗忘者组织起来之前将其铲除的理想目标。",al={"为什么血色十字军在丧钟镇","丧钟镇的十字军","为什么狂热分子在这里"}},{q="是谁给执行官阿伦提供了关于信使的情报？",a="驻扎在布瑞尔的被遗忘者指挥部截获了信使离开修道院的消息，并将情报传达给了阿伦，以便他的当地部队能够进行拦截。",al={"谁警告了阿伦","谁发报告给阿伦","被遗忘者如何得知"}}},fp="17,361,16.372.0,24.305.0,16.334.1,25.157.0,34.132.0,44.194.1,37.169.1,62.236.0,52.153.0"}
P.entries["quest:3821"] = {n="巨槌石",s="萨特拉克·长齿的妻子沙妮在三周前被派往调查火腹食人魔中间发生的诡异仪式，但至今没有人收到她小队的消息。萨特拉克无法离开岗位，因此他请求你去探寻她的下落。",h="萨特拉克·长齿的妻子沙妮在三周前被派往调查火腹食人魔中间发生的诡异仪式，但至今没有人收到她小队的消息。萨特拉克无法离开岗位，因此他请求你去探寻她的下落。",kw={"荒芜之地","燃烧平原","巨槌石","火腹食人魔","戈托克","沙妮·长齿","萨特拉克"},sec={{t="杳无音信的丈夫",b="沙妮的命令将她带往了燃烧平原，去调查火腹食人魔中间发生的诡异仪式。那已经是三周前的事了。戈托克说他没有收到任何关于她小队成员的消息，并劝萨特拉克忘掉这件事，坚守自己的岗位。萨特拉克无法接受这一点，毕竟失踪的是他的妻子。由于无法擅离职守，他请求你亲自去那里寻找她。"},{t="沙妮的话语",b="沙妮提到了萨特拉克，语气中带着怜悯。他们原本计划在服役期满后搬去辛特兰与她的父母同住，但现在这些计划都化为泡影了。"}},faq={{q="萨特拉克在寻找谁？",a="他的妻子，沙妮·长齿。她被派往燃烧平原调查火腹食人魔的诡异仪式，之后便音讯全无。",al={"谁失踪了","萨特拉克的妻子","沙妮·长齿"}},{q="为什么沙妮去了燃烧平原？",a="她在三周多以前被派往那里，去调查关于火腹食人魔举行诡异仪式的报告。",al={"沙妮的任务","火腹食人魔的仪式","沙妮为何离开"}},{q="为什么萨特拉克不亲自去寻找她？",a="他无法离开自己的岗位，因此他请求你代替他前往。",al={"萨特拉克为何不能离开","萨特拉克为何在等待"}},{q="戈托克对失踪的小队有什么看法？",a="戈托克没有收到任何关于该小队的消息，并告诉萨特拉克把这件事放下，继续执行他的职责。",al={"戈托克的反应","戈托克说了什么"}}},fp="14,240,22.409.0,14.174.1,29.147.0,41.109.0,46.60.0,50.119.0"}
P.entries["quest:383"] = {n="重要情报",s="“重要的情报”标志着一名新生的被遗忘者在丧钟镇的训练即将结束。信使带着截获的血色十字军文件，被派往提瑞斯法林地，向布瑞尔的执行官塞加德汇报。",h="“重要的情报”标志着一名新生的被遗忘者在丧钟镇的训练即将结束。信使带着截获的血色十字军文件，被派往提瑞斯法林地，向布瑞尔的执行官塞加德汇报。",kw={"布瑞尔","炉灰庄园","丧钟镇","文件","执行官阿伦","执行官塞加德","血色十字军","提瑞斯法林地","重要的情报"},ang={["faction:Horde"]="在此处收集的情报有助于被遗忘者巩固对提瑞斯法林地的控制，保护幽暗城北部的门户免受十字军的入侵。",["race:Undead"]="携带这些截获的计划代表着一种成人礼：在从坟墓中爬出并证明了自己的价值后，你将从丧钟镇的摇篮被派遣去参与洛丹伦更广阔的战争。"},sec={{t="离开丧钟镇",b="在清除了当地的威胁并截获了一名血色十字军的信使后，新招募的被遗忘者被认为已经做好了服更广泛兵役的准备。执行官阿伦将找回的情报交给玩家，指引他们穿过丧钟镇隐蔽的峡谷，沿着道路向东前往布瑞尔，路过炉灰庄园。"},{t="决定性的一击",b="抵达布瑞尔后，执行官塞加德会对缴获的信件进行评估。这些文件包含名册和详细信息，可以确认在提瑞斯法林地各地活动的血色十字军指挥官，为实施有针对性的暗杀奠定了基础，旨在瓦解这些狂热者的领导层并摧毁其士气。"}},faq={{q="血色十字军文件里有什么信息？",a="缴获的文件包含了驻扎在提瑞斯法林地各处的血色十字军军官的名单和任务。执行官塞加德打算利用这些名册来锁定目标，并通过迅速、令人沮丧的打击来消灭他们的当地领导层。",al={"血色文件是什么","血色十字军文件内容","收集了什么情报"}},{q="执行官塞加德在哪里？",a="执行官塞加德驻扎在布瑞尔，位于布瑞尔城镇大厅外的城镇广场上。",al={"塞加德在哪里","寻找执行官塞加德","执行官塞加德位置"}},{q="我该怎么从丧钟镇前往布瑞尔？",a="沿着丧钟镇北面的路走。在通往更广阔的提瑞斯法林地的岔路口，走东边的路，继续前行，经过炉灰庄园，穿过带顶棚的桥，直达布瑞尔。",al={"前往布瑞尔的路线","怎么去布瑞尔","前往布瑞尔的方向"}},{q="为什么这个任务标志着丧钟镇篇章的结束？",a="丧钟镇是新苏醒的被遗忘者的初始试炼之地。一旦你帮助稳固了这里的局势，并收集到关于血色十字军的情报，执行官阿伦就会将你调派给布瑞尔的高阶指挥官。",al={"丧钟镇任务完成","为什么要离开丧钟镇","这是丧钟镇的最后一个任务吗"}},{q="执行官阿伦是谁？",a="执行官阿伦是被遗忘者的军官，负责监督丧钟镇的行动、安全以及新苏醒的亡灵的初步整合。",al={"阿伦是谁","阿伦的背景故事"}},{q="上交这些文件后会发生什么？",a="递交这些文件将使你融入以布瑞尔为基地的更广泛的被遗忘者军事行动中，从而开启在整个提瑞斯法林地拆除当地血色十字军营地和天灾军团残余势力的任务。",al={"what comes next","重要的情报之后的下一个任务"}}},fp="18,145,18.301.0,17.233.1,57.211.0,33.88.0,38.170.0,49.219.0,22.136.0,46.201.0"}
P.entries["quest:384"] = {n="啤酒烤猪排",s="卡拉诺斯的雷酒酿制厂的拉格纳·雷酒需要新鲜的峭壁野猪排和一满杯狂想麦酒，来招待他旅店里那些饥肠辘辘的顾客。由于他平时的肉类供应商参军去了，拉格纳只能指望过路的旅人来帮忙，好让那道闻名遐迩的猪排继续留在菜单上。",h="卡拉诺斯的雷酒酿制厂的拉格纳·雷酒需要新鲜的峭壁野猪排和一满杯狂想麦酒，来招待他旅店里那些饥肠辘辘的顾客。由于他平时的肉类供应商参军去了，拉格纳只能指望过路的旅人来帮忙，好让那道闻名遐迩的猪排继续留在菜单上。",kw={"啤酒炖猪排","峭壁野猪","丹莫罗","卡拉诺斯","拉格纳·雷酒","狂想麦酒","雷酒酿制厂"},ang={["faction:Alliance"]="即便是卡拉诺斯的旅店补给短缺，也与广泛的联盟战争努力有关，因为当地的山民纷纷放下手中的营生，响应号召参军入伍。",["profession:Cooking"]="对炉边烹饪感兴趣的冒险者，可以直接向丹莫罗最著名的酿酒大师之一，学习将麦芽酒与野味融合的秘诀。",["race:Dwarf"]="对于矮人来说，醇厚的麦酒和烤野猪是山区待客之道的基石，因此维持酿制厂的供应是一项关乎地方荣誉的大事。"},sec={{t="急需补给的旅店",b="位于卡拉诺斯的雷酒酿制厂以醇厚的矮人麦酒和丰盛的旅店菜肴而闻名。其中最著名的当属传奇的啤酒炖猪排。然而，旅店老板拉格纳·雷酒现在陷入了困境：负责供应肉类的当地猎人最近参军支持联盟前线去了，这让拉格纳面临着顾客盈门却无肉可做的窘境。"},{t="秘制配方",b="想要重新制作这道菜，就必须从卡拉诺斯周围积雪覆盖的山麓中，狩猎那些强壮的峭壁野猪。但这道菜真正的秘诀在于腌料。拉格纳坚持要用直接从酿制厂酒桶里取出的新鲜狂想麦酒。麦酒能分解坚韧的野味，将粗糙的山区猎物变成足以令矮人交口称赞的美味盛宴。"}},faq={{q="拉格纳·雷酒为什么缺肉？",a="拉格纳平时的肉类供应商是一名当地的山地捕兽人，他离开了卡拉诺斯，参军支持联盟在海外的军事行动，导致旅店失去了稳定的野味供应。",al={"为什么拉格纳需要猪排","拉格纳的肉类供应商怎么了","谁供应猪排"}},{q="狂想麦酒是从哪里来的？",a="狂想麦酒是在卡拉诺斯的雷酒酿制厂内直接酿造并供应的，在旅店吧台就可以直接向旅店老板购买。",al={"在哪里获取狂想麦酒","如何为拉格纳获取麦酒","谁出售狂想麦酒"}},{q="什么样的野猪可以提供猪排？",a="肉取自那些在整个丹莫罗地区的卡拉诺斯周边的丘陵、雪堆和冰封峡谷中游荡的峭壁野猪。",al={"哪种野猪掉落猪排","在丹莫罗哪里找到猪排","丹莫罗的峭壁野猪"}},{q="拉格纳的猪排配方有什么秘诀？",a="秘诀在于用狂想麦酒炖煮坚韧的猪排，这不仅能使寒冷地区的野味变得鲜嫩，还能融入矮人酿造工艺带来的浓郁风味。",al={"啤酒炖猪排的秘诀","啤酒炖猪排秘方"}},{q="谁在为国王的军队在前线战斗？",a="矮人新兵经常加入国王的军队，以支持联盟在东部王国各地针对穴居人、黑铁矮人入侵及其他军事战线上的持续冲突。",al={"捕兽人为什么参军","国王的军队在打什么战争","联盟前线 25 adp"}},{q="雷酒酿制厂位于哪里？",a="酿制厂是卡拉诺斯主要的旅店，位于贯穿丹莫罗中心地带的主干道旁。",al={"雷酒酿制厂在哪里","拉格纳·雷酒在哪里","卡拉诺斯旅店位置"}}},fp="21,224,16.240.0,21.254.0,40.215.0,35.123.0,36.108.0,42.138.0,55.155.0,44.112.0"}
P.entries["quest:3841"] = {n="领养孤儿",s="在执行正义之后，辛达尔·月纹在你从达纳苏斯归来时迎接你并带来了一个消息：一窝蛋被救了下来，虽然母亲已经死了。辛达尔愿意给你一颗蛋作为宠物，并让你去找奎恩丁，他正在千针石林的闪光平原的赛道旁等待。",h="在执行正义之后，辛达尔·月纹在你从达纳苏斯归来时迎接你并带来了一个消息：一窝蛋被救了下来，虽然母亲已经死了。辛达尔愿意给你一颗蛋作为宠物，并让你去找奎恩丁，他正在千针石林的闪光平原的赛道旁等待。",kw={"蛋","菲拉斯","辛达尔·月纹","奎恩丁","闪光平原","小精龙","千针石林"},sec={{t="失去母亲的鸟巢",b="辛达尔·月纹很高兴看到你从达纳苏斯回来，并汇报了你离开期间取得的进展。一窝蛋被救了下来，尽管母亲在救援赶到之前就已经死了。这些蛋看起来很快就要孵化了，所以它们需要一个好的照料者，而辛达尔愿意给你一颗作为宠物。如果你真的有兴趣，就把这颗蛋带到闪光平原的赛道，奎恩丁会在那里告诉你更多信息。"},{t="在闪光平原的奎恩丁",b="奎恩丁正在千针石林，并让你不要被这个地方误导：比赛并不是他出现在那里的原因。奎恩丁正在调查这片土地的可补救性，希望能用新的肥沃土壤来滋养它，并可能找到附近的水源。奎恩丁也觉得菲拉斯和千针石林之间的变化很奇怪，并说这种变化发生时，有奇怪的魔法在作祟。"},{t="奎恩丁对这颗蛋的看法",b="奎恩丁将其命名为精龙的蛋，它已接近成熟，状态非常好，并对你能找到一颗感到惊讶。如今在菲拉斯很少见到这种生物了；奎恩丁听说有偷猎者在附近活动，为了各种原因猎杀或捕获它们。奎恩丁认为这很可惜，因为它们长大后非常美丽，并问你是如何找到这种宝贝的。"}},faq={{q="这颗蛋是从哪里来的？",a="当你在达纳苏斯的时候，辛达尔·月纹和其他人救下了一窝蛋。母亲在他们到达之前就已经死了。",al={"蛋是从哪里来的","蛋的来源","精龙的蛋背景故事"}},{q="在哪里可以找到奎恩丁？",a="在千针石林的闪光平原的赛道旁。",al={"奎恩丁的位置","奎恩丁在哪里","奎恩丁 闪光平原"}},{q="为什么奎恩丁会在闪光平原？",a="不是为了比赛。奎恩丁正在调查这片土地的可补救性，希望能为该地区带来新的肥沃土壤，并可能在附近找到水源。",al={"为什么奎恩丁在赛道","奎恩丁在做什么","奎恩丁的研究"}}},fp="28,292,23.404.0,20.381.0,29.383.1,28.128.0,27.63.0,39.158.0"}
P.entries["quest:3842"] = {n="即将孵化",s="身处千针石林的奎恩丁听说月织者将精龙的蛋交给了你。这枚蛋看起来快要孵化了，所以奎恩丁想要确认它是否健康、完好，并向你索要两瓶坚韧药剂。",h="身处千针石林的奎恩丁听说月织者将精龙的蛋交给了你。这枚蛋看起来快要孵化了，所以奎恩丁想要确认它是否健康、完好，并向你索要两瓶坚韧药剂。",kw={"坚韧药剂","菲拉斯","沙漠赛道","月织者","奎恩丁","精龙的蛋","千针石林"},ang={["profession:Alchemy"]="炼金术士可以制作奎恩丁所需要的坚韧药剂。"},sec={{t="保护蛋",b="奎恩丁觉得月织者照料这枚蛋的事情很有趣，并认为他们两方都很能干。既然这枚蛋是送给你的礼物，那么只要你愿意，它就归你负责。它看起来快要孵化了，但应该先检查一下它的健康状况和是否有损伤。一个小小的保护咒语就能搞定，奎恩丁手头有所有的材料，唯独缺两瓶坚韧药剂。奎恩丁承认他在等待的时候被赛车比赛吸引了，一旦确认了蛋的健康状况，他就会把蛋还给你继续保管。"}},faq={{q="谁想要坚韧药剂？",a="身处千针石林沙漠赛道附近的奎恩丁，向你索要两瓶坚韧药剂。",al={"谁给予这个任务","任务发布者","奎恩丁的位置"}},{q="在此之前发生了什么？",a="在“寻找家园的孤儿”任务中，你把这枚蛋带给了奎恩丁。这是月织者赠送的礼物。",al={"前置任务","蛋从哪里来","前置条件"}},{q="完成咒语需要什么？",a="两瓶坚韧药剂。奎恩丁已经随身准备好了其他材料。",al={"我需要带什么","所需物品","所需的坚韧药剂"}},{q="奎恩丁为什么想要这些药剂？",a="这枚蛋即将孵化，奎恩丁想要确认它是健康且未受损的。这些药剂用于一个保护它的简单咒语中。",al={"为什么需要坚韧药剂","药剂的用途"}}},fp="18,233,18.526.0,30.93.0,32.99.0,35.76.0,34.132.0"}
P.entries["quest:3843"] = {n="新的生命",s="在“短暂的孵化”之后，奎恩丁称这枚蛋为一个壮观的标本，并派你去往辛特兰的鹰巢山，找一位名叫阿格纳的矮人。这枚蛋非常脆弱，你只有一小时的时间找到阿格纳，否则里面的幼崽就会死亡。",h="在“短暂的孵化”之后，奎恩丁称这枚蛋为一个壮观的标本，并派你去往辛特兰的鹰巢山，找一位名叫阿格纳的矮人。这枚蛋非常脆弱，你只有一小时的时间找到阿格纳，否则里面的幼崽就会死亡。",kw={"鹰巢山","阿格纳","菲拉斯","脆弱的蛋","辛特兰","奎恩丁","小精龙"},sec={{t="赶往鹰巢山",b="奎恩丁认为这枚精龙的蛋是一个壮观的标本；如果它能存活，将会成为一只健康的宠物。还有最后一件事：去往辛特兰的鹰巢山，与阿格纳交谈。他是一位驯兽大师，可以指导孵化的最后步骤。这枚蛋非常脆弱，没有妥善照料无法支撑太久：如果你在一小时内没有找到阿格纳，里面的幼崽就会死亡。阿格纳住在蛮锤城堡。"},{t="阿格纳的鉴定",b="阿格纳很久没见过这种生物了，并将其命名为小精龙。为了让这个小家伙顺利孵化并茁壮成长，需要提供食物，阿格纳很高兴你能及时赶到。"}},faq={{q="是谁派你去找阿格纳？",a="是奎恩丁，他在“短暂的孵化”任务后续中，让你带着这枚脆弱的蛋前往辛特兰的鹰巢山。",al={"任务发布者","谁开启了“家庭新成员”","蛋的任务发布者"}},{q="谁必须接收这枚蛋？",a="阿格纳，一位在辛特兰鹰巢山的矮人驯兽大师。阿格纳住在蛮锤城堡。",al={"我该把蛋带到哪里","阿格纳是谁","谁来接收这枚蛋"}},{q="运送这枚蛋有多少时间？",a="一小时。如果在这段时间内没有把蛋交给阿格纳，里面的幼崽就会死亡。",al={"蛋的时间限制","我有多少时间","蛋的计时器"}},{q="这一步在任务链中处于什么位置？",a="它紧随“短暂的孵化”之后，需要将蛋交给在鹰巢山的阿格纳。",al={"任务链","what comes next","任务链进度"}}},fp="31,244,19.439.0,15.204.1,33.112.0,25.116.0,42.88.0,38.87.0"}
P.entries["quest:385"] = {n="捕猎鳄鱼",s="洛克莫丹的旅行者营地经营着鳄鱼皮和鳄鱼肉的贸易，虽然危险，但生意十分稳定。马雷克·铁心经常寻找那些愿意在湖岸和岛屿上冒险的坚韧追踪者，以狩猎这些珍贵的野兽。对于渴望在咬合的巨颚和坚硬的兽皮面前磨练意志的猎人来说，洛克湖既是竞技场，也能带来利润。",h="洛克莫丹的旅行者营地经营着鳄鱼皮和鳄鱼肉的贸易，虽然危险，但生意十分稳定。马雷克·铁心经常寻找那些愿意在湖岸和岛屿上冒险的坚韧追踪者，以狩猎这些珍贵的野兽。对于渴望在咬合的巨颚和坚硬的兽皮面前磨练意志的猎人来说，洛克湖既...",kw={"鳄鱼狩猎","鳄鱼肉","鳄鱼皮","矮人猎人","旅行者营地","洛克莫丹","马雷克·铁心","洛克湖"},ang={["class:Hunter"]="对于想要磨练胆识以对抗洛克湖水下恐怖生物的有志射手和兽王猎人来说，旅行者营地是一个理想的试炼场。",["profession:Cooking"]="坚韧精瘦的鳄鱼肉为边境营地的篝火提供了制作美味炖菜和烤肉的丰盛主料。",["race:Dwarf"]="登山家们以征服洛克莫丹的荒野为荣，他们将狩猎鳄鱼视为一种务实的生存之道和正当的营生。"},sec={{t="有利可图的猎物",b="洛克莫丹因其宁静的山间水域而备受推崇，但湖面之下却潜伏着凶猛的掠食者。鳄鱼在浅滩和泥泞的河岸边繁衍生息，使得横渡或垂钓对于粗心大意的人来说变得危机四伏。然而，对于驻扎在旅行者营地的户外探索者来说，这些危险的爬行动物是珍贵的猎物。整个卡兹莫丹的工匠和裁缝们都在不断寻求耐用的鳄鱼皮来制作坚固的护甲和皮革制品，而乡村酒馆也愿意花大价钱购买鲜美多汁、肉质精瘦的鳄鱼尾肉。"},{t="浅滩巨颚",b="狩猎洛克湖的鳄鱼并非新手捕兽人的差事。这些野兽主要盘踞在点缀于湖面的岩石小岛周围，它们拥有能粉碎骨头的巨颚，布满了如剃刀般锋利的牙齿。像马雷克·铁心这样的矮人老兵身上满是与这些野兽搏斗留下的伤疤，他们警告新来者，在水中踏错一步就可能丢掉一条胳膊。想要成功地剥皮和屠宰它们，需要耐心、坚硬的钢铁，以及敢于直接踏入这些爬行动物猎场的勇气。"}},faq={{q="为什么要在洛克莫丹狩猎鳄鱼？",a="商人和工匠们非常看重鳄鱼皮，因为它们可以用来制作坚固的服装和皮甲，而它们的肉也被认为是一种美味的地方佳肴。旅行者营地经营着这些资源的稳定贸易，以供应往来卡兹莫丹的商旅。",al={"为什么要狩猎鳄鱼","鳄鱼肉和鳄鱼皮的用途","马雷克为什么要狩猎鳄鱼"}},{q="鳄鱼通常在哪里出没？",a="鳄鱼栖息在泥泞的浅滩、湖岸边，尤其是位于洛克湖中心的一些岩石岛屿上。",al={"鳄鱼位置","在洛克莫丹哪里能找到鳄鱼","鳄鱼在哪里"}},{q="马雷克·铁心是谁？",a="马雷克·铁心是一位经验丰富的矮人登山家兼猎人，驻扎在洛克莫丹东南部的旅行者营地。他从事当地野生动物材料的贸易，并乐于讲述自己在洛克湖最凶猛野兽的利爪下死里逃生的故事。",al={"马雷克·铁心","谁发布狩猎鳄鱼的任务","任务发布者马雷克"}},{q="为什么狩猎它们如此危险？",a="洛克莫丹的鳄鱼是一种富有攻击性的领地型掠食者，拥有巨大的咬合力和匕首般的利齿。猎人们必须进入深水区或孤立的小岛才能与它们交战，而在对爬行动物有利的地形中，随时可能面临突袭。",al={"鳄鱼危险吗","鳄鱼的危险性","为什么鳄鱼难以猎杀"}},{q="鳄鱼肉真的可以安全食用吗？",a="是的，鳄鱼肉因其紧实的口感和浓郁、丰盛的风味而受到整个矮人领地边境厨师和酒馆常客的推崇，只要经过妥善处理和烘烤，便是一道佳肴。",al={"鳄鱼肉可以吃吗","鳄鱼肉可食用性","鳄鱼肉的味道"}},{q="旅行者营地是什么地方？",a="旅行者营地是位于洛克莫丹东南部的一个风景优美的哨站，作为联盟猎人、追踪者和登山家的避风港和集结地，他们负责监视山谷中荒野地带的情况。",al={"什么是旅行者营地","旅行者营地的用途","旅行者营地在哪里"}}},fp="17,195,18.227.0,20.374.0,40.200.0,39.125.0,23.213.0,37.209.0,43.159.0,29.179.0"}
P.entries["quest:386"] = {n="伸张正义",s="“善恶终有报”是一个联盟任务，由湖畔镇的卫兵伯尔顿提供，他对围绕一名兽人战争罪犯的政治拖延感到愤怒。玩家被派往暴风城监狱，在腐败的贵族安排他逃脱之前处决可怕的塔格尔。",h="“善恶终有报”是一个联盟任务，由湖畔镇的卫兵伯尔顿提供，他对围绕一名兽人战争罪犯的政治拖延感到愤怒。玩家被派往暴风城监狱，在腐败的贵族安排他逃脱之前处决可怕的塔格尔。",kw={"伯尔顿","黑石","刽子手","加塞尔佐格","湖畔镇","赤脊山","监狱","塔格尔"},ang={["class:Paladin"]="绕过腐败的法律暂缓执行令，对一名不知悔改的施虐者进行惩罚，挑战了法典化法律与真正的道德正义之间的平衡。",["faction:Alliance"]="该任务揭示了像湖畔镇这样的前线边境驻军与暴风城贵族法庭内自私的政治阴谋之间日益扩大的鸿沟。",["race:Human"]="对于王国的人类来说，处决塔格尔是为了偿还黑石入侵赤脊山期间，当地城镇卫兵和民兵所遭受暴行的个人恩怨。"},sec={{t="悬而未决的刽子手",b="可怕的塔格尔在赤脊山臭名昭著，他曾担任黑石兽人酋长加塞尔佐格将军手下的首席刽子手，这些兽人盘踞在石堡要塞。塔格尔以残酷著称，即便是黑石入侵者中也以此闻名，他曾亲自监督对多名赤脊山守军的拷打和处决。在最终被俘后，他被转移到首都的高警戒监狱——暴风城监狱，并因其对王国的暴行被判处死刑。"},{t="高层的腐败",b="尽管可怕的塔格尔被正式判处死刑，但由于暴风城贵族议会中某位未具名的贵族进行干预，他的处决被叫停了。驻扎在脆弱的湖畔镇的卫兵伯尔顿看穿了这些政治把戏，怀疑其中存在肮脏交易或贿赂，意图确保这个残暴的家伙最终被释放。伯尔顿决定亲自伸张正义，招募值得信赖的冒险者潜入发生暴乱的监狱，绕过官僚主义的干预，执行死刑判决。"}},faq={{q="可怕的塔格尔是谁？",a="可怕的塔格尔是一名精锐的黑石兽人，曾在赤脊山担任加塞尔佐格将军手下的首席刽子手。他因折磨被俘的人类士兵而臭名昭著，最终被俘并被关押在暴风城监狱中。",al={"塔格尔","塔格尔是谁","塔格尔背景故事"}},{q="为什么暴风城还没有处决塔格尔？",a="尽管已被判处死刑，但他的处决因首都一位有权势的贵族干预而被无限期搁置。卫兵伯尔顿怀疑其中涉及政治腐败或隐蔽的黑幕，旨在赦免或利用这位兽人军阀。",al={"为什么塔格尔还活着","贵族推迟执行死刑"}},{q="谁提供了“善恶终有报”任务？",a="卫兵伯尔顿提供了这个任务。他驻扎在赤脊山的湖畔镇，保卫城镇免受黑石兽人的持续入侵。",al={"任务发布者","哪里领取任务"}},{q="可怕的塔格尔在哪里可以找到？",a="塔格尔被关押在暴风城监狱内，监狱位于暴风城运河区。通常可以在监狱中央监区的牢房里找到他。",al={"塔格尔位置","塔格尔在哪里"}},{q="加塞尔佐格将军是谁？",a="加塞尔佐格将军是占据赤脊山东部石堡要塞的黑石兽人部队的指挥官，塔格尔曾在他手下担任刽子手。",al={"加塞尔佐格","赤脊山黑石将军"}},{q="为什么卫兵伯尔顿要亲自采取行动？",a="伯尔顿亲眼目睹了赤脊山的士兵在塔格尔的屠刀下受苦和死亡。他对于暴风城的政客将一名冷血杀手视为政治筹码感到厌恶，因此绕过官方的官僚程序，以确保真正的正义得到伸张。",al={"伯尔顿动机","为什么要绕过贵族"}}},fp="20,192,23.445.0,25.341.1,25.208.0,42.162.0,41.137.0,37.144.0,27.135.0,54.207.0"}
P.entries["quest:3861"] = {n="咕咕嘎！",s="“咯咯哒！”是一个不同寻常且充满隐秘的互动，能让冒险者赢得普通农场禽类的信任。通过模仿鸡的叫声并提供适当的谷物，旅行者可以获得一枚珍贵的蛋，孵化出属于自己的羽翼伙伴。",h="“咯咯哒！”是一个不同寻常且充满隐秘的互动，能让冒险者赢得普通农场禽类的信任。通过模仿鸡的叫声并提供适当的谷物，旅行者可以获得一枚珍贵的蛋，孵化出属于自己的羽翼伙伴。",kw={"小鸡","鸡蛋","咯咯哒","禽类","萨丁","萨丁农场","特殊的鸡饲料","西部荒野小鸡"},ang={["faction:Alliance"]="这项任务围绕着西部荒野的萨丁农场展开，使得这种奇异的羽毛仪式成为年轻联盟冒险者在探索这个饱受蹂躏的农村王国时的一段经典故事。",["profession:Cooking"]="鸟儿所需的特殊的鸡饲料是完全可以食用的，不过大多数厨师宁愿把这些粗粮留给鸟儿吃，也不愿自己食用。"},sec={{t="奇特的交流",b="虽然大多数旅行者对艾泽拉斯农场里随处可见的普通鸡不屑一顾，但这些禽类却有着令人惊讶的洞察力。如果冒险者愿意俯下身，模仿它们的动作和叫声足够长的时间，鸡就会停止毫无目的的啄食，转而以一种不可思议的兴趣注视着这位凡人。在那短暂的交流时刻，鸟儿会在泥土中抓出字母，暗示它的饥饿，并指引好奇者去找能喂养它的合适农夫。"},{t="农夫的饲料",b="满足鸟儿那神秘的要求需要获得特殊的鸡饲料。在西部荒野，萨丁一家储备着这种谷物供他们的鸡群食用。出示这种特制的饲料并表现出热情的鼓励，鸟儿就会急切地啄食。作为交换，这只鸡会产下一枚温暖的、新鲜的蛋，你可以将其孵化为忠诚的伙伴。"}},faq={{q="鸡是如何提供任务的？",a="如果你在鸡面前反复使用“小鸡”或“拍翅膀”表情，它最终会停下来好奇地打量你。此时，这只鸡就会产生反应，并通过在泥土中抓出名字来表达它的饥饿。",al={"小鸡任务起始","如何与鸡对话","咯咯哒任务解锁"}},{q="鸡在泥土中拼出了什么？",a="这只鸡在泥土中抓出了字母“S-A-L-D-E-A-N”（萨丁），然后便走开了。这指引着旅行者前往西部荒野中部的萨丁农场，找到农夫萨丁和他妻子，他们出售这种鸟儿渴望的特制谷物。",al={"鸡抓出的字","鸡写了什么","萨丁的鸡"}},{q="在哪里可以买到特殊的鸡饲料？",a="农夫萨丁在西部荒野的萨丁农场储备有特殊的鸡饲料。",al={"鸡饲料商人","哪里买鸡饲料","萨丁的饲料"}},{q="这可以对世界上任何一只鸡使用吗？",a="任何在定居地区发现的标准农场鸡都能对该动作做出反应，尽管它们最常出现在人类农场周围，例如西部荒野的那些农场。",al={"哪些鸡有效","任何鸡都可以吗","哪里找鸡"}},{q="拿到饲料后如何完成任务？",a="在携带特殊的鸡饲料时找到一只鸡，并对着它热情地欢呼。鸡会期待地看着你，接受饲料，并在身下产下一枚蛋供你拾取。",al={"如何交咯咯哒任务","喂鸡得蛋","咯咯哒任务上交"}},{q="完成任务能得到什么？",a="被喂饱的鸡会在脚下产下一枚鸡蛋。拾取这枚蛋会获得一个鸡蛋物品，让你能召唤属于自己的忠诚的西部荒野小鸡，跟随你踏上冒险旅程。",al={"咯咯哒任务奖励","鸡蛋宠物","西部荒野小鸡奖励"}}},fp="6,150,19.288.0,17.230.0,33.145.0,44.176.0,42.74.0,46.140.0,53.124.0,40.165.0"}
P.entries["quest:387"] = {n="镇压暴动",s="在暴风城鹅卵石街道的深处，高度戒备的监狱陷入了一片混乱。在一群被监禁的迪菲亚潜行者成员的策划下，囚犯们发起了一场有预谋的越狱。典狱官塞尔沃特急需招募冒险者，在首都得知监狱受损的真相之前，镇压暴乱的囚犯并恢复秩序。",h="在暴风城鹅卵石街道的深处，高度戒备的监狱陷入了一片混乱。在一群被监禁的迪菲亚潜行者成员的策划下，囚犯们发起了一场有预谋的越狱。典狱官塞尔沃特急需招募冒险者，在首都得知监狱受损的真相之前，镇压暴乱的囚犯并恢复秩序。",kw={"罪犯","迪菲亚","暴乱分子","镇压暴乱","监狱","暴风城","暴乱","典狱官塞尔沃特"},ang={["class:Paladin"]="在城市深处恢复秩序，考验着正义裁决与对反叛公民绝望的致命报复之间的界限。",["faction:Alliance"]="监狱内部的叛乱就在暴风城的街道之下，这代表了联盟主王国核心地带的一次灾难性安全疏漏。",["race:Human"]="许多在牢房里战斗的迪菲亚囚犯都是曾经的王国石匠和平民，他们被逼走上叛乱之路，这使得这场血腥的暴乱对暴风城人民而言是一场痛苦的内部冲突。"},sec={{t="失去控制的监狱",b="监狱旨在关押那些威胁暴风王国的最危险的罪犯、阴谋家和不法之徒。然而，一群被监禁的迪菲亚潜行者策划了一场突如其来的暴力暴乱，从守卫手中直接夺取了牢房区的控制权。整座监狱已被完全攻陷，走廊里挤满了武装暴徒，正常的应对程序已经完全瘫痪。监狱当局没有组织严密的收复行动，而是指望到访的勇士一路杀过暴乱区域。"},{t="绝望与掩盖",b="典狱官塞尔沃特下令一旦发现迪菲亚囚犯格杀勿论，这既反映了他绝望的心境，也是为了自保。典狱官怀疑这场精心策划的叛乱背后有鬼，他担心一旦更广泛的贵族阶层或暴风城贵族议会发现监狱失控，他的职位就不保了。通过下令对叛乱者处以极刑，塞尔沃特希望能够以武力摧毁囚犯的意志，在消息传出运河闸门之前平息叛乱。"}},faq={{q="为什么典狱官塞尔沃特请求冒险者去平息暴乱？",a="监狱守卫已经失去了对内部牢房的控制，暴乱的迪菲亚囚犯占据了上风。典狱官塞尔沃特担心一旦灾难的全部规模传到暴风城领导层的耳中，他会丢掉职位，因此他招募了能干的雇佣兵来消灭暴乱头目并迅速重新建立控制。",al={"为什么要雇佣冒险者","塞尔沃特的动机","为什么要做监狱任务"}},{q="谁在监狱里发动暴乱？",a="暴乱的核心成员是那些被俘的迪菲亚潜行者成员——包括普通囚犯、顽固罪犯和有组织的暴乱分子——他们是在该组织在西部荒野和艾尔文森林发动秘密战争时被关押起来的。",al={"谁在暴乱","监狱里的迪菲亚囚犯","是谁越狱了"}},{q="塞尔沃特认为这场暴乱是内部勾结吗？",a="是的。典狱官塞尔沃特公开怀疑其中有鬼，他认为如此突然且彻底的暴乱，如果没有外部干预或城内安全防卫的疏忽，不可能纯属巧合。",al={"是否是叛国罪","监狱里的阴谋","监狱内部勾结"}},{q="这场暴乱发生在哪里？",a="暴乱被勉强控制在监狱内部，那是一座位于暴风城Mage Quarter运河旁的地底最高安全等级地下城。",al={"监狱在哪里","监狱入口","监狱位置"}},{q="这些迪菲亚暴乱分子被杀后会怎样？",a="虽然清除暴乱分子削弱了叛乱者的势力，但当你返回时，典狱官塞尔沃特承认危机远比一场简单的冲突要严重得多，需要对关押在更深处的那些重要头目采取进一步的打击。",al={"监狱会变安全吗","镇压暴乱之后"}},{q="对所有越狱的罪犯可以使用致命武力吗？",a="典狱官塞尔沃特宣布，在接管期间积极叛乱的法定惩罚是立即处死，他命令勇士就地处决囚犯、罪犯和暴乱分子，以迫使幸存的囚犯屈服。",al={"为什么要杀他们","叛乱的惩罚","杀囚犯合法吗"}}},fp="18,226,28.371.0,24.411.0,64.277.0,44.233.0,50.185.0,36.136.0,51.214.0,56.223.0"}
P.entries["quest:388"] = {n="鲜血的颜色",s="“血的颜色”是居住在暴风城的悲伤祖母尼科瓦·拉斯克发布的个人任务。由于她年幼的孙子在城内的监狱中被杀害，她悲愤交加，雇佣冒险者进入监狱，夺回迪菲亚潜行者标志性的红色头巾作为报复。",h="“血的颜色”是居住在暴风城的悲伤祖母尼科瓦·拉斯克发布的个人任务。由于她年幼的孙子在城内的监狱中被杀害，她悲愤交加，雇佣冒险者进入监狱，夺回迪菲亚潜行者标志性的红色头巾作为报复。",kw={"血的颜色","迪菲亚潜行者","麦克·拉斯克","尼科瓦·拉斯克","红色毛纺面罩","监狱","暴风城"},ang={["faction:Alliance"]="麦克·拉斯克的死揭示了暴风城本土防御的压力，显示了将经验丰富的士兵调离首都所带来的惨重代价。",["race:Human"]="暴风城的人类公民承受着迪菲亚暴力带来的冲击，无论是在周围的乡村农田，还是在城墙之内。"},sec={{t="监狱高墙上的男孩",b="当暴风城的正规军队被派往遥远的前线时，当地的防御只能依靠志愿新兵和城市的年轻人。尼科瓦·拉斯克的孙子麦克在监狱担任守卫时年仅十四岁。这名年轻的守卫负责看守穷凶极恶的罪犯和叛乱的迪菲亚潜行者，被迫置身于一个远超他经验范畴的极其危险的环境中。"},{t="反抗的象征",b="在铁窗后，被俘的迪菲亚囚犯开始撕碎他们配发的羊毛监狱毯，将碎布拼凑成简易的红色头巾。这些粗糙的服饰成了他们帮派的识别色，标志着即使身陷囹圄，他们依然效忠于迪菲亚潜行者。当年轻的麦克斥责囚犯并试图维持纪律时，囚犯们从背后刺伤了这个男孩，让他倒在石地上身亡。"},{t="悲伤与复仇",b="麦克的无谓死亡让尼科瓦深受打击，她不再寻求官方的帮助，而是寻求冷酷的复仇。她派遣勇敢的冒险者深入监狱，消灭骚乱的囚犯，并带回十条他们珍视的红色头巾——这些头巾被染成了她孙子流下的鲜血的颜色。呈上这些血色的战利品，给这个破碎的家庭带来了一种严峻的慰藉。"}},faq={{q="尼科瓦·拉斯克是谁？",a="尼科瓦·拉斯克是暴风城的一位年长居民，她十四岁的孙子麦克最近在监狱担任守卫时被杀害。",al={"尼科瓦·拉斯克","任务发布者","谁发布血的颜色任务"}},{q="为什么一个十四岁的孩子会去看守危险的囚犯？",a="由于暴风城的大部分正规军都被派往了前线，城市不得不依靠缺乏经验的当地人和年轻人来填补防御岗位，其中包括看守监狱中的囚犯。",al={"为什么麦克是守卫","麦克的年龄","儿童守卫"}},{q="为什么迪菲亚囚犯要戴红色羊毛头巾？",a="红色头巾是迪菲亚潜行者的统一象征。在被关押在监狱期间，囚犯们撕碎了他们的羊毛监狱毯来制作红色头巾，以保持他们的犯罪团结。",al={"为什么戴红色头巾","红色头巾背景故事","迪菲亚红色头巾"}},{q="麦克·拉斯克是怎么死的？",a="麦克发现囚犯们撕碎羊毛毯制作迪菲亚帮派头巾并斥责了他们。作为对他斥责的回应，囚犯们从背后刺死了这名十四岁的守卫。",al={"麦克是怎么死的","谁杀了麦克","麦克发生了什么"}},{q="尼科瓦怎么处理这些头巾？",a="她将它们作为复仇的证据保存起来。凝视着这些破碎的羊毛信物，她在哀悼孙子无谓逝去生命的同时，因为知道杀害他的人受到了审判而感到了一丝平静。",al={"头巾怎么处理","尼科瓦与头巾"}},{q="这个任务在哪里进行？",a="这个任务会将你送往监狱，那是位于暴风城运河区的高安全级别监狱，此时迪菲亚囚犯们正在发动公开暴动。",al={"哪里获取头巾","血的颜色任务地点"}}},fp="18,208,24.343.0,18.295.0,19.308.0,21.139.0,57.155.0,51.126.0,23.152.0,38.181.0,33.127.0"}
P.entries["quest:389"] = {n="巴基尔·斯瑞德",s="在从死亡矿井找到一封未寄出的信之后，城市建筑师巴隆斯·阿历克斯顿指引调查者去寻找巴基尔·斯瑞德，也就是迪菲亚潜行者首领的左膀右臂。斯瑞德目前被关押在暴风城街道下戒备森严的监狱中，他掌握着关于该兄弟会余孽阴谋的关键情报。",h="在从死亡矿井找到一封未寄出的信之后，城市建筑师巴隆斯·阿历克斯顿指引调查者去寻找巴基尔·斯瑞德，也就是迪菲亚潜行者首领的左膀右臂。斯瑞德目前被关押在暴风城街道下戒备森严的监狱中，他掌握着关于该兄弟会余孽阴谋的关键情报。",kw={"巴隆斯·阿历克斯顿","巴基尔·斯瑞德","迪菲亚","艾德温·范克里夫","石匠工会","暴风城","监狱","未寄出的信","典狱官塞尔沃特"},ang={["class:Rogue"]="斯瑞德代表了迪菲亚中那些强硬、有组织的地下派系，他们用建筑锤换成了尖刀和街头暴力。",["faction:Alliance"]="即使艾德温·范克里夫已被击杀，迪菲亚的威胁依然通过监狱那未加固的牢房，直接渗透到了首都的心脏地带。",["race:Human"]="石匠工会的叛乱凸显了暴风城的统治贵族与那些亲手建造这座城市的平民之间深重且难以愈合的政治裂痕。"},sec={{t="苦涩的历史",b="当巴隆斯·阿历克斯顿看到从死亡矿井找到的证据时，他承认了自己与艾德温·范克里夫共有的那段历史。他们两人都曾是石匠工会的核心工匠，负责在第一次和第二次战争的废墟上重建暴风城。在完成了王国宏伟的白色城墙和塔楼之后，贵族们却拒绝向石匠们支付承诺的报酬。虽然一些高层成员被许以优渥的官职来安抚他们，但范克里夫拒绝抛弃普通的劳工，他领导了一场暴力骚乱，离开了城市，并创立了迪菲亚潜行者。"},{t="转投监狱",b="为了破译范克里夫的全部计划，并揭开该兄弟会仍在针对暴风城策划的阴谋，阿历克斯顿指引调查者去寻找巴基尔·斯瑞德。斯瑞德曾是石匠起义期间范克里夫的首席副手，后来被捕并被关押在Mage Quarter运河下的城市监狱里。然而，想要接近他困难重重：当到达监狱大门时，典狱官塞尔沃特透露，囚犯们已经策划了一场全面的叛乱，将监狱变成了一个现役战区。"}},faq={{q="谁是巴基尔·斯瑞德？",a="巴基尔·斯瑞德曾在石匠工会和后来的早期迪菲亚起义中担任艾德温·范克里夫的主要副手。在被暴风城当局抓获后，他被关押在监狱的深处。",al={"巴基尔·斯瑞德背景故事","斯瑞德是谁","斯瑞德过往"}},{q="为什么巴隆斯·阿历克斯顿要派你去和斯瑞德交谈？",a="在查验了从死亡矿井找到的那封未寄出的信后，阿历克斯顿意识到，对暴风城的威胁不仅仅局限于死亡矿井。他相信作为范克里夫曾经的左膀右臂，斯瑞德比任何人都更了解该兄弟会的内幕运作和剩余的阴谋。",al={"为什么要找斯瑞德","巴隆斯·阿历克斯顿的动机","为什么要前往监狱"}},{q="石匠工会为何遭到背叛？",a="在石匠们完成了第二次战争后暴风城的大规模重建工作后，贵族议会拒绝履行他们的财政协议，导致劳工们拿不到工钱，陷入赤贫。范克里夫拒绝了让他闭嘴的贿赂，转而领导了一场骚乱，从城门外撤出。",al={"石匠为何没拿到工钱","迪菲亚的动机","石匠骚乱原因"}},{q="监狱位于何处？",a="监狱的入口位于暴风城Mage Quarter东北部的运河沿岸。典狱官塞尔沃特正站在入口内侧，试图抵挡越狱的囚犯。",al={"监狱位置","监狱入口","如何找到典狱官塞尔沃特"}},{q="当你到达时，监狱里发生了什么？",a="监狱已经陷入彻底的混乱。巴基尔·斯瑞德和他的同伙囚犯们已经制服了守卫，打开了牢房，并控制了下层大厅，使得典狱官塞尔沃特难以阻止骚乱蔓延到暴风城的街道上。",al={"塞尔沃特为什么愤怒","监狱危机","监狱发生了什么"}},{q="巴隆斯·阿历克斯顿是如何避免加入迪菲亚的？",a="与拒绝妥协并选择武装起义的范克里夫不同，阿历克斯顿是那些接受了王国政府雇佣的高级工匠之一，最终晋升为城市建筑师。",al={"巴隆斯是迪菲亚吗","巴隆斯·阿历克斯顿石匠"}}},fp="12,200,16.429.0,22.357.1,20.174.0,54.254.0,39.242.0,30.162.0,54.220.0,48.168.0"}
P.entries["quest:39"] = {n="托马斯的报告",s="“交付托马斯的报告”将来自艾尔文森林东部的严峻情报带回了闪金镇的驻军指挥部。卫兵托马斯委派一位冒险者通知治安官杜汉，告知他两名卫兵的牺牲以及当地鱼人部落难以遏制的扩张。这份报告强调了暴风城的军事力量在其腹地竟已薄弱到了何种令人堪忧的地步。",h="“交付托马斯的报告”将来自艾尔文森林东部的严峻情报带回了闪金镇的驻军指挥部。卫兵托马斯委派一位冒险者通知治安官杜汉，告知他两名卫兵的牺牲以及当地鱼人部落难以遏制的扩张。这份报告强调了暴风城的军事力量在其腹地竟已薄弱到了何...",kw={"艾尔文森林","闪金镇","卫兵托马斯","马拉克","治安官杜汉","鱼人","报告","罗尔夫"},ang={["class:Warrior"]="对于效忠王国的勇士们来说，马拉克和罗尔夫的牺牲凸显了边境驻军在面对无情的非人类敌人时的残酷现实。",["faction:Alliance"]="递交托马斯的报告揭示了联盟主要王国核心的脆弱性，表明即使是首都外围的道路也正逐渐失去驻军的控制。",["race:Human"]="人类保卫者们直接感受到了这些损失带来的痛苦，眼睁睁地看着家园的安宁因人力不足和敌对入侵的加剧而遭受蚕食。"},sec={{t="来自东方的噩耗",b="卫兵托马斯驻扎在通往艾尔文森林东部荒野的桥梁附近，此时已濒临崩溃。他负责监视河流交通和边境动乱，但他的小队在面对凶猛的鱼人部落时损失惨重，卫兵马拉克和罗尔夫不幸殉职。由于剩余兵力寥寥无几，无法遏制这种水生生物的威胁，托马斯被迫派出一名急使沿着道路赶回闪金镇。"},{t="兵力匮乏的驻军",b="当治安官杜汉在闪金镇收到这份报告时，消息证实了他最担心的战略恐慌。闪金镇已经在艰难地维持基础巡逻，同时还要应付豺狼人侵扰、迪菲亚强盗的威胁，以及暴风城完全没有援军支援的情况。两名经验丰富的卫兵的损失，以及鱼人可能很快威胁到闪金镇本身的现实，说明了该地区的防御力量已经濒临全面崩溃。"}},faq={{q="马拉克和罗尔夫是谁？",a="马拉克和罗尔夫是驻扎在艾尔文森林东部、隶属于卫兵托马斯麾下的暴风城卫兵。在河流和湖泊附近巡逻时，他们被侵扰水道的凶猛鱼人部落包围并杀害。",al={"马拉克和罗尔夫","谁牺牲了","阵亡卫兵"}},{q="为什么卫兵托马斯要找冒险者来递交报告？",a="卫兵托马斯已经没有多余的兵力可用了。他的哨所人力极度短缺，如果擅离职守或者派走仅存的少数哨兵，那么东部的桥梁将完全无人防守。",al={"卫兵托马斯为何需要帮助","为什么派信使","托马斯为何不能派卫兵"}},{q="鱼人对闪金镇构成了什么威胁？",a="正如治安官杜汉在读到这份快报时所指出的，东部河流沿岸失控的鱼人势力正在迅速向西扩张。由于没有足够的卫兵来把守外围，杜汉担心战斗在一周内就会蔓延到闪金镇的郊区。",al={"鱼人威胁","鱼人会攻击闪金镇吗","鱼人有多严重"}},{q="为什么暴风城不向艾尔文森林派遣援军？",a="暴风城的军事资源在多条战线上都紧缺到了极点，加之国王瓦里安·乌瑞恩失踪后首都陷入政治僵局，情况变得更加复杂。偏远定居点和边境桥梁在很大程度上只能依靠当地民兵和受雇的冒险者来维持生存。",al={"为何没有暴风城军队","军队在哪里","为何防御薄弱"}},{q="治安官杜汉读完报告后会发生什么？",a="治安官杜汉意识到他的驻军缺乏直接遏制鱼人攻势的人手，必须寻找其他方法来装备并支持那些愿意守卫防线的人，将注意力转向为区域防御争取补给和护甲。",al={"下一个任务","杜汉做了什么","报告后的任务线"}},{q="卫兵托马斯驻扎在哪里？",a="卫兵托马斯驻守在艾尔文森林的东侧，负责看守那些分隔森林中心地带与靠近赤脊山的荒野边界的河流桥梁。",al={"卫兵托马斯位置","托马斯在哪里","托马斯位置"}}},fp="22,188,25.271.0,33.363.0,25.173.0,63.150.0,45.182.0,57.252.0,51.158.0,32.168.0"}
P.entries["quest:3901"] = {n="断骨骷髅",s="“扫荡碎骨骷髅”是暗影牧师萨维斯指派给丧钟镇中刚觉醒的被遗忘者的早期试炼。这些新生的亡灵需要摧毁十二具碎骨骷髅，以此证明他们对抗天灾军团的韧性，并展现出捍卫自己刚获得的自由所需的意志力。",h="“扫荡碎骨骷髅”是暗影牧师萨维斯指派给丧钟镇中刚觉醒的被遗忘者的早期试炼。这些新生的亡灵需要摧毁十二具碎骨骷髅，以此证明他们对抗天灾军团的韧性，并展现出捍卫自己刚获得的自由所需的意志力。",kw={"丧钟镇","被遗忘者","碎骨骷髅","萨维斯","天灾军团","骷髅","提瑞斯法","亡灵"},ang={["class:Priest"]="直接为暗影牧师萨维斯工作，让刚复生的牧师们能更早地领略到定义了被遗忘者精神道路的那种残酷实用主义。",["faction:Horde"]="丧钟镇的试炼将新的被遗忘者士兵磨练成有能力的战士，让他们准备好捍卫自己羽翼未丰的阵营，并巩固提瑞斯法林地的安全。",["race:Undead"]="对抗碎骨骷髅是一个严酷的提醒，告诫任何意志动摇的被遗忘者未来会遭遇什么，并将你来之不易的自主权与天灾军团的无脑奴役形成了鲜明对比。"},sec={{t="意志的考验",b="在清理了在丧钟镇徘徊的无脑僵尸后，新生的被遗忘者会立即面临更严酷的试炼。暗影牧师萨维斯指示新兵去对抗在定居点外围游荡的碎骨骷髅。这些活动骸骨没有任何理智或自我控制能力，但比起附近的腐朽尸体，它们的攻击更猛烈，战斗也更凶残。在它们的咔嗒作响的伏击中幸存下来，证明了新兵在受到直接压力时不会动摇。"},{t="捍卫刚获得的自由",b="对于萨维斯和丧钟镇的领导层来说，清理这些骷髅有着双重目的。它既能保护这个脆弱的避难所不被巫妖王残存的势力所淹没，又能淘汰掉那些无法胜任的新兵。那些失败或犹豫不决的人可能会面临与游荡在森林中的无脑行尸同样的命运。击败碎骨骷髅向萨维斯证明了新兵具备在这个憎恨他们存在的世界上生存所需的勇气。"}},faq={{q="什么是碎骨骷髅？",a="碎骨骷髅是仍然受巫妖王奴役的无脑亡灵。它们被剥去了血肉和认知意志，在丧钟镇边缘游荡，攻击任何经过它们身边的生物。",al={"碎骨骷髅","什么是碎骨骷髅","这些骷髅是谁"}},{q="为什么暗影牧师萨维斯要消灭这些骷髅？",a="萨维斯想要在压力下测试刚觉醒的被遗忘者的战斗能力和意志力。清理这些具有攻击性的骷髅也能保护丧钟镇免受天灾军团的侵袭。",al={"为什么要杀死骷髅","萨维斯的目的","扫荡碎骨骷髅的原因"}},{q="哪里可以找到碎骨骷髅？",a="它们游荡在丧钟镇山谷的北部和东北部边界，就在无脑僵尸出没的村庄之外。",al={"碎骨骷髅的位置","在哪里可以找到碎骨骷髅","丧钟镇的骷髅刷新点"}},{q="完成这个任务后会发生什么？",a="萨维斯认为你的初步训练已经完成，并宣告你已经证明自己配得上这份自由。随后他会指引你去找丧钟镇的其他领导者，以协助被遗忘者更广泛的行动。",al={"扫荡碎骨骷髅后的下一个任务","完成后要做什么","萨维斯的下一步指引"}},{q="为什么一些亡灵可以获得自由，而这些骷髅却依然没有意识？",a="当第三次战争后巫妖王的心灵控制减弱时，一小部分亡灵挣脱了束缚并找回了自我意识，组成了被遗忘者。而像碎骨骷髅这样的构装体和简单的活动骸骨没有保留任何人格或意志，依然完全受制于天灾军团。",al={"为什么骷髅没有意识","被遗忘者与天灾军团的自由意志","被遗忘者是如何觉醒的"}},{q="谁是暗影牧师萨维斯？",a="暗影牧师萨维斯是丧钟镇教堂中的被遗忘者监工。他负责评估新复生的亡灵，引导他们完成觉醒，并确保他们有足够强大的力量作为自由的存在活下去。",al={"谁是萨维斯","萨维斯背景故事","暗影牧师萨维斯的职责"}}},fp="24,194,17.424.0,27.336.0,30.180.0,59.183.0,41.144.0,41.188.0,63.269.0,28.204.0"}
P.entries["quest:3902"] = {n="捡破烂",s="“搜刮丧钟镇”是亡灵卫兵萨尔坦指派给刚刚觉醒的被遗忘者的一项早期后勤任务。当新复生的亡灵从土里爬出来时，被遗忘者必须在整个枯萎的定居点中搜刮废弃的箱子和板条箱，以为新招募的人员提供装备。这展现了希尔瓦娜斯的子民初创时所面临的极度匮乏，他们必须通过回收废弃物品来维持生存。",h="“搜刮丧钟镇”是亡灵卫兵萨尔坦指派给刚刚觉醒的被遗忘者的一项早期后勤任务。当新复生的亡灵从土里爬出来时，被遗忘者必须在整个枯萎的定居点中搜刮废弃的箱子和板条箱，以为新招募的人员提供装备。这展现了希尔瓦娜斯的子民初创时所面...",kw={"亡灵卫兵萨尔坦","丧钟镇","被遗忘者的补给","破烂装备","搜刮丧钟镇","提瑞斯法林地","亡灵初始任务"},ang={["faction:Horde"]="虽然被遗忘者与海外遥远的部落结盟，但像丧钟镇这样的前哨站必须通过绝望的本地搜刮来维持日常生存，而非依赖外援。",["race:Undead"]="这项任务展示了你们刚刚拥抱的亡灵生涯的严峻准则：在艾泽拉斯，没有人会给予怜悯或施舍，被遗忘者必须从尘土中搜刮出自己的未来。"},sec={{t="务实的复生",b="新复生的被遗忘者苏醒后，面临的是腐朽与匮乏的严酷现实。与拥有繁荣补给线和军械库的成熟国家不同，丧钟镇的自由亡灵几乎一无所有。亡灵卫兵萨尔坦的直率要求反映了从墓地泥土中建立一支军队所必需的冷酷务实：每一块可用的布料、皮革和铁器都必须被找回，以用来为那些刚爬出墓穴的亡灵穿戴盔甲。"},{t="在提瑞斯法勉强度日",b="丧钟镇布满了昔日人类居民的遗迹，以及王国沦陷于天灾军团时废弃的物资。亡灵卫兵们没有任由这些可用物资在镇上的板条箱里腐烂，而是让新生亡灵作为拾荒者投入服务。正如萨尔坦所言，被遗忘者不指望活着的生物给予任何施舍，他们必须完全依靠自己的勤劳才能站稳脚跟。"}},faq={{q="为什么亡灵卫兵萨尔坦需要破烂装备？",a="亡灵卫兵萨尔坦正在收集装备，以武装在附近墓地中不断复苏的新生被遗忘者。如果没有搜刮来的衣服、靴子和工具，新兵们只能赤手空拳、毫无防备地在枯萎的荒野上游荡。",al={"为什么要搜刮物资","萨尔坦的目标","为什么要寻找箱子"}},{q="破烂装备在哪里可以找到？",a="这些物品散落在丧钟镇各处的箱子和板条箱堆里，通常位于废弃建筑物附近或定居点的隐蔽角落。",al={"箱子在哪里","破烂装备的地点","丧钟镇的箱子"}},{q="亡灵卫兵萨尔坦是谁？",a="萨尔坦是一名驻扎在丧钟镇的务实亡灵卫兵，负责评估并让新复生的亡灵投入工作，通过严厉的纪律来维护秩序和生存。",al={"萨尔坦是谁","亡灵卫兵萨尔坦背景故事"}},{q="为什么被遗忘者在这里没有标准的军事补给？",a="被遗忘者是一个年轻且饱受困扰的派系，他们必须在充满敌意的活人敌人和受操纵的天灾军团中开辟生存空间。在丧钟镇，资源极度紧张，迫使他们必须回收并重新利用废墟中留下的任何东西。",al={"为什么没有装备","被遗忘者补给短缺","丧钟镇装备"}},{q="完成这项任务后会发生什么？",a="萨尔坦会用公共储备库中的一件回收护甲来奖励新兵，这巩固了新兵从一名未经考验的尸体到黑暗女王麾下合格士兵的转变。",al={"后续任务","搜刮奖励"}},{q="为什么现在有这么多新亡灵在丧钟镇复生？",a="随着巫妖王对其仆从的控制力减弱，一些洛丹伦的亡者得以恢复神智，从坟墓中苏醒，他们感到困惑并需要立即的引导。",al={"为什么会复生","丧钟镇的新兵","为什么是新生亡灵"}}},fp="21,250,24.288.0,23.334.0,49.216.0,36.128.0,26.163.0,60.199.0,40.179.0,58.180.0"}
P.entries["quest:3903"] = {n="米莉·奥斯沃斯",s="“米莉·奥斯沃斯”是北郡修道院的维里副队长委托给有前途的新兵的一项简短任务。它引导冒险者穿过修道院区域，去帮助当地居民米莉，她的马车和生计正岌岌可危。这项任务标志着冒险者从清理修道院周围区域转变为帮助艾尔文森林陷入困境的平民。",h="“米莉·奥斯沃斯”是北郡修道院的维里副队长委托给有前途的新兵的一项简短任务。它引导冒险者穿过修道院区域，去帮助当地居民米莉，她的马车和生计正岌岌可危。这项任务标志着冒险者从清理修道院周围区域转变为帮助艾尔文森林陷入困境的...",kw={"维里副队长","艾尔文森林","收成","米莉·奥斯沃斯","北郡修道院","马厩","马车"},ang={["faction:Alliance"]="这项任务说明了北郡当地联盟部队所面临的压力，卫兵们必须依靠过往的冒险者来保护当地平民免受新兴威胁的侵害。",["race:Human"]="对于在北郡开始旅程的年轻人类来说，代替维里行事展现了维持艾尔文森林稳定所必需的社区精神。"},sec={{t="可靠的帮手",b="在证明了自己有能力对抗侵扰北郡山谷的迪菲亚盗贼后，新兵引起了维里副队长的注意。意识到冒险者是有能力的得力助手后，维里将他们引荐给他的朋友米莉·奥斯沃斯。比起官方的驻军事务，这项任务更多是作为私人的忙，以帮助一位被山谷中日益动荡的局势所困扰的平民。"},{t="马厩旁的麻烦",b="米莉·奥斯沃斯在北郡修道院的另一侧，靠近马厩的地方等候着她的马车。虽然维里副队长必须坚守岗位保卫修道院，但米莉的麻烦需要有人直接前往山谷解决，而兵力吃紧的卫戍部队根本抽不出人手。"}},faq={{q="是谁让你来和米莉·奥斯沃斯谈话的？",a="维里副队长，他驻守在北郡修道院正门外。在你处理完迪菲亚强盗证明了自己的可靠性后，他会交给你这个任务。",al={"谁发布了米莉·奥斯沃斯任务","米莉·奥斯沃斯任务发布者","去哪里接米莉·奥斯沃斯任务"}},{q="在哪里可以找到米莉·奥斯沃斯？",a="米莉·奥斯沃斯驻守在北郡修道院另一侧的马车旁，靠近马厩，距离东南方的葡萄园不远。",al={"米莉·奥斯沃斯位置","米莉在哪里","米莉·奥斯沃斯在哪里"}},{q="为什么维里副队长不能亲自帮助米莉？",a="维里的卫兵职责使他必须坚守在北郡修道院。由于山谷受到强盗和害虫的侵扰，当地驻军没有多余的人手来处理平民的私事。",al={"为什么维里不帮忙","维里的职责","为什么要帮米莉"}},{q="完成这个任务需要什么前提条件？",a="你必须先为维里副队长完成“盗贼兄弟会”任务，他才会认为你足够可靠，可以去协助米莉。",al={"米莉·奥斯沃斯任务需求","盗贼兄弟会的后续","如何解锁米莉·奥斯沃斯任务"}},{q="米莉需要什么帮助？",a="米莉在当地的动乱中难以打理她的农作物和马车，这直接导致了需要从周围的山谷中保卫她收成的任务。",al={"米莉想要什么","米莉的麻烦","米莉的收成问题"}},{q="米莉·奥斯沃斯对维里副队长来说是谁？",a="维里称米莉为需要帮助的朋友，是他在受限于岗位的同时依然挂念的一位北郡社区成员。",al={"维里和米莉","米莉和维里有关系吗","维里怎么认识米莉的"}}},fp="13,181,26.237.0,22.223.0,42.85.0,33.118.0,43.154.0,45.97.0,31.125.0,38.112.0"}
P.entries["quest:3904"] = {n="米莉的葡萄",s="米莉的葡萄是一项简单的差事，源于北郡日益严重的强盗危机。在迪菲亚潜行者迫使当地农民米莉·奥斯沃斯放弃她在农场中收获的葡萄后，冒险者必须勇敢地进入这些被占领的田地，在她的生计被偷走或踩踏之前将其找回。",h="米莉的葡萄是一项简单的差事，源于北郡日益严重的强盗危机。在迪菲亚潜行者迫使当地农民米莉·奥斯沃斯放弃她在农场中收获的葡萄后，冒险者必须勇敢地进入这些被占领的田地，在她的生计被偷走或踩踏之前将其找回。",kw={"板条箱","迪菲亚","艾尔文森林","葡萄","米莉·奥斯沃斯","米莉的葡萄","北郡修道院","北郡农场"},ang={["faction:Alliance"]="找回米莉的庄稼让年轻的联盟新兵们第一次直观地了解到了距离暴风城仅几英里之遥的迪菲亚问题。",["race:Human"]="对于在北郡开启旅程的人类而言，保护像米莉这样的小农户代表了捍卫艾尔文森林劳动人民的核心职责。"},sec={{t="留下的庄稼",b="当米莉·奥斯沃斯在北郡山谷的东南田地里收集葡萄时，迪菲亚强盗蜂拥而至，她被迫逃命。在惊慌失措中，她留下了装在桶和板条箱里的收获，散落在被占领的田垄间。由于当地守卫人手不足，她担心即使守卫最终赶走了入侵者，沉重的战靴和混乱的战斗也会把强盗还没来得及搬走的果实践踏殆尽。"},{t="压力之下的北郡",b="强盗公然占据正在耕作的农场，凸显了北郡的安全状况已变得多么脆弱。由于暴风城的注意力集中在别处，且山谷中缺乏足够的守卫，像米莉这样的普通公民只能依靠来访的新兵和流浪者来保护他们的财产，并确保供应修道院的食物和葡萄酒的安全。"}},faq={{q="米莉·奥斯沃斯是谁？",a="米莉·奥斯沃斯是一位在北郡农场工作的当地农民。她照料并收获山谷的葡萄，这对北郡的酿酒业至关重要，但她却被到来的迪菲亚潜行者赶出了田地。",al={"米莉·奥斯沃斯","米莉是谁","葡萄女士"}},{q="为什么北郡的守卫不能取回这些收获？",a="北郡山谷的守卫人手不足，忙于遏制蔓延的强盗威胁和狗头人侵扰。米莉还担心笨拙的军事清剿行动会直接把她娇嫩的葡萄踩进泥里。",al={"为什么守卫不帮忙","北郡守卫","懒惰的守卫"}},{q="迪菲亚在农场里做什么？",a="迪菲亚潜行者潜入北郡山谷，旨在破坏该地区的生产，骚扰当地居民，并在暴风城守卫的眼皮底下掠夺资源。",al={"为什么迪菲亚在农场","迪菲亚葡萄","北郡的迪菲亚"}},{q="板条箱在哪里？",a="收获用的桶和板条箱散落在北郡农场的地面上，位于北郡修道院的东南方，周围是巡逻的敌对迪菲亚强盗。",al={"板条箱位置","去哪里找葡萄","收获在哪里"}},{q="米莉拿回葡萄后会发生什么？",a="一旦收获安全了，米莉会委托冒险者将她的葡萄出货单交给北郡修道院内的尼尔斯修士，以便对产量进行核算并加工成葡萄酒。",al={"后续任务","米莉的葡萄之后","接下来做什么"}},{q="为什么葡萄对北郡修道院很重要？",a="北郡山谷出产著名的葡萄酒，并供应修道院的教士社区。米莉的庄稼既维持了当地的贸易，也供应着北郡兄弟会维护的地窖。",al={"北郡葡萄酒","葡萄为什么重要"}}},fp="15,172,18.308.0,25.300.0,21.152.0,53.183.0,43.154.0,29.170.0,46.171.1,45.183.0"}
P.entries["quest:3905"] = {n="葡萄出货单",s="随着米莉·奥斯沃斯的收成从迪菲亚盗贼手中抢回，她写下了一份单据，记录了收回的葡萄产量。将这份账本交给北郡修道院的尼尔斯修士，可以确保修道会补充其著名的葡萄酒储备。这对这个遭受围困的山谷的生计来说，标志着一次虽小但甜蜜的胜利。",h="随着米莉·奥斯沃斯的收成从迪菲亚盗贼手中抢回，她写下了一份单据，记录了收回的葡萄产量。将这份账本交给北郡修道院的尼尔斯修士，可以确保修道会补充其著名的葡萄酒储备。这对这个遭受围困的山谷的生计来说，标志着一次虽小但甜蜜的胜...",kw={"尼尔斯修士","迪菲亚","艾尔文","葡萄出货单","收获","米莉·奥斯沃斯","北郡修道院","葡萄园","葡萄酒"},ang={["class:Priest"]="葡萄酒在北郡修道院既有待客价值也有宗教价值，将实际的农业与修道会的仪式联系在一起。",["faction:Alliance"]="确保北郡的当地粮食储备有助于维持暴风城主要征兵和休整圣地的自给自足。",["race:Human"]="对于开启旅程的年轻人类来说，帮助米莉和尼尔斯修士保护了王国珍视的田园传统之一。"},sec={{t="山谷的佳酿",b="北郡山谷以其肥沃的土壤和宁静的果园在艾尔文闻名遐迩，葡萄园种植的作物既是当地的食粮，也是宗教祭祀所需的贸易品。当强盗和土匪占领了东部的田地时，他们所危害的不仅仅是单纯的水果：他们切断了修道院的葡萄酒和食物供应线。随着收成从被占领的田地中夺回，这份葡萄出货单正式记录了每一蒲式耳收回的果实。"},{t="钟楼小酌",b="尼尔斯修士担任北郡修道院的食品和饮料主管，不过他最出名的是喜欢在钟楼安静的高处品尝北郡的葡萄酒。虽然强盗的威胁就在门外，但收到新鲜的葡萄给了修道会一个向圣光祝酒并稍稍松一口气的理由。"}},faq={{q="什么是葡萄出货单？",a="葡萄出货单是农夫米莉·奥斯沃斯在她的葡萄收成从迪菲亚盗贼手中夺回后写下的库存账本。它记录了抢救回来的产量，以便修道院的军需官可以正式补充地窖储备。",al={"葡萄出货单物品","什么是出货单","米莉的出货单"}},{q="谁是尼尔斯修士？",a="尼尔斯修士是一位居住在北郡修道院的僧侣，负责监督食物和饮料的供应。他大部分时间都在修道院的钟楼里品尝葡萄酒。",al={"尼尔斯修士","谁是尼尔斯","钟楼里的僧侣"}},{q="我在哪里可以找到尼尔斯修士？",a="尼尔斯修士位于北郡修道院内，在俯瞰庭院的钟楼上休息。",al={"尼尔斯位置","尼尔斯修士在哪里","寻找尼尔斯修士"}},{q="为什么北郡的葡萄作物如此重要？",a="北郡生产著名的葡萄酒和新鲜补给，维持着当地教士和驻军的需求。收获中断威胁到了艾尔文各地的日常储备和宗教仪式用品。",al={"为什么葡萄很重要","北郡葡萄酒传说","米莉收成的重要性"}},{q="是谁在威胁米莉的收成？",a="迪菲亚强盗占领了北郡山谷的东部田地，将米莉·奥斯沃斯赶走，并把她装箱的收成藏在葡萄园各处，直到冒险者将他们赶走。",al={"谁偷了葡萄","葡萄盗贼","葡萄园里的强盗"}},{q="把葡萄出货单交给尼尔斯修士后会发生什么？",a="尼尔斯以圣光的名义送上祝福，并为尽管山谷里有强盗的困扰，修道院的地窖仍能保留新鲜葡萄酒而感到高兴。",al={"任务后续","尼尔斯酿酒吗","葡萄出货单之后是什么"}}},fp="14,139,20.218.0,22.252.0,27.150.0,21.125.0,30.84.0,44.179.0,36.166.0,53.168.0"}
P.entries["quest:391"] = {n="监狱暴动",s="“监狱暴动”是一项联盟任务，由位于暴风城监狱大门口的典狱官塞尔沃特发布。为了平息持续不断的叛乱并向城卫兵证明你的忠诚，你受命深入混乱的中心，处决这场暴动的首领：巴基尔·斯瑞德。",h="“监狱暴动”是一项联盟任务，由位于暴风城监狱大门口的典狱官塞尔沃特发布。为了平息持续不断的叛乱并向城卫兵证明你的忠诚，你受命深入混乱的中心，处决这场暴动的首领：巴基尔·斯瑞德。",kw={"巴基尔·斯瑞德","迪菲亚","哈姆霍克","监狱暴动","暴风城","监狱","典狱官塞尔沃特"},ang={["class:Rogue"]="潜入这场暴乱，让我们能够阴郁地审视当迪菲亚潜行者的地下秘密网络失去所有约束时会发生什么。",["faction:Alliance"]="在国王失踪且王国力量捉襟见肘的情况下，Mage Quarter下方发生的全面暴乱威胁到了暴风城的稳定。",["race:Human"]="许多暴徒都是迪菲亚潜行者的特工和心怀不满的石匠，他们在重建争议后背弃了自己的王国。"},sec={{t="血染的石块",b="在Mage Quarter的鹅卵石之下，监狱已经陷入了彻底的无政府状态。罪犯、迪菲亚潜行者以及暴徒们冲破了禁锢，占领了监舍区，将这座设施变成了一个无法进入的战区。典狱官塞尔沃特和他的卫兵们绝望地坚守在入口处，完全无法通过常规手段推进并恢复秩序。"},{t="信任的代价",b="由于怀疑任何打听巴基尔·斯瑞德下落的人，典狱官塞尔沃特提出了一场严酷的忠诚测试。他没有让你进行简单的交谈，而是命令你杀入暴乱的监舍区，在牢房中杀掉斯瑞德，并将这位叛军首领的首级带回来。只有除掉这场叛乱的领头人，外来者才能证明自己并非暗中与叛军勾结。"},{t="断裂的线索",b="杀死巴基尔·斯瑞德给了这场暴动的组织者以决定性的一击，但也让他关于困扰暴风城的阴谋所可能提供的直接答案彻底沉默了。当看到斯瑞德的首级时，惊讶的塞尔沃特承认，这位囚犯的死或许能让监狱重新变得可控，并提供了他自己在暴乱爆发前关于斯瑞德秘密联络人的线索。"}},faq={{q="谁发布了“监狱暴动”任务？",a="该任务由典狱官塞尔沃特发布，他就站在暴风城Mage Quarter的监狱入口通道内。",al={"谁发布监狱暴动","监狱暴动任务发布者","监狱暴动如何开始"}},{q="我需要做什么来完成这个任务？",a="你必须冒险进入监狱地下城，在东部监舍区找到首领巴基尔·斯瑞德，处决他，并将他的首级带回给典狱官塞尔沃特。",al={"监狱暴动任务目标","如何完成监狱暴动"}},{q="巴基尔·斯瑞德在监狱里的什么位置？",a="从入口出发，沿着北边的走廊走到T字路口，然后进入东部的监舍区。巴基尔·斯瑞德就在由食人魔哈姆霍克守卫的一个三室牢房的中央牢房里。",al={"斯瑞德在哪里","巴基尔·斯瑞德位置","如何找到斯瑞德"}},{q="为什么典狱官塞尔沃特想要巴基尔·斯瑞德死？",a="巴基尔·斯瑞德是策划监狱内部暴动的主要首领。塞尔沃特认为，除掉叛乱的领头人是卫兵们夺回监舍区控制权的唯一途径，同时也能确保你不是暗中为叛军效力。",al={"为什么要杀斯瑞德","为什么塞尔沃特要斯瑞德死"}},{q="完成“监狱暴动”后会发生什么？",a="在上交斯瑞德的首级后，典狱官塞尔沃特会引导你进入调查的下一阶段，他在“好奇的访客”任务中派你去调查一名在暴动前曾探访过监狱的神秘人物。",al={"监狱暴动后续任务","监狱暴动之后是什么"}},{q="部落玩家可以获得这个任务吗？",a="不能。监狱暴动是严格的联盟任务，因为该地下城位于首都暴风城的深处。",al={"监狱暴动是联盟专属吗","部落监狱暴动"}}},fp="18,225,18.362.0,18.336.1,16.376.1,39.97.0,43.149.0,50.192.0,49.233.0,49.183.1,36.111.0"}
P.entries["quest:392"] = {n="好奇的访客",s="在平定了监狱的暴乱后，典狱官塞尔沃特透露了一个关于暴乱头目巴基尔·斯瑞德的令人不安的发现。在暴乱发生前的几个月里，斯瑞德一直定期接待一名神秘男子，该男子持有名为Maelik的合法证件。",h="在平定了监狱的暴乱后，典狱官塞尔沃特透露了一个关于暴乱头目巴基尔·斯瑞德的令人不安的发现。在暴乱发生前的几个月里，斯瑞德一直定期接待一名神秘男子，该男子持有名为Maelik的合法证件。",kw={"巴隆斯·阿历克斯顿","巴基尔·斯瑞德","可疑访客","迪菲亚","maelik","监狱","石匠工会","典狱官塞尔沃特"},ang={["class:Rogue"]="这名安静的访客能够凭借合规文件直接走进戒备森严的监狱，这凸显了潜行大师的狡猾与手腕。",["faction:Alliance"]="追踪巴基尔·斯瑞德的神秘联系人对于根除在首都公开活动的迪菲亚同情者至关重要。",["race:Human"]="伪造或获准的进入文书的曝光，揭露了暴风王国政府内部深处的脆弱环节和潜在的腐败。"},sec={{t="协议漏洞",b="巴基尔·斯瑞德在暴风城监狱服刑的最初几年里一直被他的旧同伙抛弃，至少守卫们是这么认为的。但这种情况在监狱暴乱发生前几个月发生了改变，当时一名安静的访客开始每周一到两次地探望斯瑞德。他通过了所有的检查，持有授权文书，并自称Maelik。典狱官塞尔沃特意识到这些探访很可能是随后发生的血腥暴乱的协调过程，于是收集了访客的体貌特征，并派遣冒险者去咨询城市建筑师巴隆斯·阿历克斯顿，以查明这名访客的真实身份。"},{t="与石匠工会的联系",b="巴隆斯·阿历克斯顿在叛乱前曾与艾德温·范克里夫和石匠工会紧密合作，如今他也卷入了这项调查。虽然“Maelik”这个名字听起来很陌生，而且体貌特征也可能符合无数前工匠，但该访客拥有合法的官僚通行证，这一事实表明此事绝非普通罪犯溜过守卫那么简单。这桩谜案揭示了迪菲亚兄弟会的同情者和特工在暴风城的市政设施中渗透得有多深。"}},faq={{q="任务中提到的这位可疑访客是谁？",a="那位访客自称叫Maelik。在监狱暴乱发生前的几个月里，他每周一到两次探望囚犯巴基尔·斯瑞德，并携带着看似合法的身份证明文件。",al={"maelik是谁","斯瑞德的访客","可疑访客的身份"}},{q="为什么典狱官塞尔沃特要派你去见巴隆斯·阿历克斯顿？",a="巴隆斯·阿历克斯顿是暴风城的城市建筑师，曾与艾德温·范克里夫和石匠工会共事。由于迪菲亚兄弟会源自石匠工会，塞尔沃特希望阿历克斯顿能通过过去的工会关系认出这名访客。",al={"为什么找巴隆斯·阿历克斯顿","巴隆斯是谁","向巴隆斯汇报"}},{q="Maelik是如何在不被发现的情况下进入监狱的？",a="Maelik出示了合法的文书，完全通过了监狱的安全检查。守卫没有合法的理由拒绝他进入，这表明要么是官僚机构出现了失误，要么是有腐败官员在王国行政部门内部协助他通行。",al={"访客是如何进入的","maelik的文书","监狱安保失误"}},{q="巴基尔·斯瑞德在监狱暴乱中扮演了什么角色？",a="巴基尔·斯瑞德是关押在监狱中的迪菲亚兄弟会头目之一。他组织并领导了囚犯们的暴力骚乱，这很可能是一项通过他与Maelik的会面所策划的协调行动。",al={"巴基尔·斯瑞德是谁","斯瑞德做了什么"}},{q="巴隆斯·阿历克斯顿读了描述之后发生了什么？",a="阿历克斯顿认不出Maelik这个名字，也不认识塞尔沃特提供的体貌特征。然而，他承认这名访客必然与城内有联系，因此同意深入调查，揭开这名陌生人的真实身份。",al={"巴隆斯认识maelik吗","接下来发生什么"}},{q="为什么这名访客对迪菲亚兄弟会的调查很重要？",a="这些定期的探访证明，监狱暴乱并非突发的非法狂暴，而是一场由能够接触到暴风城高级官方文件的某人所促成的迪菲亚精心策划的阴谋。",al={"迪菲亚阴谋","为什么访客很重要"}}},fp="19,188,20.425.0,23.390.1,50.156.0,53.272.0,55.231.0,52.189.0,56.167.0,64.206.0"}
P.entries["quest:3921"] = {n="维妮·布特巴克",s="地精工程师斯布特瓦夫在摆弄那个找回来的损坏的主动式负载平衡器时把它弄坏了，因此需要在他的地下矿道同事们要求交差之前找个行家来修复它。他派遣冒险者穿过贫瘠之地前往北部，去向莫尔杉壁垒附近的一位聪明技师温妮奇·螺栓桶求助。",h="地精工程师斯布特瓦夫在摆弄那个找回来的损坏的主动式负载平衡器时把它弄坏了，因此需要在他的地下矿道同事们要求交差之前找个行家来修复它。他派遣冒险者穿过贫瘠之地前往北部，去向莫尔杉壁垒附近的一位聪明技师温妮奇·螺栓桶求助。",kw={"损坏的主动式负载平衡器","莫尔杉壁垒","主动式负载平衡器","淤泥沼泽","斯布特瓦夫","贫瘠之地","地下矿道","温妮奇·螺栓桶"},ang={["faction:Horde"]="温妮奇的营地坐落在莫尔杉壁垒的阴影下，这是部落在北贫瘠之地防御灰谷敌对入侵的关键防御咽喉要道。",["profession:Engineering"]="工程师们能够理解该主动式负载平衡器所激发的强烈好奇心；即使斯布特瓦夫和温妮奇都不知道它最初的用途，仅凭其复杂的齿轮结构就值得一探究竟。"},sec={{t="一次精细的事故",b="斯布特瓦夫的野心超过了他的机械技术。在让一位冒险者从淤泥沼泽的荆棘谷地精控制台取回神秘的主动式负载平衡器后，斯布特瓦夫忍不住向他在地下矿道的工程师同行们吹嘘了一番。不幸的是，他的摆弄弄巧成拙，导致这件精密的装置损坏了。为了兑现他的诺言，他急需一个具备更高超技术能力的人来诊断损伤并进行维修。"},{t="壁垒旁的技师",b="温妮奇·螺栓桶的营地位于莫尔杉壁垒南侧的路上，这里是分隔北贫瘠之地与灰谷的防御屏障。她以好奇的天性和创造性的思维而闻名，总是很容易被复杂的机械所吸引。当她看到那个损坏的主动式负载平衡器时，其内部齿轮立刻勾起了她的好奇心，促使她放下手头的一切工作，开始研究如何将其修复。"}},faq={{q="主动式负载平衡器为什么会损坏？",a="斯布特瓦夫在从淤泥沼泽的控制台找回该装置后，曾试图检查并摆弄它，结果却损坏了其复杂的内部机械结构。",al={"为什么损坏","它是怎么坏的","斯布特瓦夫弄坏的"}},{q="温妮奇·螺栓桶是谁？",a="她是一位富有创造力的地精技师，驻扎在北贫瘠之地与灰谷交界处的莫尔杉壁垒南侧，以精通复杂机械而闻名。",al={"温妮奇是谁","螺栓桶的位置","温妮奇在哪里"}},{q="斯布特瓦夫为什么如此关心修复它？",a="斯布特瓦夫已经向地下矿道的同事们吹嘘过他搞到了这个装置。如果他不能拿出一个正常运作的设备，他的名声和职业地位将受到严重打击。",al={"为什么修理主动式负载平衡器","斯布特瓦夫与地下矿道","他为什么在乎"}},{q="温妮奇知道主动式负载平衡器到底是做什么用的吗？",a="不知道。刚拿到它时，她甚至询问主动式负载平衡器到底是什么，但很快就被其复杂的齿轮声所吸引，想要修复它纯粹是为了看看它到底有什么用。",al={"她知道这是什么吗","对她来说主动式负载平衡器是什么"}},{q="莫尔杉壁垒位于哪里？",a="莫尔杉壁垒是部落的防御前哨，位于贫瘠之地的北缘，守卫着通往灰谷的通道。",al={"莫尔杉壁垒位置","壁垒在哪里","贫瘠之地与灰谷边界"}},{q="温妮奇检查完损坏的装置后会发生什么？",a="由于对它的结构很感兴趣，温妮奇同意修理这个主动式负载平衡器，但她需要特定的机械零件，首先就是淤泥沼泽的荆棘谷地精工具桶里存放的那些小金属块，以便让齿轮重新运转起来。",al={"接下来做什么","小金属块","主动式负载平衡器的下一步"}}},fp="18,249,17.373.0,27.338.0,30.134.0,26.202.0,51.181.0,51.148.0,38.120.0,54.225.1"}
P.entries["quest:3922"] = {n="高强度齿轮",s="“高强度齿轮”是贫瘠之地北部的一项任务，由古怪的技师Wenikee Boltbucket发布。她渴望修理并研究一个找回来的samophlange，于是委托冒险者去附近的淤泥沼泽突袭荆棘谷地精的钻探作业，以获取备用零件。",h="“高强度齿轮”是贫瘠之地北部的一项任务，由古怪的技师Wenikee Boltbucket发布。她渴望修理并研究一个找回来的samophlange，于是委托冒险者去附近的淤泥沼泽突袭荆棘谷地精的钻探作业，以获取备用零件。",kw={"贫瘠之地","高强度齿轮","samophlange","淤泥沼泽","工具桶","荆棘谷地精","wenikee boltbucket"},ang={["faction:Horde"]="荆棘谷地精在淤泥沼泽的侵入性作业对部落来说是一种持续的环境滋扰，因此任何偷窃他们物资的借口都受欢迎。",["profession:Engineering"]="任何在职的工程师在Wenikee草率的修理工作在她脸上爆炸之前，就能认出这是地精作品的典型警告信号。"},sec={{t="Wenikee的工程需求",b="在获得了一个复杂的samophlange后，Wenikee Boltbucket决心摆弄这台奇怪的机器，看看它是如何工作的。然而，精密的地精机械需要非常特殊的硬件。由于自己缺乏材料，Wenikee派跑腿去从当地的荆棘谷地精工作队那里偷窃17.5号高强度齿轮，这些家伙粗心地把沉重的工具桶随手丢在附近的淤泥沼泽油井边。"},{t="易爆的突破",b="收集十五个特制金属齿轮需要避开那些在道路东侧沼泽中横冲直撞的荆棘谷地精操作员和伐木工。一旦硬件送到，Wenikee立刻把samophlange放在地上，开始进行即时调整。正如典型的地精工程学，不匹配的零件和草率的组装导致了一场突如其来的灾难性爆炸——Wenikee被震得七荤八素，但显然并未因此气馁。"}},faq={{q="什么是高强度齿轮？",a="在地精工程学术语中，高强度齿轮是小型、标准化的金属紧固件或弹药组件。Wenikee特别需要17.5号齿轮来与samophlange内部精密的齿轮进行对接。",al={"高强度齿轮","什么是高强度齿轮"}},{q="Wenikee Boltbucket是谁？",a="Wenikee Boltbucket是一位在贫瘠之地北部主路旁露营的独立技师。她对复杂的机械装置有着强烈的痴迷，尤其是samophlange，完全不顾其中明显的安全隐患。",al={"wenikee","wenikee是谁","wenikee boltbucket"}},{q="在哪里可以找到高强度齿轮？",a="它们是从散落在淤泥沼泽周围的工具桶中拾取的，淤泥沼泽是由荆棘谷地精运营的一个工业化伐木和石油开采营地，位于Wenikee路边小营地的正东面。",al={"工具桶位置","寻找高强度齿轮","淤泥沼泽工具桶"}},{q="当Wenikee修理samophlange时会发生什么？",a="Wenikee刚收到零件并开始修理这台机器，它就超负荷并直接在她脸上引爆了，展示了校准不良的机械极其危险且不稳定的一面。",al={"samophlange能用吗","samophlange爆炸","wenikee爆炸"}},{q="荆棘谷地精为什么在淤泥沼泽？",a="荆棘谷地精建立了淤泥沼泽，旨在从贫瘠之地的沼泽地中进行露天开采和提取石油及自然资源，用重型钻机和炼油厂污染了周围的景观。",al={"为什么荆棘谷地精在淤泥沼泽","淤泥沼泽目的","荆棘谷地精 贫瘠之地"}},{q="这个任务会解锁后续任务吗？",a="会。在她的修理尝试失败后，Wenikee会派你去奥格瑞玛咨询前荆棘谷地精工程师Rilli Greasygob，任务名为“Rilli Greasygob”。",al={"what comes next","后续任务","高强度齿轮之后"}}},fp="12,176,27.288.0,23.339.1,22.185.0,26.196.0,33.178.0,50.171.1,45.187.0,41.171.1"}
P.entries["quest:3923"] = {n="雷里·格里斯高布",s="这个任务要求冒险者将一个损坏的主动式负载平衡器从修补匠温尼基·螺栓桶那里直接带到奥格瑞玛。为了寻找真正了解该装置起源的专家，温尼基指引你去找里利·油嘴，他是一位曾在荆棘谷地精效力过的前工程师，目前驻扎在诺格的机器商店。",h="这个任务要求冒险者将一个损坏的主动式负载平衡器从修补匠温尼基·螺栓桶那里直接带到奥格瑞玛。为了寻找真正了解该装置起源的专家，温尼基指引你去找里利·油嘴，他是一位曾在荆棘谷地精效力过的前工程师，目前驻扎在诺格的机器商店。",kw={"破碎的主动式负载平衡器","诺格的机器商店","奥格瑞玛","里利·油嘴","主动式负载平衡器","valley of honor","荆棘谷地精","温尼基·螺栓桶"},ang={["faction:Horde"]="部落依靠像奥格瑞玛诺格机器商店这样的城市车间，来改装从掠夺卡利姆多的掠夺性财团手中缴获的敌方机械。",["profession:Engineering"]="每一位工程师都知道何时该放下扳手；螺栓桶意识到增加更多的表盘只会让事情变得更糟，这直接引出了由前公司技术人员保存的专门行业机密。"},sec={{t="当修补失败时",b="温尼基·螺栓桶尝试着诊断从贫瘠之地的荆棘谷地精钻探点回收来的主动式负载平衡器。不幸的是，增加额外的测量仪表只会证实该设备正处于完全崩溃的边缘。由于意识到堆砌更多的杠杆和表盘可能会彻底毁掉这个装置，螺栓桶承认自己束手无策，并决定将这个问题交给拥有专有技术知识的人。"},{t="前公司雇员",b="为了破译这台机器的内部工作原理，螺栓桶派遣旅行者前往奥格瑞玛的Valley of Honor，去拜访诺格的机器商店。在那里工作的是里利·油嘴，一位曾经在荆棘谷地精残酷的等级制度下谋生的工程师。油嘴一眼就认出了这台机器，并对有人能在贫瘠之地那个地精集团的争议性行动中幸存下来感到惊讶。"}},faq={{q="谁是里利·油嘴？",a="里利·油嘴是一位地精工程师，在奥格瑞玛的Valley of Honor的诺格的机器商店工作。由于此前曾为荆棘谷地精工作，他拥有关于该集团专有技术的一手稀有知识，包括像主动式负载平衡器这样神秘的装置。",al={"里利·油嘴","谁是里利","诺格的机器商店里利"}},{q="为什么温尼基·螺栓桶不能自己修理主动式负载平衡器？",a="温尼基·螺栓桶试图通过连接额外的测量仪表来诊断主动式负载平衡器，但这些仪表显示其结构完整性正在迅速恶化。她意识到胡乱修补只会毁掉这个精密装置，因此决定需要一个拥有直接的荆棘谷地精制造经验的人。",al={"为什么要送给里利","螺栓桶失败","温尼基修不好"}},{q="里利·油嘴在哪里？",a="里利·油嘴位于奥格瑞玛东北区的Valley of Honor里的诺格的机器商店内。",al={"里利·油嘴位置","油嘴在哪里","找到里利"}},{q="荆棘谷地精在其中扮演什么角色？",a="主动式负载平衡器是从贫瘠之地北部的淤泥沼泽的荆棘谷地精露天采矿作业中回收的。由于这是荆棘谷地精的定制技术，只有像里利·油嘴这样的前公司员工才有能力对其进行适当的维护和解读。",al={"荆棘谷地精联系","为什么是荆棘谷地精","谁制造了主动式负载平衡器"}},{q="把主动式负载平衡器交给里利后会发生什么？",a="在认出该装置后，里利·油嘴判定要完全操作或重建它，他需要荆棘谷地精的官方操作说明，这引导冒险者去寻找主动式负载平衡器说明书。",al={"里利之后做什么","主动式负载平衡器任务线后续"}},{q="主动式负载平衡器到底是什么？",a="似乎没人能确定。这是一个复杂的、古怪的荆棘谷地精装置，充满了齿轮；即使是温尼基·螺栓桶也不得不询问什么是主动式负载平衡器，而里利需要公司自己的手册才能搞清楚它。",al={"什么是主动式负载平衡器","主动式负载平衡器解释"}}},fp="15,197,20.281.0,20.299.0,23.206.0,60.203.0,33.117.0,43.224.0,51.181.1,29.217.0"}
P.entries["quest:3924"] = {n="主动式负载平衡器说明书",s="“主动式负载平衡器说明书”是一个由奥格瑞玛的侏儒工程师里里·油嘴发布的任务。为了修复一个损坏的主动式负载平衡器，里里派遣冒险者重返贫瘠之地，从他曾经的荆棘谷地精对手那里夺回该装置的专有操作说明。",h="“主动式负载平衡器说明书”是一个由奥格瑞玛的侏儒工程师里里·油嘴发布的任务。为了修复一个损坏的主动式负载平衡器，里里派遣冒险者重返贫瘠之地，从他曾经的荆棘谷地精对手那里夺回该装置的专有操作说明。",kw={"贫瘠之地","库普拉格工头","石矿洞","说明书","奥格瑞玛","里里·油嘴","主动式负载平衡器","斯布特瓦夫","荆棘谷地精"},ang={["faction:Horde"]="协助奥格瑞玛内的地精专家有助于获得宝贵的技术回收物，同时打击荆棘谷地精在附近地区的掠夺性行动。",["profession:Engineering"]="工程师们能够理解地精企业知识产权中荒谬的保密行为，复杂的蓝图被撕碎并囤积，以防止同事复制发明。"},sec={{t="企业竞争与商业机密",b="在荆棘谷地精的雇佣兵队伍中，技术知识就是货币。里里·油嘴曾经与库普拉格工头共事，后者是一位监督员，他以偏执的保密态度守护着神秘的主动式负载平衡器的内部构造。库普拉格并没有分享这本说明书，而是将其单独的页面分发给受信任的下属，让里里这样的同行对它的内部运作一无所知。"},{t="潜入石矿洞",b="为了破解从贫瘠之地带给他的复杂机械装置，里里派遣旅行者潜入位于贫瘠之地东北部的石矿洞。找回说明书需要直接追踪库普拉格工头，并收集他分发到矿井作业中的所有散页，最终汇编成一本修复这一棘手装置的完整指南。"}},faq={{q="什么是主动式负载平衡器说明书？",a="这是一本技术用户指南，详细说明了主动式负载平衡器的机械原理和维修程序，这是一种荆棘谷地精使用的复杂而古怪的机械装置。",al={"什么是说明书","主动式负载平衡器说明书物品","用户手册"}},{q="库普拉格工头是谁？",a="库普拉格工头是驻扎在贫瘠之地东北部石矿洞的荆棘谷地精监督员。他是里里·油嘴的前竞争对手，他嫉妒地囤积着主动式负载平衡器的操作秘密和说明书页面。",al={"库普拉格","库普拉格是谁","库普拉格工头"}},{q="石矿洞位于哪里？",a="石矿洞开凿在贫瘠之地东北部地区的群山之中，位于十字路口以北，海岸线以西。",al={"石矿洞位置","石矿洞在哪里","寻找石矿洞"}},{q="为什么里里·油嘴需要这本说明书？",a="里里相信他可以成功修复并操作从贫瘠之地带回的损坏的主动式负载平衡器，但该装置专有且复杂的设计需要其官方操作说明。",al={"里里为什么需要说明书","为什么要修复主动式负载平衡器"}},{q="斯布特瓦夫在这个任务中起到什么作用？",a="斯布特瓦夫是位于棘齿城的一位合伙人，他最初寻求关于该装置的信息并与里里保持联系，通过发送感谢和报酬来换取机器的蓝图。",al={"斯布特瓦夫的联系","棘齿城地精斯布特瓦夫"}},{q="说明书交回后会发生什么？",a="里里热情地拿走说明书研究其内容，希望能最终让机器运转起来，尽管修复这样一台神秘的装置仍然是一个持续存在的机械难题。",al={"任务结论","里里修复了吗"}}},fp="18,193,37.338.0,28.316.1,31.135.0,23.203.0,39.98.0,41.152.0,41.201.0,42.143.0"}
P.entries["quest:393"] = {n="往日的阴影",s="“往昔阴影”是一个联盟调查任务，指引玩家从暴风城建筑师巴隆斯·阿历克斯顿处前往军情七处首领马迪亚斯·肖尔处。在调查了一名曾与被监禁的迪菲亚潜行者头目巴基尔·斯瑞德交谈过的神秘访客后，线索从公共建设丑闻转向了暴风城的秘密情报网络。",h="“往昔阴影”是一个联盟调查任务，指引玩家从暴风城建筑师巴隆斯·阿历克斯顿处前往军情七处首领马迪亚斯·肖尔处。在调查了一名曾与被监禁的迪菲亚潜行者头目巴基尔·斯瑞德交谈过的神秘访客后，线索从公共建设丑闻转向了暴风城的秘密情...",kw={"巴隆斯·阿历克斯顿","巴基尔·斯瑞德","格雷戈尔·莱斯科瓦","马里克","马尔松","mathias shaw","往昔阴影","军情七处","暴风城"},ang={["class:Rogue"]="向Old Town的马迪亚斯·肖尔汇报，让潜行者能够直接一窥联盟情报工作和政治监视的巅峰。",["faction:Alliance"]="调查的这一阶段标志着低级迪菲亚匪徒直接与暴风城的腐败贵族联系在一起的关键点。",["race:Human"]="对于暴风城的人类来说，这项任务揭示了瓦里安·乌瑞恩国王缺席期间，王国统治阶层分裂到了何种地步。"},sec={{t="阴影中的线索",b="在向典狱官塞尔沃特询问有关监狱主要囚犯巴基尔·斯瑞德的可疑访客信息后，调查在巴隆斯·阿历克斯顿这里陷入了僵局。虽然这位城市建筑师无法确认那个神秘人物的身份，但他指点你去找一个专门处理首都所有秘密的人：秘密情报机构军情七处的首领，马迪亚斯·肖尔。"},{t="揭开访客的面纱",b="将密封的体貌描述递交给位于Old Town的军情七处总部后，立刻有了结果。肖尔很快识破了访客使用的化名“马里克”。他认出了这是一个习惯像脱掉斗篷一样随意抛弃名字的职业杀手的特征，并将他确认为一名通常以“马尔松”为代号的刺客。"},{t="贵族叛变",b="肖尔透露，马尔松目前受雇于暴风城贵族格雷戈尔·莱斯科瓦勋爵，此人早已以狡诈闻名。这一联系揭露了一个令人不寒而栗的事实：迪菲亚潜行者的犯罪暴乱不仅仅是西部荒野的一场遥远的叛乱，而是一场深入暴风城贵族大厅的阴谋。"}},faq={{q="是谁让你去找马迪亚斯·肖尔的？",a="暴风城建筑师巴隆斯·阿历克斯顿在承认无法辨认监狱典狱官笔记中描述的访客后，指引你去找马迪亚斯·肖尔。阿历克斯顿动用了一份旧时的人情，以引起这位情报大师的注意。",al={"谁给予此任务","往昔阴影任务给予者"}},{q="马迪亚斯·肖尔在哪里？",a="马迪亚斯·肖尔位于暴风城Old Town的军情七处总部内。这座建筑是王国潜行者、侦察兵和情报官员的秘密指挥中心。",al={"马迪亚斯·肖尔位置","肖尔在哪里","寻找马迪亚斯·肖尔"}},{q="监狱的神秘访客是谁？",a="该访客使用的名字是马里克。巴隆斯无法确认他的身份，并将密封的描述发送给了马迪亚斯·肖尔。",al={"马里克是谁","斯瑞德的访客是谁","刺客是谁"}},{q="格雷戈尔·莱斯科瓦勋爵为何卷入其中？",a="巴隆斯从未提到过莱斯科瓦。这位勋爵在事件中的角色直到马迪亚斯·肖尔读过访客的描述后才曝光。",al={"马尔松为谁工作","莱斯科瓦的关系"}},{q="SI:7代表什么？",a="SI:7代表暴风城情报局。它是暴风城的秘密行动和间谍机构，负责在国内外收集情报并执行秘密任务。",al={"什么是军情七处","si:7的含义"}},{q="为什么巴隆斯·阿历克斯顿能调动军情七处？",a="巴隆斯·阿历克斯顿提到马迪亚斯·肖尔欠他一个人情，尽管他刻意拒绝透露细节。",al={"为什么肖尔欠巴隆斯人情","巴隆斯与肖尔的关系"}}},fp="18,191,21.329.0,21.258.1,25.223.1,30.187.0,37.155.0,47.113.1,37.126.1,25.142.0,44.79.0"}
P.entries["quest:394"] = {n="禽兽的首级",s="在背叛者格雷戈·莱斯科瓦男爵被刺杀后，这项任务指引你从埃林·提亚斯那里前往Old Town去见马迪亚斯·肖尔。报告莱斯科瓦的死讯能巩固你在暴风城秘密情报网络中的地位。",h="在背叛者格雷戈·莱斯科瓦男爵被刺杀后，这项任务指引你从埃林·提亚斯那里前往Old Town去见马迪亚斯·肖尔。报告莱斯科瓦的死讯能巩固你在暴风城秘密情报网络中的地位。",kw={"埃林·提亚斯","野兽的头颅","莱斯科瓦","mathias shaw","old town","军情七处","暴风城"},ang={["class:Rogue"]="直接向马迪亚斯·肖尔报告是一项至关重要的入门考验，能够向暴风城最重要的阴影组织首领证明你的可靠性。",["faction:Alliance"]="清除暴风城内部的腐败贵族有助于在瓦里安·乌瑞恩国王缺席导致的局势动荡期间稳定王国。"},sec={{t="已解决的问题",b="随着莱斯科瓦男爵在针对王国的阴谋得逞前被击倒，对暴风城领导层的直接威胁已被铲除。奶酪商兼资深特工埃林·提亚斯立刻指引你离开犯罪现场，深入Old Town的阴影之中，并告诫你不要因朝廷的赞誉而冲昏了头脑。"},{t="向军情七处首领报告",b="在Old Town的隐秘密室中，马迪亚斯·肖尔通过军情七处监管着王国的秘密机构。在收到莱斯科瓦死亡的消息后，肖尔认可了你的技术和冷酷，热切地赞扬了你的效率，并感谢你为暴风城的人民所做的伟大贡献。"}},faq={{q="这个任务的目的是什么？",a="这个简短的插曲要求你从埃林·提亚斯处前往暴风城Old Town的马迪亚斯·肖尔那里，以确认格雷戈·莱斯科瓦男爵已被处决。",al={"野兽的头颅任务","野兽的头颅任务要做什么"}},{q="马迪亚斯·肖尔是谁？",a="马迪亚斯·肖尔是军情七处的首领，这是暴风城的秘密情报机构和刺客公会，其行动基地就设在Old Town的隐秘处。",al={"肖尔","马迪亚斯·肖尔","军情七处首领"}},{q="为什么埃林·提亚斯派你去找肖尔，而不是找宫廷卫兵？",a="提亚斯身处暴风城情报机构的核心。由于莱斯科瓦是一位从事高度叛国活动的显赫贵族，处理余波需要秘密进行，而不是在卫兵中引发公开的丑闻。",al={"为什么找肖尔而不是卫兵","为什么向肖尔报告"}},{q="莱斯科瓦对暴风城构成了什么威胁？",a="格雷戈·莱斯科瓦男爵一直在与颠覆性特工密谋反对王室和首都的安全，从贵族内部背叛王国。",al={"莱斯科瓦的威胁","莱斯科瓦做了什么"}},{q="报告莱斯科瓦死亡后会发生什么？",a="马迪亚斯·肖尔准备结束这起阴谋，并派你前往解决笼罩在暴风城上空的最后颠覆威胁。",al={"野兽的头颅后续任务","what comes next"}},{q="在哪里可以找到马迪亚斯·肖尔？",a="马迪亚斯·肖尔位于军情七处的指挥大楼内，藏身于暴风城东部地区的Old Town之中。",al={"肖尔的位置","马迪亚斯·肖尔在哪里"}}},fp="21,211,17.258.1,26.265.0,34.139.0,20.103.0,67.191.0,43.145.0,46.137.0,32.110.0"}
P.entries["quest:395"] = {n="兄弟会的灭亡",s="“兄弟会的终结”标志着在Stormwind Keep内针对格雷戈尔·雷斯科瓦男爵的秘密行动后的余波。随着这个背叛的贵族死去，马迪亚斯·肖尔大师派你去见城市建筑师巴隆斯·阿历克斯顿，并警告你不要透露究竟是谁执行了致命一击。",h="“兄弟会的终结”标志着在Stormwind Keep内针对格雷戈尔·雷斯科瓦男爵的秘密行动后的余波。随着这个背叛的贵族死去，马迪亚斯·肖尔大师派你去见城市建筑师巴隆斯·阿历克斯顿，并警告你不要透露究竟是谁执行了致命一击。",kw={"巴隆斯·阿历克斯顿","兄弟会的终结","迪菲亚","埃林·提亚斯","格雷戈尔·雷斯科瓦","mathias shaw","军情七处","stormwind keep"},ang={["class:Rogue"]="Mathias Shaw的警告强调了军情七处行动的一条不成文规定：在沉默中执行王国的正义，永远不要因为贵族的血而公开邀功。",["faction:Alliance"]="揭露Stormwind Keep内部的迪菲亚阴谋证明，王国面临的颠覆不仅来自乡间的强盗，还来自其自身的贵族大厅内部。",["race:Human"]="对于暴风城的人类来说，这项任务终结了多年前开始于城市街道上的石匠反叛，在不撕裂王国的情况下维护了正义。"},sec={{t="阴影中的线索",b="在格雷戈尔·雷斯科瓦男爵及其迪菲亚联系人，沉默之刃马尔松被暗杀后，马迪亚斯·肖尔大师建议务必极其谨慎。在皇家要塞内除掉一位高阶贵族充满了政治风险，即使雷斯科瓦已经深陷叛国罪中。肖尔建议你与巴隆斯·阿历克斯顿分享迪菲亚阴谋的大致情况，同时将你自己的致命角色——以及那个流氓奶酪商人埃林·提亚斯的参与——完全排除在记录之外。"},{t="松了一口气",b="巴隆斯·阿历克斯顿，这位曾经作为石匠帮助重建暴风城的城市建筑师，对雷斯科瓦的死讯感到如释重负。在石匠工会被驱逐且分文未得后，阿历克斯顿和其他在重建工作中扮演重要角色的杰出人物都成为了艾德温·范克里夫复仇的目标。随着雷斯科瓦被灭口，阴谋也被挫败，阿历克斯顿相信，笼罩在王国建筑师和贵族头顶的直接报复威胁终于消除了。"}},faq={{q="“兄弟会的终结”里发生了什么？",a="在Stormwind Keep除掉格雷戈尔·雷斯科瓦男爵后，你向军情七处的马迪亚斯·肖尔大师汇报。肖尔指示你去向城市建筑师巴隆斯·阿历克斯顿汇报，他急切地想知道针对城市领导人的迪菲亚阴谋是否已经被挫败。",al={"什么是兄弟会的终结","兄弟会的终结任务概述","兄弟会的终结简介"}},{q="为什么肖尔让你不要承认杀了雷斯科瓦？",a="格雷戈尔·雷斯科瓦男爵是暴风城贵族议会的一位高阶贵族。即使证据表明他与迪菲亚勾结，公开承认在皇家要塞内暗杀了一位贵族也会引发政治丑闻和报复性的审查。肖尔深谙这座城市的残酷政治，建议让这件事保持无名状态。",al={"为什么要隐瞒雷斯科瓦的死","为什么要对雷斯科瓦撒谎","肖尔关于雷斯科瓦的建议"}},{q="为什么不应该提到埃林·提亚斯？",a="埃林·提亚斯在Trade District伪装成一个普通的奶酪商人，但实际上他是一位在城市阴影中拥有广泛联络网的资深特工。曝光他参与揭露阴谋的行动会暴露他的掩护身份，并危及他庞大的地下网络。",al={"为什么要隐瞒提亚斯","提亚斯的秘密","提亚斯奶酪商人身份"}},{q="为什么巴隆斯·阿历克斯顿会特别担心迪菲亚？",a="巴隆斯·阿历克斯顿是石匠工会的一员，曾与艾德温·范克里夫一起重建暴风城。当贵族议会拒绝支付工人工资时，石匠们转而沦为强盗，而留在城市服务岗位的阿历克斯顿则被置于了范克里夫复仇的中心。",al={"为什么阿历克斯顿会关心","巴隆斯·阿历克斯顿与范克里夫","阿历克斯顿与迪菲亚的联系"}},{q="这个任务标志着迪菲亚威胁的终结了吗？",a="虽然它除掉了艾德温·范克里夫在贵族议会中的关键同情者，但这并不能完全抹除迪菲亚的存在。然而，除掉雷斯科瓦是对他们渗透暴风城政府的沉重打击，并避免了一场来自城墙之内的即时政变。",al={"迪菲亚被消灭了吗","迪菲亚现在死了吗","兄弟会的终结结束了迪菲亚吗"}},{q="这项调查接下来会走向何方？",a="由于你成功除掉了阴谋者，巴隆斯·阿历克斯顿感到如释重负，他准备了一份有关迪菲亚兄弟会的报告呈交给国王，并要求你亲自在Stormwind Keep的觐见中递交，该任务名为“觐见国王”。",al={"下一个任务是什么","兄弟会的终结之后是什么","下一个找谁"}}},fp="17,187,25.404.1,18.411.0,34.231.0,56.232.0,39.245.1,61.268.0,50.238.0,40.213.1"}
P.entries["quest:396"] = {n="觐见国王",s="“觐见国王”是对西部荒野和死亡矿井中长久以来针对迪菲亚潜行者调查的终结。带着城市建筑师巴隆斯·阿历克斯顿拟定的最终报告，英雄们前往Stormwind Keep，在王国的最高权威面前彻底终结这一威胁。然而，抵达王座大厅时却发现，首都的王室事务并不像看起来那么简单。",h="“觐见国王”是对西部荒野和死亡矿井中长久以来针对迪菲亚潜行者调查的终结。带着城市建筑师巴隆斯·阿历克斯顿拟定的最终报告，英雄们前往Stormwind...",kw={"觐见国王","巴隆斯·阿历克斯顿","兄弟会的终结","迪菲亚报告","艾德温·范克里夫","卡特拉娜·普瑞斯托","stormwind keep","瓦里安·乌瑞恩"},ang={["class:Rogue"]="踏入最高权力大厅报告艾德温·范克里夫的倒台，这鲜明地提醒了人们王室特工和不法公会首领之间的界限是多么微薄。",["faction:Alliance"]="递交这份报告标志着威胁联盟主要人类王国的一场重大内部危机的解决。",["race:Human"]="对于暴风城的人类来说，这次觐见是一个苦乐参半的里程碑：它为西部荒野遭受的恐怖袭击报了仇，却也悄然揭示了王国那脆弱且国王缺位的现状。"},sec={{t="王室传唤",b="在击败了艾德温·范克里夫并瓦解了月溪镇下方的阴谋后，城市建筑师巴隆斯·阿历克斯顿为王室编写了一份官方卷宗。阿历克斯顿坚持认为，那个摧毁了该公会犯罪企业的人应该接受君主的嘉奖。信使带着这份详细的报告穿过大运河来到Stormwind Keep，满怀期待地准备觐见王国的统治者。"},{t="空虚的王座",b="当报告的携带者踏入皇家宫廷时，并没有发现瓦里安·乌瑞恩国王在等待他们。相反，皇家顾问女伯爵卡特拉娜·普瑞斯托代表王室接过了卷宗。普瑞斯托轻描淡写地解释了君主的缺席，称瓦里安国王正在执行一项长期的外交任务，无法亲自进行嘉奖。她收下了报告，称赞英雄使暴风城免于范克里夫阴谋的侵害，并以失踪国王的名义提供了奖励，巧妙地掩盖了迪菲亚潜行者起义的严酷真相。"}},faq={{q="为什么是由我而不是巴隆斯·阿历克斯顿来递交这份报告？",a="巴隆斯·阿历克斯顿认为你通过实地调查赢得了这份荣誉。既然是你亲自追踪迪菲亚潜行者的阴谋穿过西部荒野并突袭了死亡矿井，阿历克斯顿坚持认为你应该亲自呈交调查结果并接受王室的认可。",al={"为什么要递交报告","巴隆斯·阿历克斯顿的报告","觐见国王与报告递交"}},{q="瓦里安·乌瑞恩国王在哪里？",a="瓦里安·乌瑞恩国王不在Stormwind Keep。官方说法是，王室朝臣解释国王正在执行一项秘密外交任务，将年幼的儿子安度因留在了王座上，由伯瓦尔·弗塔根公爵摄政。",al={"国王在哪里","瓦里安为什么不在","瓦里安·乌瑞恩在哪里","国王失踪"}},{q="到底是谁接收了迪菲亚潜行者的报告？",a="女伯爵卡特拉娜·普瑞斯托在皇家宫廷接待了你。作为王座的首席顾问，她接受了巴隆斯·阿历克斯顿的报告，称赞你铲除了艾德温·范克里夫，并代表王室为你提供了奖励。",al={"谁来终结任务","在stormwind keep里找谁","谁来接收报告"}},{q="这个任务是迪菲亚潜行者任务线的终点吗？",a="是的。该任务作为在西部荒野早期开始并贯穿死亡矿井地下城的宏大迪菲亚故事线的正式政治总结。",al={"迪菲亚任务线终点","这是最后一个迪菲亚任务吗","死亡矿井后续"}},{q="为什么女伯爵卡特拉娜·普瑞斯托对国王的缺席表现得如此轻描淡写？",a="普瑞斯托表现得从容不迫，以维持皇家宫廷的秩序。通过向访客保证瓦里安国王只是在远方处理国事，摄政政府试图降低人们对国王下落不明的焦虑。",al={"普瑞斯托为什么冷静","普瑞斯托的外交任务","普瑞斯托的借口"}},{q="在此之后迪菲亚潜行者会怎样？",a="随着艾德温·范克里夫的死亡和他们宏大的巨型战舰计划的挫败，该兄弟会的领导层已分崩离析。然而，分散的强盗和残党仍在困扰着西部荒野、赤脊山和暴风城的小巷。",al={"迪菲亚潜行者消失了吗","迪菲亚潜行者的未来","兄弟会被摧毁了吗"}}},fp="25,184,15.339.0,15.405.1,58.230.0,27.192.0,37.216.0,53.119.0,71.159.0,50.212.0"}
P.entries["quest:397"] = {n="干得好",s="“你服务得很好”是暴风城的一项术士任务。术士学员们受黑爪加尔德斯之托，需要回到“屠宰场小羊”酒馆下的秘密据点，完成他们的任务并领取奖励。",h="“你服务得很好”是暴风城的一项术士任务。术士学员们受黑爪加尔德斯之托，需要回到“屠宰场小羊”酒馆下的秘密据点，完成他们的任务并领取奖励。",kw={"贵族的酒","黑爪","小鬼","威肖克勋爵","暴风城","屠宰场小羊","加尔德斯","兹吉"},ang={["class:Warlock"]="这项任务展示了在暴风城生存所需的冷酷务实：在爱管闲事的贵族将城市卫兵引向你们之前，先消灭他们，以此来保护你的集会。",["faction:Alliance"]="在暴风城那洁净的尖塔和虔诚的信仰之下，隐藏着一个阴暗的角落，禁忌的术士们在这里秘密暗杀那些高贵的干预者，以保护他们的存在。"},sec={{t="影中买来的沉默",b="在暴风城的表面之下，黑暗艺术的修行者们在岌岌可危的宽容中运作。当像威肖克勋爵这样的贵族权威威胁要揭露或破坏他们的隐秘研究时，集会采取了果断的行动。通过用毒药暗杀威肖克，术士们保住了他们在“屠宰场小羊”酒馆下的隐秘据点。"},{t="主人的恩赐",b="在收到威肖克喝下最后一杯酒的消息后，黑爪加尔德斯认为眼前的威胁已经消除。作为对让城市卫兵和好奇的同僚远离此事的报酬，加尔德斯委托他那唯唯诺诺的仆从——一个名叫兹吉的小鬼——将一份黑暗的谢礼授予这位忠诚的修行者。"}},faq={{q="黑爪加尔德斯是谁？",a="黑爪加尔德斯是一位在暴风城秘密活动的著名术士。他致力于保护城中隐秘的暗影施法者不被当地贵族发现，并采取冷酷无情的手段消除任何试图窥探他们禁忌法术的人。",al={"加尔德斯是谁","加尔德斯的角色","黑爪首领"}},{q="威肖克勋爵发生了什么事？",a="威肖克勋爵被灌下了一瓶由暴风城隐秘术士特制的毒药。他的死确保了贵族家族不会再调查或打扰在城市街道下进行仪式的黑暗修行者。",al={"威肖克死了吗","那杯酒是干什么用的","威肖克勋爵的命运"}},{q="兹吉是谁？",a="兹吉是一个被束缚在黑爪加尔德斯麾下的小鬼。他满腹牢骚又贪婪成性，渴望把主人的宝藏据为己有，但又害怕公开反抗加尔德斯的命令会招致惩罚。",al={"小鬼兹吉是谁","兹吉仆从"}},{q="为什么威肖克勋爵会成为术士们的目标？",a="威肖克对暴风城的术士集会构成了严重的干扰和暴露威胁。通过终结他的干涉，术士们换取了不受打扰的安全性，从而可以在不受贵族阻碍的情况下继续钻研恶魔学识和暗影魔法。",al={"为什么要杀威肖克","威肖克的威胁"}},{q="这个任务链在哪里结束？",a="该任务直接在小鬼兹吉处完成，他位于暴风城法师区“屠宰场小羊”酒馆下方的术士圣所，黑爪加尔德斯附近。",al={"我在哪里交“你服务得很好”这个任务","兹吉的位置"}},{q="为什么这项任务严格限制只有术士才能接？",a="这项行动涉及微妙的内部集会政治和非法暗杀。只将这种致命的阴谋委托给经过验证的术士门徒，可以防止背叛，并让更广泛的联盟当局对这一行为一无所知。",al={"这是术士专属任务吗","为什么是术士任务"}}},fp="23,178,27.288.0,17.264.1,33.243.0,30.191.1,12.174.0,46.196.0,37.137.0,49.186.0"}
P.entries["quest:398"] = {n="悬赏：蛆眼",s="“通缉：蛆眼”是由布瑞尔的被遗忘者领导层发布的一份正式死亡悬赏。这只臭名昭著的豺狼人一直在劫掠附近的墓地和农场，直接向巫妖王的亡灵天灾输送尸体。执行官塞加德要求获得该生物被处决的证明，以确保加伦鬼屋周边的土地安全。",h="“通缉：蛆眼”是由布瑞尔的被遗忘者领导层发布的一份正式死亡悬赏。这只臭名昭著的豺狼人一直在劫掠附近的墓地和农场，直接向巫妖王的亡灵天灾输送尸体。执行官塞加德要求获得该生物被处决的证明，以确保加伦鬼屋周边的土地安全。",kw={"悬赏","布瑞尔","执行官塞加德","加伦鬼屋","豺狼人","盗墓贼","巫妖王","蛆眼","提瑞斯法林地"},ang={["faction:Horde"]="如果部落想要在洛丹伦维持一个对抗天灾军团残余势力的稳固立足点，就必须平定提瑞斯法林地的北部边境。",["race:Undead"]="蛆眼偷走的每一具尸体，都是一个沦为巫妖王奴隶傀儡的逝去同胞。除掉它既是国防的需要，也是为了个人复仇。"},sec={{t="严重的罪行",b="在提瑞斯法林地，死者远未得到安息。这只名为蛆眼的豺狼人之所以被判处死刑，不仅是因为它在四处搜刮，更因为它是巫妖王的活跃帮凶。虽然豺狼人通常被视为受饥饿驱使的野蛮野兽，但蛆眼却一直在系统性地挖掘坟墓，搜集遗骸，从而壮大天灾军团的势力。"},{t="布瑞尔的正义",b="对于被遗忘者而言，他们的整个存在都取决于是否能从巫妖王的统治中挣脱出来，因此将死去的族人送回天灾军团的战争机器中是不可饶恕的罪行。负责布瑞尔当地军事执法的执行官塞加德发布了这份悬赏，旨在终结加伦鬼屋附近的盗墓行径。领取赏金的行刑者必须带回蛆眼的爪子，作为这头野兽再也无法骚扰提瑞斯法林地的确凿证据。"}},faq={{q="蛆眼是谁？",a="蛆眼是一只臭名昭著的豺狼人，出没于提瑞斯法林地的北部地区。即使在同类中，它也被视为极度卑劣的存在，它劫掠加伦鬼屋附近的农场，并为天灾军团搜集尸体。",al={"蛆眼背景故事","蛆眼是谁","豺狼人蛆眼"}},{q="为什么被遗忘者要杀死它？",a="它因直接向巫妖王的天灾军团输送新鲜劫掠的尸体而被判死刑。对于被遗忘者的生存而言，剥夺天灾军团的兵源和资源至关重要。",al={"为什么要杀蛆眼","蛆眼的罪行","为什么悬赏蛆眼"}},{q="蛆眼通常出现在哪里？",a="它潜伏在加伦鬼屋的一间破旧废弃小屋里，那是一个位于布瑞尔北部的废弃农场。",al={"蛆眼位置","蛆眼在哪里","寻找蛆眼"}},{q="谁负责支付这笔悬赏？",a="位于布瑞尔中心的执行官塞加德负责接收击杀证明，并代表被遗忘者的军事权威发放赏金。",al={"谁接收蛆眼任务","蛆眼任务交接","布瑞尔悬赏发布者"}},{q="为什么执行官塞加德想要它的爪子？",a="按照经典的边境正义原则，获取像蛆眼的爪子这样独特的身体部位作为战利品，可以确保在发放赏金前拥有无可辩驳的死亡证明。",al={"为什么需要蛆眼的爪子","爪子证明","蛆眼的爪子"}},{q="豺狼人与天灾军团结盟了吗？",a="通常情况下，豺狼人的行为完全出于饥饿和贪婪，但蛆眼的行为则是直接向天灾军团交易或输送尸体，这使它成为一个极其危险的勾结者。",al={"豺狼人与天灾军团","豺狼人是否为巫妖王工作","天灾豺狼人"}}},fp="18,259,13.259.0,16.366.0,18.175.0,34.183.0,34.91.0,35.139.0,38.96.0,35.147.0"}
P.entries["quest:399"] = {n="童年的记忆",s="居住在暴风城Cathedral Square的城市建筑师巴隆斯·阿历克斯顿，正寻求帮助以找回一件他青年时代的传家宝。他家族位于西部荒野的旧宅已被焚毁并落入盗贼之手，只留下了深埋的记忆。",h="居住在暴风城Cathedral Square的城市建筑师巴隆斯·阿历克斯顿，正寻求帮助以找回一件他青年时代的传家宝。他家族位于西部荒野的旧宅已被焚毁并落入盗贼之手，只留下了深埋的记忆。",kw={"阿历克斯顿农场","巴隆斯·阿历克斯顿","cathedral square","平凡的开端","哨兵岭","简单的指南针","暴风城","西部荒野"},ang={["faction:Alliance"]="代表首都显贵深入西部荒野，凸显了暴风城安全的街道与附近未受保护的边境土地之间日益扩大的脱节感。",["race:Human"]="阿历克斯顿农场的命运折射出西部荒野自耕农的缓慢衰落，几代人类农夫都在暴风城的家门口被法外之徒剥夺了家园。"},sec={{t="建设者的根基",b="虽然巴隆斯·阿历克斯顿现在是暴风城的一位杰出建筑师，但他早年的生活却要朴素得多。早在设计石构建筑和城市楼宇之前，他曾是在西部荒野田间劳作的农家男孩。他从耕种乡间土地到为城市规划者提供建议的历程，在这个王国中是一次罕见的晋升，但他依然深深眷恋着塑造了他人生道路的这段平凡开端。"},{t="西部荒野的悲剧",b="像西部荒野各地的许多农庄一样，阿历克斯顿农场成为了席卷该地区的混乱局势的牺牲品。强盗和流浪者放火烧毁了房屋，迫使巴隆斯的父亲背井离乡。在纵火和占领的混乱中，家族的传家宝被遗弃了。巴隆斯请求勇敢的旅人前往哨兵岭以西那座废弃且被强盗盘踞的农场，找回他的第一个指南针——这是在房屋陷落前被藏起来的一件充满怀旧意义的纪念品。"}},faq={{q="谁是巴隆斯·阿历克斯顿？",a="巴隆斯·阿历克斯顿是暴风城的城市建筑师，位于Cathedral Square附近。尽管他在首都有着显赫的地位，但他是在西部荒野作为一个普通的农夫之子长大的，后来才离开乡村学习建筑工艺。",al={"巴隆斯·阿历克斯顿","谁是巴隆斯","城市建筑师"}},{q="阿历克斯顿农场在哪里？",a="这座农场坐落在西部荒野中部、哨兵岭的正西方。和该地区的许多房产一样，它已被焚毁，并被迪菲亚兄弟会势力的暴徒和流寇所占据。",al={"阿历克斯顿农场位置","农场在哪里","阿历克斯顿农场"}},{q="为什么这个指南针对比巴隆斯很重要？",a="这个指南针具有纯粹的纪念意义。这是巴隆斯童年在农场时拥有的第一个导航工具，象征着他从乡村劳工成长为建筑规划师的历程。虽然对他的当前职业来说毫无实际用途，但它却是他过去无法替代的遗物。",al={"为什么需要指南针","指南针是什么","简单的指南针"}},{q="是谁烧毁了阿历克斯顿农场？",a="农场被在西部荒野作恶的盗贼和不法之徒夷为平地。随着王国的军队兵力分散，无法保障偏远农庄的安全，强盗们夺取了土地并赶走了阿历克斯顿一家。",al={"谁烧毁了农场","为什么农场被毁","西部荒野农场被烧"}},{q="在农场的什么地方可以找到指南针？",a="指南针在全家逃离前被藏了起来，可以在主农舍烧焦的废墟中的一个小箱子里找到。",al={"指南针位置","指南针在哪里","被隐藏的指南针"}},{q="巴隆斯的父亲遭遇了什么？",a="巴隆斯的父亲在袭击中幸存并逃离了农场。虽然没能带着财产穿过烈火和强盗的包围，但他记得在逃离前将家族贵重的纪念品藏在了哪里。",al={"巴隆斯的父亲","阿历克斯顿的父亲","谁是巴隆斯的父亲"}}},fp="17,175,17.272.0,19.352.0,22.181.0,40.164.0,38.260.0,34.198.0,43.129.0,32.183.0"}
P.entries["quest:40"] = {n="鱼人的威胁",s="“鱼人威胁”是由闪金镇的雷米“两次”发布的短途送信任务。由于担心两栖捕食者侵入水道的消息，雷米派遣旅行者去通知闪金镇的治安官杜汉。这项差事凸显了暴风城当地驻军在应对新兴荒野威胁时，资源捉襟见肘的现状。",h="“鱼人威胁”是由闪金镇的雷米“两次”发布的短途送信任务。由于担心两栖捕食者侵入水道的消息，雷米派遣旅行者去通知闪金镇的治安官杜汉。这项差事凸显了暴风城当地驻军在应对新兴荒野威胁时，资源捉襟见肘的现状。",kw={"鱼人威胁","艾尔文森林","进一步的忧虑","闪金镇","治安官杜汉","鱼人","雷米“两次”"},ang={["faction:Alliance"]="这份简报展示了暴风城卫队在官僚和后勤上的压力，迫使该镇不得不依赖独立的冒险者来调查传言。",["race:Human"]="对于保卫家园的人类来说，东方水道的入侵触动了他们的心弦，因为熟悉的溪流变成了水生野兽危险的狩猎场。"},sec={{t="来自东方的请求",b="当雷米“两次”在闪金镇寻找商机时，一种奇怪的新威胁让他感到不安。鱼人开始顺流而上，爬向内陆浅滩，不仅干扰了渔业，还威胁到了无辜的旅行者。雷米确信当地卫兵忽视了一场正在酝酿的灾难，于是恳求路人将消息带回镇中心。"},{t="紧张的驻军",b="在闪金镇收到这份报告后，治安官杜汉对此表示怀疑。杜汉的任务是在王家军队兵力吃紧的情况下保卫王国，他此刻正忙于应付河爪豺狼人和迪菲亚强盗的暴力复苏。由于没有确凿的军事情报，治安官拒绝为了追查东方溪流中鱼人的流言而分散他那稀缺的兵力。"}},faq={{q="谁发布了“鱼人威胁”任务？",a="该任务由来自赤脊山的商人雷米“两次”提供，他在艾尔文森林的闪金镇可以找到。",al={"鱼人威胁 任务发布者","谁开启 鱼人威胁","雷米 任务"}},{q="为什么雷米“两次”担心鱼人？",a="雷米观察到鱼人顺着艾尔文森林东部的河流游了上来，驱赶了当地的鱼群，并袭击了水道沿线的旅行者。",al={"为什么雷米害怕","艾尔文森林 鱼人问题","鱼人威胁 剧情"}},{q="为什么治安官杜汉不立即派遣部队？",a="治安官杜汉认为平民的传言未经证实。由于闪金镇的驻军正忙于应对豺狼人袭击和有组织的强盗活动，在没有正式的军事侦察报告的情况下，他无法抽调士兵。",al={"为什么杜汉无视鱼人","治安官杜汉 回应","为什么不向东方派兵"}},{q="这个任务接下来会导向哪里？",a="治安官杜汉在这次对话后会引出“进一步的忧虑”任务，在动用王室资源向东进发之前，需要侦察兵提供可靠的证实。",al={"鱼人威胁 之后是什么","鱼人威胁 后续任务","进一步的忧虑 任务"}},{q="玩家在哪里交付“鱼人威胁”任务？",a="该任务是在闪金镇Lion's Pride Inn外交付给治安官杜汉的。",al={"鱼人威胁 在哪里交","鱼人威胁 交任务","杜汉 位置"}},{q="鱼人在艾尔文森林构成的更大威胁是什么？",a="虽然鱼人看起来原始且无规律，但它们对石碑湖和水晶湖等内陆湖泊的侵略性殖民，与豺狼人和强盗的袭击一起，威胁到了农村贸易和农业。",al={"艾尔文森林里的鱼人","艾尔文森林的鱼人危险吗"}}},fp="13,162,20.175.0,19.191.0,34.105.0,46.128.0,49.173.0,32.121.0,44.88.0,53.187.0"}
P.entries["quest:400"] = {n="贝尔丁的工具",s="“钢架的工具”是联盟早期的递送差事，将离开卡拉诺斯的旅行者引向附近的钢架补给站机械工作室。萨雷克·黑石会让你带上一箱全新的重型装备上路，送给贝尔丁·钢架。这位攻城坦克技师大师消耗扳手和棘轮的速度，让城镇供应商都望尘莫及。",h="“钢架的工具”是联盟早期的递送差事，将离开卡拉诺斯的旅行者引向附近的钢架补给站机械工作室。萨雷克·黑石会让你带上一箱全新的重型装备上路，送给贝尔丁·钢架。这位攻城坦克技师大师消耗扳手和棘轮的速度，让城镇供应商都望尘莫及。",kw={"弧光扳手","贝尔丁·钢架","丹莫罗","獠牙棘轮","卡拉诺斯","驾驶员迪恩·石轮","攻城坦克","钢架补给站","萨雷克·黑石"},ang={["profession:Engineering"]="贝尔丁的生意取决于弧光扳手和獠牙棘轮等精密工程仪器，这反映了机械战争对精制工具造成的巨大压力。",["race:Dwarf"]="矮人装甲战争完全依赖于像钢架补给站这样的野战维修站，以维持铁炉堡强大的攻城坦克在冰封隘口上滚滚前行。",["race:Gnome"]="贝尔丁消耗的弧光扳手和复杂的棘轮，是诺莫瑞根精密工程风格的标志，经过改造以适应粗犷的矮人装甲。"},sec={{t="一位对其装备要求严苛的大师",b="贝尔丁·钢架在整个丹莫罗都享有盛誉，是山里最顶尖的攻城坦克机械师，但他那狂暴的工作作风也让他的工作室付出了沉重的代价。据卡拉诺斯的萨雷克·黑石所说，钢架弄坏弧光扳手和工具的速度，几乎和当地补给箱运达的速度一样快。当卡拉诺斯装配好一批耐用的装备后，任何前往东北方向的人都会很快被招募去把这个沉重的包裹运到补给站。"},{t="保持引擎运转",b="到达钢架补给站后，旅行者会发现院子里烟雾缭绕、油污遍地，铁甲战争机器正在空转。贝尔丁积压了大量繁重的军事维修工作，其中包括对驾驶员迪恩·石轮的攻城坦克的关键维修。在你到达前几个小时，贝尔丁刚弄断了他最后一个獠牙棘轮，因此这份运送来的板条箱成了铁炉堡履带装甲部队的救命稻草。"}},faq={{q="我该把工具带到哪里？",a="沿着通往铁炉堡的道路向东北方向离开卡拉诺斯。贝尔丁·钢架在钢架补给站的露天工作区工作，周围停满了攻城坦克和车辆。",al={"钢架在哪里","去哪递送工具","贝尔丁·钢架位置"}},{q="贝尔丁·钢架是谁？",a="贝尔丁·钢架是一位著名的矮人机械师和攻城坦克专家，他在丹莫罗经营着钢架补给站。他负责为服役于铁炉堡机械化装甲部队的老兵飞行员提供维修、改装和保养服务。",al={"贝尔丁是谁","贝尔丁背景故事","攻城坦克技术"}},{q="为什么贝尔丁总是弄坏工具？",a="攻城坦克是巨大的、装甲厚重的战争机器，由超大型的铁制配件连接在一起。维修这些加固的船体需要极大的杠杆力和蛮力，这在紧急维修时经常会弄断精巧的弧光扳手和獠牙棘轮。",al={"为什么工具损坏","弧光扳手断裂","钢架工具"}},{q="贝尔丁在修理谁的攻城坦克？",a="当你递送工具时，贝尔丁正在努力完成对驾驶员迪恩·石轮的攻城坦克的必要维修，迪恩·石轮是驻扎在补给站的一名矮人老兵飞行员。",al={"驾驶员迪恩·石轮的坦克","什么引擎坏了","石轮的攻城坦克"}},{q="什么是钢架补给站？",a="钢架补给站是位于卡拉诺斯东北方向的一处露天机械集结地和工作室。它是老兵攻城坦克飞行员和坦克乘员测试、调试和修理装甲履带的聚集中心。",al={"什么是补给站","补给站用途","钢架工作室"}},{q="为什么萨雷克·黑石会找冒险者来运送工具？",a="萨雷克刚刚填好了钢架最新的工具订单，需要一位前往东北方向的可靠旅行者来运送这个沉重的板条箱，他为此提供了少量的金币，并引荐你认识聚集在路上的老兵飞行员。",al={"为什么要我去做","萨雷克递送原因"}}},fx={fd264fde={q="萨雷克·黑石为什么要送这些工具过去？",a="萨雷克负责卡拉诺斯的补给贸易，刚刚备齐了贝尔丁·钢架最近订购的装备。贝尔丁是丹莫罗最出色的攻城器械技师，但他粗糙的双手会以惊人的速度磨坏精密工具，比如奥术扳手。确保贝尔丁得到补给，就能让守护道路和山脉的矮人攻城器械保持正常运转。",al={"萨雷克·黑石的动机","为什么要送工具给钢架","为什么送钢架工具"}}},fp="20,172,26.333.0,27.277.0,26.155.0,25.231.0,36.210.0,36.114.0,27.188.0,59.201.0"}
P.entries["quest:401"] = {n="等待希拉完工",s="这段短暂的停顿，标志着希拉·沃宁迪正在破译隐居的隐士亚伯克隆比送来的那份晦涩字条。当他在夜色镇市政厅伏案疾书时，一种不祥的阴霾笼罩了整个房间，暗示着这位隐士的字里行间隐藏着远比预想中更为黑暗的内容。",h="这段短暂的停顿，标志着希拉·沃宁迪正在破译隐居的隐士亚伯克隆比送来的那份晦涩字条。当他在夜色镇市政厅伏案疾书时，一种不祥的阴霾笼罩了整个房间，暗示着这位隐士的字里行间隐藏着远比预想中更为黑暗的内容。",kw={"亚伯克隆比","夜色镇","暮色森林","艾尔罗·埃伯洛克","希拉·沃宁迪","翻译"},ang={["class:Mage"]="研习奥术文本和符文的法师们，在读到这些被揭开的内容时，会认出其中残留的诅咒信息的黑暗共鸣。",["faction:Alliance"]="夜色镇那脆弱的安全岌岌可危。"},sec={{t="翻译时刻",b="在收到隐士亚伯克隆比亲笔写下的神秘字条后，希拉·沃宁迪只需片刻法术便能将其破译。作为一名协助守夜人和城镇领导层的学者，他在执行任务时并未立即意识到这封信中潜藏着何种恐怖。"},{t="不祥的寒意",b="当希拉完成翻译的那一刻，空气中的气氛发生了明显的转变。一种突如其来的沉重感笼罩了房间，仿佛有一层厚厚的黑幕遮盖了这片区域。这封被破译的信件预示着夜色镇将面临巨大的危险，也揭示了亚伯克隆比那些看似无害的琐事，实际上是一场邪恶复仇计划的一部分。"}},faq={{q="希拉·沃宁迪是谁？",a="希拉·沃宁迪是一位居住在夜色镇市政厅的博学学者。他通过翻译从暮色森林阴暗荒野中送来的古代文献、奇怪文档和加密信息，来协助艾尔罗·埃伯洛克公爵和当地官员。",al={"希拉·沃宁迪","希拉是谁","希拉 暮色森林"}},{q="希拉正在翻译什么字条？",a="这封字条出自亚伯克隆比之手，他是隐居在暮色森林西缘小屋的一位隐士。在把这封字条交到希拉手中进行翻译之前，你曾为他跑过一连串的腿。",al={"字条是什么","亚伯克隆比的字条","亚伯克隆比写了什么"}},{q="为什么当他翻译完时空气会变得沉重？",a="这股突如其来的压抑寒意是末日将至的征兆：无论字条上写了什么，对夜色镇而言都是噩耗。当这份翻译件最终交到艾尔罗·埃伯洛克公爵手中时，其完整的含义便会水落石出。",al={"为什么空气变得沉重","笼罩大地的黑幕","暮色森林 阴暗空气"}},{q="接下来应该把翻译好的信件交给谁？",a="希拉完成翻译后，会指示你将这些令人不寒而栗的内容直接带到房间另一头的艾尔罗·埃伯洛克公爵手中，以便守夜人能为即将发生的事情做好准备。",al={"我该把翻译件带去哪里","接下来谁会收到字条","希拉之后的下一步"}},{q="亚伯克隆比真的是夜色镇的敌人吗？",a="亚伯克隆比表现得像是一位需要帮助才能生存的无害隐士。但随着希拉完成翻译，那股令人窒息的沉重感表明他的字条对夜色镇来说是不祥之兆，而当它传达给艾尔罗·埃伯洛克公爵时，其真实意图便会显露无遗。",al={"亚伯克隆比是邪恶的吗","隐士敌人","亚伯克隆比背景"}},{q="为什么必须等待他？",a="破译古代密码需要时间和专注。这段短暂的延迟让希拉有时间去解析隐士的笔迹和编码用语，从而为镇长整理出一份可读的译文。",al={"为什么要等希拉","我要等多久","希拉等待"}}},fp="24,191,23.228.0,16.248.1,22.228.0,31.186.1,45.169.2,46.164.0,46.240.2,32.164.0"}
P.entries["quest:4021"] = {n="人马无双！",s="在贫瘠之地的当地酋长被系统性地铲除后，寇卡半人马从凄凉之地发动了孤注一掷的报复。一支入侵部队直接向Regthar Deathgate位于十字路口西侧的前哨站进军，最终与督军克罗姆扎展开了激烈的对决。",h="在贫瘠之地的当地酋长被系统性地铲除后，寇卡半人马从凄凉之地发动了孤注一掷的报复。一支入侵部队直接向Regthar Deathgate位于十字路口西侧的前哨站进军，最终与督军克罗姆扎展开了激烈的对决。",kw={"贫瘠之地","碉堡","半人马","反击","十字路口","凄凉之地","寇卡","克罗姆扎","regthar deathgate","督军克罗姆扎"},ang={["class:Warrior"]="与前哨站的步兵并肩作战，抵御半人马入侵者无休止的冲锋，使这场防守战成为了一次对前线忍耐力和战场纪律的典型考验。",["faction:Horde"]="保卫碉堡巩固了部落在贫瘠之地中部的领土控制，确保了杜隆塔尔、莫高雷和十字路口之间重要的补给线安全。",["race:Tauren"]="击退克罗姆扎的入侵为平原带来了至关重要的安全，遏制了世世代代一直困扰牛头人部族的古老而凶残的半人马威胁。"},sec={{t="来自凄凉之地的复仇",b="针对贫瘠之地寇卡半人马的战役沉重打击了他们的部落首领。随着Barak Kodobane、Verog the Dervish和Hezrul Bloodmark的死亡，残余的半人马发现自己四分五裂，群龙无首。为了回应这种羞辱，消息传向了西边的群山，抵达了他们位于凄凉之地的祖居地。这些久经沙场的寇卡战士并没有四散到灌木丛中，而是集结起来，越过边境进入贫瘠之地，渴望着为针对初生的部落营地而流血复仇。"},{t="保卫碉堡",b="这支报复部队的目标是Regthar Deathgate把守的、位于十字路口西侧的加固部落碉堡。一波又一波的寇卡入侵者冲击着防线，与驻扎在此的部落步兵展开了激烈的交战。这支战团的先锋是督军克罗姆扎，一位威严的指挥官，他的军旗是入侵者的集结号。通过坚守防线、击杀克罗姆扎并扯下他的战旗，守军彻底摧毁了半人马在中部平原的威胁。"}},faq={{q="为什么寇卡人要攻击这个特定的前哨站？",a="Regthar Deathgate策划了针对贫瘠之地繁茂绿洲周围寇卡领袖的系统性暗杀。为了给阵亡的酋长复仇，半人马直接向他位于十字路口西侧的加固碉堡进军，旨在摧毁这个负责指挥的部落岗哨。",al={"为什么攻击regthar","为什么攻击贫瘠之地碉堡","半人马反击原因"}},{q="这些半人马援军从哪里来？",a="这支入侵战团穿过了来自凄凉之地的西部山口，那里是大多数半人马氏族居住的崎岖荒芜的核心地带。",al={"寇卡人从哪来","寇卡增援来源","凄凉之地半人马"}},{q="谁是督军克罗姆扎？",a="督军克罗姆扎是来自凄凉之地的寇卡报复战团的领袖。他亲自领导了针对Regthar碉堡的冲锋，在部落守军将他击倒之前，他一直挥舞着一面独特的战旗作战。",al={"谁是克罗姆扎","克罗姆扎背景故事","督军克罗姆扎"}},{q="Thrall会得知这场战斗吗？",a="是的。当呈上克罗姆扎军旗的残片时，Regthar Deathgate承诺将直接向奥格瑞玛的大酋长Thrall传达正式消息，以表彰对贫瘠之地的保卫战。",al={"thrall反击","thrall会听到这个消息吗","大酋长奖励"}},{q="这场战斗后，寇卡的存在会发生什么变化？",a="督军克罗姆扎的战败摧毁了寇卡在贫瘠之地中部最后的有组织进攻力量，保卫了十字路口周围的贸易路线，并使剩余的部落处于四分五裂、群龙无首的状态。",al={"寇卡人被击败了吗","贫瘠之地半人马的命运","寇卡任务线终结"}},{q="克罗姆扎军旗的碎片有什么用？",a="扯下一块克罗姆扎的作战军旗是这位督军死亡的无可辩驳的实物证据，象征着半人马入侵的彻底失败。",al={"克罗姆扎的军旗","军旗碎片任务物品","为什么要拿军旗"}}},fp="14,184,23.493.0,22.401.1,51.237.0,49.119.0,24.162.0,36.145.1,54.197.1,48.131.0"}
P.entries["quest:403"] = {n="戒备森严",s="“受到严密看管的雷酒木桶”位于卡拉诺斯雷酒酿制厂的酒窖中。它代表了著名的矮人酿酒家族的珍贵库存，日夜受到看管，以防止小偷和竞争对手干扰他们的工艺。",h="“受到严密看管的雷酒木桶”位于卡拉诺斯雷酒酿制厂的酒窖中。它代表了著名的矮人酿酒家族的珍贵库存，日夜受到看管，以防止小偷和竞争对手干扰他们的工艺。",kw={"丹莫罗","矮人酿酒","受到严密看管的雷酒木桶","加文·雷酒","卡拉诺斯","雷霆麦酒","雷酒酿制厂"},ang={["class:Rogue"]="溜进酒窖去偷一桶烈性矮人麦酒是经典的操作，但一个守在木桶旁的警惕矮人让这趟潜入变得棘手得多。",["race:Dwarf"]="每个矮人都明白，家族的秘制佳酿值得用生命去捍卫，这就是为什么加文在地窖里固执守卫显得如此理所应当。"},sec={{t="严密看管的酒窖",b="在丹莫罗寒冷的雪地里，没有什么比好麦酒受到更严密的保护了。在卡拉诺斯雷酒酿制厂的地板下，大桶大桶的烈酒在静谧中陈酿。这个家族对他们的库存十分谨慎，派遣了像加文·雷酒这样的警卫守在木桶旁，以确保没有任何一滴酒被篡改或偷走。"},{t="家族骄傲与竞争",b="矮人的酿酒业和锻造或采矿一样，是一门严肃的学科。雷酒家族对他们的独家配方引以为豪，尤其是那口感浓烈的雷霆麦酒。在丹莫罗周围徘徊的贪婪穴居怪，以及联盟内部激烈的酿酒竞争面前，加文警惕的守卫确保了家族的液体黄金在真正开桶之前分毫未动。"}},faq={{q="为什么我打不开这个木桶？",a="加文·雷酒就站在地下室里看守。只要他还在守卫，就不允许任何人打扰雷酒家族的木桶。",al={"无法打开木桶","为什么我不能动麦酒","加文守卫木桶"}},{q="加文·雷酒是谁？",a="加文是雷酒氏族的一员，驻扎在卡拉诺斯的酿制厂酒窖中。他的主要职责是看管家族最好的麦酒，并阻止任何想要偷窃或制造麻烦的人篡改库存。",al={"加文是谁","加文背景故事","地下室里的矮人"}},{q="这个木桶在哪里？",a="木桶位于卡拉诺斯镇的雷酒酿制厂下方的酒窖中，就在丹莫罗。",al={"受到看管的木桶在哪里","酒窖位置","雷酒地下室"}},{q="为什么雷酒家族要如此严密地看管他们的麦酒？",a="对矮人来说，酿酒是一门受人尊敬的技艺和家族遗产。面对竞争对手、狡猾的小偷，以及穴居怪和麻风侏儒等附近的威胁，珍贵的雷霆麦酒桶需要时刻受到保护。",al={"为什么要守卫麦酒","雷酒麦酒的重要性"}},{q="这是其他任务的一部分吗？",a="是的。它与马莱斯·麦酒的任务“苦涩的竞争”有关，你需要将一大桶热麦酒偷偷混入雷酒家族的雷霆麦酒桶中。",al={"雷酒任务线","这是什么任务的任务目标"}},{q="你能引开或支走加文吗？",a="可以。加文有严格的命令不得动用库存，但他承认自己很想尝尝雷霆麦酒。在任务“引开加文”中带给他一桶酒，就能将他的注意力从木桶上引开。",al={"如何通过加文的守卫","引开加文"}}},fp="26,118,20.177.0,26.273.0,29.134.0,26.202.0,29.90.0,51.194.0,30.144.0,32.158.0"}
P.entries["quest:404"] = {n="腐烂的爪子",s="“腐烂的任务”是布瑞尔的亡灵卫兵迪林格尔提供的一项早期军事任务。它指示冒险者击退那些在定居点以西的老桥附近徘徊的、盲目且充满攻击性的天灾军团。收集这些怪物被消灭的证据能够确保道路安全，并减轻提瑞斯法林地守军的压力。",h="“腐烂的任务”是布瑞尔的亡灵卫兵迪林格尔提供的一项早期军事任务。它指示冒险者击退那些在定居点以西的老桥附近徘徊的、盲目且充满攻击性的天灾军团。收集这些怪物被消灭的证据能够确保道路安全，并减轻提瑞斯法林地守军的压力。",kw={"腐烂的任务","布瑞尔","亡灵卫兵迪林格尔","腐烂的爪子","蹂躏过的尸体","腐烂的死者","天灾军团","提瑞斯法林地"},ang={["faction:Horde"]="确保布瑞尔的安全可以使初生的部落在东部王国建立起一个对抗天灾军团的稳固立足点。",["race:Undead"]="摧毁天灾军团对于被遗忘者来说是非常私人的事情，这是对曾经囚禁他们思想的无情力量的复仇。"},sec={{t="守卫桥梁",b="布瑞尔位于提瑞斯法林地东部的一个关键十字路口，任何敌人的靠近都直接威胁到被遗忘者的势力据点。盲目的天灾军团不断地从水道向西渗透，聚集在旧石桥残破的遗迹周围。如果没有定期的巡逻将它们击退，这些蹒跚的尸体很快就会堵塞布瑞尔和西部农场之间的交通。"},{t="对盲从者的怨恨",b="对于被遗忘者来说，在边境游荡的天灾军团不仅仅是一个战略上的麻烦，更是一种侮辱。每一个盲目的食尸鬼和腐烂的尸体都代表着Sylvanas Windrunner的追随者们曾经摆脱过的奴役与折磨。像迪林格尔这样的亡灵卫兵在摧毁他们曾经的俘虏者时会感到一种冷酷的满足，他们要求获取利爪作为残酷的证明，以确保这些盲目的死者被彻底安葬。"}},faq={{q="谁发布了这个任务？",a="这项任务由亡灵卫兵迪林格尔指派，他是驻扎在提瑞斯法林地布瑞尔西出口的一名被遗忘者卫兵军官。",al={"任务发布者","腐烂的任务接取地点","亡灵卫兵迪林格尔任务"}},{q="为什么亡灵卫兵迪林格尔想要腐烂的利爪？",a="利爪是死亡的恐怖证明。亡灵卫兵需要确认游荡的天灾军团已被彻底消灭，而不仅仅是被赶离了主路。",al={"为什么需要腐烂的利爪","利爪的原因"}},{q="哪里可以找到腐烂的死者？",a="它们在布瑞尔以西的荒草地和河岸上游荡，大量聚集在旧石桥周围。",al={"腐烂的死者位置","食尸鬼在哪里","旧桥位置"}},{q="为什么提瑞斯法林地会有天灾军团？",a="虽然被遗忘者从天灾军团手中夺回了洛丹伦首都及周围林地的控制权，但仍有天灾军团渗入提瑞斯法林地，并侵扰了布瑞尔以西、靠近旧桥的地区。",al={"为什么天灾军团在这里","提瑞斯法的天灾军团"}},{q="完成这项任务后会发生什么？",a="清理桥梁后会发现附近农场存在更深层的问题，促使亡灵卫兵迪林格尔派遣你前往更西边的地方去检查那些被占领的磨坊。",al={"后续任务","腐烂的任务之后是什么"}},{q="被遗忘者和天灾军团难道不是一回事吗？",a="不是。被遗忘者是拥有自由意志的亡灵，他们打破了巫妖王的心灵控制，并为保护自己的自主权而战。天灾军团则仍然是盲目的奴隶，受制于冰封王座的铁意志。",al={"被遗忘者和天灾军团的区别","他们难道不都是亡灵吗"}}},fp="13,186,18.316.0,29.376.0,21.117.0,48.101.0,33.118.0,41.186.0,40.107.1,52.201.0"}
P.entries["quest:4041"] = {n="视灵药剂",s="格雷甘·山酒会为你制作一瓶视灵药剂，但前提是你得带给他一株灵根草。格雷甘还声称自己对草药和炼金术有着非常深厚的了解。",h="格雷甘·山酒会为你制作一瓶视灵药剂，但前提是你得带给他一株灵根草。格雷甘还声称自己对草药和炼金术有着非常深厚的了解。",kw={"炼金术","灵根草","菲拉斯","格雷甘·山酒","米布隆","视灵药剂"},sec={{t="酿酒师需要的灵根草",b="一旦你把灵根草交到格雷甘·山酒手中，他就能为你制作视灵药剂。与此同时，格雷甘夸耀自己对草药和炼金术无所不知，还讲起了一个关于把午餐用的奶酪变成黄金的故事，甚至在你走开时还会问你要去哪儿。如果想知道哪里能找到灵根草，问格雷甘就对了。"},{t="当灵根草送达时",b="当你带着灵根草回来时，格雷甘会问候你说，你把老米布隆给耍了。"}},faq={{q="谁酿造视灵药剂？",a="格雷甘·山酒，只要你带给他一株灵根草。",al={"谁提供视灵药剂","在哪里获得视灵药剂"}},{q="制作这种药剂需要什么材料？",a="一株灵根草。格雷甘可以告诉你去哪里找。",al={"视灵药剂的材料","格雷甘需要什么"}},{q="格雷甘·山酒吹嘘些什么？",a="格雷甘吹嘘自己对草药和炼金术有很深的造诣，并讲起了一个把午餐奶酪变成黄金的故事。",al={"格雷甘·山酒的吹嘘","格雷甘的草药和炼金术"}}},fp="17,166,25.348.0,24.101.1,28.45.0,47.50.0,40.132.0"}
P.entries["quest:405"] = {n="流浪的巫妖",s="在你于布瑞尔对抗天灾残党和腐皮豺狼人的服役结束后，执政官塞弗伦指引你前往南方的幽暗城。比索·埃斯沙德，Magic Quarter里的一位杰出大法师，需要一位能干的特工来执行一项关于流浪巫妖的敏感任务。",h="在你于布瑞尔对抗天灾残党和腐皮豺狼人的服役结束后，执政官塞弗伦指引你前往南方的幽暗城。比索·埃斯沙德，Magic Quarter里的一位杰出大法师，需要一位能干的特工来执行一项关于流浪巫妖的敏感任务。",kw={"比索·埃斯沙德","布瑞尔","magic quarter","执政官塞弗伦","流浪的巫妖","塞弗伦的命令","提瑞斯法林地","幽暗城"},ang={["class:Mage"]="向比索·埃斯沙德报到，可以让你面见被遗忘者中最强大的奥术和冰霜大师之一。",["faction:Horde"]="获得未结盟或强大的死灵资产，能巩固被遗忘者在洛丹伦废墟的险境，以对抗共同的敌人。",["race:Undead"]="接受来自首都的第一批直接命令，标志着你从布瑞尔的当地民兵工作转变为执行幽暗城更宏大的地缘政治意志。"},sec={{t="首都的召唤",b="既然你已经在布瑞尔的废墟城镇中证明了自己的能力，执政官塞弗伦认为你有资格参与更高层级的被遗忘者事务。比索·埃斯沙德，一位居住在幽暗城Magic Quarter的强大法师，要求派遣一名在与天灾军团的战斗中经受过考验的代理人。塞弗伦交给你正式的命令，派遣你前往洛丹伦废墟之下，进入被遗忘者首都的地下长廊。"},{t="流浪的巫妖",b="虽然塞弗伦承认并不了解具体细节，但他透露这项任务的核心是寻找并招募一个流浪巫妖。巫妖是天灾军团所制造的最致命的施法者之一，因此任何接触都充满了危险。当你把命令送到比索的奥术圣所时，这位冷酷的法师开门见山，急切地想要评估布瑞尔的执政官是否派遣了足够强大的人来处理如此危险的猎物。"}},faq={{q="谁派遣我执行这项任务？",a="执政官塞弗伦，那位管理提瑞斯法林地布瑞尔镇的被遗忘者官员，派遣你携带书面命令直接去找比索·埃斯沙德。",al={"谁发布了流浪的巫妖任务","流浪的巫妖任务发布者","塞弗伦的命令"}},{q="我在哪里能找到比索·埃斯沙德？",a="比索·埃斯沙德居住在幽暗城的Magic Quarter，通常可以在被奥术能量环绕的中央高台上找到他。",al={"比索在哪里","比索·埃斯沙德的位置","如何找到比索"}},{q="命令中提到的任务是什么？",a="比索打算招募一个流浪的、脱离控制的巫妖，但他首先需要一个有能力追踪该巫妖身份和下落线索的代理人。",al={"巫妖任务的内容","那个流浪巫妖是谁","流浪的巫妖任务目的"}},{q="为什么比索需要一位在对抗天灾军团中经受过考验的代理人？",a="巫妖是最初效忠于巫妖王的死灵冰霜和死亡魔法的大师。处理一个拥有自由意志或孤立的巫妖，需要一个已经证明有能力在天灾军团的亡灵威胁下存活下来的人。",al={"为什么要对抗天灾的经验","为什么比索需要我"}},{q="在接到这个任务之前必须完成什么前置条件？",a="你必须完成执政官塞弗伦之前的任务“掘墓者”，清理加伦鬼屋中的腐皮豺狼人和掘墓贼。",al={"流浪的巫妖前置任务","如何解锁流浪的巫妖"}},{q="向比索报到之后会发生什么？",a="在交出塞弗伦的命令后，比索会提供任务“巫妖的身份”，指引你去调查文物和线索，以揭开这个神秘实体生前是谁。",al={"流浪的巫妖后续任务","流浪的巫妖后续"}}},fp="17,206,22.339.0,14.398.0,26.132.0,32.124.0,44.135.0,60.195.0,64.168.0,37.173.0"}
P.entries["quest:4062"] = {n="机器的崛起",s="塞朵拉·穆瓦丹尼在大地精华碎片上发现了首字母缩写和等级标记，而你在燃烧平原摧毁的机器上印着IV级。塞朵拉让你带着一份碎片样本去寻找鲁特维尔·沃拉图斯，他是元素科学方面的学者，就在东边的一个营地里。",h="塞朵拉·穆瓦丹尼在大地精华碎片上发现了首字母缩写和等级标记，而你在燃烧平原摧毁的机器上印着IV级。塞朵拉让你带着一份碎片样本去寻找鲁特维尔·沃拉图斯，他是元素科学方面的学者，就在东边的一个营地里。",kw={"荒芜之地","燃烧平原","元素碎片样本","g.l.a.","鲁特维尔·沃拉图斯","机器的崛起","塞朵拉·穆瓦丹尼"},sec={{t="碎片上的标记",b="这些碎片带有首字母缩写G.L.A.，下方还有等级标记。你在燃烧平原摧毁的机器上印着IV级，塞朵拉推测这只是一个较低的等级。塞朵拉希望你带上一块碎片样本给鲁特维尔·沃拉图斯，他在元素科学领域的学者中颇有名望。鲁特维尔驻扎在东边的一个营地里，塞朵拉希望他能协助这次调查。"},{t="鲁特维尔的发现",b="当你把碎片展示给鲁特维尔时，他的脸色变得苍白。他认识这些标记。"}},faq={{q="是谁让你去找鲁特维尔·沃拉图斯的？",a="是塞朵拉·穆瓦丹尼，她想让鲁特维尔检查一下从燃烧平原摧毁的机器上获得的碎片样本。",al={"谁给予此任务","任务发布者","塞朵拉·穆瓦丹尼"}},{q="鲁特维尔·沃拉图斯在哪里？",a="在东边的一个营地里。",al={"鲁特维尔在哪里","鲁特维尔的位置","鲁特维尔·沃拉图斯的营地"}},{q="元素碎片上有什么标记？",a="碎片上带有首字母缩写G.L.A.，下方有等级标记。被摧毁的机器是IV级的。",al={"碎片上的缩写","g.l.a.代表什么","iv级"}},{q="为什么塞朵拉想让鲁特维尔检查这些碎片？",a="鲁特维尔在元素科学领域的学者中颇有名望，塞朵拉希望他能协助这次调查。",al={"为什么找鲁特维尔","为什么咨询鲁特维尔"}}},fp="24,279,19.378.0,16.78.1,33.126.0,33.22.0,42.103.0,51.104.0"}
P.entries["quest:407"] = {n="悲伤之地",s="“悲伤田野”标志着药剂师乔汉将从索利丹农场收集的普通南瓜武器化实验的终结。在给作物注入了他最新的炼金药剂后，乔汉派遣你将这颗斑纹南瓜喂给一名困在布瑞尔的血色十字军俘虏。",h="“悲伤田野”标志着药剂师乔汉将从索利丹农场收集的普通南瓜武器化实验的终结。在给作物注入了他最新的炼金药剂后，乔汉派遣你将这颗斑纹南瓜喂给一名困在布瑞尔的血色十字军俘虏。",kw={"药剂师乔汉","布瑞尔","血色十字军俘虏","悲伤田野","恐惧之末旅店","斑纹南瓜","皇家药剂师协会","提瑞斯法林地"},ang={["faction:Horde"]="皇家药剂师协会的生物化学研究经常让被遗忘者的新盟友感到不安，但它对于确保提瑞斯法林地为部落所有仍然至关重要。",["race:Undead"]="对于被遗忘者来说，这项实验展示了在这种被南方的狂热人类和北方的巫妖王大军包围的环境下生存所必需的残酷实用主义。"},sec={{t="天才的武器",b="皇家药剂师协会的药剂师乔汉认为，被遗忘者必须利用一切战术优势来抵御来自北方的天灾军团和来自南方的各种人类入侵。协会并未仅仅依赖于原始的刀剑或黑暗魔法，而是试图利用这片土地上的普通农产品。通过毒化从索利丹农场的人类农夫那里搜刮来的南瓜，乔汉打算证明，即使是常见的农产品，在黑暗女王的意志下也能被改造成杀人工具。"},{t="地窖测试",b="测试对象正在布瑞尔的恐惧之末旅店地板下等待着。这名血色十字军俘虏被铁链锁住且处于饥饿状态，他以典型的狂热蔑视迎接被遗忘者的造访，并祈求圣光来净化亡灵。然而，饥饿很快就击垮了这名十字军的意志。俘虏将那颗带有毒性的斑纹南瓜误认为是救命食物，便狼吞虎咽地吃下，结果迅速变异成了一只腐烂的食尸鬼，随后倒在尘土中一命呜呼。"}},faq={{q="为什么药剂师乔汉要用南瓜作为他的毒药容器？",a="乔汉想证明平凡的作物可以被转变成针对活人的隐蔽且有效的武器。通过将附近人类农场的日常农产品与炼金药剂混合，皇家药剂师协会正在测试利用敌人基本生存需求来进行攻击的投放方式。",al={"为什么选择南瓜","为什么毒化南瓜","斑纹南瓜背景故事"}},{q="旅店地窖里的囚犯是谁？",a="这个囚犯是一名血色十字军俘虏，是被遗忘者军队在提瑞斯法林地抓获的血色十字军狂热分子。由于饥饿和与世隔绝，这名狂热者一直坚守着宗教狂热，直到接触到食物。",al={"血色十字军俘虏是谁","恐惧之末里的狂热者","布瑞尔地窖囚犯"}},{q="血色十字军在吃下南瓜后发生了什么？",a="乔汉的最新配方几乎立刻就在这名饥饿的狂热者身上起效了，这为药剂师协会提供了他们所需要的残酷证据。",al={"狂热者发生了什么","狂热者变异","狂热者是否变成了食尸鬼"}},{q="恐惧之末旅店的地窖在哪里？",a="地窖位于布瑞尔恐惧之末旅店的正下方。前台柜台后面有一条坡道通往关押区域，被遗忘者的卫兵就是把囚犯关在那里的。",al={"如何找到地窖","狂热者的位置","恐惧之末地窖入口"}},{q="皇家药剂师协会在这里试图达成什么目标？",a="该协会在Sylvanas Windrunner的领导下工作，旨在发明能够消灭天灾军团以及像血色十字军这样的人类威胁的生物和炼金药剂。在布瑞尔的囚犯身上进行的小规模实验，正是这些药剂的试运行。",al={"药剂师协会的目标","为什么要测试瘟疫","皇家药剂师协会提瑞斯法"}},{q="为什么血色十字军活跃在提瑞斯法林地？",a="血色十字军认为所有的亡灵都是必须被消灭的憎恶，他们不区分无脑的天灾军团和拥有自由意志的被遗忘者。他们在洛丹伦王国的旧址上维持着营地和驻军，试图通过圣火收复这片土地。",al={"提瑞斯法血色十字军","血色十字军为什么在这里","布瑞尔的十字军势力"}}},fp="15,193,21.415.0,15.384.1,56.217.0,41.213.0,60.130.1,40.153.0,60.240.0,53.223.0"}
P.entries["quest:408"] = {n="家族墓穴",s="“家族墓穴”是一项部落任务，要求玩家进入阿加曼德家族墓穴对抗天灾军团。在布瑞尔执政官塞弗伦的命令下，冒险者必须消灭复活的阿加曼德祖先，并击杀天灾军团的骷髅指挥官达戈尔队长。",h="“家族墓穴”是一项部落任务，要求玩家进入阿加曼德家族墓穴对抗天灾军团。在布瑞尔执政官塞弗伦的命令下，冒险者必须消灭复活的阿加曼德祖先，并击杀天灾军团的骷髅指挥官达戈尔队长。",kw={"阿加曼德家族墓穴","阿加曼德磨坊","布瑞尔","达戈尔队长","执政官塞弗伦","腐烂的祖先","天灾军团","家族墓穴","提瑞斯法林地","哀嚎的祖先"},ang={["faction:Horde"]="巩固提瑞斯法林地对于稳固部落在东部王国的立足点至关重要，这将消除威胁其北部据点的直接隐患。",["race:Undead"]="对于被遗忘者来说，达戈尔队长代表了他们誓死摆脱的一切：被奴役于巫妖王的意志。消灭那些复活的祖先既是一种自卫行为，也是为了打破天灾军团对其家园控制的严峻职责。"},sec={{t="提瑞斯法的一曲狐步舞",b="尽管被遗忘者在提瑞斯法林地建立起了脆弱的统治，但巫妖王天灾军团的残党仍然深深扎根于这片乡野之中。阿加曼德磨坊曾是洛丹伦繁荣的面粉生产中心，如今却已变成了一座危险的天灾军团据点。布瑞尔的执政官塞弗伦怀着沉重的心情注视着这里的军事集结，他深知每一寸被无脑亡灵占据的土地，都在侵蚀着被遗忘者的独立根基。"},{t="亵渎墓地",b="当地天灾军团占领的核心是阿加曼德家族墓穴，骷髅指挥官达戈尔队长在那里设立了总部。利用黑暗通灵术，达戈尔将几代阿加曼德家族的死者从安息中强行唤醒，并将其扭曲为腐烂的祖先和哀嚎的祖先，以壮大自己的军队。塞弗伦派遣被遗忘者特工去清理墓穴，让不安的亡者重归安息，并割下达戈尔的头颅，以此瓦解天灾军团在提瑞斯法北部的指挥体系。"}},faq={{q="达戈尔队长是谁？",a="达戈尔队长是一名驻扎在阿加曼德家族墓穴内的骷髅天灾军官。他以这座陵墓为基地，指挥着当地的天灾部队，并利用通灵术复活阿加曼德家族的祖先，向被遗忘者发起进攻。",al={"达戈尔队长","谁是达戈尔","达戈尔背景故事"}},{q="为什么执政官塞弗伦关心阿加曼德磨坊？",a="阿加曼德磨坊是天灾军团的一个主要据点，离布瑞尔和幽暗城近在咫尺，威胁巨大。如果放任不管，达戈尔队长麾下不断增加的复活祖先部队可能会对新解放的被遗忘者定居点发动攻势。",al={"布瑞尔为何关注","塞弗伦与阿加曼德","阿加曼德的重要性"}},{q="什么是哀嚎的祖先和腐烂的祖先？",a="他们是富裕的阿加曼德家族的已故先辈。他们的遗体和灵魂本应在祖传的墓地中安息，却被达戈尔队长用黑暗法术腐化并束缚，成为了听命于天灾军团的傀儡。",al={"哀嚎的祖先","腐烂的祖先","阿加曼德祖先"}},{q="击杀达戈尔后会发生什么？",a="将达戈尔队长的颅骨带回给执政官塞弗伦，可以打破天灾军团在磨坊的集中指挥。塞弗伦将这场胜利誉为被遗忘者的一次关键打击，也是将巫妖王的影响力彻底从洛丹伦清除的早期步骤。",al={"墓穴的后续","阿加曼德任务线结局","达戈尔被击败"}}},fp="16,160,21.326.0,17.368.0,22.181.0,56.167.0,42.161.0,36.245.1"}
P.entries["quest:409"] = {n="证明忠诚",s="“证明忠诚”是冈瑟尔·阿坎努斯设置的一项关键考验，旨在判断你究竟是真正服务于拥有自由意志的被遗忘者，还是效忠于巫妖王。为了赢得这位独居死灵法师的信任，你被派遣去召唤并消灭潜伏在他岛屿附近的危险天灾军团特工莉莉丝·内法拉。",h="“证明忠诚”是冈瑟尔·阿坎努斯设置的一项关键考验，旨在判断你究竟是真正服务于拥有自由意志的被遗忘者，还是效忠于巫妖王。为了赢得这位独居死灵法师的信任，你被派遣去召唤并消灭潜伏在他岛屿附近的危险天灾军团特工莉莉丝·内法拉。",kw={"比索·埃斯沙德","澈水湖","诱灵蜡烛","冈瑟尔·阿坎努斯","莉莉丝·内法拉","证明忠诚","天灾祭坛","提瑞斯法林地"},ang={["class:Mage"]="比索·埃斯沙德和冈瑟尔·阿坎努斯代表了洛丹伦重要的奥术和死灵法术天赋；展现你的能力能赢得这位强大的施法者同僚的职业尊重。",["race:Undead"]="对于被遗忘者来说，打破冈瑟尔的孤立状态有着特殊的意义；这向一位亡灵同胞证明，他们之中没有任何人必须独自面对天灾军团或生者的愤怒。"},sec={{t="隐士的猜疑",b="自从复生为亡灵以来，冈瑟尔·阿坎努斯就一直独自隐居在澈水湖的一座岛屿上，极其执着地维护着自己的独立。尽管比索·埃斯沙德在冈瑟尔的法术书上施加的魔法附魔证实了这位使者并未带有天灾军团的污秽气息，但对于这位多疑的隐士来说，言语和咒语还远远不够。为了赢得他的信任，外来者必须通过果断的暴力行动，表现出对巫妖王爪牙的积极敌意。"},{t="击杀莉莉丝·内法拉",b="在冈瑟尔避难所的南边，矗立着一座染血的祭坛，那是莉莉丝·内法拉所使用的，她是活跃在提瑞斯法林地的可怕的天灾军团特工。利用特制的诱灵蜡烛，请愿者可以唤醒潜藏在阴影中的莉莉丝，与她进行正面对决。击杀这名特工，粉碎了冈瑟尔长期以来坚持的信念——即他是唯一一个能够挣脱巫妖王铁腕控制的亡灵生物。"}},faq={{q="为什么冈瑟尔·阿坎努斯需要证明？",a="冈瑟尔通过不信任任何人，才得以作为独立的亡灵生存下来。在提瑞斯法林地，他被天灾军团、血色十字军以及其他威胁所包围，他认为任何亡灵访客都可能是巫妖王派来的特工，目的是将他征服，除非这些访客能流下天灾军团的鲜血。",al={"冈瑟尔为何怀疑我","冈瑟尔的信任"}},{q="莉莉丝·内法拉是谁？",a="莉莉丝·内法拉是一位强大的天灾军团特工，活跃在澈水湖南岸。她在靠近冈瑟尔岛屿的一座古老血腥祭坛附近活动，为巫妖王在林地的势力效劳。",al={"谁是莉莉丝","莉莉丝·内法拉背景故事"}},{q="什么是诱灵蜡烛？",a="诱灵蜡烛是一件从冈瑟尔岛上的板条箱中获取的仪式物品。将其放置在血腥祭坛上并点燃，就能将莉莉丝·内法拉从她的长眠之地召唤出来，从而与她展开战斗。",al={"诱灵蜡烛","如何召唤莉莉丝"}},{q="莉莉丝被击败后，冈瑟尔意识到什么？",a="击败莉莉丝迫使冈瑟尔不得不接受一个惊人的事实：他并非独一无二。直到这次考验之前，他一直真诚地认为自己是洛丹伦唯一一个摆脱了巫妖王精神控制的亡灵。",al={"冈瑟尔的反应","冈瑟尔的顿悟"}},{q="这场对决发生在哪里？",a="仪式发生在澈水湖中冈瑟尔岛南岸外湖岸边的一座祭坛上，位于提瑞斯法林地东部。",al={"祭坛在哪里","莉莉丝的位置"}},{q="证明忠诚后会发生什么？",a="随着冈瑟尔的疑虑消除，他终于同意听取幽暗城使者的意见，并重新考虑他孤独的流亡生活，这为他正式加入希尔瓦娜斯女士的被遗忘者阵营奠定了基础。",al={"证明忠诚后做什么","莉莉丝死后"}}},fp="18,189,22.405.0,29.362.1,36.237.0,22.169.0,32.191.0,60.178.1,41.155.0,43.187.1"}
P.entries["quest:410"] = {n="潜伏的阴影",s="“沉睡的阴影”是一场在提瑞斯法林地的澈水湖畔的冈瑟尔的居所中进行的黑暗仪式。通过将一支神秘的蜡烛放置在古老且浸满鲜血的桌子上，旅行者可以召唤出天灾军团的走狗莉莉丝·内法拉，将其击败即可向冈瑟尔·阿坎努斯证明来访者是巫妖王的敌人。",h="“沉睡的阴影”是一场在提瑞斯法林地的澈水湖畔的冈瑟尔的居所中进行的黑暗仪式。通过将一支神秘的蜡烛放置在古老且浸满鲜血的桌子上，旅行者可以召唤出天灾军团的走狗莉莉丝·内法拉，将其击败即可向冈瑟尔·阿坎努斯证明来访者是巫妖王...",kw={"血腥桌子","诱灵蜡烛","沉睡的阴影","被遗忘者仪式","莉莉丝·内法拉","证明忠诚","提瑞斯法林地"},ang={["class:Priest"]="暗影牧师们将蜡烛的呼唤视为一种暗影联结的演练，将一个不安的游荡灵魂拉回物理位面进行冲突。",["class:Warlock"]="术士们理解将灵魂束缚在血腥祭坛上的共鸣力量，这使得该仪式成为操纵生死边界的常见练习。",["race:Undead"]="对于被遗忘者来说，在提瑞斯法中心地带的血腥祭坛上进行仪式，时刻提醒着他们，他们的新存在是建立在死亡、黑暗魔法以及对黑暗女王坚定不移的忠诚之上的。"},sec={{t="令人毛骨悚然的祭坛",b="在澈水湖的冈瑟尔的居所岛上，伫立着一张破旧且布满血迹的餐桌。它绝非寻常的废弃家具，而是某种邪恶召唤的物质焦点。桌面上沾满了干涸的血迹，在阴影中被遗弃，成为了一个充斥着死亡与黑暗魔法的临时祭坛。"},{t="诱灵蜡烛",b="若要唤醒此地潜伏的任何事物，必须将诱灵蜡烛放置在这满是血迹的表面并点燃火焰。蜡烛的光芒穿透了提瑞斯法林地的阴霾，将莉莉丝·内法拉的灵魂从死亡的帷幕中召唤出来。这是一种刻意的亡灵扰动行为，旨在考验那些试图证明自身实力与忠诚的人。"}},faq={{q="在桌子上点燃蜡烛的目的是什么？",a="在破旧且布满血迹的桌子上点燃诱灵蜡烛，会召唤出莉莉丝·内法拉的阴影，这是一个必须被消灭的危险幽灵。",al={"为何点燃蜡烛","沉睡的阴影任务目标","桌子仪式"}},{q="这场仪式会召唤出谁？",a="仪式会引出莉莉丝·内法拉，这是一个亡灵生物和天灾军团的走狗，游荡在提瑞斯法林地澈水湖的冈瑟尔的居所。",al={"召唤对象","沉睡的阴影幽灵","阴影是谁"}},{q="这与证明对被遗忘者的忠诚有什么关系？",a="召唤并消灭莉莉丝·内法拉是“证明忠诚”任务中的考验：隐居的冈瑟尔·阿坎努斯要求以此作为证明，确认你确实是天灾军团的敌人，而非巫妖王的仆从。",al={"证明忠诚的关联","为何击杀莉莉丝","被遗忘者考验"}},{q="这场仪式在哪里进行？",a="仪式在冈瑟尔的居所进行，即冈瑟尔·阿坎努斯位于提瑞斯法林地澈水湖中的岛屿，地点就在岛屿南岸附近那张沾满干涸血迹的破旧餐桌旁。",al={"桌子位置","桌子在哪里","莉莉丝的餐桌"}},{q="任何人都可以点燃蜡烛吗？",a="任何持有诱灵蜡烛并正在接受被遗忘者忠诚考验的人，都可以在祭坛上点燃火焰。",al={"谁可以进行仪式","职业要求","蜡烛仪式"}},{q="这张桌子本身就闹鬼吗？",a="这张桌子是天灾军团走狗莉莉丝·内法拉所使用的古老血腥祭坛。在上面点燃诱灵蜡烛是唤醒她沉睡的关键。",al={"桌子有魔法吗","为何使用血腥桌子"}}},fp="17,231,16.270.0,23.242.1,56.121.0,31.138.0,59.145.0,34.201.0,28.113.0,31.139.0"}
P.entries["quest:411"] = {n="巫妖归顺",s="“浪子巫妖回归”标志着将冈瑟尔·阿坎努斯招募进被遗忘者这一任务的终结。在证明了你的意图并取回了他的魔典后，你带着一颗奥术共鸣宝石回到了幽暗城的比索·埃斯沙德处。",h="“浪子巫妖回归”标志着将冈瑟尔·阿坎努斯招募进被遗忘者这一任务的终结。在证明了你的意图并取回了他的魔典后，你带着一颗奥术共鸣宝石回到了幽暗城的比索·埃斯沙德处。",kw={"阿坎努斯","比索","澈水湖","冈瑟尔","埃斯沙德","巫妖","虚空宝石","浪子","幽暗城"},ang={["class:Mage"]="目睹比索与冈瑟尔的共鸣，展示了达拉然传统法术与幽暗城魔法区所修习的黑暗死灵法术之间的完美融合。",["faction:Horde"]="招募像冈瑟尔这样拥有大师级水平且独立的死灵法师，极大地巩固了部落在东部王国的魔法地位。",["race:Undead"]="冈瑟尔在没有女妖之王干预的情况下获得解放，有力地证明了洛丹伦的逝者所能展现出的纯粹意志力。"},sec={{t="难得的重逢",b="冈瑟尔·阿坎努斯在澈水湖的一座岛屿上独自隐居了多年，他凭借坚强的意志摆脱了巫妖王的控制，却完全不知道希尔瓦娜斯·风行者已经解放了洛丹伦。冈瑟尔对外界心怀苦涩与疑虑，直到一名冒险者带回了他的法术书并证明了他们对天灾军团的敌意，他才打消了对幽暗城使者的戒心。在确信来者并非敌人后，冈瑟尔将一颗虚空宝石交给了对方，以便与他曾经的同事建立联系。"},{t="魔法区的共鸣",b="回到幽暗城的魔法区后，携带者将虚空宝石交给了比索·埃斯沙德。比索引导宝石的力量，在圣所内直接召唤出了冈瑟尔的灵体幻象。通过这种魔法共鸣，这位巫妖正式同意与被遗忘者的事业结盟。获得像冈瑟尔这样拥有独立掌控力的死灵法师，对于黑暗女王刚刚建立的王国来说是一次巨大的成功，这加强了他们抵御天灾军团和生者的魔法防御。"}},faq={{q="谁是冈瑟尔·阿坎努斯？",a="冈瑟尔·阿坎努斯是一位极其强大的死灵法师，他凭借自己的意志摆脱了巫妖王的精神控制。他曾在澈水湖的一座岛屿上隐居，并认定所有其他亡灵都是没有思想的奴隶，直到冒险者向他证明了事实并非如此。",al={"冈瑟尔·阿坎努斯背景","浪子巫妖是谁","冈瑟尔幽暗城"}},{q="谁是比索·埃斯沙德？",a="比索·埃斯沙德是一位居住在幽暗城魔法区的高级法师兼学者。他是冈瑟尔·阿坎努斯的老同事，并负责协调寻找并将其招募进被遗忘者的工作。",al={"比索背景","比索是谁","埃斯沙德幽暗城"}},{q="虚空宝石有什么作用？",a="虚空宝石是冈瑟尔·阿坎努斯提供的一件附魔神器。当比索·埃斯沙德将奥术能量注入其中时，它会显现出冈瑟尔的幽灵投影，使两位施法者能够跨越遥远的距离进行交谈。",al={"什么是虚空宝石","冈瑟尔宝石"}},{q="为什么冈瑟尔同意加入被遗忘者？",a="冈瑟尔多年来一直担心自己是洛丹伦唯一有自由意志的亡灵。在确信希尔瓦娜斯的被遗忘者确实摆脱了天灾军团的控制，并且正在积极对抗巫妖王后，他自愿宣誓效忠，并与他曾经的同僚重新建立了联系。",al={"为何加入被遗忘者","冈瑟尔效忠"}},{q="为什么任务称冈瑟尔为“巫妖”？",a="冈瑟尔看起来和普通的被遗忘者没什么两样，而不像天灾军团那种漂浮在空中、周身环绕冰霜的巫妖，但被遗忘者仍然这样称呼他。他生前曾是肯瑞托的学生和熟练的死灵法师，在第三次战争期间死于瘟疫并被复活，后来凭借自身力量摆脱了巫妖王的控制。",al={"冈瑟尔是真正的巫妖吗","冈瑟尔巫妖形态"}},{q="当你上交虚空宝石时会发生什么？",a="完成交付后，比索会激活宝石，在魔法区召唤出冈瑟尔的幻象。投影向比索移动，开启了他们期待已久的重聚，随后便消失了。",al={"虚空宝石上交事件","比索处发生了什么"}}},fp="25,136,21.463.0,30.412.1,23.252.0,23.194.0,28.218.0,44.226.1,41.267.0,45.188.1"}
P.entries["quest:412"] = {n="自动净化装置",s="“重组计划”是拉兹·滑链在卡拉诺斯组织的一项大胆的工程创举。为了应对诺莫瑞根的悲剧，拉兹和奥齐·电环试图利用一种被称为“重组器”的实验性装置，来逆转他们那些患病的同胞变成麻风侏儒的可怕变异。",h="“重组计划”是拉兹·滑链在卡拉诺斯组织的一项大胆的工程创举。为了应对诺莫瑞根的悲剧，拉兹和奥齐·电环试图利用一种被称为“重组器”的实验性装置，来逆转他们那些患病的同胞变成麻风侏儒的可怕变异。",kw={"丹莫罗","诺莫瑞根","多档齿轮","卡拉诺斯","麻风侏儒","奥齐·电环","拉兹·滑链","重组器","自适应齿轮"},ang={["profession:Engineering"]="工程师们会欣赏拉兹非正统的修补方式，其特点是复杂的重新稳定齿轮、曲柄棘轮和用于操纵生物物理辐射的粘稠电胶凝胶。",["race:Gnome"]="对于侏儒来说，这项任务代表着一种绝望而真挚的希望，旨在拯救那些在首都陷落期间被扭曲成暴力空壳的失踪家人和朋友。"},sec={{t="灾难的补救措施",b="当辐射淹没诺莫瑞根以清除穴居人威胁时，它未能消灭入侵者，反而使大多数侏儒居民扭曲变成了疯狂、病态的麻风侏儒。发明家拉兹·滑链拒绝接受这种悲剧性的变异是永久性的，他与奥齐·电环合作开发了一种技术性的治疗手段：重组器。他们大胆的目标不仅于此，更在于恢复变异同胞的健康和理智。"},{t="从受害者身上搜刮",b="制造一个精密的样机需要精确的组件，即重新稳定齿轮和陀螺机械装置。讽刺的是，这些必不可少的部件直接从诺莫瑞根封闭大门外徘徊的敌对麻风侏儒身上回收。通过从他们被腐蚀的兄弟姐妹身上采集机械碎片，拉兹希望能组装出能够挽回他们共同悲剧的装置。"}},faq={{q="重组器的作用是什么？",a="重组器是拉兹·滑链和奥齐·电环设计的一台实验性机器，旨在逆转诺莫瑞根辐射产生的可怕突变效应，并治愈麻风侏儒。",al={"什么是重组器","重组器的目的","重组的含义"}},{q="拉兹·滑链和奥齐是谁？",a="他们是丹莫罗卡拉诺斯的侏儒发明家。在诺莫瑞根陷落后，他们致力于研究这场危机，并制造技术解决方案来拯救他们流离失所、饱受辐射之苦的人民。",al={"谁是拉兹","谁是奥齐·电环","拉兹·滑链背景故事"}},{q="为什么诺莫瑞根外会有麻风侏儒？",a="在穴居人入侵诺莫瑞根期间，城市中被释放了辐射以消灭这些野兽。这一策略造成了灾难性的后果：它没能阻止穴居人，反而导致许多幸存的侏儒发疯，变异成了敌对的麻风侏儒。",al={"为什么侏儒会变成麻风侏儒","麻风侏儒是怎么来的","诺莫瑞根辐射"}},{q="重组器的零件从哪里来？",a="它们直接从徘徊在丹莫罗西部诺莫瑞根入口处的疯狂麻风侏儒身上回收，这些麻风侏儒身上仍然携带着残存的技术硬件。",al={"去哪里获取齿轮和装置","重新稳定齿轮来源","陀螺机械装置"}},{q="重组器真的有效吗？",a="拉兹声称，只要有合适的零件、液压润滑剂，并对电胶凝胶进行调整，这台机器就能让侏儒恢复正常。然而，侏儒工程学以极不稳定著称，它是否真的能消除有毒辐射的影响仍不确定。",al={"重组器治愈他们了吗","麻风侏儒能被治愈吗","重组器成效"}}},fp="25,184,23.239.0,29.233.0,42.140.0,38.212.0,46.159.0,52.164.0,38.227.0"}
P.entries["quest:4120"] = {n="堕落的力量",s="塔罗·刺蹄是位于菲拉斯莫沙彻营地的一名猎人，他相信了解敌人能扭转战局。塔罗派你去灰谷北面的费伍德森林，去对付那些受邪能污染的熊和狼，看看它们是否真的变得更强大了。",h="塔罗·刺蹄是位于菲拉斯莫沙彻营地的一名猎人，他相信了解敌人能扭转战局。塔罗派你去灰谷北面的费伍德森林，去对付那些受邪能污染的熊和狼，看看它们是否真的变得更强大了。",kw={"愤怒之爪灰熊","莫沙彻营地","邪能腐蚀","魔爪劫掠者","费伍德森林","菲拉斯","塔罗·刺蹄"},sec={{t="了解你的敌人",b="塔罗·刺蹄是一位努力学习对手长处的猎人，他相信仅仅是了解敌人就能让你在战斗中占据上风。费伍德森林位于灰谷的北面，一种被称为邪能的物质污染了那里的生物。塔罗认为，那里受邪能驱使而发狂的熊和狼也变得更加强大了。你要面对的是愤怒之爪灰熊和魔爪劫掠者，每种各杀十二只。受邪能影响的生物会发出诡异的绿光，塔罗感觉到这种力量既邪恶又非常强大。"},{t="塔罗的耳闻",b="在听过你对野兽的描述后，塔罗断定它们表现出了盲目的凶残，并警告你要保持警惕，进一步了解这种腐蚀，因为你必须时刻了解你的敌人。"}},faq={{q="谁派你去费伍德森林？",a="塔罗·刺蹄，位于菲拉斯莫沙彻营地的一名猎人。",al={"任务发布者","谁给予腐蚀的力量任务","塔罗·刺蹄位置"}},{q="为什么塔罗·刺蹄要让你去对付费伍德森林的野兽？",a="塔罗相信了解敌人能扭转战局，他想让你亲自确认那些受邪能污染的生物是否真的如传闻中那样强大。",al={"为什么要猎杀熊和狼","腐蚀的力量任务目的","塔罗·刺蹄动机"}},{q="费伍德森林的目标生物是哪些？",a="费伍德森林的愤怒之爪灰熊和魔爪劫掠者，每种各十二只。",al={"哪些野兽","费伍德森林目标","要战斗的怪物"}},{q="塔罗如何评价邪能？",a="任何被邪能触碰过的事物都会发出诡异的绿光。塔罗感觉到这股力量既邪恶又非常强大。",al={"什么是污染","费伍德森林的绿光","什么是邪能"}}},fp="26,240,15.500.0,15.180.1,25.52.0,57.162.0,40.67.0,29.108.0"}
P.entries["quest:4124"] = {n="失踪的信使",s="位于羽月要塞的拉托尼库斯·月矛说，一名信使和他携带的包裹大约在一周前失踪了。要塞自己组织的搜寻一无所获，因此这名信使被宣布为失踪，你被派往寻找正在寻求帮助的基恩诺·火花。",h="位于羽月要塞的拉托尼库斯·月矛说，一名信使和他携带的包裹大约在一周前失踪了。要塞自己组织的搜寻一无所获，因此这名信使被宣布为失踪，你被派往寻找正在寻求帮助的基恩诺·火花。",kw={"信使","羽月要塞","菲拉斯","基恩诺·火花","豺狼人","拉托尼库斯·月矛","包裹","拉斯查尔"},sec={{t="失踪的信使",b="拉托尼库斯·月矛遇到了难题。一名信使和包裹在一周前失踪了，要塞的搜寻没有任何结果，所以拉托尼库斯宣布他失踪了。他的同伴基恩诺·火花正在寻求这方面的帮助，他应该就在羽月要塞，或许在他的住处。如果你有时间和精力，拉托尼库斯请你去和基恩诺谈谈。"},{t="基恩诺疲惫的搜寻",b="基恩诺知道是拉托尼库斯——基恩诺称他为拉特罗——派你来的。基恩诺认为这是一项注定失败的任务，但他还是接受了任何能提供的帮助，并渴望结束这件事。每天，基恩诺都会前往菲拉斯寻找拉斯查尔的踪迹，但每天晚上回来时，只有豺狼人的牙齿和失望。"}},faq={{q="谁失踪了？",a="一名大约在一周前连同他携带的包裹一起失踪的信使。要塞的搜寻毫无发现，他已被宣布失踪。",al={"谁是信使","谁失踪了","失踪信使的名字"}},{q="基恩诺·火花在哪里？",a="在羽月要塞，或许在他的住处。",al={"基恩诺·火花的位置","基恩诺在哪里","找到基恩诺"}},{q="谁发起了对信使的搜寻？",a="位于羽月要塞的拉托尼库斯·月矛，他派你去寻找基恩诺·火花并提供帮助。",al={"谁发布了失踪信使任务","拉托尼库斯·月矛的任务","谁发起了失踪信使任务"}}},fp="19,271,22.449.0,20.301.1,21.159.0,38.51.0,38.89.0"}
P.entries["quest:4125"] = {n="失踪的信使",s="基恩诺·火花告诉你，信使拉斯查尔大约一周前出发前往萨兰纳尔，计划划船沿海岸南下。基恩诺没能找到那条船，他请求你沿着菲拉斯的海岸搜寻，看看能不能找到有关拉斯查尔下落的线索。",h="基恩诺·火花告诉你，信使拉斯查尔大约一周前出发前往萨兰纳尔，计划划船沿海岸南下。基恩诺没能找到那条船，他请求你沿着菲拉斯的海岸搜寻，看看能不能找到有关拉斯查尔下落的线索。",kw={"羽月要塞","菲拉斯","被遗忘的海岸","基恩诺·火花","拉斯查尔","划艇","萨兰纳尔"},sec={{t="沿海岸的路线",b="大约一周前，拉斯查尔出发前往萨兰纳尔。拉斯查尔对菲拉斯非常了解，自羽月将军率领远征军来到这里以来，他一直都在远征军中效力。据基恩诺所知，拉斯查尔打算划船沿海岸南下，穿过菲拉斯南部，以避开部落的营地。基恩诺没能找到那条船，它可能被藏起来了或者沉没了，他请求你沿着菲拉斯的海岸搜寻，因为船上可能藏有关于拉斯查尔下落的线索。在大陆上，被遗忘的海岸从码头向南延伸。"},{t="在岸边",b="透过略显浑浊的积水，你发现了一条破烂的小船，它的一侧布满了巨大的破洞，几乎只剩下了木头框架。无论是什么东西毁了它，很可能试图把它劈成两半。船的另一侧绘有羽月要塞的小型徽记，在船底的淤泥中，有什么金属的东西在闪闪发光。"}},faq={{q="谁是拉斯查尔？",a="失踪的信使。拉斯查尔对菲拉斯非常了解，自羽月将军率领远征军来到这里以来，他一直都在远征军中效力。",al={"拉斯查尔是谁","失踪信使身份","谁失踪了"}},{q="拉斯查尔要去哪里？",a="去萨兰纳尔。拉斯查尔计划划船沿海岸南下，然后穿过菲拉斯南部，以避开部落的营地。",al={"拉斯查尔的目的地","他要去哪里","信使路线"}},{q="拉斯查尔失踪多久了？",a="大约一周了，自从他出发前往萨兰纳尔起。",al={"拉斯查尔什么时候离开的","失踪了多久"}},{q="这次搜寻是从哪里开始的？",a="这一步紧接在之前的“失踪的信使”之后，在那一步中，你与基恩诺·火花进行了交谈。",al={"上一步任务","这个任务是如何开始的"}}},fp="19,253,22.521.0,12.329.1,15.140.0,26.121.0,34.46.0,28.94.0"}
P.entries["quest:4127"] = {n="船只的残骸",s="在水中的一艘失事划艇旁，你在泥地里发现了一把保养良好的小刀。羽月要塞的基恩诺·火花希望你带回发现的任何线索，而一种感觉让你不寒而栗，似乎还有什么东西也潜伏在这片水域中。",h="在水中的一艘失事划艇旁，你在泥地里发现了一把保养良好的小刀。羽月要塞的基恩诺·火花希望你带回发现的任何线索，而一种感觉让你不寒而栗，似乎还有什么东西也潜伏在这片水域中。",kw={"船只残骸","丢弃的小刀","羽月要塞","菲拉斯","基恩诺·火花","失踪的信使","拉沙尔","划艇"},sec={{t="泥地中的小刀",b="在失事小艇附近的泥地里摸索时，你的指尖碰到了一把看起来保养良好的小刀的握柄。不管是谁在船上，可能已经弄丢了它，而小艇上缺掉的那一大块可能与此有关。你拿起了小刀，想起羽月要塞的基恩诺·火花曾让你带回发现的任何线索，但一种感觉让你不寒而栗，似乎还有什么东西也潜伏在这片水域中。"},{t="一个问题",b="基恩诺认为这把刀属于拉沙尔，并询问你是否真的在船底发现的它。仅凭这把刀可能不足以将小艇与拉沙尔的失踪联系起来，但有一个非同寻常的方法可以了解更多信息，基恩诺询问你是否听说过“心理测量术”。"}},faq={{q="小刀是在哪里发现的？",a="在岸边水中的失事划艇旁的泥地里。",al={"小刀位置","丢弃的小刀在哪里","我在哪里能找到小刀"}},{q="谁希望带回这条线索？",a="羽月要塞的基恩诺·火花，他希望你带回发现的任何线索。",al={"谁派我去船上","谁想要这把小刀","船只残骸任务上交"}},{q="这是把什么样的小刀？",a="是一把保养良好的小刀，在失事小艇旁的泥地里。不管是谁在船上，可能已经弄丢了它。",al={"谁拥有这把小刀","这是谁的刀刃"}},{q="在调查残骸之前发生了什么？",a="它是《失踪的信使》的第二部分，任务中曾要求你寻找信使的船。",al={"前置任务","什么导致了船只残骸"}}},fp="13,233,18.429.0,18.301.1,30.66.0,32.95.0,25.95.0,54.102.0"}
P.entries["quest:4129"] = {n="奎恩提斯的技艺",s="基恩诺·火花让你带着匕首去找羽月要塞的驻地德鲁伊奎恩提斯，他可以通过触摸了解一件物品的过去。基恩诺说，这笔债务正好可以抵消奎恩提斯欠下的卡利姆多梭哈赌债。",h="基恩诺·火花让你带着匕首去找羽月要塞的驻地德鲁伊奎恩提斯，他可以通过触摸了解一件物品的过去。基恩诺说，这笔债务正好可以抵消奎恩提斯欠下的卡利姆多梭哈赌债。",kw={"被丢弃的匕首","羽月要塞","基恩诺·火花","卡利姆多梭哈","灵视","奎恩提斯","拉斯彻尔"},sec={{t="德鲁伊的债务",b="在“船只残骸”任务之后，基恩诺·火花让你带着匕首去寻找羽月要塞的驻地德鲁伊奎恩提斯，他拥有一种不同寻常的技能。那就是灵视，通过触摸就能了解物体的过去。基恩诺不愿透露这是如何运作的，称其为他不想也不愿去理解的魔法，他只知道自己确实见过这种能力。奎恩提斯欠基恩诺一笔卡利姆多梭哈赌债，只要奎恩提斯对这把匕首施展一下魔法，这笔债就一笔勾销了。奎恩提斯住在要塞里的一间小树屋中。"},{t="倒霉蛋之王",b="奎恩提斯说，灵视解读会消耗精神，就像在卡利姆多梭哈中输牌一样，所以要塞里的人都称他是“倒霉蛋之王”：牌运不佳，却能看穿自然的秘密。奎恩提斯同意帮忙，希望这把匕首能带来突破，揭开拉斯彻尔的命运。"},{t="解读之前",b="奎恩提斯感谢你，并指出灵视并非一门精确的艺术，但他曾用它来阐明那些被其他人视为毫无希望的情况。他希望这把匕首能让他瞥见拉斯彻尔遭遇了什么。这只需要片刻时间，尽管对施法者来说这很吃力，奎恩提斯请你耐心等待。"}},faq={{q="奎恩提斯是谁？",a="羽月要塞的驻地德鲁伊，住在要塞里的一间小树屋中，拥有一种不同寻常的技能：灵视。",al={"奎恩提斯","奎恩提斯是谁","羽月要塞的德鲁伊"}},{q="什么是灵视？",a="通过触摸了解物体的过去。奎恩提斯说，这种解读很消耗心神。",al={"灵视如何运作","解读匕首","奎恩提斯的灵视"}},{q="为什么奎恩提斯要帮忙解读这把匕首？",a="奎恩提斯欠基恩诺·火花一笔卡利姆多梭哈赌债，基恩诺说只要解读了匕首，这笔债就还清了。此外，奎恩提斯也急于查明拉斯彻尔的命运。",al={"为什么帮助奎恩提斯","基恩诺的债务","卡利姆多梭哈"}},{q="这在调查过程中处于什么位置？",a="它发生在“船只残骸”任务之后，那把匕首就是在那个任务里找到的。",al={"前置任务是什么","下一个任务是什么","匕首揭秘任务线"}}},fp="18,216,14.515.0,21.310.0,18.320.1,25.130.0,20.93.0,37.159.0,44.55.0"}
P.entries["quest:413"] = {n="微光酒",s="雷杰德·麦酒在烈酒村研制出一种实验性的微光烈酒后，便请求路过的旅人带一桶新鲜的麦酒去给他兄弟韦拉特。韦拉特是一名驻守在南门小径通往洛克莫丹方向哨塔的矮人巡山人，在那样的寒冷岗位上，一杯烈酒总是格外受欢迎。",h="雷杰德·麦酒在烈酒村研制出一种实验性的微光烈酒后，便请求路过的旅人带一桶新鲜的麦酒去给他兄弟韦拉特。韦拉特是一名驻守在南门小径通往洛克莫丹方向哨塔的矮人巡山人，在那样的寒冷岗位上，一杯烈酒总是格外受欢迎。",kw={"丹莫罗","卡拉诺斯","巡山人维拉特·麦酒","雷杰德·麦酒","微光烈酒","南门小径","韦拉特"},ang={["faction:Alliance"]="为尽职的巡山人们提供补给，有助于维持保护丹莫罗与洛克莫丹之间大道的守卫网络。",["race:Dwarf"]="对于矮人来说，与家人分享麦酒和守卫高山隘口一样，都是至关重要的职责。这使得这项运送任务成为了铁炉堡边境生活的一个典型缩影。"},sec={{t="边境的家传秘方",b="雷杰德·麦酒使用从丹莫罗冰冷岩壁上采集的微光叶状植株，完善了他的新发明：微光烈酒。当麦酒家族的其他成员致力于烈酒村的酿造工作时，雷杰德的兄弟韦拉特却选择了巡山人的生活。深知边境守卫生活的孤寂，雷杰德托路过的旅人送去一桶新鲜的麦酒，这既是对兄弟的关照，也是一次真正的口味测试。"},{t="南门哨塔",b="韦拉特·麦酒驻守在位于南门小径通往洛克莫丹道路旁侧的南门哨塔。在山路的高处，巡山人们忍受着刺骨的寒风和不时出现的野兽袭击，守护着往来的旅人。由于酒水短缺且渴望刺激，韦拉特发现微光烈酒非常有劲——以至于它似乎让他在这昏暗的山间夜晚看东西都变得更清楚了。"}},faq={{q="巡山人麦酒是谁？",a="巡山人韦拉特·麦酒是雷杰德·麦酒的兄弟。不同于他在烈酒村酿酒的亲人，韦拉特选择了加入丹莫罗巡山人，守望着连接丹莫罗与洛克莫丹的高山隘口。",al={"韦拉特·麦酒是谁","韦拉特·麦酒","巡山人麦酒背景故事"}},{q="南门哨塔位于何处？",a="这座塔坐落在丹莫罗的东部边界，守卫着穿过群山通往邻近洛克莫丹峡谷的南门小径。",al={"南门哨塔在哪里","巡山人麦酒位置","韦拉特在哪里"}},{q="微光烈酒有什么特别之处？",a="微光烈酒是用在雪地荒野中收集的特殊微光叶状植株酿造的。据韦拉特说，喝下它会让他的眼睛闪闪发光，感觉好像能一眼看穿黑暗。",al={"微光烈酒有什么作用","微光烈酒效果"}},{q="韦拉特喝下烈酒后发生了什么？",a="韦拉特非常喜欢这种酒，以至于他请求旅人们再运一桶到洛克莫丹，与正在塞尔萨玛巡逻道路的巡山人卡德雷尔分享。",al={"微光烈酒后续是什么","微光烈酒任务后续"}}},fp="13,181,31.379.0,26.381.0,30.217.0,42.130.0,33.181.0,44.144.1"}
P.entries["quest:4130"] = {n="心灵占卜术",s="奎恩提斯在解读了那把匕首后仍感到虚弱，他将关于拉斯查尔和木爪豺狼人的幻象传递给你，并请求你将其转达给羽月要塞的基恩诺·火花。",h="奎恩提斯在解读了那把匕首后仍感到虚弱，他将关于拉斯查尔和木爪豺狼人的幻象传递给你，并请求你将其转达给羽月要塞的基恩诺·火花。",kw={"羽月要塞","基恩诺·火花","灵视解读","奎恩提斯","拉斯查尔","水元素","木爪豺狼人"},sec={{t="奎恩提斯所见",b="奎恩提斯·琼斯派尔虽然还未恢复稳健，但他已经看到了有用的线索。在幻象中，拉斯查尔从船上拖下两个巨大的皮背包，向内陆走去，然后又回到了船上。出现了豺狼人的头皮，奎恩提斯认为拉斯查尔遇到了木爪豺狼人。拉斯查尔看起来非常担忧，几乎到了恐惧的程度，完全没有注意到身后正在形成的水元素。影像到此为止。奎恩提斯必须休息了，他请求你去告诉基恩诺，因为他有必要知道这一切。"},{t="基恩诺的答复",b="基恩诺感谢你转达了奎恩提斯的幻象。拉斯查尔有能力处理战斗，豺狼人不会让他担心，更不会让他感到恐惧。即便如此，基恩诺仍希望你和你的伙伴能根据这些线索采取行动，并取得急需的突破。"}},faq={{q="谁分享了幻象？",a="奎恩提斯·琼斯派尔，他在解读匕首后仍感到虚弱，并请求你将消息传达给基恩诺。",al={"谁进行灵视解读","灵视解读任务发布者"}},{q="奎恩提斯在幻象中看到了什么？",a="拉斯查尔从船上拿了两个大皮背包到内陆，然后又回到了船上。奎恩提斯还看到了豺狼人的头皮，推测那些豺狼人是木爪部落的。他看到拉斯查尔非常担忧，几乎到了恐惧的地步，并看到水元素在他身后成形。",al={"奎恩提斯的幻象内容","拉斯查尔幻象中发生了什么"}},{q="这份报告需要送到哪里？",a="送到羽月要塞的基恩诺·火花那里。",al={"我在哪里交付幻象报告","灵视解读找谁交谈"}}},fp="20,197,16.412.0,14.248.1,28.122.0,35.240.0,34.64.0"}
P.entries["quest:4131"] = {n="木爪豺狼人",s="在奎恩提斯的幻象之后，基恩诺·火花派遣你去搜索菲拉斯南部的木爪豺狼人营地，寻找有关信使或其随身物品的证据。基恩诺并不认为那些豺狼人是导致拉沙尔失踪的罪魁祸首，但它们确实是最好的起点。",h="在奎恩提斯的幻象之后，基恩诺·火花派遣你去搜索菲拉斯南部的木爪豺狼人营地，寻找有关信使或其随身物品的证据。基恩诺并不认为那些豺狼人是导致拉沙尔失踪的罪魁祸首，但它们确实是最好的起点。",kw={"羽月要塞","菲拉斯","基恩诺·火花","皮背包","低地荒野","奎恩提斯","拉沙尔","木爪豺狼人"},sec={{t="从哪里开始寻找",b="基恩诺·火花承认，也许那些所谓的“朋友”木爪豺狼人最终还是解决了拉沙尔，尽管基恩诺的直觉并非如此。不过，它们确实是最好的起点。除了搜索它们的营地，基恩诺也没有更好的计划。他知道豺狼人会保留它们搜刮来的东西并为此争抢，所以它们可能正好得到了奎恩提斯提到的那些背包。在过去的搜索中，基恩诺一直避免正面冲突，但现在有了幻象作为指引，他下令直接杀进去。这些营地位于菲拉斯南部。"},{t="在营地",b="两个大皮背包被钉在附近的一棵树上，每个背包的前面都带着一个羽月要塞的小徽章。它们位于低地荒野。"}},faq={{q="要寻找谁？",a="信使拉沙尔。基恩诺·火花想要关于这位信使或其随身物品的证据。",al={"失踪者是谁","木爪豺狼人搜索目标","拉沙尔是谁"}},{q="为什么要搜索木爪豺狼人营地？",a="基恩诺说那是最好的起点。豺狼人会把搜刮来的东西据为己有并为此争抢，所以它们可能正好得到了奎恩提斯提到的那些背包。",al={"为什么是木爪豺狼人","为什么要杀豺狼人","为什么要搜索豺狼人营地"}},{q="关于背包的线索是从哪里来的？",a="奎恩提斯在幻象中提到，拉沙尔从船上拿走了两个大皮背包。",al={"谁提到了背包","奎恩提斯的背包幻象","基恩诺怎么知道背包的事"}},{q="木爪营地在哪里？",a="在菲拉斯南部。",al={"木爪豺狼人位置","菲拉斯的豺狼人营地在哪里","木爪营地地图"}}},fp="18,257,22.531.0,12.159.1,26.99.0,35.156.0,49.107.0,28.20.0"}
P.entries["quest:4135"] = {n="痛苦深渊",s="背包中有一封匆忙写下的便条，署名是羽月要塞的拉沙尔。他在信中写道，他发现了一些虫状生物，并决定亲自去调查。你对他的搜寻现在指向了那里。",h="背包中有一封匆忙写下的便条，署名是羽月要塞的拉沙尔。他在信中写道，他发现了一些虫状生物，并决定亲自去调查。你对他的搜寻现在指向了那里。",kw={"羽月","菲拉斯","卵囊","拉沙尔","萨兰纳尔","木爪","痛苦深渊","祖卡什"},sec={{t="背包里的便条",b="背包里装着一个打算送往萨兰纳尔的包裹，还有一封写得非常匆忙的便条，没有特定的收件人。作者是羽月要塞的拉沙尔，他在便条中描述了自己在痛苦深渊（位于豺狼人营地以南）发现的那些阴险的虫状生物。他觉得必须亲眼去看看，因为它们似乎对整个菲拉斯构成了严重的威胁。这张便条标明了他前往的地方。"},{t="下方潜伏着什么",b="在痛苦深渊，你发现了一个巨大的异种卵囊。其表面看起来粘糊糊的，上面还长着坚硬的突起。它的高度和宽度足以容纳一个人，透过外皮，你可以隐约看到里面有一个人形的轮廓，你认为那就是它所困住的人。"}},faq={{q="拉沙尔是谁？",a="羽月要塞的拉沙尔写下了在背包中发现的那张便条。他前去调查自己发现的那些虫状生物，而你对他的搜寻还在继续。",al={"拉沙尔背景故事","谁是拉沙尔","拉沙尔 羽月"}},{q="痛苦深渊位于哪里？",a="拉沙尔的便条指出痛苦深渊位于木爪豺狼人营地的南边。",al={"痛苦深渊位置","痛苦深渊在哪里","如何找到痛苦深渊"}},{q="拉沙尔为什么要去痛苦深渊？",a="他的便条中说，他在那里发现了阴险的虫状生物，并觉得有必要亲自调查，因为它们看起来对整个菲拉斯都是严重的威胁。",al={"拉沙尔为何前往虫巢","拉沙尔的动机","为什么是痛苦深渊"}},{q="在这次搜寻之前发生了什么？",a="这是在上一阶段任务“木爪豺狼人”之后进行的。",al={"痛苦深渊前置任务","哪个任务在先"}}},fp="17,205,21.368.0,16.295.1,15.155.0,35.71.0,40.163.0,30.50.0"}
P.entries["quest:414"] = {n="卡德雷尔的酒",s="《送给卡德雷尔的黑啤酒》是一项联盟护送任务，带领旅行者走出冰封的丹莫罗高地，进入温和的洛克莫丹山谷。你受托携带一桶雷杰德·麦酒刚刚改良完成的微光黑啤酒，横跨领地边界，送到正在塞尔萨玛巡逻的巡山人卡德雷尔手中。",h="《送给卡德雷尔的黑啤酒》是一项联盟护送任务，带领旅行者走出冰封的丹莫罗高地，进入温和的洛克莫丹山谷。你受托携带一桶雷杰德·麦酒刚刚改良完成的微光黑啤酒，横跨领地边界，送到正在塞尔萨玛巡逻的巡山人卡德雷尔手中。",kw={"麦芽酒","维拉特·麦酒","酒桶","丹莫罗","卡德雷尔","洛克莫丹","雷杰德","微光黑啤酒","塞尔萨玛"},ang={["faction:Alliance"]="这项任务是引导联盟英雄走出丹莫罗冰雪覆盖的起始地区，进入洛克莫丹更广阔边境的自然引导线。",["race:Dwarf"]="跨越领地边界运送一桶高山麦芽酒是典型的矮人式情谊，它将烈酒村的酿酒师与守卫卡兹莫丹的边境巡逻队联系在了一起。"},sec={{t="山的那一头的滋味",b="在品尝过他兄弟雷杰德·麦酒刚刚酿造完成的微光黑啤酒后，巡山人维拉特·麦酒坚信这美酒不应只留在丹莫罗。驻扎在守卫山口的东部边境哨岗上，维拉特·麦酒望着守卫邻近土地的同胞。对于矮人巡山人来说，这可能是一项寒冷而艰苦的工作，而一颗坚毅的心需要烈酒来慰藉。维拉特·麦酒希望得到前线同袍的真实评价，便托付路过的旅行者将一桶酒向东运往洛克莫丹。"},{t="通往塞尔萨玛之路",b="这段旅程标志着年轻的矮人和侏儒冒险者自然而然的成年礼，他们早期的时光大多是在丹莫罗冰封的峭壁间度过的。向东南穿过南门哨岗，踏过贯穿山岩的长隧道，旅行者会突然进入气候温和、林木葱郁的洛克莫丹盆地。沿着通往塞尔萨玛定居点的道路巡逻，巡山人卡德雷尔很乐意从警卫工作中抽出空来，撬开酒桶，发现维拉特·麦酒的新配方有着令人惊叹的后劲。"}},faq={{q="巡山人卡德雷尔是谁？",a="巡山人卡德雷尔是一名驻扎在洛克莫丹的矮人守卫。他每天都在穿过塞尔萨玛镇的中央大道上巡逻。",al={"卡德雷尔","卡德雷尔是谁","巡山人卡德雷尔的位置"}},{q="什么是微光黑啤酒？",a="微光黑啤酒是由雷杰德·麦酒在丹莫罗西部的烈酒村酿酒厂酿造的一种烈性特制麦芽酒，以其令人晕眩的后劲和令人精神振奋的温暖感而闻名。",al={"什么是微光黑啤酒","微光黑啤酒","雷杰德的酿造"}},{q="我该如何从丹莫罗前往洛克莫丹？",a="从丹莫罗的东部哨岗出发，向东南穿过山洞，经过南门。一旦进入洛克莫丹，沿着道路向东北岔路走，直达湖畔定居点塞尔萨玛。",al={"如何前往洛克莫丹","通往塞尔萨玛的路","从丹莫罗到洛克莫丹"}},{q="为什么维拉特·麦酒要让卡德雷尔品尝这种酒？",a="巡山人维拉特·麦酒和巡山人卡德雷尔都是矮人巡山人组织的成员。维拉特·麦酒对他兄弟的新配方印象深刻，因此他希望驻扎在邻近山谷的战友也能品尝一下。",al={"为什么要给卡德雷尔送黑啤酒","维拉特·麦酒和卡德雷尔的关系"}},{q="卡德雷尔觉得这酒怎么样？",a="喝了一口之后，卡德雷尔对其强劲的口感感到震惊，他对着麦格尼的胡须发誓，这黑啤酒让他头晕目眩，四肢轻盈，仿佛整个人都要飘起来了。",al={"卡德雷尔的反应","微光黑啤酒好喝吗"}},{q="这个任务后续还有任务吗？",a="虽然它结束了在丹莫罗开始的微光黑啤酒递送任务线，但将酒桶送到目的地直接将旅行者带入了塞尔萨玛，从而在洛克莫丹开启了许多新的任务和职责。",al={"送给卡德雷尔的黑啤酒后续","what comes next"}}},fp="16,172,28.411.0,21.456.0,27.103.0,22.181.0,42.188.0,49.201.0,36.150.0,38.151.0"}
P.entries["quest:415"] = {n="雷杰德的新酒",s="雷杰德的新酒是一个丹莫罗的联盟差事，召唤冒险者回到烈酒村。酿酒师雷杰德·麦酒利用收集到的微光草完善了一种新配方，他希望一位值得信赖的朋友能品尝他最新的杰作。这是收集酿酒原料与将他珍贵的微光酒分发到整个山区王国之间的桥梁。",h="雷杰德的新酒是一个丹莫罗的联盟差事，召唤冒险者回到烈酒村。酿酒师雷杰德·麦酒利用收集到的微光草完善了一种新配方，他希望一位值得信赖的朋友能品尝他最新的杰作。这是收集酿酒原料与将他珍贵的微光酒分发到整个山区王国之间的桥梁。",kw={"麦芽酒","酿造","烈酒村","丹莫罗","驾驶员贝隆·风箱","雷杰德·麦酒","微光酒","微光草","萨雷克·黑石"},ang={["faction:Alliance"]="浓郁的矮人麦芽酒滋养着东部王国的联盟驻军，使丹莫罗等严酷的前线哨所士气高昂。",["race:Dwarf"]="对于矮人来说，没有什么比受到受人尊敬的酿酒师亲自召唤来喝下第一桶鲜酒的荣誉更高了。"},sec={{t="烈酒村的传唤",b="当一位矮人酿酒师在他的地窖中发现金矿般珍贵的配方时，消息迅速传遍了丹莫罗。在从苦寒山坡上获得了微光草之后，像萨雷克·黑石或驾驶员贝隆·风箱这样的当地联络人会催促路过的冒险者回到烈酒村。雷杰德·麦酒已经完成了他试验性批次的酿造，并渴望与那位使这一切成为可能的旅行者分享成果。"},{t="品尝劳动成果",b="烈酒村以独特的酿酒工艺而繁荣，而麦酒最新的一批产品绝非普通的麦芽酒。将当地草药融入麦芽浆中酿造出了一种独特的饮料，即微光酒。在将酒桶运往邻近的前哨站以及洛克莫丹那些口渴的顾客手中之前，雷杰德坚持要求那位为了这些草药而冒着生命危险的冒险者获得首尝的殊荣。"}},faq={{q="是谁让我回到雷杰德·麦酒那里？",a="驻扎在丹莫罗的盟友，如萨雷克·黑石或驾驶员贝隆·风箱，会告知你雷杰德正在烈酒村召唤你。",al={"谁开启了雷杰德的新酒任务","任务发布者","去哪里接任务"}},{q="烈酒村在哪里？",a="烈酒村坐落在丹莫罗的西部，沿着冰封的涌冰湖湖岸而建。",al={"烈酒村在哪","烈酒村位置","雷杰德·麦酒位置"}},{q="雷杰德的新酒是用什么做的？",a="雷杰德将野生微光草——一种在丹莫罗寒冷峭壁中发现的奇特原生植物——融入他传统的麦芽酒配方中，酿造出了他的新酒。",al={"酒里有什么","雷杰德做了什么","微光草配方"}},{q="我和雷杰德谈话后会发生什么？",a="雷杰德会让你品尝他的新杰作，然后委派你将一大桶微光酒送到他的兄弟威尔特那里，他是一位驻扎在洛克莫丹边境南侧岗哨的登山者。",al={"后续任务","what comes next","雷杰德任务链"}},{q="为什么雷杰德特别想让我尝试？",a="因为你协助他获得了试验配方所需的稀有微光草，雷杰德认为让你先品尝最终成品是符合矮人礼节的。",al={"为什么雷杰德找我","谁测试了啤酒"}},{q="最终的饮料叫什么名字？",a="这种试验性的调配酒被称为微光酒，以赋予其独特口感的关键成分命名。",al={"他做了什么饮料","饮料名称","雷杰德的啤酒"}}},fp="17,148,21.265.0,26.272.0,39.127.0,26.85.0,35.126.0,37.203.1,47.153.0,39.105.0"}
P.entries["quest:416"] = {n="狗头人的耳朵",s="“捕鼠行动”是洛克莫丹的一项当地悬赏任务，由塞尔萨玛的巡山人卡德雷尔发布。冒险者被派往清除在西侧山麓蔓延的隧道鼠狗头人，必须消灭这些害虫并带回它们的耳朵来领取奖励。",h="“捕鼠行动”是洛克莫丹的一项当地悬赏任务，由塞尔萨玛的巡山人卡德雷尔发布。冒险者被派往清除在西侧山麓蔓延的隧道鼠狗头人，必须消灭这些害虫并带回它们的耳朵来领取奖励。",kw={"悬赏","狗头人","洛克莫丹","巡山人卡德雷尔","捕鼠行动","塞尔萨玛","隧道鼠","隧道鼠耳朵"},ang={["faction:Alliance"]="巡山人卡德雷尔代表了洛克莫丹当地的矮人官方，为任何愿意保卫其定居点的联盟冒险者提供悬赏。",["race:Dwarf"]="作为卡兹莫丹的守护者，矮人们有责任确保塞尔萨玛周边的山麓免受害虫和地底入侵者的侵扰。"},sec={{t="山麓的害虫",b="在塞尔萨玛以西，一群隧道鼠狗头人在洛克莫丹的山麓安了家。这些地底害虫在山腰挖掘洞穴，用污秽弄脏了周围的地形，对矮人定居点造成了持续的骚扰。如果放任不管，它们的巢穴将威胁到通往城镇的道路的安全与卫生。"},{t="巡山人的悬赏",b="为了应对这些入侵的害虫，巡山人卡德雷尔决定亲自出手，对这些生物发布了长期悬赏。卡德雷尔号召路过的冒险者，要求他们上交切下的隧道鼠耳朵作为捕杀证明，然后才会支付金币和报酬，尽管这些充满刺鼻气味的战利品查验起来令人作呕。"}},faq={{q="谁发布“捕鼠行动”任务？",a="巡山人卡德雷尔在塞尔萨玛发布了这份悬赏。他请求过往的旅客和冒险者帮忙清除从附近山腰入侵城镇的害虫。",al={"捕鼠行动任务发布者","捕鼠行动领取地点","卡德雷尔任务"}},{q="什么是隧道鼠狗头人？",a="隧道鼠是一类狗头人，它们在塞尔萨玛附近的西侧山麓挖掘洞穴并在此定居，其污秽遍布山腰。",al={"什么是隧道鼠","洛克莫丹的狗头人","隧道鼠狗头人"}},{q="在哪里可以找到隧道鼠狗头人？",a="隧道鼠狗头人及其洞穴位于塞尔萨玛的正西侧，分散在崎岖的山腰和山麓地带。",al={"隧道鼠位置","捕鼠行动地点","塞尔萨玛西侧的洞穴"}},{q="为什么卡德雷尔要求上交隧道鼠耳朵？",a="巡山人卡德雷尔需要隧道鼠狗头人的耳朵作为击杀证明，才会发放城镇的悬赏奖励。",al={"为什么要收集耳朵","卡德雷尔为什么要耳朵","洛克莫丹击杀证明"}},{q="为什么这位巡山人会担心狗头人的入侵？",a="狗头人搬进了塞尔萨玛外面的山麓，它们不仅筑起了洞穴，还用自己的污秽弄脏了周围的矮人土地。卡德雷尔希望消灭它们以保障该地区的安全。",al={"为什么要清除隧道鼠","塞尔萨玛鼠患","为什么要在洛克莫丹杀狗头人"}},{q="“捕鼠行动”会引出更大的任务线吗？",a="“捕鼠行动”是一项旨在清除塞尔萨玛周边害虫的简单当地悬赏任务，并非那种复杂的连续任务。一旦交付了耳朵，卡德雷尔就会支付悬赏。",al={"捕鼠行动后续任务","捕鼠行动任务链","捕鼠行动后的任务"}}},fp="12,178,23.224.0,22.216.0,33.125.0,28.129.0,42.113.0,41.98.0,62.171.0,45.97.0"}
P.entries["quest:4161"] = {n="卡多雷的菜谱",s="“卡多雷的食谱”是扎瑞恩在多兰纳尔传授的一堂关于平衡的课程，他是一位烹饪导师。通过在泰达希尔各地收集精确数量的蜘蛛腿，有志成为厨师的人们学到，从大自然中获取食物需要节制与尊重。",h="“卡多雷的食谱”是扎瑞恩在多兰纳尔传授的一堂关于平衡的课程，他是一位烹饪导师。通过在泰达希尔各地收集精确数量的蜘蛛腿，有志成为厨师的人们学到，从大自然中获取食物需要节制与尊重。",kw={"烹饪","多兰纳尔","卡多雷","卡多雷的食谱","蜘蛛烤肉","泰达希尔","扎瑞恩"},ang={["profession:Cooking"]="这个任务是在泰达希尔进行荒野烹饪的初步入门，奖励是卡多雷蜘蛛烤肉食谱。",["race:NightElf"]="这堂课强化了卡多雷的核心世界观：通过实行节制并只取必要之物来维持与自然的和谐。"},sec={{t="星之子",b="在多兰纳尔旅店后方，扎瑞恩照料着一口冒泡的坩埚，向年轻的冒险者们传授他族人的传统。早在现代之前，暗夜精灵就自称为“卡多雷”，意为“星之子”。对扎瑞恩而言，理解这种祖传的遗产并非始于战场，而是始于猎人、猎物以及泰达希尔周边枝桠之间的关系。"},{t="只取所需",b="这堂课的核心在于节制。扎瑞恩要求他的学生从幽影谷外的丛林蛛形生物身上收集小型蜘蛛腿，但明确命令只能拿七个——不多不少。在暗夜精灵文化中，与自然和谐共处要求严格只取必要之物，并以善意回馈荒野。即使在动荡时期也必须保持这种微妙的平衡，这种哲学将简单的蜘蛛烤肉变成了一种道德准则。"}},faq={{q="扎瑞恩是谁？",a="扎瑞恩是一位暗夜精灵烹饪导师，在多兰纳尔旅店后方照看一口坩埚。他在指导年轻冒险者烹饪的同时，强调卡多雷祖先价值观的重要性。",al={"扎瑞恩","扎瑞恩是谁","多兰纳尔厨师","多兰纳尔烹饪训练师"}},{q="为什么扎瑞恩坚持要求收集正好七根蜘蛛腿？",a="扎瑞恩强调，卡多雷必须与自然和谐相处，只取生存所需之物。严格收集所需的数量能培养对生命森林的尊重，并维持自然平衡。",al={"为什么是七根腿","为什么只要七根","拿七根就够了"}},{q="“卡多雷”这个词是什么意思？",a="在达纳苏斯语中，卡多雷意为“星之子”，这是暗夜精灵数千年来对自己的古老称呼。",al={"卡多雷是什么意思","卡多雷的含义","星之子"}},{q="在哪里收集蜘蛛腿？",a="这些蜘蛛腿可以从游荡在幽影谷受保护边界之外、泰达希尔森林中的林木蜘蛛身上收获。",al={"哪里掉落蜘蛛腿","蜘蛛腿位置","哪种蜘蛛"}},{q="暗夜精灵用蜘蛛腿烹制什么？",a="扎瑞恩教冒险者如何制作卡多雷蜘蛛烤肉，这是一种传统的荒野料理，能将丛林蜘蛛肉变成一种营养丰富、适合旅行的餐点。",al={"那个食谱是什么","卡多雷蜘蛛烤肉","蜘蛛食物"}},{q="泰达希尔所有的蜘蛛都能提供所需的蜘蛛腿吗？",a="不。在幽影谷受保护的山谷内发现的幼年蜘蛛无法提供扎瑞恩食谱所需的合适腿部；必须狩猎那些游荡在泰达希尔更广阔树林中的蜘蛛。",al={"幽影谷的蜘蛛行吗","幽影谷蜘蛛腿"}}},fp="22,156,21.348.0,26.347.0,14.143.0,63.195.0,35.150.0,35.101.0,45.163.0,51.148.0"}
P.entries["quest:417"] = {n="驾驶员的复仇",s="追踪一名失踪的矮人攻城机驾驶员，线索指向丹莫罗荒野中的一具冻尸。在遗骸旁发现的莫里·铁钻的日记详细记录了他与一只名为“肮脏的爪子”的臭名昭著的掠食者之间的致命搏斗，并留下了一个垂死的复仇愿望。",h="追踪一名失踪的矮人攻城机驾驶员，线索指向丹莫罗荒野中的一具冻尸。在遗骸旁发现的莫里·铁钻的日记详细记录了他与一只名为“肮脏的爪子”的臭名昭著的掠食者之间的致命搏斗，并留下了一个垂死的复仇愿望。",kw={"丹莫罗","锤足","希尔德夫","冰爪熊","铁炉堡攻城部队","肮脏的爪子","复仇"},ang={["class:Hunter"]="在丹莫罗寒冷的狂风中追踪像“肮脏的爪子”这样异常凶猛的兽王，是对山区生存能力的真正考验。",["faction:Alliance"]="铁炉堡的驾驶员是矮人和联盟防御的重要分支，因此搜救失踪的驾驶员是一项至关重要的职责。",["race:Dwarf"]="为铁炉堡攻城部队阵亡的兄弟复仇是荣誉攸关的大事，这能确保希尔德夫的遗志得到尊重，他的凶手受到惩罚。"},sec={{t="最后的日记",b="驾驶员希尔德夫没能在他滞留的崎岖雪崖中幸存下来。当旅行者发现他的遗骸时，他们在他身旁找到了他的日记。在最后的笔迹中，希尔德夫记录了他与一只被他称为“肮脏的爪子”的巨大冰爪熊之间的残酷遭遇。尽管他最初设法抵御了这只怪兽，但伤势实在太重，野兽最终还是折返回来，终结了虚弱的驾驶员的性命。"},{t="驾驶员的遗愿",b="希尔德夫知道自己命不久矣，便在日记中写下了最后一个请求：向夺走他生命的怪物复仇。带着日记和从倒下的野兽身上撕下的爪子回到驾驶员塞克·锤足身边，为铁炉堡攻城部队画上了一个沉痛的句号，既缅怀了他们失去的战友，也消除了山路上的一大致命威胁。"}},faq={{q="希尔德夫是谁？",a="驾驶员希尔德夫是一名矮人攻城机驾驶员，也是铁炉堡攻城部队的一员。他的攻城机抛锚后，他徒步走进丹莫罗的山区，他的朋友驾驶员塞克·锤足派出搜寻者去寻找他，结果却只在雪地里发现了他的遗骸。",al={"希尔德夫","死去的矮人是谁","失踪的驾驶员"}},{q="“肮脏的爪子”是什么？",a="“肮脏的爪子”是一只游荡在丹莫罗山坡上、异常巨大且凶猛的冰爪熊。它伏击了驾驶员希尔德夫并造成了致命伤，随后折返回来杀死了他。",al={"肮脏的爪子","冰爪熊","谁杀了希尔德夫"}},{q="驾驶员塞克·锤足是谁？",a="驾驶员塞克·锤足是一名驻扎在丹莫罗、经验丰富的攻城机驾驶员，隶属于铁炉堡攻城部队。他非常担心失踪的朋友希尔德夫，于是指引冒险者前往荒野探查真相。",al={"塞克·锤足","驾驶员塞克·锤足"}},{q="为什么希尔德夫的死对铁炉堡很重要？",a="铁炉堡攻城部队依靠其训练有素的驾驶员和机械来侦察和保卫首都周围的山区领地。失去像希尔德夫这样技术娴熟的驾驶员，对部队的战力是一个沉重的打击。",al={"为什么要关心希尔德夫","攻城部队的重要性"}},{q="这个任务链从哪里开始？",a="旅程始于驾驶员塞克·锤足提供的“失踪的驾驶员”任务，他请求你寻找失踪的朋友。这随后引导你发现希尔德夫的尸体，从而开启“驾驶员的复仇”。",al={"如何开启驾驶员的复仇","失踪的驾驶员任务链"}},{q="你需要带什么证据给锤足？",a="你必须呈交从驾驶员尸体上找到的莫里·铁钻的日记，以及从“肮脏的爪子”尸体上取得的肮脏的爪子，以证明这只野兽已被杀死。",al={"肮脏的爪子的证据","需要什么物品"}}},fp="17,160,13.182.0,20.217.0,17.248.0,18.196.0,24.213.0,46.181.0,34.163.0,46.145.0"}
P.entries["quest:418"] = {n="塞尔萨玛血肠",s="在繁华的塞尔萨玛小镇，厨师维德拉·壁炉用一道著名的高地主食喂饱了当地的劳工和矿工：血肠。烹制这种丰盛的矮人佳肴需要从洛克莫丹周边山谷中搜集新鲜食材。",h="在繁华的塞尔萨玛小镇，厨师维德拉·壁炉用一道著名的高地主食喂饱了当地的劳工和矿工：血肠。烹制这种丰盛的矮人佳肴需要从洛克莫丹周边山谷中搜集新鲜食材。",kw={"熊肉","血肠","野猪肠","烹饪","洛克莫丹","蜘蛛毒液","塞尔萨玛","维德拉·壁炉"},ang={["faction:Alliance"]="为维德拉提供补给有助于让塞尔萨玛的当地劳动力保持体力，他们正致力于维护基础设施并挖掘洛克莫丹各处的古代遗迹。",["profession:Cooking"]="为维德拉收集食材可以奖励有抱负的厨师获得正宗的血肠配方，扩充他们的丰盛野外口粮食谱。",["race:Dwarf"]="血肠是一道典型的矮人慰藉食品，体现了卡兹莫丹山地氏族粗犷的烹饪品味。"},sec={{t="一道丰盛的高地菜肴",b="塞尔萨玛从来不缺饥肠辘辘的食客。从充满活力的孩子们，到从铁环挖掘场归来的疲惫矿工，维德拉·壁炉在酒馆的炉台前不知疲倦地忙碌着。为了让镇民们吃得饱足满意，她沿用了一道在洛克莫丹广为人知的烹饪传统：用漫游在崎岖山道间的野生动物制成的美味血肠。"},{t="不同寻常的香料",b="虽然传统的血肠主要使用鲜血、调味肉和天然肠衣，但维德拉的配方体现了矮人粗犷务实的风格。野猪的肠子被用作肠衣，熊肉作为结实的馅料，并加入了蜘蛛毒液来增添一种强烈、刺鼻的味道。尽管收集毒液和内脏并非胆小者所能为，但做出来的成果却是一道深受当地欢迎的美食，旅行者们很快就会爱上它。"}},faq={{q="谁是维德拉·壁炉？",a="维德拉·壁炉是住在烈酒旅店里的塞尔萨玛常驻厨师和管家。她以能喂饱洛克莫丹辛勤工作的人们，尤其是附近挖掘场的劳工为荣。",al={"维德拉","谁是维德拉","塞尔萨玛厨师"}},{q="为什么配方里要用蜘蛛毒液？",a="维德拉使用蜘蛛毒液作为一种独特的香料，赋予她的血肠标志性的风味。矮人的味觉以坚韧著称，这种毒液带来的刺鼻味道是普通草药无法比拟的。",al={"香肠中的蜘蛛毒液","为什么用蜘蛛毒液","蜘蛛香料"}},{q="谁会吃塞尔萨玛的血肠？",a="这道香肠是当地镇民、顽皮的孩子，以及每天傍晚从铁环挖掘场繁重工作中归来的疲惫工人们的餐点。",al={"谁吃血肠","为什么要制作香肠"}},{q="食材在哪里可以找到？",a="这三种成分——黑熊、山地野猪和林木潜伏者蜘蛛——都徘徊在洛克莫丹湖泊周边的荒野和林木山丘中。",al={"去哪找熊肉","去哪找野猪肠","食材位置"}},{q="香肠使用什么肠衣？",a="维德拉使用从当地山地野猪身上清理出来的天然肠衣，制作出一种结实的外壳，能够将密实的熊肉和调好味的馅料在火上烤制时保持完整。",al={"香肠肠衣","野猪肠","肠衣配方"}},{q="旅行者可以学习烹制这种香肠吗？",a="可以。如果冒险者给维德拉带来食材，她会很高兴分享她的配方，让有烹饪技巧的旅行者能够亲手制作这道丰盛的矮人佳肴。",al={"我可以烹饪血肠吗","香肠配方","烹饪配方"}}},fp="24,168,22.226.0,21.254.0,25.168.0,37.75.0,34.119.0,32.115.0,37.115.0,42.96.0"}
P.entries["quest:419"] = {n="失踪的驾驶员",s="驾驶员塞克·锤足为他的战友莫里·希尔德尔夫感到极其担忧。希尔德尔夫的攻城坦克损毁后，徒步闯入了丹莫罗崎岖的山峦。他当时正在寻找一种制造强力爆破火药所必需的稀有矿石，但数日过去了，山峰间却只回荡着令人不安的咆哮声。",h="驾驶员塞克·锤足为他的战友莫里·希尔德尔夫感到极其担忧。希尔德尔夫的攻城坦克损毁后，徒步闯入了丹莫罗崎岖的山峦。他当时正在寻找一种制造强力爆破火药所必需的稀有矿石，但数日过去了，山峰间却只回荡着令人不安的咆哮声。",kw={"爆破火药","准将背心","丹莫罗","失踪驾驶员","莫里·希尔德尔夫","驾驶员塞克·锤足","攻城坦克"},ang={["profession:Engineering"]="希尔德尔夫的远征凸显了矮人为了提炼高效炸药和爆破火药，对挥发性矿物的不懈追求。",["race:Dwarf"]="一位熟练的攻城坦克驾驶员丧生于野兽之口令人痛心，这再次印证了即便是卡兹莫丹的后院，依然潜伏着致命的危险。"},sec={{t="中断的搜寻",b="矮人的攻城坦克是强悍的战争机器，但即使是铁制的履带，也难以应对丹莫罗那险峻崎岖的山脊。驾驶员莫里·希尔德尔夫在搜寻制造优质爆破火药所需的稀有矿石时，强行驱使坦克冲上陡坡，导致机械损毁。希尔德尔夫并未因抛锚而气馁，他命令同伴驾驶员塞克·锤足留守并看管损毁的机器，自己则徒步向更加寒冷的荒野深处进发。"},{t="雪中的回响",b="数日过去了，希尔德尔夫仍未归营。深夜时分，岩石峭壁间开始回荡着奇怪而凶残的野兽咆哮声，这让锤足原本轻微的不安转变为逐渐蔓延的恐惧。虽然希尔德尔夫以铁石心肠著称，但在没有机械装甲保护、也没有重火力支援的情况下，要在丹莫罗严寒的高地应对潜行的捕食者，这无疑是一场危险的赌博。"},{t="残酷的发现",b="沿着希尔德尔夫留下的路径爬上山坡，看到的并非被困的侦察兵，而是一场冻结的悲剧。这名矮人的遗骸暴露在自然环境中，已被山中的食腐动物撕咬得支离破碎。他僵硬的手中紧紧攥着草草写就的笔记，而他残破的躯体上依然披着那件准将背心，证实这位勇敢的攻城工程师已经遭遇了不幸，死于非命。"}},faq={{q="为什么驾驶员希尔德尔夫要独自前往荒野？",a="希尔德尔夫正在寻找制造优质矮人爆破火药所需的稀有矿石。当他的攻城坦克在陡峭的山坡上损毁时，他选择徒步深入峭壁，而不是放弃勘探。",al={"希尔德尔夫离开的原因","希尔德尔夫在做什么","驾驶员希尔德尔夫的任务"}},{q="是谁让你去寻找希尔德尔夫的？",a="希尔德尔夫的朋友兼攻城坦克操作员，驾驶员塞克·锤足请求旅行者进行调查。他奉命留守以保护受损的机械，而希尔德尔夫则先行一步去侦察。",al={"谁发放任务","失踪驾驶员任务发布者"}},{q="希尔德尔夫的攻城坦克发生了什么事？",a="希尔德尔夫在寻找矿石时，试图驾驶他的重型机械直接冲上一道陡峭冰冷的坡地，导致机械结构损坏，被困在了雪地里。",al={"损毁的攻城坦克","坦克损坏的原因"}},{q="是什么杀死了驾驶员希尔德尔夫？",a="锤足在山中听到了野兽的咆哮声，并为希尔德尔夫感到担忧。追寻他的踪迹便能揭开这位驾驶员的命运。",al={"希尔德尔夫的杀手","驾驶员如何死亡","谁杀了希尔德尔夫"}},{q="在希尔德尔夫的遗骸处发现了什么证据？",a="遗骸手中紧握着一本莫里·希尔德尔夫草草记录的笔记，身上仍穿着一件保存完好的准将背心。",al={"希尔德尔夫的证据","希尔德尔夫遗骸上的物品","死亡证明"}},{q="发现希尔德尔夫的遗体后会发生什么？",a="找到希尔德尔夫揭示了他搜寻过程中发生的事情。后续的调查将根据在那里发现的证据继续进行。",al={"失踪驾驶员下一步","复仇任务"}}},fp="14,195,18.266.0,18.273.0,16.281.1,51.200.0,35.183.0,41.148.0,27.118.1,42.123.1,49.116.1"}
P.entries["quest:420"] = {n="森内尔的观察站",s="这项任务完成了寒脊山谷的一条侦察线，将格瑞林的报告穿过充斥着穴居人的通道，送达给他在卡拉诺斯的兄弟森内尔。它将安威玛尔与世隔绝的训练场与丹莫罗面临的更广泛的威胁连接了起来。通过森内尔坦诚的接待，旅行者们第一次窥见了前线侦察兵与铁炉堡议会之间酝酿的政治摩擦。",h="这项任务完成了寒脊山谷的一条侦察线，将格瑞林的报告穿过充斥着穴居人的通道，送达给他在卡拉诺斯的兄弟森内尔。它将安威玛尔与世隔绝的训练场与丹莫罗面临的更广泛的威胁连接了起来。通过森内尔坦诚的接待，旅行者们第一次窥见了前线侦...",kw={"寒脊山谷","丹莫罗","格瑞林·白须","格瑞林的报告","铁炉堡议会","卡拉诺斯","巡山人萨鲁斯","森内尔·白须","穴居人"},ang={["faction:Alliance"]="在暴风城因国内纷争而瘫痪，无法向北方盟友提供援助的时候，帮助侦察兵协调情报工作能确保丹莫罗的安全。",["race:Dwarf"]="从受到保护的训练山谷进入卡拉诺斯，标志着你正式投身于卡兹莫丹的防务，也让你初步体会到前线侦察兵是如何与铁炉堡谨慎的议会发生冲突的。",["race:Gnome"]="穿过通道前往卡拉诺斯，让流亡的侏儒们更接近丹莫罗的主要枢纽，以及支持他们矮人东道主的持续努力。"},sec={{t="穿过通往卡拉诺斯的隧道",b="在格瑞林·白须从霜鬃巨魔手中找回被偷的日记后，他为他的兄弟森内尔准备了一份关于山谷威胁的详细报告。驻守在寒脊山谷出口的巡山人萨鲁斯，将这份急件委托给路过的冒险者。离开相对封闭的新手谷地意味着必须闯过穿过大山的隧道，这里最近被暴力的穴居人占领，它们伏击所有往来的行人。突破重围的旅行者将抵达丹莫罗中部白雪皑皑的高速公路上，沿着主路直接进入舒适的卡拉诺斯枢纽。"},{t="暴躁的欢迎与议会政治",b="在卡拉诺斯的雷酒酿制厂里取暖的森内尔·白须，用粗鲁的巡山人好客之道迎接了新人。读完格瑞林的调查结果后，森内尔对他兄弟激进的措辞嗤之以鼻。格瑞林大肆引用国王麦格尼·铜须的名义来要求采取紧急行动，森内尔指出这种自信的策略必然会激怒顽固的铁炉堡议会。森内尔承认由于严寒，他自己在提交观察报告方面落后了，但格瑞林的急件让他重新回到了岗位上，并进一步展开了对雪原各地敌对势力的监视工作。"}},faq={{q="为什么巡山人萨鲁斯要让旅行者去递送报告？",a="巡山人萨鲁斯被派驻在寒脊山谷的隧道口负责防线，抵御好战的穴居人。他无法擅离职守，所以当有能力的冒险者经过时，他便委托他们将格瑞林的急件安全地送到卡拉诺斯。",al={"为什么萨鲁斯找你","萨鲁斯信使","谁发布了这个任务"}},{q="森内尔·白须是谁？",a="森内尔·白须是一位矮人侦察兵，也是格瑞林·白须的兄弟。他驻扎在卡拉诺斯，负责整理当地威胁的侦察报告，并将其转交给铁炉堡的高级指挥部。",al={"森内尔是谁","森内尔·白须 卡拉诺斯","森内尔背景"}},{q="格瑞林的报告里写了什么？",a="这份报告汇编了格瑞林关于霜鬃巨魔在寒脊山谷的活动和入侵情况的调查结果。报告写得很紧急，并引用了国王麦格尼·铜须的权威，要求当局提供增援并给予关注。",al={"报告里写了什么","格瑞林报告内容","格瑞林报告剧情"}},{q="为什么森内尔说格瑞林的报告会激怒议会？",a="格瑞林强硬地引用国王麦格尼的名义来要求采取行动。在铁炉堡的政治中，依赖皇家法令可能会绕过或挑战矮人议会的官僚权威和尊严，这会让那些更喜欢正式审议的议员们感到恼火。",al={"议会不悦","森内尔 铁炉堡议会","为什么议会很生气"}},{q="寒脊山谷和卡拉诺斯之间的隧道为什么很危险？",a="一族石颚穴居人最近从深处的地下裂缝中涌出，占领了山中隧道，并袭击任何试图通过的矮人旅行者、商人和信使。",al={"寒脊隧道危险","穴居人隧道 丹莫罗","为什么隧道里有穴居人"}},{q="递送这份消息后，道路通向哪里？",a="抵达卡拉诺斯后，冒险者们将被纳入丹莫罗的更大范围防御体系中。森内尔·白须随后会请求帮助调查更多的霜鬃巨魔和穴居人的威胁，而城镇领导人则会将援助引向烈酒村、铁炉堡以及偏远的农场。",al={"森内尔之后做什么","森内尔的观察后的下一个任务","卡拉诺斯通向哪里"}}},fp="20,181,30.294.0,36.428.0,63.192.0,24.168.0,27.205.0,70.174.0,66.162.0,55.218.0"}
P.entries["quest:421"] = {n="证明你的价值",s="“证明你的实力”是部落的一项新手任务，由银松森林瑟伯切尔的达拉尔·道恩维沃尔提供。为了协助被遗忘者对抗南部人类和矮人领地的行动，冒险者需要清除在路边徘徊的野性狼人。这标志着揭开大法师阿鲁高所造成的奥术余波的第一步。",h="“证明你的实力”是部落的一项新手任务，由银松森林瑟伯切尔的达拉尔·道恩维沃尔提供。为了协助被遗忘者对抗南部人类和矮人领地的行动，冒险者需要清除在路边徘徊的野性狼人。这标志着揭开大法师阿鲁高所造成的奥术余波的第一步。",kw={"阿鲁高","达拉尔·道恩维沃尔","月怒白头狼人","证明你的实力","瑟伯切尔","影牙城堡","银松森林","狼人"},ang={["class:Mage"]="达拉尔·道恩维沃尔的任务是对施法者们发出的严厉警告，提醒他们鲁莽使用召唤魔法所带来的灾难性风险，而阿鲁高就是最典型的例子。",["faction:Horde"]="平定银松森林的荒野确保了部落能够拥有一条通往洛丹伦南部的通畅军事要道。",["race:Undead"]="对于被遗忘者来说，清理银松森林对于确保幽暗城的边界安全以及消除达拉然失败后遗留的威胁至关重要。"},sec={{t="确保南部走廊的安全",b="希尔瓦娜斯·风行者女士和她的恐惧魔王副官瓦里玛萨斯的目标是确保提瑞斯法林地以南地区的控制权，包括人类和矮人的飞地。然而，穿过银松森林的道路依然危险重重。被遗忘者们发现他们的补给线和前哨基地受到了潜伏在松树覆盖的山丘中的月怒狼人的威胁，而非一个开放的集结地。"},{t="阿鲁高的祸害",b="这些野兽的出现并非自然现象。达拉尔·道恩维沃尔直接将矛头指向了阿鲁高，这位来自达拉然的失势前法师在天灾入侵期间向该地区释放了来自异界的狼人。阿鲁高此后占据了影牙城堡，任由他创造的野性生物横行森林。在达拉尔让士兵深入调查阿鲁高的巫术之前，新兵们必须通过猎杀最近的月怒白头狼人来展示他们的武力。"}},faq={{q="达拉尔·道恩维沃尔是谁？",a="达拉尔·道恩维沃尔是一名驻扎在瑟伯切尔的被遗忘者法师。他负责监督对抗银松森林中魔法威胁的工作，主要集中在消灭大法师阿鲁高和他的野性狼人群上。",al={"达拉尔·道恩维沃尔","谁给予证明你的实力任务","瑟伯切尔任务发布者"}},{q="月怒白头狼人在哪里？",a="这些白头狼人在瑟伯切尔山下、大路旁边的树林和荒废的家园中徘徊。",al={"白头狼人在哪里","月怒白头狼人位置","白头狼人聚集点"}},{q="为什么部落关心银松森林里的狼人？",a="银松森林是连接幽暗城与南部领土的关键战略走廊。希尔瓦娜斯女士和瓦里玛萨斯需要安全的通道来向南部投射力量，因此这些极具攻击性的狼人群成了无法容忍的隐患。",al={"为什么要杀狼人","被遗忘者的狼人问题","为什么要清理银松森林"}},{q="阿鲁高与这些生物有什么联系？",a="大法师阿鲁高在为达拉然效力时召唤了异维度的狼人来对抗天灾军团。召唤出的野兽变成了野性生物，让阿鲁高在愧疚中发疯，随后他撤退到影牙城堡并开始助长这种诅咒。",al={"狼人是怎么到这里的","阿鲁高与狼人的联系","谁召唤了狼人"}},{q="向达拉尔证明自己的实力后会发生什么？",a="一旦你通过击杀白头狼人证明了你的战斗能力，达拉尔·道恩维沃尔就会直接让你参与到他铲除阿鲁高势力的行动中，开始名为“Arugal's Folly”的多阶段任务链。",al={"后续任务","证明你的实力之后做什么","arugal's folly起始"}},{q="联盟会参与这个任务吗？",a="不。“证明你的实力”是仅供部落完成的任务，在被遗忘者的哨所瑟伯切尔领取。",al={"联盟能做证明你的实力吗","联盟在银松森林"}}},fp="16,249,30.327.0,15.422.0,24.163.0,43.142.0,51.183.0,47.208.0,47.185.0,39.86.0"}
P.entries["quest:422"] = {n="阿鲁高的愚行",s="由位于瑟伯切尔的达拉尔·道恩维沃尔指派，此任务要求被遗忘者特工从附近的农场取回阿鲁高最早期的法术书。揭开狼人诅咒背后的魔法秘密，对于被遗忘者将其反制这位疯狂法师并稳固银松森林的局势至关重要。找回“阿鲁高的拯救”是揭开影牙城堡潜伏威胁的第一步。",h="由位于瑟伯切尔的达拉尔·道恩维沃尔指派，此任务要求被遗忘者特工从附近的农场取回阿鲁高最早期的法术书。揭开狼人诅咒背后的魔法秘密，对于被遗忘者将其反制这位疯狂法师并稳固银松森林的局势至关重要。找回“阿鲁高的拯救”是揭开影牙...",kw={"阿鲁高","达拉尔·道恩维沃尔","尘封的法术书","肯瑞托","阿鲁高的拯救","瑟伯切尔","银松森林","狼人"},ang={["class:Mage"]="对于被遗忘者法师而言，研究阿鲁高的工作是一个深刻的教训，展示了若在缺乏纪律或适当预见的情况下使用魔法，会造成多么灾难性的后果。",["faction:Horde"]="部落在银松森林的存在受到了野兽的挑战；遏制阿鲁高对于建立从洛丹伦出发的稳定补给线至关重要。",["race:Undead"]="银松森林是幽暗城的西方盾牌。从狂暴的狼人手中夺回这片土地，对于稳固黑暗女王的边境至关重要。"},sec={{t="法师的嘲弄",b="达拉尔·道恩维沃尔，一位居住在瑟伯切尔地穴中的雄心勃勃的被遗忘者法师，对大法师阿鲁高毫无敬意。在道恩维沃尔眼中，阿鲁高不过是一个平庸的修行者，他居然能进入肯瑞托简直令人费解，而且他的魔法造诣看起来也十分业余。然而，现在在银松森林游荡的那些可怕野兽却不容忽视。为了打破阿鲁高对该地区的控制，道恩维沃尔打算解构那些将狼人释放到洛丹伦的法术。"},{t="农场的遗留物",b="在占据影牙城堡之前，阿鲁高曾居住在河桥北面一处偏僻的麦田农场。死亡猎手斥候在农舍二楼发现了被遗弃且保存完好的法术书，但因为有徘徊的野兽，他们无法回收这些书卷。仔细搜寻这些尘封的魔典，便可获得名为“阿鲁高的拯救”的咒语，这揭示了在银松森林蔓延的非自然诅咒的关键内幕。"}},faq={{q="达拉尔·道恩维沃尔是谁？",a="达拉尔·道恩维沃尔是一名驻扎在银松森林瑟伯切尔的被遗忘者法师。他忠于希尔瓦娜斯·风行者，致力于剖析并反制大法师阿鲁高的魔法实践，以便为被遗忘者夺回该领土。",al={"达拉尔·道恩维沃尔","谁给予arugal's folly任务","瑟伯切尔法师"}},{q="什么是“阿鲁高的拯救”？",a="这是阿鲁高被弃书卷中记载的一道特定法术，可以追溯到他住在桥北农场的时候。达拉尔·道恩维沃尔需要这道咒语来分析阿鲁高研究的奥术基础。",al={"阿鲁高的拯救","那本书是什么"}},{q="阿鲁高的旧法术书在哪里？",a="这些尘封的法术书存放在银松森林北部河桥以北的一处废弃农舍的二楼。",al={"书在哪里","尘封的法术书位置","农舍里的书"}},{q="为什么道恩维沃尔瞧不起阿鲁高？",a="道恩维沃尔认为阿鲁高是一个低劣的巫师，其奥术造诣肤浅且一眼就能看穿。他觉得肯瑞托居然在达拉然接纳阿鲁高加入他们的行列，简直令人费解。",al={"为什么道恩维沃尔憎恨阿鲁高","道恩维沃尔对阿鲁高的看法"}},{q="为什么这项任务对被遗忘者很重要？",a="阿鲁高制造的狼人屠杀被遗忘者部队，并威胁到他们对银松森林的控制。通过分析他的法术，被遗忘者希望消除这一威胁，并为黑暗女王确保该地区的安全。",al={"被遗忘者对阿鲁高的兴趣","为什么被遗忘者在意阿鲁高"}},{q="当你触碰那些尘封的法术书时会发生什么？",a="惊动这些魔典会引来潜伏在农舍内的月怒狼人，它会立即攻击任何试图染指阿鲁高遗留研究的人。",al={"法术书陷阱","月怒黑行者攻击"}}},fp="14,332,17.415.0,25.397.1,24.207.0,29.212.0,42.150.0,40.164.0,43.189.0,49.138.0"}
P.entries["quest:423"] = {n="阿鲁高的愚行",s="这项任务派遣被遗忘者特工去从游荡在银松森林的月怒狼人身上收集附魔镣铐。达拉尔·道恩维沃尔正在分析阿鲁高的笔记，旨在弄清这位叛变法师是如何人为地增强他不稳定的魔法的。研究这些束缚物能让被遗忘者更进一步地瓦解困扰该地区的狼人威胁。",h="这项任务派遣被遗忘者特工去从游荡在银松森林的月怒狼人身上收集附魔镣铐。达拉尔·道恩维沃尔正在分析阿鲁高的笔记，旨在弄清这位叛变法师是如何人为地增强他不稳定的魔法的。研究这些束缚物能让被遗忘者更进一步地瓦解困扰该地区的狼人...",kw={"阿鲁高","达拉尔·道恩维沃尔","达拉然","黑魂","贪食者","肯瑞托","瑟伯切尔","镣铐","银松森林","狼人"},ang={["class:Mage"]="被遗忘者法师们能理解达拉尔刻薄的专业批评：阿鲁高通过物理附魔束缚物引导力量，以此弥补了他糟糕的奥术基础。",["faction:Horde"]="清理银松森林的树林可以确保连接提瑞斯法与更南部地区的高级道路交通安全。",["race:Undead"]="对于被遗忘者来说，从野性狼人手中夺回银松森林对于保护提瑞斯法林地的南部边界并巩固希尔瓦娜斯女王的领地至关重要。"},sec={{t="捷径",b="在检查了阿鲁高被找回的研究资料后，达拉尔·道恩维沃尔对他曾经的同僚表达了极度的蔑视。据达拉尔所说，阿鲁高根本不配在达拉然任职，更不用说在王国最危急的时刻操纵高阶奥术了。为了弥补平庸的才华，阿鲁高依赖附魔的遗物和装置来增强并束缚他召唤的狼人野兽。达拉尔需要这些物品的实体样本，来剖析维持这些怪物存在的魔法纽带。"},{t="月怒束缚物",b="银松森林中受到诅咒的居民变成了月怒狼人，它们在森林中游荡，身上带着阿鲁高附魔束缚物的实体表现。月怒贪食者和月怒黑魂在瑟伯切尔的北部和东部地区潜行。因为金属中编织的残余奥术能量而备受珍视，它们沉重的镣铐成为道恩维沃尔针对影牙城堡进行反制研究的关键样本。"}},faq={{q="达拉尔·道恩维沃尔为什么要狼人镣铐？",a="达拉尔断定阿鲁高利用附魔物品来弥补薄弱的魔法才华。通过检查月怒贪食者和黑魂佩戴的附魔镣铐，达拉尔希望提取其中的魔法能量，并揭开阿鲁高如何指挥他的野兽的秘密。",al={"为什么要收集镣铐","狼人镣铐的目的","达拉尔·道恩维沃尔的计划"}},{q="阿鲁高在银松森林发疯前是谁？",a="阿鲁高曾是达拉然的一名法师。据达拉尔·道恩维沃尔说，阿鲁高在肯瑞托中被视为才华平庸，但在第三次战争期间，他转向了禁忌的异界召唤，以释放狼人对抗天灾军团。",al={"阿鲁高的背景故事","阿鲁高是谁","阿鲁高与达拉然"}},{q="月怒贪食者和黑魂在哪里可以找到？",a="这些野蛮的狼人在银松森林瑟伯切尔的北部和东部的荒野中游荡，在古老遗迹和森林小径附近潜行。",al={"去哪里找贪食者","黑魂的位置","银松森林的狼人位置"}},{q="为什么被遗忘者如此关注阿鲁高？",a="阿鲁高的狼人横行银松森林，直接威胁到了瑟伯切尔以及被遗忘者在提瑞斯法林地以南的领土控制权。中和他的魔法对于保卫北部王国至关重要。",al={"被遗忘者的狼人威胁","为什么要对抗阿鲁高"}},{q="达拉尔·道恩维沃尔怎么看达拉然？",a="达拉尔对他达拉然的前同僚怀有苦涩的蔑视，认为他们是一群傻瓜，竟信任阿鲁高并给予他无法胜任的职责。",al={"达拉尔对达拉然的评价","达拉尔谈论肯瑞托"}},{q="阿鲁高是否与天灾军团合作？",a="不。阿鲁高最初召唤狼人是为了对抗天灾军团以保卫达拉然。然而，这些野兽变得狂野并导致他精神失常，最终使他将影牙城堡据为己有。",al={"阿鲁高与天灾军团的联盟","阿鲁高是天灾军团吗"}}},fp="14,233,17.386.0,21.309.0,47.170.0,48.211.0,52.130.0,46.155.0,44.130.0,35.158.0"}
P.entries["quest:424"] = {n="阿鲁高的愚行",s="“Arugal's Folly”是瑟伯切尔在银松森林持续对抗那位疯狂大法师影响的战役中的一项关键任务。达拉尔·道恩维沃尔派遣部落的冒险者潜入埃利姆矿洞，处决被腐蚀的工头——“苍白的”格里姆森，从而为瓦里玛萨斯的部队获取重要的矿产资源。",h="“Arugal's...",kw={"arugal's folly","达拉尔·道恩维沃尔","埃利姆矿洞","苍白的格里姆森","瑟伯切尔","银松森林","瓦里玛萨斯"},ang={["class:Mage"]="研究阿鲁高失控的咒语和变形魔法如何渗入矿井，是对魔法滥用后果的一次惨痛教训。",["profession:Mining"]="埃利姆矿洞深处的矿脉在各处丘陵中备受觊觎，一旦清除敌对的腐化工人们，就能提供宝贵的矿石。",["race:Undead"]="从阿鲁高的疯狂仆从手中夺取的每一个战略据点，都能为被遗忘者提供原始金属，以加强他们新生的国家对抗生者和天灾军团。"},sec={{t="确保深处安全",b="在调查大法师阿鲁高对森林释放的黑暗魔法时，达拉尔·道恩维沃尔收到了来自被遗忘者暗影猎手的紧急情报。从影牙城堡蔓延开来的野性巫术已经到达了位于东南部丘陵的埃利姆矿洞，狼人如今在那里筑巢。这座矿洞拥有幽暗城军事化建设所需的关键矿石，但目前的居住者使其完全无法开采。"},{t="斩首示众",b="在受侵染的矿坑深处潜伏着“苍白的”格里姆森，这位被玷污的工头指挥着地下隧道中的疯狂残党。道恩维沃尔下令进行一次直接的斩首行动：只要击杀格里姆森并将他的头颅带回瑟伯切尔，矿坑中的狼人就会失去领袖，从而允许被遗忘者的劳工为瓦里玛萨斯领主夺回这处挖掘场。"}},faq={{q="谁是“苍白的”格里姆森？",a="“苍白的”格里姆森是埃利姆矿洞的工头。和银松森林南部许多劳工和居民一样，他受到大法师阿鲁高实验所散发出的腐蚀性魔法影响，堕落成了一个看管受侵染地下巢穴的扭曲生物。",al={"格里姆森","谁是格里姆森","埃利姆工头"}},{q="埃利姆矿洞在哪里？",a="埃利姆矿洞位于银松森林中瑟伯切尔东南部的崎岖丘陵中。它的隧道深挖进山坡，里面挤满了狼人。",al={"埃利姆矿洞位置","埃利姆矿洞在哪里","在哪里找到格里姆森"}},{q="瓦里玛萨斯为什么关心一个采矿作业？",a="瓦里玛萨斯负责监督被遗忘者势力的战略扩张。来自埃利姆矿洞的高产铁矿和石料对于武装部队和加固洛丹伦各处的堡垒至关重要。",al={"瓦里玛萨斯为什么想要矿洞","瓦里玛萨斯的意图"}},{q="格里姆森被杀后会发生什么？",a="达拉尔·道恩维沃尔会将格里姆森的头颅作为胜利的证明，并将注意力转回主要威胁上，准备直接打击阿鲁高势力渗透的核心。",al={"arugal's folly之后","接下来做什么","后续任务"}},{q="是什么魔法腐蚀了矿洞？",a="大法师阿鲁高在银松森林释放了狂野的异界魔法和狼人诅咒。这种魔法蔓延到了埃利姆矿洞，玷污了工头“苍白的”格里姆森，并导致矿坑被狼人占据。",al={"矿洞里的阿鲁高魔法","什么腐蚀了埃利姆","矿洞诅咒"}},{q="达拉尔·道恩维沃尔提到的暗影猎手是谁？",a="暗影猎手是被遗忘者军队的秘密情报和侦察部门，他们在瑟伯切尔等哨站运作，负责监视敌军动向和地区异常情况。",al={"暗影猎手","谁是暗影猎手"}}},fx={["8e7515d1"]={q="达拉尔·道恩维沃尔为什么要杀死苍白的格瑞姆森？",a="达拉尔在研究阿鲁高的黑暗附魔时，也必须听命于瓦里玛萨斯。瓦里玛萨斯要求夺取埃利姆矿洞，为被遗忘者在银松森林的军事推进提供资源。阿鲁高蔓延的魔法污染了矿洞，也腐化了工头苍白的格瑞姆森。杀死格瑞姆森就能瓦解他对矿场的控制，为被遗忘者 확보重要的矿石和金属来源，同时也让达拉尔继续得到恐惧魔王的赏识。",al={"为什么杀格瑞姆森","达拉尔·道恩维沃尔的动机","达拉尔为什么要矿洞"}},["49f6b035"]={q="格瑞姆森的头颅有什么用？",a="达拉尔·道恩维沃尔需要格瑞姆森被砍下的头颅，作为这名受污染工头已死的确凿证据。瓦里玛萨斯要求迅速取得战果，达拉尔不能让人怀疑埃利姆矿洞是否已清除了被腐化的监工，是否已经可以接管。",al={"为什么拿格瑞姆森的头","格瑞姆森头颅的用途","格瑞姆森头颅任务"}}},fp="14,239,19.372.0,16.281.0,24.210.0,36.149.0,51.176.0,36.155.0,38.205.0,55.176.0"}
P.entries["quest:425"] = {n="邪恶的伊瓦",s="“伊瓦的头颅”是银松森林中的一个任务，标志着死亡猎手兰妮·尤瑞克和奎恩·尤瑞克所进行的侦察任务已进入高潮。被困在名为伊瓦农场的农舍中，兰妮请求部落的旅行者消灭凶残的食尸鬼伊瓦的头颅，以便奎恩能从重伤中恢复过来，并完成他们对高级执行官哈德瑞克的报告。",h="“伊瓦的头颅”是银松森林中的一个任务，标志着死亡猎手兰妮·尤瑞克和奎恩·尤瑞克所进行的侦察任务已进入高潮。被困在名为伊瓦农场的农舍中，兰妮请求部落的旅行者消灭凶残的食尸鬼伊瓦的头颅，以便奎恩能从重伤中恢复过来，并完成他们...",kw={"死亡猎手","食尸鬼","哈德瑞克","伊瓦","伊瓦农场","伊瓦的头颅","奎恩·尤瑞克","兰妮·尤瑞克","瑟伯切尔"},ang={["class:Rogue"]="协助死亡猎手展示了在被贪婪的天灾恐怖生物出其不意地袭击时，隐秘侦察所面临的危险。",["faction:Horde"]="通过清理像伊瓦这样的天灾余孽，部落军队保护了被遗忘者在洛丹伦的战争努力所需的关键补给线和战略要地。",["race:Undead"]="该任务强调了死亡猎手危险的职责，展示了被困在敌后的落单被遗忘者侦察兵必须如何依靠流浪的勇士。"},sec={{t="出轨的任务",b="兄妹兰妮·尤瑞克和奎恩·尤瑞克被死亡猎手派往银松森林各地进行侦察，以向瑟伯切尔的高级执行官哈德瑞克复命。当他们穿过森林北部的一处农舍时，他们的侦察工作戛然而止，并遭遇了暴力袭击，埋伏他们的正是名为伊瓦的头颅的凶恶食尸鬼。"},{t="谷仓中的威胁",b="尽管侦察兵们设法保住了性命，但奎恩在对峙中受了重伤。即使在接受了由森林野兽制成的炼金药剂后，奎恩仍然虚弱得无法行军。兰妮知道伊瓦正在附近的谷仓徘徊，等待着她的防备松懈，于是她请求部落的冒险者冲进谷仓，斩下伊瓦的头颅，并永久确保农场的安全。"}},faq={{q="谁是伊瓦的头颅？",a="伊瓦的头颅是一个潜伏在银松森林北部的危险天灾食尸鬼。伊瓦农场曾经是他自己的农场；他和他的大部分家人及工人都倒在了天灾军团手下，现在他潜伏在那里，伏击过往的路人并残害被遗忘者侦察兵。",al={"谁是伊瓦","伊瓦的头颅背景故事","伊瓦的头颅是什么"}},{q="在哪里可以找到伊瓦的头颅？",a="伊瓦潜伏在伊瓦农场内那座破败的谷仓里，位于兰妮·尤瑞克和奎恩·尤瑞克避难的那座荒废农舍的北面。",al={"伊瓦位置","伊瓦在哪里","伊瓦的头颅谷仓"}},{q="谁是兰妮和奎恩·尤瑞克？",a="兰妮和奎恩·尤瑞克是被遗忘者兄妹，都是死亡猎手。他们被高级执行官哈德瑞克派去绘制和调查银松森林内的敌军活动，随后遭到了伊瓦的伏击。",al={"谁是兰妮·尤瑞克","尤瑞克兄妹","谁是奎恩·尤瑞克"}},{q="为什么兰妮请求冒险者杀死伊瓦？",a="奎恩在最初的遭遇中受了重伤，目前仍在康复中。兰妮必须留在她哥哥身边保护他免受天灾军团的突袭，这使她无法亲自去猎杀那个食尸鬼。",al={"为什么要杀伊瓦","为什么兰妮不战斗"}},{q="谁接收关于伊瓦死亡的报告？",a="高级执行官哈德瑞克，即驻守在银松森林瑟伯切尔的军事指挥官，将接收侦察兵的正式侦察日志，兰妮承诺在日志中称赞冒险者的协助。",al={"谁是哈德瑞克","谁派出的尤瑞克兄妹"}},{q="伊瓦被杀后会发生什么？",a="消灭伊瓦的头颅结束了死亡猎手在伊瓦农场的苦难。随着直接威胁的消除，奎恩有了治愈所需的时间，兄妹俩随后将完成他们对森林的勘测。",al={"伊瓦之后发生什么","伊瓦之后的任务"}}},fp="13,216,18.234.0,22.291.0,21.229.0,33.124.0,30.189.0,45.165.0,40.181.0,33.168.1"}
P.entries["quest:426"] = {n="磨坊告急",s="在这项由布瑞尔的亡灵卫兵迪林格尔下达的任务中，被遗忘者士兵被派往附近的阿加曼德磨坊，以打破天灾军团的立足点。毫无思想的亡灵在破败的风车间集结，威胁着要在距离提瑞斯法林地定居点极近的地方建立前哨基地。为了阻止这个集结地，新兵们必须粉碎那些骷髅士兵和白骨施法者的队伍。",h="在这项由布瑞尔的亡灵卫兵迪林格尔下达的任务中，被遗忘者士兵被派往附近的阿加曼德磨坊，以打破天灾军团的立足点。毫无思想的亡灵在破败的风车间集结，威胁着要在距离提瑞斯法林地定居点极近的地方建立前哨基地。为了阻止这个集结地，新...",kw={"阿加曼德磨坊","焦黑颅骨","布瑞尔","黑眼白骨施法者","亡灵卫兵迪林格尔","刻痕肋骨","天灾军团","磨坊沦陷","提瑞斯法林地"},ang={["class:Warrior"]="在阿加曼德磨坊与武装骷髅的交锋，是对抗那些不知疼痛、毫不留情的顽敌的一场残酷的实战考验。",["faction:Horde"]="守住提瑞斯法林地对于确保部落在洛丹伦北部的唯一立足点至关重要，因此清除天灾军团的集结地是一项重要的战术优先事项。",["race:Undead"]="对于被遗忘者而言，将天灾军团驱逐出阿加曼德磨坊意义深远：这不仅保护了他们的新领土，也粉碎了那些曾经奴役他们的、巫妖王的盲从奴隶。"},sec={{t="迫在眉睫的磨坊威胁",b="阿加曼德磨坊曾是提瑞斯法林地农业的中心，但在第三次战争之后，这里的风车俯瞰着远比农作物更凄惨的景象。受巫妖王奴役的天灾军团已开始在磨坊区域集结。如果这些毫无思想的傀儡成功控制了磨坊，他们将拥有一个稳固的作战基地，以此为跳板深入提瑞斯法，直接打击初生的被遗忘者领地。"},{t="毁灭的证明",b="亡灵卫兵迪林格尔从不浪费时间在情感上。为了加固布瑞尔并巡逻该地区，迪林格尔命令新兵猎杀拨浪鼓骨架和碎颅士兵，以及黑眼白骨施法者。通过要求上交刻痕肋骨和焦黑颅骨作为他们毁灭的证明，迪林格尔确保了骷髅军队正被物理摧毁，并在他们的攻势真正开始前，将这些毫无思想的残党赶回瘟疫之地。"}},faq={{q="为什么天灾军团要在阿加曼德磨坊集结？",a="天灾军团正试图在提瑞斯法西部建立一个前沿集结地。如果他们能在阿加曼德磨坊站稳脚跟，就能协调对林地深处的突袭，并直接威胁到布瑞尔等附近的被遗忘者定居点。",al={"为什么阿加曼德磨坊","磨坊里的天灾军团","为何争夺磨坊"}},{q="亡灵卫兵迪林格尔是谁？",a="亡灵卫兵迪林格尔是驻扎在布瑞尔的被遗忘者哨兵。他负责协调针对提瑞斯法林地地区性威胁的战术打击，特别是针对不断侵蚀的天灾军团和威胁道路的敌对豺狼人团伙。",al={"亡灵卫兵迪林格尔背景故事","迪林格尔是谁","布瑞尔的迪林格尔"}},{q="阿加曼德磨坊位于哪里？",a="阿加曼德磨坊坐落在提瑞斯法林地西部主干道的北侧。从布瑞尔向西穿过河上的桥，并沿北岔路前行，即可直达那些标志性的废弃风车。",al={"阿加曼德磨坊在哪里","磨坊位置","如何前往磨坊"}},{q="为什么迪林格尔想要肋骨和颅骨？",a="迪林格尔需要切实的证据来证明天灾军团的前线已被击溃。带回骷髅步兵的刻痕肋骨和白骨施法者的焦黑颅骨，确保了敌军已经被重创并削减。",al={"刻痕肋骨与焦黑颅骨","为何要收集肋骨和颅骨"}},{q="这里的被遗忘者和天灾军团之间是什么关系？",a="被遗忘者是摆脱了巫妖王精神控制的亡灵。而天灾军团仍然是受巫妖王意志束缚的、盲从的奴隶，他们积极寻求消灭被遗忘者，并为他们的主人夺回洛丹伦。",al={"被遗忘者对阵天灾军团","为何要与同为亡灵的敌人作战"}},{q="清理掉这些天灾军团后会发生什么？",a="清理步兵只是对抗阿加曼德磨坊入侵的第一步。迪林格尔和亡灵卫兵们将继续深入磨坊，铲除盘踞在那里的指挥官和黑暗势力。",al={"what comes next","磨坊沦陷之后"}}},fp="17,222,29.360.0,20.368.0,47.190.0,28.188.0,36.170.0,40.177.0,67.197.0,42.210.0"}
P.entries["quest:4265"] = {n="逃离虫巢",s="你在痛苦深渊发现的虫茧在你触碰时裂开了，里面是一个暗夜精灵，他还活着，但处于极度惊恐之中。他就是失踪的信使拉沙尔。既然他已经从祖卡什虫巢中获救，必须把拉沙尔生还的消息告诉羽月要塞的基恩诺·火花。",h="你在痛苦深渊发现的虫茧在你触碰时裂开了，里面是一个暗夜精灵，他还活着，但处于极度惊恐之中。他就是失踪的信使拉沙尔。既然他已经从祖卡什虫巢中获救，必须把拉沙尔生还的消息告诉羽月要塞的基恩诺·火花。",kw={"信使","羽月要塞","菲拉斯","基恩诺·火花","虫茧","拉沙尔","痛苦深渊","祖卡什"},sec={{t="脱离虫茧",b="当你把他从虫茧中扶下来时，这个暗夜精灵动了一下。他自称是拉沙尔，他说自己被虫子袭击后就在茧里瘫痪了。他看起来很健康，但依然处于极度惊恐之中。他问你是不是要塞派来的。"},{t="给羽月要塞的消息",b="基恩诺·火花正在羽月要塞等候，必须告诉他拉沙尔还活着且安然无恙。"},{t="回到要塞",b="拉沙尔已经抵达要塞并告诉了基恩诺发生的一切。基恩诺说整个要塞都无法表达对你的感激之情，如果没有你及时赶到，拉沙尔早就死了，而且你还没索要任何佣金。你被誉为真正的英雄，永远是基恩诺的朋友。"}},faq={{q="谁被困在祖卡什虫茧里？",a="一位名叫拉沙尔的暗夜精灵，他是失踪的信使，在被虫子袭击后被困在茧里并陷入瘫痪。",al={"茧里的人是谁","拉沙尔是谁","从虫巢中获救的精灵"}},{q="拉沙尔获救后我该告诉谁？",a="你应该把拉沙尔生还且安然无恙的消息告诉羽月要塞的基恩诺·火花。",al={"脱离虫巢任务去哪里交","救出拉沙尔后我该找谁谈话","基恩诺·火花的位置"}},{q="在搜索过程中，之前发生了什么？",a="在这之前是“痛苦深渊”任务，你在那里发现了虫茧。",al={"脱离虫巢之前的任务是什么","脱离虫巢的前置任务","上一个任务"}}},fp="19,289,14.242.0,31.112.0,22.292.1,39.108.0,35.90.0,36.54.0"}
P.entries["quest:4266"] = {n="羽月将军的欢迎",s="基恩诺·火花告诉你，珊蒂斯·羽月将军想亲自和你谈谈。这肯定是因为你为要塞所做的一切，但她也想和你讨论一下你和拉沙尔在菲拉斯南部遇到的那些昆虫生物。",h="基恩诺·火花告诉你，珊蒂斯·羽月将军想亲自和你谈谈。这肯定是因为你为要塞所做的一切，但她也想和你讨论一下你和拉沙尔在菲拉斯南部遇到的那些昆虫生物。",kw={"英雄的欢迎","羽月要塞","菲拉斯","基恩诺·火花","虫巢","拉沙尔","珊蒂斯·羽月","祖卡什"},sec={{t="召唤",b="基恩诺·火花传话：珊蒂斯·羽月将军想亲自见你，她正在羽月要塞的主营地等你。基恩诺承认有关祖卡什昆虫的报告令人恐惧。"},{t="在将军身边",b="将军代表整个要塞向你表达了最诚挚的感谢并送上一份礼物，尽管她说你面对压倒性优势时展现的英勇值得千倍的回报。她随后再次请求你的帮助。既然在菲拉斯发现了祖卡什虫巢，她认为你是最佳人选。"}},faq={{q="为什么羽月将军想见我？",a="基恩诺认为她打算感谢你的帮助，同时也想谈谈你和拉沙尔在菲拉斯南部遇到的那些祖卡什昆虫。",al={"为什么见珊蒂斯","珊蒂斯召唤","英雄的欢迎为什么"}},{q="是谁让你去和珊蒂斯·羽月交谈的？",a="基恩诺·火花，他说将军想亲自见你。",al={"谁开启了英雄的欢迎","英雄的欢迎任务发布者","基恩诺·火花任务"}},{q="珊蒂斯·羽月将军在哪里？",a="羽月将军正在羽月要塞的主营地等你。",al={"珊蒂斯在哪里","羽月要塞将军位置","寻找珊蒂斯·羽月"}},{q="关于祖卡什昆虫有什么担忧？",a="基恩诺觉得关于祖卡什昆虫的报告令人恐惧，而将军想和你谈谈它们。",al={"什么是祖卡什","为什么祖卡什很危险","菲拉斯虫巢"}}},fp="16,265,9.229.0,21.303.1,44.155.0,49.68.0,46.78.0,47.111.0"}
P.entries["quest:4267"] = {n="异种蝎的崛起",s="珊蒂斯·羽月将军交给你一份拉沙尔关于菲拉斯东南部虫群侵扰的报告副本。这份主要报告归档在达纳苏斯，她希望你能将这份副本送交给格拉希娜·灵风，一位对这些生物有深入了解的Temple of the Moon祭司。",h="珊蒂斯·羽月将军交给你一份拉沙尔关于菲拉斯东南部虫群侵扰的报告副本。这份主要报告归档在达纳苏斯，她希望你能将这份副本送交给格拉希娜·灵风，一位对这些生物有深入了解的Temple of the Moon祭司。",kw={"达纳苏斯","羽月要塞","菲拉斯","格拉希娜·灵风","拉沙尔","珊蒂斯·羽月","异种虫","temple of the moon"},sec={{t="守护者的副本",b="虽然主要报告归档在达纳苏斯，但珊蒂斯·羽月将这份副本交托给你。它是给格拉希娜·灵风的，她是守护者的同僚。她是一位祭司，住在达纳苏斯的Temple of the Moon，将军说她对这些生物了解颇深，收到这份报告对每个人都有好处。她向你道别，并祈祷艾露恩护佑众生。"},{t="祭司所知之事",b="格拉希娜欢迎你来到这座神圣的寺庙，并告诉你暗夜精灵已经了解报告中提到的那种恐怖。她说，这些生物将迅速吞噬菲拉斯，它们是任何人将要面对的最可怕的威胁之一。它们被称为异种虫，只不过是部落和联盟将要面对的最严重威胁之一的工具。她祈祷在它们摧毁我们之前，我们能找到击败它们的决心。"}},faq={{q="是谁让你带着这份报告前往达纳苏斯？",a="珊蒂斯·羽月将军给了你一份拉沙尔的报告，让你带去达纳苏斯。",al={"谁开启了异种虫的崛起","异种虫的崛起任务发布者","谁给予了异种虫的崛起任务"}},{q="格拉希娜·灵风是谁？",a="格拉希娜·灵风是达纳苏斯的一位祭司，你可以在Temple of the Moon找到她。珊蒂斯·羽月称她是守护者的同僚，对报告中提到的生物有很深的了解。",al={"格拉希娜是谁","格拉希娜·灵风背景故事","格拉希娜·灵风在哪里"}},{q="拉沙尔的报告是关于什么的？",a="这是拉沙尔本人关于菲拉斯东南部虫群侵扰的记录。",al={"拉沙尔的报告是什么","拉沙尔发现了什么","拉沙尔报告的内容"}},{q="在这次运送之前发生了什么？",a="这是在“英雄的礼遇”之后，也就是你在哨所与羽月将军会面之后。",al={"异种虫的崛起前置任务","异种虫的崛起的前置任务是什么"}}},fp="20,292,27.425.0,24.450.1,44.88.0,27.198.0,31.71.0,31.85.0"}
P.entries["quest:427"] = {n="与血色十字军的战争",s="布瑞尔的执行官塞加德在提瑞斯法林地指挥着被遗忘者针对血色十字军的战役。利用执行官阿伦搜集到的情报，你被派往索利丹农场以西的岗哨塔，消灭驻扎在那里的血色战士。这次袭击标志着被遗忘者军队发起了首次攻势，旨在将狂热的十字军从他们的领土上清除出去。",h="布瑞尔的执行官塞加德在提瑞斯法林地指挥着被遗忘者针对血色十字军的战役。利用执行官阿伦搜集到的情报，你被派往索利丹农场以西的岗哨塔，消灭驻扎在那里的血色战士。这次袭击标志着被遗忘者军队发起了首次攻势，旨在将狂热的十字军从他...",kw={"布瑞尔","死亡卫队","血色十字军","血色战士","索利丹农场","希尔瓦娜斯","提瑞斯法林地","塞加德"},ang={["faction:Horde"]="在提瑞斯法林地和幽暗城周围建立稳固的边界，对于部落在东部王国建立永久据点至关重要。",["race:Undead"]="对于被遗忘者来说，血色十字军代表了一种苦涩的讽刺：这些活着的昔日同胞不仅不为洛丹伦的悲剧沦陷而哀悼，反而将他们视为怪物并寻求将他们彻底抹除。"},sec={{t="两线作战",b="在希尔瓦娜斯·风行者女王的领导下，年轻的被遗忘者国家正面临多线作战的威胁。尽管死亡卫队时刻警惕着巫妖王不断壮大的军队，但血色十字军的狂热人类却在争夺被遗忘者对他们昔日家园的统治权。十字军认为所有的亡灵都是需要用火焰和利刃净化的憎恶，他们对被遗忘者已经摆脱了天灾军团控制这一事实视而不见。"},{t="打击西方哨所",b="多亏了执行官阿伦在丧钟镇获取的情报文件，执行官塞加德现在掌握了那些狂热分子在整个提瑞斯法林地内确切的营地和哨所位置。由于正规的死亡卫队忙于遏制天灾军团，独立的被遗忘者勇士被指派直接出击。第一次打击的目标是索利丹农场以西的岗哨塔，那里的血色战士正在集结并威胁着布瑞尔的西侧入口。"}},faq={{q="为什么血色十字军敌视被遗忘者？",a="血色十字军是一个致力于消灭亡灵的极端人类组织。他们不区分受巫妖王控制、毫无思想的天灾军团和效忠希尔瓦娜斯女王、拥有自由意志的被遗忘者，视每一个亡灵为必须被焚烧的瘟疫怪物。",al={"为何血色十字军仇恨亡灵","血色十字军的动机","他们为何发起攻击"}},{q="执行官塞加德是谁？",a="执行官塞加德是驻扎在布瑞尔的被遗忘者死亡卫队的高级军官。他负责指挥战术部署、保卫首都周边的道路，并监督针对附近血色十字军和天灾军团入侵的进攻行动。",al={"塞加德是谁","布瑞尔任务发布者执行官","塞加德背景故事"}},{q="被遗忘者是如何获得血色十字军据点情报的？",a="重要的战术文件是由执行官阿伦在丧钟镇部下的新兵搜集到的。这些文件列出了整个提瑞斯法林地的血色十字军巡逻路线、哨所和营地，为执行官塞加德策划有针对性的反击提供了所需的信息。",al={"血色十字军文件","阿伦的情报","他们如何发现塔楼"}},{q="血色战士在哪里？",a="血色战士驻扎在索利丹农场以西的一座防御塔内，位于提瑞斯法林地的西部乡村地区。",al={"血色战士位置","塔楼在哪里","索利丹农场塔楼"}},{q="为什么死亡卫队不直接处理血色十字军？",a="死亡卫队的正规军因为监视天灾军团而兵力捉襟见肘，巫妖王麾下的敌军数量每晚都在增加。由于无法抽调正规士兵参与这些防务，塞加德只能依靠有志向、无任务的勇士来清除十字军。",al={"为何派遣玩家","死亡卫队在哪里","为何帮助塞加德"}},{q="这次任务能终结血色十字军在提瑞斯法林地的存在吗？",a="不能。这次对西部岗哨塔的袭击仅仅是执行官塞加德领导的四部分战役中的第一次打击，目的是摧毁整个地区的血色十字军指挥系统和哨所。",al={"这是最后一个血色十字军任务吗","血色十字军任务线"}}},fp="31,319,15.393.0,28.426.0,55.292.0,23.253.0,59.238.0,39.118.0,55.265.0,55.173.0"}
P.entries["quest:428"] = {n="失踪的亡灵哨兵",s="“失踪的死亡猎手”是瑟伯切尔的高级执行官哈德瑞克指派的一项侦察任务。两名被遗忘者侦察兵，兰妮·尤瑞克和奎恩·尤瑞克，数周前在银松森林北部那些闹鬼的农场进行调查时失踪了。追踪他们的踪迹不仅揭开了他们的下落，还揭露了威胁到被遗忘者在该地区统治地位的步步逼近的危险。",h="“失踪的死亡猎手”是瑟伯切尔的高级执行官哈德瑞克指派的一项侦察任务。两名被遗忘者侦察兵，兰妮·尤瑞克和奎恩·尤瑞克，数周前在银松森林北部那些闹鬼的农场进行调查时失踪了。追踪他们的踪迹不仅揭开了他们的下落，还揭露了威胁到被...",kw={"死亡猎手","哈德瑞克","奎恩·尤瑞克","兰妮·尤瑞克","侦察","天灾军团","瑟伯切尔","银松森林"},ang={["class:Rogue"]="尤瑞克兄妹是阴影中的同僚。看到经验丰富的死亡猎手陷入困境，这严厉地提醒着人们：仅靠潜行并不能保证在面对北方的恐怖时能够活下来。",["faction:Horde"]="守住银松森林可以确保幽暗城与洛丹伦南部地区之间的通道安全，这使得此类侦察任务对于部落的安全至关重要。",["race:Undead"]="被遗忘者特工知道，每一名失踪的探员都意味着他们对银松森林那脆弱的防御体系可能出现缺口。保护好自己的族人，才能确保瑟伯切尔免受突袭。"},sec={{t="来自北方的寂静",b="死亡猎手是希尔瓦娜斯女王和被遗忘者的耳目以及暗中利刃。当特工失去联系时，指挥部必须予以关注。高级执行官哈德瑞克数周前派遣侦察兵兰妮·尤瑞克和奎恩·尤瑞克前往银松森林北部，负责监视废弃的农场并观察敌人的动向。自他们离开后，哈德瑞克没有收到任何信使或报告，他担心这对搭档已经落入天灾军团之手，或者遭遇了更糟糕的命运。"},{t="北方的威胁",b="银松森林北部危机四伏，坐落于洛丹伦的荒废庄园与提瑞斯法林地的阴影边界之间。游荡的亡灵、潜伏的野兽和野性的狼人，让即使是经验丰富的潜行者也不敢在此单枪匹马地穿行。寻找尤瑞克兄妹需要搜索他们最初展开侦察的那些北部破旧农场，并希望能找回他们在被危险包围前所收集到的情报。"},{t="陷入阴影",b="沿着他们的踪迹寻找，发现兰妮·尤瑞克和奎恩·尤瑞克还活着，虽然仅仅是勉强维持着自由。他们躲过了食尸鬼“污秽的伊瓦尔”的袭击，但奎恩受了重伤，死亡猎手们现在被困在农场里，而那只食尸鬼就在附近徘徊。营救他们将使被遗忘者更深入地应对潜伏在道路之外的野性威胁。"}},faq={{q="兰妮·尤瑞克和奎恩·尤瑞克是谁？",a="兰妮·尤瑞克和奎恩·尤瑞克是隶属于死亡猎手的两名被遗忘者侦察兵，死亡猎手是被遗忘者的情报和刺杀组织。他们在失踪前被派往北部的银松森林监视当地的农场。",al={"谁是尤瑞克兄妹","谁是失踪的死亡猎手","兰妮和奎恩背景故事"}},{q="为什么高级执行官哈德瑞克关心他们？",a="哈德瑞克在瑟伯切尔负责监督被遗忘者的军事行动。与两名关键侦察人员失去联络，会导致被遗忘者对北部边境的敌对活动一无所知，尤其是在附近还有天灾军团徘徊的情况下。",al={"为什么哈德瑞克关心","谁派出了尤瑞克兄妹","哈德瑞克失踪的侦察兵"}},{q="尤瑞克兄妹在哪里失踪的？",a="他们在侦察银松森林北部时失踪了。他们的侦察路线集中在瑟伯切尔以北那些分散、腐朽的农场上。",al={"死亡猎手在哪里","尤瑞克位置","去哪里找到兰妮和奎恩"}},{q="死亡猎手在银松森林北部面临哪些威胁？",a="银松森林北部充斥着游荡的天灾余孽、具有攻击性的掠食者以及在树林中徘徊的诡异狼人，无论是哪一种，对于落单的侦察兵来说都是致命的危险。",al={"他们发生了什么","银松森林的危险","他们为什么失踪"}},{q="找到失踪的死亡猎手后会发生什么？",a="找到兰妮·尤瑞克后，便开启了通过任务“野性之心”帮助受创的侦察兵恢复的任务，并由此引出与“污秽的伊瓦尔”等当地威胁的对峙。",al={"下一个任务是什么","失踪的死亡猎手之后","尤瑞克之后的任务链"}},{q="死亡猎手是一个什么样的组织？",a="死亡猎手是被遗忘者首屈一指的间谍、侦察和刺杀公会，是黑暗女王在整个洛丹伦的秘密先锋。",al={"什么是死亡猎手","死亡猎手组织","被遗忘者刺客"}}},fp="18,194,24.364.0,18.363.0,22.319.1,30.197.0,49.212.0,32.144.0,62.141.0,53.146.1,45.146.0"}
P.entries["quest:4281"] = {n="萨兰纳尔的货物",s="你在木爪豺狼人营地里拾取了一包货物，原本这应该是送往萨兰纳尔的，那是菲拉斯东南部的一个小型中转站。无论信使发生了什么事，这份货物终究没有送达，包装上手写着一个名字：法芬德尔，这可能就是收件人。",h="你在木爪豺狼人营地里拾取了一包货物，原本这应该是送往萨兰纳尔的，那是菲拉斯东南部的一个小型中转站。无论信使发生了什么事，这份货物终究没有送达，包装上手写着一个名字：法芬德尔，这可能就是收件人。",kw={"法芬德尔","羽月要塞","菲拉斯","拉沙尔","萨兰纳尔","未送达的包裹","木爪"},sec={{t="丢失的包裹",b="这批货物本应送达萨兰纳尔，即菲拉斯东南部的一个小型中转站，但你却在木爪豺狼人营地里发现了它们。仔细观察会发现包装外侧手写着一个名字：法芬德尔。不难猜出这正是收件人，而你应该去萨兰纳尔寻找此人。"},{t="中转站的消息",b="法芬德尔赞美了艾露恩：来自羽月要塞的货物终于送到了。看到包裹在你手中，法芬德尔担心负责送信的拉沙尔遭遇了不测。最近，木爪豺狼人对南部发生的某件事感到非常不安，法芬德尔怀疑拉沙尔是在那里的荒野中遇难了。他提醒你要小心。"}},faq={{q="法芬德尔是谁？",a="法芬德尔是包裹包装上手写的名字，也是你在萨兰纳尔要寻找的人。",al={"法芬德尔","法芬德尔是谁","法芬德尔 萨兰纳尔"}},{q="萨兰纳尔在哪里？",a="萨兰纳尔是菲拉斯东南部的一个小型中转站，这批货物本应送往那里。",al={"萨兰纳尔位置","萨兰纳尔在哪里"}},{q="包裹是在哪里找到的？",a="你在木爪豺狼人营地里找到的。",al={"包裹是从哪里来的","包裹来源","未送达包裹的来源"}},{q="信使发生了什么事？",a="信使的下落不明。不过，既然货物尚未送达，那就需要把包裹送到萨兰纳尔去。",al={"信使是谁","失踪信使的名字","谁运送了包裹"}}},fp="18,310,20.321.0,23.338.1,27.116.0,19.104.0,27.40.0,29.118.0"}
P.entries["quest:429"] = {n="荒野之心",s="“野性之心”是银松森林中由兰妮·尤瑞克发布的部落任务。为了救治被食尸鬼“污秽的伊瓦尔”所伤的哥哥奎恩，你需要收集变色的狼人狼心，并交给瑟伯切尔的药剂师伦弗利尔，以制作炼金药剂。",h="“野性之心”是银松森林中由兰妮·尤瑞克发布的部落任务。为了救治被食尸鬼“污秽的伊瓦尔”所伤的哥哥奎恩，你需要收集变色的狼人狼心，并交给瑟伯切尔的药剂师伦弗利尔，以制作炼金药剂。",kw={"药剂师伦弗利尔","变色的狼人狼心","污秽的伊瓦尔","玛尔丁果园","奎恩·尤瑞克","兰妮·尤瑞克","瑟伯切尔","银松森林","野性之心"},ang={["class:Rogue"]="经验丰富的死亡猎手被一只野性食尸鬼击倒，这残酷地提醒了人们在洛丹伦荒野中生存所需要的隐蔽与杀戮技巧。",["race:Undead"]="这个任务突显了被遗忘者实用主义的残酷性；即便在手足之情中，生存也依赖于搜刮来的器官和冷冰冰的炼金科学，而非神圣的恩典。"},sec={{t="兄弟的绝望",b="在银松森林北部的一处农场，死亡猎手小队遭遇了灾难性的伏击。兰妮·尤瑞克不得不照顾身受重伤的哥哥奎恩。野性的食尸鬼“污秽的伊瓦尔”将奎恩重创，他的伤势难以愈合。兰妮深知，对于被这种野蛮攻击撕裂的不死之身，常规的休养已无济于事，于是她转向了皇家药剂师学会那令人毛骨悚然的技艺，希望能将她哥哥破碎的身体缝合复原。"},{t="天灾污染之地的炼金术",b="银松森林的狼群也未能幸免于笼罩洛丹伦北部的黑暗腐蚀。当地的狼人拥有被腐蚀的、变色的心脏，其中蕴含着极为独特的能量。在常人眼中，这些器官肮脏不堪，但皇家药剂师学会已经掌握了提炼这些污秽器官的方法，以此制成能够使干枯的被遗忘者躯体重焕生机的药剂。"},{t="伦弗利尔冷酷的职责",b="驻扎在瑟伯切尔的药剂师伦弗利尔对此事感到十分不满，而非同情。希尔瓦娜斯·风行者女士曾亲自指派他进行紧迫的研究工作，伦弗利尔对皇家药剂师学会沦为那些无能侦察兵的随军医护而感到愤懑。尽管如此，他还是收下了这些令人作呕的材料，并调制了药水，以确保黑暗女王的特工们能够继续执行任务。"}},faq={{q="为什么奎恩·尤瑞克需要狼人狼心才能治愈？",a="被遗忘者的生理构造与活人不同。在被食尸鬼“污秽的伊瓦尔”重创后，奎恩需要专业的炼金协助。皇家药剂师学会利用银松森林狼人身上那些被污染的变色心脏，调制出专门针对亡灵组织的恢复药剂。",al={"为什么需要狼人狼心","奎恩治愈","治疗药水配方"}},{q="在哪里可以找到变色的狼人狼心？",a="狼人游荡在银松森林的中部林区，尤其是在尤瑞克兄妹受困的道路与东侧的玛尔丁果园之间的荒野地带。",al={"狼人在哪里","银松森林狼人位置","狼人狼心打怪"}},{q="谁是“污秽的伊瓦尔”？",a="“污秽的伊瓦尔”是一只潜伏在尤瑞克兄妹藏身农场的危险食尸鬼。当兰妮和奎恩·尤瑞克经过那里侦查时，遭到了它的攻击，虽然两人都逃脱了，但奎恩却被它严重抓伤。",al={"谁是伊瓦尔","污秽的伊瓦尔背景故事","食尸鬼伊瓦尔"}},{q="为什么药剂师伦弗利尔对这项任务感到恼火？",a="药剂师伦弗利尔驻扎在瑟伯切尔，他声称黑暗女王赋予了他极其重要的重任。他认为死亡猎手侦查任务失败是一种耻辱，更是对他伟大的炼金实验的不必要干扰。",al={"伦弗利尔为什么生气","伦弗利尔对话","伦弗利尔的态度"}},{q="把心脏交给伦弗利尔后会发生什么？",a="当伦弗利尔处理完这些变色的心脏后，他会让你带着恢复药剂回到兰妮和奎恩·尤瑞克身边，这样奎恩就能康复并去寻求复仇。",al={"野性之心后的下一个任务","药水怎么用"}},{q="为什么死亡猎手需要冒险者的帮助？",a="由于奎恩的伤势严重，且面临游荡的天灾军团和野兽的持续威胁，兰妮·尤瑞克无法离开哥哥半步。她只能依靠过往的部落旅行者来采集器官，并将求援消息带给瑟伯切尔。",al={"为什么兰妮不能自己去拿心脏","死亡猎手失败"}}},fp="11,198,23.404.0,36.248.0,21.368.1,47.214.0,46.187.0,21.170.0,48.211.0,50.168.1,54.220.0"}
P.entries["quest:4297"] = {n="小精龙的食物",s="阿格纳暂时会帮你照看蛋，好让它能为破壳而出的那一天做好准备。小精龙是杂食性生物，既吃肉也吃植物，幼崽喜欢新鲜多汁的侧腹肉。阿格纳想要一些银鬃追猎者的侧腹肉，作为这只小家伙的第一顿美餐。",h="阿格纳暂时会帮你照看蛋，好让它能为破壳而出的那一天做好准备。小精龙是杂食性生物，既吃肉也吃植物，幼崽喜欢新鲜多汁的侧腹肉。阿格纳想要一些银鬃追猎者的侧腹肉，作为这只小家伙的第一顿美餐。",kw={"阿格纳","蛋","艾露恩","侧腹肉","辛特兰","杂食动物","银鬃追猎者","小精龙"},sec={{t="幼崽的第一顿饭",b="阿格纳说小精龙是杂食动物，所以当它们破壳而出时，需要一些好的食物。新鲜多汁的侧腹肉非常适合小家伙。阿格纳在照看蛋的同时，需要银鬃追猎者的侧腹肉来喂养它。如果第一顿饭没吃好，刚出生的小家伙可能活不过第一周。"},{t="艾露恩的计划",b="阿格纳从未了解小精龙为什么会吃肉。阿格纳只知道这与艾露恩为精灵制定的计划有关，并怀疑它们是否注定要成为保护者，但无法确定。阿格纳还承认，因为是你得到了这枚蛋，他感到有些嫉妒。"},{t="带回侧腹肉",b="当你带着侧腹肉回来时，阿格纳认为肉的品质不错，并说这枚蛋看起来快要孵化了。阿格纳取笑你即将成为父亲或母亲，因为你并没有预料到要承担这样的责任。"}},faq={{q="小精龙吃什么？",a="小精龙是杂食动物，既吃肉也吃植物。阿格纳说新鲜多汁的侧腹肉非常适合幼崽食用。",al={"小精龙饮食","小精龙吃什么","小精龙食物"}},{q="阿格纳在哪里照看蛋？",a="阿格纳在辛特兰照看这枚蛋，这也是你需要带肉去的地方。",al={"阿格纳位置","阿格纳在哪里"}},{q="阿格纳需要什么肉？",a="阿格纳需要五块银鬃追猎者的侧腹肉，以便在幼崽破壳后喂养它。",al={"获取什么肉","幼崽的肉类食物","追猎者侧腹肉"}},{q="艾露恩与小精龙有什么联系？",a="阿格纳从未弄明白为什么小精龙会吃肉，只知道这与艾露恩为精灵制定的计划有关，并怀疑它们是否注定要成为保护者。",al={"艾露恩与小精龙","为什么吃肉与艾露恩有关"}},{q="如果幼崽没有吃上第一顿美餐会怎样？",a="阿格纳警告说，如果没有一顿好的第一餐，它可能活不过第一周。",al={"幼崽没有食物","幼崽能存活吗"}}},fp="13,269,24.353.0,12.270.0,20.220.1,30.145.0,44.84.0,26.94.0,41.153.0,53.84.0"}
P.entries["quest:4298"] = {n="为人父母",s="辛特兰的阿格纳发现蛋的孵化进度比预期的要快得多，他想和你谈谈这件事。",h="辛特兰的阿格纳发现蛋的孵化进度比预期的要快得多，他想和你谈谈这件事。",kw={"阿格纳","成为父母","蛋","为幼崽提供食物","万物皆自由","辛特兰","宠物"},sec={{t="比预期更快",b="阿格纳并没有料到蛋的孵化会如此迅速。前往辛特兰与阿格纳交谈，你一直在那里为幼崽提供食物。"},{t="某种程度上的父母",b="阿格纳把蛋交给了你，这样它就会和你建立羁绊，并把你视为它的父母。阿格纳祝贺你成为了一位“父母”。"}},faq={{q="谁有关于蛋的消息？",a="阿格纳，他一直在辛特兰照看这枚蛋。",al={"谁开启成为父母任务","成为父母任务发放者","阿格纳任务"}},{q="我在哪里可以找到阿格纳？",a="阿格纳在辛特兰。",al={"成为父母位置","阿格纳在哪里"}},{q="这一步之前发生了什么？",a="这紧接在“为幼崽提供食物”任务之后，你需要在那个任务中为幼崽收集肉类。",al={"成为父母前提条件","成为父母前置任务"}}},fp="17,122,20.162.0,19.141.1,27.71.0,32.28.0,27.71.0"}
P.entries["quest:430"] = {n="回到奎恩身旁",s="“返回奎恩处”是银松森林中的一个部落任务，任务中，一位冒险者将药剂师伦弗利尔配制的恢复药剂送到受伤的死亡猎手奎恩·尤瑞克手中。奎恩被困在瑟伯切尔北部的伊瓦农场，虚弱不堪，他需要这瓶药剂才能考虑重返岗位。",h="“返回奎恩处”是银松森林中的一个部落任务，任务中，一位冒险者将药剂师伦弗利尔配制的恢复药剂送到受伤的死亡猎手奎恩·尤瑞克手中。奎恩被困在瑟伯切尔北部的伊瓦农场，虚弱不堪，他需要这瓶药剂才能考虑重返岗位。",kw={"药剂师伦弗利尔","亡灵哨兵埃兰德","死亡猎手","伊瓦农场","奎恩·尤瑞克","奎恩的药水","瑟伯切尔","银松森林"},ang={["class:Rogue"]="协助死亡猎手的同僚，突显了在被群体捕食者突袭时，侦察工作所面临的危险现实。",["faction:Horde"]="营救被困在敌后的侦察兵对于巩固部落在银松森林中对抗野性狼人种群的立足点至关重要。",["race:Undead"]="该任务展示了皇家药剂师学会的实际效用，他们提供关键的恢复药剂，以保持黑暗女王的侦察兵在敌对地形中的作战能力。"},sec={{t="苦涩的药剂",b="在为皇家药剂师学会采集了野兽之心后，瑟伯切尔的药剂师伦弗利尔配制了一种旨在帮助奎恩·尤瑞克的恢复药水。伦弗利尔没有时间多愁善感或讲究礼节，他匆忙将药剂交出，以便继续进行他那秘密的炼金研究，只留下冒险者独自跑腿，重返荒野。"},{t="伊瓦农场的喘息",b="奎恩·尤瑞克与他的妹妹——死亡猎手兰妮·尤瑞克一起，躲在被称为伊瓦农场的废弃农舍中。他被食尸鬼邪恶的伊瓦尔重伤，无法在敌对领土上行军，因此在冒险者抵达后立即喝下了药剂。虽然药剂恢复了他的体力，让他最终得以赶路，但周围的领土仍然充满危险，尤其是潜伏在附近的食尸鬼那充满恶意的注视。"}},faq={{q="奎恩·尤瑞克在哪里？",a="奎恩·尤瑞克躲在银松森林北部的伊瓦农场，这是一处废弃的农舍，位于瑟伯切尔以北很远的地方。",al={"奎恩在哪里","奎恩·尤瑞克位置","伊瓦农场位置"}},{q="是谁为奎恩制作了药水？",a="皇家药剂师学会的炼金术士、驻扎在瑟伯切尔地穴中的药剂师伦弗利尔，利用从森林中收集的野兽之心酿制了这种药水。",al={"谁酿制了药水","药剂师伦弗利尔的药水"}},{q="为什么奎恩无法独自行动？",a="奎恩在与妹妹一起侦察该地区时，遭到食尸鬼邪恶的伊瓦尔的伏击并被严重抓伤，导致他失去行动能力，只能依靠妹妹兰妮和药物治疗来恢复。",al={"奎恩为什么被困住","奎恩·尤瑞克受伤"}},{q="给奎恩喝下药水后会发生什么？",a="喝下药剂恢复了奎恩的体力，为反击威胁他们阵地的危险食尸鬼邪恶的伊瓦尔铺平了道路。",al={"返回奎恩处之后做什么","奎恩之后的下一个任务"}},{q="奎恩的妹妹是谁？",a="奎恩的妹妹是死亡猎手兰妮·尤瑞克，她一直待在伊瓦农场保护他，并协调他们的生存事宜。",al={"奎恩·尤瑞克的妹妹","奎恩的妹妹"}},{q="药剂师伦弗利尔关心奎恩的命运吗？",a="伦弗利尔表现出的个人关切微乎其微，他纯粹将这瓶药剂视为一项跑腿任务，随后就打发走了冒险者，以便他能继续为皇家药剂师学会进行秘密研究。",al={"伦弗利尔关心吗","伦弗利尔的态度"}}},fp="15,200,16.281.0,25.340.0,30.114.0,30.141.0,40.142.0,43.145.1,22.121.0,50.146.0"}
P.entries["quest:431"] = {n="诱灵蜡烛",s="诱灵蜡烛是一项简单的任务，重点在于回收在提瑞斯法林地发现的特殊仪式蜡烛。这些诡异的牛油蜡烛浸透了黑暗魔法，是从冈瑟尔的居所——也就是冈瑟尔·阿坎努斯在澈水湖上的岛屿——的一箱圣烛中寻获的。",h="诱灵蜡烛是一项简单的任务，重点在于回收在提瑞斯法林地发现的特殊仪式蜡烛。这些诡异的牛油蜡烛浸透了黑暗魔法，是从冈瑟尔的居所——也就是冈瑟尔·阿坎努斯在澈水湖上的岛屿——的一箱圣烛中寻获的。",kw={"诱灵蜡烛","一箱圣烛","被遗忘者","神秘学","仪式蜡烛","提瑞斯法林地","幽暗城"},ang={["class:Priest"]="暗影牧师深知处理那些旨在召唤徘徊的灵魂和引出无形之物的物品时，需要掌握微妙的平衡。",["class:Warlock"]="黑暗艺术的从业者可以轻易识别出仪式召唤中所使用的特殊牛油和魔法共鸣。",["race:Undead"]="对于被遗忘者而言，在提瑞斯法回收神秘的器具既是生存的需要，也是为了进行研究，以确保危险的神器不会落入敌手。"},sec={{t="牛油与黑暗仪式",b="冈瑟尔的居所上的木箱提供了用于他的忠诚考验的诱灵蜡烛。冈瑟尔要求冒险者带上一根蜡烛，前往岛屿南岸外那座古老而血腥的祭坛，点燃它，并直面天灾军团的特工莉莉丝·奈法拉。"},{t="重获的圣物",b="装有这些蜡烛的木箱位于冈瑟尔的居所，即巫妖冈瑟尔·阿坎努斯居住的澈水湖上的岛屿。在“忠诚的考验”任务中，冈瑟尔要求的测试只需要一根蜡烛：在岛屿南岸外那座古老而血腥的祭坛上点燃它，就会唤醒天灾军团的特工莉莉丝·奈法拉。"}},faq={{q="诱灵蜡烛有什么用？",a="诱灵蜡烛需要在冈瑟尔的居所附近的血色祭坛上点燃，以便为冈瑟尔的忠诚考验唤醒莉莉丝·奈法拉。",al={"什么是诱灵蜡烛","蜡烛的用途","蜡烛有什么作用"}},{q="这些蜡烛在哪里可以找到？",a="它们存放在冈瑟尔的居所（位于提瑞斯法林地澈水湖上，冈瑟尔·阿坎努斯的岛屿）的一箱圣烛里。",al={"哪里可以找到诱灵蜡烛","蜡烛箱位置","一箱圣烛"}},{q="这些蜡烛是谁制作的？",a="资料中没有记载它们的制造者。冈瑟尔在他的岛上保留了一箱蜡烛，用于“忠诚的考验”中设置的任务。",al={"谁制作了诱灵蜡烛","蜡烛的制造者","谁制作了箱子"}},{q="部落或被遗忘者为什么需要它们？",a="冈瑟尔·阿坎努斯在“忠诚的考验”中需要这种蜡烛。在岛屿南岸外的血色祭坛上点燃它，便能唤醒天灾军团特工莉莉丝·奈法拉，将其击败则证明你是巫妖王的敌人。",al={"为什么被遗忘者需要蜡烛","为什么要回收蜡烛","为什么部落需要蜡烛"}},{q="任何人都能使用这种蜡烛吗？",a="诱灵蜡烛需要被放在莉莉丝的血色餐桌上并点燃，才能在冈瑟尔的考验中召唤她。",al={"我可以点燃它吗","如何使用蜡烛","使用诱灵蜡烛"}},{q="这些蜡烛与天灾军团有关吗？",a="这根蜡烛会唤醒莉莉丝·奈法拉，一位强大的天灾军团特工。冈瑟尔要求你消灭她，以证明你是巫妖王的敌人。",al={"这是天灾魔法吗","蜡烛属于天灾吗","天灾教派蜡烛"}}},fp="20,170,21.187.0,17.273.0,48.129.0,30.129.0,26.109.0,41.220.0,31.120.0,38.143.0"}
P.entries["quest:432"] = {n="该死的石腭怪！",s="工头乔尼·石眉在石腭怪完全占领了古博拉采掘场的作业区后已是束手无策。这些具有破坏性和攻击性的野兽砸毁了他的采矿设备和火药桶，让他怒不可遏，急于报复。由于视力下降，他无法亲自与它们作战，因此他花钱雇佣勇敢的冒险者深入坑道，去消灭那些野蛮的头骨重锤。",h="工头乔尼·石眉在石腭怪完全占领了古博拉采掘场的作业区后已是束手无策。这些具有破坏性和攻击性的野兽砸毁了他的采矿设备和火药桶，让他怒不可遏，急于报复。由于视力下降，他无法亲自与它们作战，因此他花钱雇佣勇敢的冒险者深入坑道，...",kw={"丹莫罗","古博拉","火药","采掘场","石腭","头骨重锤","石眉","石腭怪"},ang={["profession:Mining"]="古博拉采掘场代表着重要的矮人采石和矿产开采工作。清除入侵者是让鹤嘴锄重新挥舞起来的第一步。",["race:Dwarf"]="卡兹莫丹的石腭怪入侵对每一位矮人来说都感同身受。看到古博拉的采石工被毫无理智的野蛮石腭怪赶走，让深入坑道的复仇变得更加私人化。"},sec={{t="采掘场的混乱",b="古博拉采掘场曾是一个引以为傲、产量丰富的矮人挖掘场，坐落在丹莫罗东部的雪山之中。当底下的石腭怪冲破基岩并涌入下层台地时，这种繁荣景象便戛然而止。这些野蛮人不仅占领了隧道，还肆意破坏，砸烂了脚手架，引爆了珍贵的爆破火药桶。"},{t="石眉的怒火",b="从山脊的安全地带看着自己毕生的心血付诸东流，工头乔尼·石眉已处于崩溃的边缘。他对自己衰老的双手和糟糕的瞄准能力感到沮丧，只能指望路过的流浪者和联盟新兵去执行这原始的复仇。减少石腭头骨重锤的数量能让他稍感宽慰，但如果不彻底根除它们，便无法平息他的怒火。"}},faq={{q="古博拉采掘场在哪里？",a="古博拉采掘场位于丹莫罗东部，通往洛克莫丹大门的公路南侧。工头乔尼·石眉就站在俯瞰那些被侵扰的挖掘坑边缘。",al={"古博拉采掘场位置","采掘场在哪里","石眉位置"}},{q="石腭怪为什么要袭击采掘场？",a="石腭怪居住在整个卡兹莫丹地底深处。矮人的挖掘工作经常会打通石腭怪巢穴所在的地下洞穴，从而引发猛烈的地表冲击，迅速淹没正在作业的矿场。",al={"为什么石腭怪在这里","石腭怪入侵原因"}},{q="工头乔尼·石眉是谁？",a="工头乔尼·石眉是负责古博拉采掘场的矮人主管。他性格尖刻、脾气暴躁，而且因战斗技能退化而烦恼，他指引愿意作战的战士去清除石腭怪的侵扰。",al={"工头乔尼·石眉","任务发布者"}},{q="什么是石腭头骨重锤？",a="石腭头骨重锤是占领古博拉采掘场的石腭怪部落中野蛮的前线执法者，它们依靠原始的力量和粗陋的棍棒来重击入侵者。",al={"头骨重锤"}},{q="为什么石眉不能亲自清理采掘场？",a="石眉承认他的视力和瞄准能力已大不如前。受限于年龄，他选择雇佣冒险者，而不是冒着被坑道内石腭怪淹没的风险亲自动手。",al={"为什么石眉不战斗"}},{q="石腭怪在采掘场里破坏什么？",a="除了扰乱采矿作业外，石腭怪还在积极破坏重型设备并引爆补给品，其中包括珍贵的矮人爆破火药桶。",al={"石腭怪的破坏","石腭怪在破坏什么"}}},fp="21,245,19.272.0,24.300.0,26.167.0,40.179.0,25.159.0,31.158.0,45.167.0,45.153.0"}
P.entries["quest:433"] = {n="公众之仆",s="来自铁炉堡的参议员梅尔·圣石亲自前往古博拉采掘场，以应对威胁丹莫罗采矿作业的突发穴居怪入侵。为了夺回该地点，他招募冒险者去消灭好斗的石颚碎骨者，以便矿工们能够重返工作岗位。",h="来自铁炉堡的参议员梅尔·圣石亲自前往古博拉采掘场，以应对威胁丹莫罗采矿作业的突发穴居怪入侵。为了夺回该地点，他招募冒险者去消灭好斗的石颚碎骨者，以便矿工们能够重返工作岗位。",kw={"碎骨者","丹莫罗","古博拉","采掘场","石颚","参议院","圣石","穴居怪"},ang={["faction:Alliance"]="铁炉堡的资源对整个联盟都至关重要，因此保卫丹莫罗的采掘场是经济上的必然需求。",["profession:Mining"]="矿工们感受到了古博拉关闭带来的痛苦，丰富的石料和矿石脉络在入侵穴居怪的棍棒下被遗弃。",["race:Dwarf"]="古博拉发生的穴居怪入侵直接打击了你家乡的工业，再次证明了当深层挖掘遭遇地底恐怖时会付出多么惨重的代价。"},sec={{t="前线的参议员",b="很难见到一位铁炉堡参议院的成员站在充满泥泞与积雪的冲突矿坑中，但参议员梅尔·圣石并非典型的政客。作为矮人统治机构和探险者协会的双重成员，圣石亲自担负起组织应对古博拉采掘场穴居怪侵扰的重任。他没有等待缓慢的立法程序，而是直接雇佣有能力的雇佣兵和旅行者来铲除这些入侵者。"},{t="古博拉的灾难",b="古博拉采掘场曾经是丹莫罗石料和矿产财富的重要来源，但深度的挖掘工作打破了此前封闭的地下空洞。原始、野蛮的石颚部族穴居怪涌入矿坑，破坏了精密的采矿设备，并驱逐了平民劳工。圣石的目标是清除凶恶的石颚碎骨者，为山地探险队员驻守采掘场并恢复铁铲作业基础设施铺平道路。"}},faq={{q="参议员梅尔·圣石是谁？",a="梅尔·圣石是一位矮人高官，他在铁炉堡参议院任职，同时也是探险者协会的成员。他亲自深入一线处理古博拉采掘场的穴居怪威胁，而不是躲在城市的高墙之后。",al={"圣石","参议员圣石","这位参议员是谁"}},{q="为什么古博拉采掘场会被穴居怪占领？",a="矮人矿工在采掘场下方的地底挖得太深，无意中打通了石颚穴居怪部落居住的洞穴。这些生物冲进了露天挖掘场，砸毁了机器，迫使工人们逃离。",al={"为什么古博拉有穴居怪","采掘场穴居怪","采掘场发生了什么"}},{q="什么是石颚碎骨者？",a="石颚碎骨者是地底石颚穴居怪氏族中的暴力作战人员。他们挥舞粗糙的武器，依靠纯粹的凶猛来压制矮人矿工和守卫。",al={"石颚碎骨者","碎骨者","碎骨者穴居怪"}},{q="在清理完穴居怪之后有什么计划？",a="一旦最初的穴居怪势力被铲除，参议员圣石计划引入铁炉堡山地探险队员来妥善加固采掘场，修复受损的机器，并恢复资源开采。",al={"圣石的计划","古博拉接下来会发生什么"}},{q="为什么探险者协会会参与其中？",a="参议员圣石隶属于探险者协会，该协会的成员经常调查整个卡兹莫丹山脉各处的古代挖掘点、地下遗迹和穴居怪入侵事件。",al={"探险者协会采矿","为什么协会在这里"}},{q="古博拉采掘场在哪里？",a="古博拉采掘场位于丹莫罗东南部，坐落在卡拉诺斯通往洛克莫丹的南门之路以南的雪山丘陵中。",al={"古博拉位置","采掘场在哪里"}}},fp="18,188,22.226.0,25.278.0,32.159.0,44.181.0,30.143.0,47.172.0,43.171.0,34.141.0"}
P.entries["quest:434"] = {n="伏击！",s="“袭击！”是一个发生在Stormwind Keep的高风险任务，涉及侏儒技师泰里恩和奶酪商人埃林·提亚斯策划的一次卧底行动。冒险者协助在皇家花园中进行了一次秘密诱捕行动，将叛国的阴谋分子当场抓获。",h="“袭击！”是一个发生在Stormwind Keep的高风险任务，涉及侏儒技师泰里恩和奶酪商人埃林·提亚斯策划的一次卧底行动。冒险者协助在皇家花园中进行了一次秘密诱捕行动，将叛国的阴谋分子当场抓获。",kw={"迪菲亚","埃林·提亚斯","莱斯科瓦","马赞","泰里奥娜女祭司","无声之刃","间谍机器人","stormwind keep","袭击","泰里恩"},ang={["class:Rogue"]="这项使命反映了潜行者地下世界错综复杂的暗影行动，证明了奶酪店和安静的花园角落往往比正式的议会拥有更大的政治权力。",["faction:Alliance"]="处决莱斯科瓦铲除了Stormwind Keep中一名效忠迪菲亚的叛徒，但也暴露了引导少年国王安度因的领导层中存在的危险脆弱性。",["race:Human"]="对于Stormwind的人类来说，这次伏击揭示了一个令人心碎的现实：蹂躏西部荒野和赤脊山的匪患，实际上是受到他们自己皇家宫殿内贵族们的秘密资助。"},sec={{t="花园伏击",b="在间谍泰里恩和奶酪商人埃林·提亚斯的策划调查下，Stormwind Keep内的棋局已定。泰里恩早已告诉马赞，他该和格雷戈尔·莱斯科瓦爵士再次会面了，并在此过程中散布了一些虚假情报。随后，他派遣了一个伪装成泰里奥娜女祭司的工程机械人进入要塞图书馆，告诉莱斯科瓦他的客人已经到了。莱斯科瓦支开了守卫，步入静谧的要塞花园，与“无声之刃”马赞会面，此人正是与迪菲亚潜行者有关联的刺客。"},{t="要塞中的叛国者",b="调查人员潜伏在阴影中，听着莱斯科瓦和马赞确认了调查人员长久以来的怀疑：Stormwind的高层贵族正在积极勾结威胁王国的迪菲亚阴谋。叛国者的谈话一结束，陷阱便发动了。莱斯科瓦和“无声之刃”都必须在皇家守卫返回发现贵族倒在鹅卵石上之前，在庭院中被迅速处决。这一行动有力地切断了迪菲亚在权力中心最深的据点之一。"},{t="暗影游戏",b="虽然眼前的威胁被消除了，但后续却留下了一些令人不安的问题。埃林·提亚斯在与马赞了结个人恩怨时感到极大的满足，尽管他并不情愿自己的私下运作间接帮助了马迪亚斯·肖尔和军情七处。莱斯科瓦的死确凿地证明了宫廷内部的腐烂，暗示迪菲亚潜行者并非单独行动——贵族中有人允许他们作恶。"}},faq={{q="格雷戈尔·莱斯科瓦爵士是谁？",a="格雷戈尔·莱斯科瓦爵士是一位居住在Stormwind Keep的显赫贵族。在他文质彬彬的表象之下，他暗中与迪菲亚潜行者勾结，利用自己的地位和影响力从宫廷内部协助他们颠覆王国。",al={"莱斯科瓦","莱斯科瓦是谁","格雷戈尔·莱斯科瓦"}},{q="“无声之刃”马赞是谁？",a="“无声之刃”马赞是一名代表迪菲亚潜行者的致命刺客。他充当了不法之徒与莱斯科瓦爵士之间的直接地下联络人，传递信息并策划阴谋，直到被诱入泰里恩设在花园里的陷阱。",al={"马赞","无声之刃","马赞是谁"}},{q="为什么埃林·提亚斯会关心这次行动？",a="虽然表面上只是个经营精制奶酪的大师，但埃林·提亚斯是一位与Stormwind地下世界有着深厚联系的潜行者。马赞曾将目标对准了提亚斯身边的人，促使他策划了这位刺客的覆灭，即便这样做顺带帮助了马迪亚斯·肖尔和军情七处。",al={"提亚斯的作用","为什么奶酪商人会卷入其中","埃林·提亚斯的目的"}},{q="泰里恩是如何诱使莱斯科瓦到外面的？",a="泰里恩部署了一个伪装成泰里奥娜女祭司的工程机械人。这个伪装机器人走过宫廷守卫进入图书馆，告诉莱斯科瓦他的客人已经到了，促使他支开守卫并到花园进行秘密会面。泰里恩早先已告知马赞是时候进行另一次会面了，并在此过程中散布了虚假情报。",al={"间谍机器人伪装","泰里奥娜","莱斯科瓦是如何被诱骗出来的"}},{q="为什么守卫没有立即保护莱斯科瓦？",a="为了保守他与迪菲亚进行非法交易的秘密，莱斯科瓦在会面开始前支开了他的守卫。这短暂的私密窗口让调查人员得以伏击并处决莱斯科瓦和马赞，而无需面对皇家守卫的干预。",al={"为什么守卫不帮助莱斯科瓦","守卫 莱斯科瓦"}},{q="莱斯科瓦被杀后发生了什么？",a="随着莱斯科瓦和马赞的死亡，埃林·提亚斯指引你前往Old Town，告知军情七处的马迪亚斯·肖尔大师莱斯科瓦的威胁已除，此即任务“野兽的头颅”。",al={"袭击之后该做什么","野兽的头颅"}}},fp="11,132,15.489.0,19.434.1,12.284.2,28.197.2,31.194.1,48.224.1,48.254.2,50.200.1,37.164.1"}
P.entries["quest:435"] = {n="护送埃兰德",s="亡灵哨兵埃兰德被好斗的掠食者困在了室内，他需要有人护送他穿过银松森林，以便与他的搭档汇合。协助他安全穿过荒野将把他直接带到亡灵哨兵兰妮·尤瑞克身边。",h="亡灵哨兵埃兰德被好斗的掠食者困在了室内，他需要有人护送他穿过银松森林，以便与他的搭档汇合。协助他安全穿过荒野将把他直接带到亡灵哨兵兰妮·尤瑞克身边。",kw={"亡灵哨兵埃兰德","亡灵哨兵的报告","伊瓦农场","兰妮·尤瑞克","银松森林","狼群"},ang={["faction:Horde"]="援助孤立无援的亡灵哨兵可以为从瑟伯切尔向外推进的部落军队提供关键的前线侦察。",["race:Undead"]="被遗忘者亡灵哨兵极其依赖团队协作和潜行；发现一名特工竟被简单的野兽困住，这突显了银松森林的荒野对于新复生者来说是多么危险。"},sec={{t="被狼群围困",b="即便是经验丰富的被遗忘者斥候，有时也会在银松森林残酷的生态面前感到力不从心。亡灵哨兵埃兰德被困在了一处破旧的避难所里，四周环绕着饥肠辘辘的狼群，它们渴望撕咬他那干枯躯体上仅存的血肉。孤身一人想要突破它们的包围无异于自杀。"},{t="险恶的穿越",b="埃兰德的目标位于伊瓦农场附近，他的搭档亡灵哨兵兰妮·尤瑞克在那里负责警戒。路线直接穿过了捕食性的狼群领地。一旦在护送下穿过这些徘徊的野兽，埃兰德就会冲向最后一段路程，抵达兰妮·尤瑞克的前哨站以寻求安全。在那里，斥候们可以为幽暗城汇总他们的情报。"}},faq={{q="为什么狼群会猎杀亡灵斥候？",a="正如埃兰德冷漠地评价的那样，银松森林的野兽一定是饿极了，才会把一具干枯的被遗忘者尸体当作一顿美餐。森林中野蛮的野生动物以攻击领地内一切移动的物体而闻名。",al={"狼群为何攻击亡灵","为什么吃亡灵","埃兰德与狼群"}},{q="亡灵哨兵埃兰德是向谁汇报？",a="埃兰德正要向亡灵哨兵兰妮·尤瑞克汇报，她是他的侦察搭档，驻扎在伊瓦农场附近的一座农舍里。他们共同为被遗忘者监视着林中的威胁。",al={"兰妮·尤瑞克是谁","埃兰德向谁汇报","埃兰德的搭档"}},{q="护送任务通向哪里？",a="埃兰德离开避难所，前往伊瓦农场附近的农舍向兰妮·尤瑞克汇报。与兰妮交谈后，他会进入室内上楼查看受伤的奎恩·尤瑞克。",al={"护送目的地","埃兰德去哪里","埃兰德的路线"}},{q="埃兰德获救后会发生什么？",a="一旦埃兰德与兰妮·尤瑞克安全汇合，这两名斥候就会整理他们的发现。随后，兰妮·尤瑞克会委托你将他们汇总的快报送回瑟伯切尔，任务名为“亡灵哨兵的报告”。",al={"护送埃兰德之后做什么","任务亡灵哨兵的报告","护送埃兰德的任务后续"}},{q="护送过程中还会遇到其他威胁吗？",a="主要的危险来自于在埃兰德的起始位置和伊瓦农场附近的农舍之间的开阔地上巡逻的狼群。",al={"护送任务的敌人","袭击埃兰德的怪物","路上有什么"}},{q="亡灵哨兵在银松森林中扮演什么角色？",a="亡灵哨兵是被遗忘者的精英潜行者、斥候和刺客。在银松森林，他们被部署在主要驻军的前方，追踪天灾军团的残党、狼人入侵、野兽以及联盟的动向。",al={"什么是亡灵哨兵","亡灵哨兵的角色","亡灵哨兵背景故事"}}},fp="16,166,18.271.0,22.283.0,43.152.0,40.199.0,27.201.0,37.214.1,54.111.0,46.201.0"}
P.entries["quest:436"] = {n="铁环挖掘场",s="“铁环挖掘场”是一个联盟任务，连接了塞尔萨玛和洛克湖以东正在进行的考古挖掘。吉恩·角盔对无法解释的补给延迟感到怀疑，于是派遣一位冒险者去查明是什么阻碍了勘察员基恩萨·铁环的团队。抵达挖掘现场后，真相很快浮出水面：一群凶猛的石鄂怪已经占领了遗迹。",h="“铁环挖掘场”是一个联盟任务，连接了塞尔萨玛和洛克湖以东正在进行的考古挖掘。吉恩·角盔对无法解释的补给延迟感到怀疑，于是派遣一位冒险者去查明是什么阻碍了勘察员基恩萨·铁环的团队。抵达挖掘现场后，真相很快浮出水面：一群凶猛...",kw={"挖掘","探险者协会","落斧","角盔","铁环","洛克莫丹","塞尔萨玛","石鄂怪"},ang={["faction:Alliance"]="要保卫洛克莫丹，就必须确保重要的贸易道路和研究点免受地下石鄂怪部落的威胁。",["race:Dwarf"]="卡兹莫丹的每一次挖掘都代表着揭开矮人祖先和泰坦遗产真相的努力，因此铁环团队的安全对于铁炉堡至关重要。"},sec={{t="山脚下的停滞",b="在塞尔萨玛镇，吉恩·角盔负责监管运往洛克莫丹各地探险者协会的物资。尽管补给和工具源源不断，但由勘察员基恩萨·铁环领导的挖掘点却报告称进展甚微。角盔了解基恩萨·铁环是一位正直、勤奋的矮人，他担心并非仅仅因为懒惰，而是发生了什么不好的事情干扰了行动。"},{t="石鄂怪入侵",b="抵达坐落在东部山丘中的挖掘现场，真相便大白于天下。探险家麦格玛尔·落斧报告称，暴躁的石鄂怪成群结队地涌入挖掘点，骚扰矮人探险队并破坏了他们的发现。在击退这些野蛮的入侵者之前，探险者协会无法完成对这些古代石器的研究。"}},faq={{q="是谁派你去铁环挖掘场的？",a="驻扎在塞尔萨玛的吉恩·角盔请求你去查看挖掘情况。他注意到尽管补给定期送达，但挖掘进度却停滞不前，因此他需要派人去实地调查。",al={"任务起始","谁发布的任务","吉恩·角盔的角色"}},{q="挖掘点位于何处？",a="挖掘点位于洛克湖东侧的山脚下。从塞尔萨玛出发的旅行者必须绕过湖泊南端，沿着向东的小径进入山区。",al={"挖掘点位置","铁环挖掘场在哪里","如何到达那里"}},{q="麦格玛尔·落斧是谁？",a="麦格玛尔·落斧是一位协助勘察员基恩萨·铁环进行挖掘工作的探险家。他负责监督现场的日常运作和后勤，并向从塞尔萨玛派来的信使说明情况。",al={"落斧","麦格玛尔·落斧是谁","任务交付npc"}},{q="挖掘进度为何停滞不前？",a="探险行动被好战的石鄂怪阻断了。这些生物涌入遗迹，干扰了挖掘工作，迫使探险者协会将重心转移到自我防卫上。",al={"为何缓慢","延迟原因","挖掘发生了什么"}},{q="完成此任务后接下来要做什么？",a="麦格玛尔·落斧会指引你协助团队收回失物，并立即接取任务“收集神像”，以夺回被石鄂怪偷走的遗物。",al={"下一个任务","后续任务","收集神像任务"}},{q="探险者协会在这里寻找什么？",a="勘察员基恩萨·铁环的探险队正在洛克莫丹地下搜寻古代遗物和石制品，以揭示矮人的历史及其久远的身世起源。",al={"挖掘目的","矮人挖掘原因","洛克莫丹的古代遗迹"}}},fp="21,210,27.264.0,21.253.1,39.142.0,37.149.0,22.170.0,36.139.0,44.151.0,47.166.0"}
P.entries["quest:437"] = {n="亡者农场",s="亡者农场是一项由瑟伯切尔的高级执行官哈德瑞克发布的突击任务。被遗忘者侦察兵发现，盘踞在一处北部废弃农场中的腐皮豺狼人正受到天灾军团女妖夜刺的指挥和庇护，要确保银松森林的安全，必须消灭她。",h="亡者农场是一项由瑟伯切尔的高级执行官哈德瑞克发布的突击任务。被遗忘者侦察兵发现，盘踞在一处北部废弃农场中的腐皮豺狼人正受到天灾军团女妖夜刺的指挥和庇护，要确保银松森林的安全，必须消灭她。",kw={"女妖","亡者农场","哈德瑞克","夜刺","腐皮","天灾军团","瑟伯切尔","银松森林"},ang={["faction:Horde"]="打破天灾军团对银松森林北部的控制，有助于保护连接幽暗城与洛丹伦南部领地的交通走廊。",["race:Undead"]="对于被遗忘者来说，摧毁夜刺是对天灾军团的一次私人报复，也是对希尔瓦娜斯和她的女妖们曾遭受的幽灵折磨的一次严酷提醒。"},sec={{t="田野之灾",b="瑟伯切尔以北坐落着一处名为亡者农场的废弃农场。这片土地曾经只是一片普通的农田，如今却被腐皮豺狼人所占据——这是一群瘟疫缠身、四处搜刮的害虫，在银松森林的乡村地区横行无忌。高级执行官哈德瑞克曾派遣小规模突击队试图将它们驱逐，但每次进攻都在某种异常魔法的阻挠下陷入僵局。"},{t="女妖的掌控",b="腐皮豺狼人的行动不仅仅出自野蛮的本能，它们受到了天灾军团的增援。一名名为夜刺的女妖监管着该地区，每当豺狼人面临覆灭的危机时，她就会利用黑暗魔法驱散被遗忘者的散兵游勇。哈德瑞克派遣部落勇士前去屠杀豺狼人，直到引诱夜刺现身，并要求带回她的幽灵精华作为她被消灭的证明。"}},faq={{q="亡者农场位于何处？",a="亡者农场位于银松森林瑟伯切尔的北部。那是一处杂草丛生、腐朽破败的农场，遭到了腐皮豺狼人的严重入侵。",al={"亡者农场位置","亡者农场在哪","亡者农场怎么去"}},{q="谁是夜刺？",a="夜刺是一名天灾军团女妖，她负责指挥并庇护亡者农场的腐皮豺狼人，利用黑暗魔法驱逐了先前所有被遗忘者的突击部队。",al={"谁是夜刺","夜刺背景故事","女妖夜刺"}},{q="为什么豺狼人会与女妖合作？",a="银松森林的腐皮豺狼人受到了亡灵瘟疫的侵染。天灾军团利用像夜刺这样的角色，将这些狂暴的生物作为先锋步兵，用来对抗被遗忘者。",al={"为什么腐皮豺狼人和天灾军团合作","豺狼人与天灾军团的关系","腐皮豺狼人背景"}},{q="如何引出夜刺？",a="夜刺会一直保持隐藏，直到受她庇护的豺狼人被大量屠杀。杀掉足够多的腐皮豺狼人，就会迫使她出现在农场中央，以捍卫她的领地。",al={"如何召唤夜刺","夜刺在哪里","夜刺不出现"}},{q="谁发布了“亡者农场”这个任务？",a="驻扎在瑟伯切尔的被遗忘者指挥官，高级执行官哈德瑞克，为了确保该地区的安全，发布了这个任务。",al={"谁发布亡者农场任务","亡者农场任务发布者","哈德瑞克任务"}},{q="消灭夜刺后会发生什么？",a="将夜刺的精华带给高级执行官哈德瑞克，证明天灾军团在银松森林北部失去了一个关键据点，哈德瑞克随后会将你的注意力转向瑟伯切尔以东的破旧渡口。",al={"亡者农场后续","亡者农场之后做什么"}}},fp="15,199,24.313.0,19.289.0,34.123.0,17.151.0,38.199.0,30.151.0,36.142.0,42.186.1"}
P.entries["quest:438"] = {n="破旧渡口",s="高级执行官哈德瑞克指派被遗忘者勇士前往瑟伯切尔以东，调查破旧渡口。湖畔码头遭到了天灾军团和腐皮豺狼人的侵袭，这引起了人们的警觉，因为敌人在洛丹米尔湖沿岸的势力正在不断扩张。",h="高级执行官哈德瑞克指派被遗忘者勇士前往瑟伯切尔以东，调查破旧渡口。湖畔码头遭到了天灾军团和腐皮豺狼人的侵袭，这引起了人们的警觉，因为敌人在洛丹米尔湖沿岸的势力正在不断扩张。",kw={"装满尸体的船","破旧渡口","芬里斯岛","高级执行官哈德瑞克","洛丹米尔湖","腐皮","瑟伯切尔","银松森林"},ang={["faction:Horde"]="守卫洛丹米尔湖周围的警戒线，能确保部落在银松森林的补给线免受北部天灾军团的侵袭。",["race:Undead"]="对于被遗忘者来说，天灾军团在银松森林建立的任何立足点，都是对提瑞斯法和幽暗城边境的直接生存威胁。"},sec={{t="跨湖的注视",b="在镇压了死亡之地的天灾军团势力后，高级执行官哈德瑞克将他的战略目光投向了银松森林东部的水道。破旧渡口曾经是一个连接洛丹伦大陆和洛丹米尔湖岛屿庄园的普通交通渡口，如今已悄然演变成一个亡灵活动的活跃据点。哈德瑞克派遣斥候去探明究竟是什么将巫妖王的仆从吸引到了这些腐烂的码头上。"},{t="阴森的货物",b="到达渡口后，你发现那里不仅仅只有漫无目的游荡的腐皮豺狼人。码头边停泊着一艘浸水的平底船，上面装满了精心包裹、经过防腐处理的尸体。望向洛丹米尔湖的迷雾，可以看到芬里斯岛上对着的一组码头，这暴露了一条将尸体直接运往岛上堡垒的恐怖补给线。"}},faq={{q="是谁让你去破旧渡口？",a="高级执行官哈德瑞克是驻扎在银松森林瑟伯切尔的被遗忘者军事指挥官，在你协助清理完死亡之地后，他会发布这个任务。",al={"谁发布破旧渡口任务","哈德瑞克 渡口 任务","破旧渡口任务发布者"}},{q="破旧渡口在哪里？",a="渡口位于瑟伯切尔以东，洛丹米尔湖的西岸，也就是内陆溪流汇入开阔水域的地方。",al={"破旧渡口位置","银松森林渡口在哪里","如何找到破旧渡口"}},{q="破旧渡口有什么生物？",a="该区域被天灾亡灵占领，主要是腐皮豺狼人和在岸边及周围码头巡逻的复活骷髅。",al={"破旧渡口的怪物","渡口的敌人有哪些","破旧渡口怪物"}},{q="你在渡口发现了什么？",a="你发现一艘装满尸体的船半截搁浅在水面上，船上的尸体摆放整齐，准备运往芬里斯岛。",al={"渡口有什么","渡口任务交付物品","船里有什么"}},{q="为什么天灾军团要在意这个渡口？",a="该渡口是横跨洛丹米尔湖的集结和中转点，天灾军团可以通过它将新鲜尸体直接运送到芬里斯岛的据点。",al={"为什么天灾军团在破旧渡口","渡口天灾军团的目的"}},{q="破旧渡口的后续任务是什么？",a="检查装满尸体的船会立即触发任务“腐皮线索”，指引你调查豺狼人的行动以及它们与芬里斯岛的联系。",al={"破旧渡口后续任务","破旧渡口后续"}}},fp="18,184,20.360.0,12.254.1,36.140.0,36.119.0,41.112.0,34.137.0,42.125.0,38.131.0"}
P.entries["quest:439"] = {n="线索",s="在洛丹米尔湖调查一艘装满尸体的驳船时，在一个刚死去的女人手上发现了一枚刻字的戒指。将这个可怕的发现报告给瑟伯切尔的高级执行官哈德瑞克，揭露了一个令人不安的行动：腐皮豺狼人正在盗掘提瑞斯法林地的乱葬岗，并将尸体运往芬里斯岛。",h="在洛丹米尔湖调查一艘装满尸体的驳船时，在一个刚死去的女人手上发现了一枚刻字的戒指。将这个可怕的发现报告给瑟伯切尔的高级执行官哈德瑞克，揭露了一个令人不安的行动：腐皮豺狼人正在盗掘提瑞斯法林地的乱葬岗，并将尸体运往芬里斯岛...",kw={"装满尸体的船","黛丽娅","黛丽娅的戒指","芬里斯岛","哈德瑞克","腐皮豺狼人线索","腐皮豺狼人","瑟伯切尔"},ang={["faction:Horde"]="哈德瑞克在瑟伯切尔协调部落的行动，以确保银松森林的安全，抵御像占据芬里斯岛的腐皮豺狼人部族这样日益增长的怪物营地。",["race:Undead"]="对提瑞斯法林地乱葬岗的亵渎对被遗忘者来说感同身受，他们自己阵亡的亲人和尚未复生的同胞正被运走，成为豺狼人炼金恐怖实验的原材料。"},sec={{t="恐怖的货物",b="在检查洛丹米尔湖岸边一艘被遗弃、装满尸体的渡船时，被遗忘者侦察兵发现并不是所有的死者都是古老的遗骸。从那堆腐肉中伸出了一只未被包裹、带有瘟疫痕迹的手，属于一个刚被杀害的女人，她戴着一枚简单的戒指，上面刻着“献给黛丽娅”。这艘船本身表明这是有组织的后勤行动，而不是毫无意义的食腐进食。"},{t="墓地掠夺者",b="当黛丽娅的戒指被送到瑟伯切尔交给高级执行官哈德瑞克时，这位被遗忘者指挥官迅速将线索拼凑在了一起。一具刚下葬不久的尸体只能来自边界另一边提瑞斯法林地的巨大乱葬岗。盘踞在银松森林的腐皮豺狼人不仅仅是在林中徘徊；他们正在有条不紊地挖掘人类尸体，并将其运过水域送往芬里斯岛，用于邪恶且未知的目的。"}},faq={{q="什么是装满尸体的船？",a="那是一艘停泊在银松森林洛丹米尔湖岸边的旧渡船。腐皮豺狼人一直利用它作为运输工具，将挖掘出来的人类尸体运过水域，送到他们在芬里斯岛的据点。",al={"尸体船","破旧渡船","湖中船只"}},{q="黛丽娅是谁？",a="黛丽娅是一名死于瘟疫的人类受害者，她的尸体最近被埋葬在提瑞斯法林地的乱葬岗中。她的尸体被腐皮豺狼人偷走了，只留下了她那枚刻字的戒指作为调查人员的线索。",al={"黛丽娅背景故事","黛丽娅是谁","“献给黛丽娅”的戒指"}},{q="豺狼人为什么要收集尸体？",a="腐皮豺狼人是侍奉天灾军团的不死豺狼人。他们并没有吃掉这些尸体，而是洗劫了提瑞斯法林地的乱葬岗，并将尸体运往芬里斯岛的天灾军团据点。",al={"豺狼人为什么需要尸体","腐皮豺狼人的尸体","芬里斯岛的尸体"}},{q="高级执行官哈德瑞克是谁？",a="高级执行官哈德瑞克是驻扎在银松森林瑟伯切尔的被遗忘者军事指挥官。他负责监督针对地区威胁的防御工作，包括野蛮的腐皮豺狼人、达拉然法师和狼人。",al={"哈德瑞克","瑟伯切尔指挥官","执行官哈德瑞克"}},{q="船上的尸体是从哪里来的？",a="根据高级执行官哈德瑞克的说法，尸体新鲜的状态表明它们是从附近的提瑞斯法林地的乱葬岗中挖出来的，那里草草埋葬了天灾军团和瘟疫的受害者。",al={"船上尸体的来源","提瑞斯法墓地的船只"}},{q="向哈德瑞克报告这条线索后会发生什么？",a="哈德瑞克派遣特工直接在芬里斯岛对抗腐皮豺狼人的威胁，并获取他们正在提炼的腐烂脓液样本，同时还促使对黛丽娅的身份进行调查并归还她的戒指。",al={"腐皮豺狼人线索之后","黛丽娅戒指后续"}}},fp="14,276,16.273.0,21.348.1,30.188.0,15.156.0,37.170.1,28.223.0,44.153.0,49.231.1"}
P.entries["quest:440"] = {n="黛丽娅的戒指",s="高级执行官哈德瑞克派遣一名冒险者前往布瑞尔，带去一枚刻有黛丽娅名字的婚戒。执政官塞弗伦查阅了城镇记录，调查她的身份并确定戒指的来源。",h="高级执行官哈德瑞克派遣一名冒险者前往布瑞尔，带去一枚刻有黛丽娅名字的婚戒。执政官塞弗伦查阅了城镇记录，调查她的身份并确定戒指的来源。",kw={"布瑞尔","黛丽娅","黛丽娅的戒指","豺狼人","高级执行官哈德瑞克","执政官塞弗伦","万人坑","烂皮","银松森林","刻字的戒指"},ang={["faction:Horde"]="阻止烂皮豺狼人亵渎提瑞斯法境内部落控制的坟墓，既是为了领土安全，也是为了报复。",["race:Undead"]="对于被遗忘者而言，黛丽娅的戒指是一个安静的提醒，诉说着将他们生前的过去与在洛丹伦那阴冷、严峻的现在联系在一起的脆弱纽带。"},sec={{t="银松森林的纪念品",b="在调查盘踞在银松森林北缘的烂皮豺狼人时，侦察兵发现了一枚刻有黛丽娅名字的戒指。高级执行官哈德瑞克没有丢弃这件饰品，而是指示你将其带回边境的布瑞尔。由于执政官塞弗伦负责管理提瑞斯法地区的市政记录和埋葬登记，他是最有可能查明她身份的官员——尽管哈德瑞克对于是否还有被遗忘者关心这件事深表怀疑。"},{t="被窃的遗物",b="在布瑞尔收到这枚戒指后，执政官塞弗伦证实黛丽娅确实是曾经在此地居住并安葬在城镇万人坑中的居民。在银松森林的烂皮豺狼人处发现她的珠宝揭示了一件阴险的亵渎行径：受瘟疫扭曲的豺狼人一直在劫掠万人坑，并将尸体运往南方供天灾军团进行实验，这让塞弗伦急于除掉这些豺狼人。"}},faq={{q="黛丽娅是谁？",a="黛丽娅是那枚被寻回的戒指上刻的名字。哈德瑞克让你去查阅布瑞尔执政官塞弗伦的记录，以了解她是谁。",al={"黛丽娅是谁","黛丽娅背景故事","黛丽娅的戒指"}},{q="为什么黛丽娅的戒指会在银松森林被发现？",a="这枚戒指是在对烂皮豺狼人的调查中寻获的。塞弗伦的记录或许能解释这是谁的纪念品，以及它如何出现在银松森林。",al={"为什么豺狼人会有那枚戒指","烂皮戒指","戒指是如何到达银松森林的"}},{q="为什么高级执行官哈德瑞克认为这枚戒指无关紧要？",a="哈德瑞克指出，亡灵状态通常会剥离生前的牵挂。他推测黛丽娅的爱人要么已经死了，要么即便复生为被遗忘者，也对生前的誓言和记忆完全漠不关心。",al={"哈德瑞克对话","为什么哈德瑞克如此愤世嫉俗","被遗忘者的情感"}},{q="执政官塞弗伦在这个任务中扮演什么角色？",a="作为布瑞尔的执政官，塞弗伦负责管理当地的市政记录和死亡登记，这使他能够确认黛丽娅的身份和埋葬地点。",al={"布瑞尔的塞弗伦","执政官塞弗伦的作用","塞弗伦是谁"}},{q="烂皮豺狼人是否与天灾军团结盟？",a="是的。银松森林的烂皮豺狼人感染了天灾瘟疫，在黑暗势力的影响下活动，并为了死灵目的收集尸体。",al={"烂皮豺狼人是天灾军团吗","豺狼人与天灾军团","银松森林豺狼人"}},{q="这项调查接下来会导向何处？",a="执政官塞弗伦查阅了布瑞尔的记录以确认黛丽娅的身份。他所了解到的信息为后续调查提供了线索。",al={"刻字的戒指之后该做什么","后续任务","黛丽娅任务续接"}}},fp="17,187,24.359.0,20.284.1,15.129.0,49.148.1,53.158.0,52.127.1,48.150.1,40.119.1"}
P.entries["quest:441"] = {n="拉林夫与幽暗城",s="这个任务连接着从布瑞尔到幽暗城的调查，要求冒险者将一枚找回的传家戒指交给一位名叫拉林夫的鳏夫。这枚戒指是在一具运往芬里斯岛的被盗女尸身上发现的，它揭示了洛丹伦曾经的居民之间的一场悲剧。将戒指送达，便开启了一场黑暗的复仇之路。",h="这个任务连接着从布瑞尔到幽暗城的调查，要求冒险者将一枚找回的传家戒指交给一位名叫拉林夫的鳏夫。这枚戒指是在一具运往芬里斯岛的被盗女尸身上发现的，它揭示了洛丹伦曾经的居民之间的一场悲剧。将戒指送达，便开启了一场黑暗的复仇之...",kw={"丈夫的复仇","布瑞尔","黛丽娅","黛丽娅的戒指","拉林夫","塞弗伦","trade quarter","幽暗城"},ang={["faction:Horde"]="带着旧洛丹伦的信物穿过幽暗城的大门，展现了被遗忘者盟友生活中阴郁的现实。",["race:Undead"]="拉林夫对他妻子悲惨离世的冷漠反应，反映了被遗忘者普遍存在的心理创伤，他们生前的牵挂已经腐化为苦涩的愤怒。"},sec={{t="悲剧的传家宝",b="在布瑞尔，执政官塞弗伦整理了关于一具被盗尸体和一枚属于名叫黛丽娅的女人的刻字戒指的线索。为了确认其来源并将其归还给她的家人，塞弗伦指示寻找者深入幽暗城的地下大厅，寻找黛丽娅在世的丈夫——拉林夫。"},{t="冰冷的心，苦涩的复仇",b="拉林夫·安迪恩位于幽暗城繁忙的贸易区，他一眼就认出了他前妻的戒指。像许多被遗忘者一样，亡灵的状态已经磨灭了他对黛丽娅的离世和遗体受辱所感到的悲伤、哀恸或悔恨。然而，尽管温柔的情感已经消亡，但一种不屈的复仇渴望依然存在，促使拉林夫密谋向那些亵渎她安息的人复仇。"}},faq={{q="谁发布了这个任务？",a="在提瑞斯法林地的布瑞尔镇，当你将黛丽娅的戒指交还给执政官塞弗伦后，他会立即发布此任务。",al={"如何获取拉林夫与幽暗城任务","任务发布者","执政官塞弗伦任务"}},{q="拉林夫·安迪恩在哪里？",a="拉林夫·安迪恩位于幽暗城的贸易区，站在地下城市的商人和工匠中间。",al={"拉林夫位置","拉林夫在哪里","贸易区拉林夫"}},{q="这枚戒指是谁的？",a="这枚戒指属于黛丽娅，她是一位来自布瑞尔的女性，也是洛丹伦陷落前拉林夫·安迪恩的妻子。",al={"黛丽娅的戒指","黛丽娅是谁","这枚戒指是谁的"}},{q="为什么拉林夫不哀悼他死去的妻子？",a="作为被遗忘者的一员，拉林夫承认像哀伤和爱情这样温柔的情感在他亡灵的心中已经冷却。取而代之的是，他心中残留的情感已经变质为一种冰冷的复仇欲望。",al={"拉林的反应","拉林夫在乎吗","为什么拉林夫如此冷漠"}},{q="这个任务之后会发生什么？",a="上交戒指后将直接进入任务“丈夫的复仇”，拉林夫会派你去为他妻子的受辱进行报复。",al={"后续任务","拉林夫的后续","接下来做什么"}},{q="黛丽娅的戒指最初是如何被发现的？",a="这枚戒指是在任务“腐皮豺狼人的线索”中找回的，是从银松森林的破旧渡口的一艘船上，被包裹着的黛丽娅的尸体手中取下的。",al={"戒指来源","戒指从哪里来"}}},fx={a3ed960c={q="为什么执政官塞弗伦要把黛丽娅的戒指送给Raleigh？",a="找到那枚刻有铭文的戒指后，执政官塞弗伦想起一位名叫Deliah的女人曾与丈夫Raleigh住在布瑞尔。如今Raleigh住在幽暗城的被遗忘者之中。塞弗伦派你送去这件纪念物，让Raleigh确认这件传家宝是否确实属于他的前妻，为他失散家人的遭遇带来慰藉或答案。",al={"为什么把戒指送给raleigh","执政官塞弗伦的动机","为什么送黛丽娅的戒指"}}},fp="25,202,17.277.0,29.326.1,22.96.0,33.87.0,30.101.0,40.124.0,30.80.1,38.117.0"}
P.entries["quest:442"] = {n="突袭芬里斯岛",s="突袭芬里斯岛是高级执行官哈德瑞克为清除银松森林中的天灾军团据点而下达的关键军事指令。为了打破巫妖王对洛丹米尔湖的掌控，被遗忘者特工被派去强攻芬里斯城堡，并取下死灵法师瑟尔·鸦爪的首级。",h="突袭芬里斯岛是高级执行官哈德瑞克为清除银松森林中的天灾军团据点而下达的关键军事指令。为了打破巫妖王对洛丹米尔湖的掌控，被遗忘者特工被派去强攻芬里斯城堡，并取下死灵法师瑟尔·鸦爪的首级。",kw={"芬里斯岛","哈德瑞克","洛丹米尔湖","天灾军团","瑟伯切尔","银松森林","瑟尔·鸦爪"},ang={["class:Mage"]="比索·埃斯沙德和药剂师伦弗利尔密切监测着瑟尔死后产生的魔法余波，对其死灵编织的剧烈消散深感着迷。",["faction:Horde"]="部落在东部王国的立足点很大程度上依赖于被遗忘者在银松森林和提瑞斯法林地对抗对立势力和游荡的天灾军团，从而稳定当地局势。",["race:Undead"]="对于被遗忘者来说，消灭瑟尔·鸦爪是一种个人复仇。粉碎天灾军团的据点证明了他们反抗巫妖王意志的决心是坚定的。"},sec={{t="清理洛丹米尔湖",b="几个星期以来，芬里斯岛一直是洛丹米尔湖中心的一块毒疮。虽然被遗忘者控制了西部道路，并在瑟伯切尔建立了据点，但天灾军团却在芬里斯城堡内盘踞了下来。在这个强大的死灵法师瑟尔·鸦爪的指挥下，这座岛屿前哨站不仅威胁着银松森林，还威胁着通往幽暗城的南部水路。高级执行官哈德瑞克深知，只要还有一个巫妖王的仆从在他们东海岸外进行邪恶的实验，被遗忘者就永远无法真正掌控银松森林。"},{t="瑟尔·鸦爪的陨落",b="强攻芬里斯城堡需要在成群的腐皮豺狼人和行尸走肉中杀出一条血路，才能在堡垒中与瑟尔·鸦爪对峙。瑟尔身负邪恶的死灵诅咒，通过黑暗魔法汲取攻击者的生命力来强化自己的攻击。在他战败后，人们砍下了瑟尔的头颅作为他死亡的铁证。他倒下时所引发的死灵波动极其剧烈，以至于药剂师伦弗利尔在远处的瑟伯切尔都能探测到那股魔法冲击波。"}},faq={{q="高级执行官哈德瑞克为什么要杀掉瑟尔·鸦爪？",a="瑟尔·鸦爪是统领芬里斯岛天灾军团的大死灵法师。任由这样一支盘踞的天灾军团不管，会威胁到被遗忘者在瑟伯切尔的据点，并危及洛丹米尔湖的水路安全。哈德瑞克要求取下他的首级，以证实天灾军团在当地的指挥体系已被彻底粉碎。",al={"为什么要杀瑟尔","哈德瑞克的动机","芬里斯岛的威胁"}},{q="瑟尔·鸦爪在哪里？",a="瑟尔·鸦爪居住在芬里斯岛上的废墟城堡深处，该岛位于银松森林以东的洛丹米尔湖中央。他坐镇于城堡的下层公共大厅，周围有不死随从和扭曲的爪牙守卫。",al={"瑟尔·鸦爪的位置","瑟尔在哪里","寻找瑟尔"}},{q="瑟尔·鸦爪死后会发生什么？",a="当瑟尔被消灭时，释放出的极其庞大的黑暗死灵能量会在整个地区回荡。在瑟伯切尔，药剂师伦弗利尔探测到了魔法消散产生的冲击波，高级执行官哈德瑞克称赞这次突袭是被遗忘者的一场巨大的战略胜利。",al={"瑟尔之死的反应","瑟尔死后发生了什么"}},{q="这次突袭前，是谁控制着芬里斯岛？",a="芬里斯岛处于天灾军团的直接占领之下。瑟尔·鸦爪将这座岛上的城堡作为前进基地，指挥着复活的不死生物和被枯萎魔法扭曲的腐皮豺狼人去威胁洛丹米尔湖的水域。",al={"谁控制着芬里斯岛","芬里斯岛的阵营","芬里斯岛是天灾军团吗"}},{q="为什么比索的药水对这次任务很重要？",a="瑟尔会施放鸦爪诅咒，这是一种使人虚弱的诅咒，既能削弱对手的力量，又能增强自己的实力。比索·埃斯沙德提供了反咒语，而药剂师伦弗利尔在先前的行动中将其酿制成药水，专门用于中和这种死灵诅咒。",al={"鸦爪诅咒的解药","比索的药水与瑟尔","对抗瑟尔的诅咒"}},{q="芬里斯岛对被遗忘者有什么战略意义？",a="芬里斯岛坐落在洛丹米尔湖中，与银松森林和希尔斯布莱德丘陵接壤。控制或清除它就能消除一个有能力对银松森林发动攻击的活跃敌方前哨站，从而从洛丹伦的边境清除一大股天灾军团势力。",al={"芬里斯岛为何重要","芬里斯岛的重要性"}}},fp="22,215,22.494.0,27.336.1,56.247.0,33.229.0,39.238.1,45.188.0,51.252.0,66.237.0"}
P.entries["quest:443"] = {n="腐皮豺狼人的脓液",s="“腐皮豺狼人的脓液”是银松森林中一个部落阵营的任务，由瑟伯切尔的高级执行官哈德瑞克发布。为了在发起进攻前了解盘踞在芬里斯岛上那些非自然的腐皮豺狼人，被遗忘者指挥部派遣冒险者提取这些生物血管中循环流淌的恶臭神秘液体，以供研究。",h="“腐皮豺狼人的脓液”是银松森林中一个部落阵营的任务，由瑟伯切尔的高级执行官哈德瑞克发布。为了在发起进攻前了解盘踞在芬里斯岛上那些非自然的腐皮豺狼人，被遗忘者指挥部派遣冒险者提取这些生物血管中循环流淌的恶臭神秘液体，以供研...",kw={"药剂师伦弗利尔","芬里斯岛","高级执行官哈德瑞克","洛丹米尔湖","腐皮豺狼人","腐皮豺狼人的脓液","瑟伯切尔","银松森林"},ang={["faction:Horde"]="芬里斯岛坐落在银松森林的东缘，如果部落部队不加以监视，它将成为一个战术危险区。",["race:Undead"]="对于被遗忘者来说，了解生物恐怖和人造疾病既是一门科学，也是一种生存本能。剖析腐皮豺狼人的体液，可以让皇家药剂师协会确定这种感染是否威胁到他们在洛丹伦的领地。"},sec={{t="非自然生物学",b="银松森林的腐皮豺狼人远非普通的野生类人生物。它们腐朽、充满攻击性，并且浑身散发着凋零的气息，占据了诸如洛丹米尔湖中的芬里斯岛等战略要地。高级执行官哈德瑞克意识到，它们那非自然的生命力源于某种流淌在体内的奇异液体，在派遣士兵进行代价高昂的突袭之前，必须先获得样本。"},{t="药剂师的分析",b="皇家药剂师协会在瑟伯切尔设有常驻机构，而药剂师伦弗利尔专门研究生物和化学异常现象。通过将这些腐皮豺狼人的脓液样本带给伦弗利尔，被遗忘者希望揭开这些豺狼人的起源，查明是谁在改造它们，并找出在战斗中可以利用的弱点。"}},faq={{q="什么是腐皮豺狼人的脓液？",a="这是一种非自然的恶臭液体，流淌在芬里斯岛腐皮豺狼人的体内。这种肮脏的混合物取代了正常的血液，维持着它们类似亡灵般的腐烂状态，并赋予了它们异常的生命力。",al={"什么是脓液","腐皮豺狼人液体","豺狼人脓液"}},{q="为什么高级执行官哈德瑞克想要这些脓液样本？",a="哈德瑞克计划对芬里斯岛发起进攻，但军事智慧告诉他必须先了解敌人。通过获取液体样本供药剂师伦弗利尔检查，被遗忘者希望推断出是谁创造了腐皮豺狼人，并找到可以利用的生物学弱点。",al={"为什么要收集脓液","哈德瑞克的目标","为什么哈德瑞克需要脓液"}},{q="腐皮豺狼人在哪里？",a="它们栖息在芬里斯岛上，该岛位于银松森林中破旧渡口的洛丹米尔湖对岸。岛上的海岸线、营地和周围的废墟遍布各种腐皮豺狼人，包括蛮兵和瘟疫织者。",al={"我在哪里可以找到腐皮豺狼人","腐皮豺狼人位置","芬里斯岛的豺狼人"}},{q="谁是药剂师伦弗利尔？",a="伦弗利尔是皇家药剂师协会的一名研究员，驻扎在瑟伯切尔的墓穴外。他代表被遗忘者研究银松森林各地的凋零、瘟疫和各种奇怪的生物危害。",al={"谁是伦弗利尔","药剂师伦弗利尔的角色"}},{q="伦弗利尔收到脓液后会发生什么？",a="一旦伦弗利尔收到样本，他就会着手分析该液体的化学成分以追溯腐皮豺狼人的起源，从而引出后续任务“腐皮豺狼人的起源”。",al={"腐皮豺狼人的脓液后的任务","腐皮豺狼人的脓液后续"}},{q="为什么被遗忘者关心豺狼人？",a="腐皮豺狼人占据着洛丹米尔湖中的芬里斯岛，这是一个紧邻被遗忘者领土的重要据点。此外，它们腐烂的状态和对瘟疫类能力的使用暗示了外界的干预，这对幽暗城的安全构成了潜在的直接威胁。",al={"为什么被遗忘者要对抗豺狼人","银松森林的豺狼人威胁"}}},fp="14,178,17.319.0,19.288.0,23.181.0,56.183.0,38.209.0,28.220.0,48.145.0,38.228.0"}
P.entries["quest:444"] = {n="腐皮豺狼人的产生",s="“腐皮的起源”是一个被遗忘者任务，它将银松森林中皇家药剂师学会的研究与幽暗城的法术专业知识结合了起来。在分析了从豺狼人身上提取的腐臭液体后，药剂师伦弗利尔派遣一位冒险者去咨询比索·埃斯沙德，以揭开这些腐烂野兽背后的魔法渊源。",h="“腐皮的起源”是一个被遗忘者任务，它将银松森林中皇家药剂师学会的研究与幽暗城的法术专业知识结合了起来。在分析了从豺狼人身上提取的腐臭液体后，药剂师伦弗利尔派遣一位冒险者去咨询比索·埃斯沙德，以揭开这些腐烂野兽背后的魔法渊...",kw={"药剂师伦弗利尔","比索·埃斯沙德","magic quarter","腐皮豺狼人的脓液","腐皮的起源","脓液样本","银松森林","幽暗城"},ang={["class:Mage"]="比索·埃斯沙德的作用强调了奥术预言和学术法术是如何成为解决困扰普通炼金术的黑暗谜团的重要工具。",["class:Warlock"]="在腐皮豺狼人的脓液中发现的与死灵法术混合在一起的邪能和术士魔法，表明银松森林的荒野中存在着蓄意的、禁忌的法术。",["race:Undead"]="这项任务展示了皇家药剂师学会与幽暗城奥术大师之间的合作，协调科学与法术以保卫洛丹伦。"},sec={{t="死亡与邪能的混合物",b="在检查从侵扰银松森林的腐皮豺狼人身上采集的液体时，药剂师伦弗利尔成功地将这种污秽的物质还原为其基本元素。他的初步化学蒸馏揭示了一些比普通豺狼人疾病更奇怪的东西：这种脓液带有死灵法术和术士法术这种不可错认的双重特征。伦弗利尔意识到纯粹的炼金术无法揭示这些法术的全貌，于是指派一名代理人将准备好的样本直接带到首都进行深奥的审查。"},{t="面见法师",b="样本被带到了比索·埃斯沙德那里，他是一位驻扎在幽暗城Magic Quarter高处的被遗忘者法师。比索不属于皇家药剂师学会，但他对奥术和黑暗学科的精通使他成为解码异常力量编织的宝贵资源。在收到这个邪恶的药瓶后，比索检测到了他多年未见的古老而强大的附魔，并立即准备了一个预言法术来识别是谁编织了这种邪恶的魔法。"}},faq={{q="是谁派玩家去执行这个任务的？",a="药剂师伦弗利尔，一位驻扎在银松森林瑟伯切尔的皇家药剂师学会炼金术师，在检查了从附近的腐皮豺狼人身上回收的脓液后指派了这项任务。",al={"谁开启了腐皮的起源任务","在哪里接腐皮的起源任务"}},{q="为什么伦弗利尔要把样本送到比索·埃斯沙德那里？",a="伦弗利尔发现腐皮豺狼人的脓液中浸透了死灵法术和术士魔法。由于仅靠炼金术无法完全解释正在运作的附魔，他寻求幽暗城的比索·埃斯沙德的奥术专长，以占卜其魔法起源。",al={"为什么要找比索·埃斯沙德","为什么要给法师样本"}},{q="比索·埃斯沙德在哪里？",a="比索·埃斯沙德住在幽暗城的Magic Quarter，周围是奥术研究员和训练师。",al={"比索的位置","比索·埃斯沙德在哪里"}},{q="什么是腐皮豺狼人？",a="腐皮豺狼人是潜伏在银松森林中的亡灵豺狼人。与普通毫无意识的野兽不同，它们腐烂的状态是由邪恶的魔法实验人为诱导的。",al={"什么是腐皮豺狼人","银松森林的腐皮豺狼人"}},{q="当你把样本交给比索时会发生什么？",a="比索认出了贯穿液体中的古老而强大的魔法，并指出他已经很长时间没有遇到这些特定的法术了。他立即开始施放预言法术来追踪魔法的来源。",al={"比索做了什么","比索·埃斯沙德的反应"}},{q="接下来的任务是什么？",a="在这次交付和比索的预言之后，他派遣冒险者去执行“Thule Ravenclaw”任务，以调查应对豺狼人腐化负责的叛变法师。",al={"腐皮的起源之后的下一个任务","腐皮的起源的后续任务"}}},fp="16,193,29.275.0,22.290.1,35.150.0,54.189.0,33.99.0,23.116.0,51.144.0,22.114.1"}
P.entries["quest:4449"] = {n="被锁起来的矮人",s="有人被锁在了灼热峡谷的一间木制厕所里，正在里面大声求救。他当时正在躲避黑铁矮人，钻进厕所躲藏，结果那些地质学家把门从外面锁上了。他想给八名黑铁地质学家一点教训，还要十五块丝绸……说是为了什么特别的东西，但没说清楚。",h="有人被锁在了灼热峡谷的一间木制厕所里，正在里面大声求救。他当时正在躲避黑铁矮人，钻进厕所躲藏，结果那些地质学家把门从外面锁上了。他想给八名黑铁地质学家一点教训，还要十五块丝绸……说是为了什么特别的东西，但没说清楚。",kw={"被抓","黑铁地质学家","灼热峡谷","丝绸","木制厕所"},sec={{t="被锁住了",b="厕所里传出的声音讲述了逃离黑铁矮人并躲进去藏身的经过。那些黑铁地质学家一定是用了什么魔法看到了他，因为他还没反应过来，门就被锁上了。"},{t="两个忙",b="那个人要求给八名黑铁地质学家一点教训，还要十五块丝绸，虽然他解释要丝绸的原因时结结巴巴，最后什么也没说出来。"}},faq={{q="谁被困在厕所里了？",a="一个没有透露姓名的人，他当时为了躲避黑铁矮人而藏在了里面。",al={"厕所里的人是谁","谁被锁在厕所里","厕所里的人"}},{q="为什么那个人想要丝绸？",a="他要了十五块丝绸，但说不清为什么要，只是声称没别的用途。",al={"为什么要丝绸","丝绸是做什么的","为什么厕所里的人要丝绸"}},{q="是谁锁上了厕所的门？",a="黑铁地质学家。那个人认为他们看到了他躲进去，然后用法术锁上了门。",al={"谁锁了门","谁困住了那个人","哪些黑铁矮人"}},{q="需要杀死多少地质学家？",a="那个人要求除掉其中的八个。",al={"地质学家的数量","地质学家计数"}}},fp="7,316,9.215.0,10.196.0,35.79.0,38.84.0,29.115.0,34.53.0"}
P.entries["quest:445"] = {n="给银松森林送信",s="这个跑腿任务是一项至关重要的信使任务，它将皇家药剂师协会在布瑞尔的研究与他们在银松森林的持续工作连接了起来。受药剂师乔汉的委托，你将宝贵的研究结果送交瑟伯切尔的药剂师伦弗利尔，以协助黑暗女王开发The New Plague。",h="这个跑腿任务是一项至关重要的信使任务，它将皇家药剂师协会在布瑞尔的研究与他们在银松森林的持续工作连接了起来。受药剂师乔汉的委托，你将宝贵的研究结果送交瑟伯切尔的药剂师伦弗利尔，以协助黑暗女王开发The New...",kw={"布瑞尔","送往银松森林的快递","乔汉","the new plague","伦弗利尔","皇家药剂师协会","瑟伯切尔","银松"},ang={["faction:Horde"]="虽然被遗忘者的炼金术研究在其他部落盟友中经常引起疑虑，但在银松森林道路上的安全通行和信使工作保障了北部领土的安全。",["race:Undead"]="递送这份研究代表着对Sylvanas的直接效忠和被遗忘者的生存，有助于实现皇家药剂师协会的核心抱负。"},sec={{t="一个因目标而团结的学会",b="皇家药剂师协会直接受Sylvanas Windrunner的指挥，任务是调制出一种足以消灭生者与天灾军团的The New Plague。被遗忘者领地内各个孤立的实验室不能各自为政；生存与进步需要不断的沟通。在布瑞尔，药剂师乔汉收集了实验成果，必须毫无延误地传达给在现场的其他研究人员。"},{t="南方的哨站",b="银松森林是被遗忘者扩张和研究的下一个前沿。药剂师伦弗利尔驻守在瑟伯切尔，负责监管当地面临月怒狼人、流氓人类和残留天灾军团威胁下的生物化学测试。通过接收来自提瑞斯法林地的乔汉的研究笔记，伦弗利尔将新的炼金术发现整合到他自己的本地实验中，进一步推进了协会的宏伟蓝图。"}},faq={{q="药剂师乔汉为什么要发送这些文件？",a="皇家药剂师协会的成员被期望分享他们的发现，以加速The New Plague的创造。乔汉需要将他在提瑞斯法林地的最新研究成果送到南方，以便其他研究人员可以在他的工作基础上继续研究。",al={"为什么要派送研究成果","乔汉的笔记","为什么要发送研究"}},{q="瑟伯切尔位于哪里？",a="瑟伯切尔是银松森林主要的被遗忘者哨站。它位于提瑞斯法林地边界以南，幽暗城西南，沿着蜿蜒穿过森林的主路旁。",al={"瑟伯切尔在哪里","寻找伦弗利尔","瑟伯切尔的位置"}},{q="药剂师伦弗利尔是谁？",a="伦弗利尔是驻扎在瑟伯切尔的皇家药剂师协会的杰出成员。他负责指导实地测试并研究在银松森林各地发现的奇异成分，并向幽暗城协会的高层领导汇报。",al={"伦弗利尔的职责","谁是伦弗利尔","银松森林的伦弗利尔"}},{q="乔汉提到的The New Plague是什么？",a="The New Plague是皇家药剂师协会在Sylvanas Windrunner的命令下正在设计的一种定制炼金术瘟疫。它的设计目的是根除活着的敌人以及巫妖王的亡灵爪牙。",al={"the new plague","sylvanas的瘟疫","什么瘟疫"}},{q="伦弗利尔提到的亡灵壁垒是什么？",a="伦弗利尔提到他需要将样本送到“亡灵壁垒”，但这并没有明确指出他指的是哪一座亡灵壁垒。",al={"伦弗利尔的亡灵壁垒","伦弗利尔的样本","送往亡灵壁垒的样本"}},{q="为什么要使用冒险者而不是正式的信使？",a="被遗忘者的信使面临着充满狂暴狼人、好斗的野生动物和敌对人类幸存者的危险道路。将研究委托给一个有能力的冒险者可以确保精细的炼金术笔记完好无损地送达瑟伯切尔，同时也能为地区工作增加一个人手。",al={"为什么要我送信","为什么要冒险者作为信使"}}},fp="29,165,26.422.0,20.387.0,49.214.0,31.179.0,28.252.0,43.211.0,42.127.0,53.238.0"}
P.entries["quest:4450"] = {n="塔纳利斯的账本",s="在完成“被困！”任务后，灼热峡谷中木制茅厕里的住客会委托你去完成一件在塔纳利斯接下的差事。加基森的克林科·古德斯迪尔想要在峡谷和其他几个地方找回某些东西，你需要将它们收集齐全并交给通过他。",h="在完成“被困！”任务后，灼热峡谷中木制茅厕里的住客会委托你去完成一件在塔纳利斯接下的差事。加基森的克林科·古德斯迪尔想要在峡谷和其他几个地方找回某些东西，你需要将它们收集齐全并交给通过他。",kw={"比吉尔的飞艇残骸","尘泥沼泽","加基森","玻璃蛛","贾奎亚","克林科·古德斯迪尔","来自塔纳利斯的差事","灼热峡谷","悲伤沼泽","木制茅厕"},sec={{t="来自塔纳利斯的差事",b="在得到帮助之后，那个人回想起了他在塔纳利斯时接下的一件小差事。加基森的克林科·古德斯迪尔想要一份搜集物品的清单，其中一些就在这峡谷里，另一些则在别处。古德斯迪尔的账本会被从门缝下递给你，你需要带着它，以及上面列出的所有物品，去塔纳利斯交给古德斯迪尔。"},{t="账本上的内容",b="账本上列出了二十根坚固的水晶腿节，这些材料来自灼热峡谷的玻璃蛛，还有一份逾期的包裹。包裹在尘泥沼泽比吉尔的飞艇残骸处。第三件物品，古德斯迪尔的平衡焰刃，被悲伤沼泽东岸的一只鱼人贾奎亚拿走了。"}},faq={{q="任务从哪里开始？",a="在灼热峡谷的木制茅厕那里，在你帮助了被锁在里面的人之后。",al={"任务起始","谁给予来自塔纳利斯的差事","茅厕位置"}},{q="克林科·古德斯迪尔是谁？",a="他在塔纳利斯的加基森。他说自己忙得不可开交，有许多顾客都在寻求他的服务。",al={"克林科·古德斯迪尔是谁","加基森的克林科·古德斯迪尔","克林科·古德斯迪尔在哪里"}},{q="账本上写了什么？",a="二十根坚固的水晶腿节、一份逾期的包裹，以及古德斯迪尔的平衡焰刃。",al={"需要什么物品","账本物品清单","古德斯迪尔的账本物品"}},{q="逾期的包裹在哪里？",a="在尘泥沼泽比吉尔的飞艇残骸处的坠毁飞艇上。",al={"逾期包裹位置","逾期包裹在哪里","比吉尔的飞艇残骸包裹"}},{q="谁拿走了古德斯迪尔的平衡焰刃？",a="贾奎亚，一只位于悲伤沼泽东岸的鱼人。",al={"平衡焰刃位置","谁掉落平衡焰刃","悲伤沼泽的贾奎亚"}},{q="这个任务之前有什么？",a="“被困！”，在同一个木制茅厕处。",al={"前置任务","必要任务","来自塔纳利斯的差事之前的任务链"}}},fp="19,257,18.325.0,21.332.0,22.88.0,25.102.0,22.89.0,29.63.0,40.57.0,22.37.0"}
P.entries["quest:4451"] = {n="自由的钥匙",s="你在灼热峡谷发现了一把小巧的黄铜钥匙。钥匙头上刻着几行字，说明它是黑铁矮人的厕所钥匙，严禁复制。至于它通向何处，你还不得而知。",h="你在灼热峡谷发现了一把小巧的黄铜钥匙。钥匙头上刻着几行字，说明它是黑铁矮人的厕所钥匙，严禁复制。至于它通向何处，你还不得而知。",kw={"黑铁矮人厕所","格里塞特厕所钥匙","洛基德","灼热峡谷","自由之匙","木制厕所"},sec={{t="有标记的钥匙",b="这把黄铜钥匙看起来很普通，但上面刻着“黑铁矮人厕所”的字样，并警告不要复制。它通向哪里尚不可知，想要了解的话，就得在灼热峡谷四处寻找它的用处。"},{t="被打断的如厕",b="木制厕所里有人咳嗽着问是谁，对被打扰感到很不耐烦。厕所里的人名叫洛基德，他很高兴你找到了钥匙，并说黑铁矮人在把他锁进去之后就把钥匙藏起来了。"}},faq={{q="格里塞特厕所钥匙上写着什么？",a="钥匙头上刻着“黑铁矮人厕所”的字样，并有一条禁止复制的警告。",al={"钥匙铭文","钥匙上写了什么","厕所钥匙文字"}},{q="这把钥匙通向哪里？",a="这需要你去发现。钥匙上标明它属于一座黑铁矮人的厕所，其用途可以在灼热峡谷的某个地方找到。",al={"钥匙在哪里使用","厕所位置","自由之匙任务交还"}}},fp="18,202,12.226.0,20.191.1,46.90.0,25.147.0"}
P.entries["quest:446"] = {n="图勒·鸦爪",s="在银松森林发现奇怪的腐皮豺狼人的脓液后，比索·埃斯沙德断定这种邪恶的物质出自他那背叛的前同事图勒·鸦爪之手。为了帮助被遗忘者击退腐皮豺狼人，比索为药剂师伦弗利尔准备了一份包含反咒语的特制卷轴。",h="在银松森林发现奇怪的腐皮豺狼人的脓液后，比索·埃斯沙德断定这种邪恶的物质出自他那背叛的前同事图勒·鸦爪之手。为了帮助被遗忘者击退腐皮豺狼人，比索为药剂师伦弗利尔准备了一份包含反咒语的特制卷轴。",kw={"药剂师伦弗利尔","比索·埃斯沙德","芬里斯岛","腐皮","天灾军团","瑟伯切尔","银松森林","图勒·鸦爪"},ang={["class:Mage"]="比索和图勒之间的冲突凸显了洛丹伦昔日法师之间的悲剧性分歧，对比了那些堕落于通灵术的人与那些在亡灵状态下仍保持奥术纪律的人。",["faction:Horde"]="根除洛丹伦的天灾残余可以巩固部落在东部王国的立足之地。",["race:Undead"]="中和图勒·鸦爪对被遗忘者至关重要，因为他对比芬里斯岛的控制威胁到了瑟伯切尔以及通往首都区的西部通路。"},sec={{t="变节的同僚",b="当一名信使将腐皮豺狼人的脓液样本送到幽暗城法师区的比索·埃斯沙德手中时，这位老练的法师立刻认出了其中独特的奥术共鸣。这种提取物属于图勒·鸦爪，他曾是第三次战争前与比索一同学习、前途无量的年轻法师。当巫妖王崛起时，图勒背叛了他的同伴，向天灾军团宣誓效忠，并在洛丹伦陷落时抛弃了他的人性。"},{t="芬里斯岛的主宰",b="比索不安地了解到，鸦爪不仅在战争中幸存下来，还盘踞在洛丹米尔湖中芬里斯岛上的芬里斯城堡内。从那里，图勒指挥着腐皮豺狼人，将邪恶的魔法灌注给它们，并派遣它们去骚扰被遗忘者的边境。比索利用他对昔日同僚魔法能力的了解，誊写了一份专门用于中和图勒特有诅咒和结界的特制卷轴。"},{t="炼金术对策",b="信使带着比索的卷轴，回到瑟伯切尔交给皇家药剂师协会的药剂师伦弗利尔。伦弗利尔对这位幽暗城法师展现出的强大魔法咒语非常着迷，开始将高等奥术与协会的炼金药剂结合起来。最终制成的药剂专门用于破解鸦爪的妖术，为进攻芬里斯城堡扫清了障碍。"}},faq={{q="图勒·鸦爪是谁？",a="图勒·鸦爪曾是一位前途无量的年轻人类法师，曾在达拉然接受训练，并与比索·埃斯沙德一同学习。当巫妖王开始在洛丹伦散布腐蚀时，图勒背叛了他的同胞，转而侍奉天灾军团，最终崛起并从芬里斯岛指挥着腐皮豺狼人。",al={"图勒背景故事","谁是图勒","图勒·鸦爪的身世"}},{q="为什么比索·埃斯沙德了解图勒的魔法？",a="在洛丹伦陷落之前，比索和图勒是同事和施法同伴。因为他们曾一起学习奥术，所以比索对比索偏好的法术、魔法理论和妖术非常熟悉。",al={"比索和图勒","比索如何认识图勒","比索·埃斯沙德的关系"}},{q="比索的卷轴有什么用？",a="比索的卷轴包含专门用于破解图勒法术的复杂反咒语。药剂师伦弗利尔使用这些咒语配制出一种炼金药水，可以保护被遗忘者的勇士免受鸦爪妖术的侵害。",al={"比索的卷轴","卷轴的用途","卷轴的作用"}},{q="为什么腐皮豺狼人对银松森林构成了威胁？",a="与普通的野兽不同，腐皮豺狼人受到图勒·鸦爪利用天灾通灵术的指挥和强化。它们以芬里斯岛为大本营，对银松森林各处的被遗忘者定居点和巡逻队发动有组织的入侵。",al={"腐皮豺狼人","为什么要对抗豺狼人","芬里斯岛豺狼人"}},{q="这个任务发生在哪里？",a="任务始于幽暗城法师区的比索·埃斯沙德，终于银松森林瑟伯切尔的药剂师伦弗利尔。",al={"图勒·鸦爪任务提交","图勒·鸦爪任务在哪里提交","卷轴交付地点"}},{q="伦弗利尔收到卷轴后会发生什么？",a="随着反制药水的研制成功，伦弗利尔会派你去向高级执行官哈德瑞克汇报，为全面突袭芬里斯岛、消灭图勒·鸦爪并收复该岛做好准备。",al={"接下来会发生什么","图勒·鸦爪任务之后","进攻芬里斯岛"}}},fp="15,251,26.380.0,25.329.1,26.359.1,23.296.0,44.192.0,33.187.0,51.195.0,33.148.0,49.184.1"}
P.entries["quest:447"] = {n="致命的配方",s="“死亡处方”是银松森林瑟伯切尔的药剂师伦弗利尔委托的一项炼金术差事。冒险者受命收集灰熊之心和蜘蛛之血，并将这些不稳定的生物试剂运送到幽暗城的皇家药剂师学会交给大药剂师法拉尼尔，以协助研制被遗忘者致命的“The New Plague”。",h="“死亡处方”是银松森林瑟伯切尔的药剂师伦弗利尔委托的一项炼金术差事。冒险者受命收集灰熊之心和蜘蛛之血，并将这些不稳定的生物试剂运送到幽暗城的皇家药剂师学会交给大药剂师法拉尼尔，以协助研制被遗忘者致命的“The New...",kw={"法拉尼尔","新瘟疫","伦弗利尔","皇家药剂师学会","银松森林","粘丝洞","幽暗城"},ang={["faction:Horde"]="被遗忘者的药剂师们通过剧毒的生物配方追求胜利，这是部落新盟友之间一种严酷的战争方式。",["race:Undead"]="为皇家药剂师学会的瘟疫研究做出贡献，是有抱负的被遗忘者为保护他们脆弱的国度免受天灾和人类侵害所能承担的最崇高职责之一。"},sec={{t="对抗双敌的武器",b="身为驻扎在银松森林前线的药剂师，伦弗利尔深知希尔瓦娜斯的人民所面临的严峻困境。在阿尔萨斯的无情军团与人类残部的夹击下，传统战争难见胜算。被遗忘者的宏伟野心在于研制“The New Plague”——一种足以腐蚀生者人类与亡灵天灾的强力工程瘟疫。伦弗利尔的实地研究表明，将粘丝洞的蜘蛛毒液与当地灰熊心脏中的浓缩毒素相结合，可以产生一种剧毒的基底。"},{t="运往Apothecarium",b="一旦从银松森林的荒野中收集到这些器官和血液，就必须将它们送到洛丹伦废墟之下，进入Apothecarium的核心区域。在那里，大药剂师法拉尼尔主持着皇家药剂师学会的宏大计划。法拉尼尔会立即接收伦弗利尔的样本，测试它们的传染特性，从而改进那些或许有朝一日能确保被遗忘者统治整个大陆的配方。"}},faq={{q="收集熊心和蜘蛛血的目的是什么？",a="药剂师伦弗利尔的研究表明，粘丝洞的蜘蛛之血与灰熊心脏中的毒素混合后会产生致命反应。这些试剂共同为皇家药剂师学会测试和研制“The New Plague”提供了关键的原材料。",al={"为什么要熊心","为什么要蜘蛛血","这个配方是做什么用的"}},{q="大药剂师法拉尼尔是谁？",a="大药剂师法拉尼尔是皇家药剂师学会的负责人，驻扎在幽暗城的Apothecarium区。他代表希尔瓦娜斯·风行者统筹所有关于研制“The New Plague”的研究。",al={"法拉尼尔背景故事","法拉尼尔是谁","大药剂师"}},{q="为什么被遗忘者要制造“The New Plague”？",a="由于在人数上处于劣势且受到人类的鄙视，被遗忘者缺乏打赢一场长期常规战争的军事人力。定制的“The New Plague”旨在消灭生者敌人和亡灵天灾，从而确保他们的生存和自主权。",al={"为什么制造新瘟疫","被遗忘者瘟疫动机","新瘟疫背景故事"}},{q="药剂师伦弗利尔在哪里？",a="药剂师伦弗利尔在瑟伯切尔开展他的研究，这是位于银松森林内的主要被遗忘者定居点。",al={"伦弗利尔位置","伦弗利尔在哪里"}},{q="粘丝洞在哪里？",a="粘丝洞是一片被蜘蛛盘踞的荒野，位于银松森林中瑟伯切尔的西北方，那里到处是伦弗利尔所需的巨型蜘蛛。",al={"粘丝洞位置","银松森林哪里找蜘蛛"}},{q="这个任务还有后续吗？",a="是的。大药剂师法拉尼尔会利用运送来的试剂继续他的实验，这直接引出了在Apothecarium内部进一步改进和测试这种致命混合物的后续任务。",al={"死亡处方后续","是否有第二部分"}}},fp="18,204,25.440.0,28.351.0,63.209.0,34.187.0,48.225.0,38.83.0,29.144.0,33.149.0"}
P.entries["quest:448"] = {n="给哈德瑞克的报告",s="《Report to Hadrec》是一份Horde军事调度命令，旨在指示Sepulcher内的勇士去请示Silverpine Forest的战场指挥官。继Apothecary Renferrel和Bethor Iceshard对Lake Lordamere中Scourge存在的调查之后，High Executor Hadrec开始协调突袭Fenris Isle所需的军事准备工作。这标志着行动从魔法侦察转变为直接的战术战争。",h="《Report to Hadrec》是一份Horde军事调度命令，旨在指示Sepulcher内的勇士去请示Silverpine Forest的战场指挥官。继Apothecary Renferrel和Bethor...",kw={"fenris","hadrec","iceshard","ravenclaw","renferrel","瑟伯切尔","silverpine","thule"},ang={["faction:Horde"]="Sepulcher负责协调Horde在Lordaeron的西部防御，保护通往Capital City废墟的道路，防御Scourge的前哨站和人类幸存者。",["race:Undead"]="对于Forsaken而言，Thule Ravenclaw代表着Lich King试图侵入他们家园的奴役意志，因此消灭他已成为关乎民族生存的关键大事。"},sec={{t="Silverpine Forest的局势升级",b="虽然Apothecary Renferrel和法师Bethor Iceshard在探究叛变的死灵法师Thule Ravenclaw所造成的威胁方面投入了大量精力，但仅凭学术研究无法清除日益壮大的Scourge据点。随着Thule Ravenclaw在Fenris Isle上积极奴役着The Restless Dead，Apothecary Renferrel意识到问题已远远超出了炼金术或奥术所能解决的范畴。阻止这种日益严重的感染需要Forsaken军队的坚硬钢铁与严明军纪，这也将问题从药剂师的实验台直接转移到了指挥官的办公桌上。"},{t="High Executor的军火库",b="High Executor Hadrec驻扎在Sepulcher的地下墓穴中，代表Dark Lady指挥着Silverpine Forest的所有战略行动。当Bethor关于Thule Ravenclaw的严峻警告传达到他耳中时，High Executor Hadrec毫不犹豫地采取了行动，因为他深知一名盘踞在Lake Lordamere西岸的死灵法师对Undercity的侧翼构成了致命的威胁。为了确保对该岛屿要塞的突袭取得成功，High Executor Hadrec打开了当地驻军的军火库，在将先遣战斗人员送入战场前为他们装备好武器。"}},faq={{q="谁是High Executor Hadrec？",a="High Executor Hadrec是驻扎在Sepulcher的Forsaken军事指挥官。他负责监督整个Silverpine Forest的前线防御和进攻行动，直接向Undercity领导层负责。",al={"hadrec","谁是hadrec","sepulcher指挥官"}},{q="为什么Apothecary Renferrel要派你去见High Executor Hadrec？",a="Apothecary Renferrel和Bethor Iceshard发现Thule Ravenclaw在Fenris Isle上集结了一支危险的Scourge部队。由于消灭盘踞在此的死灵法师需要的是军事力量和得当的装备，而非仅仅依靠炼金术，因此Apothecary Renferrel指引你去找驻军指挥官。",al={"为什么要报告给hadrec","renferrel与hadrec的联系"}},{q="Sepulcher位于哪里？",a="Sepulcher是一座位于Silverpine Forest中部的Forsaken要塞式定居点和墓穴建筑群，是Horde在该地区的主要枢纽和行动集结地。",al={"sepulcher在哪里","sepulcher位置"}},{q="谁是Thule Ravenclaw？",a="Thule Ravenclaw是一位强大的Scourge死灵法师，他占领了Lake Lordamere中Fenris Isle上的Fenris Keep，并在此复活亡者，在Silverpine Forest的东海岸建立了一个活跃的登陆点。",al={"thule ravenclaw","thule背景故事"}},{q="向High Executor Hadrec报告后会发生什么？",a="High Executor Hadrec会向你发放来自Sepulcher军火库的补给，并下令立即对Fenris Isle发动军事突袭，以消灭Thule Ravenclaw并打破Scourge对Lake Lordamere的控制。",al={"向hadrec报告后做什么","后续任务hadrec"}},{q="High Executor Hadrec提到的Bethor是谁？",a="Bethor Iceshard是一位居住在Undercity的Magic Quarter的Forsaken法师，他的魔法占卜帮助揭示了Thule Ravenclaw仪式确切的性质和危险性。",al={"谁是bethor","比索·埃斯沙德"}}},fp="16,242,24.406.0,27.369.0,28.190.0,49.277.0,31.171.0,23.186.0,39.191.0,34.169.0"}
P.entries["quest:449"] = {n="亡灵哨兵的报告",s="亡灵哨兵的报告是一项至关重要的军事信使任务，需要送达瑟伯切尔的高级执行官哈德瑞克手中。在北方荒野中保护受伤的亡灵哨兵后，你需要将他们收集到的有关意外天灾活动的机密情报带回给被遗忘者的高层指挥部。这份报告改变了被遗忘者对他们在银松森林控制权的评估。",h="亡灵哨兵的报告是一项至关重要的军事信使任务，需要送达瑟伯切尔的高级执行官哈德瑞克手中。在北方荒野中保护受伤的亡灵哨兵后，你需要将他们收集到的有关意外天灾活动的机密情报带回给被遗忘者的高层指挥部。这份报告改变了被遗忘者对他...",kw={"亡灵哨兵","埃兰","哈德瑞克","奎因","兰妮·尤瑞克","报告","天灾军团","瑟伯切尔","银松森林","幽暗城"},ang={["class:Rogue"]="亡灵哨兵代表了被遗忘者间谍活动的巅峰；执行他们至关重要的快报传递任务，证明了你与黑暗女王麾下首席暗影特工的立场一致。",["faction:Horde"]="被遗忘者为从天灾军团手中保卫银松森林而进行的斗争，对于在洛丹伦北部建立一个稳固的部落立足点至关重要。",["race:Undead"]="传递这份情报直接支持了幽暗城的扩张，并向高级执行官哈德瑞克和亡灵哨兵网络证明了你的可靠性。"},sec={{t="前线情报",b="亡灵哨兵是黑暗女王的耳目和匕首，他们深入未开化的荒野，走在正规军之前。在提瑞斯法和银松的边界附近，一支先遣巡逻队在绘制敌军动向时遭遇了毁灭性的抵抗。尽管亡灵哨兵奎因几乎因伤丧命，埃兰也拼死杀出重围，但他们的侦察任务还是获得了对被遗忘者占领银松森林至关重要的情报。"},{t="天灾因素",b="当高级执行官哈德瑞克审阅这份密封的战地报告时，它证实了一个噩耗：天灾军团的无脑军队在银松森林的存在比幽暗城的战略家们预想的要沉重和激进得多。瑟伯切尔的指挥部不仅需要确保废弃人类村庄的安全并平息流浪野兽，还必须在争夺该地区的战斗中为应对天灾军团的协同反击做好准备。"}},faq={{q="什么是亡灵哨兵的报告？",a="这是一份由亡灵哨兵兰妮·尤瑞克代表她那支受伤的侦察小队撰写的战地快报。它汇编了他们对敌对威胁的观察结果，特别是银松森林北部意料之外的天灾活动，并将这些数据直接传递给了瑟伯切尔的区域指挥官。",al={"亡灵哨兵的报告","报告是什么","尤瑞克给了我什么"}},{q="谁是高级执行官哈德瑞克？",a="高级执行官哈德瑞克是负责被遗忘者在银松森林行动的军事指挥官。他驻扎在瑟伯切尔，协调侦察兵、防线以及将天灾军团和敌对人类驱逐出该地区的更广泛战役。",al={"哈德瑞克","高级执行官哈德瑞克","瑟伯切尔指挥官"}},{q="为什么这份报告的信息让哈德瑞克感到惊讶？",a="被遗忘者的领导层原以为银松森林里的天灾军团与提瑞斯法林地和瘟疫之地的激烈战斗相比，不仅分散而且规模很小。亡灵哨兵的伤亡和发现证明，巫妖王的爪牙即使在这么靠南的地方依然根深蒂固，并且极具危险。",al={"为什么感到惊讶","哈德瑞克的反应","银松森林的天灾军团"}},{q="谁是亡灵哨兵？",a="亡灵哨兵是被遗忘者的精英秘密组织，担任刺客、间谍和前线侦察兵，直接受Sylvanas Windrunner指挥。他们在整个争议领土内活动，在正规军进驻之前铲除威胁。",al={"亡灵哨兵","亡灵哨兵背景","被遗忘者潜行者"}},{q="瑟伯切尔位于何处？",a="瑟伯切尔是一座坐落在银松森林中部的墓穴和中央基地营地，位于南北主干道的西侧。它是被遗忘者在全省范围内行动的主要驻军点和休息点。",al={"瑟伯切尔在哪里","瑟伯切尔位置"}},{q="哈德瑞克读完报告后会发生什么？",a="在认识到局势的严重性和银松森林日益增长的威胁后，哈德瑞克指引你继续前往咨询驻扎在瑟伯切尔的其他专家，首先从药剂师伦弗利尔开始，以协助开发针对区域威胁的对策。",al={"下一个任务","接下来做什么","哈德瑞克之后"}}},fx={df12075a={q="为什么兰妮·尤瑞克需要尽快送出报告？",a="兰妮·尤瑞克和她的同伴发现了有关天灾军团活动及银松森林荒野中敌对威胁的重要情报。由于这些信息直接关系到被遗忘者能否守住这片区域，瑟伯切尔的高级执行官哈德瑞克必须立即收到报告，以便军方指挥部采取应对行动。",al={"兰妮·尤瑞克为什么要你做这件事","兰妮·尤瑞克的动机","为什么送出亡灵哨兵的报告"}},de251098={q="为什么兰妮·尤瑞克让你送报告，而不是自己去？",a="兰妮的侦察小队目前无法上路。她的兄弟兼亡灵哨兵同僚Quinn在任务中身受重伤，仍在兰妮照料下慢慢恢复。小队行动受阻，而报告又刻不容缓，兰妮只能依靠你这样身强力壮的旅人，将情报送到瑟伯切尔。",al={"兰妮·尤瑞克为什么找我","兰妮为什么不能亲自送报告","为什么由我来送报告"}}},fp="25,280,22.381.0,18.411.0,32.253.0,28.195.0,54.274.0,26.212.0,31.157.0,43.186.0"}
P.entries["quest:4495"] = {n="好朋友",s="当她的常客埃沃隆没有按时出现在奥达希尔时，迪兰妮亚·月光感到非常不安。她知道埃沃隆经常去北边那座蜘蛛出没的黑丝洞附近的丘陵，于是请求路过的冒险者帮她寻找他。",h="当她的常客埃沃隆没有按时出现在奥达希尔时，迪兰妮亚·月光感到非常不安。她知道埃沃隆经常去北边那座蜘蛛出没的黑丝洞附近的丘陵，于是请求路过的冒险者帮她寻找他。",kw={"好朋友","奥达希尔","迪兰妮亚·月光","埃沃隆","幽影谷","黑丝洞","蜘蛛","泰达希尔"},ang={["class:Druid"]="关注自然平衡的德鲁伊会认识到，黑丝洞附近极具攻击性的林木蜘蛛是困扰这棵大树的广泛腐蚀所带来的症状。",["race:NightElf"]="对于在奥达希尔下开始旅程的年轻卡多雷来说，回应迪兰妮亚的请求是学习社区责任感以及了解威胁这片曾经宁静的林地的蔓延危机的早期课程。"},sec={{t="失踪的访客",b="在幽影谷那宁静的枝桠间，每天的作息规律早已根深蒂固，任何模式上的偏差都会立刻引起注意。迪兰妮亚·月光在奥达希尔的树冠庇护下打理着日常事务，她已经习惯了埃沃隆每天准时的造访。当数小时过去却仍不见他的踪影时，她的担忧驱使她向那些准备前往林地深处的冒险者寻求帮助。"},{t="黑丝洞的险境",b="尽管有林木蜘蛛的威胁，埃沃隆还是有个众所周知的习惯，那就是在幽影谷的北部洼地附近徘徊。随着黑丝洞里爬满了极具攻击性的蛛形纲生物，离开既定路径对于粗心的旅行者来说变得越来越危险。在洞口正西方的崎岖山坡上搜索时，会发现埃沃隆正躲藏在那里，迫切需要援助。"}},faq={{q="迪兰妮亚·月光是谁？",a="迪兰妮亚·月光是一名居住在奥达希尔下方幽影谷的暗夜精灵。她与埃沃隆有着稳定的日常友谊，当他没能遵守约定时间造访时，她会立刻察觉。",al={"迪兰妮亚","迪兰妮亚·月光背景故事","谁开启好朋友任务"}},{q="埃沃隆是谁？",a="埃沃隆是幽影谷的一名暗夜精灵，以在黑丝洞附近的丘陵漫步而闻名。在未能完成对迪兰妮亚·月光的每日拜访后，人们发现他被困在洞穴入口正西方的悬崖上。",al={"埃沃隆","埃沃隆在哪里","失踪的朋友是谁"}},{q="在哪里可以找到埃沃隆？",a="埃沃隆躲藏在幽影谷北部，黑丝洞入口正西方山坡上的岩石和灌木丛中。",al={"埃沃隆位置","寻找埃沃隆","黑丝洞埃沃隆"}},{q="为什么北部洞穴被认为是危险的？",a="黑丝洞及其周围的山坡上到处都是有毒的林木蜘蛛。泰达希尔不断蔓延的腐蚀激怒了这些生物，使得该地区对单独旅行者来说危机四伏。",al={"为什么黑丝洞危险","幽影谷蜘蛛","泰达希尔蜘蛛洞"}},{q="找到埃沃隆之后会发生什么？",a="在找到埃沃隆后，他透露自己在蜘蛛洞附近的意外遭遇让他陷入了困境，随后开启了后续任务“急需帮助的朋友”，以寻求治疗。",al={"好朋友之后的任务","埃沃隆的下一步","急需帮助的朋友任务"}},{q="为什么迪兰妮亚这么快就为埃沃隆担心？",a="埃沃隆每天都在同一时间造访迪兰妮亚。因为他迟到了几个小时，而且经常在危险的蜘蛛洼地附近徘徊，所以她担心他遭遇了不幸。",al={"为什么迪兰妮亚担心","埃沃隆日常","为什么迪兰妮亚会发现"}}},fp="13,168,17.177.0,26.241.0,27.147.0,15.185.0,27.105.0,46.183.0,35.162.1,48.188.0"}
P.entries["quest:4496"] = {n="擒虫先擒王",s="位于加基森的炼金师匹斯特苏格研究过异种虫，并将它们比作蜜蜂，其中的虫后就是它们的弱点。必须制作一个诱饵将它引出来，而这需要用到位于西方的安戈洛环形山的腺体和土壤。",h="位于加基森的炼金师匹斯特苏格研究过异种虫，并将它们比作蜜蜂，其中的虫后就是它们的弱点。必须制作一个诱饵将它引出来，而这需要用到位于西方的安戈洛环形山的腺体和土壤。",kw={"加基森","戈里希","炼金师匹斯特苏格","腺体","异种虫","塔纳利斯","安戈洛环形山","安戈洛的泥土"},sec={{t="诱捕虫后",b="炼金师匹斯特苏格的研究将异种虫比作蜜蜂。消灭蜂巢的虫后，剩下的虫群就会陷入混乱。为了引出虫后，必须调制出一种诱饵，而一旦它被召唤出来，你就是负责解决它的人。"},{t="来自安戈洛的试剂",b="在调制诱饵之前，炼金师匹斯特苏格需要一些试剂。异种虫巢穴位于西边的安戈洛环形山，你必须从那里的虫子身上获取一个腺体。这个腺体不能受损。炼金师匹斯特苏格还需要五份安戈洛的泥土。"}},faq={{q="谁需要腺体和土壤，以及在哪里？",a="位于加基森的炼金师匹斯特苏格。",al={"谁发布了丛林里的混乱","炼金师匹斯特苏格的位置","丛林里的混乱任务发布者"}},{q="炼金师匹斯特苏格调制诱饵需要什么？",a="一个未受损的戈里希腺体（从异种虫身上获得），以及五份安戈洛的泥土。",al={"丛林里的混乱任务物品","炼金师匹斯特苏格需要的试剂","腺体和土壤"}},{q="异种虫巢穴在哪里？",a="在加基森西边的安戈洛环形山里。",al={"戈里希腺体获取地点","异种虫巢穴位置","安戈洛的泥土获取地点"}},{q="为什么炼金师匹斯特苏格要引出虫巢的虫后？",a="炼金师匹斯特苏格的研究将异种虫比作蜜蜂，所以只要虫后一死，剩下的虫群就会陷入混乱。",al={"为什么要杀死虫后","炼金师匹斯特苏格的计划","异种虫蜜蜂理论"}}},fp="20,217,20.229.0,21.252.0,49.35.0,39.116.0,27.44.0,53.113.0"}
P.entries["quest:45"] = {n="罗尔夫的下落",s="“发现罗尔夫的命运”是艾尔文森林中的一项联盟任务，旨在追踪两名失踪的暴风城卫兵。在石碑湖岸边发现卫兵玛拉凯残缺不全的尸体后，足迹通向东边一个充满敌意的鱼人村落，去揭开他同伴罗尔夫的下场。",h="“发现罗尔夫的命运”是艾尔文森林中的一项联盟任务，旨在追踪两名失踪的暴风城卫兵。在石碑湖岸边发现卫兵玛拉凯残缺不全的尸体后，足迹通向东边一个充满敌意的鱼人村落，去揭开他同伴罗尔夫的下场。",kw={"艾尔文森林","卫兵托马斯","玛拉凯","鱼人","罗尔夫","罗尔夫·哈特福德","石碑湖"},ang={["class:Warrior"]="站在罗尔夫·哈特福德的尸体旁，这残酷地提醒着人们，服务于王国的边境步兵们正面临着血腥的现实。",["faction:Alliance"]="找到罗尔夫证实了暴风城农村边境的脆弱性，在那里的驻军短缺使得基础巡逻队暴露在致命的野外攻击之下。"},sec={{t="蹼状足迹的踪迹",b="卫兵托马斯在艾尔文森林东部派遣了巡逻队以应对日益增长的威胁，但两名卫兵——玛拉凯和罗尔夫——在石碑湖岸边失踪了。调查玛拉凯那被啃食得残缺不全的遗骸时，发现泥地上留下了蹼状的足迹，这些足迹沿着水边向东延伸，直指一个破败的鱼人营地。"},{t="巡逻的终点",b="顺着这些足迹，你来到了沿海鱼人定居点的中心。那里躺着另一具被这些生物剥去装备的尸体。在这名牺牲士兵的脖子上挂着一枚刻有文字的奖章，确认了他的身份是步兵罗尔夫·哈特福德，这证明两名卫兵都没能在伏击中幸存。"}},faq={{q="罗尔夫是谁？",a="罗尔夫·哈特福德是一名暴风城步兵，在卫兵托马斯的指挥下，负责与卫兵玛拉凯一起巡逻艾尔文森林东部。两名卫兵在石碑湖附近被鱼人淹没并杀害。",al={"罗尔夫是谁","步兵罗尔夫","罗尔夫·哈特福德"}},{q="罗尔夫的尸体在哪里？",a="罗尔夫的尸体位于石碑湖的南岸更东处，藏在靠近湖边的一座鱼人村落里。",al={"罗尔夫的位置","罗尔夫在哪里","寻找罗尔夫"}},{q="卫兵为什么会在石碑湖附近？",a="卫兵托马斯在艾尔文森林东部的河流和湖泊沿岸部署了卫兵，以监视鱼人和豺狼人的入侵，但人手不足的巡逻队在突如其来的协同攻击面前显得不堪一击。",al={"卫兵为何失踪","卫兵在做什么","艾尔文森林巡逻"}},{q="如何确认那具尸体属于罗尔夫？",a="在那具破烂不堪的尸体的脖子上，挂着一枚金属奖章，上面清晰地刻着“步兵罗尔夫·哈特福德”的名字。",al={"罗尔夫的奖章","确认罗尔夫身份"}},{q="找到罗尔夫后会发生什么？",a="随着玛拉凯和罗尔夫的悲惨命运得到确认，你的任务是返回西部的东谷伐木场大桥，将这个噩耗报告给卫兵托马斯。",al={"罗尔夫任务后的下一步","找到罗尔夫后做什么"}},{q="石碑湖的鱼人是异常的威胁吗？",a="艾尔文森林的鱼人活动变得异常凶猛且具有协同性，它们深入内陆，侵入石碑湖和河流，威胁着当地的贸易和单独行动的巡逻队。",al={"艾尔文森林的鱼人威胁","鱼人为何攻击"}}},fp="20,157,24.162.0,17.246.1,13.189.1,29.125.1,46.188.0,46.103.1,32.169.1,54.176.0"}
P.entries["quest:450"] = {n="致命的配方",s="大药剂师法拉尼尔委派部落冒险者从焚木村寻回药剂师伯纳德遗失的研究成果。伯纳德成为了大法师阿鲁高暗影魔法的受害者，留下了一些关于曾摧毁洛丹米尔湖水生生物的远古瘟疫的关键笔记。",h="大药剂师法拉尼尔委派部落冒险者从焚木村寻回药剂师伯纳德遗失的研究成果。伯纳德成为了大法师阿鲁高暗影魔法的受害者，留下了一些关于曾摧毁洛丹米尔湖水生生物的远古瘟疫的关键笔记。",kw={"阿鲁高","伯纳德","法拉尼尔","日记","洛丹米尔","焚木村","伦弗利尔","瑟伯切尔"},ang={["faction:Horde"]="在银松森林协助皇家药剂师学会，有助于保卫被遗忘者的边境，抵御阿鲁高释放的各种狂野恐怖之物。",["race:Undead"]="皇家药剂师学会展现出了冷酷的实用主义：当像伯纳德这样有前途的同僚陷入疯狂时，他的个人悲剧便被无视，取而代之的是挽救他那致命的研究。"},sec={{t="迷失于暗影的思绪",b="在陨落之前，药剂师伯纳德曾被认为是皇家药剂师学会最有前途的研究人员之一。他驻扎在焚木村，调查过去的生态灾难，以协助被遗忘者的炼金研究。然而，当大法师阿鲁高在银松森林释放其黑暗巫术时，伯纳德屈服于诅咒，堕落成了一个在法师奴役下毫无思想的仆从。"},{t="洛丹米尔湖的秘密",b="尽管大药剂师法拉尼尔认为伯纳德已经无药可救，但他的研究对学会而言依然极具价值。伯纳德曾一直在记录一种很久以前就消灭了洛丹米尔湖所有水生生物的被遗忘瘟疫的特性。从焚木村旅店寻回他的日记并将其交给瑟伯切尔的药剂师伦弗利尔，这能确保皇家药剂师学会可以将这些致命的特性改编用于黑暗女王的军火库。"}},faq={{q="谁是药剂师伯纳德？",a="药剂师伯纳德曾是皇家药剂师学会驻银松森林的一名天才研究员。当大法师阿鲁高在该地区施下黑暗诅咒，粉碎了伯纳德的意志并将他禁锢在焚木村作为奴仆时，他前途无量的职业生涯便画上了句号。",al={"伯纳德背景故事","伯纳德是谁","药剂师伯纳德 焚木村"}},{q="为什么皇家药剂师学会想要伯纳德的日记？",a="在精神崩溃之前，伯纳德一直在记录一种很久以前就杀死了洛丹米尔湖所有水生生物的远古瘟疫。学会寻求这些记录是为了了解这种剧毒媒介，并将其致命的机理纳入他们正在进行的研究中。",al={"为什么要获取日记","伯纳德日记的用途","洛丹米尔湖瘟疫笔记"}},{q="伯纳德的日记在哪里？",a="日记存放在焚木村旅店楼上的伯纳德书房里，位于村庄后部。这位受折磨的药剂师依然守卫着他曾经的住所。",al={"日记在哪里","寻找伯纳德的日记","焚木村旅店日记"}},{q="谁来接收寻回的日记？",a="日记必须交给药剂师伦弗利尔，他负责在银松森林的瑟伯切尔监督皇家药剂师学会的实地行动。",al={"谁接收伯纳德的日记","日记交给谁","日记交到哪里"}},{q="焚木村发生了什么？",a="焚木村受到了大法师阿鲁高的腐化影响，他从附近的影牙城堡释放了暗影魔法。诅咒扭曲了村民的心智和身体，使他们受制于阿鲁高的黑暗意志。",al={"焚木村诅咒","焚木村怎么了","阿鲁高的焚木村诅咒"}},{q="谁是大药剂师法拉尼尔？",a="大药剂师法拉尼尔是皇家药剂师学会的负责人，他在幽暗城的Apothecarium指挥行动。他直接监督新型瘟疫和毒药的制造，以保卫被遗忘者并铲除他们的敌人。",al={"法拉尼尔","谁发布了死亡配方任务","幽暗城药剂师领袖"}}},fp="18,202,21.359.0,29.444.1,25.210.0,60.160.0,34.172.0,35.147.0,34.167.0,34.200.0"}
P.entries["quest:4504"] = {n="极度粘稠的沥青",s="加基森的特兰雷克想要快速赚一笔，他有个新点子：制作一种超级粘合剂。制作这种粘合剂的焦油必须取自安戈洛环形山北部，焦油坑附近的野兽。特兰雷克愿意分享一小部分利润。",h="加基森的特兰雷克想要快速赚一笔，他有个新点子：制作一种超级粘合剂。制作这种粘合剂的焦油必须取自安戈洛环形山北部，焦油坑附近的野兽。特兰雷克愿意分享一小部分利润。",kw={"叶绿素","加基森","胶水","超级粘性焦油","塔纳利斯","焦油坑","特兰雷克","安戈洛环形山"},sec={{t="一个粘人的主意",b="特兰雷克希望这个最新的点子能带来快钱，并许诺给你一小部分利润。普通的焦油粘性不够。他需要十二份样本，必须从安戈洛环形山北部焦油坑附近的生物身上采集。"},{t="为什么要找那些野兽",b="那些焦油坑附近的植物状生物，它们的皮肤里含有叶绿素。将其与焦油混合，就能制成超级粘合剂。"},{t="焦油到手之后",b="特兰雷克处理了这些焦油，结果很快发现双手粘在了一起。他当即改变了主意：特兰雷克认定，开发一种超级焦油清洁剂才是真正的生财之道。"}},faq={{q="谁在索要这种粘性焦油？",a="加基森的特兰雷克。",al={"谁发放超级粘合剂任务","超级粘合剂任务发放者","特兰雷克任务"}},{q="为什么焦油必须取自野兽？",a="普通的焦油粘性不够。焦油坑附近的植物状生物的皮肤里含有叶绿素，这能让焦油变得超级粘。",al={"为什么是野兽焦油","普通焦油与粘性焦油的区别","为什么要从野兽身上获取焦油"}},{q="那些焦油野兽在哪里？",a="在安戈洛环形山北部的焦油坑旁边。",al={"超级粘性焦油在哪里","焦油野兽位置","安戈洛焦油坑"}},{q="特兰雷克打算用这些焦油做什么？",a="特兰雷克想把这些焦油制成超级粘合剂来赚快钱，并承诺给提供帮助的人一小部分利润。",al={"特兰雷克的目标","超级粘合剂的目的","为什么特兰雷克想要焦油"}}},fp="12,214,13.231.0,14.122.0,20.167.1,28.23.0,42.144.0,25.43.0,43.123.0"}
P.entries["quest:4507"] = {n="捕捉皇后",s="完成“丛林混乱”后，炼金师匹斯特苏格会把诱饵交给你，并派遣你深入安戈洛环形山中的其拉虫巢。这个诱饵的目的是引出戈利什虫巢女王，匹斯特苏格想要把它的脑部带回加基森进行研究。",h="完成“丛林混乱”后，炼金师匹斯特苏格会把诱饵交给你，并派遣你深入安戈洛环形山中的其拉虫巢。这个诱饵的目的是引出戈利什虫巢女王，匹斯特苏格想要把它的脑部带回加基森进行研究。",kw={"大脑","加基森","戈利什","诱饵","匹斯特苏格","女王","其拉虫","塔纳利斯","安戈洛"},sec={{t="诱饵与水晶",b="匹斯特苏格给了你这个诱饵。据推测，虫巢网络中有一块水晶，被其拉虫用来作为整个虫巢的调谐装置，而孵化场是搜寻它的最佳地点。将诱饵用在那块水晶上，女王应该就会现身，不过很可能会有几名卫兵伴随左右。"},{t="女王的脑部",b="匹斯特苏格要求将女王的脑部带回加基森。匹斯特苏格承认这听起来很恶心，但表示这个脑部对于研究来说至关重要。"},{t="女王陨落之后",b="匹斯特苏格怀疑其拉虫可能受到某种邪恶智能的操控，想到是什么在指挥这种阴险的生物，他就感到战栗。当脑部送达时，匹斯特苏格称这是一场伟大的胜利，但他怀疑这并非其拉虫存在的全部规模，并表示事情解决得太过顺利了。"}},faq={{q="戈利什虫巢女王在哪里？",a="她是在安戈洛环形山的其拉虫巢内被召唤出来的，需要对匹斯特苏格认为位于孵化场内的一块水晶使用诱饵。",al={"戈利什女王位置","其拉虫女王在哪里","去哪里找戈利什女王"}},{q="虫巢里的水晶有什么用？",a="匹斯特苏格认为，其拉虫在虫巢网络中使用了一块水晶，作为整个虫巢的调谐装置。诱饵就是为了那块水晶准备的，孵化场就是尝试的地方。",al={"虫巢水晶","女王诱饵水晶","使用女王诱饵"}},{q="为什么匹斯特苏格想要女王的脑部？",a="匹斯特苏格表示它必须被研究，并要求将其带到加基森。",al={"为什么需要戈利什大脑","戈利什女王大脑的用途","匹斯特苏格的研究"}},{q="在此之前需要做什么？",a="在此之前是“丛林混乱”，在那项任务中，匹斯特苏格要求获得一个气味腺体和安戈洛的泥土来调制诱饵。",al={"卒子吃掉王后前置任务","卒子吃掉王后的前一个任务是什么","前置任务"}}},fp="19,240,24.290.0,17.146.0,21.299.1,32.133.0,36.175.0,43.70.0,23.100.0"}
P.entries["quest:4508"] = {n="临危不惧",s="女王倒下后，炼金师匹斯特苏格希望这些最新发现能够传达给那些有能力采取行动的人。你带着安戈洛报告前往达纳苏斯的Temple of the Moon，去见格拉希娜·灵风。",h="女王倒下后，炼金师匹斯特苏格希望这些最新发现能够传达给那些有能力采取行动的人。你带着安戈洛报告前往达纳苏斯的Temple of the Moon，去见格拉希娜·灵风。",kw={"达纳苏斯","加基森","格拉希娜·灵风","匹斯特苏格","其拉虫人","塔纳利斯","temple of the moon","安戈洛报告"},sec={{t="致达纳苏斯的报告",b="匹斯特苏格说，这些研究发现必须送到能有所作为的人手中，因为单靠加基森无法应对。最新的报告必须送到位于达纳苏斯的格拉希娜·灵风手中，匹斯特苏格希望能在Temple of the Moon找到她。她在联盟的大人物中很有交情，如果能把他们拉进来，或许还有一线生机。"},{t="格拉希娜的回应",b="格拉希娜称那些无法放下对部落仇恨的人是蠢货，并表示除非把他们直接扔进虫巢里，否则她无法进一步证明其拉虫人的威胁。她对这份报告感到欣慰，但也怀疑它是否有帮助，因为联盟除了部落之外，对任何威胁都视而不见，甚至连达纳苏斯的领导层对于这种威胁是什么也意见不一。她说，范达尔·鹿盔推测这些其拉虫人并不像她所认为的那样是某种古老的危险。她敦促你继续致力于击败其拉虫人。"}},faq={{q="是谁派你带着报告去的？",a="来自加基森的炼金师匹斯特苏格。",al={"谁开启了暴风雨前的宁静","暴风雨前的宁静任务发布者","暴风雨前的宁静在哪里开始"}},{q="这份报告必须送到哪里？",a="送到达纳苏斯的格拉希娜·灵风那里，匹斯特苏格最后知道她是在Temple of the Moon。",al={"我应该把匹斯特苏格的报告交给谁","格拉希娜·灵风在哪里","暴风雨前的宁静交任务"}},{q="为什么匹斯特苏格要把报告发给格拉希娜·灵风？",a="加基森无法单独处理此事。格拉希娜在联盟的大人物中很有交情，如果能把他们拉进来，或许还有一线生机。",al={"为什么要发往达纳苏斯","为什么是格拉希娜·灵风"}},{q="在此任务之前的是什么？",a="“吃掉女王”，在那次任务中你被派去对付戈里什虫后。",al={"暴风雨前的宁静的前置条件","暴风雨前的宁静的上一个任务"}}},fp="21,199,22.371.0,16.510.1,30.37.0,35.101.0,59.145.0,32.73.0"}
P.entries["quest:4509"] = {n="临危不惧",s="女王陨落后，炼金师匹斯特苏格希望最新的发现能送到那些能够采取行动的人手中。你要将匹斯特苏格的安戈洛报告交给奥格瑞玛的基尔兹宾·鼓眼。",h="女王陨落后，炼金师匹斯特苏格希望最新的发现能送到那些能够采取行动的人手中。你要将匹斯特苏格的安戈洛报告交给奥格瑞玛的基尔兹宾·鼓眼。",kw={"暴风雨前的宁静","暗影裂口","加基森","奥格瑞玛","匹斯特苏格","其虫","塔纳利斯","基尔兹宾·鼓眼"},sec={{t="奥格瑞玛的报告",b="匹斯特苏格说，既然加基森无法独自应对，那么今日的发现必须送到可能有所作为的人手中。这份最新的报告要送给奥格瑞玛的基尔兹宾·鼓眼，匹斯特苏格认为他应该还在暗影裂口的上层。基尔兹宾在部落高层有朋友，如果能争取到他们，或许还有一线生机。"},{t="基尔兹宾的回答",b="基尔兹宾称那些只看得到对联盟的仇恨而看不到其他东西的人为傻瓜，并表示除了把他们扔进虫巢里，他无法进一步证明其虫的威胁。他很高兴收到这份报告，但怀疑它是否有帮助，因为部落除了联盟以外，无视任何威胁。如果事实传到萨尔耳中，他或许会采取行动，但他正受到各方矛盾建议的困扰。基尔兹宾敦促你继续致力于击败其虫。"}},faq={{q="是谁派你送交这份报告的？",a="加基森的炼金师匹斯特苏格。",al={"暴风雨前的宁静任务给予者","谁发布暴风雨前的宁静","匹斯特苏格任务"}},{q="基尔兹宾·鼓眼在哪里？",a="在奥格瑞玛。匹斯特苏格认为他在暗影裂口的上层。",al={"基尔兹宾·鼓眼位置","基尔兹宾在哪里","基尔兹宾·鼓眼奥格瑞玛"}},{q="为什么匹斯特苏格要把报告送给基尔兹宾·鼓眼？",a="加基森无法独自做到这一点。基尔兹宾在部落高层有朋友，如果能争取到他们，或许还有一线生机。",al={"为什么将报告送往奥格瑞玛","匹斯特苏格动机"}},{q="在此之前直接发生的是什么？",a="“皇后之死”，在该任务中你被派去追捕戈里希虫巢的虫后。",al={"暴风雨前的宁静先决条件","暴风雨前的宁静前置任务"}}},fp="21,183,22.366.0,17.443.1,30.37.0,27.76.0,57.143.0,32.73.0"}
P.entries["quest:451"] = {n="致命的配方",s="“死亡配方”这一任务总结了对一名已故研究员调查结果的后续工作，指引冒险者前往洛丹米尔湖收集稀有的生物试剂。被遗忘者通过回收收获的苔藓和一种奇怪的肿瘤，为幽暗城的皇家药剂师学会大药剂师法拉尼尔提供了必要的组件。这项工作直接支持了皇家药剂师学会开发新型瘟疫的总体目标。",h="“死亡配方”这一任务总结了对一名已故研究员调查结果的后续工作，指引冒险者前往洛丹米尔湖收集稀有的生物试剂。被遗忘者通过回收收获的苔藓和一种奇怪的肿瘤，为幽暗城的皇家药剂师学会大药剂师法拉尼尔提供了必要的组件。这项工作直接...",kw={"死亡配方","apothecarium","贝拉德","黎明岛","法拉尼尔","硬瘤","湖泊爬行者","洛丹米尔湖","湖泊潜伏者","新型瘟疫","伦弗利尔","邪鳍鱼人"},ang={["faction:Horde"]="被遗忘者药剂师欢迎盟友部落战士帮助他们收集新型瘟疫的试剂。",["race:Undead"]="完成贝拉德未竟的实验直接增强了黑暗女王的愿景，证明了即使在死亡之后，每一位被遗忘者的头脑都在为种族的生存做出贡献。"},sec={{t="研究的遗产",b="药剂师贝拉德因阿鲁高的诅咒而丧命，这对皇家药剂师学会是一次沉重的打击，但他留下的野外日志为银松森林和洛丹米尔湖被污染的生物学提供了至关重要的见解。驻扎在瑟伯切尔的药剂师伦弗利尔仔细研究了贝拉德留下的笔记，发现他记录了当地淡水生物中一些极具潜力的特性。伦弗利尔并没有让贝拉德的牺牲付诸东流，而是委派部落的勇士去实现他那位已故同事的遗愿。"},{t="洛丹米尔湖的危险",b="收集贝拉德指定的试剂需要冒险前往黎明岛，这是一组位于洛丹米尔湖东部水域、笼罩在迷雾中的岛屿。栖息在这些岛屿上的湖泊潜伏者和湖泊爬行者会采集在受污染水域中生存的特殊苔藓。更难寻获的是硬瘤，这是一种奇异的赘生物，贝拉德曾指出它存在于沿着安伯米尔附近的小岛和湖泊南岸筑巢的邪鳍鱼人部落中。"},{t="为Apothecarium提供燃料",b="这些样本一旦被收集，就会绕过瑟伯切尔，直接被送往幽暗城的Apothecarium，交到大药剂师法拉尼尔手中。法拉尼尔认为这些奇怪的突变是研制一种能够根除天灾军团和活体敌人的新型瘟疫的关键步骤。贝拉德的研究被迅速整合到学会正在进行的坩埚大缸中，使被遗忘者距离他们的终极武器又近了一步。"}},faq={{q="为什么皇家药剂师学会需要苔藓和肿瘤？",a="药剂师贝拉德的野外日志中记录道，在湖泊野兽身上发现的水生苔藓和当地邪鳍鱼人身上生长的奇异硬瘤具有独特的生物特性。大药剂师法拉尼尔利用这些罕见的突变试剂来酿造和提炼皇家药剂师学会的新型瘟疫。",al={"为什么需要苔藓和肿瘤","药剂师配方配料","肿瘤有什么用"}},{q="贝拉德是谁？",a="药剂师贝拉德是皇家药剂师学会的一名研究员，在银松森林开展工作。在他因阿鲁高的诅咒变成一个无脑的仆从后，他留下的野外日志为药剂师伦弗利尔和大药剂师法拉尼尔提供了继续其工作所需的重要试剂规格。",al={"药剂师贝拉德","贝拉德是谁","贝拉德日志"}},{q="黎明岛位于哪里？",a="黎明岛是一组位于洛丹米尔湖东部的小岛，就在银松森林的东面。岛上到处都是湖泊潜伏者、湖泊爬行者和敌对的邪鳍鱼人部落。",al={"黎明岛在哪里","黎明岛位置","湖泊潜伏者位置"}},{q="谁是大药剂师法拉尼尔？",a="大药剂师法拉尼尔是皇家药剂师学会的领袖，驻扎在幽暗城的Apothecarium深处。他代表希尔瓦娜斯·风行者监管所有关于化学战、生物混合剂以及新型瘟疫制造的研究与开发。",al={"法拉尼尔","谁是法拉尼尔","大药剂师法拉尼尔"}},{q="为什么邪鳍鱼人会长出硬瘤？",a="洛丹米尔湖周围的水域和湖岸受到了枯萎的腐败和附近奥术冲突的严重扭曲。在邪鳍鱼人身上发现的硬瘤是由这种受污染的环境导致的罕见异常赘生物，这使它们引起了被遗忘者巨大的科学兴趣。",al={"为什么鱼人有肿瘤","邪鳍鱼人肿瘤背景","硬瘤鱼人"}},{q="这个任务与新型瘟疫有什么联系？",a="整个“死亡配方”系列任务是一项与新型瘟疫的开发直接挂钩的试剂收集工作。当像伦弗利尔这样的初级药剂师破译并收集区域材料时，所有的物资都会被直接汇集到法拉尼尔在幽暗城的中央瘟疫酿造中心。",al={"与新型瘟疫的联系","新型瘟疫任务线","这是瘟疫吗"}}},fp="18,262,20.437.0,29.362.0,24.342.1,60.288.0,15.265.0,36.172.0,34.256.0,49.224.0,46.212.0"}
P.entries["quest:4512"] = {n="远方的软泥怪",s="在铁炉堡繁忙的大厅里，侏儒研究员拉里斯·空轮正试图通过研究软泥怪和黏液，来揭开艾泽拉斯进化的秘密。由于对皇家药剂师协会对这些邪恶泥潭产生的浓厚兴趣感到好奇，他委托联盟的冒险者前往受到腐蚀的费伍德森林收集样本。",h="在铁炉堡繁忙的大厅里，侏儒研究员拉里斯·空轮正试图通过研究软泥怪和黏液，来揭开艾泽拉斯进化的秘密。由于对皇家药剂师协会对这些邪恶泥潭产生的浓厚兴趣感到好奇，他委托联盟的冒险者前往受到腐蚀的费伍德森林收集样本。",kw={"受诅咒的软泥怪","探险者协会","费伍德森林","诺莫瑞根","铁炉堡","拉里斯·空轮","软泥怪","皇家药剂师协会","黏液","被污染的软泥怪"},ang={["faction:Alliance"]="监测皇家药剂师协会的收集习惯，可以为联盟提供关于幽暗城可能正在炮制何种险恶药剂的重要情报。",["race:Dwarf"]="尽管传统的矮人挖掘者更喜欢石头和金属，而不是胶状淤泥，但探险者协会依然从拉里斯古怪的驱动力中受益匪浅。",["race:Gnome"]="拉里斯体现了侏儒在失去诺莫瑞根后，重建声誉和尊严的不懈进取精神。"},sec={{t="一种奇怪的执念",b="尽管大多数探险者协会的学者都关心古代泰坦遗物或矮人的家谱，但拉里斯·空轮却将他充满好奇的心思放在了一个更黏糊的研究对象上：软泥怪。这些活着的泥潭遍布湿地、被诅咒的森林和潮湿的废墟，它们打破了常规的生物分类。在目睹了被遗忘者药剂师在洛丹伦各地收集黏液样本后，拉里斯决心弄清楚究竟是什么让这些胶状怪物对幽暗城的炼金术士如此具有吸引力。"},{t="原始的分泌物",b="拉里斯持有一种颇具争议的理论，即软泥怪并非单纯的不自然害虫或魔法副产品，而是与艾泽拉斯行星起源息息相关的原始分泌物。为了证明这一假说，他派遣勇敢的斥候跨越海洋，前往费伍德森林那被枯萎笼罩的树冠下，用特制的罐子捕捉受诅咒的软泥怪和被污染的软泥怪样本。"},{t="证明侏儒的价值",b="在拉里斯的学术追求背后，隐藏着许多流离失所的族人所共有的深刻个人动机。在诺莫瑞根遭遇灾难性的辐射危机后，成千上万的侏儒在铁炉堡的大锻炉里找到了避难所。通过为探险者协会取得一项突破性的发现，拉里斯希望让那些持怀疑态度的矮人闭嘴，并向他们证明，接纳侏儒进入这座山中之城绝非单纯的施舍，而是对联盟科学界的一笔宝贵财富。"}},faq={{q="拉里斯·空轮是谁？",a="拉里斯·空轮是一位居住在铁炉堡的侏儒研究员和学者。他与探险者协会合作，致力于研究艾泽拉斯各地软泥怪和黏液的生物起源。",al={"拉里斯·空轮","谁是任务给予者","研究软泥怪的侏儒"}},{q="为什么拉里斯如此关心软泥怪？",a="拉里斯怀疑软泥怪可能作为原始分泌物，与艾泽拉斯的行星起源有关。此外，注意到被遗忘者的皇家药剂师协会正在积极收集黏液样本，这让他渴望在部落之前揭开它们的秘密特性。",al={"为什么要研究黏液","为什么需要软泥怪瓶","软泥怪理论"}},{q="你在哪里收集软泥怪样本？",a="样本必须使用拉里斯提供的空玻璃容器，从徘徊在卡利姆多北部费伍德森林腐化林地的受诅咒软泥怪和被污染的软泥怪身上收集。",al={"软泥怪在哪里","被污染的软泥怪位置","受诅咒的软泥怪位置"}},{q="为什么被遗忘者要收集软泥怪？",a="皇家药剂师协会经常利用毒素、枯萎病和生物怪物进行实验，以推进被遗忘者的炼金术。他们对原始软泥怪的兴趣向联盟学者表明，这些生物体内含有剧毒或致突变的化合物。",al={"幽暗城的软泥怪","皇家药剂师协会的黏液","为什么被遗忘者需要软泥怪"}},{q="这个任务与诺莫瑞根的陷落有什么联系？",a="在诺莫瑞根因为石腭怪和辐射而陷落后，拉里斯深感身为铁炉堡难民的压力。他相信为探险者协会赢得一项重大的科学成就，将证明为侏儒提供庇护对矮人东道主来说是真正值得的。",al={"诺莫瑞根的关联","矮人与侏儒的关系","铁炉堡的侏儒难民"}},{q="交付样本后会发生什么？",a="拉里斯会立即在他位于铁炉堡的实验室里测试这些标本，进一步发展他关于软泥怪分类学和元素起源的理论。",al={"黏液任务后续","交付软泥怪瓶后下一步"}}},fp="30,190,20.346.0,24.280.0,21.354.0,24.170.0,39.218.0,37.154.0,38.199.0,54.247.0,43.137.0"}
P.entries["quest:4513"] = {n="远方的软泥怪",s="在对受污染的样本进行了初步研究后，侏儒研究员拉里斯·空轮开始寻找未受污染的软泥怪样本，以了解这些奇异的生物是如何适应环境的。他意识到软泥怪会吸收像费伍德森林这类地方的腐蚀性本质，于是他派遣冒险者前往卡利姆多各地，去发现并收集纯净、未受污染的样本。",h="在对受污染的样本进行了初步研究后，侏儒研究员拉里斯·空轮开始寻找未受污染的软泥怪样本，以了解这些奇异的生物是如何适应环境的。他意识到软泥怪会吸收像费伍德森林这类地方的腐蚀性本质，于是他派遣冒险者前往卡利姆多各地，去发现并...",kw={"费伍德森林","胶质软泥怪","铁炉堡","拉里斯·空轮","软泥怪研究","纯净样本瓶","安戈洛环形山"},ang={["faction:Alliance"]="在铁炉堡的指挥下，联盟冒险者受命前往卡利姆多未驯服的荒野，以支持侏儒的科学研究。",["race:Gnome"]="拉里斯体现了典型的侏儒科学方法，坚持在得出广泛结论之前分离变量并找到未受污染的对照组。"},sec={{t="纯净之事",b="拉里斯·空轮在铁炉堡进行的初步实验立刻遇到了障碍：他之前检查的软泥怪样本被费伍德森林的黑暗能量彻底污染了。虽然这证明了软泥怪会吸收并反映周围环境的特征，但这让他缺乏对照组。为了了解软泥怪生命的基准特性，他需要未受恶魔腐蚀或城市污秽影响的样本。"},{t="追踪原始粘液",b="在饱受腐蚀与战火蹂躏的艾泽拉斯，寻找未受污染的粘液绝非易事。线索最终指向了遥远的南方，即史前盆地安戈洛环形山，那里的胶质软泥怪在与世隔绝的原始生态系统中繁衍生息。通过从这些野生生物身上获取样本，冒险者为拉里斯提供了他所需要的稀有纯净物质，以揭示这些无定形生物是如何与艾泽拉斯的生命生物群落相互作用的。"}},faq={{q="为什么拉里斯·空轮需要纯净的软泥怪样本？",a="他早期的样本受到了费伍德森林腐蚀性能量的污染。为了验证粘液会适应并反映其直接环境的理论，拉里斯需要来自未受污染栖息地的原始样本，作为研究的干净基准。",al={"为什么需要纯净软泥怪","拉里斯纯净粘液","什么是纯净软泥怪"}},{q="纯净的软泥怪在哪里？",a="纯净的样本可以从栖息在卡利姆多南部安戈洛环形山那郁郁葱葱的史前荒野中的胶质软泥怪身上采集。",al={"在哪里寻找纯净软泥怪","纯净样本瓶位置","纯净粘液在哪里"}},{q="拉里斯·空轮是谁？",a="他是一位驻扎在铁炉堡的好奇侏儒研究员，致力于揭开艾泽拉斯粘液和软泥怪的生物学奥秘。",al={"拉里斯是谁","拉里斯·空轮背景故事"}},{q="为什么软泥怪对研究人员如此有吸引力？",a="软泥怪拥有独特的生物适应性，能够轻易地吸收并反映它们所居住地区的魔法、环境和腐蚀性特征。",al={"为什么要研究粘液","软泥怪背景故事"}},{q="这是拉里斯之前任务的后续吗？",a="是的。拉里斯之前曾要求收集软泥怪以开始他的研究，但最初的样本显示出严重的费伍德森林恶魔污染，促使他寻找未受玷污的粘液。",al={"拉里斯之前的任务","在此之前发生了什么"}},{q="拉里斯打算用这些样本做什么？",a="他打算将纯净样本与受污染的样本进行对比，以了解环境变化如何影响生物，进而了解艾泽拉斯更广泛的种群。",al={"拉里斯软泥怪研究","粘液的用途"}}},fp="30,207,18.266.0,25.190.1,49.192.0,33.92.0,24.124.0,47.103.0,43.126.0,46.160.0"}
P.entries["quest:452"] = {n="焚木村中的伏击",s="焚木村伏击是亡灵哨兵在受诅咒的焚木村内协调的一次关键打击。通过暗杀当地的人类议会，被遗忘者希望打破大法师阿鲁高对受诅咒居民的控制，并削弱他那座耸立在上方的高耸堡垒。",h="焚木村伏击是亡灵哨兵在受诅咒的焚木村内协调的一次关键打击。通过暗杀当地的人类议会，被遗忘者希望打破大法师阿鲁高对受诅咒居民的控制，并削弱他那座耸立在上方的高耸堡垒。",kw={"阿鲁高","亡灵哨兵费雷亚","费雷亚","莫里森镇长","焚木村伏击","焚木议会","影牙城堡","银松森林"},ang={["class:Rogue"]="这次伏击是典型的亡灵哨兵战术：渗透敌方据点，潜伏待命，并在敌人的权力中心清除敌方指挥官。",["faction:Horde"]="破坏阿鲁高的傀儡网络削弱了威胁部落穿越银松森林前往南部边界通道的更大隐患。",["race:Undead"]="对于被遗忘者来说，确保银松森林南部的安全对于保卫幽暗城的边境至关重要，而消灭阿鲁高的走狗让他们距离夺取焚木村又近了一步。"},sec={{t="打击傀儡",b="亡灵哨兵费雷亚潜伏在焚木村的市政厅内，静候村庄领导层的到来。当大法师阿鲁高在影牙城堡内闭门不出，专心钻研他的黑暗法术时，他依靠当地的焚木议会作为傀儡来维持受诅咒民众间的秩序。费雷亚打算通过一场迅猛的伏击消灭这些领导层，她希望没有了议会的调停，在村庄街道和周边树林游荡的狼人就会摆脱阿鲁高的统治。"},{t="斩首行动",b="这次伏击的目标是市政管理部门的所有在职成员，最终以莫里森镇长的死亡告终。通过在议员们走进会议室时将其清除，被遗忘者给予了村庄行政指挥链一次沉重的打击。幽暗城认为这次屠杀不仅是复仇，更是彻底征服焚木村并围攻影牙城堡中那名疯狂大法师的战略先决条件。"}},faq={{q="亡灵哨兵费雷亚是谁？",a="亡灵哨兵费雷亚是被遗忘者顶尖的间谍和暗杀组织——亡灵哨兵的一名特工。她深入敌后，直接在焚木村内建立了立足点，以协调对大法师阿鲁高当地基础设施的打击。",al={"费雷亚","亡灵哨兵费雷亚","谁发布焚木村伏击"}},{q="为什么被遗忘者要杀死焚木议会？",a="阿鲁高利用议会作为政治傀儡，让受诅咒的人类村民保持顺从并处于控制之下。被遗忘者认为，消灭这些领导者会使焚木村陷入混乱，并导致狼人反抗阿鲁高。",al={"为什么要杀死焚木议会","焚木议会的作用","焚木议会的背景故事"}},{q="谁领导焚木议会？",a="该议会由莫里森镇长领导，在亡灵哨兵伏击他们之前，他与史密瑟斯、撒切尔和布伦瑞克等议员一同处理市政事务。",al={"莫里森镇长","焚木镇长","谁在管理焚木"}},{q="这场伏击发生在什么地方？",a="伏击发生在焚木村内的市政厅建筑里，该村位于银松森林南部，沿着通往影牙城堡的道路不远处。",al={"焚木村伏击地点","费雷亚在哪里","焚木市政厅"}},{q="议会与阿鲁高之间是什么关系？",a="议会充当阿鲁高的行政喉舌。当阿鲁高躲在影牙城堡内进行黑暗实验时，议会负责管理那些在夜幕降临时会变身为凶猛野兽的村民。",al={"阿鲁高的议会","议会是否为阿鲁高效力","阿鲁高控制焚木"}},{q="杀死议会能让焚木村摆脱诅咒吗？",a="不能。消灭议会只是除去了阿鲁高的人类傀儡，但这并不能解除困扰村民的狼人诅咒，这让被遗忘者不得不去争夺一个充满了充满敌意、不受控制的怪物的城镇。",al={"焚木村是否被治愈","伏击是否能治愈狼人","焚木村诅咒是否被打破"}}},fp="15,191,20.422.0,21.324.1,29.222.0,53.200.0,31.162.0,34.141.0,56.203.0,54.187.1"}
P.entries["quest:453"] = {n="搜寻乌鸦岭",s="“寻找黑影”是一项联盟任务，要求冒险者追踪一名与斯温·约根农场的悲剧有关的神秘陌生人。在夜色镇的旅店老板斯密茨提供的线索指引下，旅行者们必须前往西面的阴森树林，搜寻那名逃亡的嫌疑人。",h="“寻找黑影”是一项联盟任务，要求冒险者追踪一名与斯温·约根农场的悲剧有关的神秘陌生人。在夜色镇的旅店老板斯密茨提供的线索指引下，旅行者们必须前往西面的阴森树林，搜寻那名逃亡的嫌疑人。",kw={"夜色镇","暮色森林","寻找黑影","乌鸦岭","scarlet raven tavern","斯温·约根","旅店老板斯密茨"},ang={["class:Rogue"]="在阴影笼罩的茂密森林中追踪一个惊慌失措的嫌疑人，需要敏锐的观察力和追踪技巧，才能将传闻与真正的踪迹区分开来。",["faction:Alliance"]="揭开基特斯逃亡的真相，对于了解威胁王国南部边境的日益增长的黑暗至关重要。"},sec={{t="鬼影踪迹",b="遵照斯温·约根的请求，去查明那个从他被毁的家园中逃离的神秘人物，搜寻行动直接指向了Scarlet Raven Tavern。旅店老板斯密茨提供了一些关键观察：那个逃亡者对夜色镇来说完全是个陌生人，显得异常紧张和慌乱，他匆忙离开了镇子微弱的边缘灯火，消失在了西面的荒野中。"},{t="揭开基特斯的真面目",b="向西追踪这名陌生人进入阴影中，最终找到了基特斯本人。他正躲在暮色森林的险境中瑟瑟发抖。当拿出从荒废农场找到的日记与他对质时，基特斯因神经极度紧张而崩溃，承认那本破旧的日记确实是他所写。他远非什么处心积虑的恶棍，他透露自己只是一个被该地区爆发的恐怖事件吓坏的目击者，并暗示这本日记只记录了那场梦魇的冰山一角。"}},faq={{q="那个黑影是谁？",a="那个黑影就是基特斯，一个胆小的流浪者。他在无意中记录了斯温·约根农场周围发生的黑暗事件，随后向西逃进了树林。",al={"黑影的身份","基特斯是谁","那个陌生人是谁"}},{q="旅店老板斯密茨说那个人去了哪里？",a="斯密茨指出那名男子是个外乡人，看起来明显被吓坏了，他向西逃出了夜色镇，闯入了危险的荒野。",al={"他去了哪里","基特斯在哪里","哪条路是西边"}},{q="基特斯为什么要从斯温的农场逃跑？",a="基特斯目睹了袭击农场的恐怖惨剧，为了保命而逃走，他害怕摧毁斯温家人的东西下一个目标就是自己。",al={"基特斯为什么逃跑","斯温农场发生了什么","基特斯为什么害怕"}},{q="在斯温的农场发现的那本书是什么？",a="那是一本由基特斯撰写的日记，详细记录了农场屠杀事件发生前的诡异现象。当拿着它与基特斯对质时，他承认这只讲述了事情的一半真相。",al={"斯温农场中的书","基特斯的日记","那本日记是什么"}},{q="在哪里可以找到基特斯？",a="基特斯躲在暮色森林西部的荒野中，避开夜色镇和森林中游荡的野兽，藏身在乌鸦岭营地附近。",al={"基特斯的位置","基特斯在暮色森林的哪里","基特斯的坐标"}},{q="找到基特斯之后会发生什么？",a="一旦基特斯承认日记是他写的，他就会整理一份关于实际发生情况的完整记录，指引你带着真相回到斯温·约根那里。",al={"接下来做什么","找到基特斯之后","我接下来该去哪里"}}},fx={["033a8771"]={q="旅店老板斯密茨为何想让你寻找那个神秘人？",a="旅店老板斯密茨与斯温农场的悲剧并无私人牵连，但他知道暮色森林的荒野危机四伏。他得知一个神经紧张的陌生人离开了夜色镇的安全地带，向西逃进野兽出没的树林，真心希望那个可怜的家伙能在被这片土地上的恐怖吞噬前获救。",al={"斯密茨的动机","为何寻找神秘人","斯密茨为何在意"}}},fp="26,196,23.347.0,17.349.1,26.144.2,49.113.0,41.137.1,38.152.2,27.130.0,35.146.1"}
P.entries["quest:454"] = {n="恶战之后",s="在一次黑铁矮人的突袭打断了前往洛克莫丹南部挖掘场的爆破火药运输后，胡达尔与他的搭档米兰分摊了职责。米兰不愿独自冒险再次遭遇伏击，因此需要一位坚实的护卫来保护剩余的物资安全运达挖掘场。",h="在一次黑铁矮人的突袭打断了前往洛克莫丹南部挖掘场的爆破火药运输后，胡达尔与他的搭档米兰分摊了职责。米兰不愿独自冒险再次遭遇伏击，因此需要一位坚实的护卫来保护剩余的物资安全运达挖掘场。",kw={"伏击","爆破火药","黑铁","挖掘","胡达尔","洛克莫丹","米兰","萨恩"},ang={["faction:Alliance"]="保持洛克莫丹的补给线畅通，能确保协会的研究得以继续，并使南部隘口保持在联盟的控制之下。",["profession:Mining"]="爆破火药是深层地下挖掘的生命线，因此保护这些木桶对于任何严肃的采矿事业来说都是至关重要的。",["race:Dwarf"]="保卫铁炉堡的后勤免受阴险的黑铁矮人破坏者的干扰，直接维护了你家乡山隘和采矿作业的安全。"},sec={{t="断裂的补给线",b="在洛克莫丹的山丘间运输开矿用的炸药从来都不是件容易事，而黑铁矮人的公开敌意更是让日常劳作变成了致命的任务。在萨恩及其同伙发动的伏击之后，搬运工胡达尔和米兰的日常工作被彻底打乱了。由于木桶散落，道路凶险，两人不得不分头行动：胡达尔留下看守剩余的物资，而米兰则准备带着下一批货物继续前进。"},{t="通往挖掘场之路",b="洛克莫丹各地的挖掘场都依赖持续不断的爆破火药供应，以便破碎岩石，挖掘泰坦遗物。米兰很清楚，小路沿途的任何山脊都可能再次爆发伏击。在捆好货物之前，他希望先找到一位同行的旅伴，从而绕过黑铁矮人可能设下的任何埋伏。"}},faq={{q="胡达尔和米兰是谁？",a="胡达尔和米兰是矮人搬运工，他们的任务是将沉重的爆破火药桶运过洛克莫丹，以支援当地的挖掘工作。",al={"胡达尔是谁","米兰是谁","洛克莫丹的火药搬运工"}},{q="为什么胡达尔和米兰不能一起走？",a="在他们的路线上发生伏击后，货物变得极易受损。他们分摊了职责，这样胡达尔可以留在后面看守剩余的木桶，而米兰则负责带着第一批货物前进。",al={"为什么要分开","为什么要分开运输火药"}},{q="谁袭击了货物？",a="一群以萨恩为首的敌对黑铁矮人伏击了搬运工，试图扰乱联盟的行动，并夺取或摧毁他们的开矿炸药。",al={"谁伏击了他们","萨恩是谁"}},{q="米兰要把火药带去哪里？",a="米兰正在将木桶运往洛克莫丹的南部挖掘场，勘察员基恩萨·铁环的团队正需要这些爆破火药来清理岩石，揭开埋藏的遗迹。",al={"火药要运往哪里","米兰的目的地"}},{q="为什么洛克莫丹的爆破火药需要严加守卫？",a="爆破火药对探险者协会的挖掘工作至关重要，但如果落入不法之徒手中，它会造成巨大的危险。活跃在整个地区的黑铁矮人渗透者一直在积极寻求破坏补给，并扰乱铁炉堡对该领土的控制。",al={"为什么要保护爆破火药","火药的重要性"}},{q="和米兰交谈后会发生什么？",a="一旦米兰完成对货车和货物的最后检查，他会请你护送他沿路前行，以确保这批货物能完好无损地运抵挖掘场。",al={"伏击后的下一步","米兰做什么"}}},fp="16,166,23.237.0,19.246.0,25.119.0,43.186.0,26.145.0,33.168.0,56.232.0,36.131.0"}
P.entries["quest:4542"] = {n="给乱风岗的紧急信件",s="“致乱风岗的信件”是一项部落任务，指派旅行者将卫兵穆赫·月角在边境升降梯附近发出的紧急信件带往千针石林。这封信警告峭壁卫兵图林·长角，半人马对当地商队的袭击正在加剧。信中还对邻近的恐怖图腾氏族那令人怀疑且疏远的举止表达了初步的担忧。",h="“致乱风岗的信件”是一项部落任务，指派旅行者将卫兵穆赫·月角在边境升降梯附近发出的紧急信件带往千针石林。这封信警告峭壁卫兵图林·长角，半人马对当地商队的袭击正在加剧。信中还对邻近的恐怖图腾氏族那令人怀疑且疏远的举止表达了...",kw={"卫兵穆赫·月角","半人马","峭壁卫兵图林·长角","乱风岗","恐怖图腾","致乱风岗的信件","千针石林","紧急信件"},ang={["faction:Horde"]="乱风岗是部落在千针石林广袤区域中至关重要的生命线。保持哨站守望者与定居点领导层之间的联络畅通，对于确保沙漠贸易路线的安全至关重要。",["race:Tauren"]="对于牛头人来说，半人马世世代代都是他们不共戴天的死敌。月角的警告是一个严峻的提醒，即便与隐居的恐怖图腾氏族之间的紧张关系正在酝酿，古老的敌人依然在卡利姆多的道路上进行狩猎。"},sec={{t="峡谷中的警告",b="卫兵穆赫·月角在峡谷西侧入口处守望，监视着通往千针石林的道路。随着半人马的攻击突然升级，边境哨兵与区域指挥层之间的联络变得至关重要。月角委托路过的部落冒险者将一封紧急信件送往东南方的乱风岗，交给驻扎在台地定居点顶部的指挥官峭壁卫兵图林·长角。"},{t="日益增长的威胁与不安的同族",b="收到信件后，图林·长角证实了严峻的局势：最近一支补给商队遭到游荡的半人马拦截并屠杀，导致乱风岗急需展开报复行动并加强防御。同样令人担忧的是月角临别前的告诫：要避开当地的恐怖图腾牛头人，他们异常古怪且带有敌意的行为暗示着在这片荒凉的平原上，更深的裂痕正在酝酿。"}},faq={{q="是谁寄出了致乱风岗的信件？",a="卫兵穆赫·月角，一位在千针石林西侧入口守望的牛头人斥候，将这份紧急信件交给你去传递。",al={"任务发布者","谁开启致乱风岗的信件任务","卫兵穆赫·月角"}},{q="谁接收了这份紧急信件？",a="峭壁卫兵图林·长角在位于升降梯东南方、高耸的乱风岗台地定居点上收到了信件。",al={"任务交付地点","峭壁卫兵图林·长角位置","乱风岗领袖"}},{q="紧急信件汇报了什么内容？",a="信件向乱风岗警示，下方的道路上半人马袭击和对商队的骚扰活动突然增加。",al={"信件内容","信件主题"}},{q="为什么卫兵穆赫·月角担心恐怖图腾氏族？",a="月角指出，附近的恐怖图腾氏族成员对其他牛头人表现得古怪而疏远，建议旅行者远离他们。",al={"恐怖图腾警告","为什么要避开恐怖图腾"}},{q="图林·长角读完信后发生了什么？",a="由于对最近一支补给商队遭到屠杀感到愤怒，峭壁卫兵图林·长角立即在后续任务“安抚半人马”中下达了针对当地半人马的报复行动指令。",al={"后续任务","致乱风岗的信件之后"}},{q="如何从峡谷底部到达乱风岗？",a="沿着主峡谷道路向东走，直到到达巨大的针状台地底部，然后乘坐木质平台升降梯直接升至村庄。",al={"如何前往乱风岗","如何抵达乱风岗上方"}}},fx={["65381134"]={q="卫兵穆赫·月角为何想把消息送到乱风岗？",a="峡谷中的半人马袭击愈演愈烈，旅人、商队和哨站都面临迫在眉睫的危险。卫兵穆赫·月角驻守在升降梯，亲眼目睹暴力事件不断升级。他知道峭壁卫兵图林·长角和驻扎在乱风岗的守军需要提前获悉消息，以便组织防御并保护重要补给路线。",al={"为何把消息送到乱风岗","穆赫·月角的动机","为何警告长角"}},c67c7dfd={q="卫兵穆赫·月角为何需要冒险者送信？",a="卫兵穆赫·月角驻守在升降梯，守卫贫瘠之地与千针石林之间的重要边境。半人马劫掠愈演愈烈，邻近的蛮鬃氏族也行迹可疑。月角不能擅离哨位，否则升降梯就会失去防守，因此由一位有能力的旅人递送信件最为合适。",al={"月角为何不能送信","送信到乱风岗为何找我","月角为何需要帮助"}}},fp="24,367,25.430.0,28.406.0,39.133.0,32.131.0,36.119.0,50.154.0,46.184.0,53.150.0"}
P.entries["quest:455"] = {n="丹奥加兹告急",s="“丹奥加兹突袭”是一项紧急军事任务，要求你杀出重围，穿过连接洛克莫丹与湿地的关键山隘——丹奥加兹。龙喉氏族的兽人已经在隧道中盘踞，威胁要切断铁炉堡通往米奈希尔港的重要生命线。冒险者肩负着消灭兽人先遣队，并将入侵的消息传达给瓦斯塔格·铁腭的任务。",h="“丹奥加兹突袭”是一项紧急军事任务，要求你杀出重围，穿过连接洛克莫丹与湿地的关键山隘——丹奥加兹。龙喉氏族的兽人已经在隧道中盘踞，威胁要切断铁炉堡通往米奈希尔港的重要生命线。冒险者肩负着消灭兽人先遣队，并将入侵的消息传达...",kw={"龙喉","丹奥加兹","洛克莫丹","米奈希尔港","山口","罗克加","瓦斯塔格·铁腭","湿地"},ang={["faction:Alliance"]="米奈希尔港是联盟在东部王国与西部大陆之间的主要门户；保持这条陆路畅通对于整个阵营至关重要。",["race:Dwarf"]="扫清丹奥加兹可以保护卡兹莫丹的祖传山隘，并维护铁炉堡与其西海港口之间的关键通道。"},sec={{t="被切断的动脉",b="丹奥加兹是唯一一条横穿洛克莫丹与湿地沼泽盆地之间峭壁的陆路山隘。对于铁炉堡的矮人来说，这条石质通道对于通往联盟在该地区的主要沿海港口——米奈希尔港的贸易、部队调动和补给运输至关重要。如果山口失守，铁炉堡通往西海的联系实际上将被扼杀，导致孤立的前哨站无法得到矮人的增援。"},{t="龙喉的突袭",b="虽然第二次战争后，龙喉氏族的残党长期盘踞在湿地的丘陵与废墟之中，但他们突然有组织地向丹奥加兹推进，标志着局势的严重升级。龙喉的斥候和步兵不再仅仅滞留于沼泽地中的据点，而是占领了隧道并加固了山口。巡山人罗克加征召勇敢的联盟旅行者击碎这一封锁，消灭入侵的兽人，并将袭击的消息直接带给位于米奈希尔港的瓦斯塔格·铁腭。"}},faq={{q="为什么丹奥加兹对联盟如此重要？",a="丹奥加兹是连接洛克莫丹与湿地的唯一一条直接山路。它将卡兹莫丹的心脏地带与米奈希尔港连接起来，而米奈希尔港是促进跨海海军运输的主要联盟港口。",al={"丹奥加兹的重要性","丹奥加兹为何重要","为何要扫清山口"}},{q="占据山口的龙喉兽人是谁？",a="龙喉氏族是旧部落的残党，以在第二次战争中奴役红龙而臭名昭著。在战败后，四散的派系撤退到了湿地，现在他们向南推进到山口，试图夺取战略要冲。",al={"龙喉氏族是谁","兽人为何出现在丹奥加兹","龙喉氏族背景"}},{q="这项任务指向何处？",a="一旦你杀出山口并消灭了驻守的步兵和斥候，道路将向北穿过湿地，并在岔路口向西转向米奈希尔港，你将在那里向瓦斯塔格·铁腭汇报。",al={"丹奥加兹突袭后去哪","谁接收报告","瓦斯塔格·铁腭在哪里"}},{q="为什么瓦斯塔格·铁腭会对这份报告感到惊讶？",a="龙喉氏族通常隐藏在湿地沼泽丘陵的营地中。他们大胆地突袭丹奥加兹的矮人隧道，代表了他们向有组织侵略行为的一种出人意料且令人警觉的转变。",al={"瓦斯塔格的反应","兽人为何袭击丹奥加兹"}},{q="是谁下令进攻山口？",a="驻扎在洛克莫丹北部的矮人卫兵巡山人罗克加下令发起攻击，以防止兽人巩固据点并切断与海岸的通讯。",al={"谁发布任务","巡山人罗克加的任务"}},{q="完成这次突袭之后会发生什么？",a="将报告送达给瓦斯塔格·铁腭可以提醒米奈希尔港的驻军注意这一迫在眉睫的威胁，从而开启进一步协助矮人防御湿地龙喉氏族的机会。",al={"丹奥加兹突袭后的后续任务","在米奈希尔港要做什么"}}},fp="18,235,16.400.0,19.354.0,46.175.0,46.245.0,29.192.0,47.187.0,35.189.0,42.182.0"}
P.entries["quest:456"] = {n="自然的平衡",s="《自然之道》是暗夜精灵在幽影谷觉醒后接到的引导任务。由管理员伊尔萨莱恩委派，任务要求年轻的冒险者去捕杀过度繁衍的幼年夜刃豹和蓟熊怪。这项任务向新英雄介绍了卡多雷保护泰达希尔自然和谐的古老职责。",h="《自然之道》是暗夜精灵在幽影谷觉醒后接到的引导任务。由管理员伊尔萨莱恩委派，任务要求年轻的冒险者去捕杀过度繁衍的幼年夜刃豹和蓟熊怪。这项任务向新英雄介绍了卡多雷保护泰达希尔自然和谐的古老职责。",kw={"奥达希尔","自然之道","ilthalaine","卡多雷","夜刃豹","幽影谷","泰达希尔","蓟熊怪"},ang={["class:Druid"]="对于初出茅庐的德鲁伊来说，这次捕杀是Cenarion式管理严酷现实的第一课：保护荒野有时需要通过流血来拯救整体。",["class:Hunter"]="学习追踪并捕杀具有攻击性的野生动物，是每一位猎人与卡利姆多野兽建立联系的基础。",["race:NightElf"]="这项任务标志着你作为卡多雷成年保护者旅程的第一步，让你明白自然的平衡需要积极的干预和尊重。"},sec={{t="微妙的和谐",b="泰达希尔看似狂野而古老，但其生态系统却十分年轻且脆弱。在幽影谷，受世界之树那广阔枝叶的庇护，春季的连绵大雨扰乱了森林微妙的循环。某些野生动物的数量繁衍超出了土地的承载能力，威胁到要耗尽山谷的资源，并导致整个生态系统陷入饥荒。保护森林需要积极的管理。"},{t="管理员的召唤",b="管理员伊尔萨莱恩看守着幽影谷的丛林，确保没有任何一种元素压倒另一种。为了防止动物大规模饿死，他派遣年轻的暗夜精灵进入树林，以削减蓟熊怪和掠食性的夜刃豹的数量。这是一项虽然不起眼但至关重要的责任，确立了卡多雷文化的核心哲学：与自然和谐相处需要积极的平衡和艰难的抉择。"}},faq={{q="为什么要杀死夜刃豹和蓟熊怪？",a="春季的大雨导致幼年夜刃豹和蓟熊怪的数量激增。幽影谷的资源有限，无法承载过多的野生动物，过度繁衍的兽群有耗尽食物的风险，这不仅会威胁它们自身，也会导致其他生物陷入饥饿。",al={"为什么要杀蓟熊怪","为什么要杀夜刃豹","自然之道的理由"}},{q="谁是管理员伊尔萨莱恩？",a="管理员伊尔萨莱恩是驻扎在幽影谷的一名卡多雷守护者。他宣誓的职责是监视山谷的野生动物和植被，以确保自然的和谐不被破坏。",al={"谁是伊尔萨莱恩","任务发布者","管理员伊尔萨莱恩背景"}},{q="这个任务发生在什么地方？",a="该任务发生在幽影谷，这是一个位于泰达希尔枝干内的隐蔽森林飞地，泰达希尔是卡利姆多北海岸外的一棵世界之树。",al={"任务地点","幽影谷在哪里","暗夜精灵新手区"}},{q="完成这项任务后接下来要做什么？",a="伊尔萨莱恩会委派你执行第二阶段的捕杀任务，同时会交给你一枚职业徽记，指引你前往奥达希尔寻找你的第一位导师。",al={"后续任务","系列任务的下一步"}}},fp="21,237,18.333.0,22.382.0,51.228.0,30.173.0,33.146.0,43.181.0"}
P.entries["quest:457"] = {n="自然的平衡",s="这项任务是管理员伊尔萨莱恩为了保护幽影谷脆弱的生态环境所做的持续努力，通过猎杀成熟的蓟熊怪和疥癣的夜刃豹来维持平衡。随着泰达希尔的野生生物无节制地繁衍，暗夜精灵守护者必须出手干预，防止这些捕食者和觅食者过度繁殖，从而啃光树枝上的植被。",h="这项任务是管理员伊尔萨莱恩为了保护幽影谷脆弱的生态环境所做的持续努力，通过猎杀成熟的蓟熊怪和疥癣的夜刃豹来维持平衡。随着泰达希尔的野生生物无节制地繁衍，暗夜精灵守护者必须出手干预，防止这些捕食者和觅食者过度繁殖，从而啃光...",kw={"奥达希尔","自然平衡","猎杀","ilthalaine","疥癣的夜刃豹","幽影谷","泰达希尔","蓟熊怪"},ang={["class:Druid"]="德鲁伊教义强调和谐而非多愁善感；削减数量过多的种群可以保护伟大的生命之网。",["class:Hunter"]="击败迅捷的夜刃豹和顽固的蓟熊怪可以教授追踪和猎杀技能，这对于控制自然至关重要。",["race:NightElf"]="对于年轻的暗夜精灵来说，这项任务代表了他们在泰达希尔进行荒野管理时所面临的残酷现实的最早一课。"},sec={{t="管理的重担",b="虽然猎杀幼崽有助于稳定未来的种群增长，但幽影谷成年种群也对世界之树的生态系统构成了直接威胁。管理员伊尔萨莱恩指引年轻的守卫深入森林，猎杀成熟的蓟熊怪和年长、疥癣的夜刃豹，以防它们贪婪的食欲耗尽这片土地有限的植被和猎物。"},{t="捕食者与猎物",b="在奥达希尔以北，森林的环境发生了变化，幼崽让位给了花斑夜刃豹和那些在土壤中掘食的凶猛蓟熊怪。尽管猎杀野生生物是一项残酷的职责，但卡多雷的教义认为，有节制的狩猎是保护整个森林免于生态崩溃的必要责任。"}},faq={{q="管理员伊尔萨莱恩为什么要猎杀这些野兽？",a="如果不进行干预，蓟熊怪和夜刃豹的数量激增将耗尽幽影谷的重要资源，使这片土地变得贫瘠，无法维持泰达希尔枝叶上的任何生命。",al={"为什么要杀熊怪和夜刃豹","为什么要有自然平衡","狩猎的原因"}},{q="疥癣的夜刃豹和蓟熊怪在哪里？",a="它们游荡在幽影谷的北半部，越过奥达希尔的枝干。寻找那些身上有斑点的夜刃豹，而不是在圣所附近发现的那些条纹皮毛的幼崽。",al={"疥癣的夜刃豹在哪里","蓟熊怪的位置","到哪里找到它们"}},{q="管理员伊尔萨莱恩是谁？",a="管理员伊尔萨莱恩是幽影谷的看护者，负责监管泰达希尔起始林地的健康状况，并引导新觉醒的暗夜精灵维护森林的平衡。",al={"伊尔萨莱恩是谁","管理员伊尔萨莱恩的背景故事"}},{q="这符合暗夜精灵关于自然的信仰吗？",a="暗夜精灵崇敬自然，但管理工作需要控制过度生长。任由一个物种过度繁殖并饿死其他物种会损害整个森林，因此猎杀虽然令人悲伤，却是一项重要的职责。",al={"暗夜精灵的自然信仰","为什么德鲁伊要杀动物","卡多雷的平衡"}},{q="这是“自然平衡”任务线的终点吗？",a="这是初始“自然平衡”任务线的第二步，也是最后一步，尽管很快会有其他任务来解决困扰泰达希尔野生生物的更深层、更不自然的腐蚀问题。",al={"自然平衡任务会继续吗","自然平衡之后是什么"}},{q="为什么这些夜刃豹被描述为“疥癣的”？",a="它们是游荡在林地边缘、更年长、更粗野的捕食者。它们庞大的数量超出了幽影谷食物供应的极限，导致许多夜刃豹变得邋遢且好斗。",al={"为什么是疥癣的","夜刃豹出了什么问题"}}},fp="21,157,23.258.0,17.210.0,57.194.0,58.184.0,30.171.0,54.193.0,47.170.0,43.139.0"}
P.entries["quest:458"] = {n="森林守护者",s="“林地守护者”是幽影谷的一项入门任务，由德鲁伊麦利萨尔·鹿盔发布。在森林之灵低语的警示下，麦利萨尔让你去寻找塔琳德拉。这位难以捉摸的树妖出人意料地回到了林地。她的出现暗示着泰达希尔的树冠下正有什么令人不安的事情在酝酿。",h="“林地守护者”是幽影谷的一项入门任务，由德鲁伊麦利萨尔·鹿盔发布。在森林之灵低语的警示下，麦利萨尔让你去寻找塔琳德拉。这位难以捉摸的树妖出人意料地回到了林地。她的出现暗示着泰达希尔的树冠下正有什么令人不安的事情在酝酿。",kw={"奥达希尔","树妖","麦利萨尔·鹿盔","幽影谷","塔琳德拉","泰达希尔","林地守护者"},ang={["class:Druid"]="德鲁伊将树妖视为自然界的同胞并予以高度尊重；响应塔琳德拉的出现是留意翡翠梦境和林地平衡的早期召唤。",["race:NightElf"]="对于从奥达希尔走出的年轻暗夜精灵来说，遇见塞纳留斯的女儿是他们维护这棵新生世界之树和谐的第一次直接职责。"},sec={{t="林中的低语",b="在奥达希尔的枝叶下训练新手时，麦利萨尔·鹿盔从林地之灵那里接收到了令人不安的预兆。树妖塔琳德拉，作为自然的守护者，在离开卡利姆多的林地多年后，又在幽影谷重新现身。由于树妖很少无故出现，麦利萨尔担心自然秩序出现了失衡。"},{t="寻找树妖",b="在哨兵侦察报告的指引下，刚觉醒的保卫者们冒险前往奥达希尔西南方向的周边树林。找到塔琳德拉后，证实了麦利萨尔的直觉是准确的：塞纳留斯之女确实是回来处理影响兽穴及周边林地的入侵腐蚀的。"}},faq={{q="谁发布了这个任务？",a="麦利萨尔·鹿盔，一位驻扎在幽影谷奥达希尔下层平台的暗夜精灵德鲁伊，向刚觉醒的冒险者提供此任务。",al={"任务发布者","谁发布任务","麦利萨尔任务"}},{q="我在哪里能找到塔琳德拉？",a="塔琳德拉位于奥达希尔西南方向的森林中，站在幽影谷的林间小路上。",al={"塔琳德拉位置","塔琳德拉在哪里","寻找树妖"}},{q="塔琳德拉是谁？",a="塔琳德拉是一位树妖，也是塞纳留斯的永恒之女之一。作为林地守护者，树妖与森林的健康息息相关，除非自然面临重大威胁，否则她们很少直接干预。",al={"塔琳德拉是谁","塔琳德拉背景","幽影谷树妖"}},{q="为什么麦利萨尔对她的回归感到担忧？",a="多年来，在卡利姆多的森林中已经感受不到塔琳德拉的气息了。她突然出现在新生的泰达希尔枝叶中，暗示着这片林地可能出了问题。",al={"麦利萨尔为何担心","麦利萨尔·鹿盔担忧"}},{q="找到塔琳德拉之后会发生什么？",a="与塔琳德拉交谈将完成此任务，并随即引出她请求援助的后续任务，让你去调查在幽影谷蔓延的腐蚀动植物。",al={"下一个任务","下一步","塔琳德拉后续"}},{q="麦利萨尔·鹿盔和大德鲁伊范达尔·鹿盔有亲属关系吗？",a="麦利萨尔与居住在达纳苏斯的暗夜精灵德鲁伊领袖大德鲁伊范达尔·鹿盔共享“鹿盔”这一姓氏，但目前尚无证据表明他们有亲属关系；麦利萨尔的主要职责是在幽影谷教导新手。",al={"麦利萨尔与范达尔的关系","麦利萨尔·鹿盔有亲属关系吗"}}},fp="22,204,20.349.0,17.273.1,22.126.0,29.91.0,19.218.0,43.173.0,39.161.0,59.198.0"}
P.entries["quest:4581"] = {n="凯尼斯·静风",s="这个任务要求一名联盟信使从阿斯特兰纳出发，向东前往古老的哨站林歌神殿。旅行者们带着哨兵辛德瑞尔·速火的侦察公文，去寻找德鲁伊凯奈斯·逐风，协助他监测腐蚀在古老森林中的蔓延情况。",h="这个任务要求一名联盟信使从阿斯特兰纳出发，向东前往古老的哨站林歌神殿。旅行者们带着哨兵辛德瑞尔·速火的侦察公文，去寻找德鲁伊凯奈斯·逐风，协助他监测腐蚀在古老森林中的蔓延情况。",kw={"灰谷","阿斯特兰纳","腐蚀","德鲁伊","林歌神殿","凯奈斯·逐风","夜歌森林","辛德瑞尔·速火"},ang={["class:Druid"]="对于德鲁伊而言，协助凯奈斯·逐风是一项根本性的使命，直接支持着塞纳里奥议会为治愈灰谷蔓延的恶魔和元素枯萎而进行的持续斗争。",["faction:Alliance"]="穿行于灰谷中部至东部的夜歌森林对于建立稳定的通信及防御野外威胁和部落入侵至关重要。",["race:NightElf"]="哨兵和卡多雷旅者有责任保持阿斯特兰纳等关键堡垒与林歌神殿等遥远据点之间的通讯畅通。"},sec={{t="发往东方的急件",b="在阿斯特兰纳镇，哨兵辛德瑞尔·速火守护着森林的西部。她收到了来自德鲁伊凯奈斯·逐风的消息，他驻扎在灰谷东部边缘附近的林歌神殿。凯奈斯对海岸和林地间出现的野生动物异常行为以及邪恶征兆深感忧虑，因此请求对该地区的安全性进行正式评估。速火将她的观察结果写成了一封密封的信件，并委托一名身强力壮的旅行者将这封急件安全地送过危险的中心森林。"},{t="林歌神殿的守望者",b="前往林歌神殿需要穿过夜歌森林的荒野，这片区域受到入侵的萨特、敌对的野生动物以及南方部落军队的威胁。在林歌神殿，凯奈斯·逐风研究着灰谷自然灵魂的微妙平衡。阅读了速火的侦察报告后，他证实了自己严峻的猜想：森林中蔓延的污秽影响并非孤立或短暂的，德鲁伊们需要进一步的援助来对抗正在扎根的邪恶。"}},faq={{q="凯奈斯·逐风在哪里？",a="凯奈斯·逐风位于林歌神殿，这是一个宁静的暗夜精灵庇护所，坐落在灰谷最东端的夜歌森林中，在大路以北。",al={"凯奈斯在哪里","凯奈斯·逐风位置","寻找凯奈斯·逐风"}},{q="谁发布这个任务？",a="这个任务由哨兵辛德瑞尔·速火发布，她驻扎在灰谷西部的暗夜精灵定居点阿斯特兰纳。",al={"任务发布者","谁开启凯奈斯·逐风任务","我在哪里开始"}},{q="辛德瑞尔的便笺里写了什么？",a="这封便笺包含一份详细的安全报告，记述了灰谷西海岸及阿斯特兰纳林地周围发生的事件，旨在帮助凯奈斯·逐风调查森林中不自然的腐蚀。",al={"辛德瑞尔的便笺内容","辛德瑞尔写了什么","辛德瑞尔的便笺"}},{q="为什么凯奈斯·逐风要调查这片森林？",a="作为一名德鲁伊，凯奈斯致力于维护自然平衡。他担心一种黑暗且无处不在的邪恶正在灰谷蔓延，因此需要哨兵的实地报告来追踪其扎根的位置。",al={"为什么凯奈斯关心这件事","凯奈斯·逐风动机","德鲁伊腐蚀"}},{q="林歌神殿对联盟旅行者来说安全吗？",a="林歌神殿本身是一个和平的联盟避难所，有友好的哨兵和德鲁伊。然而，周围的夜歌森林里充满了敌对的野兽和被腐蚀的萨特，使得前往那里的道路危机四伏。",al={"林歌神殿安全吗","林歌神殿联盟城镇","林歌神殿守卫"}},{q="送信之后会发生什么？",a="在审阅了速火的报告后，凯奈斯·逐风会着手调查森林腐蚀的具体性质，并招募旅行者直接对威胁该地区的枯萎力量采取行动。",al={"what comes next","后续任务","凯奈斯后续"}}},fp="17,202,22.415.0,23.447.0,35.128.0,21.101.0,28.184.0,50.212.0,43.185.0,39.161.0"}
P.entries["quest:459"] = {n="森林守护者",s="塔琳德拉，一位守护幽影谷的树妖，试图找出当地生物突然变得富有攻击性以及附近的熊怪失踪背后的原因。通过调查野生的劣魔并收集被腐蚀的魔苔样本，冒险者们证实了黑暗魔法已经开始在世界之树的根部滋生。",h="塔琳德拉，一位守护幽影谷的树妖，试图找出当地生物突然变得富有攻击性以及附近的熊怪失踪背后的原因。通过调查野生的劣魔并收集被腐蚀的魔苔样本，冒险者们证实了黑暗魔法已经开始在世界之树的根部滋生。",kw={"阿斯瑞达斯·熊皮","魔苔","树皮部落","劣魔","劣魔眷属","幽影谷","塔琳德拉","泰达希尔"},ang={["class:Druid"]="德鲁伊与森林的灵魂和树妖有着神圣的纽带；调查被污染的魔苔对于诊断困扰世界之树的灵性疾病至关重要。",["race:NightElf"]="对于从奥达希尔出发的年轻卡多雷来说，这项任务是一个早期的、令人震惊的发现，让他们意识到他们神圣的新家园很容易受到来自内部的腐化。"},sec={{t="林间的枯萎",b="即使在幽影谷那与世隔绝的高地上，泰达希尔宁静的自然环境也开始出现裂痕。像塔琳德拉这样的树妖已经注意到森林中正弥漫着一股黑暗的变异。曾经温顺的熊怪放弃了他们世代居住的巢穴，重新集结成了富有攻击性的树皮部落，而狂野的劣魔和劣魔眷属开始横行在林间小径上。"},{t="污秽的生长",b="塔琳德拉怀疑是不自然的腐化助长了森林的敌意。通过击杀成群的劣魔并收集魔苔样本，你提供了不可辩驳的证据，证明黑暗的附魔正附着在泰达希尔的枝干上。随着这一残酷真相的确认，塔琳德拉指引年轻的保卫者前往多兰纳尔村，与德鲁伊阿斯瑞达斯·熊皮商议。"}},faq={{q="塔琳德拉是谁？",a="塔琳德拉是一位驻扎在幽影谷荒野中的树妖守望者。作为塞纳留斯的女儿，她致力于保护林间的动植物，并在腐化威胁到平衡时向暗夜精灵守护者发出警报。",al={"塔琳德拉","谁是任务发放人","幽影谷树妖"}},{q="什么是魔苔？",a="魔苔是一种注入了黑暗魔法的污秽生长物，它已经开始附着在幽影谷的野生动物身上。它的出现激怒并扭曲了像劣魔这样的生物，驱使它们陷入不自然的疯狂。",al={"魔苔","什么是魔苔","魔苔腐化"}},{q="幽影谷的熊怪发生了什么事？",a="曾经平静地生活在林谷中的熊怪已经放弃了他们传统的居所。由于受到泰达希尔蔓延的阴险腐朽影响，他们已经在充满敌意的树皮部落旗帜下集结在一起。",al={"熊怪之谜","树皮部落","熊怪去了哪里"}},{q="这项调查接下来会引向何处？",a="在证实魔苔已经在幽影谷扎根后，塔琳德拉指引旅行者深入泰达希尔，前往多兰纳尔定居点。在那里，德鲁伊阿斯瑞达斯·熊皮正在调查这种腐化在世界之树上的更广泛蔓延。",al={"后续任务","之后去哪里","阿斯瑞达斯·熊皮"}},{q="什么是劣魔和劣魔眷属？",a="劣魔和它们的眷属是泰达希尔枝干上原生的顽皮、矮小的林间精灵。它们通常是难以管教的害虫，但在接触到像魔苔这样具有腐化作用的影响时，会变得极具攻击性。",al={"劣魔","劣魔眷属","什么是劣魔"}},{q="为什么泰达希尔会出现腐化？",a="虽然泰达希尔的种植是为了恢复暗夜精灵失去的永生并为他们提供一个新的避难所，但黑暗能量已经开始渗入其枝干和野生动物之中，这让负责守卫它的德鲁伊和森林之魂感到困扰。",al={"为什么泰达希尔被腐化","幽影谷腐化"}}},fp="22,200,21.259.0,14.299.0,19.187.0,17.167.0,44.94.0,40.119.0,29.197.0,40.205.0"}
P.entries["quest:46"] = {n="悬赏鱼人",s="暴风城军队已对在艾尔文森林东部蔓延的鱼人部族发布了悬赏令。由于驻军兵力吃紧，卫兵托马斯只能依靠过往的冒险者来清理石碑湖周围及南部水道沿岸的营地，以防这些怪物淹没该地区的农场和道路。",h="暴风城军队已对在艾尔文森林东部蔓延的鱼人部族发布了悬赏令。由于驻军兵力吃紧，卫兵托马斯只能依靠过往的冒险者来清理石碑湖周围及南部水道沿岸的营地，以防这些怪物淹没该地区的农场和道路。",kw={"悬赏","艾尔文","鱼鳍","觅食者","卫兵托马斯","潜伏者","治安官杜汉","鱼人","石碑湖"},ang={["class:Hunter"]="石碑湖周围沼泽般的岸边和长满芦苇的河岸，是追踪这些敏捷且具有群体意识的水生掠食者的理想练兵场。",["faction:Alliance"]="清理水道可以保障闪金镇与赤脊山边界之间重要的补给线和乡村家园的安全。",["race:Human"]="对于暴风城的公民来说，这份契约是一个鲜明的提醒，让他们意识到在首都腹地之外，王国的保护力量已变得多么薄弱。"},sec={{t="水道上的威胁",b="虽然艾尔文森林的西部道路相对安全，但东部的水域却滋生了日益严重的鱼人威胁。鱼人潜伏者和觅食者已经在石碑湖周围和南部溪流的分叉处建立了具有攻击性的沿岸定居点。起初看似微不足道的小麻烦，如今已迅速演变成领地扩张，全副武装的鱼人开始袭击过往的旅客并侵扰人类定居点。"},{t="防线吃紧",b="卫兵托马斯驻扎在通往赤脊山的东部大桥上，发现自己正处于外部威胁与当地骚乱的夹缝之中。随着瓦里安·乌瑞恩国王失踪，暴风城的军事指挥陷入了官僚主义的瘫痪，城镇驻军很难得到他们请求的增援。治安官杜汉和当地官员已转而求助于官方悬赏，用硬币换取被割下的鱼鳍，以遏制这一水生种族的威胁。"}},faq={{q="为什么艾尔文森林会有针对鱼人的悬赏？",a="鱼人在石碑湖和艾尔文森林东部的南部溪流建立了不断扩大的营地。它们的觅食小队威胁到了附近的农场、道路和旅客，迫使暴风城军队花钱雇佣冒险者来削减它们的数量。",al={"为什么要杀鱼人","鱼人悬赏原因","为什么会有鱼人悬赏"}},{q="谁在支付这笔悬赏？",a="悬赏由暴风城军队通过治安官杜汉指挥下的闪金镇拨付，卫兵托马斯作为前线联络人，负责向驻扎在东部河道交叉口的冒险者支付报酬。",al={"谁提供这个任务的奖励","谁支付悬赏","暴风城军队悬赏"}},{q="鱼人的定居点位于何处？",a="主要的群落分布在北部的石碑湖沿岸和岛屿上，以及南部东侧溪流分叉处的河岸边。",al={"艾尔文森林鱼人位置","艾尔文鱼人在哪里","石碑湖鱼人"}},{q="为什么暴风城的卫兵不能自己处理这件事？",a="由于政治动荡、领导层失踪以及强盗横行，暴风城的军事力量在整个王国范围内严重不足。像卫兵托马斯驻守的桥梁这样的哨所只有寥寥数人，他们无法对沿岸的鱼人部落发起持续的进攻。",al={"为什么卫兵托马斯需要帮助","为什么卫兵不亲自去打鱼人","艾尔文卫兵人手不足"}},{q="卫兵托马斯需要什么样的证明来证明清理工作？",a="卫兵托马斯要求上交直接从栖息在艾尔文东部水道的鱼人潜伏者和觅食者身上获取的破碎的鱼鳍。",al={"什么掉落破碎的鱼鳍","任务证明","鱼鳍"}},{q="治安官杜汉知道鱼人问题的严重性吗？",a="是的。卫兵托马斯提到，治安官杜汉对整个艾尔文森林东部的鱼人局势非常焦虑，因此关于清理营地的正面报告对提振当地士气至关重要。",al={"治安官杜汉鱼人","闪金镇知情吗","杜汉的反应"}}},fp="17,269,25.280.0,18.432.0,43.222.0,29.169.0,41.147.0,54.228.0,49.98.0,66.144.0"}
P.entries["quest:460"] = {n="支离破碎",s="“碎裂之躯”任务始于一位冒险者发现了阿拉里克的头颅。这是一颗还能活动的断头，属于芬里斯岛上亡灵法师瑟尔·鸦爪的一位前仆从。阿拉里克恳求冒险者将他带过芬里斯城堡，送到马厩附近的一个无名墓穴，他的其余遗骸就被埋在那里。",h="“碎裂之躯”任务始于一位冒险者发现了阿拉里克的头颅。这是一颗还能活动的断头，属于芬里斯岛上亡灵法师瑟尔·鸦爪的一位前仆从。阿拉里克恳求冒险者将他带过芬里斯城堡，送到马厩附近的一个无名墓穴，他的其余遗骸就被埋在那里。",kw={"阿拉里克","芬里斯岛","芬里斯城堡","腐皮","浅坑","银松森林","会说话的头颅","瑟尔·鸦爪"},ang={["class:Mage"]="瑟尔扭曲的结界——将防御性的防护法术异化为无法逃脱的断肢亡灵诅咒——是一个严峻的警示，昭示着当奥术魔法被死灵法术扭曲时会带来怎样的后果。",["race:Undead"]="被遗忘者勇士们会认出瑟尔·鸦爪那背信弃义的施法手段，这是天灾军团的巫师们在洛丹伦各地施加残酷暴行的典型表现。"},sec={{t="被背叛的保镖",b="在遭遇惨剧之前，阿拉里克曾是瑟尔·鸦爪的首席仆从兼私人保镖。瑟尔·鸦爪是一位强大的天灾军团法师，盘踞在银松森林的芬里斯城堡。当亡灵瘟疫席卷该地区时，瑟尔声称他会用奥术魔法保护阿拉里克，使其免受瘟疫之苦。然而，这个扭曲的结界反而将阿拉里克困在了一种永久而痛苦的亡灵状态中，让他被砍下的躯体依然保持着完全的意识。"},{t="腐皮豺狼人的玩物",b="通过将当地的狼群感染死灵腐烂，瑟尔一手造就了腐皮豺狼人，随后他又向自己的保镖下了毒手。这位亡灵法师斩下了阿拉里克的头颅，并将这颗依然活着、还能说话的头扔给残暴的豺狼人当作消遣。腐皮豺狼人将他的躯体拖到了城堡马厩外一个匆忙挖掘的浅坑中，并把他的头当作一个恐怖的玩具，直到一名外来者介入。"},{t="残躯重聚",b="抵达马厩附近那个匆忙挖掘的土坑，阿拉里克的头颅便能与他无头的躯干重聚。尽管他依然被瑟尔施加的亡灵诅咒所束缚，但肢体得以复原还是让阿拉里克获得了一丝苦涩的慰藉。"}},faq={{q="阿拉里克是谁？",a="阿拉里克曾是芬里斯城堡中瑟尔·鸦爪的首席仆从兼私人保镖。瑟尔以保护他免受亡灵瘟疫侵害为幌子，对他施下了一道邪恶的咒语，这反而将他困入了永恒的亡灵状态。",al={"阿拉里克","会说话的头颅是谁","银松森林会说话的头颅"}},{q="阿拉里克为什么会被斩首？",a="瑟尔·鸦爪在完成创造腐皮豺狼人的实验后不久就斩下了阿拉里克的头。随后，这位亡灵法师将阿拉里克断裂但仍有意识的头颅扔给了豺狼人当作玩物。",al={"阿拉里克为什么只剩一颗头","谁砍下了阿拉里克的头"}},{q="阿拉里克的墓在哪里？",a="他的躯体埋在芬里斯岛芬里斯城堡庭院内一个匆忙挖掘的无名浅坑中，靠近马厩建筑。",al={"阿拉里克的躯体在哪里","浅坑位置","芬里斯的墓穴在哪里"}},{q="什么是腐皮豺狼人？",a="腐皮豺狼人是芬里斯岛当地的豺狼人种群，因瑟尔·鸦爪的死灵实验而变成了腐烂且带有亡灵气息的恐怖生物。",al={"腐皮","腐皮豺狼人","芬里斯岛豺狼人"}},{q="瑟尔·鸦爪是谁？",a="瑟尔·鸦爪是一位人类巫师兼天灾军团亡灵法师，他占据了位于洛丹米尔湖中的芬里斯城堡，并将其用作腐化豺狼人和传播天灾军团影响力的实验室。",al={"瑟尔","瑟尔·鸦爪"}},{q="找到墓穴后会发生什么？",a="当阿拉里克与他的遗骸重聚后，他会协助你找到一个藏有强力法杖的壁龛，随后你可以将其带回幽暗城，交给达拉然的法师比索·埃斯沙德。",al={"碎裂之躯后续","碎裂之躯下一步"}}},fp="17,193,20.382.0,26.370.0,20.249.1,14.198.0,24.167.0,32.131.0,29.159.0,23.198.0,38.167.1"}
P.entries["quest:461"] = {n="密室",s="在芬里斯城堡外的一座浅坟中发现奥拉瑞克的遗骸（他很健谈）后，冒险者们被指引回到堡垒内部。在这一逝去人类记忆的引导下，旅行者们寻找一处隐藏在尘封书架后的被遗忘壁龛，以让他在此安息并取回一件古老的遗物。",h="在芬里斯城堡外的一座浅坟中发现奥拉瑞克的遗骸（他很健谈）后，冒险者们被指引回到堡垒内部。在这一逝去人类记忆的引导下，旅行者们寻找一处隐藏在尘封书架后的被遗忘壁龛，以让他在此安息并取回一件古老的遗物。",kw={"奥拉瑞克","尘封书架","芬里斯城堡","隐藏壁龛","腐皮豺狼人","银松森林","图勒·鸦爪"},ang={["class:Mage"]="这个隐藏的壁龛保存着芬里斯城堡的奥术遗产，掩藏着与图勒·鸦爪这类前达拉然法师直接相关的神器。",["faction:Horde"]="从芬里斯城堡的核心地带取回遗物，削弱了图勒在芬里斯岛上的立足点，并协助了被遗忘者巩固银松森林的战役。",["race:Undead"]="对于被遗忘者而言，与不安、能说话的骸骨打交道已是家常便饭，但奥拉瑞克渴望在人类废墟中安息的心愿，却深刻地提醒着他们所继承的这片土地的过往。"},sec={{t="不安的请求",b="即使死后，奥拉瑞克依然保留着芬里斯城堡鼎盛时期的鲜活记忆。部落斥候将他从那座简陋、草率的泥土坟墓中挖出，这让他感到解脱。他的骸骨拒绝仅仅被带往瑟伯切尔。相反，他用重要情报作为交换：城堡西南塔楼内有一处隐藏的壁龛，里面存放着一件图勒·鸦爪和他的法师同僚们珍视的物品。"},{t="埋入墙中",b="避开盘踞在岛屿堡垒上的腐皮豺狼人，旅行者们带着奥拉瑞克的遗骸穿过石质长廊。在他所说的秘密隔间位于高层，隐藏在一个布满灰尘的书架后面。打开之后，奥拉瑞克唯一的请求就是将他封存在城堡古老的砖石之中，他希望能在自己度过一生中最快乐时光的墙壁里获得安宁，远离豺狼人啃噬的利齿。"}},faq={{q="奥拉瑞克是谁？",a="奥拉瑞克曾是芬里斯城堡中图勒·鸦爪的首席仆从和保镖，在腐皮豺狼人被创造出来后，他被图勒斩首。他的遗骸在堡垒外的一座浅坟中被发现，其活跃的灵魂在指引部落冒险者，以换取在他钟爱的堡垒内获得妥善安葬的机会。",al={"奥拉瑞克背景故事","奥拉瑞克是谁","这是谁的骸骨"}},{q="隐藏的壁龛位于何处？",a="隐藏的壁龛位于芬里斯城堡西南方向的塔楼内，隐蔽在上层一个不起眼的尘封书架后。",al={"尘封书架在哪里","壁龛在哪里","隐藏壁龛位置"}},{q="壁龛里藏着什么物品？",a="在这个隐蔽的壁龛里放置着一根古老的魔杖，那是图勒·鸦爪和他在达拉然的前同僚们曾经珍视的物品，此外还有奥拉瑞克留给帮助过他的人的其他遗物。",al={"壁龛里有什么","芬里斯城堡宝藏","图勒的物品"}},{q="为什么奥拉瑞克想留在芬里斯城堡内？",a="奥拉瑞克认为他在芬里斯城堡居住的时光是他一生中最美好的日子。将他的遗骸封存在砖石中能带给他安宁，并让他免受在庭院中游荡的食腐豺狼人的骚扰。",al={"为什么要把奥拉瑞克留在芬里斯","奥拉瑞克的安息地"}},{q="找到书架后会发生什么？",a="将奥拉瑞克封入壁龛并取回魔杖后，冒险者们会接到指示回到幽暗城，将遗物交给比索·埃斯沙德。",al={"隐藏壁龛后的任务","我该如何处理这根魔杖"}},{q="为什么奥拉瑞克让你把他的靴子留下？",a="当他的骸骨从浅坟中被挖出时，奥拉瑞克幽默地坚持要把他的旧靴子留在土里，并评论说那些靴子从来都不合脚。",al={"奥拉瑞克的靴子","留下靴子"}}},fp="16,137,18.321.0,19.312.1,14.295.0,34.101.0,34.158.0,48.186.0,37.124.1,50.137.0"}
P.entries["quest:463"] = {n="绿色守卫者",s="“林地守护者”是一个引导联盟玩家深入湿地沼泽的任务。大副菲兹莫斯会从米奈希尔港指派冒险者前往东北方的沼泽，寻找一个传说中潜伏在野兽之中的神秘实体。",h="“林地守护者”是一个引导联盟玩家深入湿地沼泽的任务。大副菲兹莫斯会从米奈希尔港指派冒险者前往东北方的沼泽，寻找一个传说中潜伏在野兽之中的神秘实体。",kw={"丹莫德","菲兹莫斯","林地守护者","米奈希尔","雷希尔","践踏之爪","湿地"},ang={["class:Druid"]="虽然普通的码头工人将雷希尔视为沼泽怪物，但德鲁伊会立即认出这是一位与自然平衡共鸣的远古守护者。",["race:NightElf"]="远离卡利姆多的暗夜精灵们，即使在卡兹莫丹潮湿泥泞的土地上，也能找到一种熟悉而令人慰藉的自然远古守护者的回响。"},sec={{t="酒馆传闻与沼泽故事",b="在米奈希尔港的码头周围，水手和流浪者们总是绘声绘色地谈论着沼泽中潜伏的野兽。大副菲兹莫斯将林地守护者描述为一个长着腿的贪婪怪兽，警告那些轻信的探寻者，一旦离开干燥的道路，就会被“老绿皮”咬成两段。对于码头的人们来说，任何潜伏在浑浊水域中的庞然大物，都不过是沼泽里又一个吃人的威胁罢了。"},{t="沼泽的守护者",b="那些勇敢地听从指引，向着丹莫德岔路口以东进发的人会发现，酒馆里的传闻完全错了。林地守护者并非无脑的食肉动物，而是雷希尔，一位与湿地野蛮生长之物结合的高大远古守护者。雷希尔非但不会吞噬游荡的傻瓜，反而还在注视着这片被糟蹋土地的悲哀，并招募愿意帮忙的凡人来净化这片被污染的沼泽。"}},faq={{q="林地守护者是谁？",a="林地守护者就是雷希尔，一位居住在湿地的远古自然守护者。虽然沿海的水手认为他是一个野蛮的怪物，但他实际上是一位与植物和野生动物融为一体的睿智守护者。",al={"林地守护者是谁","林地守护者身份","雷希尔是谁"}},{q="我在哪里可以找到林地守护者？",a="雷希尔位于大路以东的沼泽地中，靠近湿地北部通往丹莫德的岔路口附近。",al={"林地守护者位置","雷希尔在哪里","林地守护者坐标"}},{q="为什么大副菲兹莫斯认为林地守护者很危险？",a="菲兹莫斯只知道米奈希尔港的酒馆传闻和迷信。由于湿地到处都是野兽，水手们理所当然地认为任何潜伏在鳄鱼和掠食者之中的巨大实体，都只是又一个吃人的野兽。",al={"为什么菲兹莫斯感到恐惧","林地守护者是邪恶的吗"}},{q="雷希尔找旅行者有什么事？",a="雷希尔在寻找勇士来照料湿地，他形容这片土地正因溃烂的伤口而哭泣。他指引来访者保护野生动物，并平息那些破坏当地生态系统稳定的威胁。",al={"林地守护者做什么","雷希尔的目的","为什么要见林地守护者"}},{q="找到林地守护者后会发生什么？",a="一旦你与雷希尔交谈，他会认可自然对你的评价，并给你任务“践踏之爪”，以帮助解决困扰沼泽的问题。",al={"林地守护者的后续任务","践踏之爪任务"}},{q="这个任务需要战斗才能完成吗？",a="不需要。这个任务只需要在穿越湿地的旅途中活下来，并直接在沼泽中的林地与雷希尔交谈即可。",al={"林地守护者战斗","我要和林地守护者战斗吗"}}},fp="15,169,27.378.0,25.283.1,23.170.0,33.107.0,67.199.0,38.173.0,43.138.0,54.105.0"}
P.entries["quest:464"] = {n="龙喉战旗",s="米奈希尔港的斯托菲队长指派联盟勇士去袭击镇子东北方的一个龙喉兽人营地，并夺回他们的战旗。这些兽人的残党在第二次战争后被击溃并四散奔逃，如今又开始在湿地的沼泽中积蓄力量。",h="米奈希尔港的斯托菲队长指派联盟勇士去袭击镇子东北方的一个龙喉兽人营地，并夺回他们的战旗。这些兽人的残党在第二次战争后被击溃并四散奔逃，如今又开始在湿地的沼泽中积蓄力量。",kw={"斯托菲队长","龙喉氏族","格瑞姆巴托","米奈希尔港","奈克罗什","奈克罗斯","战旗","湿地"},ang={["class:Warrior"]="直接打击这个战争营地是对你勇气的考验，因为你要面对那些即便失去了龙类坐骑，依然战斗得如疯子般凶狠的第二次战争老兵。",["faction:Alliance"]="米奈希尔港是暴风城、铁炉堡与北方诸王国之间的重要生命线；容忍一个敌对的兽人营地在附近扎根会危及整个航运通道。",["race:Dwarf"]="龙喉氏族亵渎了古老的矮人要塞格瑞姆巴托，并用战争玷污了周边的山脉，因此每杀死一名龙喉战士，都是在执行迟到的正义。"},sec={{t="龙喉氏族的残党",b="在第二次战争期间，龙喉氏族在格瑞姆巴托的山中要塞奴役了红龙军团。当他们邪恶的控制被打破时，获得自由的巨龙对俘虏者发起了猛烈的复仇，几乎将兽人赶尽杀绝。少数幸存者逃离了格瑞姆巴托，躲进了威尔加挖掘场东面的高山中，躲避红龙军团的愤怒。"},{t="崛起的营地",b="尽管龙喉兽人曾被认为已彻底覆灭，但他们又重新出现了。在米奈希尔港的东北方，这些野蛮的幸存者建立了一个活跃的战争营地，并将他们的绯红旗帜插在了沼泽地里。斯托菲队长意识到了在港口城镇附近出现如此激进的兽人武装力量所带来的危险，他要求削减其兵力，并拆毁他们引以为傲的战旗作为他们战败的证明。"},{t="奈克罗斯的遗产",b="在夺取战旗后，斯托菲队长揭露说这些重组的兽人由奈克罗什领导，他是臭名昭著的术士奈克罗斯之子。奈克罗斯曾通过黑暗魔法指挥被俘的红龙，直到魔法失效，他本人也被昔日的俘虏撕成了碎片。他那充满仇恨的儿子如今统领着幸存者，心中怀着对杀害他父亲的那些巨兽的执念与复仇渴望。"}},faq={{q="湿地的龙喉兽人是谁？",a="他们是在第二次战争期间奴役红龙军团的兽人氏族的残党。在失去对巨龙的控制后，他们遭到了无情的猎杀和驱散，幸存者从格瑞姆巴托逃走，躲藏在山脉和沼泽之中。",al={"龙喉兽人 湿地","龙喉氏族是谁","湿地兽人"}},{q="为什么斯托菲队长想要他们的战旗？",a="斯托菲队长认为米奈希尔港东北方新建立的营地对该镇构成了严重威胁。他要求获取他们的战旗，作为联盟士兵已经袭击该营地并削弱其战斗力的实证。",al={"为什么要收集战旗","斯托菲队长 战旗"}},{q="龙喉氏族的那些巨龙发生了什么事？",a="当束缚巨龙的黑暗魔法失效后，红龙军团调转枪头对付他们的俘虏。巨龙在卡兹莫丹各地凶猛地猎杀龙喉兽人，彻底重创了该氏族。",al={"巨龙发生了什么","龙喉巨龙"}},{q="现在是谁在领导龙喉氏族？",a="他们由奈克罗什领导，他是前龙喉氏族首领奈克罗斯之子。奈克罗什集结了幸存者，并发誓要向杀害他父亲的红龙复仇。",al={"龙喉首领","谁是奈克罗什"}},{q="龙喉兽人在建立这个营地之前躲在哪里？",a="在逃离格瑞姆巴托后，幸存的兽人躲藏在威尔加挖掘场东部的崎岖山脉中，随后才进入湿地沼泽建立营地。",al={"龙喉兽人躲在哪里","龙喉避难所"}},{q="这些龙喉兽人隶属于萨尔的部落吗？",a="不。这些龙喉残党是出于复仇和生存目的的独立武装，他们的行动完全游离于萨尔大酋长在卡利姆多建立的新部落之外。",al={"龙喉兽人是否在部落中","龙喉 萨尔部落"}}},fp="11,187,25.312.0,19.296.0,20.323.1,43.220.0,50.190.0,46.154.0,33.143.1,57.162.0,56.132.0"}
P.entries["quest:465"] = {n="纳克罗什的优势",s="“内克罗什的赌博”是由米奈希尔港的斯托菲队长委派的一项紧急打击任务。获悉酋长内克罗什建造了攻城器械，企图在增援部队被阻断在丹奥加兹的情况下轰炸这座脆弱的港口小镇，联盟派遣了勇敢的志愿者深入沼泽，在袭击开始前烧毁龙喉氏族的投石车。",h="“内克罗什的赌博”是由米奈希尔港的斯托菲队长委派的一项紧急打击任务。获悉酋长内克罗什建造了攻城器械，企图在增援部队被阻断在丹奥加兹的情况下轰炸这座脆弱的港口小镇，联盟派遣了勇敢的志愿者深入沼泽，在袭击开始前烧毁龙喉氏族的...",kw={"斯托菲队长","投石车","龙喉氏族","丹奥加兹","米奈希尔港","内克罗什","内克罗什的赌博","湿地"},ang={["class:Warrior"]="突袭戒备森严的敌军战营以摧毁重型攻城炮火，需要积极的前线战术和残酷的肉搏战。",["faction:Alliance"]="随着丹奥加兹陷入战斗封锁，联盟必须依靠勇敢的志愿者而非正规军队来瓦解龙喉氏族的战争机器。",["race:Dwarf"]="米奈希尔港是铜须矮人通往西海的门户；如果它毁于龙喉氏族的攻城武器，铁炉堡的海上联系将会遭到重创。"},sec={{t="迫在眉睫的围攻",b="当联盟的冒险者们正与龙喉氏族的突击小队交战时，矮人侦察兵发现了该氏族的真正企图。酋长内克罗什在湿地的营地中亲自监督建造了全尺寸的攻城投石车。他的目标大胆而极具毁灭性：将他的战争机器推进到米奈希尔港，轰塌堡垒的城墙，摧毁联盟在西海岸的主要航运枢纽。"},{t="受阻于丹奥加兹",b="丹奥加兹的瓶颈让米奈希尔港的处境更加危急。山道中激烈的战斗和兽人的活动有效地将低地与铁炉堡的主力守军隔离开来。由于无法从卡兹莫丹获得即时援助，斯托菲队长无法抽调防御部队来守卫外围，因此，先发制人地破坏投石车成了港口唯一的生存机会。"},{t="营地中的烈火",b="携带“矮人火绒”的侦察兵必须直接冲入龙喉营地的中心。将那些笨重的木制器械付之一炬，不仅能让内克罗什失去炮火支援，使他的战士们暴露在危险之中，还能阻止他们在与这位督军正面交锋前摧毁米奈希尔的防御。"}},faq={{q="内克罗什是谁？",a="内克罗什是统领湿地龙喉氏族残部的冷酷酋长。他正在策划一场直接的军事行动，意图围攻米奈希尔港。",al={"内克罗什","酋长内克罗什","内克罗什是谁"}},{q="为什么米奈希尔港如此危险？",a="该镇高度依赖海上贸易，在地理上与铁炉堡隔绝。由于丹奥加兹的山口正陷入激战，无法通过陆路获得增援，导致该镇无法抵御集中式的围攻。",al={"米奈希尔的危险","为什么港口脆弱","对米奈希尔的威胁"}},{q="这项任务的目标是什么？",a="你的任务是携带矮人火绒深入龙喉营地，在这些投石车被推向米奈希尔港之前将其点燃并摧毁。",al={"赌博任务目标","我要做什么","投石车任务"}},{q="谁发布了这个任务？",a="负责协调港口本地防御以及对抗龙喉氏族行动的矮人军官斯托菲队长，亲自下达了这些命令。",al={"任务发布者","谁发布了内克罗什的赌博","斯托菲队长的职责"}},{q="摧毁投石车之后要做什么？",a="一旦他们的攻城器械化为灰烬，就必须通过追踪并处决酋长内克罗什本人，彻底根除这一威胁。",al={"摧毁投石车之后","后续任务","接下来做什么"}},{q="为什么铁炉堡无法派兵支援米奈希尔？",a="连接洛克莫丹和湿地的道路穿过丹奥加兹，该地区正受到敌对势力的激烈争夺和伏击，切断了可靠的地面交通。",al={"丹奥加兹的封锁","为什么没有增援","铁炉堡的援助"}}},fp="17,270,15.339.0,20.337.0,22.309.0,16.149.0,38.207.0,33.159.0,27.132.0,46.118.1,49.144.0"}
P.entries["quest:466"] = {n="火岩矿石",s="钢架补给站的驾驶员迪恩·石轮正在寻找在湿地发现的易挥发火岩矿石样本。他相信这种矿石的爆炸特性可以彻底改变火炮弹药，因此他委托矿工前往北方，从一个隐蔽的洞穴中开采这种危险的矿物。",h="钢架补给站的驾驶员迪恩·石轮正在寻找在湿地发现的易挥发火岩矿石样本。他相信这种矿石的爆炸特性可以彻底改变火炮弹药，因此他委托矿工前往北方，从一个隐蔽的洞穴中开采这种危险的矿物。",kw={"奥加兹大门","火炮","炮弹","丹莫罗","火岩矿石","采矿","矿石","驾驶员迪恩·石轮","钢架补给站","湿地"},ang={["profession:Engineering"]="对于那些寻找下一次大爆炸的机械工程师来说，那些威胁要炸飞制造者的爆炸性化合物是他们日常工作的一部分。",["profession:Mining"]="开采火岩矿石需要娴熟的采矿技巧；矿石的挥发性使得从矿脉中精细地开采它，成为了对矿工工艺水平的真正考验。",["race:Dwarf"]="矮人工程师和炮手以不断推动火药技术的发展而闻名，而开发火岩矿石炮弹非常符合卡兹莫丹的攻城传统。"},sec={{t="一次易挥发的发现",b="关于一种被称为火岩矿石的稀有且不稳定的矿物的消息已经传到了钢架补给站的攻城机驾驶员和机械师耳中。据传，在湿地潮湿的沼泽地带，奥加兹大门西北的一个洞穴内蕴藏着丰富的矿脉。火岩矿石反应极其剧烈且处理起来十分危险，因为这种矿石有着在粗心的矿工面前爆炸的坏名声。"},{t="明日的弹药",b="在别人眼中是采矿隐患的东西，在驾驶员迪恩·石轮看来却是军事潜力。如果提炼得当，火岩矿石可以作为矮人火炮的毁灭性推进剂或载荷，制造出能够粉碎坚固防御工事的炮弹。迪恩·石轮希望能获得原始样本，这样勇敢（或者说鲁莽）的研究人员就可以在不炸平补给站的前提下开始测试冶炼技术。"}},faq={{q="火岩矿石有什么用？",a="火岩矿石是一种极易挥发的爆炸性矿物。驾驶员迪恩·石轮打算测试冶炼方法，以利用其活泼的特性来制造高威力的火炮弹药和炮弹。",al={"火岩矿石用途","火岩矿石作用"}},{q="火岩矿石在哪里可以找到？",a="矿脉位于奥加兹大门西北的一个洞穴系统中，坐落在湿地的南部山区。",al={"火岩矿石位置","如何获得火岩矿石"}},{q="驾驶员迪恩·石轮是谁？",a="驾驶员迪恩·石轮是铁炉堡攻城大队的一名矮人攻城机驾驶员，驻扎在丹莫罗的钢架补给站，与机械师和攻城工程师一起工作，致力于改进矮人的作战机械。",al={"驾驶员迪恩·石轮","谁发布此任务"}},{q="为什么开采这种矿石需要矿工锄？",a="火岩矿石天然存在于原生矿脉中，而不是地表的散矿。矿工必须具备足够的技巧，才能在不引爆的情况下，安全地将这种易碎且具有爆炸性的矿石从岩壁上凿下来。",al={"需要采矿技能吗","所需的采矿技能"}},{q="火岩矿石处理起来安全吗？",a="不安全。这种矿石以极不稳定著称，在挖掘、运输和冶炼过程中存在严重的意外爆炸威胁。",al={"火岩矿石危险吗","火岩矿石会爆炸吗"}},{q="这与“石轮的搜寻”有什么联系？",a="此任务直接承接“石轮的搜寻”。在该任务中，飞行员比罗·长须或巡山人卡德雷尔会把你派往钢架补给站，因为迪恩·石轮听到了关于这种稀有矿石的传言，并希望有人去搜寻它。",al={"石轮的搜寻后续","任务链"}}},fp="22,240,20.246.0,21.285.0,33.171.0,27.97.0,23.217.0,47.174.0,30.99.0,44.182.0"}
P.entries["quest:467"] = {n="迪恩·石轮的梦想",s="“石轮的搜寻”是一项联盟指令，旨在引导冒险者前往丹莫罗钢架补给站寻找驾驶员迪恩·石轮。这位充满热情的攻城坦克驾驶员听闻了一种奇异矿石的消息，并寻求一位大胆的探险家来为他的坦克军火寻找新鲜燃料。",h="“石轮的搜寻”是一项联盟指令，旨在引导冒险者前往丹莫罗钢架补给站寻找驾驶员迪恩·石轮。这位充满热情的攻城坦克驾驶员听闻了一种奇异矿石的消息，并寻求一位大胆的探险家来为他的坦克军火寻找新鲜燃料。",kw={"丹莫罗","炽热矿石","卡德雷尔","长须","驾驶员迪恩·石轮","攻城坦克","钢架补给站","石轮"},ang={["profession:Engineering"]="每天摆弄高爆炸药的工程师们，一定会敬佩石轮致力于提升坦克火力的执着精神。",["profession:Mining"]="目光敏锐、善于发现奇异可燃矿石的矿工，会发现石轮关于稀有地下矿石的传闻正合他们的口味。",["race:Dwarf"]="对于矮人巡山人和技师来说，向钢架补给站的同僚伸出援手，是完善卡兹莫丹武器库的一项光荣职责。",["race:Gnome"]="侏儒创新者们会很容易理解驾驶员迪恩·石轮想要将传统攻城武器推向常规安全极限之外的渴望。"},sec={{t="匠人的抱负",b="矮人的攻城坦克是工程学上的传奇杰作，但操作员们从不满足于现状。铁炉堡和洛克莫丹附近都在传言，驻扎在首都外不远处的驾驶员迪恩·石轮正计划升级他的战争机器的威力。无论是由飞行员比罗·长须还是巡山人卡德雷尔指引，旅行者们受招募的目的都很简单：去见见这位雄心勃勃的驾驶员，听听他的提议。"},{t="前往钢架补给站",b="驾驶员迪恩·石轮在钢架补给站设立了他的工作室，这是一处位于卡拉诺斯东侧路旁的试验场和集结地。在齿轮的碰撞声和喷涌的蒸汽中，石轮一直留意着是否有勇敢的探矿者，能够帮他找到那种已知的、极易挥发的稀有矿石，将他坦克的火力提升到毁灭性的新高度。"}},faq={{q="谁提供这个任务？",a="你可以由铁炉堡的飞行员比罗·长须或洛克莫丹路上的巡山人卡德雷尔指引前往寻找驾驶员迪恩·石轮。",al={"任务发布者","谁开启石轮的搜寻","在哪里获取任务"}},{q="我可以在哪里找到驾驶员迪恩·石轮？",a="驾驶员迪恩·石轮驻扎在丹莫罗的钢架补给站，就在卡拉诺斯东北方小路尽头。",al={"石轮位置","驾驶员迪恩·石轮在哪里","钢架补给站石轮"}},{q="驾驶员迪恩·石轮需要什么？",a="石轮热衷于改装他的攻城坦克，并痴迷于寻找能显著增强他坦克弹药火力的稀有矿脉。",al={"石轮的目标","石轮为什么要找我","石轮需要什么"}},{q="这个任务的后续是什么？",a="一旦你向补给站的驾驶员迪恩·石轮报到，他就会交给你“寻找炽热矿石”任务，引导你去湿地获取这种挥发性矿石。",al={"后续任务","石轮后续","石轮的搜寻之后是什么"}},{q="这是联盟专属任务吗？",a="是的，驾驶员迪恩·石轮和他的联系人都是铁炉堡军队和联盟的忠诚成员。",al={"部落可以做石轮的搜寻吗","阵营要求"}},{q="为什么补给站对野生矿石感兴趣？",a="矮人工程师和坦克驾驶员不断尝试新的燃烧化合物、烟火和挥发性元素，以使他们的战争机器在面对穴居人、黑铁矮人和野兽时更具优势。",al={"为什么需要攻城坦克矿石","矮人坦克火药"}}},fp="18,137,21.206.0,29.181.0,22.115.0,33.97.0,31.132.0,28.115.0,28.82.0,41.194.0"}
P.entries["quest:468"] = {n="向巡山人罗克加报告",s="“向巡山人罗克加报到”是一个联盟指引任务，指引冒险者从洛克莫丹的哨所向北前往丹奥加兹。巡山人卡德雷尔会派遣有能力的旅行者去与罗克加汇合，后者正在组织一场前往湿地泥泞低地的重要探险。这是连接矮人故乡与北方领土的关口。",h="“向巡山人罗克加报到”是一个联盟指引任务，指引冒险者从洛克莫丹的哨所向北前往丹奥加兹。巡山人卡德雷尔会派遣有能力的旅行者去与罗克加汇合，后者正在组织一场前往湿地泥泞低地的重要探险。这是连接矮人故乡与北方领土的关口。",kw={"丹奥加兹","铁炉堡","卡德雷尔","洛克莫丹","巡山人","罗克加","侦察","湿地"},ang={["faction:Alliance"]="确保丹奥加兹的安全可以保障通往米奈希尔港的陆路交通畅通无阻，米奈希尔港是联盟在东部王国的主要西部港口。",["race:Dwarf"]="响应巡山人同僚的号召，能够巩固铁炉堡腹地与湿地矮人领地之间至关重要的陆路联系。"},sec={{t="通往北门之路",b="丹奥加兹是洛克莫丹与湿地沼泽地带之间的关键动脉。这座防御森严的山口建在北部的山脊上，长期以来，它确保了往来于铁炉堡和更北方的联盟定居点之间的贸易、信使和军事分遣队的通行安全。随着边境局势日益紧张，巡山人卡德雷尔密切注视着过往的旅行者，招募坚韧的志愿者来加强北方的岗哨。"},{t="任务出岔子了",b="虽然巡山人卡德雷尔最初派出的新兵以为这只是一次普通的侦察任务，但丹奥加兹的现实情况却危险得多。到达北门后，冒险者发现巡山人罗克加正在准备一场真正的战斗，而非和平的侦察之旅。封锁山口的敌对势力迅速将原定的简单侦察变成了一场艰难且混乱的保卫关口的苦战。"}},faq={{q="是谁下令向罗克加报到的？",a="这项任务由巡山人卡德雷尔发布。他驻扎在塞尔萨玛，位置就在烈酒旅店的马路对面，负责监视通往山口的主路。",al={"谁发布向巡山人罗克加报到","罗克加任务发布者","卡德雷尔任务"}},{q="我在哪里可以找到巡山人罗克加？",a="巡山人罗克加驻扎在洛克莫丹向北延伸的道路上，守护着通往丹奥加兹山隧道的入口。",al={"罗克加位置","罗克加在哪里","巡山人罗克加所在地"}},{q="为什么通过丹奥加兹的任务如此重要？",a="丹奥加兹是连接洛克莫丹和湿地的主要陆路通道。确保该通道畅通对于联盟维持补给线、军事联络以及前往米奈希尔港及更远地区的交通安全至关重要。",al={"为什么要去丹奥加兹","丹奥加兹的重要性","湿地路线"}},{q="见到巡山人罗克加后会发生什么？",a="罗克加会立即请求你协助完成“丹奥加兹的关口”，并揭示原定的侦察行动已经演变成一场旨在清除封锁山隧道之敌对势力的血腥战斗。",al={"向罗克加报到后的任务","罗克加后续","罗克加之后的下一个任务"}},{q="什么等级的冒险者应该接取这个任务？",a="这项任务针对的是20到21级左右、已经完成洛克莫丹任务并准备好前往危险的湿地冒险的资深旅行者。",al={"罗克加任务等级","丹奥加兹任务等级","何时前往湿地"}},{q="部落角色可以接取这个任务吗？",a="不可以。铁炉堡巡山人只效忠于国王麦格尼·铜须和联盟，这意味着只有联盟冒险者才能接受该任务。",al={"部落可以做这个任务吗","部落向罗克加报到"}}},fp="29,240,26.348.0,19.279.1,41.155.0,37.123.0,51.196.0,47.166.1,56.159.0,44.135.0"}
P.entries["quest:4681"] = {n="搁浅的巨兽",s="“冲上岸的生物”是温尼斯·布莱葛在奥伯丁发起的一项调查，旨在检查黑海岸雾气弥漫的海岸线上死去的海洋生物。她代表达纳苏斯的Temple of the Moon行事，派遣冒险者前往奥伯丁西侧检查一具沉在水底的巨型海龟的骨架。这项研究试图解释为什么如此多的海洋生物会搁浅或死在岸边。",h="“冲上岸的生物”是温尼斯·布莱葛在奥伯丁发起的一项调查，旨在检查黑海岸雾气弥漫的海岸线上死去的海洋生物。她代表达纳苏斯的Temple of the...",kw={"奥伯丁","搁浅生物","黑海岸","达纳苏斯","温尼斯·布莱葛","海龟","海龟的残骸","泰达希尔","temple of the moon"},ang={["class:Druid"]="黑海岸古老海洋巨兽的大规模死亡和反常逃离，暗示了某种源自泰达希尔周围水域的自然平衡受到腐蚀或破坏。",["class:Priest"]="执行这项调查是为了支持Temple of the Moon的艾露恩女祭司，她们负责监督卡利姆多北部的精神与自然福祉。",["race:NightElf"]="奥伯丁是连接泰达希尔与大陆的门户；有证据表明海洋生物正在积极逃离你们的新家园，这是一个令人不安的预兆。"},sec={{t="令人不安的潮汐",b="黑海岸雾气弥漫的沙滩已成为海洋巨兽的坟场。搁浅的巨兽和溺毙的利维坦布满了沙滩和浅滩，让奥伯丁的暗夜精灵们困惑不已。在已经调查了岸边的一只搁浅生物后，温尼斯·布莱葛又指派旅行者潜入码头西侧的水域，靠近一艘沉船，去检查一具巨大的海龟骨架，并为Temple of the Moon收集证据。"},{t="逃离世界之树",b="温尼斯的最终目标是收集足够的物证，向达纳苏斯的艾露恩女祭司提交一份正式报告。她的初步发现指向了一个令人深感不安的假说：这些温顺的海洋动物可能并非死于意外，而是为了逃离外海的某种东西——这片水域可能环绕着泰达希尔本身。"}},faq={{q="为什么海洋生物会冲上黑海岸的岸边？",a="原因尚不清楚。温尼斯需要从搁浅的生物身上采集样本，以便她能向Temple of the Moon提交报告并继续研究。",al={"为什么海龟在死亡","黑海岸搁浅生物","为什么鲸鱼搁浅"}},{q="谁是温尼斯·布莱葛？",a="温尼斯·布莱葛是一名驻扎在奥伯丁的暗夜精灵研究员，直接向达纳苏斯的Temple of the Moon汇报。她正在记录黑海岸沿线死去的和搁浅的海洋生物潮。",al={"温尼斯","奥伯丁研究员","冲上岸的生物任务发布者"}},{q="海龟骨架在哪里？",a="海龟的骨架位于奥伯丁码头正西方的海底，靠近黑海岸外的一艘沉船残骸。",al={"海龟残骸位置","海龟骨架在哪里","海龟骨头"}},{q="Temple of the Moon与此事有何关联？",a="Temple of the Moon负责管理暗夜精灵领地的生态和精神事务。温尼斯需要具体的实体样本，以便就这种奇怪的死亡现象向女祭司们提交一份正式报告。",al={"达纳苏斯为什么关心","temple of the moon的作用","艾露恩女祭司的参与"}},{q="还有更多搁浅的生物可以找到吗？",a="是的。温尼斯指出，搁浅的生物遍布整个黑海岸的海岸线，她鼓励冒险者搜寻沙滩，并从其他搁浅的巨兽身上回收残骸。",al={"其他搁浅的海洋生物","更多海洋生物任务","黑海岸搁浅巨兽"}},{q="两个“冲上岸的生物”任务有什么区别？",a="第一个任务派遣你去调查附近沙滩上搁浅的生物，而后续任务则要求你游到码头西侧，去检查一具沉在水底的海龟骨架。",al={"冲上岸的生物第一部分与第二部分","两个冲上岸的生物任务","冲上岸的生物任务链"}}},fp="13,229,17.352.0,26.266.1,50.140.0,29.197.0,41.138.0,54.172.0,41.147.0,62.177.0"}
P.entries["quest:469"] = {n="日常供货",s="“日常派送”是矮人猎人埃纳尔·石钳委托的一项差事，他请求前往米奈希尔港的旅行者将鞣制好的鳄鱼皮交给当地的制皮匠。为了避免在家中面对家庭矛盾，埃纳尔依靠过往的冒险者来维持他的补给线运作。",h="“日常派送”是矮人猎人埃纳尔·石钳委托的一项差事，他请求前往米奈希尔港的旅行者将鞣制好的鳄鱼皮交给当地的制皮匠。为了避免在家中面对家庭矛盾，埃纳尔依靠过往的冒险者来维持他的补给线运作。",kw={"鳄鱼皮","埃纳尔·石钳","詹姆斯·哈洛兰","米奈希尔港","塞达","制皮匠","湿地"},ang={["faction:Alliance"]="米奈希尔港是连接铁炉堡领地与北方大陆的主要海上门户，这使得鳄鱼皮等基本贸易商品对于装备当地卫兵和码头工人至关重要。",["race:Dwarf"]="即使远离铁炉堡，矮人们也在潮湿的低地进行贸易，尽管处理家庭纠纷显然比对付沼泽野兽要困难得多。"},sec={{t="不情愿的快递员",b="在沼泽地里，埃纳尔·石钳靠捕猎当地野生动物为生，尤其是那些潜伏在水道旁的凶猛鳄鱼。虽然他收集了大量有价值的毛皮，但交付这些货物需要前往米奈希尔港。由于不愿在婚姻出现裂痕时面对妻子塞达，埃纳尔更愿意留在野外，将包裹转交给过往的旅行者。"},{t="米奈希尔的商业贸易",b="这些毛皮的收件人是米奈希尔港的一位制皮匠，詹姆斯·哈洛兰。哈洛兰依靠当地猎人定期送来的货物，为来往港口的商人和水手制作靴子并鞣制皮革。由于注意到埃纳尔已经一周没露面了，这位制皮匠很容易就推断出这次代理交付背后的婚姻争执，并寻思着或许该让自己的妻子出面干预，去和塞达调解一下。"}},faq={{q="为什么埃纳尔·石钳不自己去送这些皮毛？",a="埃纳尔承认他的妻子塞达最近心情一直很糟糕。为了避免面对她的脾气，他逗留在湿地，并雇佣过往的旅行者将货物送进城里。",al={"埃纳尔为什么躲藏","埃纳尔的婚姻问题","埃纳尔为什么不回家"}},{q="詹姆斯·哈洛兰是谁？",a="詹姆斯·哈洛兰是驻扎在米奈希尔港的一名制皮匠和皮革制品工匠。他从当地捕兽人那里购买生皮和兽皮，将其鞣制并出售为靴子和成品皮具。",al={"制皮匠哈洛兰","詹姆斯·哈洛兰是谁"}},{q="塞达是谁？",a="塞达是埃纳尔·石钳的妻子，住在米奈希尔港。她最近的糟糕心情是埃纳尔整天待在沼泽地里不愿回家的主要原因。",al={"埃纳尔的妻子","塞达是谁"}},{q="正在运输的是什么种类的毛皮？",a="这批货物是一捆鳄鱼皮，是从沼泽地沼泽和水道中泛滥的大型爬行动物身上剥下来的。",al={"什么毛皮","日常派送物品"}},{q="哈洛兰知道为什么埃纳尔要避开米奈希尔港吗？",a="知道。当你把这一捆货物交给他时，哈洛兰提到埃纳尔已经有近一周没来过了，并立即猜测这是因为和塞达闹了矛盾。",al={"哈洛兰知道吗","制皮匠的反应"}},{q="这次派送是在哪里进行的？",a="这次派送始于湿地公路旁的埃纳尔·石钳，终于西海岸米奈希尔港的詹姆斯·哈洛兰工作室。",al={"在哪里交任务","日常派送地点"}}},fp="14,171,19.367.0,20.336.0,54.182.0,22.156.0,12.136.0,41.99.0,57.132.0,36.148.0"}
P.entries["quest:47"] = {n="金砂交易",s="“金砂交易”是闪金镇的雷米发布的一项早期悬赏。这位神经质的经纪人出钱雇佣冒险者，从盘踞在艾尔文森林各处矿洞里的狗头人手中夺取原生的金砂。虽然这为初出茅庐的旅者提供了正当的工作，但雷米那些可疑的门路暗示，他的生意不仅仅是简单的金属加工那么简单。",h="“金砂交易”是闪金镇的雷米发布的一项早期悬赏。这位神经质的经纪人出钱雇佣冒险者，从盘踞在艾尔文森林各处矿洞里的狗头人手中夺取原生的金砂。虽然这为初出茅庐的旅者提供了正当的工作，但雷米那些可疑的门路暗示，他的生意不仅仅是简...",kw={"艾尔文森林","法戈第矿洞","金砂","闪金镇","玉石矿洞","狗头人","雷米"},ang={["class:Rogue"]="雷米低沉的态度和他那来自未透露姓名的“合伙人”的信物，带有极其明显的地下组织在闪金镇平静表面下运作的气息。",["faction:Alliance"]="艾尔文森林至关重要的金矿和矿藏被野蛮的狗头人而非皇家挖掘队所把持，这一事实说明了王国的军事力量究竟匮乏到了何种地步。",["profession:Mining"]="在法戈第矿洞和玉石矿洞中搜寻的矿工会发现，狗头人紧紧守着最富集的铜矿脉，因此为了开采矿石，必须将他们清理掉。"},sec={{t="遍地钱袋与矿镐的小镇",b="闪金镇坐落在艾尔文森林的十字路口，商贾、城镇卫兵和疲惫的旅人在此交汇。其中就包括雷米，一个阴险的家伙，他喜欢重复自己说话的习惯掩盖了他敏锐的逐利眼光。与其雇佣昂贵的采矿队去开采原生矿物，雷米更愿意利用在Lion's Pride Inn中往来的冒险者。他的提议很简单：找回那些被当地害虫囤积的金砂，然后直接换取金币。"},{t="狗头人的劫掠",b="狗头人已经彻底占领了艾尔文森林最宝贵的地下开采场，即南部的法戈第矿洞和东北部的玉石矿洞。在黑暗中挖掘他们心爱的蜡烛和闪亮的小玩意儿时，这些像老鼠一样的掘地工将未精炼的矿石残渣和碎屑积攒在自己的口袋里。驱逐他们符合王国的利益，但收集这些金砂却让消灭害虫变成了一桩有利可图的买卖。"},{t="柜台后的阴影",b="虽然雷米声称支付高价纯粹是出于商业原因，但他的报酬却带着隐晦的警告。在收到金砂后，他会悄悄给帮手一个代表他“合伙人”的信物。在艾尔文森林，有组织的强盗、领不到薪水的石匠以及在暴风城阴影下运作的地下网络正日益扼杀这里的秩序，雷米那些沉默的经纪人对那笔黄金可能有着超越普通乡村贸易的计划。"}},faq={{q="谁是雷米？",a="雷米是一位古怪的当地经纪人，驻扎在闪金镇的Lion's Pride Inn外。他以重复句子结尾而闻名，他从往来的冒险者手中收购贵重材料，并与一些阴暗的合伙人保持着联系。",al={"雷米","金砂交易任务发放者","闪金镇的雷米"}},{q="狗头人从哪里得到的金砂？",a="狗头人终其一生都在挖掘艾尔文森林的矿脉，例如法戈第矿洞和玉石矿洞里的那些。当他们在岩石中抓挠挖掘，寻找宝藏和蜡烛时，天然的金片和金砂就会在他们的口袋和袋子里积聚。",al={"为什么狗头人有金砂","金砂来源"}},{q="我去哪里寻找雷米提到的矿洞？",a="携带金砂的狗头人主要可以在法戈第矿洞（位于闪金镇南面）和玉石矿洞（位于东北面，靠近东谷伐木场的边界）及其周围找到。",al={"矿洞位置","艾尔文森林狗头人位置"}},{q="为什么暴风城允许狗头人控制他们的矿洞？",a="由于瓦里安·乌瑞恩国王失踪，且贵族议会拒绝为边远地区抽调部队，暴风城卫兵的人手极其短缺。当地驻军无法清理矿洞，导致这些矿洞被狗头人占据，而战斗只能由独立的旅行者来完成。",al={"为什么矿洞没有守卫","暴风城为什么失去了矿洞"}},{q="金砂是用于锻造还是贸易？",a="在狗头人携带的原始形态下，金砂太过细小且杂质太多，无法用于普通的锻造工作。相反，它被作为原材料出售给像雷米这样的经纪人，由他们通过自己的私人渠道进行整合与提炼。",al={"金砂的用途","金砂可以熔炼吗"}}},fp="18,190,27.355.0,18.319.0,26.320.1,24.201.0,31.207.0,45.178.0,56.235.0,45.205.0"}
P.entries["quest:470"] = {n="搜寻软泥怪",s="塞达在铁须之墓照例祭拜时，被在墓穴附近徘徊的恶心软泥怪吓到了，于是扔出自己的背包来引开它们。由于不敢再次面对那些蠕动的淤泥怪，她请求米奈希尔港的勇敢的冒险者去追踪那个吞掉了她财物的生物。",h="塞达在铁须之墓照例祭拜时，被在墓穴附近徘徊的恶心软泥怪吓到了，于是扔出自己的背包来引开它们。由于不敢再次面对那些蠕动的淤泥怪，她请求米奈希尔港的勇敢的冒险者去追踪那个吞掉了她财物的生物。",kw={"丹莫德","铁须之墓","米奈希尔港","软泥怪","沾满软泥的背包","塞达","塞达的背包","湿地"},ang={["faction:Alliance"]="米奈希尔港是联盟穿过险恶湿地的主要生命线，帮助受惊的市民能确保这个重要港口的安全与秩序。",["race:Dwarf"]="铁须之墓安放着一位受人尊敬的矮人先祖的遗骸，被污秽的软泥怪玷污墓穴是对任何铜须忠诚者的侮辱。"},sec={{t="惊惶撤退",b="塞达是一位居住在米奈希尔港的旅人，她经常前往东北方的湿地，在铁须之墓进行祭拜。在最近一次访问中，她发现这座古老的墓穴里爬满了污秽、滴着粘液的软泥怪。看到这些无定形的怪物，她惊慌失措，将自己的挎包扔向其中一只。那生物直接将背包囫囵吞下，不过这也让塞达争取到了足够的时间逃回了安全的港口城镇。"},{t="铁须之墓的淤泥",b="著名的矮人英雄铁须的安息地位于竞争激烈的丹莫德要塞附近。尽管它具有历史上的尊崇地位，但周围的沼泽地很容易受到腐化，吸引了无定形的酸性软泥怪，吞噬任何不幸路过此地的东西。塞达记不清到底是哪只怪物吞掉了她珍贵的财物，只能留待旅人们去搜寻墓地，切开那些蠕动的疫病怪，找回她那被浸湿的挎包。"}},faq={{q="塞达是谁？",a="塞达是一位身处米奈希尔港的联盟旅人。她经常前往湿地进行朝圣，访问铁须之墓。这个习惯最近让她陷入了严重的危险，当时敌对的软泥怪伏击了她。",al={"塞达","谁发布任务","塞达是谁"}},{q="铁须之墓在哪里？",a="铁须之墓位于湿地的东北部，丹莫德以南。这座石制墓穴周围的区域已经被腐蚀性的湿地软泥怪所侵扰。",al={"铁须之墓位置","铁须在哪里","软泥怪在哪里"}},{q="哪只软泥怪吞掉了塞达的背包？",a="塞达在受到攻击时陷入了恐慌，无法区分这些生物。在铁须之墓外徘徊的任何粘液怪都可能是那个藏着她被消化财物的罪魁祸首。",al={"哪只软泥怪","带着背包的软泥怪","背包在哪里"}},{q="塞达为什么要去铁须之墓？",a="塞达每周都会去墓地向安葬在那里的古代矮人致敬，但这一平静的传统却因软泥怪的意外出现而中断了。",al={"塞达为何访问墓地","塞达每周访问"}},{q="找回背包后会发生什么？",a="当将沾满粘液的挎包带回米奈希尔港后，塞达会把里面的东西倒在地上以取回她的个人物品。她发现这个被毁坏的容器太恶心了，不值得保留，于是便将清理干净的背包送给了找回它的冒险者。",al={"背包里有什么","背包奖励"}},{q="这和附近的黑铁矮人有关吗？",a="虽然北边的丹莫德正卷入与黑铁部族的冲突之中，但侵扰铁须之墓的粘液怪是湿地潮湿、腐烂角落里的野生沼泽掠食者，并非矮人士兵。",al={"与黑铁矮人的关联","与丹莫德的关联"}}},fp="24,175,18.370.0,26.386.0,12.157.0,26.135.0,32.145.0,39.135.0,40.232.1,48.207.0"}
P.entries["quest:471"] = {n="学徒的职责",s="“学徒的职责”是米奈希尔港的制皮师詹姆斯·哈洛兰提供的一份联盟契约。在将年轻的学徒送入沼泽却导致他被巨型鳄鱼人咬伤后，哈洛兰雇佣了一位能干的冒险者去完成那项危险的收集任务，并报一箭之仇。",h="“学徒的职责”是米奈希尔港的制皮师詹姆斯·哈洛兰提供的一份联盟契约。在将年轻的学徒送入沼泽却导致他被巨型鳄鱼人咬伤后，哈洛兰雇佣了一位能干的冒险者去完成那项危险的收集任务，并报一箭之仇。",kw={"学徒的职责","鳄鱼人","巨型鳄鱼人","詹姆斯·哈洛兰","制皮","米奈希尔港","鱼人小屋","湿地","幼年鳄鱼人的皮"},ang={["class:Hunter"]="沼泽里的这些顶级掠食者是强大的目标，追踪成年巨型鳄鱼人是对追踪者在浑浊水域中航行和应对凶猛野生动物能力的考验。",["faction:Alliance"]="米奈希尔港是连接卡兹莫丹与联盟其余部分的一条生命线，这使得当地工匠的安全和自给自足对该港口的生存至关重要。"},sec={{t="艰苦的学徒生涯",b="像米奈希尔港这样的边境港口的商人必须依赖当地的原材料，但周围的沼泽却毫不留情。詹姆斯·哈洛兰将他年轻的学徒送入沼泽，去剥取湿地巨型鳄鱼人的皮。当这名年轻人没有回来时，哈洛兰循迹而去，发现他已经被那些捕食野兽严重咬伤了。"},{t="毛皮与报复",b="虽然当地的接生婆认为学徒能够活下来，但这孩子在袭击中落下残疾，失去了一条腿。由于需要补充库存，并寻求对那些伤害了他视如己出之人的野兽进行报复，哈洛兰征募旅行的冒险者沿着海岸向北前进，越过鱼人小屋，去猎杀那些巨型鳄鱼人。"}},faq={{q="詹姆斯·哈洛兰是谁？",a="詹姆斯·哈洛兰是一位在米奈希尔港工作的制皮师和鞣皮匠。他依靠从湿地各处的当地野生动物身上收集的皮革来维持他的手艺。",al={"詹姆斯·哈洛兰","谁发布了学徒的职责任务","米奈希尔港制皮师"}},{q="哈洛兰的学徒发生了什么事？",a="哈洛兰派他的学徒进入沼泽去从巨型鳄鱼人身上收集皮革。这个男孩遭到了掠食者的攻击并被严重咬伤，最终失去了一条腿，不过镇上的接生婆认为他能够活下来。",al={"学徒发生了什么","谁被咬伤了","学徒断腿"}},{q="巨型鳄鱼人在哪里？",a="巨型鳄鱼人在湿地的沼泽和北海岸出没，就在米奈希尔港以北的沿海鱼人定居点之外。",al={"巨型鳄鱼人在哪里","湿地鳄鱼人位置","巨型鳄鱼人地点"}},{q="有什么前置任务能开启这项任务？",a="该任务之前是“幼年鳄鱼人的皮”，哈洛兰先让冒险者猎杀较小的鳄鱼人，之后才升级到伤害了他学徒的巨型品种。",al={"学徒的职责前置任务","上一个任务","鳄鱼人任务线"}},{q="悲剧发生后，为什么哈洛兰还需要那些皮？",a="哈洛兰还需要做生意和完成订单，但他同时也因愤怒而驱动。他乐于让冒险者去猎杀那些伤害了他视如己出之人的野兽。",al={"为什么需要毛皮","哈洛兰的动机"}},{q="哈洛兰会让你当学徒吗？",a="在看到你的工作后，哈洛兰曾简短地开玩笑说要收你做他的新学徒，但随即打消了这个念头，指出你年纪太大了，而且显然注定要去经历另一种命运。",al={"我能成为学徒吗","学徒机会"}}},fp="19,167,22.308.0,21.310.0,22.141.0,39.165.0,39.127.0,43.164.0,57.173.0,42.186.0"}
P.entries["quest:472"] = {n="丹莫德的陷落",s="丹莫德，这座俯瞰着萨多尔大桥的北方矮人要塞，已经在黑铁矮人的猛烈攻击下沦陷了。米奈希尔港内一名身受重伤的幸存者正在寻找一位联盟冒险者，希望对方能前往北方，探明指挥官布莱德·长须以及要塞卫兵的残部是否还活着。",h="丹莫德，这座俯瞰着萨多尔大桥的北方矮人要塞，已经在黑铁矮人的猛烈攻击下沦陷了。米奈希尔港内一名身受重伤的幸存者正在寻找一位联盟冒险者，希望对方能前往北方，探明指挥官布莱德·长须以及要塞卫兵的残部是否还活着。",kw={"黑铁","丹莫德","哈尔罗·巴纳比","布莱德·长须","米奈希尔港","萨多尔大桥","湿地"},ang={["faction:Alliance"]="丹莫德的沦陷切断了铁炉堡与北方阿拉希高地联盟行动之间的安全陆路交通，使得北方走廊容易遭受破坏。",["race:Dwarf"]="铁炉堡山地矮人被屠杀，以及家乡南部的氏族亲属对丹莫德的亵渎，这是一种苦涩的、个人的侮辱，必须以血来偿还。"},sec={{t="破碎的北方堡垒",b="丹莫德长期以来一直是卡兹莫丹北部的基石，守护着连接湿地与阿拉希高地的萨多尔大桥这一重要交通要道。在桥梁本身遭遇伏击后，守军撤回要塞内试图重整旗鼓。但在防御防线重新建立之前，数量众多的黑铁矮人发动了猛攻，屠杀了守军并迫使他们进行绝望的撤离。"},{t="绝望的逃亡",b="哈尔罗·巴纳比是守军中的一名年轻士兵，在混乱的撤退中，一把流斧击中了他的后背，使他受了重伤。布莱德·长须认为他的伤势致命，便与剩余的部队一起将巴纳比绑在他们最后一匹幸存的战马上，将他送往南方的米奈希尔港。巴纳比在苦难中幸存了下来，但在港口的旅店醒来时，他却饱受幸存者愧疚感的折磨，完全不知道是否有战友从那场屠杀中生还。"},{t="冷酷的残部",b="在被占领的要塞附近，深处的北方沼泽中，布莱德·长须依然活着，并将一小群伤痕累累的幸存者团结在一起。尽管得知年轻的哈尔罗在那次重伤中幸存让他感到一丝宽慰，但这位老练的指挥官仍面临着严峻的战术现实：丹莫德已完全处于黑铁矮人的控制之下，其大厅被一群割喉者和破坏者占据，这威胁到了卡兹莫丹与北方人类领地之间的整个走廊。"}},faq={{q="丹莫德发生了什么事？",a="丹莫德被敌对的黑铁矮人攻占并夺取了。守军在附近的萨多尔大桥就已经遭受了伏击，在他们还未能在城镇内巩固防御之前，黑铁矮人就发起了进攻，并歼灭了大部分的守备团。",al={"为什么丹莫德被毁","谁袭击了丹莫德","丹莫德背景故事"}},{q="哈尔罗·巴纳比是谁？",a="哈尔罗·巴纳比是驻扎在丹莫德的一名铁炉堡士兵，在丹莫德沦陷时侥幸生还。在撤退过程中，他的后背被飞斧击中，他的指挥官将他绑在守军唯一幸存的马匹上，送往南方的米奈希尔港接受医疗救治。",al={"哈尔罗是谁","哈尔罗·巴纳比背景故事","米奈希尔受伤的士兵"}},{q="布莱德·长须在哪里？",a="指挥官布莱德·长须在被占领的丹莫德镇外围的荒野中避难，靠近通往萨多尔大桥的北部公路。",al={"布莱德在哪里","布莱德位置","寻找布莱德"}},{q="为什么丹莫德具有战略重要性？",a="丹莫德是湿地最北端的定居点和防御工事。它守护着萨多尔大桥的南端入口，这是连接卡兹莫丹与阿拉希高地及洛丹伦的唯一陆路桥梁。",al={"为什么要关心丹莫德","萨多尔大桥的联系"}},{q="是谁在攻击丹莫德？",a="攻击者是黑铁矮人，他们是来自南方的背信弃义的氏族成员，他们向北推进到湿地，旨在摧毁萨多尔大桥等基础设施，并骚扰铁炉堡的领地。",al={"谁占领了丹莫德","湿地的黑铁矮人"}},{q="找到布莱德后会发生什么？",a="一旦你确认布莱德还活着并带去巴纳比幸存的消息，布莱德就会让你参与一项针对占据丹莫德废墟的黑铁矮人部队的残酷复仇任务。",al={"丹莫德沦陷后续","丹莫德沦陷后会发生什么"}}},fp="16,244,25.393.0,18.398.0,16.384.1,26.217.0,21.271.0,36.141.1,40.202.0,34.206.0,37.188.1"}
P.entries["quest:4722"] = {n="搁浅的海龟",s="在黑海岸那终年笼罩着薄雾、被浪潮拍打的海岸上，躺着一只巨大的搁浅海龟的残骸，周围环绕着四处搜寻食物的鱼人。尽管已经被啃食得残破不堪，但仍能从残骸中提取出有价值的生物样本。奥伯丁的博物学家们会收集这些样本，并运回达纳苏斯的Temple of the Moon进行正式研究。",h="在黑海岸那终年笼罩着薄雾、被浪潮拍打的海岸上，躺着一只巨大的搁浅海龟的残骸，周围环绕着四处搜寻食物的鱼人。尽管已经被啃食得残破不堪，但仍能从残骸中提取出有价值的生物样本。奥伯丁的博物学家们会收集这些样本，并运回达纳苏斯的...",kw={"奥伯丁","搁浅","黑海岸","达纳苏斯","温尼斯·布莱葛","鱼人","残骸","海龟"},ang={["class:Druid"]="德鲁伊将搁浅的海洋生物和食腐的鱼人视为黑海岸生态失衡的征兆，这需要密切的观察与修复。",["race:NightElf"]="远古海洋生物无法解释的搁浅预示着卡利姆多水域深处发生了更严重的破坏，这促使奥伯丁和达纳苏斯的研究者们调查每一个被冲上岸的利维坦。"},sec={{t="搁浅的利维坦",b="黑海岸漫长的海岸线经常会出现来自无尽之海的遇难生物，包括那些死后漂流上岸或因迷失方向而搁浅的巨型古老海龟。一旦搁浅，这些尸体很快就会引来食腐动物。充满敌意的灰雾鱼人在海龟的骨架周围建立了简陋的营地，切割着龟肉和龟壳。尽管遭到了它们的啃食，但在残骸中往往仍保留着完好的骨骼、甲壳或组织样本。"},{t="达纳苏斯的实地研究",b="温尼斯·布莱葛驻扎在奥伯丁定居点，她是一名实地研究员，负责记录沿海异常的海洋生物和生态干扰。暗夜精灵们带着敬畏与科学的好奇心观察着这些搁浅的野兽。一旦回收，合适的残骸会被仔细分类并准备运往达纳苏斯，那里的学者们正试图查明为何如此多的远洋巨兽会冲上岸边。"}},faq={{q="为什么黑海岸有这么多搁浅的海洋生物？",a="黑海岸动荡的水域和强大的沿岸洋流会自然地将漂流的残骸和垂死的海洋生物冲上沙滩。暗夜精灵学者怀疑深海中的非自然干扰正在将海洋生物驱赶向浅滩，这促使当地的博物学家研究每一个冲上岸的尸体。",al={"为何海龟死亡","黑海岸搁浅生物","为何搁浅"}},{q="谁需要这些海龟残骸？",a="温尼斯·布莱葛，一名位于奥伯丁的暗夜精灵研究员，她代表达纳苏斯的博物学家和学者，从冒险者手中收集被冲上岸的样本。",al={"任务交给谁","温尼斯 奥伯丁","海龟残骸任务地点"}},{q="为什么鱼人聚集在海龟周围？",a="当地的灰雾鱼人是机会主义者，它们会搜寻任何被冲上海滩的东西。搁浅的巨型海龟为它们提供了丰富的肉类、坚韧的皮和用于制造工具与遮蔽物的骨骼。",al={"海龟附近的鱼人","灰雾食腐者","鱼人营地"}},{q="温尼斯收到样本后会做什么？",a="温尼斯会将有价值的组织和骨骼样本打包，通过海运送往达纳苏斯，那里的学者和女祭司会检查它们，以监测沿海生态系统的健康状况和行为模式。",al={"达纳苏斯如何处理残骸","海龟样本研究"}},{q="这是海岸上唯一的搁浅生物吗？",a="不是。黑海岸漫长的海岸线上有多只搁浅的海龟以及搁浅的海洋巨兽，其中几只为奥伯丁的学者提供了研究样本。",al={"其他搁浅动物","更多死海龟","被冲上岸的生物"}},{q="海龟对暗夜精灵来说是神圣的吗？",a="暗夜精灵将卡利姆多的原生野兽视为艾露恩与荒野之神庇护下的自然平衡的一部分。虽然海龟并非独有的神圣化身，但它们意外的死亡和搁浅被视为严重的生态警示信号。",al={"暗夜精灵海龟","德鲁伊与海龟"}}},fp="18,256,20.400.0,28.384.0,57.273.0,33.129.0,43.154.0,56.191.0,50.163.0,42.230.0"}
P.entries["quest:4723"] = {n="搁浅的海洋生物",s="在薄雾海那雾气缭绕的岸边，躺着一具巨大的长尾鲨尸骸，它的体型远超黑海岸浅滩中常见的任何生物。虽然当地的鱼人正在啃食腐肉，但奥伯丁的博物学者们仍在寻找骨骼样本，试图弄清为何这种巨大的深海怪兽会搁浅在海岸上。",h="在薄雾海那雾气缭绕的岸边，躺着一具巨大的长尾鲨尸骸，它的体型远超黑海岸浅滩中常见的任何生物。虽然当地的鱼人正在啃食腐肉，但奥伯丁的博物学者们仍在寻找骨骼样本，试图弄清为何这种巨大的深海怪兽会搁浅在海岸上。",kw={"奥伯丁","搁浅","骨骼","黑海岸","温尼斯·布莱葛","薄雾海","鱼人","海兽","长尾鲨"},ang={["class:Druid"]="致力于维护自然和谐的德鲁伊们将这只搁浅的巨兽视为无尽之海生态系统遭到破坏的警示信号。",["race:NightElf"]="黑海岸沿线的搁浅事件是周边水域失去平衡的令人不安的迹象，这促使奥伯丁和达纳苏斯的博物学者们展开调查，以免更多的海洋生物丧生。"},sec={{t="浅滩上的巨兽",b="薄雾海的海岸线并不乏沉船和潮水冲上来的残骸，但这种巨大的长尾鲨遗骸的突然出现令人担忧。这只生物的体型令当地常见的野生动物相形见绌，显然它来自远超无尽之海平静水域的深海。尽管沿海的鱼人蜂拥而上，争相分食这具尸体，但它们并没有力量或协作能力来猎杀如此规模的深海巨兽。这只掠食者在冲上岸之前，显然是被其他某种东西击倒的。"},{t="达纳苏斯的研究",b="奥伯丁的温尼斯·布莱葛正在协调实地工作，从黑海岸搁浅的巨型动物身上收集骨骼和生物样本。达纳苏斯的暗夜精灵研究人员希望通过检查骨骼残骸和组织样本，来确定是疾病、深海动荡还是奥术腐蚀驱使这些海洋巨兽冲上这片死亡之沙。"}},faq={{q="冲上岸的是什么野兽？",a="这是一具巨大的长尾鲨遗骸，它是水生掠食者，体型远大于黑海岸海滩附近通常见到的那些长尾鲨。",al={"这是什么生物","死去的怪物是什么","沙滩上死的是什么动物"}},{q="是鱼人杀了它吗？",a="不。尽管鱼人聚集在尸体周围分食腐肉，但观察者们指出，即使鱼人成群结队，它们也过于弱小，根本无法猎杀那种体型的深海巨兽。",al={"鱼人杀了长尾鲨吗","鱼人杀了海兽吗"}},{q="为什么海洋生物会搁浅在黑海岸？",a="确切原因尚不清楚。暗夜精灵研究人员怀疑是看不见的海洋动荡、疾病或生态环境恶化迫使深海动物游入浅滩，最终搁浅死亡。",al={"为什么长尾鲨在死亡","为什么生物会搁浅"}},{q="温尼斯·布莱葛是谁？",a="温尼斯·布莱葛是驻扎在奥伯丁的暗夜精灵研究员。她收集黑海岸搁浅野生动物的骨骼标本和生物样本，并送往达纳苏斯进行详细研究。",al={"温尼斯是谁","谁在奥伯丁收集骨头"}},{q="收集到的骨骼被送往哪里？",a="在温尼斯于奥伯丁对样本进行分类和预处理后，它们会被送往首都达纳苏斯的学者和博物学家手中，进行解剖学和魔法方面的调查。",al={"骨头被送到哪","奥伯丁如何处理骨头"}},{q="这具尸体位于何处？",a="这具尸体就躺在黑海岸西岸线薄雾海的沙滩上。",al={"尸体位置","搁浅的海兽在哪里"}}},fp="20,235,23.436.0,20.304.0,42.100.0,24.122.0,59.187.0,29.165.0,35.122.0,30.84.0"}
P.entries["quest:4725"] = {n="搁浅的海龟",s="黑海岸的浪潮中躺着一具巨大的海龟尸体，上面装着一辆破损的马车，贪婪的灰雾鱼人正蜂拥而至。与海岸上其他死去的巨兽不同，这只生物在死在沙滩上之前，曾被蛇形的纳迦当作驮兽来使唤。",h="黑海岸的浪潮中躺着一具巨大的海龟尸体，上面装着一辆破损的马车，贪婪的灰雾鱼人正蜂拥而至。与海岸上其他死去的巨兽不同，这只生物在死在沙滩上之前，曾被蛇形的纳迦当作驮兽来使唤。",kw={"奥伯丁","搁浅","马车","黑海岸","灰雾","温尼斯·布莱葛","纳迦","海龟","有奇怪标记的箱子"},ang={["faction:Alliance"]="调查搁浅生物为奥伯丁的哨兵提供了关键情报，可以追踪鱼人的泛滥和有组织的纳迦突袭队的崛起。",["race:NightElf"]="黑海岸冲上岸的纳迦补给兽的存在证实了卡多雷的祖先宿敌正在积极加固距离达纳苏斯令人不安的近距离滩头阵地。"},sec={{t="受羁绊的野兽",b="黑海岸那终年雾气笼罩的海岸上，搁浅的海巨兽数量多得令人担忧，但这只海龟却揭示了一个更为阴险的故事。在它那巨大的甲壳上捆绑着一辆破旧的马车，正随着潮汐腐烂废弃。与其他搁浅死亡的生物不同，它不是因疾病或自然衰竭而死，而是被智慧的操控者强行征用，并驱赶到了海岸上。"},{t="浅滩的拾荒者",b="这具尸体没安静多久。当地的灰雾鱼人很快便蜂拥而至，在腐烂的肉块和搜刮来的木材中挖出了一个巢穴。在鱼人的垃圾和海龟马车破碎的底盘之间，静静地躺着一个完好无损、带有奇特标记的容器，那是这只野兽的原主人留下的。"},{t="纳迦补给线",b="当把这个“有奇怪标记的箱子”交给奥伯丁的温尼斯·布莱葛时，残酷的现实浮出水面。容器上带有纳迦的标记，挽具也与那些蛇人用来从深海运输武器和战争物资的补给马车相吻合。这只死海龟直接证明了纳迦正在向黑海岸北部发起入侵，而找回的文物也被火速送往达纳苏斯进行进一步研究。"}},faq={{q="为什么海龟背上有辆马车？",a="这辆马车属于纳迦，他们将巨型海龟作为驮兽和攻城兽来使用。他们利用这些马车将补给和武器从深海运送到黑海岸的海岸线上。",al={"海龟马车","为什么海龟上有马车","被套上挽具的海龟"}},{q="马车里装的是什么？",a="在废弃的马车残骸中有一个“有奇怪标记的箱子”。上面的符文表明它是纳迦的财产，这促使奥伯丁的学者将其送往达纳苏斯进行官方审查。",al={"海龟箱子","有奇怪标记的箱子","海龟马车里的箱子"}},{q="为什么鱼人聚集在海龟周围？",a="灰雾鱼人居住在海岸线上，经常搜刮沉船和搁浅的尸体。它们将这只巨型海龟的遗骸当作了食物来源和巢穴。",al={"海龟周围的鱼人","灰雾鱼人与海龟","为什么鱼人吃海龟"}},{q="谁在研究黑海岸搁浅的生物？",a="奥伯丁的温尼斯·布莱葛负责监督对搁浅海洋生物浪潮的调查，并记录在它们遗骸上发现的文物和奇怪材料。",al={"谁在研究搁浅的海洋生物","奥伯丁研究员","温尼斯·布莱葛的职责"}},{q="这只海龟与黑海岸的其他搁浅生物有什么不同？",a="虽然许多其他生物是因为疾病、腐化或海洋灾难而被冲上岸，但显然这只海龟是经过驯化的，装上了沉重的货物装备，并且是被纳迦蓄意驱赶到沙滩上的。",al={"其他搁浅的海龟","为什么这只海龟不同","黑海岸的海龟之谜"}},{q="那个有标记的箱子离开奥伯丁后去了哪里？",a="温尼斯·布莱葛在奥伯丁记录了这一发现，并将那个纳迦箱子送往达纳苏斯，那里的精灵领袖正在分析北部边境日益增长的威胁。",al={"箱子被送到哪儿","送往达纳苏斯的箱子","奥伯丁怎么处理箱子"}}},fp="18,142,18.278.0,26.226.0,17.365.1,50.149.0,28.148.0,43.143.0,47.166.0,73.134.0,47.168.0"}
P.entries["quest:4727"] = {n="搁浅的海龟",s="在黑海岸的北岸，躺着一具巨大的搁浅海龟的骸骨。令人称奇的是，当地的灰雾鱼人似乎对它视而不见。代表月神殿，人们收集了它残骸的样本并交给了奥伯丁的温尼斯·布莱葛。博物学家和女祭司们想要找出这些海洋巨兽为何会冲上岸，以及为什么连食腐动物都不愿靠近这些残骸。",h="在黑海岸的北岸，躺着一具巨大的搁浅海龟的骸骨。令人称奇的是，当地的灰雾鱼人似乎对它视而不见。代表月神殿，人们收集了它残骸的样本并交给了奥伯丁的温尼斯·布莱葛。博物学家和女祭司们想要找出这些海洋巨兽为何会冲上岸，以及为什么...",kw={"奥伯丁","搁浅","残骸","黑海岸","灰雾","温尼斯·布莱葛","鱼人","遗骸","海龟","temple of the moon"},ang={["class:Druid"]="德鲁伊们密切监视着海岸线，当鱼人这类食腐物种拒绝碰触这些尸体时，他们深感忧虑，这预示着水域中可能存在某种不自然的污染。",["class:Priest"]="服务于月神殿意味着将艾露恩的仁慈管理延伸到所有生命，并调查那些扰乱自然和谐的死亡事件。",["race:NightElf"]="在黑海岸，这些雄伟海洋生物无法解释的死亡和被避开的现象，突显了威胁卡多雷祖居之地的日益严重的不平衡状况。"},sec={{t="奇怪的缺席",b="黑海岸的北海岸聚集着大量的灰雾鱼人，这些生物以疯狂地搜刮任何从迷雾之海冲上岸的营养物而闻名。然而，这具巨大的海龟骸骨却基本完好无损。是鱼人们单纯错过了这顿美餐，还是因为某种不为人知的原因主动避开了这些残骸，这对研究这片海滩生态的人来说仍然是一个令人困扰的谜团。"},{t="海岸线研究",b="在奥伯丁，温尼斯·布莱葛代表月神殿收集这些搁浅巨兽的样本。暗夜精灵女祭司们试图了解困扰着黑海岸水域的异动，她们利用骸骨碎片来确定是疾病、魔法腐化还是凶残的海洋捕食者导致了这些海洋古生物的死亡。"}},faq={{q="什么是搁浅的海龟？",a="它是黑海岸北部搁浅的一只远古海龟的巨大骸骨。它不同寻常的出现以及食腐动物的远离，使它成为了暗夜精灵研究的对象。",al={"海龟残骸","海龟骸骨","这是什么海龟"}},{q="为什么鱼人不碰那具尸体？",a="灰雾鱼人通常会撕碎海滩上的任何尸体，但它们却对这具残骸敬而远之。目前没人知道原因：鱼人可能只是没发现它，或者因为某种未知的原因而避开。温尼斯觉得它们的缺席很有意思，并打算在研究残骸时将其作为重点关注。",al={"为什么鱼人不吃它","灰雾鱼人海龟","为什么避开残骸"}},{q="温尼斯·布莱葛是谁？",a="温尼斯·布莱葛是一位驻扎在奥伯丁的暗夜精灵研究员，她代表月神殿收集黑海岸搁浅海洋生物的实地样本。",al={"温尼斯奥伯丁","谁想要海龟残骸","海龟任务上交"}},{q="月神殿为什么要关心搁浅的海洋生物？",a="艾露恩的女祭司们负责维护卡利姆多北部自然世界的平衡与管理。由于黑海岸的海洋生物死亡数量异常，神殿正在分析生物样本，以诊断导致海洋生物死亡的潜在病因。",al={"月神殿海龟","为什么研究海龟","艾露恩海洋生物"}},{q="这只海龟的具体位置在哪里？",a="这具特殊的残骸位于黑海岸北部的沙质海岸线上，靠近灰雾鱼人部落的栖息地。",al={"海龟在哪里","搁浅海龟位置","黑海岸海龟"}},{q="黑海岸还有其他搁浅的生物吗？",a="是的。黑海岸的海岸线上散布着多具搁浅的海洋生物和巨型海龟，每一具都促使奥伯丁的研究人员调查这些海洋巨兽死亡的原因。",al={"其他搁浅生物","更多海龟","搁浅海洋生物任务"}}},fp="18,297,17.267.0,22.304.0,31.177.0,41.243.0,29.142.0,65.177.0,44.102.0,50.174.0"}
P.entries["quest:4728"] = {n="搁浅的海洋生物",s="在黑海岸雾气缭绕的海岸线上，横卧着一具巨大的海洋哺乳动物尸骸，发掘工作被迫中途废弃。散落的工具和一辆闲置的独轮手推车显示，这里的考察被迫中止，使得这具标本成了伺机而动的鱼人和过往旅人好奇目光的对象。",h="在黑海岸雾气缭绕的海岸线上，横卧着一具巨大的海洋哺乳动物尸骸，发掘工作被迫中途废弃。散落的工具和一辆闲置的独轮手推车显示，这里的考察被迫中止，使得这具标本成了伺机而动的鱼人和过往旅人好奇目光的对象。",kw={"奥伯丁","搁浅","骨骼","黑海岸","探险者协会","温尼斯","鱼人","海洋生物"},ang={["faction:Alliance"]="这一发现突显了达纳苏斯和铁炉堡探险者协会在编纂卡利姆多之谜方面的合作努力。",["race:Dwarf"]="尸骸周围遗弃的工具属于你在探险者协会的同胞，他们被当地的鱼人从挖掘现场赶走了。",["race:NightElf"]="月神殿对巨型海洋生物异常频繁地死亡并冲上黑海岸神圣沙滩的现象深感忧虑。"},sec={{t="被迫中止的发掘",b="黑海岸沙滩上躺着的那具尸骸是一只巨大的海洋哺乳动物，其身体已被部分剖开，饱经海浪冲刷。在它腐烂的残骸周围散布着一辆生锈的独轮手推车和丢弃的发掘工具，这清楚地表明曾有人试图对这头野兽进行有组织的科学研究，但在完成之前就被驱赶走，或者匆忙放弃了此地。"},{t="探险者协会与鱼人",b="那些被遗弃的装备属于在黑海岸进行研究的铁炉堡探险者协会的野外研究员。当当地的鱼人蜂拥而至，宣称这头被冲上岸的巨兽归它们搜刮时，他们对这具巨型尸骸的研究便戛然而止。奥伯丁的温尼斯·布莱葛代表月神殿，乐于接受任何回收的骨骼样本，以进一步研究这桩困扰海岸线的不自然搁浅事件。"}},faq={{q="躺在沙滩上的这是什么生物？",a="这是一只被冲上黑海岸的巨型海洋哺乳动物的遗骸。该物种尚无明确鉴定，但它体型巨大，足以吸引食腐的鱼人和矮人研究员。",al={"搁浅海洋生物鉴定","这具尸骸是什么","死在这里的是什么"}},{q="是谁留下了这些工具和独轮手推车？",a="这些工具是矮人探险者协会的成员留下的。他们曾在此设立了一个发掘点来研究这头搁浅的野兽，但在完成研究前，遭到了敌对海岸鱼人的攻击并被驱赶。",al={"谁留下了工具","黑海岸废弃独轮车","谁在这里挖掘"}},{q="为什么温尼斯·布莱葛想要这些骨头？",a="温尼斯·布莱葛代表达纳苏斯的月神殿收集样本。暗夜精灵正在积极调查这桩令人不安的奇异现象，即大量巨型海洋生物死后被冲上黑海岸的海岸线。",al={"为什么温尼斯需要骨头","月神殿海洋生物","奥伯丁海洋骨骼"}},{q="为什么鱼人在尸骸周围徘徊？",a="鱼人是被这顿巨大的肉食盛宴吸引来的，随后它们驱赶了矮人学者，以便自己搜刮并捍卫这些残骸。",al={"尸骸周围的鱼人","为什么鱼人在这里","食腐鱼人"}},{q="探险者协会在当地与奥伯丁有正式盟约吗？",a="是的。作为联盟的成员，探险者协会在黑海岸保持着存在，并与当地的暗夜精灵当局展开合作，经常分享他们的科学发现和海岸调查报告。",al={"探险者协会奥伯丁","黑海岸的矮人","黑海岸联盟探险者协会"}},{q="黑海岸沿岸还有其他搁浅的生物吗？",a="是的。在黑海岸雾气弥漫的沙滩上，已经冲上了多具巨大的海洋野兽尸骸和骨架，这表明卡利姆多的水域发生了大范围的骚乱。",al={"更多搁浅生物","黑海岸其他尸骸","多具搁浅海洋生物"}}},fp="20,152,19.214.0,26.315.0,41.169.0,42.182.0,48.189.0,44.138.0,63.191.0,60.157.0"}
P.entries["quest:473"] = {n="向斯托菲队长报告",s="“向斯托菲队长报告”是一项在米奈希尔港发布的联盟军事指令。在丹奥加兹与龙喉氏族发生初步冲突后，瓦斯塔格·铁腭会将久经沙场的战士送入港口的城堡，以协调更深层次的防御工作。斯托菲队长负责指挥当地的驻军，并正在组织针对沼泽地中那些根深蒂固的兽人的直接打击。",h="“向斯托菲队长报告”是一项在米奈希尔港发布的联盟军事指令。在丹奥加兹与龙喉氏族发生初步冲突后，瓦斯塔格·铁腭会将久经沙场的战士送入港口的城堡，以协调更深层次的防御工作。斯托菲队长负责指挥当地的驻军，并正在组织针对沼泽地中...",kw={"斯托菲队长","龙喉氏族","丹奥加兹","米奈希尔港","米奈希尔城堡","瓦斯塔格·铁腭","war room","沼泽地"},ang={["class:Warrior"]="瓦斯塔格·铁腭非常看重纯粹的战斗能力，他会直接将经验丰富的一线战士派往斯托菲队长的战术指挥部。",["faction:Alliance"]="米奈希尔港是南方王国与卡兹莫丹之间运输货物和增援部队的主要门户；如果因为兽人突袭队而失去了这条道路，将重创联盟的贸易。",["race:Dwarf"]="保卫米奈希尔港与铁炉堡大门之间的贸易路线对于卡兹莫丹的安全至关重要，因此这项任务对矮人来说是必不可少的。"},sec={{t="日益扩大的威胁",b="虽然矮人登山者长期以来一直监视着丹奥加兹狭窄的山路，但龙喉氏族的卷土重来绝不仅仅局限于洛克莫丹的边界。瓦斯塔格·铁腭意识到，这些兽人正在向外扩张，建立营地并威胁着整个沼泽地。保卫隘口只是保障通往铁炉堡道路安全这项更大行动中的第一步。"},{t="米奈希尔的作战室",b="在米奈希尔城堡深处坐落着作战室，斯托菲队长在那里监督着这座联盟港口的防御。面对来自黑铁矮人破坏者、当地野兽和沼泽鱼人的攻击，队长依靠有能力的志愿者来应对外部军事威胁。瓦斯塔格的推荐证明了你足够强硬，可以接受针对龙喉战争机器的直接命令。"}},faq={{q="是谁让我去向斯托菲队长报告的？",a="瓦斯塔格·铁腭驻扎在米奈希尔港的米奈希尔城堡中，在你证明了自己在与当地龙喉兽人的战斗中的实力后，他会派你去向斯托菲队长报告。",al={"谁给予此任务","任务发布者","瓦斯塔格·铁腭"}},{q="斯托菲队长在哪里？",a="斯托菲队长在米奈希尔城堡内，位于西部沼泽地米奈希尔港的中心。你可以在城堡的作战室里找到他，他正站在战术地图前。",al={"斯托菲队长位置","斯托菲在哪","米奈希尔作战室"}},{q="为什么龙喉兽人是米奈希尔城堡优先处理的目标？",a="龙喉氏族在整个沼泽地都拥有古老的据点，并对连接米奈希尔港和铁炉堡的贸易路线构成了极具侵略性的威胁。随着他们的军队越过丹奥加兹，守军不能忽视他们不断扩张的营地。",al={"为什么对抗龙喉","龙喉威胁","沼泽地的兽人"}},{q="向斯托菲队长报告后会发生什么？",a="一旦你向斯托菲队长报告，他会直接将你编入对抗龙喉氏族的攻势中，派遣你去攻击他们的营地并摧毁他们在沼泽里的战旗。",al={"下一步做什么","后续任务","向斯托菲报告后"}},{q="沼泽地的龙喉兽人是什么来头？",a="龙喉氏族是旧部落的残党，他们在第二次战争期间因在格瑞姆巴托奴役红龙而闻名。尽管格瑞姆巴托已被摧毁，但幸存的战帮仍然盘踞在整个沼泽地，袭击过往旅客并公然反抗联盟的权威。",al={"龙喉氏族背景","谁是龙喉","沼泽地兽人"}},{q="为什么米奈希尔港的兵力如此捉襟见肘？",a="米奈希尔港不仅要应对源源不断的沼泽野生动物和入侵的鱼人，还要面对试图破坏港口的敌对黑铁矮人。由于驻军忙于保卫城墙和码头，斯托菲队长必须依靠外部的勇士来打击远处的兽人前哨站。",al={"米奈希尔防御","为什么部队繁忙","港口问题"}}},fp="27,260,17.316.0,24.331.0,34.163.0,35.144.0,56.232.0,50.174.0,43.242.0,41.270.0"}
P.entries["quest:4730"] = {n="搁浅的海洋生物",s="在黑海岸风雨交加的海岸线上，一具巨大的海洋哺乳动物尸体被冲上沙滩，早已残缺不全，周围还有伺机而动的鱼人。奥伯丁的温尼斯·布莱葛祭司正在收集这些搁浅巨兽的骨骼样本，试图查明为何这些本性温顺的海洋生物会死得如此惨烈。",h="在黑海岸风雨交加的海岸线上，一具巨大的海洋哺乳动物尸体被冲上沙滩，早已残缺不全，周围还有伺机而动的鱼人。奥伯丁的温尼斯·布莱葛祭司正在收集这些搁浅巨兽的骨骼样本，试图查明为何这些本性温顺的海洋生物会死得如此惨烈。",kw={"奥伯丁","搁浅的海中生物","黑海岸","温尼斯·布莱葛","鱼人","海洋生物的骸骨","泰达希尔","temple of the moon"},ang={["class:Druid"]="任何海洋生物行为的紊乱对塞纳里奥议会来说都是一个凶兆，这预示着某种不自然的腐蚀正在毒害海岸线上的野生动物。",["class:Priest"]="月神殿资助并监督了这项调查，寻求神启以了解导致卡利姆多水域动荡不安的腐蚀源头。",["faction:Alliance"]="保卫奥伯丁周围的海岸线，对于保障连接黑海岸、泰达希尔和东部王国之间重要的联盟航运线路至关重要。",["race:NightElf"]="黑海岸沿岸的搁浅事件令卡多雷人感到无比痛苦，他们崇尚自然和谐，目睹着新家园泰达希尔周边的水域变得日益动荡，心中充满了恐惧。"},sec={{t="可怕的海岸发现",b="沿着黑海岸人迹罕至的沙滩向北走，便能看到一具巨大的海洋哺乳动物尸体，它已经开始腐烂，且被啃食得残缺不全。海浪不断拍打着它裸露的肋骨，一群异常凶猛的鱼人正在贪婪地啃食着这些残骸。这一幕既悲惨又令人不安，预示着海洋的平衡正如同内陆那些遭到腐蚀的森林一样，正在严重崩塌。"},{t="非同寻常的搁浅",b="据温尼斯·布莱葛祭司所说，这些冲上海岸的生物通常是泰达希尔周边海域的原生温顺哺乳动物。与那些好斗的锯齿鲨不同，这些温顺的巨兽从未有过主动冲上岩石自杀的先例。月神殿正在积极进行骨骼取样，以查明究竟是何种邪恶的腐蚀或隐藏的威胁，迫使它们离开深海，惨死在海岸上。"}},faq={{q="被冲上岸的是什么生物？",a="这些骨架属于一种巨大的、温顺的海洋哺乳动物，它们通常栖息在泰达希尔根部周围深邃平静的水域。它们是天性平和的巨兽，不会表现出攻击性，也不会主动搁浅。",al={"这是什么动物","搁浅的生物是什么","海怪骨骼"}},{q="海洋生物为什么要搁浅？",a="具体原因尚不清楚，但温尼斯·布莱葛祭司指出，对于该物种而言，这种搁浅行为极不自然。暗夜精灵的研究者怀疑，周边海域可能存在潜在的动荡或腐蚀，导致这些生物迷失方向，或是迫使它们逃离原本的栖息地。",al={"为什么它会搁浅","为什么海洋生物会死亡","黑海岸搁浅"}},{q="温尼斯·布莱葛是谁？",a="温尼斯·布莱葛是驻扎在奥伯丁的月神殿祭司。她负责协调黑海岸海岸线的生态调查，通过收集骨骼残骸来研究折磨着当地海洋动物的病痛。",al={"谁是任务交付人","谁是温尼斯","奥伯丁祭司"}},{q="为什么鱼人会聚集在尸体周围？",a="这些鱼人是机会主义者，被这头搁浅的巨兽吸引，将其视为唾手可得的丰富食物来源。围聚在这具尸体旁的鱼人比奥伯丁附近的那些要更强壮、更具攻击性。",al={"为什么这里有鱼人","骨头附近的鱼人","海岸鱼人"}},{q="这种生物通常生活在哪里？",a="这些海洋哺乳动物生活在环绕着泰达希尔巨型枝干和根系的开阔水域中，在正常情况下极少接近内陆海岸。",al={"它们住在哪","海洋哺乳动物栖息地","泰达希尔海洋生物"}},{q="这与黑海岸的其他搁浅事件有什么联系？",a="有几种海洋生物被冲上了黑海岸，包括肉食性的锯齿鲨和巨型海龟。虽然锯齿鲨天性暴躁，但温顺哺乳动物的搁浅证实了这种海洋异常现象正在影响整个海岸生态系统中的各类物种。",al={"其他搁浅的海洋生物","搁浅的锯齿鲨","搁浅的海龟"}}},fp="20,216,30.254.0,26.305.0,37.170.0,38.269.0,29.194.0,43.144.0,39.145.0,53.259.0"}
P.entries["quest:4731"] = {n="搁浅的海龟",s="这头搁浅在黑海岸边的海龟尸体背着一辆破碎的马车，上面还有一个刻有奇怪符文的箱子。与其它自然搁浅的海洋生物不同，这只生物似乎是在作为役用野兽服役时被杀死的。",h="这头搁浅在黑海岸边的海龟尸体背着一辆破碎的马车，上面还有一个刻有奇怪符文的箱子。与其它自然搁浅的海洋生物不同，这只生物似乎是在作为役用野兽服役时被杀死的。",kw={"灰谷","奥伯丁","搁浅的海龟","黑海岸","灰雾","温尼斯·布莱葛","鱼人","娜迦","temple of the moon"},ang={["class:Druid"]="看着一头高贵的海龟被迫拖运战争武器，最后死后还要在食腐动物中腐烂，这展现了娜迦对野生动物的腐化和蔑视。",["faction:Alliance"]="调查这些残骸能向奥伯丁和达纳苏斯发出警告，让他们注意到威胁卡利姆多北部的娜迦后勤路线。",["race:NightElf"]="娜迦为了军事运输而亵渎海洋生物的行为令卡多雷感到愤怒，发现这些踪迹有助于Temple of the Moon追踪威胁灰谷的线索。"},sec={{t="役用野兽",b="黑海岸边到处都是远古海洋生物的遗骨，但这具海龟骨架却诉说着一个明显是人为的故事。在它巨大的龟壳上，捆绑着一辆撞毁的马车的残骸。这只生物并非像其它冲上岸的生物那样死于疾病或迷失方向；它是在运送货物时被赶上礁石的。在马车的残骸中，放着一个装饰有不熟悉的蛇形雕刻的容器，它被遗弃在那些以此腐烂外壳为食的拾荒者中间。"},{t="娜迦入侵",b="当温尼斯·布莱葛在奥伯丁检查这个被捞上来的箱子时，她认定这种工艺属于娜迦。在两栖攻击期间，这些蛇形恶魔经常利用巨大的海生物将补给品和武器运送到岸上。考虑到残骸位于黑海南岸的位置，温尼斯怀疑这批物资在运往灰谷的途中遭遇了不测，这表明娜迦在整个卡利姆多北部的野心正在扩张。"}},faq={{q="为什么这只海龟背上有一辆马车？",a="马车是娜迦安装在这只生物身上的，他们利用巨型海龟作为活的役用动物，将补给品、武器和战争物资从深海运送到陆地上。",al={"海龟马车","为什么海龟有马车","海龟挽具"}},{q="目前是谁住在遗骸里？",a="一群强大的灰雾鱼人在这只海龟死后占据了它巨大的外壳，并利用它巨大的空壳作为防御性的海边巢穴。",al={"谁住在海龟壳里","灰雾鱼人 海龟","守护海龟的是什么"}},{q="有奇怪标记的箱子应该送到哪里？",a="这个箱子应该送到温尼斯·布莱葛那里，她是驻扎在沿海定居点奥伯丁的一名代表Temple of the Moon的特使。",al={"我应该把箱子交给谁","有奇怪标记的箱子","上交奇怪标记的箱子"}},{q="箱子上的标记意味着什么？",a="这些标记是娜迦文字。它们表明该箱子和其所载的马车是沿海岸移动的娜迦补给车队的一部分，在灾难发生前很可能正向南前往灰谷。",al={"海龟箱子背景","谁制造了有奇怪标记的箱子","娜迦箱子"}},{q="为什么Temple of the Moon对搁浅的海龟感兴趣？",a="艾露恩的女祭司们正在调查威胁黑海岸的环境和军事威胁。像这个箱子一样回收的文物会被送到达纳苏斯，以便学者们绘制敌方活动的动向图。",al={"为什么神殿需要海龟","温尼斯 黑海岸任务"}},{q="海龟在死前要去哪里？",a="根据尸体沿海岸的位置，温尼斯·布莱葛怀疑娜迦正在指挥这只载货的生物向南行进，目的地可能是灰谷。",al={"海龟目的地","海龟要去哪里"}}},fp="18,147,17.367.0,18.385.1,53.171.0,40.143.0,39.101.0,37.170.1,60.198.0,46.150.1"}
P.entries["quest:4732"] = {n="搁浅的海龟",s="在饱经风霜的黑海岸边，巨大的海龟骸骨频繁被冲上岸，这令人感到不安。调查这些悲惨的搁浅事件，能为奥伯丁的温尼斯·布莱葛提供样本，从而研究为什么卡利姆多的海洋生物正在走向灭绝。",h="在饱经风霜的黑海岸边，巨大的海龟骸骨频繁被冲上岸，这令人感到不安。调查这些悲惨的搁浅事件，能为奥伯丁的温尼斯·布莱葛提供样本，从而研究为什么卡利姆多的海洋生物正在走向灭绝。",kw={"奥伯丁","搁浅","黑海岸","灰雾","温尼斯·布莱葛","鱼人","诺达希尔","海龟","泰达希尔","temple of the moon"},ang={["class:Druid"]="这些古老海洋居民的悲惨搁浅，是继海加尔山之战和泰达希尔突然出现之后，自然界失去平衡的鲜明标志。",["class:Priest"]="服务于Temple of the Moon并取回这些遗骸，有助于The Sisterhood of Elune诊断正在卡利姆多水域蔓延的看不见的灵性疾病。",["race:NightElf"]="Temple of the Moon致力于缅怀并了解那些曾经在诺达希尔枝叶下宁静嬉戏、如今却日渐消逝的生灵。"},sec={{t="骸骨之滩",b="雾气笼罩的黑海岸边散布着巨型利维坦和雄伟海龟的遗骸。许多这种古老的爬行动物漂流到了浅滩上，或是爬上沙滩等待死亡。灰雾鱼人经常成群结队地聚集在这些巨大的尸体旁，将血肉啃食殆尽，只剩下壳和骨头，并在腐肉周围建立起简陋的营地。"},{t="消逝的水域",b="第三次战争之前，海龟曾在大海加尔山和世界之树诺达希尔根部周围的圣洁水域中繁衍生息。在诺达希尔为击败燃烧军团而牺牲，以及随后在卡利姆多北岸种植泰达希尔之后，海龟的数量急剧下降。像温尼斯·布莱葛这样的艾露恩祭司正代表Temple of the Moon研究这些海岸遗骸，试图弄清楚是黑暗魔法、变幻莫测的大海，还是它们古老栖息地的丧失，在驱使这些温和的巨人走向死亡。"}},faq={{q="为什么海龟会在黑海岸搁浅？",a="具体原因对暗夜精灵来说仍然是个谜。历史上，海龟曾在世界之树诺达希尔下的水域中茁壮成长。在第三次战争中诺达希尔遭到破坏以及泰达希尔升起之后，它们的数据急剧下降，而且许多海龟似乎在黑海岸的浅滩上选择了自我了断。",al={"为什么海龟在这里死亡","黑海岸海龟之谜","为什么会搁浅"}},{q="温尼斯·布莱葛是谁？",a="温尼斯·布莱葛是一位驻扎在奥伯丁的暗夜精灵学者，也是Temple of the Moon的代表。她的任务是对冲上岸的海洋生物进行编目和研究，以揭示为什么黑海岸的野生动物正在遭受苦难。",al={"温尼斯是谁","去哪里上交海龟遗骸","奥伯丁研究员"}},{q="为什么鱼人聚集在海龟残骸周围？",a="当地的灰雾鱼人是机会主义者，它们会搜寻这些巨大的尸体以获取食物和材料。它们经常直接在搁浅的海龟和海洋生物旁边建立海岸聚居地，将尸体剥食干净。",al={"为什么鱼人在海龟身上","灰雾拾荒者","沙滩上的鱼人营地"}},{q="这些海龟与诺达希尔有什么联系？",a="根据暗夜精灵的说法，海龟曾经在海加尔山底部和世界之树诺达希尔周围清澈的水域中常见且活跃。诺达希尔遭受的毁灭性打击严重破坏了自然平衡，此后这些生物的目击记录大幅减少。",al={"诺达希尔的联系","海加尔山海龟","海加尔山与海龟的联系"}},{q="泰达希尔的出现与它们的数量减少有关吗？",a="祭司们注意到，自泰达希尔生长以来，海龟出现的数量越来越少。这座新的世界之树是否改变了沿岸洋流，破坏了它们的迁徙路线，或者携带了某种影响海洋生物的不自然光环，是Temple of the Moon目前正在积极研究的课题。",al={"泰达希尔对海龟的影响","为什么泰达希尔改变了海龟"}},{q="黑海岸还有其他搁浅的生物吗？",a="是的。黑海岸漫长的海岸线上有许多搁浅的海洋生物和海龟。每一具尸体都提供了独特的骨骼和组织样本，温尼斯·布莱葛利用这些样本来拼凑出黑海岸正在发生的这场更大规模的生态灾难。",al={"更多搁浅任务","其他搁浅的海龟","搁浅的海洋生物"}}},fx={ad0e3c15={q="温尼斯·布莱葛为什么想要海龟的残骸？",a="温尼斯·布莱葛代表奥伯丁的月神殿研究这些残骸。海龟曾经繁盛于海加尔山和诺达希尔山脚一带，但自从泰达希尔种下之后，它们的数量便急剧减少，被冲上黑海岸的尸体也开始不断增多。她收集这些尚可利用的样本，希望通过生物学研究揭示这些生物为何走向灭亡。",al={"为什么收集海龟残骸","温尼斯为什么要海龟骨头","海龟残骸的用途"}}},fp="18,182,17.271.0,16.493.0,53.307.0,29.202.0,51.192.0,52.235.0,55.255.0,53.230.0"}
P.entries["quest:4733"] = {n="搁浅的海洋生物",s="沿着暮光海岸的岩石小湾，一具巨大的长尾鲨骸骨搁浅在海浪之中。它的体型远超当地已知的任何生物，其突然死亡并搁浅，是困扰黑海岸暗夜精灵的一系列令人担忧的深海异常现象的一部分。",h="沿着暮光海岸的岩石小湾，一具巨大的长尾鲨骸骨搁浅在海浪之中。它的体型远超当地已知的任何生物，其突然死亡并搁浅，是困扰黑海岸暗夜精灵的一系列令人担忧的深海异常现象的一部分。",kw={"奥伯丁","搁浅的海洋生物","黑海岸","温尼斯·布莱葛","海洋生物的骸骨","temple of the moon","长尾鲨","暮光海岸"},ang={["class:Druid"]="顶级海洋捕食者的搁浅是生态系统陷入困境的一个明显迹象，这与塞纳里奥议会在整个黑海岸的广泛担忧密切相关。",["class:Priest"]="温尼斯·布莱葛在月神殿的主持下进行她的研究，寻求通过对海洋平衡进行切实的科学探究来获得平衡与神圣的启示。",["race:NightElf"]="泰达希尔附近海洋生物莫名其妙的减少和搁浅让卡多雷感到不安，他们寄希望于艾露恩和月神殿来解读这些黑暗的预兆。"},sec={{t="搁浅的巨人",b="黑海岸南部的暮光海岸上经常散落着漂流木和海洋残骸，但这个小湾里有着更引人注目的东西：一具巨大的长尾鲨残骸。尽管食腐动物和潮汐已经开始将它肢解，但它巨大的骨架远超在这些沿海浅滩中发现的任何普通捕食者。它显然是这些水域的外来者，要么是因为非自然的疾病、迷失方向，要么是因为隐秘之海深处的某种干扰而被冲上了岩石。"},{t="月神殿的守望",b="在奥伯丁，代表Temple of the Moon的女祭司们对这些冲上岸的死去的巨兽产生了浓厚的兴趣。温尼斯·布莱葛负责监督海洋生物骸骨的收集工作，以确定是什么导致了这些深海捕食者死亡。虽然过去曾在泰达希尔的根部附近发现过巨大的长尾鲨，但它们的数量一直在稳步下降，这让女祭司们担心卡利姆多北海岸外的脆弱海洋平衡正在瓦解。"}},faq={{q="这具搁浅的尸体是什么野兽？",a="这是一具巨大的长尾鲨的骨架，一种掠食性海洋野兽。它的体型是黑海岸沿岸常见的长尾鲨的数倍，因此它出现在这里是非常反常的。",al={"搁浅的海洋生物是什么","黑海岸的巨大长尾鲨","搁浅的怪物尸体"}},{q="这种生物最初来自哪里？",a="女祭司温尼斯·布莱葛指出，虽然过去已知这种体型的生物会在泰达希尔附近的水域出没，但它们的种群数量一直在稳定下降。它并非黑海岸附近浅滩的原生生物。",al={"长尾鲨住在哪里","长尾鲨的起源"}},{q="月神殿为什么要研究这些尸体？",a="月神殿试图了解困扰黑海岸的广泛搁浅现象。通过检查骨骼和遗骸，女祭司们希望确定是腐化、疾病还是外部力量导致这些深海野兽冲上陆地。",al={"为什么温尼斯想要骨头","月神殿的海洋生物","为什么要研究搁浅动物"}},{q="应该把骨头送到哪里？",a="海洋生物的骸骨被送往奥伯丁港口城镇的暗夜精灵研究员温尼斯·布莱葛那里。",al={"在哪里上交海洋生物的骸骨","谁负责接收长尾鲨骨头"}},{q="这具尸体位于海岸的什么地方？",a="这具尸体位于黑海岸南部海岸线上的暮光海岸的一处岩石小湾中。",al={"搁浅的生物在哪里","黑海岸的长尾鲨位置","暮光海岸的骸骨"}},{q="黑海岸还有其他搁浅的生物吗？",a="是的。多种不同的海洋野兽和巨兽都冲上了黑海岸的整个海岸线，这促使奥伯丁的研究人员展开了持续的调查。",al={"其他搁浅动物","搁浅的海洋生物任务线"}}},fp="20,195,19.420.0,18.386.1,43.158.0,45.202.0,55.260.0,34.105.0,43.87.0,59.141.0"}
P.entries["quest:4736"] = {n="寻找梅纳拉·沃伦德",s="这个任务指引有前途的联盟术士跨越重洋来到干旱的贫瘠之地，寻找梅纳拉·沃伦德。梅纳拉在位于棘齿城上方斯坦哈德·法尔杉的塔楼中行事，她为经验丰富的术士提供了制作专业工具和服装的机会，以加强他们对恶魔力量的控制。",h="这个任务指引有前途的联盟术士跨越重洋来到干旱的贫瘠之地，寻找梅纳拉·沃伦德。梅纳拉在位于棘齿城上方斯坦哈德·法尔杉的塔楼中行事，她为经验丰富的术士提供了制作专业工具和服装的机会，以加强他们对恶魔力量的控制。",kw={"石南草","魔化金线血袍","铁炉堡","梅纳拉·沃伦德","棘齿城","斯坦哈德·法尔杉","贫瘠之地","术士"},ang={["class:Warlock"]="这趟旅程代表了迈向高级法术的必经之路，直接通向术士魔化金线血袍的制作。",["faction:Alliance"]="深入贫瘠之地需要穿越敌对领土，并依靠棘齿城脆弱的中立性来进入斯坦哈德的塔楼。",["race:Gnome"]="那些在奥术和邪能腐蚀面前保持谨慎克制的侏儒术士发现，梅纳拉比起纯粹的理论纸上谈兵，更看重实际的控制力。",["race:Human"]="习惯于暴风城和铁炉堡隐藏教派的人类修行者，必须适应棘齿城隐蔽峰顶相对开放的环境。"},sec={{t="来自铁炉堡的召唤",b="石南草是潜伏在铁炉堡阴暗角落里的同僚，他能识别出哪些术士在不屈服于腐蚀的情况下超越了基础恶魔学。他没有将学生关在山中，而是指引他们前往卡利姆多，赞扬他们的纪律性，并敦促他们向一位在实践邪能魔法方面更为精湛的工匠寻求指导。"},{t="棘齿城上方的飞地",b="在俯瞰地精港口棘齿城的悬崖上，矗立着斯坦哈德·法尔杉的孤塔。在一个对黑暗法术深感怀疑的世界里，邪能的修行者往往会抛弃种族和政治界限以求生存。梅纳拉·沃伦德正是出于这个原因留在了斯坦哈德的避难所，与各种势力的术士合作，以确保他们危险的技艺保持精进，并确保召唤出的恶魔被牢牢束缚。"}},faq={{q="谁开启了“寻找梅纳拉·沃伦德”这个任务？",a="该任务由石南草提供，他在铁炉堡的阴暗地带活动，专门服务于那些纪律达到一定程度的联盟术士。",al={"任务发布者","谁发布任务","石南草位置"}},{q="在哪里可以找到梅纳拉·沃伦德？",a="梅纳拉·沃伦德居住在位于贫瘠之地的斯坦哈德·法尔杉的塔楼中，该塔楼坐落在直接俯瞰地精港口城市棘齿城的悬崖上。",al={"梅纳拉·沃伦德位置","梅纳拉·沃伦德在哪里","斯坦哈德·法尔杉塔楼位置"}},{q="为什么联盟术士必须前往部落领地？",a="术士出于必要，经常在传统的阵营忠诚之外行动。棘齿城是由热砂港运营的中立港口，而斯坦哈德的塔楼提供了一个隐蔽的避风港，禁忌魔法的修行者可以在这里聚集和研究，远离窥探的目光。",al={"为什么去贫瘠之地","为什么去棘齿城","贫瘠之地对联盟是否危险"}},{q="完成任务后梅纳拉提供什么？",a="与梅纳拉交谈开启了制作强力术士服装的机会，首先是收集制作魔化金线血袍所需的组件的任务。",al={"梅纳拉教什么","任务奖励","梅纳拉之后的后续任务"}},{q="梅纳拉·沃伦德是联盟还是部落？",a="梅纳拉·沃伦德对黑暗艺术的修行者持中立态度，无论他们来自哪里。虽然严厉且刻薄，但她会帮助任何寻求她指导且纪律严明的术士。",al={"梅纳拉阵营","梅纳拉是否友好"}},{q="为什么术士会跨越种族界限聚集在一起？",a="正如梅纳拉所指出的，术士召唤的恶魔实体在反击粗心的召唤者时，不会区分种族。生存和对扭曲虚空的掌控需要共享知识和相互生存，而不是阵营争斗。",al={"术士团结","为什么术士合作"}}},fp="30,219,24.280.0,25.325.0,54.109.0,37.90.0,63.230.0,39.131.0,39.167.0,47.143.0"}
P.entries["quest:4737"] = {n="寻找梅纳拉·沃伦德",s="泽弗洛斯特，一位潜伏在奥格瑞玛的Cleft of Shadow里的愤世嫉俗的术士训练师，指引经验丰富的修行者去贫瘠之地寻找梅纳拉·沃伦德。尽管他对恶魔腐蚀所带来的必然代价发出了严厉的警告，但他还是将雄心勃勃的术士指引向一位能够制作强大奥术法袍的专家导师。",h="泽弗洛斯特，一位潜伏在奥格瑞玛的Cleft of...",kw={"贫瘠之地","血袍","cleft of shadow","邪能魔法","梅纳拉·沃伦德","棘齿城","术士长袍","泽弗洛斯特"},ang={["class:Warlock"]="这个任务代表了部落术士的一个关键通过仪式，指引他们在梅纳拉·沃伦德的指导下组装他们自己标志性的魔化金线血袍。",["faction:Horde"]="部落术士必须不断应对传统萨满和战士的蔑视，只能在奥格瑞玛的Cleft of Shadow或棘齿城附近的中立地带等隐蔽角落寻找栖身之所。"},sec={{t="阴影中的警告",b="在奥格瑞玛的Cleft of Shadow深处，术士们在一种不安的宽容面纱下活动。泽弗洛斯特是黑魔法导师中更为尖酸刻薄的一位，总是嘲笑那些渴望掌握力量的雄心勃勃的学徒。在他眼中，任何深入钻研邪能魔法的人都只是在加速奔向自己的奴役之路。他坚称，恶魔成瘾彻底控制修行者只是时间问题，甚至会让最自律的学者也沦为扭曲虚空的奴隶。"},{t="前往棘齿城的道路",b="尽管泽弗洛斯特对此表示蔑视，但他承认其他修行者并不认同他那悲观的看法。关于梅纳拉·沃伦德的消息已经传到了奥格瑞玛，这是一位驻扎在俯瞰中立地精港口棘齿城的悬崖上的熟练术士。梅纳拉正在寻找有前途的弟子，以协助制作专门用于驾驭他们奥术力量的工具。对于渴望进一步提升技艺的术士来说，这次召唤标志着锻造传说中的魔化金线血袍的开始。"},{t="务实的同伴",b="在棘齿城上方的高处找到梅纳拉之后，术士社会的本质变得显而易见。梅纳拉指出，术士们必须抛开种族和文化的竞争，互相支持，因为他们与之交易的恶魔并不存在偏见，也不会对任何动摇的人表现出怜悯。分享专业知识和制作防护法袍并非出于高尚的慈善，而是为了在他们所束缚的敌对实体手中生存下去的实际需要。"}},faq={{q="泽弗洛斯特是谁？",a="泽弗洛斯特是一位居住在奥格瑞玛下方Cleft of Shadow的兽人术士训练师。他对追求邪能力量持极度怀疑的态度，认为所有雄心勃勃的术士都是注定要成为恶魔腐蚀奴隶的傻瓜。",al={"泽弗洛斯特","泽弗洛斯特背景故事","谁开启了寻找梅纳拉·沃伦德的任务"}},{q="梅纳拉·沃伦德是谁？",a="梅纳拉·沃伦德是一位造诣深厚的术士，居住在俯瞰地精港口棘齿城的贫瘠之地悬崖上。她担任新晋术士的导师，帮助他们收集稀有试剂来制作强力的仪式法袍。",al={"梅纳拉·沃伦德","梅纳拉·沃伦德在哪里","梅纳拉是谁"}},{q="为什么泽弗洛斯特认为所有术士都是傻瓜？",a="泽弗洛斯特认为，邪能魔法不可避免地会腐蚀并奴役任何试图掌握它的人。在他看来，没有修行者有足够的意志力来避免成瘾，而追求更强大的力量只会加速他们的毁灭。",al={"泽弗洛斯特关于腐蚀的观点","为什么泽弗洛斯特警告我"}},{q="在哪里可以找到梅纳拉·沃伦德？",a="梅纳拉驻扎在贫瘠之地，位于俯瞰沿海港口棘齿城的高山上。术士们必须向东穿过干旱的草原才能到达她所在的营地。",al={"梅纳拉的位置","寻找梅纳拉·沃伦德"}},{q="为什么来自不同种族的术士会合作？",a="正如梅纳拉所解释的那样，术士召唤的恶魔力量对任何未能控制它们的人都会表现出不加区别的残酷恶意。由于生存依赖于绝对的精准，术士们经常跨越文化界限分享知识和工具。",al={"术士的团结","为什么术士要联合起来"}},{q="找到梅纳拉·沃伦德之后会发生什么？",a="梅纳拉·沃伦德会立即招募术士在艾泽拉斯各地收集奇异而强大的材料，以制作与邪能共鸣的防护服装——魔化金线血袍。",al={"梅纳拉之后的任务","梅纳拉想要什么"}}},fp="30,213,23.433.0,19.410.0,22.413.0,15.194.0,25.192.0,46.198.0,37.150.0,51.199.0,45.162.0"}
P.entries["quest:4738"] = {n="寻找梅纳拉·沃伦德",s="一位寻求制作强大法袍的联盟术士在法师区的秘密修行者的指引下，必须横跨无尽之海去寻找梅纳拉·沃伦德。梅纳拉坐镇于中立港口棘齿城上方的高塔中，不分阵营地向黑暗施法者传授契约与神器制作等危险技艺。",h="一位寻求制作强大法袍的联盟术士在法师区的秘密修行者的指引下，必须横跨无尽之海去寻找梅纳拉·沃伦德。梅纳拉坐镇于中立港口棘齿城上方的高塔中，不分阵营地向黑暗施法者传授契约与神器制作等危险技艺。",kw={"血袍","德米赛特·克劳斯","魔化金线血袍","梅纳拉·沃伦德","棘齿城","slaughtered lamb","贫瘠之地","术士任务"},ang={["class:Warlock"]="这场成人礼将暴风城隐秘的巢穴与卡利姆多广阔的前线连接了起来，它教会了我们对恶魔力量的追求超越了凡人的阵营之争。",["faction:Alliance"]="踏上这段旅程迫使联盟施法者离开他们熟悉的东部领土，进入贫瘠之地那未经驯服的荒野中寻找专业的指导。"},sec={{t="不情愿的推荐",b="在暴风城Slaughtered Lamb下方的黑暗地穴中，术士训练师德米赛特·克劳斯以其严苛且毫不留情的标准而闻名。当一位有抱负的术士达到可以编织强大力量物品的门槛时，德米赛特很少会认为他们真的准备好了。尽管如此，隐秘结社中的高层还是下令让学生继续进修，将他们派往远离首都安逸环境的地方以证明自己的实力。"},{t="棘齿城上方的高塔",b="目的地是贫瘠之地中俯瞰地精港口棘齿城的荒凉山丘。在那里，梅纳拉·沃伦德在一座石塔中经营着她的实验室。梅纳拉远离了暴风城的严苛法律和奥格瑞玛的监视目光，不分种族或政治立场接纳学徒，因为她深知术士所面对的恶魔和邪恶实体对每一个凡人灵魂都怀有同样的恶意。"}},faq={{q="为什么联盟术士会被派往贫瘠之地？",a="联盟中很少有修行者拥有足够的奥术知识或自由去制作诸如魔化金线血袍之类的高级邪能法袍。梅纳拉·沃伦德在棘齿城上方的一座僻静塔楼中开展工作，这里是一处罕见的避难所，所有背景的术士都能在这里学习超出首都卫兵和审判官掌控范围的危险技艺。",al={"为什么选择棘齿城","为什么要前往贫瘠之地","梅纳拉·沃伦德的背景"}},{q="德米赛特·克劳斯是谁？",a="德米赛特·克劳斯是一位资深的人类术士训练师，在暴风城法师区的Slaughtered Lamb下方进行秘密行动。她行事严厉，极力保护那些危险的知识，只有在接到指导术士结社的隐秘力量的命令时，她才会将学生派往梅纳拉处。",al={"德米赛特·克劳斯背景故事","谁开启了寻找梅纳拉任务"}},{q="梅纳拉·沃伦德关心联盟与部落的冲突吗？",a="不。梅纳拉公开表示，术士必须摒弃种族和阵营的界限。他们召唤出的恶魔和位面力量对所有犯错的人展现出同样的残暴，这使得相互生存和共同研习黑暗技艺比凡人的战争重要得多。",al={"梅纳拉是部落还是联盟","梅纳拉痛恨联盟吗"}},{q="梅纳拉·沃伦德准备让术士制作什么物品？",a="找到梅纳拉是锻造奥术法袍并将其转化为传说中的魔化金线血袍的第一步，这是一件注入了稀有试剂、精良裁缝工艺和被束缚的恶魔能量的强力装备。",al={"梅纳拉传授什么","这是为哪件法袍准备的","血袍任务"}},{q="前往棘齿城对联盟术士来说危险吗？",a="贫瘠之地主要是部落领土，遍布着敌对的野生生物、半人马和兽人巡逻队。然而，棘齿城本身是由热砂港运营的中立港口，如果联盟旅行者沿着海岸走或者从藏宝海湾乘船安全抵达，梅纳拉的塔楼还是可以进入的。",al={"棘齿城有多危险","贫瘠之地安全吗"}},{q="为什么德米赛特·克劳斯认为玩家还没准备好？",a="德米赛特认为，对于尚未经过考验的新手来说，制作注入邪能的强力物品是鲁莽的行为。术士神器需要极度的自律；在绑定试剂或恶魔精华时哪怕出现微小的错误，都可能摧毁施法者，或者将恐怖的生物释放到世界上。",al={"为什么德米赛特怀疑玩家","德米赛特的警告"}}},fp="30,172,26.297.0,23.308.0,59.275.0,24.268.0,65.207.0,61.192.0,58.261.0,55.252.0"}
P.entries["quest:4739"] = {n="寻找梅纳拉·沃伦德",s="这个任务将让部落术士从幽暗城阴暗的区划出发，横跨大海前往棘齿城。在俯瞰港口的山丘之上，导师梅纳拉·沃伦德正在等待着那些准备好制作强大奥术服饰的施法者。",h="这个任务将让部落术士从幽暗城阴暗的区划出发，横跨大海前往棘齿城。在俯瞰港口的山丘之上，导师梅纳拉·沃伦德正在等待着那些准备好制作强大奥术服饰的施法者。",kw={"贫瘠之地","魔化金线血袍","卡尔·噬灵","梅纳拉·沃伦德","棘齿城","斯坦哈德的塔","幽暗城","术士"},ang={["class:Warlock"]="这段旅程标志着术士进入了高级修行阶段，并开启了制作与虚空能量相协调的专业法袍的道路。",["faction:Horde"]="该任务展示了部落中分散的术士派系是如何维持一个横跨洛丹伦和卡利姆多的地下网络的。",["race:Undead"]="从幽暗城阴森的深处开始，被遗忘者术士必须远行至卡利姆多阳光暴晒的荒野，以继续他们神秘的学问。"},sec={{t="来自暗影的召唤",b="在被遗忘者的首都幽暗城，卡尔·噬灵观察着术士们日益增长的天赋。他意识到修行者已经超越了基础的诅咒和小鬼奴役，因此敦促他们前往无尽之海彼岸寻求专业指导。恶魔控制的技艺不容迟疑，只有技术精湛的导师才能确保术士在面对虚空波动能量时能够存活下来。"},{t="棘齿城上的高塔",b="在俯瞰地精港口棘齿城的一处高崖上，矗立着斯坦哈德·法尔杉的塔楼。远离了城市卫兵警惕的目光，像梅纳拉·沃伦德这样的修行者聚集于此，指导年轻的学徒。不同背景的术士在严酷的修行现实下，抛开了部落和政治上的仇恨：如果意志动摇，他们所契约的恶魔将会毫不留情地吞噬人类、兽人或被遗忘者。"}},faq={{q="谁发放这个任务？",a="卡尔·噬灵在幽暗城发放此任务。他能识别出术士何时拥有了足够的力量和经验，从而从梅纳拉·沃伦德的高级教导中获益。",al={"任务发放者","如何接取任务","卡尔·噬灵位置"}},{q="在哪里可以找到梅纳拉·沃伦德？",a="梅纳拉居住在贫瘠之地，她与斯坦哈德·法尔杉一起，在俯瞰棘齿城港口的石塔中修行。",al={"梅纳拉在哪里","寻找梅纳拉·沃伦德","梅纳拉位置"}},{q="为什么部落术士必须长途跋涉前往贫瘠之地？",a="恶魔艺术是在隐秘的区域中练习的，以防止外界干扰。梅纳拉·沃伦德在斯坦哈德的塔中进行专业培训和长袍制作，在这里，所有背景的术士都能不受公民或宗教当局的干涉进行学习。",al={"为什么是棘齿城","为什么要前往贫瘠之地","为什么要去找梅纳拉"}},{q="找到梅纳拉·沃伦德之后会发生什么？",a="梅纳拉会认可你的训练，并提议引导你制作魔化金线血袍，由此开启一条在艾泽拉斯各地收集稀有且危险材料的任务线。",al={"任务后续","梅纳拉给予我什么","下一个任务"}},{q="为什么不同种族的术士要分享知识？",a="正如梅纳拉所解释的那样，恶魔不讲慈悲；如果召唤者无法控制它们，它们不会因为种族而区别对待。实际的生存需求迫使术士们分享技术，以防范共同的灾难。",al={"术士合作","为什么术士要合作","梅纳拉术士背景"}},{q="谁是斯坦哈德·法尔杉？",a="斯坦哈德·法尔杉是一位大师级术士，他维护着棘齿城上方那座偏远的石塔，为那些寻求在远离主要阵营据点的地方掌握恶魔艺术的修行者提供避难所和教学中心。",al={"斯坦哈德之塔","棘齿城的塔属于谁","斯坦哈德·法尔杉"}}},fp="30,157,26.308.0,23.353.0,22.132.0,37.93.0,58.229.0,46.178.0,51.142.0,22.174.0"}
P.entries["quest:474"] = {n="击败纳克罗什",s="击败奈克罗什标志着联盟针对湿地龙喉氏族的战役达到了高潮。在他们的攻城器械被破坏后，冒险者们受命直接击杀酋长奈克罗什，以确保米奈希尔港的安全。将他的人头带回给斯托菲队长，将彻底粉碎兽人对这座沿海港口的威胁。",h="击败奈克罗什标志着联盟针对湿地龙喉氏族的战役达到了高潮。在他们的攻城器械被破坏后，冒险者们受命直接击杀酋长奈克罗什，以确保米奈希尔港的安全。将他的人头带回给斯托菲队长，将彻底粉碎兽人对这座沿海港口的威胁。",kw={"斯托菲队长","投石车","酋长","龙喉氏族","铁炉堡","米奈希尔港","奈克罗什","湿地"},ang={["class:Warrior"]="在奈克罗什酋长自己设防的战争营地中面对他，是对抗沼泽最凶猛的兽人指挥官之一的终极考验，是对武力的终极测试。",["faction:Alliance"]="保卫米奈希尔港保护了连接铁炉堡、暴风城与卡利姆多及北部海域的主要海军动脉。",["race:Dwarf"]="对于卡兹莫丹的矮人来说，龙喉氏族是他们祖先疆界上的一道挥之不去的伤疤。消灭奈克罗什直接保障了矮人的道路和铁炉堡的西海贸易。"},sec={{t="斩首龙喉氏族",b="龙喉兽人长期以来一直祸害着卡兹莫丹的沼泽地，他们盘踞在坚固的营地中，威胁着米奈希尔港的海运航线。在发现并烧毁了氏族的投石车后，沼泽的防御者们直捣蛇头。当地战团的指挥官，酋长奈克罗什，成了打破围城的最后一道障碍。他的死让残余的龙喉掠夺者失去了战术协调能力。"},{t="保卫港口",b="将奈克罗什的人头带回米奈希尔港交给斯托菲队长，这标志着铁炉堡守军的一场巨大胜利。失去了重型攻城武器和酋长的龙喉氏族遭受了沉重打击，短期内很难恢复元气。对于这座饱受困扰的港口而言——它是联盟在洛丹伦和卡兹莫丹之间的主要生命线——酋长的倒下确保了码头和商船免受突袭。"}},faq={{q="奈克罗什是谁？",a="奈克罗什是统领湿地龙喉氏族残部的冷酷酋长。在联盟冒险者干预之前，他以营地为据点，组织了一场使用攻城投石车对米奈希尔港的预谋袭击。",al={"酋长奈克罗什","奈克罗什是谁","奈克罗什 湿地"}},{q="为什么米奈希尔港想要奈克罗什死？",a="奈克罗什对米奈希尔港构成了直接的生存威胁。在他的指挥下，龙喉氏族建造了战争投石车，意图炮轰该港口，并瘫痪连接卡兹莫丹与其他联盟领地的关键航运线路。",al={"为什么要杀奈克罗什","斯托菲队长的动机"}},{q="是谁下令杀死奈克罗什的？",a="这道命令是在烧毁龙喉投石车后直接下达的。酋长的人头最终被交给了负责监督米奈希尔港防御工作的斯托菲队长。",al={"谁发布了击败奈克罗什任务","在哪里交奈克罗什的头颅"}},{q="奈克罗什被击败后，龙喉氏族会怎么样？",a="随着投石车被毁，酋长被杀，龙喉战团在领导力和士气上遭受了毁灭性打击。虽然仍有散兵游勇在沼泽地出没，但他们针对米奈希尔港的直接攻势已被有效粉碎。",al={"奈克罗什死后的龙喉氏族","湿地兽人会怎样"}},{q="龙喉氏族在湿地做什么？",a="龙喉氏族在第二次战争期间定居在湿地和邻近的格瑞姆巴托高地。部落战败后，叛变的残部滞留在沼泽中，劫掠贸易路线，并对联盟和卡兹莫丹的矮人怀有深仇大恨。",al={"为什么龙喉氏族会在湿地","龙喉氏族湿地背景故事"}},{q="为什么米奈希尔港对联盟如此重要？",a="米奈希尔港是铁炉堡王国在西海岸唯一的各大海港。它是将部队、贸易物资和旅客经由无尽之海运往卡利姆多和向北前往洛丹伦的主要枢纽。",al={"米奈希尔港的重要性","米奈希尔港的战略价值"}}},fp="15,285,26.411.0,19.417.0,16.170.0,44.198.0,33.170.0,62.203.1,49.267.0,50.185.0"}
P.entries["quest:4740"] = {n="通缉：莫克迪普！",s="“通缉：莫克迪普！”是一项联盟悬赏任务，张贴在奥伯丁旅店外的告示板上。村议会寻求除掉莫克迪普，这是一个危险的鱼人首领，他被指控杀害了一名暗夜精灵哨兵，并击沉了黑海岸附近的商船。冒险者必须沿着迷雾笼罩的海岸向南进发，引诱这名袭击者并伸张正义。",h="“通缉：莫克迪普！”是一项联盟悬赏任务，张贴在奥伯丁旅店外的告示板上。村议会寻求除掉莫克迪普，这是一个危险的鱼人首领，他被指控杀害了一名暗夜精灵哨兵，并击沉了黑海岸附近的商船。冒险者必须沿着迷雾笼罩的海岸向南进发，引诱这...",kw={"奥伯丁","黑海岸","戈琳达·纳希恩","灰雾","莫克迪普","鱼人","哨兵","通缉海报"},ang={["faction:Alliance"]="奥伯丁是重要的北部贸易枢纽，因此莫克迪普涉嫌击沉的货船是对卡利姆多联盟后勤的一次沉重打击。",["race:NightElf"]="对于保卫黑海岸的卡多雷来说，击杀莫克迪普不仅为死去的哨兵姐妹报了仇，也保障了奥伯丁码头所提供的脆弱生命线。"},sec={{t="迷雾浅滩的威胁",b="黑海岸沿线的灰雾鱼人通常被认为是个麻烦，但莫克迪普将事态升级为了针对奥伯丁的公开战争。根据张贴在镇旅店外的通缉令，这只凶猛的野兽至少对杀害一名暗夜精灵哨兵负有直接责任，并被怀疑破坏或击沉了近海的两艘货船。面对日益严重的航运损失和沿海袭击，奥伯丁村议会授权发布了公开悬赏，以终结这个狂暴的鱼人首领。"},{t="小屋的伏击",b="莫克迪普并不会在开阔的海岸线上漫无目的地游荡。他潜伏在南部海岸附近，围绕着篝火的一群鱼人小屋中。任何擅自闯入营地的人都会触发有组织的防御：一波波的灰雾海岸奔行者和岸行者会从海浪中涌出，保护他们的定居点，随后莫克迪普本人会带着他的先锋队出现，击杀入侵者。"},{t="为逝者伸张正义",b="带着莫克迪普死亡的证明回到奥伯丁，对哨兵来说完成了残酷的必要之举。哨兵戈琳达·纳希恩代表议会负责处理悬赏报酬。通过摧毁灰雾氏族的领导层，穿过黑海岸迷雾的旅客和航道免受了沿海破坏之苦。"}},faq={{q="我在哪里可以接到莫克迪普的悬赏任务？",a="你可以在黑海岸奥伯丁中心旅店外张贴的通缉令上接受该任务。",al={"通缉莫克迪普起始位置","莫克迪普任务起始","奥伯丁通缉海报"}},{q="为什么奥伯丁议会要悬赏莫克迪普？",a="莫克迪普是一个特别暴力的鱼人，至少杀害了一名暗夜精灵哨兵，并被怀疑在黑海岸附近海域击沉了两艘货船。",al={"为什么杀莫克迪普","莫克迪普做了什么","莫克迪普的罪行"}},{q="我在哪里可以找到莫克迪普？",a="莫克迪普位于奥伯丁以南很远的海滩边，守卫着三座围绕中央篝火而建的鱼人小屋。",al={"莫克迪普位置","莫克迪普在哪里","莫克迪普营地"}},{q="为什么我到达鱼人营地时莫克迪普不在那儿？",a="莫克迪普不会站在开阔地带。踏入篝火附近的小屋之间会触发从海洋中涌出的波浪状灰雾鱼人。当最初的防御者被击杀后，莫克迪普会随最后一波出现。",al={"莫克迪普不在","莫克迪普刷新","如何召唤莫克迪普"}},{q="莫克迪普死后该向谁交任务？",a="向在奥伯丁执勤的哨兵戈琳达·纳希恩报告莫克迪普的死讯。",al={"莫克迪普向谁交任务","莫克迪普任务交付","戈琳达·纳希恩位置"}},{q="这个营地的鱼人和其他黑海岸的鱼人有什么不同吗？",a="莫克迪普指挥着灰雾鱼人部落的成员，包括海岸侦察兵和战士，他们以协同的波次进行工作，以保卫他们的海滨营地。",al={"灰雾鱼人","莫克迪普部落","莫克迪普带了什么鱼人"}}},fp="17,209,36.391.0,22.282.0,22.243.0,42.74.0,59.156.0,26.90.0,52.195.0,45.74.0,71.135.0"}
P.entries["quest:475"] = {n="烦恼之风",s="“不安的微风”是泰达希尔的阿斯瑞达斯·熊皮给予的一项早期任务，要求调查星风村的报告缺失情况。伟大的典狱官盖洛拉斯·塔文斯伦就在附近守护着那些正在冬眠的猛禽德鲁伊，他突然的沉默预示着某种不自然的危险正在向这棵世界之树蔓延。",h="“不安的微风”是泰达希尔的阿斯瑞达斯·熊皮给予的一项早期任务，要求调查星风村的报告缺失情况。伟大的典狱官盖洛拉斯·塔文斯伦就在附近守护着那些正在冬眠的猛禽德鲁伊，他突然的沉默预示着某种不自然的危险正在向这棵世界之树蔓延。",kw={"阿斯瑞达斯·熊皮","班奈希尔","猛禽德鲁伊","翡翠梦境","盖洛拉斯·塔文斯伦","星风村","泰达希尔","不安的微风","伊瑟拉"},ang={["class:Druid"]="德鲁伊们对班奈希尔兽穴以及与伊瑟拉缔结契约的沉睡者怀有深切的敬意，因此任何对其守护者的干扰都属于迫在眉睫的个人事务。",["race:NightElf"]="对于暗夜精灵而言，守护猛禽德鲁伊的神圣休憩对于维护他们在泰达希尔这片新家园中脆弱的平衡至关重要。"},sec={{t="沉默的守望者",b="在泰达希尔的林间定居点，信息的传递通常既迅速又有序。阿斯瑞达斯·熊皮倚赖着盖洛拉斯·塔文斯伦传来的消息，这位伟大的典狱官受托守护着正在班奈希尔兽穴中休憩的猛禽德鲁伊。这些沉睡的德鲁伊与翡翠梦境中的伊瑟拉维持着神圣的契约，使他们的避难所对于这棵年轻的世界之树的精神平衡至关重要。当东方的报告中断时，一种令人不安的预感便在森林冠盖间弥漫开来。"},{t="星风村的不安",b="阿斯瑞达斯请求旅行者前往东方的森林，亲自去星风村寻找盖洛拉斯。信使的缺失绝非仅仅是因为疏忽，污秽的腐化和狂躁的野生动物已经开始在荒野中骚动。找到盖洛拉斯后就会发现，阿斯瑞达斯的直觉是正确的：麻烦已经降临到村庄，危及了附近兽穴的安全。"}},faq={{q="阿斯瑞达斯·熊皮是谁？",a="阿斯瑞达斯·熊皮是泰达希尔的一位杰出的暗夜精灵监工，他负责追踪森林的状况，并确保他沉睡中的德鲁伊同胞的避难所不被打扰。",al={"阿斯瑞达斯·熊皮","阿斯瑞达斯背景","任务发布者阿斯瑞达斯"}},{q="盖洛拉斯·塔文斯伦是谁？",a="盖洛拉斯·塔文斯伦是被选中的伟大典狱官，负责保护附近班奈希尔兽穴中沉睡的猛禽德鲁伊，在他们的灵魂漫游于翡翠梦境时确保他们的安全。",al={"盖洛拉斯·塔文斯伦","伟大典狱官盖洛拉斯","盖洛拉斯是谁"}},{q="班奈希尔兽穴是什么？",a="班奈希尔兽穴是泰达希尔内的一处神圣地下洞穴，暗夜精灵德鲁伊会在此进行长时间的睡眠，以与伊瑟拉沟通并履行他们在翡翠梦境中的契约。",al={"班奈希尔兽穴","班奈希尔","班奈希尔是什么"}},{q="为什么盖洛拉斯会失去联系？",a="盖洛拉斯无法传回常规报告，是因为突如其来的危险和腐化开始威胁星风村及周围的森林，使他陷入了维持局面控制的苦战中。",al={"为什么盖洛拉斯沉默了","盖洛拉斯发生了什么","星风村的麻烦"}},{q="这个任务接下来会导向何处？",a="在星风村找到盖洛拉斯·塔文斯伦后，他会让你带着关于附近树皮豺狼人受不自然腐化影响的严峻消息，回到多兰纳尔找阿斯瑞达斯·熊皮。",al={"后续任务","不安的微风后续","不安的微风之后是什么"}},{q="任务中提到的与伊瑟拉的契约是什么？",a="暗夜精灵德鲁伊会进入漫长的冥想睡眠，与绿龙军团和伊瑟拉一同漫步在翡翠梦境中，作为自然原始蓝图的守护者。",al={"与伊瑟拉的契约","伊瑟拉德鲁伊契约","猛禽德鲁伊的睡眠"}}},fp="18,245,16.387.0,20.281.1,27.162.0,27.169.0,33.181.0,32.171.0,32.210.1,51.174.0"}
P.entries["quest:476"] = {n="瘤背熊怪的堕落",s="“Gnarlpine Corruption”是一项在泰达希尔的紧急信使任务，代表受伤的伟大典狱官盖洛拉斯·塔文斯伦发出。它警告多兰纳尔的暗夜精灵领导层，Gnarlpine熊怪已经屈服于恶魔的腐化，并占领了星风村。这份报告为军事和德鲁伊介入铺平了道路，以防止这种污秽蔓延到班奈希尔兽穴中沉睡的德鲁伊身上。",h="“Gnarlpine...",kw={"阿斯瑞达斯·熊皮","班奈希尔兽穴","多兰纳尔","魔苔","熊怪","盖洛拉斯·塔文斯伦","gnarlpine腐化","星风村","殴打者乌萨尔"},ang={["class:Druid"]="对班奈希尔兽穴的威胁对塞纳里奥议会而言是一场生存危机，因为沉睡的同胞们在腐化的Gnarlpine部族面前毫无防备。",["race:NightElf"]="星风村的陷落是一个悲惨的冲击，证明了即使是新生的世界之树也已然容易受到暗夜精灵费尽心机想要根除的恶魔污秽的侵袭。"},sec={{t="绝望的警告",b="盖洛拉斯·塔文斯伦在遭到曾经的盟友伏击后，重伤倒在星风村的废墟旁。Gnarlpine熊怪一直被视为和平的邻居和荒野的守护者，如今却突然变得狂暴起来。由于伤势过重无法亲自将消息带回文明世界，盖洛拉斯委托一位冒险者迅速将消息传达给多兰纳尔的阿斯瑞达斯·熊皮，以免这种疯狂在泰达希尔的枝干间进一步蔓延。"},{t="魔苔的祸害",b="传达给阿斯瑞达斯的报告揭露了一个令人不安的事实：熊怪们并没有仅仅变得焦躁不安，而是正在积极地遭受邪能魔法的侵害。他们的酋长，殴打者乌萨尔（Ursal the Mauler），利用了在世界之树上滋生的被腐化的魔苔，驱使他的族人陷入疯狂的暴力中。这一发现不仅威胁到了星风村这样的定居点，更直接危及到了附近的班奈希尔兽穴，那里沉睡的德鲁伊对这个精神失常的部族毫无防备。"}},faq={{q="星风村发生了什么？",a="星风村在被邪能魔法腐化后，遭到了Gnarlpine熊怪的劫掠和占领。突如其来的伏击驱逐或屠杀了那里的居民，导致盖洛拉斯·塔文斯伦受困并身负重伤。",al={"为什么星风村被废弃","星风村遇袭","谁摧毁了星风村"}},{q="为什么Gnarlpine熊怪会变得暴力？",a="他们的酋长，殴打者乌萨尔，开始使用在泰达希尔发现的邪恶的魔苔力量。黑暗的魔法本质驱使这个部族对他们曾经的暗夜精灵盟友发动了无法控制的疯狂暴力袭击。",al={"为什么gnarlpine熊怪疯了","gnarlpine的疯狂","为什么要攻击熊怪"}},{q="盖洛拉斯·塔文斯伦是谁？",a="盖洛拉斯·塔文斯伦是沉睡的利爪德鲁伊的暗夜精灵伟大典狱官，在前往班奈希尔兽穴的途中遭到了Gnarlpine部族的伏击。由于伤势过重无法前往多兰纳尔，他只能依靠旅行者来传递灾难的消息。",al={"盖洛拉斯","受伤的暗夜精灵在星风村"}},{q="阿斯瑞达斯·熊皮是谁？",a="阿斯瑞达斯·熊皮是驻扎在多兰纳尔的一位显赫的暗夜精灵权威。他负责监督区域安全，并协助协调应对针对世界之树及其居民的新兴威胁。",al={"阿斯瑞达斯","多兰纳尔的阿斯瑞达斯·熊皮"}},{q="为什么暗夜精灵担心班奈希尔兽穴？",a="班奈希尔兽穴安置了许多深陷翡翠梦境的德鲁伊。如果狂暴的Gnarlpine熊怪抵达兽穴，沉睡的暗夜精灵将完全无法抵御他们的攻击。",al={"班奈希尔的威胁","为什么班奈希尔兽穴很重要","沉睡德鲁伊的危险"}},{q="什么是魔苔？",a="魔苔是一种出现在泰达希尔的被腐化的有机生长物，被黑暗的恶魔能量所污染。它具有腐化作用，当接触或使用它时，会使当地的野生生物和熊怪陷入疯狂。",al={"什么是魔苔","泰达希尔的魔苔"}}},fp="20,308,19.414.0,23.375.1,36.224.0,47.247.0,27.257.0,27.193.0,59.178.0,17.157.0"}
P.entries["quest:4761"] = {n="桑迪斯·织风",s="桑德里斯·织风者是一个联盟任务，它将德鲁伊特伦希斯对当地熊怪的侦察工作与奥伯丁的市政领导层联系起来。在确认了附近的黑木部落日益增长的侵略性后，冒险者被指引直接向织风者长老报告。这位长老试图了解导致黑暗海岸荒野遭到扭曲的腐蚀的根源。",h="桑德里斯·织风者是一个联盟任务，它将德鲁伊特伦希斯对当地熊怪的侦察工作与奥伯丁的市政领导层联系起来。在确认了附近的黑木部落日益增长的侵略性后，冒险者被指引直接向织风者长老报告。这位长老试图了解导致黑暗海岸荒野遭到扭曲的腐...",kw={"奥伯丁","黑木","壁泉","黑暗海岸","熊怪","特伦希斯","桑德里斯·织风者"},ang={["class:Druid"]="当地熊怪和森林居民的迅速腐化标志着严重的生态失衡，这是塞纳里奥盟友和村长们无法忽视的。",["faction:Alliance"]="确保奥伯丁免受敌对林地部落的侵扰，对于保障联盟补给线以及往返于卡利姆多和泰达希尔之间的旅客的安全至关重要。",["race:NightElf"]="奥伯丁是卡多雷在大陆海岸的主要港口和立足点；将情报带给织风者长老将直接有助于你们的人民保护他们神圣的荒野。"},sec={{t="给长老的报告",b="在你对黑暗海岸受到腐蚀的熊怪营地进行侦察任务后，德鲁伊特伦希斯指引你去找奥伯丁的村长，桑德里斯·织风者。当特伦希斯在野外调查蔓延的腐蚀时，桑德里斯则负责监督定居点的日常福利，并权衡卡多雷所面临的更广泛的精神和环境危机。这份报告为领导层提供了明确的证据，表明熊怪们不仅仅是在保卫领土，而是在一种非自然恶意的侵蚀下不断恶化。"},{t="海岸沿线的腐蚀",b="在收到关于熊怪营地的消息后，桑德里斯确认奥伯丁一段时间以来一直在与当地森林居民日益增长的敌意作斗争。比单纯的侵略更令人担忧的是感染了黑暗海岸土壤、植物和水域的蔓延腐蚀。桑德里斯相信治愈这片土地需要发现这种灾祸的源头，因此他将注意力转向追踪上游的腐蚀，并招募有能力的盟友来调查该地区的水道。"}},faq={{q="桑德里斯·织风者是谁？",a="桑德里斯·织风者担任奥伯丁的长老，作为城镇治理和日常事务的明智管家。他与哨兵和德鲁伊密切合作，以了解并对抗在黑暗海岸蔓延的奇异腐蚀。",al={"桑德里斯·织风者","奥伯丁长老","桑德里斯是谁"}},{q="为什么特伦希斯要让你去找桑德里斯？",a="在侦察了黑木熊怪营地后，特伦希斯确定必须向城镇的市政领导层通报情况。桑德里斯·织风者对于野生动物和熊怪为何陷入疯狂有自己的理论，并需要第一手情报来协调应对措施。",al={"为什么要去找桑德里斯","特伦希斯的报告","奥伯丁的报告"}},{q="黑暗海岸的熊怪发生了什么事？",a="黑暗海岸的本土熊怪变得越来越暴力，屈服于一种正在扭曲森林本身的黑暗腐蚀。它们的敌意并非源于简单的边界纠纷，而是源于毒害这片土地的邪恶腐蚀。",al={"被腐蚀的熊怪","熊怪的敌意","熊怪为何疯狂"}},{q="这项调查接下来会指向哪里？",a="织风者长老怀疑黑暗海岸的水源可能携带了腐烂的源头。他迅速指引冒险者去采集壁泉河的水样，以确定污染源自何处。",al={"下一个任务","桑德里斯之后做什么","壁泉河任务"}}},fp="19,233,21.485.0,26.370.0,27.206.0,40.237.0,47.182.0,40.165.0"}
P.entries["quest:4762"] = {n="壁泉河",s="壁泉河是黑海岸北部的一条主要水道，目前正迅速变得污浊，威胁着奥伯丁的定居点。桑德里斯·织风指派联盟的调查员从河上的瀑布下方采集一份水样，以证实蔓延的腐蚀。桑德里斯怀疑河岸之外存在着更深层次的腐蚀源。",h="壁泉河是黑海岸北部的一条主要水道，目前正迅速变得污浊，威胁着奥伯丁的定居点。桑德里斯·织风指派联盟的调查员从河上的瀑布下方采集一份水样，以证实蔓延的腐蚀。桑德里斯怀疑河岸之外存在着更深层次的腐蚀源。",kw={"奥伯丁","黑木","壁泉","黑海岸","费伍德森林","河流","腐蚀","桑德里斯","瀑布","织风"},ang={["class:Druid"]="对于塞纳里奥议会的德鲁伊来说，眼睁睁看着纯净的林中水域因挥之不去的恶魔腐蚀而变得腐臭，这是要求他们集结起来净化黑海岸受伤自然的号角。",["race:NightElf"]="奥伯丁的生存依赖于黑海岸海岸线的平衡，任由蔓延的腐烂流入薄雾海将危及卡多雷的家园与生计。"},sec={{t="被污染的水道",b="壁泉河从东部高地奔流而下，最终流入奥伯丁以北、薄雾海沿岸的浅滩。近来，河水开始变质，将非自然的腐烂带向这个暗夜精灵定居点。由于担心这些污水会毒害周围的海岸和城镇的水源，桑德里斯·织风派侦察兵顺流而上，从公路桥下的瀑布池中采集样本。"},{t="费伍德的根源",b="虽然当地的黑木熊怪在河边建立了营地，并且表现出严重的躁动迹象，但桑德里斯怀疑他们可能只是在传播某种腐蚀，而真正的根源却在别处。他指认费伍德森林为源头，并预言样本将证实他的怀疑。这片东部的荒芜森林在第三次战争中遭受了创伤。净化河水需要对抗那些被腐蚀的熊怪，并净化这片土地的古老源头。"}},faq={{q="我在哪里采集水样？",a="从奥伯丁向北走，直到抵达薄雾海沿岸的壁泉河入海口。顺着河流向内陆行进至第一道瀑布，也就是那座头顶公路桥的正下方，然后用样本采集器在水池里装满水。",al={"水样在哪里","壁泉河位置","瀑布水池位置"}},{q="为什么壁泉河会变质？",a="桑德里斯怀疑沿着河流栖息的黑木熊怪可能是导致河水变质的原因，但他认为这些熊怪受到的腐蚀有着更深层的根源。他需要一份水样来进行调查。",al={"为什么河流被腐蚀","什么在毒害黑海岸的水","壁泉河污染源"}},{q="桑德里斯·织风是谁？",a="桑德里斯·织风是一位驻扎在奥伯丁的暗夜精灵学者和调查员。他研究着正在黑海岸蔓延的生态衰退现象，并致力于查明该地区腐蚀的起因。",al={"桑德里斯·织风背景","谁发布壁泉河任务"}},{q="是熊怪导致了河水中毒吗？",a="桑德里斯怀疑他们可能在散布腐蚀，但认为他们所受腐蚀的源头更为深远。采集水样正是为了帮助他展开调查。",al={"是熊怪污染了水吗","黑木熊怪的腐蚀"}},{q="这条河对奥伯丁有什么影响？",a="壁泉河在镇子以北汇入薄雾海。沿岸的洋流有可能将腐臭的径流直接带入奥伯丁的海岸线，危及当地的渔业、植物和淡水供应。",al={"对奥伯丁的威胁","为什么奥伯丁关心壁泉河"}},{q="测试完样本后会发生什么？",a="桑德里斯感谢你提供的样本，并准备进一步调查那些被腐蚀的黑木熊怪，希望能找到净化它们身上腐蚀的方法。",al={"壁泉河后续任务","壁泉河之后发生什么"}}},fp="21,246,18.378.0,19.407.1,36.198.0,42.182.1,27.168.0,53.163.1,37.194.0,38.151.1"}
P.entries["quest:4763"] = {n="黑木熊怪的堕落",s="根据在壁泉河的受污染水域中发现的证据，桑德里斯·织风派遣冒险者去切断扼杀黑木部族的黑暗势力。通过用月亮井水净化它们的食物储备，你将引诱它们的恶魔操纵者现身，从而粉碎他对北部营地的控制。",h="根据在壁泉河的受污染水域中发现的证据，桑德里斯·织风派遣冒险者去切断扼杀黑木部族的黑暗势力。通过用月亮井水净化它们的食物储备，你将引诱它们的恶魔操纵者现身，从而粉碎他对北部营地的控制。",kw={"奥伯丁","黑木","黑海岸","熊怪","月亮井","萨特","堕落护符","桑德里斯·织风","萨布拉克斯"},ang={["class:Druid"]="恢复平衡需要斩草除根。看到萨特利用邪能护符来扭曲原始的林地生物，塞纳里奥议会将对抗萨布拉克斯视为当务之急。",["class:Priest"]="通过月亮井水引导艾露恩纯净且恢复性的恩典，与萨特所使用的腐化暗影和邪能魔法形成了鲜明对比。",["race:NightElf"]="熊怪曾是卡多雷的长久盟友；看着它们沦为宿敌萨特的傀儡是一场苦涩的悲剧，暗夜精灵们急于纠正这一切。"},sec={{t="隐秘的主宰",b="奥伯丁的暗夜精灵们一直感到困惑，曾经爱好和平的黑木熊怪为何会如此凶残地反抗他们的邻居。沿着壁泉河进行的调查将这种腐化追溯到了萨特身上。这些燃烧军团的古老仆从一直在积极操纵该部族，通过阴险的护符引导邪能魔法，扭曲熊怪的思想，使它们陷入疯狂的攻击状态。"},{t="打破枷锁",b="为了引诱幕后黑手现身，桑德里斯·织风配制了一种简单却有效的药剂。通过收集黑木营地北部常见的口粮——谷物、水果和坚果——并将它们浸泡在取自奥伯丁月亮井的圣水中，这些受污染的食物就得到了净化。在中央篝火处提供这种被祝福的食物，可以让附近的熊怪从疯狂中得到片刻的喘息，从而直接暴露那名进行干扰的萨特腐化者——萨布拉克斯，他会因愤怒而现身，以捍卫自己扭曲的统治。"}},faq={{q="为什么黑木熊怪会变得如此好斗？",a="它们的心智受到了恶魔影响的毒害。萨特秘密地潜伏在营地附近，通过附魔护符引导邪恶魔法，将熊怪的本能扭曲为狂暴的暴力。",al={"为什么熊怪发狂","为什么熊怪充满敌意","黑木部族的侵略性"}},{q="萨布拉克斯是谁？",a="萨布拉克斯是一名萨特腐化者，负责监视北部黑木熊怪营地。他在暗处操纵，确保该部族始终受控于邪能疯狂，并依靠一枚堕落护符来维持他的控制。",al={"萨布拉克斯背景","萨特是谁","黑海岸的萨特首领"}},{q="净化它们的食物能永远治愈熊怪吗？",a="不能。浸润过月亮井水的食物只能打破恶魔制造的迷雾，时间仅够让它们恢复短暂的理智并引出萨布拉克斯。击败萨特并夺取他的护符是一次重大胜利，但桑德里斯·织风指出，想要找到彻底治愈这些受腐化部族的方法还需要更多的努力。",al={"治愈是永久的吗","我们拯救了熊怪吗","熊怪被治愈了吗"}},{q="使用月亮井水的想法从何而来？",a="月亮井是由艾露恩女神祝福过的神圣水池，其中蕴含着足以抵御邪能和亡灵的再生魔法。桑德里斯·织风提供了一个净化之碗，以便利用其中的圣水来中和熊怪食物中被注入的恶魔毒素。",al={"为什么要用月亮井水","月亮井净化之碗"}},{q="当食物碗放在篝火旁时会发生什么？",a="附近的熊怪会短暂地从嗜血状态中清醒过来，和平地聚集在被祝福的食物周围，并停止攻击。萨布拉克斯看到他的傀儡摆脱了折磨而感到愤怒，他会立即现身惩罚这些多管闲事的人。",al={"篝火旁的碗","净化熊怪"}},{q="桑德里斯·织风是谁？",a="桑德里斯·织风是一位驻扎在奥伯丁的暗夜精灵研究员兼调查员。他负责协调调查，揭示黑海岸生态逐渐衰退以及当地野生动物陷入疯狂的根本原因。",al={"桑德里斯·织风背景","谁发放的任务"}}},fx={dd154993={q="桑迪斯·织风为什么想要完成这件事？",a="桑迪斯·织风认为熊怪不只是危险的野兽，也是被黑暗魔法逼疯的古老盟友。暗夜精灵相信，驱除掌控黑木部族的恶魔影响，对恢复黑海岸森林的平衡至关重要。通过找出腐化的根源并剥夺萨特的力量，桑迪斯希望避免熊怪遭受永久性的精神毁灭。",al={"为什么帮助桑迪斯","桑迪斯·织风的目标","为什么净化熊怪"}},["3c287e3e"]={q="堕落护符有什么用？",a="堕落护符是一件邪恶的恶魔遗物，萨特借助它扭曲熊怪的自然意志。堕落者通过护符操控黑木熊怪的心智，以持续不断的魔法束缚驱使他们陷入疯狂并充满敌意。桑迪斯需要夺取并摧毁它，才能打破这种控制，夺回森林。",al={"堕落护符的用途","堕落护符有什么作用","萨特护符"}}},fp="23,323,15.353.0,21.401.1,42.227.0,17.203.0,52.285.1,51.242.0,57.228.1,27.213.0"}
P.entries["quest:4767"] = {n="驭风者",s="“风骑士”是一个部落任务，由位于千针石林乱风岗顶部的艾鲁提供。艾鲁自己也渴望成为一名风骑士，他委托冒险者爬上风巢的崎岖高处，收集野生双足飞龙蛋，以充实部落的空中坐骑储备。",h="“风骑士”是一个部落任务，由位于千针石林乱风岗顶部的艾鲁提供。艾鲁自己也渴望成为一名风骑士，他委托冒险者爬上风巢的崎岖高处，收集野生双足飞龙蛋，以充实部落的空中坐骑储备。",kw={"艾鲁","乱风岗","风巢","千针石林","风骑士","双足飞龙蛋"},ang={["class:Hunter"]="熟悉驯服技巧和野兽习性的猎人会明白，直接从领地意识极强的掠食者巢穴中夺取野生蛋，是多么危险且需要精准操作的事情。",["faction:Horde"]="双足飞龙构成了部落在卡利姆多的运输网络骨干，因此补充它们的马厩对于边境通讯和防御至关重要。",["race:Tauren"]="乱风岗的风骑士以他们精湛的飞行技术为荣，并将饲养和训练双足飞龙视为一项光荣的事业。"},sec={{t="天空的召唤",b="在整个卡利姆多，部落非常依赖风骑士来运送信使、侦察兵和勇士前往遥远的地方。在乱风岗，一位名叫艾鲁的年轻牛头人渴望加入他们受人尊敬的行列。由于部落扩张带来的需求超过了坐骑的供应，艾鲁肩负起了帮助获取新的双足飞龙以供应资深风骑士的重任，并为热心的旅行者提供了一个参与这项重要工作的机会。"},{t="攀登风巢",b="风巢耸立在千针石林的巍峨平顶山上，是野生双足飞龙主要的筑巢地。收集可孵化的蛋需要勇闯悬崖，并面对在巢穴周围巡逻、极具保护意识的成年双足飞龙。通过夺取这些卵，艾鲁希望证明自己的奉献精神，并开始人工饲养和训练双足飞龙，为部落的飞行管理员提供支援的艰苦过程。"}},faq={{q="谁发布这个任务？",a="该任务由艾鲁发布，他是一位渴望成为风骑士的牛头人，位于千针石林的乱风岗顶部。",al={"风骑士任务发布者","谁开启风骑士任务","艾鲁位置"}},{q="艾鲁需要什么？",a="艾鲁让你带给他十枚从风巢的巢穴中直接收集到的风巢双足飞龙蛋。",al={"风骑士任务目标","我需要收集什么","双足飞龙蛋"}},{q="风巢在哪里？",a="风巢是一座高耸的平顶山高原，位于乱风岗的西北方，就在白沙岗哨的南面。一条有图腾柱标记的天然斜坡从峡谷底部一直通往筑巢地。",al={"如何前往风巢","风巢入口","双足飞龙蛋在哪里"}},{q="为什么部落要收集野生双足飞龙蛋？",a="部落的资深风骑士们正面临着各前哨站对空中坐骑日益增长的需求，单靠圈养繁殖已无法满足。通过从野生巢穴中孵化双足飞龙，驯养员可以训练新的坐骑，以满足他们的运输和侦察需求。",al={"为什么要采集双足飞龙蛋","双足飞龙蛋背后的传说"}},{q="野生双足飞龙有敌意吗？",a="是的。野生双足飞龙极具领地意识且非常保护它们的后代，会毫不犹豫地攻击任何接近它们在风巢的巢穴的人。",al={"双足飞龙会攻击吗","双足飞龙危险"}},{q="艾鲁打算如何处理这些蛋？",a="艾鲁希望交付这些蛋能让他开始正式的风骑士训练，通过抚养这些生物并与它们建立羁绊，让它们在天空中为部落效力。",al={"艾鲁的双足飞龙","这些蛋会有什么用"}}},fp="10,269,19.432.0,19.390.0,21.97.0,19.98.0,27.200.0,44.257.0,29.143.0,41.158.0"}
P.entries["quest:477"] = {n="越境",s="“边境越界”是瑟伯切尔的暗影牧师奥利斯特指派的一项间谍任务，旨在调查达拉然在银松森林的秘密行动。通过拦截运往焚木村附近达拉然营地的补给板条箱，被遗忘者希望揭开肯瑞托为何积极支持安伯米尔这一人类堡垒的原因。",h="“边境越界”是瑟伯切尔的暗影牧师奥利斯特指派的一项间谍任务，旨在调查达拉然在银松森林的秘密行动。通过拦截运往焚木村附近达拉然营地的补给板条箱，被遗忘者希望揭开肯瑞托为何积极支持安伯米尔这一人类堡垒的原因。",kw={"安伯米尔","边境越界","达拉然板条箱","希尔斯布莱德","焚木村","瑟伯切尔","暗影牧师奥利斯特","银松森林"},ang={["class:Mage"]="部落的施法者热衷于拦截达拉然的魔法物资，以探明肯瑞托在洛丹伦使用了什么秘密和防护结界。",["class:Priest"]="在暗影牧师奥利斯特麾下效力，让被遗忘者牧师能够直接参与保卫被遗忘者教派的领地，对抗神圣和奥术的双重对手。",["race:Undead"]="被遗忘者无法容忍在他们的南侧翼存在一个不受控制的达拉然前哨站，尤其是一个在瑟伯切尔眼皮底下输送补给的据点。"},sec={{t="边境补给",b="尽管安伯米尔是银松森林东部幸存人类抵抗势力的主要据点，但达拉然的法师们并没有对他们坐视不管。装满补给品和奥术物品的货车被秘密运出希尔斯布莱德丘陵，穿过银松森林，为前哨站和集结地提供补给。其中一个后勤营地就坐落在焚木村北面，有达拉然人员驻守，监视着道路。"},{t="被遗忘者的猜疑",b="暗影牧师奥利斯特和瑟伯切尔的被遗忘者领导层认为达拉然在安伯米尔的重金投入令人不安。在他们看来，除非涉及某种更重大的战略或魔法目标，否则肯瑞托几乎没有理由冒险在被遗忘者声称领土的深处投入资源和人员去保护一个乡镇。调查这些板条箱能让被遗忘者直接掌握达拉然向西运输物资的情报。"},{t="揭开货物",b="撬开其中一个法师的板条箱后，发现里面装的不仅仅是日常补给。在精心包装的奥术用具中，还有一捆泛黄的旧地图，描绘着银松森林和更广阔的洛丹伦西部地区，以及一个神秘的魔法吊坠。达拉然似乎并非在进行普通的后勤补给，而是在进行针对性的制图和奥术侦察。"}},faq={{q="为什么达拉然法师会在银松森林活动？",a="达拉然以安伯米尔为基地，以维持人类和联盟在洛丹伦西部的存在。暗影牧师奥利斯特怀疑肯瑞托有着更深层的隐藏动机，而不仅仅是保卫一个小村庄，这促使被遗忘者袭击了他们的补给线。",al={"达拉然为何在此","达拉然 银松森林","为什么达拉然在安伯米尔"}},{q="达拉然的板条箱在哪里？",a="这些板条箱存放在一个由达拉然法师和守卫维护的营地中，位于焚木村正北面，大路旁。",al={"板条箱位置","板条箱在哪里","焚木村营地"}},{q="达拉然板条箱里有什么？",a="奥利斯特不知道达拉然在运输什么。他让你从焚木村北面的营地取回板条箱里的物品，以便他进行调查。",al={"板条箱内容物","箱子里有什么"}},{q="暗影牧师奥利斯特是谁？",a="暗影牧师奥利斯特是一位著名的被遗忘者领袖，驻扎在银松森林的瑟伯切尔，负责指导情报工作，并指挥针对人类残余势力和达拉然入侵者的攻势。",al={"暗影牧师奥利斯特","谁给予边境越界任务"}},{q="补给品是如何进入银松森林的？",a="这些补给品通过货车从希尔斯布莱德丘陵的达拉然领地运出，穿过边境关口进入银松森林，最后抵达安伯米尔和焚木村附近的集结营地。",al={"达拉然补给路线","希尔斯布莱德货车"}},{q="完成这个任务后会发生什么？",a="检查完板条箱后，把你发现的东西带回给暗影牧师奥利斯特进行研究，开启后续任务“地图与符文”。",al={"接下来做什么","后续任务","下一个任务"}}},fp="16,218,24.397.0,24.381.0,20.237.1,52.234.0,37.125.0,33.161.1,30.185.0,52.178.0,42.105.1"}
P.entries["quest:4770"] = {n="回家",s="“归乡之路”是一项部落任务，任务要求冒险者营救被困在风巢双足飞龙巢穴中的年轻牛头人博物学家波卡·雨山。在研究这些危险野兽的过程中，波卡意外失散并迷路，必须有人护送他安全走下悬崖，回到白沙岗哨。",h="“归乡之路”是一项部落任务，任务要求冒险者营救被困在风巢双足飞龙巢穴中的年轻牛头人博物学家波卡·雨山。在研究这些危险野兽的过程中，波卡意外失散并迷路，必须有人护送他安全走下悬崖，回到白沙岗哨。",kw={"护送","风巢","归乡之路","莫特加·火鬃","波卡·雨山","千针石林","白沙岗哨","双足飞龙"},ang={["faction:Horde"]="双足飞龙是卡利姆多整个部落的重要盟友和坐骑，这使得风巢的野生双足飞龙成为一个极具自然研究价值和战略意义的地方。",["race:Tauren"]="部落和长者之间的纽带在牛头人社会中至关重要；莫特加对波卡父亲的深厚责任感，凸显了引导他们进行考察的紧密社群义务。"},sec={{t="自不量力的博物学家",b="波卡·雨山跟随长者莫特加·火鬃前往千针石林，研究峡谷底部和高耸石柱上的独特野生动物。由于好奇心过重且过于自信，波卡独自溜进了风巢的高处，想要近距离观察当地的双足飞龙。这些领地意识极强的野兽将他驱赶开来，导致这位年轻的学者孤立无援、惊恐万状，在岩石间躲藏了好几天。"},{t="走出岩壁之路",b="风巢遍布着极具攻击性的双足飞龙，它们凶猛地守护着自己的巢穴和栖息地。护送波卡回到平地需要直接从这些筑巢的掠食者群中杀出一条路来。这位惊慌失措的年轻人没有准备好面对正面战斗，完全依赖路过的部落旅行者来击退成群的双足飞龙，直到他到达通往东部的峡谷小径的相对安全地带。"},{t="如释重负与清算",b="到达悬崖底部后，波卡终于可以安全地回到白沙岗哨了。他的监护人莫特加·火鬃在得知所发生的一切后感到震惊。莫特加曾向波卡犹豫不决的父亲保证，会在田野考察期间照顾好这个孩子。在庆幸波卡从愚蠢的远征中幸存下来的同时，莫特加奖励了救他的人，但私下里也感叹自己当初应该把这个鲁莽的学徒锁在图腾上。"}},faq={{q="谁是波卡·雨山？",a="波卡·雨山是一位年轻的牛头人学徒，他与莫特加·火鬃一同前往千针石林，记录和研究野生生物。他因年轻气盛，在无人看管的情况下误入了风巢。",al={"波卡","护送npc是谁"}},{q="为什么波卡躲在风巢里？",a="他独自冒险进入巢穴，想要近距离观察当地的双足飞龙和它们的窝。那些好斗的野兽袭击了他，迫使他躲藏起来，并被困在了高处的台地上。",al={"为什么波卡在风巢","波卡发生了什么事","他为什么被困住"}},{q="谁是莫特加·火鬃？",a="莫特加·火鬃是一位驻扎在千针石林白沙岗哨的牛头人博物学家。他受波卡父亲的委托，在科学考察期间负责监督并保障这个年轻人的安全。",al={"莫特加","谁是莫特加·火鬃","任务交付npc"}},{q="风巢在哪里？",a="风巢是一个高耸的台地和双足飞龙巢穴，位于千针石林的西部，正好在白沙岗哨以西，乱风岗以西北方向。",al={"风巢位置","风巢在哪里","从哪里护送他"}},{q="白沙岗哨在哪里？",a="白沙岗哨是位于千针石林风巢以东的一个小型部落营地，是牛头人博物学家研究峡谷动物群的野外基地。",al={"白沙岗哨位置","白沙岗哨在哪里"}},{q="莫特加知道波卡失踪了吗？",a="不知道。波卡是瞒着莫特加独自溜去风巢的，这就是为什么在你们汇报营救情况之前，莫特加完全不知道他的学徒身处险境。",al={"莫特加知道吗","为什么莫特加没有寻找他"}}},fx={["17b8918e"]={q="波卡·雨山为什么要这样做？",a="波卡·雨山独自潜入风巢观察双足飞龙，却因过于靠近巢穴而被困住。被凶猛的捕食者包围，迷失数日的他无法独自杀出重围。更糟的是，他知道莫特加·火鬃若发现他这次鲁莽的探险会勃然大怒，因此只有在护送下逃离，才有希望活着回到白沙岗哨。",al={"为什么帮波卡","波卡的动机","波卡为什么需要护送"}},edb8f2eb={q="波卡·雨山为什么需要你护送，而不是让卫兵来？",a="波卡·雨山偷偷离开了白沙岗哨，营地里根本没人知道他失踪了。叫卫兵来会暴露他违抗莫特加·火鬃命令的事；更紧要的是，他被困在巢穴中好几天，始终没见到一个盟友。你只是第一个偶然发现他藏身处的友善旅人。",al={"为什么是我帮波卡","波卡为什么不叫卫兵","为什么独自帮助波卡"}}},fp="14,315,29.410.0,23.387.0,20.428.1,28.212.0,35.195.0,23.190.0,27.169.0,25.166.0,36.177.1"}
P.entries["quest:478"] = {n="地图与符记",s="“地图与符文”是发生在银松森林的一次被遗忘者侦察任务。在发现一批运往安伯米尔的可疑货物后，冒险者回收了一枚刻有符文的坠饰，并将其交给瑟伯切尔的暗影牧师奥利斯特进行进一步调查。",h="“地图与符文”是发生在银松森林的一次被遗忘者侦察任务。在发现一批运往安伯米尔的可疑货物后，冒险者回收了一枚刻有符文的坠饰，并将其交给瑟伯切尔的暗影牧师奥利斯特进行进一步调查。",kw={"安伯米尔","达拉然板条箱","肯瑞托","地图与符文","rune-inscribed pendant","暗影牧师奥利斯特","银松森林","瑟伯切尔"},ang={["class:Mage"]="这枚刻有符文的坠饰显示出标志性的肯瑞托附魔图案，突显了达拉然在防护和奥术结界方面的独特传统。",["class:Priest"]="虽然暗影牧师奥利斯特掌握着强大的暗影魔法，但神圣和暗影领域的知识并不适合解开刻在坠饰上的复杂奥术公式。",["faction:Horde"]="确保银松森林免受肯瑞托这类效忠联盟势力的侵害，能保证部落在北洛丹伦维持一条重要的补给走廊。",["race:Undead"]="达拉然幸存的法师们在距离幽暗城领地非常近的地方维持着哨所。回收他们附魔的护身符对于捍卫被遗忘者在银松森林的主权至关重要。"},sec={{t="隐藏的货物",b="在安伯米尔附近拦截物资时，部落特工在边境路线上发现了一个隐藏的达拉然板条箱。容器里装的不是普通物资，而是详细的区域地图和一枚神秘的、刻有符文的坠饰。考虑到达拉然的奥术触角延伸到如此靠近其边境的地方所带来的潜在危险，侦察兵小心翼翼地取回了这件神器，以免惊动周围的人类哨兵。"},{t="瑟伯切尔的低语",b="回到瑟伯切尔后，这枚回收的坠饰被呈交给暗影牧师奥利斯特。被遗忘者的领袖们意识到肯瑞托在安伯米尔的行动有着明确的目的，但他们具体在策划什么尚不得而知。由于自己无法解读刻在符文中的强大法术，奥利斯特决定咨询亡灵中的奥术专家，以揭开达拉然的阴谋。"}},faq={{q="达拉然板条箱里有什么？",a="板条箱里装有银松森林地区的战略地图和一枚奇怪的刻有符文的坠饰。这些物品显示达拉然的法师们正在安伯米尔镇周围积极策划行动。",al={"板条箱里的东西","板条箱内容","达拉然板条箱掉落"}},{q="暗影牧师奥利斯特是谁？",a="暗影牧师奥利斯特是驻扎在瑟伯切尔的一位重要的被遗忘者权威人物。他负责监管当地的情报收集工作，并协调针对银松森林中敌对人类残部和肯瑞托特工的防御行动。",al={"奥利斯特是谁","暗影牧师奥利斯特背景"}},{q="为什么被遗忘者对安伯米尔的达拉然势力感到担忧？",a="安伯米尔是肯瑞托在被遗忘者宣称拥有的洛丹伦土地边境上建立的一个活跃据点。任何奥术文物的调动或隐秘的部队调动都对幽暗城在银松森林的统治构成了直接威胁。",al={"安伯米尔的重要性","被遗忘者与达拉然的冲突"}},{q="暗影牧师奥利斯特能解读这枚坠饰吗？",a="不能。虽然奥利斯特认出这件神器属于达拉然的法师，但其具体的附魔超出了他作为牧师的知识范畴，这促使他寻求更精通奥术的人的帮助。",al={"奥利斯特认识符文吗","奥利斯特能解读坠饰吗"}},{q="这项调查接下来会导向何处？",a="调查在“达拉的分析”中继续，坠饰被转交给瑟伯切尔的奥术专家达拉尔·道恩维沃尔，他有能力破解肯瑞托的魔法。",al={"下一个任务是什么","地图与符文后续"}},{q="什么任务引导向“地图与符文”？",a="此任务直接承接自“越过边境”，在那个任务中，被遗忘者指派一名特工去检查从达拉然边境运往银松森林的可疑贸易板条箱。",al={"前置任务","地图与符文前置"}}},fp="14,216,14.293.0,25.319.1,33.145.0,30.228.0,58.191.0,48.139.0,40.168.0,38.184.0"}
P.entries["quest:4787"] = {n="远古之卵",s="塔纳利斯的叶基亚讲述了一个名为远古之卵的传说，它在摩沙鲁预言中被提及，是巨魔帝国鼎盛时期留下的遗物。它或许能容纳哈卡的精华，叶基亚希望你从辛特兰的辛萨罗将其取回。",h="塔纳利斯的叶基亚讲述了一个名为远古之卵的传说，它在摩沙鲁预言中被提及，是巨魔帝国鼎盛时期留下的遗物。它或许能容纳哈卡的精华，叶基亚希望你从辛特兰的辛萨罗将其取回。",kw={"远古之卵","哈卡","辛特兰","辛萨罗","摩沙鲁","预言","塔纳利斯","叶基亚"},sec={{t="巨魔帝国的遗物",b="摩沙鲁预言中提到了一枚远古之卵，它是巨魔帝国鼎盛时期留下的遗物。它的力量或许能容纳哈卡的精华，叶基亚相信这是保护世界免受其邪恶侵害的唯一手段。"},{t="露天剧场后方",b="叶基亚让你将这枚卵带到塔纳利斯。传说它被隐藏在辛特兰的辛萨罗深处，位于城市顶端露天剧场后方的一个洞穴中。叶基亚感觉到巨大的力量正在觉醒，并担心时间所剩无几。"}},faq={{q="什么是远古之卵？",a="它是巨魔帝国鼎盛时期留下的遗物，在摩沙鲁预言中被提及。它的力量或许能容纳哈卡的精华。",al={"远古之卵背景故事","卵的作用","摩沙鲁预言之卵"}},{q="为什么叶基亚想要这枚卵？",a="叶基亚相信这枚卵可能是保护世界免受哈卡邪恶侵害的唯一手段。",al={"为什么要寻找这枚卵","叶基亚的目的","阻止哈卡之卵"}},{q="这枚卵藏在哪里？",a="传说它深藏在辛萨罗内部，位于城市顶端露天剧场后方的一个洞穴里。",al={"远古之卵在哪里","远古之卵位置","辛萨罗之卵洞穴"}},{q="是谁想要拿到这枚卵？",a="在塔纳利斯等待的叶基亚，希望将远古之卵带给他。",al={"谁开启了远古之卵任务","谁提供该任务","叶基亚任务发布者"}}},fp="15,229,24.233.0,23.248.0,24.136.0,32.92.0,24.95.0,34.69.0"}
P.entries["quest:479"] = {n="调查安伯米尔",s="“安伯米尔调查”是暗影牧师奥利斯特从瑟伯切尔指派的一项被遗忘者任务。随着达拉然法师在附近的安伯米尔小镇编织魔法，被遗忘者必须扰乱他们的施法并夺走他们的魔法焦点，以保住银松森林。",h="“安伯米尔调查”是暗影牧师奥利斯特从瑟伯切尔指派的一项被遗忘者任务。随着达拉然法师在附近的安伯米尔小镇编织魔法，被遗忘者必须扰乱他们的施法并夺走他们的魔法焦点，以保住银松森林。",kw={"奥利斯特","安伯米尔","达拉尔","达拉然","肯瑞托","吊坠","瑟伯切尔","银松森林"},ang={["class:Mage"]="法师们了解编织大规模奥术仪式所需的精准协调，因此他们明白切断肯瑞托的附魔焦点为何能扰乱其法术。",["faction:Horde"]="守住银松森林可以确保洛丹伦西部的入口安全，使其免受忠于达拉然的联盟前哨的威胁。",["race:Undead"]="残留在安伯米尔的肯瑞托就驻扎在幽暗城领地的家门口，这使得他们的魔法图谋对被遗忘者的生存构成了无法容忍的威胁。"},sec={{t="来自东方的威胁",b="人类城镇安伯米尔坐落在银松森林东部的群山之中，由效忠于达拉然肯瑞托的法师和防御者牢牢占据。当法师们进行大规模的协同仪式以编织魔法能量时，暗影牧师奥利斯特和他的同伴达拉尔意识到事态危急。如果任由肯瑞托不受阻碍地引导力量，被遗忘者将面临被彻底从银松森林清除的风险。"},{t="扰乱编织",b="当达拉尔在森林中进行占卜并追踪魔法流向时，奥利斯特派遣特工前往安伯米尔，直接打击那些施法者。达拉然的召魔师、法师以及他们的保护者佩戴着能帮助汇聚和协调魔法技艺的附魔吊坠。从被杀死的法师身上剥离这些护身符可以扰乱他们的仪式，为瑟伯切尔争取关键时间以锁定指挥魔法编织的头目。"}},faq={{q="暗影牧师奥利斯特为什么要针对安伯米尔？",a="盘踞在安伯米尔的肯瑞托法师正在积极引导强大的奥术能量。奥利斯特担心，如果他们的施法成功，被遗忘者将失去对银松森林的控制。",al={"为什么攻击安伯米尔","奥利斯特的动机","安伯米尔的威胁"}},{q="达拉然吊坠是用来做什么的？",a="达拉然的召魔师、法师和保护者将这些吊坠作为其法术的焦点。夺走它们会削弱法师们的努力，并帮助奥利斯特分析肯瑞托的魔法进展。",al={"什么是达拉然吊坠","吊坠的目的","为什么要收集吊坠"}},{q="安伯米尔在哪里？",a="安伯米尔位于银松森林的东部山区。从瑟伯切尔出发，沿着主干道向南行进，然后跟随岔路向东进入镇中即可到达。",al={"安伯米尔的位置","如何前往安伯米尔","安伯米尔在哪里"}},{q="达拉尔是谁，他参与了什么？",a="达拉尔是一位驻扎在瑟伯切尔的被遗忘者修行者，与暗影牧师奥利斯特共事，负责追踪并揭露为安伯米尔的达拉然法师提供能量的魔法源头。",al={"达拉尔是谁","达拉尔的角色","达拉尔与银松森林"}},{q="回收吊坠后会发生什么？",a="收集吊坠后显示达拉然的仪式已经进展得相当深入，由一位必须被正面迎击的精锐法师领导，只有击败他才能彻底停止施法。",al={"接下来会发生什么","安伯米尔调查后续","达拉然吊坠之后"}},{q="为什么达拉然的人类还在银松森林？",a="安伯米尔在第三次战争前是一个小型的伐木镇。在他们的王国遭到破坏后，幸存的肯瑞托对它产生了兴趣，并继续占据着安伯米尔以对抗天灾军团和被遗忘者。",al={"为什么达拉然人类在这里","银松森林的肯瑞托","安伯米尔背景故事"}}},fp="24,214,22.384.0,20.374.0,50.161.0,39.186.0,27.154.0,37.171.0,43.157.1,50.197.0"}
P.entries["quest:480"] = {n="法师的头领",s="The Weaver是一项由瑟伯切尔的暗影牧师奥利斯特指派的突袭任务，旨在阻止达拉然在银松森林的魔法行动。一名达拉然大法师阿塔瑞克，正指挥着该地区重新激活一个强大的魔网能量节点。通过击杀该大法师并夺取他的法杖，被遗忘者挫败了达拉然的奥术野心，并巩固了他们对周边领土的控制。",h="The...",kw={"奥利斯特","安伯米尔","阿塔瑞克","达拉然","肯瑞托","魔网能量","瑟伯切尔","银松森林","编织者"},ang={["class:Mage"]="操纵魔网线需要对奥术几何有深刻的掌握；击杀阿塔瑞克揭示了当此类精密的仪式失去其核心导管时是多么脆弱。",["class:Priest"]="暗影牧师奥利斯特指挥这次行动并非依靠神圣恢复的法术，而是以一种经过计算的意志，要在奥术催化剂绽放之前将其熄灭。",["faction:Horde"]="达拉然残部对部落依然怀有敌意，使得他们任何奥术基础设施的扩张都直接威胁到部落在北洛丹伦的领土。",["race:Undead"]="达拉然的活人法师积极地与被遗忘者争夺对洛丹伦废墟的控制权。清除他们的大法师对于确保瑟伯切尔的安全防线至关重要。"},sec={{t="Severing the Ley Thread",b="在对安伯米尔和达拉然在银松森林的活动进行初步调查后，被遗忘者得知了一个危险的情况：这些巫师正试图利用并重新激活一个休眠的魔网能量节点。如果任其发展，获得如此集中的奥术能量将使达拉然得以巩固其阵地，并威胁到幽暗城对洛丹伦南部的统治。"},{t="The Archmage's Fall",b="暗影牧师奥利斯特深知，要瓦解如此规模的行动，必须先擒其首。这一行动由大法师阿塔瑞克策划，这位强大的巫师躲藏在结界和法师同僚的保护之后。击败他并夺取他的法杖将驱散聚集的魔法，使魔网能量重新陷入沉寂，从而挫败肯瑞托在该山谷的野心。"}},faq={{q="Who is the Weaver?",a="The Weaver指的是大法师阿塔瑞克，一名驻扎在银松森林的强大的达拉然施法者。他的任务是编织并重新激活在该地区地下流动的潜在魔法魔网能量。",al={"编织者是谁","大法师阿塔瑞克","阿塔瑞克 编织者"}},{q="Why do the Forsaken want the archmage killed?",a="如果达拉然成功利用了这个休眠的魔网能量节点，他们的法师将在幽暗城的家门口获得巨大的奥术能量来源。暗影牧师奥利斯特认为这对被遗忘者的主权构成了不可容忍的威胁，因此下令在节点完全运作前进行快速暗杀。",al={"为什么击杀阿塔瑞克","被遗忘者与达拉然的冲突","为什么要攻击达拉然"}},{q="What happens after Ataeric is defeated?",a="随着阿塔瑞克被杀及其法杖被没收，奥术网络随之崩溃。聚集的法术消散，魔网能量退回到休眠状态，剥夺了肯瑞托在银松森林南部的主要奥术力量据点。",al={"编织者之后","任务结果","魔网节点发生了什么"}},{q="Who sends you on this quest?",a="暗影牧师奥利斯特，一名驻扎在银松森林瑟伯切尔的被遗忘者权威，在分析了从达拉然在安伯米尔的活动中收集的情报后，发出了这些命令。",al={"谁发布了编织者任务","奥利斯特任务","编织者任务发布者"}},{q="What is the significance of Ataeric's staff?",a="大法师阿塔瑞克的法杖是操纵区域魔网能量的导管和焦点。取回它不仅能确保魔法彻底消散，还能为奥利斯特提供一件可供被遗忘者研究其自身用途的文物。",al={"阿塔瑞克的法杖","大法师法杖的作用","为什么要拿走法杖"}},{q="Where does Dalaran's presence in Silverpine come from?",a="尽管达拉然在第三次战争中遭受了破坏，但肯瑞托的残部仍在安伯米尔等邻近领土维持着坚固的飞地、前哨站和奥术实验，试图重新建立控制并利用重要的魔法储备。",al={"银松森林的达拉然","为什么达拉然法师在银松森林","安伯米尔 达拉然"}}},fp="10,273,23.314.0,19.297.1,18.168.0,45.244.0,39.222.1,28.185.0,44.202.0,54.240.0"}
P.entries["quest:481"] = {n="达拉尔的推理",s="“达拉尔的分析”是银松森林的一个部落任务，它将暗影牧师奥利斯特对安伯米尔的间谍活动与达拉尔·道恩维沃尔的奥术研究联系在了一起。在从一个达拉然补给箱中发现一枚Rune-Inscribed Pendant后，冒险者将这件圣物带给瑟伯切尔的达拉尔进行仔细检查。该神器显示，达拉然的幸存法师们正在为一项隐藏的计划集结强大的魔法力量。",h="“达拉尔的分析”是银松森林的一个部落任务，它将暗影牧师奥利斯特对安伯米尔的间谍活动与达拉尔·道恩维沃尔的奥术研究联系在了一起。在从一个达拉然补给箱中发现一枚Rune-Inscribed...",kw={"安伯米尔","达拉尔·道恩维沃尔","达拉然","肯瑞托","吊坠","瑟伯切尔","暗影牧师奥利斯特","银松森林"},ang={["class:Mage"]="被遗忘者法师会认出肯瑞托吊坠是达拉然传统法术中常用的经典引导工具，这表明他们以前的同胞正在准备一场巨大的召唤仪式。",["faction:Horde"]="挫败肯瑞托在银松森林的计划，能确保东部王国免受复苏的联盟魔法派系的威胁。",["race:Undead"]="对于被遗忘者来说，监视达拉然在安伯米尔的行动对于守护银松森林的边界并保护瑟伯切尔免受敌对巫术的侵害至关重要。"},sec={{t="信使的货物",b="在突袭焚木村以北营地的一个达拉然补给箱后，暗影牧师奥利斯特收到了一枚藏在旧地图下的Rune-Inscribed Pendant。奥利斯特意识到它的附魔超出了他的精神领域，于是将这件圣物交给了驻扎在瑟伯切尔的奥术学者达拉尔·道恩维沃尔，他更适合解读达拉然的魔法结界。"},{t="肯瑞托的阴谋",b="在检查这枚吊坠后，达拉尔·道恩维沃尔将其鉴定为肯瑞托高阶法师历史上偏爱使用的一种特殊导流体，用于引导强大的魔法能量。如此大量的此类圣物被直接输送到防守严密的安伯米尔镇，表明法师们正在筹备一项大规模的奥术工程，这促使达拉尔穿透他们的魔法结界去洞察他们的真实意图。"}},faq={{q="Rune-Inscribed Pendant是什么？",a="该吊坠是肯瑞托高级法师用来安全引导大量魔法能量的奥术神器。它在运输途中被发现，表明安伯米尔正在获得用于高阶法术的强大焦点。",al={"什么是吊坠","肯瑞托吊坠背景故事","安伯米尔吊坠"}},{q="为什么暗影牧师奥利斯特要将吊坠送给达拉尔·道恩维沃尔？",a="暗影牧师奥利斯特主要负责为瑟伯切尔的被遗忘者处理暗影魔法和情报收集工作。由于该吊坠是达拉然工艺制造的复杂奥术圣物，因此需要像达拉尔·道恩维沃尔这样的奥术专家来正确检查其符文并推断其用途。",al={"为什么是达拉尔","谁是达拉尔·道恩维沃尔","为什么送到瑟伯切尔"}},{q="安伯米尔在哪里，为什么被遗忘者要监视它？",a="安伯米尔是银松森林东南部的一座人类堡垒城镇，由达拉然的法师维护。该镇位于希尔瓦娜斯·风行者宣称拥有的领地深处，对被遗忘者构成了直接的军事和魔法威胁，因此需要对其边界进行严格监视。",al={"为什么要监视安伯米尔","安伯米尔法师","银松森林的达拉然"}},{q="达拉尔分析吊坠后发生了什么？",a="达拉尔意识到肯瑞托正在为一个重大目标积累奥术导流体，于是他在接下来的任务“达拉然的意图”中，运用自己的魔法透视了安伯米尔的防御护盾，以查明法师们的具体计划。",al={"what comes next","达拉尔的分析之后","达拉然的意图"}},{q="在哪里可以找到达拉尔·道恩维沃尔？",a="达拉尔·道恩维沃尔位于瑟伯切尔的墓穴内，这是被遗忘者在银松森林的主要据点，位于主路旁。",al={"达拉尔的位置","达拉尔在哪里","达拉尔·道恩维沃尔 银松森林"}},{q="为什么肯瑞托要在银松森林公开活动？",a="在天灾军团摧毁洛丹伦之前，安伯米尔曾是一个安静的伐木镇。尽管首都和达拉然本身已经沦陷，但幸存的法师们还是将安伯米尔作为了一个活跃的堡垒，不断与被遗忘者的扩张发生冲突。",al={"肯瑞托 银松森林","达拉然在银松森林的存在"}}},fp="16,271,17.345.0,22.329.1,35.209.0,69.244.0,58.249.0,46.232.1,36.138.0,60.217.0"}
P.entries["quest:4811"] = {n="红色水晶",s="奥伯丁的哨兵戈琳达·纳希恩派遣旅行者去调查关于黑海岸东部山脉中嵌入的一块神秘红色水晶的传言。由于敌对的枭兽在附近不断繁殖，且似乎被那块构造物所吸引，哨兵们需要确认这一异常现象是否真实存在。",h="奥伯丁的哨兵戈琳达·纳希恩派遣旅行者去调查关于黑海岸东部山脉中嵌入的一块神秘红色水晶的传言。由于敌对的枭兽在附近不断繁殖，且似乎被那块构造物所吸引，哨兵们需要确认这一异常现象是否真实存在。",kw={"奥伯丁","黑海岸","戈琳达·纳希恩","枭兽","红色水晶","哨兵"},ang={["class:Druid"]="德鲁伊与枭兽以及黑海岸的自然秩序有着紧密的精神联系，这使得水晶的腐蚀性或破坏性拉力成为了一个紧迫的生态问题。",["faction:Alliance"]="奥伯丁是联盟在北卡利姆多的主要海岸港口；任何在山中聚集的未受遏制的威胁，都有可能使这个避风港与荒野隔绝。",["race:NightElf"]="枭兽的躁动对卡多雷来说是一个令人不安的景象，他们一直将这些生物视为艾露恩和自然的守护者而崇敬。"},sec={{t="荒野中令人不安的转变",b="世世代代以来，卡利姆多的暗夜精灵一直将枭兽视为与荒野紧密相连的温和而神秘的生物。然而近几天，一群群具有攻击性的枭兽在奥伯丁东部的山坡上迅速繁殖。虽然一些守旧派仍然保持着对枭兽的敬畏，但哨兵戈琳达·纳希恩将城镇的安全放在首位，无法忽视日益增长的危险。有报告显示，这些野兽正蜂拥至东部山峰上的某个特定地点。"},{t="东部山脉的异常现象",b="侦察兵和流浪者带来了一些传闻，称在黑海岸上方高处崎岖的山坡上，矗立着一块不自然的红色水晶。由于狂野的谣言很容易在这片雾气笼罩的海岸上传播，戈琳达需要有人实地考察，以去伪存真。找到那块深红色的巨石证实了这种异常现象确实存在，这让哨兵们不得不困惑于当地的枭兽为何会被它莫名其妙地吸引，以及它的存在是否预示着某种对这片土地的邪恶影响。"}},faq={{q="黑海岸的红色水晶是什么？",a="这是一块嵌入黑海岸上方东部山脉中的神秘绯红色构造物。哨兵们起初对其起源知之甚少，只知道当地的野生动物——尤其是枭兽——似乎无法抗拒地被吸引到它所在的位置。",al={"什么是红色水晶","黑海岸水晶","奥伯丁的红色岩石"}},{q="是谁派你去寻找红色水晶的？",a="驻扎在奥伯丁的哨兵戈琳达·纳希恩指派了这项任务。她负责保卫该定居点，并希望获得有关东部山脉传言的第一手确认信息。",al={"谁发布了红色水晶任务","戈琳达·纳希恩任务","奥伯丁水晶任务发布者"}},{q="为什么枭兽在水晶周围表现得具有攻击性？",a="历史上一直被视为温和而神秘生物的枭兽，现在变得具有领地意识且反复无常。哨兵戈琳达怀疑它们行为的突然转变和数量的激增，与这块神秘红色水晶所散发出的某种力量直接相关。",al={"为什么枭兽会发狂","黑海岸愤怒的枭兽","敌对的枭兽"}},{q="红色水晶位于哪里？",a="水晶位于奥伯丁正东方向，坐落在黑海岸崎岖的东部山脊高处，周围徘徊着枭兽。",al={"去哪里找红色水晶","红色水晶位置","黑海岸红色水晶地图"}},{q="暗夜精灵认为这块水晶危险吗？",a="哨兵戈琳达非常谨慎。虽然不确定这块石头是良性的还是邪恶的，但它激怒并聚集了野生野兽的事实，使其成为奥伯丁安全方面的一个紧迫问题。",al={"水晶有害吗","红色水晶是邪恶的吗"}},{q="发现水晶后会发生什么？",a="向戈琳达报告它的存在证实了传言的真实性。她立即寻求揭示其本质，从而促成了使用奥伯丁月光林地的水对其进行净化和取样的行动。",al={"红色水晶任务后有什么","如水流般后续任务"}}},fp="15,233,31.339.0,28.328.0,37.181.0,42.161.0,57.166.0,33.107.0,55.153.0,44.178.1"}
P.entries["quest:4812"] = {n="清洗水晶",s="《奔涌之水》是黑海岸的一项联盟任务，玩家需要借此测试从东部山壁上突出的神秘红色水晶的本质。通过将从奥伯丁收集到的神圣月亮井水浇在水晶表面，玩家试图穿透其不透明的外壳，探寻其来源。",h="《奔涌之水》是黑海岸的一项联盟任务，玩家需要借此测试从东部山壁上突出的神秘红色水晶的本质。通过将从奥伯丁收集到的神圣月亮井水浇在水晶表面，玩家试图穿透其不透明的外壳，探寻其来源。",kw={"奔涌之水","奥伯丁","黑海岸","空水瓶","费伍德森林","戈琳达·纳希恩","月亮井","红色水晶"},ang={["class:Druid"]="守护着黑海岸脆弱生态系统的德鲁伊们，对这种不自然的异界构造天生持怀疑态度，尤其是在受腐蚀的费伍德森林下方的山脊沿线。",["faction:Alliance"]="常驻奥伯丁的联盟侦察兵必须确保海岸安全，抵御从东部高地蔓延而下的腐蚀。",["race:NightElf"]="对于卡多雷来说，月亮井是生命与慰藉的神圣源泉。将这些圣水作为一种揭示真相的工具，凸显了艾露恩的恩典在化解边境威胁方面的重要性。"},sec={{t="净化未知",b="在黑海岸东部悬崖高处首次发现红色水晶后，哨兵戈琳达·纳希恩想出了一种安全检查其成分的方法。月亮井水蕴含着强大的神圣与恢复魔法，并受到暗夜精灵对艾露恩虔诚信仰的祝福。戈琳达推断，用从奥伯丁月亮井中汲取的水浇灌这座外星巨石会引发反应，从而在不彻底摧毁它的前提下，穿透其奇异而不透明的外壳。"},{t="费伍德之影",b="纳希恩的担忧很大程度上源于地理因素。黑海岸的东部山脊矗立在费伍德森林那受腐蚀的高地之下，这是一片在第三次战争中被恶魔能量扭曲的森林。如果这座红色尖塔与费伍德森林的腐蚀有关，那么接触它就存在巨大的风险。当神圣的井水顺着水晶的晶格流下时，那块嗡嗡作响的石头瞬间变得透明，暗示着无论其中囚禁着什么，都需要更仔细地观察。"}},faq={{q="我该从哪里获取任务所需的水？",a="你必须使用哨兵戈琳达·纳希恩提供的空水瓶，从暗夜精灵定居点奥伯丁的月亮井中汲取水。",al={"月亮井在哪里","月亮井水位置","灌满空水瓶"}},{q="为什么月亮井水会对水晶产生影响？",a="月亮井中盛放着由艾露恩赐福的圣洁且富含魔法的水。哨兵戈琳达·纳希恩预料其净化精华会与石头的异质能量产生反应，并揭示其隐藏的成分。",al={"为什么用月亮井水","月亮井水对水晶的魔法效果"}},{q="红色水晶位于何处？",a="神秘的红色水晶位于黑海岸东部的山壁沿线，坐落在将海岸与上方高地隔开的岩石山脚下。",al={"红色水晶位置","水晶在哪里","黑海岸的红色水晶"}},{q="为什么哨兵戈琳达会对费伍德森林感到担忧？",a="费伍德森林位于黑海岸的正东方和上方，饱受第三次战争中恶魔腐蚀的蹂躏。因为水晶出现在边界山脊附近，戈琳达担心它可能有着同样邪恶的恶魔起源。",al={"戈琳达与费伍德森林","与费伍德森林的联系"}},{q="把水浇在水晶上会发生什么？",a="戈琳达希望强大的月亮井水能揭示关于水晶成分的线索。当你将水浇上去时，就能发现它的反应。",al={"浇水后的结果","水晶会发生什么"}},{q="谁发布了《奔涌之水》任务？",a="该任务由奥伯丁的哨兵戈琳达·纳希恩发布，紧随侦察任务《红色水晶》之后。",al={"任务发布者","谁开启奔涌之水"}}},fp="17,175,21.329.0,21.382.1,40.123.0,43.198.0,33.134.0,45.187.0,52.156.1,38.114.0"}
P.entries["quest:4813"] = {n="水晶中的碎骨",s="“内在的碎片”是对奥伯丁以东悬崖上突出的神秘红色晶体进行调查的最后一个任务。你携带净化过的月井水回到现场，查看这一奇怪构造内部究竟有什么，并向哨兵戈琳达·纳希恩汇报。",h="“内在的碎片”是对奥伯丁以东悬崖上突出的神秘红色晶体进行调查的最后一个任务。你携带净化过的月井水回到现场，查看这一奇怪构造内部究竟有什么，并向哨兵戈琳达·纳希恩汇报。",kw={"奥伯丁","骨头碎片","黑海岸","戈琳达·纳希恩","颚骨","月井水","神秘红色晶体"},ang={["class:Druid"]="这种神秘的矿物既能抵抗自然磨损，也能抵抗强大的魔法，是荒野传统平衡中的一个奇怪的反常现象。",["race:NightElf"]="在灰谷和费伍德森林的山区边界，发现有人形骨头悬浮在奇怪的晶体中，这引起了守护黑海岸的哨兵们的警惕。"},sec={{t="严峻的启示",b="将受过祝福的月井水淋在深红色晶体上可以清除模糊的外层，露出它光亮表面下所禁锢的东西。晶体内部悬浮着几块小骨头碎片和半块人形颚骨。包裹它们的石头异常坚硬——非常耐用，即使强大的法术也很难将其击碎。无论是什么实体或神器产生了这些遗骸，它都以一种不可思议的孤立状态被保存在黑海岸的海岸线之上。"},{t="向奥伯丁报告",b="回到奥伯丁，哨兵戈琳达·纳希恩记下了你这令人不安的发现。这一启示并没有提供明确的答案，反而引起了当地暗夜精灵领导层的更多担忧。戈琳达承诺会将调查结果呈报给镇议会，尽管她感到些许宽慰的是，那块奇怪的晶体位于东部悬崖高处，距离城镇很远，不会对居民构成直接威胁。"}},faq={{q="红色晶体里困着什么？",a="用圣化的月井水清洗晶体使其变得足够透明，可以看到里面深深嵌入的几块骨头碎片和半块人形颚骨。",al={"晶体里有什么","这些碎片是什么","里面是什么骨头"}},{q="能把晶体敲开来检查骨头吗？",a="不能。这块晶体异常坚硬。即使是最强大的魔法也几乎不可能破坏它的结构，这使得骨头的确切身份成了一个谜。",al={"你能打破晶体吗","打开红色晶体"}},{q="你向谁汇报调查结果？",a="你向驻扎在奥伯丁港口城镇的哨兵戈琳达·纳希恩汇报你的调查结果。",al={"谁来交内在的碎片任务","任务交还","戈琳达·纳希恩"}},{q="哨兵们会如何处理这块晶体？",a="哨兵戈琳达·纳希恩计划通知奥伯丁的议会，以便他们商讨可能的行动。然而，由于晶体位于东部悬崖高处，它目前并未被视为紧急威胁。",al={"晶体接下来会怎么样","奥伯丁议会晶体"}}},fp="20,185,17.339.1,22.340.0,39.129.1,52.139.1,34.83.0,45.194.1"}
P.entries["quest:482"] = {n="达拉然的意图",s="“达拉然的意图”是银松森林的一个任务，由达拉尔·道恩维沃尔发布给暗影牧师奥利斯特。在研究了送往安伯米尔肯瑞托的Rune-Inscribed Pendant后，达拉尔意识到法师们打算利用城镇下方一个休眠的魔网能量节点，促使瑟伯切尔的被遗忘者领导层计划反击。",h="“达拉然的意图”是银松森林的一个任务，由达拉尔·道恩维沃尔发布给暗影牧师奥利斯特。在研究了送往安伯米尔肯瑞托的Rune-Inscribed...",kw={"安伯米尔","达拉尔·道恩维沃尔","达拉然的意图","肯瑞托","魔网能量","瑟伯切尔","暗影牧师奥利斯特","银松森林"},ang={["class:Mage"]="被遗忘者的法师们会识别出肯瑞托的方法：开采休眠的魔网线是一种无需在荒野中搬运庞大动力源就能建立强大奥术桥头堡的高效方式。",["class:Priest"]="暗影牧师奥利斯特指挥着瑟伯切尔的被遗忘者防御，将冷酷的军事实用主义与被遗忘者祭司的黑暗教义相结合，以清除活着的威胁。",["race:Undead"]="达拉然在银松森林深处的存在直接威胁到了被遗忘者的边界；阻止他们的魔网仪式可以保护提瑞斯法与南部边界之间的道路。"},sec={{t="休眠的火花",b="在检查从一个达拉然补给箱中找回的Rune-Inscribed Pendant时，达拉尔·道恩维沃尔回想起了一份古老的肯瑞托调查报告。法师们选择安伯米尔并非巧合；这个安静的村庄正好位于一个休眠的魔网能量节点之上。唤醒这样一个地下枢纽需要巨大的魔法储备，而法师们佩戴的附魔坠饰正是引导和催化这种力量的关键组件。"},{t="对银松森林的威胁",b="被遗忘者无法容忍一个设防的、充满力量的肯瑞托前哨站威胁到瑟伯切尔和提瑞斯法林地的南部入口。无论法师们正在准备什么样的盛大仪式，利用原始魔网线都将使达拉然在洛丹伦获得巨大的战略优势。达拉尔紧急传信给暗影牧师奥利斯特，要求制定一个策略，在法师们的仪式完成前阻止他们的进展。"}},faq={{q="肯瑞托在安伯米尔试图做什么？",a="达拉然的法师们正试图重新激活位于安伯米尔下方的一个休眠魔网能量节点。开采这条奥术脉络将赋予他们巨大的力量，以建立永久据点并推行他们在银松森林的更广泛计划。",al={"安伯米尔魔网线","达拉然法师在银松森林做什么","安伯米尔的目的"}},{q="为什么达拉尔派你去见暗影牧师奥利斯特？",a="暗影牧师奥利斯特是瑟伯切尔被遗忘者的高级军事和精神领袖。达拉尔·道恩维沃尔提供奥术方面的见解和研究，但针对达拉然的战术决策和进攻性反制措施均由奥利斯特负责。",al={"为什么要告诉奥利斯特","谁是奥利斯特","达拉尔·道恩维沃尔与奥利斯特"}},{q="法师们的坠饰与他们的计划有什么联系？",a="重新唤醒一个休眠的魔网节点需要大量的能量储备。达拉然的法师们携带的附魔坠饰充当了这种魔法的导管和容器。剥夺法师们的这些坠饰会削弱他们完成激活的能力。",al={"肯瑞托坠饰","安伯米尔坠饰","为什么要收集坠饰"}}},fp="20,252,15.396.0,24.394.0,48.190.0,50.206.0,50.200.0"}
P.entries["quest:4821"] = {n="异型卵",s="乱风岗的牛头人之间流传着关于一枚奇异外来之卵的传闻，据说它被峡谷底部的野生毒蛇严密守护着。哈加尔·雷蹄委托部落冒险者前去搜寻并取回这个样本，以免其中的东西破壳而出。",h="乱风岗的牛头人之间流传着关于一枚奇异外来之卵的传闻，据说它被峡谷底部的野生毒蛇严密守护着。哈加尔·雷蹄委托部落冒险者前去搜寻并取回这个样本，以免其中的东西破壳而出。",kw={"异型卵","阿力卡拉","乱风岗","哈加尔·雷蹄","蛇穴","毒蛇的野性","毒蛇","千针石林"},ang={["class:Hunter"]="熟悉卡利姆多野兽的猎人会立刻意识到，峡谷中的蛇巢里孕育着比普通沙漠毒蛇更为原始的东西。",["faction:Horde"]="乱风岗是部落在千针石林的主要前哨站，因此遏制出现的顶级掠食者是保卫补给线的重中之重。",["race:Tauren"]="生活在乱风岗峡谷上方的牛头人依赖于对下方野生动物微妙平衡的理解；一种入侵性的或不自然的蛇群对他们的家园构成了直接威胁。"},sec={{t="奇异之巢",b="关于一枚在乱风岗峡谷底部矗立的石针下方，散布在蛇穴深处的奇异之卵的传闻传到了这里。峡谷中本土的毒蛇像守护自己的后代一样看守着这枚卵，攻击任何靠得太近的旅人。哈加尔·雷蹄对此感到好奇，同时也担忧这可能会威胁到当地的狩猎场，于是他请勇敢的侦察兵找到蛇巢，避开这些滑行的哨兵，并将这个异物取回以供研究。"},{t="幼体苏醒",b="在仔细检查取回的卵时，哈加尔发现这远不止是一枚普通的爬行动物卵。它在触碰时外壳立即破裂，释放出一只幼年的带翼怪物，被称为阿力卡拉幼崽。这只刚出生的生物并没有发起攻击，而是冲向天空，逃离了乱风岗的木制平台，预示着峡谷的风中正酝酿着某种更深层的原始力量。"}},faq={{q="异型卵可以在哪里找到？",a="这枚卵位于千针石林崖底散布的多个蛇穴之一中，特别是在乱风岗的南部和东北部。它直接坐落在峡谷底部，周围环绕着充满敌意的本土毒蛇。",al={"异型卵位置","异型卵在哪里","千针石林卵刷新"}},{q="为什么当地的毒蛇要守护它？",a="没有人知道这枚卵是谁产下的，但峡谷里的毒蛇却像守护自己的后代一样保护着它，积极防御巢穴免受任何好奇的入侵者侵害。",al={"为什么毒蛇保护异型卵","毒蛇行为异型卵"}},{q="哈加尔·雷蹄是谁？",a="哈加尔·雷蹄是驻扎在千针石林乱风岗高处的牛头人侦察兵和守卫。他负责监视峡谷底部不寻常的动向和生态威胁，并协调部落的力量来管理当地的野兽。",al={"哈加尔·雷蹄背景故事","任务发布者哈加尔是谁"}},{q="交付卵之后会发生什么？",a="哈加尔终于可以近距离检查这枚卵了，他所见到的景象让他感到震惊。当你把它交给他时，卵里究竟有什么就会揭晓。",al={"异型卵孵化出什么","卵里面有什么"}},{q="这个任务引向什么？",a="交付这枚卵会开启一条更长的任务线，直接引向任务“毒蛇的野性”，哈加尔将在任务中寻求了解这枚卵所孕育的东西的本质。",al={"异型卵后续任务","阿力卡拉任务链下一步"}},{q="这枚异型卵真的是来自外太空吗？",a="在这种语境下，“异型”指的是对千针石林当地生态系统来说完全陌生、不自然且不熟悉的事物，而不是指来自外太空的生物。它究竟属于哪种生物，正是哈加尔想要查明的事情。",al={"异型卵是外星来的吗","卵是外星的吗"}}},fx={["7e0b1b71"]={q="哈加尔·雷蹄为什么想要异型卵？",al={"哈加尔为什么想要卵","哈加尔·雷蹄的动机","异型卵任务的原因"}},a4db3611={q="异型卵是什么？",a="异型卵是在千针石林各处蛇巢深处发现的一窝奇异蛇卵。它看起来并不像普通的蛇卵，但当地的风蛇却像守护自己的卵一样拼命保护它。哈加尔·雷蹄想要找到它并调查其来历，不过仔细查看后，它很快便孵化出一条年幼的有翼蛇，并振翅飞走。",al={"什么是异型卵","异型卵的用途","异型卵的背景"}}},fp="9,260,14.474.0,21.400.1,33.237.0,39.172.1,27.240.0,38.138.1,29.155.1,38.243.1"}
P.entries["quest:483"] = {n="唤醒圣物",s="“唤醒圣物”是一项紧急救援任务，目的是拯救沉睡在班奈希尔兽穴中的猛禽德鲁伊。堕落的棘鬃熊怪已经占领了这些神圣的土丘，危及到了那些精神漫游在翡翠梦境中的沉睡德鲁伊。如果没有这四件特定的仪式神器，就无法安全地将沉睡者唤醒回现实世界。",h="“唤醒圣物”是一项紧急救援任务，目的是拯救沉睡在班奈希尔兽穴中的猛禽德鲁伊。堕落的棘鬃熊怪已经占领了这些神圣的土丘，危及到了那些精神漫游在翡翠梦境中的沉睡德鲁伊。如果没有这四件特定的仪式神器，就无法安全地将沉睡者唤醒回现...",kw={"阿斯瑞达斯·熊皮","班奈希尔兽穴","黑色羽毛","多兰纳尔","猛禽德鲁伊","翡翠梦境","棘鬃","鸦爪神符","唤醒圣物","筑巢符文","天蓝宝石"},ang={["class:Druid"]="对于年轻的德鲁伊来说，对班奈希尔的袭击是针对他们塞纳里奥同胞的直接打击。找回圣物证明了你肩负着保护凡世土地与翡翠梦境之间神圣桥梁的责任。",["race:NightElf"]="泰达希尔枝干上兽穴的遭到亵渎，凸显了腐蚀扭曲棘鬃部族并扰乱你新家园平衡的速度之快，令人不安。"},sec={{t="亵渎密室",b="兽穴是暗夜精灵德鲁伊进行深度冬眠并漫游翡翠梦境时的隐秘圣所。在多兰纳尔以西，班奈希尔兽穴蜿蜒的通道已经被一群堕落的棘鬃熊怪所占据。这些曾经的盟友受到了蔓延在泰达希尔的邪恶腐蚀，精神变得疯狂，并亵渎了这处密室，威胁着那些对自身肉体所面临的危险毫无察觉的无助沉睡者。"},{t="回归之具",b="进入梦境的德鲁伊不能被简单地摇醒；在没有合适的精神锚点的情况下惊扰他们的沉睡，可能会粉碎他们的心智，或者让他们的灵魂永远迷失。为了执行精细的唤醒仪式，阿斯瑞达斯·熊皮需要四件封存在兽穴各处宝箱里的圣物：鸦爪神符、黑色羽毛、天蓝宝石和筑巢符文。找回它们是在棘鬃熊怪屠杀或完全劫持猛禽德鲁伊之前唤醒他们的唯一希望。"}},faq={{q="为什么德鲁伊不能直接摇醒？",a="德鲁伊的冬眠是一种连接凡世躯壳与翡翠梦境的极其微妙的恍惚状态。如果唤醒方式不当，或是没有使用“唤醒圣物”中的防护仪式，他们的意识可能会永远迷失在梦境中，与肉体永远隔绝。",al={"为什么要圣物来唤醒德鲁伊","为什么要唤醒仪式","为什么圣物是必要的"}},{q="谁是猛禽德鲁伊？",a="他们是与天空调和的暗夜精灵德鲁伊，能够化身为风暴乌鸦并驾驭风的力量。许多人都曾在泰达希尔的兽穴中进入了翡翠梦境的深度沉睡。",al={"猛禽德鲁伊","谁睡在班奈希尔"}},{q="为什么棘鬃熊怪要攻击兽穴？",a="棘鬃部族已经沦为了邪恶腐蚀的受害者，这种腐蚀正在不断毒害泰达希尔的野生动物和森林。他们曾经是暗夜精灵友好的邻居，但堕落的心智使他们变得暴戾，驱使他们成群结队地袭击像班奈希尔这样的古老圣所。",al={"为什么兽穴里有熊怪","棘鬃攻击","为什么熊怪有攻击性"}},{q="要找回的四件圣物是什么？",a="阿斯瑞达斯·熊皮委托冒险者收集鸦爪神符、黑色羽毛、天蓝宝石和筑巢符文，每一件都存放在班奈希尔兽穴内部的神圣宝箱中。",al={"是哪些圣物","需要的圣物","圣物的名字"}},{q="阿斯瑞达斯·熊皮是谁？",a="阿斯瑞达斯是一位驻扎在多兰纳尔的暗夜精灵，负责监控周围野外的精神健康，并组织力量应对棘鬃熊怪和兽穴所遭受的突如其来的腐蚀。",al={"阿斯瑞达斯·熊皮","多兰纳尔的任务发布者"}},{q="班奈希尔兽穴在哪里？",a="班奈希尔兽穴位于泰达希尔枝干上，多兰纳尔定居点正西方的山丘之中。",al={"班奈希尔的位置","班奈希尔在哪里","兽穴在哪里"}}},fp="22,304,17.415.0,19.472.0,42.238.0,32.204.0,56.229.0,41.194.0,27.220.0,38.94.0"}
P.entries["quest:484"] = {n="小鳄鱼皮",s="詹姆斯·哈洛兰是米奈希尔港的一位知名制皮匠，他雇佣旅行者提供从湿地幼年鳄鱼身上采集的新鲜鳄鱼皮。他鞣制的皮革在国际航运中很受欢迎，因此可靠的狩猎来源对他而言至关重要。提供这些更柔软的材料可以赢得他的信任，并开启后续的制皮任务。",h="詹姆斯·哈洛兰是米奈希尔港的一位知名制皮匠，他雇佣旅行者提供从湿地幼年鳄鱼身上采集的新鲜鳄鱼皮。他鞣制的皮革在国际航运中很受欢迎，因此可靠的狩猎来源对他而言至关重要。提供这些更柔软的材料可以赢得他的信任，并开启后续的制皮...",kw={"鳄鱼","埃纳尔","詹姆斯·哈洛兰","皮革","米奈希尔港","皮","制皮","湿地"},ang={["class:Hunter"]="对于途经湿地的猎人来说，哈洛兰的请求只是一项常规的野外工作，即从本地掠食者身上采集干净的皮革，且不损坏皮料。",["faction:Alliance"]="支持米奈希尔港的海上商业贸易，能确保重要的补给线和出口贸易在无尽之海上顺利流动。"},sec={{t="港口的出口贸易",b="米奈希尔港是连接东部王国与遥远大陆的重要海上枢纽，同时也支撑着围绕周边湿地资源建立的繁荣地方经济。詹姆斯·哈洛兰通过鞣制该地区大量爬行掠食者坚韧的皮革，建立了一项国际贸易。往来米奈希尔港的商人和船只将哈洛兰的皮革制品运往遥远的港口，这使得他的作坊面临着持续保持稳定库存的压力。"},{t="狩猎沼泽幼鳄",b="虽然像埃纳尔这样的老练猎人会定期提供成熟的皮革，但鞣制特殊的奢侈品需要比成年湿地鳄鱼所能提供的皮革柔软得多的皮料。为了弥补这一短缺，哈洛兰依靠过往的冒险者涉足米奈希尔港栅栏外的浅沼泽。从幼兽身上获取完整的鳄鱼皮需要精心的狩猎，以确保皮料保持完好，足以经受哈洛兰细致的鞣制过程。"}},faq={{q="詹姆斯·哈洛兰是谁？",a="詹姆斯·哈洛兰是在米奈希尔港经营的制皮大师。他鞣制的鳄鱼皮举世闻名，并经常被运往无尽之海彼岸的外国港口。",al={"詹姆斯·哈洛兰背景故事","制皮匠是谁","哈洛兰 米奈希尔"}},{q="为什么哈洛兰特别需要幼年鳄鱼皮？",a="成年鳄鱼能提供耐用、厚重的盔甲级皮革，而幼年鳄鱼的皮则柔软且更具韧性。这些娇嫩的皮革对于生产成年鳄鱼皮过于僵硬而无法制作的特定奢侈品和精细皮具至关重要。",al={"为什么要幼年鳄鱼","更柔软的皮革","鳄鱼皮的用途"}},{q="埃纳尔是谁？",a="埃纳尔是驻扎在湿地的一名当地猎人，他与詹姆斯·哈洛兰直接合作。他定期前往沼泽捕杀野生鳄鱼，为港口作坊供应原皮。",al={"埃纳尔 湿地","猎人埃纳尔","埃纳尔背景故事"}},{q="这些幼年鳄鱼在哪里可以找到？",a="幼年鳄鱼栖息在米奈希尔港周围的水道、芦苇丛和沼泽浅滩中，就在城镇大门和码头之外。",al={"鳄鱼位置","幼年鳄鱼在哪里","湿地幼年鳄鱼"}},{q="把鳄鱼皮交给哈洛兰之后会发生什么？",a="哈洛兰对皮料的质量印象深刻，他会立即请求协助处理制皮业务中的其他杂务，委派典型的学徒任务以维持作坊的运转。",al={"任务后续","鳄鱼皮任务后的下一个任务","哈洛兰的下一个任务"}},{q="为什么鳄鱼皮在米奈希尔港很有价值？",a="米奈希尔港是一个繁忙的贸易港口，连接着铁炉堡、暴风城与卡利姆多等海外领地。由技艺精湛的工匠鞣制的异域防水沼泽皮革，在停靠该镇的商人和水手中备受青睐。",al={"米奈希尔皮革贸易","鳄鱼皮价值"}}},fp="21,277,17.357.0,31.323.0,22.160.0,58.157.0,13.182.0,39.128.0,50.177.0,53.234.0"}
P.entries["quest:4841"] = {n="清除半人马",s="“安抚半人马”是由乱风岗顶部的峭壁卫兵图林·长角发布的报复性狩猎任务。为了清除聚集在峡谷尖塔下方的威胁，部落冒险者深入位于裂蹄峭壁的加拉克半人马营地进行打击。",h="“安抚半人马”是由乱风岗顶部的峭壁卫兵图林·长角发布的报复性狩猎任务。为了清除聚集在峡谷尖塔下方的威胁，部落冒险者深入位于裂蹄峭壁的加拉克半人马营地进行打击。",kw={"峭壁卫兵图林·长角","乱风岗","加拉克斥候","加拉克逐风秘法师","加拉克驯兽师","安抚半人马","裂蹄峭壁","千针石林"},ang={["faction:Horde"]="乱风岗是部落在升降梯和闪光平原之间的重要生命线。在哨所塔楼下方留下咄咄逼人的半人马，会危及穿越该区域的每一支商队。",["race:Tauren"]="对于舒哈鲁人（牛头人）来说，看到半人马营地侵占定居点会引发对世代屠杀的记忆。削减加拉克半人马的数量是关乎文化生存的头等大事。"},sec={{t="峡谷底部的威胁",b="乱风岗坐落在危险的沙漠台地上，使牛头人得以俯瞰千针石林的峡谷底部。然而，当敌对势力在绳梯和升降梯下方直接集结时，这片高地也难享安宁。加拉克半人马在裂蹄峭壁的峡谷北侧建立了一个庞大的战营，直接威胁到了补给线和牛头人在千针石林中的通行。"},{t="报复与杀戮",b="为了应对日益增长的危险，峭壁卫兵图林·长角派遣有能力的部落旅者通过无情的暴力来削减加拉克半人马的数量。牛头人认为，若要保卫乱风岗，仅靠防守升降梯是不够的，必须在半人马自己的营地中击溃他们的先锋军。击杀他们的斥候、驯兽师和逐风秘法师，旨在挫败任何针对乱风岗的协同攻击。"}},faq={{q="是谁发布了“安抚半人马”任务？",a="该任务由位于千针石林乱风岗顶部的峭壁卫兵图林·长角发布。他是该哨所的关键守卫者之一，负责监视潜伏在周围盐碱平原和峡谷中的危险。",al={"任务发布者","谁开启安抚半人马","峭壁卫兵图林·长角"}},{q="加拉克半人马位于哪里？",a="加拉克半人马在乱风岗的正北方，紧靠千针石林的北侧崖壁扎营，该区域被称为裂蹄峭壁。",al={"加拉克营地位置","裂蹄峭壁在哪里","半人马位置"}},{q="为什么牛头人要消灭半人马？",a="半人马长期以来在整个卡利姆多中部对游牧的牛头人发动了残酷的种族灭绝战争。随着加拉克部族在乱风岗脚下建立前哨营地，峭壁卫兵图林·长角要求进行迅速报复，以确保部落这座沙漠堡垒的安全。",al={"为什么杀死半人马","牛头人与半人马的冲突","为什么报复"}},{q="需要击杀哪些种类的半人马？",a="任务要求你在裂蹄峭壁的营地中猎杀十二名加拉克斥候、十名加拉克驯兽师和六名加拉克逐风秘法师。",al={"加拉克击杀目标","要杀死哪种半人马","任务目标"}},{q="完成“安抚半人马”后接下来做什么？",a="在削减了加拉克半人马的兵力后，峭壁卫兵图林·长角会将注意力转向该地区的其他威胁，并引导你执行后续任务“恐怖图腾的间谍”。",al={"后续任务","安抚半人马之后","半人马任务链"}},{q="什么前置任务引导至此任务？",a="该任务在交付“送信至乱风岗”后开启，该任务会指引旅者直接向峭壁卫兵图林·长角报到。",al={"前置条件","前序任务","如何解锁安抚半人马"}}},fx={["9375eea4"]={q="在乱风岗以北扎营的加拉克半人马是谁？",al={"加拉克半人马是谁","加拉克半人马","乱风岗以北的半人马"}}},fp="18,257,28.442.0,25.431.0,39.201.0,36.159.0,42.290.0,39.146.0,47.165.0,43.144.0"}
P.entries["quest:485"] = {n="找到OOX-09/HL！",s="一个在辛特兰的蛋形金属装置在拧动旋钮后突然弹开，一个名叫奥格索普·奥布诺提斯的侏儒从里面说话。奥格索普的一个追踪机器人坠毁在隐匿石附近，需要将信标带给它。",h="一个在辛特兰的蛋形金属装置在拧动旋钮后突然弹开，一个名叫奥格索普·奥布诺提斯的侏儒从里面说话。奥格索普的一个追踪机器人坠毁在隐匿石附近，需要将信标带给它。",kw={"藏宝海湾","求救信标","辛特兰","追踪机器人","奥格索普·奥布诺提斯","oox-09/hl","隐匿石"},sec={{t="噼啪作响的呼叫",b="摆弄那个奇怪金属蛋上的旋钮，它打开变成了一个侏儒装置。一个噼啪作响的声音报出了奥格索普·奥布诺提斯的名字，并说追踪机器人坠毁了。坐标已经计算出来了：机器人坠落在河流源头，靠近隐匿石的地方。需要将信标带给它。"},{t="河边的残骸",b="在河流源头躺着一些看起来像是机械鸡的残骸。来自金属蛋里的声音证实这就是那个追踪机器人。首先需要进行一次紧急启动，因为只有这样它才能回到藏宝海湾进行维修，需要将信标放入其中。"}},faq={{q="是谁通过求救信标在说话？",a="那个声音是一个自称奥格索普·奥布诺提斯的侏儒，他的追踪机器人在辛特兰坠毁了。",al={"谁制作了信标","谁是奥格索普","是谁在说话"}},{q="机器人坠毁在哪里？",a="奥格索普计算出的坐标显示它位于辛特兰的河流源头，靠近隐匿石。",al={"机器人在哪里","oox-09/hl位置","去哪里寻找机器人"}},{q="追踪机器人长什么样？",a="残骸看起来像是一只机械鸡。",al={"机器人是什么","机械鸡","oox长什么样"}},{q="信标是用来做什么的？",a="没有一次紧急启动，机器人就无法自行回到藏宝海湾进行维修，将信标放入其中就是为了提供启动动力。",al={"如何激活机器人","如何处理信标","如何完成寻找oox-09/hl"}}},fp="15,242,16.313.0,25.270.0,44.112.0,26.100.0,37.39.0,23.125.0"}
P.entries["quest:486"] = {n="大槌乌萨尔",s="殴打者乌萨尔是阿斯瑞达斯·熊皮努力唤醒泰达希尔沉睡的利爪德鲁伊的最终挑战。为了打破禁锢在他那些处于大兽穴中的族人身上的非自然睡眠，必须除掉那个破坏了他们召唤仪式的堕落熊怪酋长。",h="殴打者乌萨尔是阿斯瑞达斯·熊皮努力唤醒泰达希尔沉睡的利爪德鲁伊的最终挑战。为了打破禁锢在他那些处于大兽穴中的族人身上的非自然睡眠，必须除掉那个破坏了他们召唤仪式的堕落熊怪酋长。",kw={"阿斯瑞达斯","班奈希尔","熊皮","德鲁伊","熊怪","脊骨部落","殴打者","利爪","泰达希尔","乌萨尔"},ang={["class:Druid"]="守护翡翠梦境的神圣仪式至关重要。乌萨尔对利爪德鲁伊的干扰是对塞纳里奥交流仪式严重的亵渎。",["faction:Alliance"]="确保泰达希尔内部道路的安全并恢复德鲁伊的聚会，在暗夜精灵融入更广阔的联盟时，能够加强他们的据点。",["race:NightElf"]="脊骨部落的熊怪曾经是卡多雷的古老盟友。除掉他们陷入疯狂的领袖乌萨尔，是保护你的同胞和沉睡的德鲁伊们所必须采取的悲剧性举措。"},sec={{t="转为梦魇的沉睡",b="利爪德鲁伊们隐居在班奈希尔兽穴中，沉睡并与翡翠梦境进行交流。然而，他们宁静的恍惚状态却变成了一座无法逃脱的囚笼。阿斯瑞达斯·熊皮认定脊骨堡的熊怪，特别是他们凶残的领袖殴打者乌萨尔，是干涉了德鲁伊神圣仪式的罪魁祸首，导致他们被困在清醒与梦境之间。"},{t="脊骨堡内的兽穴",b="收集唤醒圣物只是困难的一半。为了让阿斯瑞达斯的唤醒仪式能够穿透禁锢德鲁伊们的精神迷雾，必须消灭干扰的源头。殴打者乌萨尔将巢穴设在脊骨堡，即该部落位于泰达希尔最西南方的家园。击败这位熊怪督军便可打破他对沉睡者心灵的控制。"},{t="更深层腐化的症状",b="虽然乌萨尔的死让阿斯瑞达斯得以进行仪式并拯救利爪德鲁伊，但他的死并不能治愈泰达希尔所受的创伤。脊骨部落依然因腐化而陷入疯狂，而世界之树枝叶间蔓延的病症源头仍然未知。"}},faq={{q="殴打者乌萨尔是谁？",a="殴打者乌萨尔是一位凶猛且堕落的脊骨部落熊怪酋长，居住在泰达希尔西南方的脊骨堡。他积极地干扰利爪德鲁伊的冥想，将他们困在班奈希尔兽穴的沉睡中。",al={"乌萨尔是谁","乌萨尔背景故事","脊骨堡的首领是谁"}},{q="为什么必须杀死乌萨尔来唤醒德鲁伊？",a="即使手握神圣的唤醒圣物，只要乌萨尔还活着，阿斯瑞达斯·熊皮的仪式就无法生效。熊怪邪恶的干扰就像是一个持续存在的精神锚点，阻止了德鲁伊们的灵魂回归本体。",al={"为什么要杀乌萨尔","乌萨尔为何必须死","唤醒圣物的用途"}},{q="在哪里可以找到殴打者乌萨尔？",a="乌萨尔盘踞在脊骨堡，那是脊骨部落位于泰达希尔最西南角的家园。",al={"乌萨尔的位置","脊骨堡在哪里","如何找到乌萨尔"}},{q="杀死乌萨尔能彻底拯救脊骨部落的熊怪吗？",a="不能。乌萨尔的死解放了沉睡的德鲁伊，但脊骨部落的熊怪仍然处于堕落状态，而在泰达希尔森林中蔓延的病症也依然存在。",al={"熊怪被治愈了吗","我们拯救了熊怪吗","泰达希尔得救了吗"}},{q="利爪德鲁伊是谁？",a="利爪德鲁伊是一个效忠于乌鸦图腾的暗夜精灵德鲁伊教派，他们可以化身为风暴乌鸦。他们在大兽穴中进入了深度沉睡，以便从翡翠梦境中守护这片荒野。",al={"利爪德鲁伊","谁在沉睡","哪些德鲁伊获救了"}},{q="阿斯瑞达斯·熊皮是谁？",a="阿斯瑞达斯·熊皮是一位驻扎在多兰纳尔的暗夜精灵德鲁伊。他指引冒险者们找回被窃的圣物并除掉乌萨尔，以便他的族人能被安全地唤醒。",al={"阿斯瑞达斯·熊皮","任务发布者阿斯瑞达斯","谁发布了乌萨尔的任务"}}},fp="16,216,26.388.0,25.314.0,23.242.1,24.197.0,46.212.0,36.98.0,58.152.1,32.213.0,27.157.0"}
P.entries["quest:4865"] = {n="狂热之蛇",s="“蛇之野”是千针石林的一个部落任务，它将奇异异型卵的发现与古老的牛头人传说联系在了一起。在乱风岗发生了一件令人不安的事情后，哈加尔·雷蹄将冒险者派往西北方的白沙岗哨，去见莫特加·火鬃，以应对阿利卡拉的苏醒。",h="“蛇之野”是千针石林的一个部落任务，它将奇异异型卵的发现与古老的牛头人传说联系在了一起。在乱风岗发生了一件令人不安的事情后，哈加尔·雷蹄将冒险者派往西北方的白沙岗哨，去见莫特加·火鬃，以应对阿利卡拉的苏醒。",kw={"阿利卡拉","乱风岗","哈加尔·雷蹄","莫特加·火鬃","圣火","蛇之野","千针石林","白沙岗哨"},ang={["class:Shaman"]="像阿利卡拉这类复仇之灵的扰动，凸显了栖息在峡谷平顶山上那些元素和精神力量之间微妙的平衡。",["faction:Horde"]="为了保持穿过千针石林的补给线畅通，必须解决那些可能威胁到升降梯与菲拉斯之间道路的神秘威胁。",["race:Tauren"]="阿利卡拉的苏醒将民间传说变成了一场紧急危机，考验着守护千针石林的牛头人的精神管理能力。"},sec={{t="血肉化的传说",b="当奇异且反常的卵开始出现在千针石林时，当地的牛头人担心会发生生态灾难。然而，在检查这些遗物时发现，它们比普通的掠食者要古老且不祥得多：种种迹象都指向了复仇之灵阿利卡拉。哈加尔·雷蹄被这可怕的证实惊呆了，他意识到峡谷正面临着一个长期以来被认为只存在于炉边故事中的神话威胁。"},{t="通往白沙岗哨之路",b="意识到这种威胁已经超出了简单的物理防御范畴，哈加尔敦促冒险者立即与莫特加·火鬃商议。莫特加驻扎在峡谷底部的西北方，即白沙岗哨，他作为一名守望者和精神向导，精通千针石林的传统预兆。如果部落想要了解并安抚或消灭这股正在崛起的复仇之灵，他的指导至关重要。"}},faq={{q="谁发放“蛇之野”任务？",a="哈加尔·雷蹄位于千针石林乱风岗的高处，在你调查了峡谷中发现的奇异异型卵之后，他会立即提供该任务。",al={"谁给予蛇之野","蛇之野任务发布者","哈加尔·雷蹄任务"}},{q="莫特加·火鬃在哪里？",a="莫特加·火鬃居住在白沙岗哨，这是一个位于乱风岗西北方向道路旁的小型牛头人营地，过了通往升降梯的岔路口就能找到。",al={"莫特加·火鬃在哪里","莫特加·火鬃位置","寻找莫特加"}},{q="阿利卡拉是谁，或者是什么？",a="阿利卡拉是牛头人神话中体现复仇之心的传奇风蛇之灵，据传它在千针石林的现身对当地部族构成了严重的心灵和物理威胁。",al={"什么是阿利卡拉","阿利卡拉背景故事","阿利卡拉的传说"}},{q="在接取此任务前必须完成什么前置任务？",a="你必须完成“异型卵”任务，在该任务中，你要从峡谷的野生兽类身上取回一枚不同寻常的卵，并将其交给哈加尔·雷蹄进行检查。",al={"蛇之野前置任务","异型卵任务线","蛇之野解锁"}},{q="找到莫特加·火鬃后会发生什么？",a="与莫特加交谈会开启任务“圣火”，开始对抗阿利卡拉之灵所需的仪式准备工作。",al={"蛇之野之后是什么","蛇之野后续","圣火任务"}},{q="为什么哈加尔·雷蹄如此惊慌？",a="哈加尔曾以为阿利卡拉的传说仅仅是故事。亲眼见到复仇之灵在峡谷中显现的证据让他感到恐惧，促使他立即请求长者的智慧。",al={"哈加尔为什么害怕","哈加尔擦汗","哈加尔的反应"}}},fp="12,308,19.406.0,22.383.0,34.176.0,33.163.0,23.190.0,60.162.0,44.126.0,38.200.0"}
P.entries["quest:487"] = {n="达纳苏斯之路",s="连接多兰纳尔定居点与暗夜精灵主城达纳苏斯的主干道，正不断遭受受到腐蚀的蓟皮熊怪的威胁。哨兵阿玛拉·夜行者负责协调侦察兵和往来旅客，以确保这条关键的贸易与信使通道免受伏击。",h="连接多兰纳尔定居点与暗夜精灵主城达纳苏斯的主干道，正不断遭受受到腐蚀的蓟皮熊怪的威胁。哨兵阿玛拉·夜行者负责协调侦察兵和往来旅客，以确保这条关键的贸易与信使通道免受伏击。",kw={"阿玛拉·夜行者","伏击者","达纳苏斯","多兰纳尔","熊怪","蓟皮怪","夜行者","通往达纳苏斯的道路","泰达希尔"},ang={["class:Priest"]="协助哨兵阿玛拉·夜行者即是服务于艾露恩姐妹会，该组织为年轻的世界之树提供了精神领导和军事防御。",["faction:Alliance"]="达纳苏斯是联盟在北卡利姆多力量的核心；确保贸易和通讯安全地沿着其主要公路流动至关重要。",["race:NightElf"]="蓟皮熊怪曾是荒野中值得尊敬的同族；在通往达纳苏斯的公路上剿灭受腐蚀的伏击者，是泰达希尔疾病所带来的残酷必然。"},sec={{t="岌岌可危的生命线",b="从多兰纳尔向西延伸至达纳苏斯的道路，是泰达希尔主要的陆路交通动脉。为了维持首都与这座世界之树枝干之间的联系，重要的贸易物资、政治公文和行人都必须每日沿此路通行。由于泰达希尔相对年轻且充满野性，维护道路的安全对于初生的卡多雷社区至关重要。"},{t="蓟皮怪的威胁",b="泰达希尔的蓟皮熊怪部落并非和平的森林居民，而是沦为了邪恶腐蚀的受害者。受某种毒害世界之树枝干的疾病所困，它们变得疯狂，并从山脊下的隐秘巢穴中冲出。蓟皮怪伏击者潜伏在路边的树丛中，捕食毫无防备的信使和旅客，将本该宁静的森林旅途变成了一场致命的考验。"},{t="哨兵的守望",b="为了对抗这些伏击者，哨兵阿玛拉·夜行者在多兰纳尔外围保持警惕。她将艾露恩祭司的精神权威与哨兵的军事警觉相结合，指引有能力的冒险者前往路下方的巢穴消灭伏击者，从而确保通往达纳苏斯大门的交通安全。"}},faq={{q="为什么多兰纳尔与达纳苏斯之间的道路如此危险？",a="受到腐蚀的蓟皮熊怪在路面下方的低矮山脊上建立了巢穴。由于泰达希尔蔓延的腐蚀，它们变得疯狂，从灌木丛中冲出伏击旅客、信使和商人。",al={"为什么熊怪在攻击","蓟皮怪的道路攻击","为什么道路不安全"}},{q="哨兵阿玛拉·夜行者是谁？",a="哨兵阿玛拉·夜行者（有时也被称为哨兵阿玛拉·夜行者）是一位驻扎在多兰纳尔西郊的暗夜精灵指挥官。她负责监督公路的安全，并协调针对附近蓟皮怪威胁的军事行动。",al={"谁发放通往达纳苏斯的任务","阿玛拉·夜行者","谁是阿玛拉·夜行者"}},{q="为什么蓟皮熊怪具有攻击性？",a="熊怪历史上曾是卡多雷的盟友和和平的邻居。然而，泰达希尔上的蓟皮熊怪部落受到了感染世界之树的怪病的扭曲，使它们心智狂乱，开始攻击任何进入森林的人。",al={"为什么蓟皮怪疯狂","泰达希尔的熊怪腐蚀","蓟皮怪是邪恶的吗"}},{q="伏击者躲在哪里？",a="伏击者栖息在多兰纳尔以西主干道旁的山崖和制高点下方，它们的巢穴使其能够跳向前往达纳苏斯的旅客。",al={"蓟皮怪伏击者在哪里","找到伏击者","伏击者巢穴位置"}},{q="为什么达纳苏斯不派遣完整的哨兵卫戍部队来清理道路？",a="哨兵部队在泰达希尔各地兵力紧张，需要处理格里尔虫患、受腐蚀的树人以及海岸沿线的威胁。像阿玛拉·夜行者这样的军官必须依靠有能力的旅行者和志愿者来保持内部交通路线的畅通。",al={"卫兵在哪里","为什么哨兵需要帮助","达纳苏斯巡逻"}},{q="为什么阿玛拉·夜行者既被称为月亮祭司，又是哨兵？",a="在卡多雷社会中，艾露恩姐妹会与哨兵军队紧密相连。祭司阶层中的领导者指挥哨兵部队，或者终生担任前线战士，这在当地很常见。",al={"阿玛拉·夜行者军衔","阿玛拉·夜行者是祭司还是哨兵","阿玛拉·夜行者称号"}}},fp="21,221,22.296.0,20.312.0,20.313.0,60.217.0,28.241.0,42.224.0,31.161.0,70.222.0,57.182.0"}
P.entries["quest:488"] = {n="赛恩的要求",s="《赛恩的委托》是由赛恩·腐蹄提供的一项联盟任务，他是一个独自潜伏在幽影谷和多兰纳尔之间道路以北的萨特。他诱骗急于求成的冒险者去猎杀当地的野生生物，收集动物部件来为他那不可告人的阴谋服务，并以此利用泰达希尔新人们的信任和天真。",h="《赛恩的委托》是由赛恩·腐蹄提供的一项联盟任务，他是一个独自潜伏在幽影谷和多兰纳尔之间道路以北的萨特。他诱骗急于求成的冒险者去猎杀当地的野生生物，收集动物部件来为他那不可告人的阴谋服务，并以此利用泰达希尔新人们的信任和天...",kw={"多兰纳尔","腐蹄","夜刃豹","萨特","幽影谷","林枭","泰达希尔","树林","赛恩"},ang={["class:Druid"]="德鲁伊誓要维护自然的平衡。为了一个扭曲的腐化生物而去偷猎夜刃豹、猫头鹰和蜘蛛，是对塞纳里奥教义的侮辱。",["race:NightElf"]="对于一个年轻的暗夜精灵来说，听命于一个萨特是极其可耻的。萨特是背叛祖先并被燃烧军团腐化的人，在泰达希尔的枝干上协助这样的生物，是对自然和卡多雷传统的冒犯。"},sec={{t="一笔可疑的交易",b="从幽影谷出发前往多兰纳尔的旅者可能会遇到站在巨树枝叶下悠闲自得的赛恩·腐蹄。这位萨特并没有表现出明显的敌意，反而承诺以物质奖励和秘密作为交换，诱使他们去跑腿。他让冒险者从周围的林地里采集夜刃豹牙齿、林枭羽毛和树林蜘蛛丝，并悄声耳语，要求他们对这一安排保密。"},{t="萨特的玩笑",b="萨特是卡多雷的宿敌，在远古之战期间被恶魔魔法腐蚀，因此赛恩出现在泰达希尔本身就是一种亵渎。毫无戒心的冒险者在完成他的差事后很快就会发现自己被戏弄了。赛恩并没有提供什么宝藏或深刻的见解，反而对旅行者竟然如此轻信一个萨特而肆意嘲笑，并为自己能骗到一个天真的陌生人来帮他做肮脏的勾当而沾沾自喜。"}},faq={{q="谁是赛恩·腐蹄？",a="赛恩·腐蹄是一只狡猾的萨特，潜伏在幽影谷西侧通往多兰纳尔的道路旁。与大多数一见面就发起攻击的萨特不同，赛恩使用花言巧语和虚假的承诺来操纵天真的旅行者，让他们为他效劳。",al={"谁是赛恩","赛恩·腐蹄背景故事","萨特任务发布者"}},{q="为什么一个萨特会在泰达希尔发布任务？",a="赛恩伪装成非敌对状态，以欺骗那些还不了解萨特那背信弃义、腐化本质的菜鸟冒险者。他利用他们渴望工作和银币的心理，收集那些他自己无法公开猎取（否则会招致哨兵部队的愤怒）的材料。",al={"为什么萨特是友好的","为什么我能和赛恩交谈","泰达希尔的萨特"}},{q="赛恩用那些牙齿、羽毛和蛛丝做什么？",a="赛恩声称这些部件是他“森林生意”所需的试剂。实际上，他很享受操纵凡人，利用他们的劳动来达成自己腐化的目的，同时在私下里嘲笑他们的轻信。",al={"为什么赛恩需要蛛丝","赛恩的试剂","动物部件有什么用"}},{q="为什么暗夜精灵不应该信任赛恩·腐蹄？",a="萨特曾经是暗夜精灵，在一万年前的远古之战期间被燃烧军团的恶魔力量所转化。他们是卡多雷的古老誓敌和腐化的携带者，与他们达成的任何交易都是危险且可耻的。",al={"为什么憎恨萨特","暗夜精灵与萨特历史","萨特是邪恶的吗"}},{q="完成《赛恩的委托》后会发生什么？",a="当你交出物品后，赛恩会公开嘲笑你愚蠢，竟然听命于一个萨特。在意识到自己的被欺骗以及协助这种生物所带来的羞耻后，冒险者随后会被引导去寻求对自己错误的救赎。",al={"赛恩的委托之后","寻求救赎任务","赛恩之后的后续"}},{q="赛恩·腐蹄在哪里？",a="他位于泰达希尔，站在幽影谷向西前往多兰纳尔的主路北侧。",al={"赛恩·腐蹄位置","赛恩在哪里","赛恩地图位置"}}},fp="14,182,17.351.0,16.339.1,21.214.0,43.236.0,53.219.0,46.231.0,45.219.1,31.108.0"}
P.entries["quest:4881"] = {n="暗杀计划",s="“暗杀指令”是一个部落任务，玩家需要在千针石林回收被截获的半人马命令来开启该任务。这些命令揭示了一场针对牛头人卡纳提·灰云的突袭行动，地点就在白沙岗哨附近的狩猎营地。",h="“暗杀指令”是一个部落任务，玩家需要在千针石林回收被截获的半人马命令来开启该任务。这些命令揭示了一场针对牛头人卡纳提·灰云的突袭行动，地点就在白沙岗哨附近的狩猎营地。",kw={"暗杀指令","暗杀阴谋","半人马","升降梯","部落","卡纳提·灰云","千针石林","白沙岗哨"},ang={["faction:Horde"]="白沙岗哨是升降梯西南方的一个小型部落前哨，卡纳提的生存对于守望千针石林至关重要。",["race:Tauren"]="半人马的敌意在牛头人的记忆中根深蒂固。在白沙岗哨保卫卡纳提·灰云，是保护卡利姆多的平原和峡谷免受半人马侵略这一长期斗争的直接延续。"},sec={{t="敌对土地上的猎人",b="千针石林一直以来都是纷争之地，被好战的半人马部族和危险的野生动物所占据。当牛头人勇士卡纳提·灰云在升降梯西南方的小型岗哨——白沙岗哨建立狩猎营地时，当地的半人马将其视为对其领地的大胆侵犯。半人马不仅想把猎物赶走，更决定彻底消灭卡纳提·灰云，以阻止部落通过峡谷进行任何进一步的扩张。"},{t="被截获的命令",b="当一名旅行者发现了一份概述半人马战略的书面法令时，这个阴谋才浮出水面。这份暗杀指令直接点名卡纳提·灰云，斥责他的鲁莽，并命令一支突袭部队向白沙岗哨集结，意图彻底铲除该营地以及任何胆敢追随他的人。将这份书信交给卡纳提能预先警告这名猎人，促使他做好准备，随时迎击突袭者。"}},faq={{q="什么是暗杀阴谋？",a="这是一场由当地半人马策划的协同伏击，针对的是在千针石林的白沙岗哨建立狩猎营地的牛头人卡纳提·灰云。半人马想要除掉他，以防止部落在峡谷中立足。",al={"暗杀阴谋概述","这个任务是关于什么的","半人马阴谋"}},{q="卡纳提·灰云是谁？",a="卡纳提·灰云是一位牛头人，在千针石林的升降梯西南方的小型哨所——白沙岗哨建立了一个狩猎营地。在半人马部族的峡谷附近扎营，使他成为了一个主要目标。",al={"卡纳提是谁","卡纳提·灰云","白沙岗哨npc"}},{q="为什么半人马想杀死卡纳提？",a="半人马认为卡纳提在白沙岗哨的存在是对千针石林无法容忍的侵犯。他们计划杀死他以拆除狩猎营地，并威慑任何未来想要在该地区定居的部落斥候。",al={"为什么要杀卡纳提","半人马动机","半人马为什么要攻击"}},{q="白沙岗哨在哪里？",a="白沙岗哨是一个位于千针石林的小型牛头人营地，坐落在升降梯西南方，沿峡谷底部延伸。",al={"白沙岗哨位置","卡纳提的营地在哪里","白沙岗哨在哪"}},{q="联盟玩家可以完成这个任务吗？",a="联盟旅行者也能找到暗杀指令，但他们无法传达警告：卡纳提·灰云是一位部落牛头人，只有部落成员才能将这份指令交给他。",al={"联盟可以做这个吗","联盟暗杀指令","联盟交任务"}},{q="卡纳提收到警告后会发生什么？",a="收到警告后，卡纳提拒绝逃离。相反，他做好准备击退袭击者，这直接引出了当半人马战队到达时保卫白沙岗哨的战斗。",al={"接下来发生什么","后续任务","保护卡纳提"}}},fp="18,223,25.461.0,22.410.1,31.238.0,24.215.0,39.219.0,25.128.0,41.167.0,36.194.1"}
P.entries["quest:489"] = {n="寻求救赎！",s="“寻求救赎！”是一个在多兰纳尔提供的任务，旨在让那些被萨特赛恩·腐蹄欺骗而干了脏活的冒险者们赎罪。森林议会因你伤害了林地野兽而要求你悔过，并指派你诱骗这名狡诈的萨特吃下受腐蚀的魔锥果。",h="“寻求救赎！”是一个在多兰纳尔提供的任务，旨在让那些被萨特赛恩·腐蹄欺骗而干了脏活的冒险者们赎罪。森林议会因你伤害了林地野兽而要求你悔过，并指派你诱骗这名狡诈的萨特吃下受腐蚀的魔锥果。",kw={"多兰纳尔","魔锥果","凯拉·星歌","萨特","寻求救赎","莎拉·夜风","塞拉尔·刃叶","泰达希尔","赛恩·腐蹄"},ang={["class:Druid"]="德鲁伊视泰达希尔的平衡为神圣之事；听从一个被恶魔腐化的流放者的命令去捕杀掠食者和食腐动物，直接违背了塞纳里奥议会的守护准则。",["race:NightElf"]="对于卡多雷来说，帮助萨特是极大的耻辱。萨特是上古之战期间被燃烧军团扭曲的古老敌人，因此通过森林议会进行赎罪关乎文化荣誉。"},sec={{t="愚行终结",b="赛恩·腐蹄是一只潜伏在多兰纳尔外围的独居萨特，他依靠欺诈手段诱骗过路人为他效力。那些无意中为了满足他扭曲的欲望而屠杀夜刃豹、林枭和蛛网蜘蛛的冒险者，很快就会招致森林议会的强烈不满。议会绝不容忍对自然的亵渎，尤其是当这种亵渎来自他们自己的盟友时。"},{t="赎罪的代价",b="无论是塞拉尔·刃叶、哨兵凯拉·星歌还是哨兵莎拉·夜风，她们传达的信息都很明确：若想在泰达希尔继续受到欢迎，你必须做出补偿。多兰纳尔的卫兵们并没有让你直接拔剑对抗腐蹄，而是教导你利用他邪恶的贪婪。通过从林地地面收集那些散发着腐蚀气息的魔锥果，你可以让这只毫无防备的生物自食其果。"},{t="呱呱的报应",b="你伪装成另一名忠诚的跑腿者，向他献上一份“甜点”，实则将有毒的果实交给了腐蹄。赛恩毫无察觉地落入了德鲁伊布置的陷阱，贪婪地吞下了这些贡品——结果立刻被变形术变成了一只无助的青蛙，他那卑鄙的阴谋被粉碎，并在他试图玷污的荒野面前低下了头。"}},faq={{q="为什么森林议会对我很生气？",a="你之前接受了赛恩·腐蹄的任务，屠杀了当地的野生动物——夜刃豹、林枭和蜘蛛——来满足萨特的突发奇想。议会认为这种对自然生物毫无必要的杀戮是对泰达希尔的亵渎，并要求你做出补救以保持良好的声誉。",al={"森林议会为何生气","寻求救赎的原因","为什么要寻求救赎"}},{q="谁可以给我这个任务？",a="一旦你完成了对腐蹄的帮助，多兰纳尔内外的几名守望者都会提供这个任务。你可以与北部住所外的塞拉尔·刃叶、旅店内的哨兵凯拉·星歌，或是西侧道路上的哨兵莎拉·夜风交谈。",al={"任务给予者","谁发布寻求救赎","哪里领取寻求救赎"}},{q="什么是魔锥果？",a="魔锥果是泰达希尔周围扭曲的树枝上掉落的受腐蚀的松果。它们很容易辨认，果壳上冒着令人不安的绿色蒸汽，蕴含着一种邪恶的魔法，德鲁伊常利用这种魔法来对付那些毫无防备的作恶者。",al={"魔锥果","魔锥果是什么","魔锥果的来源"}},{q="为什么要给赛恩·腐蹄魔锥果？",a="议会希望你给腐蹄一个教训。他会把这些受腐蚀的果实误认为是由之前帮他干活的人送来的无害零食。",al={"为什么要给赛恩魔锥果","腐蹄的零食","魔锥果陷阱"}},{q="为什么有一只萨特住在离多兰纳尔这么近的地方？",a="赛恩·腐蹄在定居点外的一个空旷林地中保持低调，用虚假的客套话来掩盖他邪恶的本性。卡利姆多各地的萨特都是燃烧军团的古老仆从，赛恩的存在表明这种腐化已经深入到了这棵年轻的世界之树中。",al={"为什么赛恩在多兰纳尔附近","多兰纳尔的萨特","赛恩·腐蹄背景故事"}},{q="我可以跳过或放弃这个任务而不影响我的声誉吗？",a="可以。虽然森林议会会因你帮助腐蹄而严厉斥责你，但选择不接受或不完成该任务并不会损害你与达纳苏斯的暗夜精灵之间的声誉。",al={"声望损失","我可以放弃寻求救赎吗","任务失败"}}},fp="16,215,22.345.0,22.384.0,22.250.1,47.218.0,27.187.0,19.183.0,41.140.1,49.256.0,65.168.0"}
P.entries["quest:490"] = {n="Bounty: Gnarlpine Furbolg",s="Bounty: Gnarlpine Furbolg是一项联盟任务，由哨兵部队授权，旨在遏制正在腐蚀泰达希尔的具有攻击性的熊怪群体。Shayla Nightbreeze在达纳苏斯外招募冒险者去猎杀这些被腐蚀的野兽，并收集它们的獠牙作为证明。",h="Bounty: Gnarlpine Furbolg是一项联盟任务，由哨兵部队授权，旨在遏制正在腐蚀泰达希尔的具有攻击性的熊怪群体。Shayla...",kw={"班尼希尔山谷","悬赏","腐蚀","达纳苏斯","熊怪","gnarlpine","gnarlpine獠牙","哨兵","shayla nightbreeze","星风村","泰达希尔"},ang={["class:Druid"]="眼看着熊怪失去与自然的和谐，变成充满敌意的野兽，这威胁到了德鲁伊誓死保卫的林地平衡。",["faction:Alliance"]="哨兵部队正积极保护暗夜精灵家园免受内部腐蚀的侵害，号召联盟冒险者肃清散布在枝叶各处的危险熊怪营地。",["race:NightElf"]="Gnarlpine曾是卡多雷和平的邻居和盟友，它们堕落于腐蚀，并因此产生的悬赏成为了保卫泰达希尔的悲剧性必要措施。"},sec={{t="来自哨兵部队的法令",b="在达纳苏斯外的道路上，Shayla Nightbreeze根据哨兵部队的直接命令，对Gnarlpine熊怪下达了悬赏令。Gnarlpine熊怪曾是这片古老森林中爱好和平的居民，但如今它们屈服于正在蔓延的腐蚀，失去了理智，成为了威胁旅行者安全和泰达希尔自然神圣性的恶毒威胁。"},{t="肃清营地",b="为了遏制Gnarlpine的侵略性，猎人们被派遣到世界之树的枝叶上，以减少它们的数量并收集它们的獠牙作为证明。它们被腐蚀的群体主要居住在两个主要据点：位于多兰纳尔西侧道路以南的班尼希尔山谷，以及东侧的星风村废墟。"}},faq={{q="谁提供了Gnarlpine熊怪的悬赏？",a="Shayla Nightbreeze委托了这项悬赏。她驻扎在泰达希尔达纳苏斯主城外的道路旁。",al={"谁发布了gnarlpine熊怪悬赏","哪里领取gnarlpine悬赏","shayla nightbreeze位置"}},{q="为什么Gnarlpine熊怪会被猎杀？",a="Gnarlpine熊怪已经屈服于腐蚀，变得盲目且具有攻击性，对旅行者、暗夜精灵定居点以及泰达希尔的自然野生动物构成了威胁。",al={"为什么要猎杀gnarlpine","gnarlpine为什么充满敌意","gnarlpine熊怪发生了什么"}},{q="在哪里可以找到Gnarlpine熊怪？",a="Gnarlpine熊怪主要聚集在班尼希尔山谷（位于多兰纳尔以西，主路以南）以及更东边的星风村。",al={"gnarlpine熊怪位置","泰达希尔的gnarlpine在哪里","哪里可以找到熊怪"}},{q="领取悬赏需要什么证明？",a="Shayla Nightbreeze要求冒险者收集并上交Gnarlpine獠牙，作为从世界之树枝叶上清除熊怪威胁的实物证明。",al={"gnarlpine悬赏证明","shayla需要什么证明","gnarlpine獠牙证明"}},{q="谁授权了对Gnarlpine的悬赏？",a="这项悬赏是根据哨兵部队（暗夜精灵的军事保护者）直接颁布的严格命令而委托的，旨在保障泰达希尔枝叶的安全。",al={"谁下达了gnarlpine悬赏","谁授权了熊怪悬赏"}},{q="Gnarlpine一直对暗夜精灵怀有敌意吗？",a="从历史上看，熊怪是森林的盟友和朋友，与暗夜精灵和平共处，但腐蚀切断了它们和平的天性，扭曲了它们的心智。",al={"熊怪一直都是敌人吗","熊怪过去友好吗"}}},fp="25,268,27.373.0,23.330.0,47.136.0,43.178.0,41.171.0,43.163.0,43.162.0,53.181.0"}
P.entries["quest:4904"] = {n="终获自由",s="“重获自由”是一项在黑云峰风吹的尖塔顶端进行的救援任务。拉克塔·风歌是一位被阿纳克·恐怖图腾囚禁的牛头人女性，她需要保护才能从绑架者的堡垒中逃出，并回到乱风岗的朋友萨利亚身边。",h="“重获自由”是一项在黑云峰风吹的尖塔顶端进行的救援任务。拉克塔·风歌是一位被阿纳克·恐怖图腾囚禁的牛头人女性，她需要保护才能从绑架者的堡垒中逃出，并回到乱风岗的朋友萨利亚身边。",kw={"阿纳克·恐怖图腾","黑云峰","护送","重获自由","乱风岗","拉克塔·风歌","萨利亚","千针石林"},ang={["faction:Horde"]="部落将乱风岗视为南部卡利姆多的重要堡垒，因此黑云峰恐怖图腾的无法无天和绑架行为对道路构成了不可容忍的威胁。",["race:Tauren"]="恐怖图腾氏族继续无视牛头人人民的和平与团结，在乱风岗的注视下，通过绑架和谋杀展示了他们的残暴。"},sec={{t="一场残暴的绑架",b="恐怖图腾氏族在千针石林的强势存在不仅仅局限于土地争端。阿纳克·恐怖图腾试图强娶拉克塔·风歌，但当她拒绝了他的追求时，他选择了暴力。阿纳克在深夜返回，在拉克塔的兄弟试图保护她时将其杀害，并强行将她拖到了黑云峰。"},{t="逃离黑云峰",b="黑云峰高耸于千针石林之上，通过高处的木质吊桥连接，这里到处都是敌对的恐怖图腾战士。护送拉克塔需要一边走下山崖，一边击退那些意图在她到达峡谷底部之前将其抓回的恐怖图腾强盗。"},{t="苦涩的重逢",b="一旦安全从山峰上撤下，拉克塔便动身返回乱风岗寻求庇护。她的同伴萨利亚得知消息后感到无比欣慰，但也为拉克塔牺牲的兄弟深感哀恸，她将他遗留的财物作为谢礼，赠予那些将她活着带回家的人。"}},faq={{q="拉克塔·风歌为什么被俘？",a="阿纳克·恐怖图腾意图娶拉克塔·风歌为妻。在她拒绝了求婚后，他在深夜袭击了她的家，杀害了保护她的兄弟，并将她强行拖到了黑云峰。",al={"拉克塔为什么被抓","谁绑架了拉克塔","阿纳克为什么带走拉克塔"}},{q="黑云峰在哪里？",a="黑云峰位于千针石林北部，是一群通过桥梁相连的高耸岩石尖塔，位于升降梯东南方，剃刀高地南方。",al={"黑云峰位置","如何前往黑云峰","拉克塔在哪里"}},{q="阿纳克·恐怖图腾是谁？",a="阿纳克是驻扎在黑云峰的恐怖图腾部族的一名残暴成员。除了绑架拉克塔并杀害她的兄弟外，他还是乱风岗的部落当局下令通缉的罪犯。",al={"阿纳克背景故事","阿纳克是谁","通缉阿纳克"}},{q="营救后应该找谁交谈？",a="一旦拉克塔被安全护送下尖塔并抵达峡谷底部，你必须回到高高的崖顶乱风岗，并与萨利亚交谈。",al={"重获自由任务在哪里交","萨利亚是谁","重获自由交任务"}},{q="为什么恐怖图腾会在逃跑途中袭击？",a="阿纳克的恐怖图腾强盗在黑云峰的高处巡逻，并会积极伏击任何试图帮助他的目标人质重获自由的人。",al={"为什么会有强盗刷出","恐怖图腾强盗护送"}},{q="拉克塔的兄弟发生了什么事？",a="拉克塔的兄弟在最初的绑架中，为了保护她免受阿纳克·恐怖图腾的伤害而遇害。他的传家宝后来由萨利亚作为解救他妹妹的报酬送出。",al={"拉克塔的兄弟","谁为了救拉克塔而死","拉克塔的兄弟怎么了"}}},fx={aa9c9984={q="拉克塔·风歌为什么需要你帮忙逃脱？",a="拉克塔·风歌拒绝了阿纳克·恐怖图腾的求婚后，被他暴力掳走；她的兄弟试图保护她时惨遭杀害。她被困在黑云峰高处，周围全是敌对的恐怖图腾战士，无法独自杀出重围。她急于逃离阿纳克强迫她成婚的企图，并回到乱风岗的萨利亚身边，因此需要你护送她杀出守卫台地的匪徒。",al={"为什么帮助拉克塔·风歌","拉克塔的动机","拉克塔为什么需要护送"}}},fp="12,261,18.346.0,30.295.0,19.306.0,33.200.0,36.174.0,23.214.0,41.153.0,46.148.0,33.182.0"}
P.entries["quest:491"] = {n="给比索的魔杖",s="这个任务通过将一件久已遗失的圣物，狼人魔杖，送回Undercity的比索·埃斯沙德手中，从而结束了对芬里斯城堡的对抗。这根魔杖是多年前由三名法师学徒制作的，象征着友谊，当Thule Ravenclaw选择Scourge时，它便被藏了起来。归还它为比索·埃斯沙德过去的痛苦篇章画上了句号。",h="这个任务通过将一件久已遗失的圣物，狼人魔杖，送回Undercity的比索·埃斯沙德手中，从而结束了对芬里斯城堡的对抗。这根魔杖是多年前由三名法师学徒制作的，象征着友谊，当Thule...",kw={"比索·埃斯沙德","芬里斯岛","芬里斯城堡","magic quarter","银松森林","thule ravenclaw简介","undercity","狼人魔杖"},ang={["class:Mage"]="狼人魔杖代表了一种经典的奥术传统：法师学徒将他们的法器结合在一起以示友谊，这种纯真在Scourge撕裂达拉然和Lordaeron时被粉碎了。",["race:Undead"]="对于像比索·埃斯沙德这样的被遗忘者法师来说，寻回瘟疫前的圣物是一种苦乐参半的提醒，让人想起凡人的抱负以及那些选择了Lich King的暴政而非自由意志的前友人们。"},sec={{t="破碎友谊的象征",b="在Lordaeron沦为废墟很久之前，三位年轻的法师将他们的练习用魔杖结合在一起，制成了一件名为狼人魔杖的单一器具。它本意是象征他们在魔法技艺上的共同纽带和抱负。然而，当Thule Ravenclaw将忠诚转向Lich King并投身Scourge时，那份友谊就此彻底破裂。虽然Thule开始鄙视他们曾经分享的友谊，但他既无法忍受摧毁这根魔杖，也无法接受把它留在前同伴的手中。"},{t="藏在城堡中",b="Thule没有放弃这根魔杖也没有销毁它，而是把它带到了芬里斯岛，并将其藏在了芬里斯城堡内一个满是灰尘的隐蔽架子上。多年来它未曾被触动，其附魔依然处于休眠状态；Thule从未调用过它的魔法，正如比索·埃斯沙德所指出的，那样的行为会立刻暴露它的下落。将其带回Undercity的Magic Quarter，归还了比索·埃斯沙德凡人时期的一件珍贵纪念品，它是从一个既不能爱他的朋友又不能放手的叛徒巢穴中找回的。"}},faq={{q="什么是狼人魔杖？",a="狼人魔杖是一件独特的魔法工具，由Thule Ravenclaw和两名法师学徒同伴在很久以前制作而成，其中一人就是比索·埃斯沙德。每个人都贡献了他们早期的学徒魔杖，将它们编织在一起，作为他们相互友谊和共同奥术研究的实体象征。",al={"狼人魔杖","什么是狼人魔杖","thule ravenclaw魔杖背景"}},{q="为什么Thule Ravenclaw要偷走魔杖？",a="当Thule投靠Lich King时，同事之间的纽带瓦解了。尽管Thule后来开始痛恨它所代表的友谊，但他占有欲太强，不愿放弃这件圣物，也不允许比索·埃斯沙德和他的另一位同伴保留它。相反，他偷走了魔杖并把它藏在芬里斯岛上。",al={"为什么thule拿走魔杖","为什么要偷魔杖","thule ravenclaw偷走的魔杖"}},{q="谁是比索·埃斯沙德？",a="比索·埃斯沙德是一位居住在Undercity的Magic Quarter的强大被遗忘者法师。在生前，在王国崩溃且Thule向Scourge投降之前，他是Thule Ravenclaw的同侪和朋友。",al={"谁是比索·埃斯沙德","比索·埃斯沙德背景故事","比索·埃斯沙德undercity"}},{q="为什么Thule没有使用狼人魔杖的魔法？",a="如果Thule曾经调用过魔杖潜藏的附魔，比索·埃斯沙德就会通过奥术之网感觉到这种共鸣。Thule仅仅出于恶意和占有欲将它藏在芬里斯城堡的一个被遗忘的架子上，使其力量未受触动。",al={"thule ravenclaw用过魔杖吗","魔杖的力量","为什么thule ravenclaw不用魔杖"}},{q="谁是参与制作魔杖的第三位学徒？",a="第三位学徒是冈瑟尔·阿坎努斯，他在Thule背叛很久之前就与比索·埃斯沙德和Thule一起编织了这根魔杖。",al={"第三位学徒是谁","三位法师的魔杖","冈瑟尔·阿坎努斯"}},{q="在被发现之前，魔杖最终在哪里？",a="魔杖被藏在芬里斯城堡内一个隐藏壁龛里满是灰尘的架子上，芬里斯城堡是Thule Ravenclaw在芬里斯岛建立Scourge行动的据点。",al={"魔杖在哪里找到的","隐藏壁龛里的魔杖","芬里斯城堡魔杖"}}},fp="14,270,31.390.0,18.424.1,23.237.0,39.233.0,23.206.0,44.211.0,54.120.0,45.160.0"}
P.entries["quest:492"] = {n="新的瘟疫",s="这个任务标志着药剂师乔汉在布瑞尔代表皇家药剂师学会进行的初步研究迎来了残酷的结局。在横跨提瑞斯法林地采集了毒液、血液和邪恶的混合物后，乔汉派你去恐惧之末旅店的地下室，将他调配的致命药剂喂给一名被俘虏的巡山人。",h="这个任务标志着药剂师乔汉在布瑞尔代表皇家药剂师学会进行的初步研究迎来了残酷的结局。在横跨提瑞斯法林地采集了毒液、血液和邪恶的混合物后，乔汉派你去恐惧之末旅店的地下室，将他调配的致命药剂喂给一名被俘虏的巡山人。",kw={"新瘟疫","药剂师乔汉","布瑞尔","被俘虏的巡山人","恐惧之末","瘟疫","毒药","皇家药剂师学会","提瑞斯法林地"},ang={["faction:Alliance"]="被俘虏的巡山人的命运说明了被遗忘者对在洛丹伦发现的联盟入侵者绝对冷酷无情。",["faction:Horde"]="虽然你的卡利姆多盟友可能为For Honor和生存而战，但被遗忘者通过冷血的炼金战争追求胜利，这种战争不分敌友。",["race:Dwarf"]="这名不幸的囚犯代表了铁炉堡巡山人触角广布的足迹，他们冒着死亡和被秘密审讯的风险来监视提瑞斯法林地。",["race:Undead"]="执行乔汉的实验能让你第一手了解到被遗忘者绝不妥协的生存准则，以及皇家药剂师学会的致命工作。"},sec={{t="一种致命的药剂",b="在你协助药剂师乔汉的这段时间里，你的努力一直在逐步完善一种致命的毒素。皇家药剂师学会代表Sylvanas Windrunner进行着一项雄心勃勃且不可告人的议程：制造一种既能绕过亡灵生物学特性，又能消灭生者的The New Plague。在最后一步中，乔汉酿造了他委婉地称为“特制饮料”的东西，并指派你将其直接喂给一名被囚禁的被遗忘者敌人。"},{t="恐惧之末旅店地下室",b="在布瑞尔的恐惧之末旅店下方，死亡卫队维护着一个潮湿的地下室，用作关押等待审讯或处置的俘虏的临时牢房。其中关押着一名被俘虏的巡山人，他是非法闯入提瑞斯法林地的铁炉堡侦察部队的一名特工。他不屈且口渴，急切地接受了这杯饮料，完全不知道其中真正的炼金药效。"},{t="一次令人毛骨悚然的示范",b="当被递上酒壶时，这名巡山人欣然喝下，甚至满怀渴望地将其与狂想麦酒相提并论，并吹嘘说矮人的蒸汽坦克会来救他。毒药几乎立即生效，当场将他杀死。乔汉临别的话语听起来极其冷酷：这瓶致命的药剂仅仅是黑暗女王为艾泽拉斯其他地区所设想的一小部分。"}},faq={{q="药剂师乔汉是谁？",a="药剂师乔汉是驻扎在提瑞斯法林地布瑞尔镇的皇家药剂师学会的一名成员。他指导了针对被遗忘者战争量身定制的The New Plague的早期研究，并雇佣冒险者从周围的荒野中收集致命的试剂。",al={"药剂师乔汉","谁提供新瘟疫任务","乔汉布瑞尔"}},{q="为什么布瑞尔会关押一名矮人？",a="铁炉堡的巡山人积极在北方王国进行侦察，以监视被遗忘者的动向并调查瘟疫之地。死亡卫队在提瑞斯法抓获了这名侦察兵，并将他关在恐惧之末旅店地下室里，直到药剂师们发现他的用处。",al={"地下室里的矮人","被俘虏的巡山人","为什么矮人在提瑞斯法"}},{q="当你给囚犯喂酒时会发生什么？",a="矮人欣然拿过酒壶，渴望在被俘后解渴。喝下后片刻，这杯毒药便将他当场毒杀，证明了乔汉最新瘟疫配方的残酷效力。",al={"矮人会死吗","饮用结果","巡山人之死"}},{q="The New Plague研究的目的是什么？",a="被遗忘者在Sylvanas Windrunner的命令下试图发明一种The New Plague。他们的目标是开发一种足够强大的生物武器，以摧毁无脑的天灾军团和威胁其主权领土的活着的种族。",al={"为什么要制造新瘟疫","皇家药剂师学会的目标","黑暗女王的瘟疫"}},{q="被俘虏的巡山人在哪里？",a="被俘虏的巡山人被关押在提瑞斯法林地布瑞尔中心地带的恐惧之末旅店楼下的地下室里。",al={"寻找被俘虏的矮人","恐惧之末旅店地下室","巡山人在哪里"}},{q="这个任务线在处理完这名矮人之后还会继续吗？",a="这项针对药剂师乔汉的四部分任务随着巡山人的死亡而结束。然而，对The New Plague的研究仍然是洛丹伦各地的一项核心且持续的努力，并将引导你前往幽暗城和瑟伯切尔进行进一步的测试任务。",al={"下一个任务","新瘟疫后续","巡山人死后"}}},fp="12,196,19.318.0,23.318.0,24.308.1,25.222.0,39.236.0,50.171.1,47.192.0,42.124.0,49.178.0"}
P.entries["quest:4921"] = {n="在战斗中失踪",s="“迷失在战场上”是一项由贫瘠之地十字路口的受伤兽人曼科里克提供的令人心酸的任务。在一次毁灭性的刺鬃野猪人伏击使他与妻子在附近的牛头人营地失散后，曼科里克请求过往的冒险者在危险的灌木丛中寻找她命运的任何线索。",h="“迷失在战场上”是一项由贫瘠之地十字路口的受伤兽人曼科里克提供的令人心酸的任务。在一次毁灭性的刺鬃野猪人伏击使他与妻子在附近的牛头人营地失散后，曼科里克请求过往的冒险者在危险的灌木丛中寻找她命运的任何线索。",kw={"刺鬃","十字路口","黄金之路","迷失在战场上","曼科里克","曼科里克的妻子","野猪人","牛头人营地"},ang={["class:Druid"]="一位路经黄金之路的牛头人德鲁伊恰好在曼科里克倒下时发现了他，并为他处理了严重的伤口，保住了他的性命。",["faction:Horde"]="曼科里克的绝望恳求展现了在充满纷争的贫瘠之地，部落定居者和巡逻队在面对刺鬃野猪人时所面临的危险。",["race:Orc"]="曼科里克以传统的兽人战斗狂怒奋勇战斗，试图保卫他的伴侣，最终却被野猪人群淹没。",["race:Tauren"]="伏击发生在一个小型牛头人营地，是一位路过的牛头人德鲁伊在黄金之路上处理了曼科里克的伤口并挽救了他的生命。"},sec={{t="营地伏击战",b="该任务始于驻扎在贫瘠之地十字路口的兽人战士曼科里克。当他和妻子在一个小型牛头人营地并肩作战时，两人突然遭到了刺鬃野猪人群的伏击。在激战中，他的妻子独自抵挡了三只野猪人，随后被源源不断的敌方增援部队包围，两人在战斗中失散。"},{t="绝望的搜寻",b="曼科里克陷入了盲目的愤怒，转身对抗不断逼近的野猪人，但对方庞大的数量轻易地将他击倒。他奄奄一息时，被一位路过的牛头人德鲁伊在黄金之路上发现，德鲁伊处理了他的伤口并挽救了他的生命。由于伤势严重无法亲自寻找，曼科里克恳求途经十字路口的旅行者搜寻贫瘠之地，带回关于他挚爱妻子的任何线索。"}},faq={{q="谁是曼科里克？",a="曼科里克是一位目前正在贫瘠之地十字路口休养的兽人战士。在遭受了一次导致他与妻子失散的残酷野猪人袭击后，他依靠过往的旅人去搜寻灌木丛，寻找她的任何踪迹。",al={"谁是曼科里克","谁发布了这个任务","曼科里克的背景故事"}},{q="曼科里克的妻子在战斗中遭遇了什么？",a="当曼科里克和他的妻子在一个小型牛头人营地并肩作战时，他们遭到了刺鬃野猪人的伏击。他的妻子独自抵挡了三名攻击者，随后被增援的敌人包围，曼科里克在混乱中与她失散。",al={"曼科里克的妻子发生了什么","他的妻子在哪里","曼科里克妻子的袭击"}},{q="曼科里克是如何从野猪人的伏击中幸存下来的？",a="曼科里克被压制并倒在战场上之后，一位路过的牛头人德鲁伊在黄金之路上发现了他，并在他伤重不治前处理了他致命的伤口。",al={"谁救了曼科里克","曼科里克是如何幸存的","黄金之路上的德鲁伊"}},{q="是谁袭击了曼科里克和他的妻子？",a="袭击者是成群结队突袭小型牛头人定居点的刺鬃野猪人。尽管曼科里克和他的妻子进行了顽强抵抗，但对方庞大的数量还是压制了他们。",al={"谁袭击了他们","贫瘠之地的野猪人","刺鬃袭击者"}},{q="旅行者应该去哪里寻找曼科里克的妻子？",a="曼科里克在被刺鬃野猪人占领的小型牛头人营地附近倒下，随后在黄金之路被发现。寻找她的旅行者通常从侦察贫瘠之地中野猪人出没的区域开始。",al={"我该去哪找她","在哪寻找曼科里克的妻子"}},{q="现在可以在哪里找到曼科里克？",a="曼科里克目前正在贫瘠之地的部落中心据点——十字路口休养，焦急地等待着关于他失踪妻子的任何消息或线索。",al={"为什么在十字路口","曼科里克现在在哪"}}},fp="14,201,18.238.0,18.333.0,15.176.0,50.218.0,44.151.0,34.144.0,47.180.0,31.106.0"}
P.entries["quest:493"] = {n="前往希尔斯布莱德丘陵",s="前往希尔斯布莱德丘陵之旅是一项部落的信使任务，旨在连接被遗忘者在银松森林的研究工作与他们在塔伦米尔的前哨站。旅行者受托携带药剂师伦弗利尔的机密笔记，南下前往充满争议的希尔斯布莱德丘陵，将重要的生物学研究成果送达药剂师林度恩手中。这份快报反映了希尔瓦娜斯·风行者女士对皇家药剂师协会施加的巨大压力，要求他们制造出大规模杀伤性武器。",h="前往希尔斯布莱德丘陵之旅是一项部落的信使任务，旨在连接被遗忘者在银松森林的研究工作与他们在塔伦米尔的前哨站。旅行者受托携带药剂师伦弗利尔的机密笔记，南下前往充满争议的希尔斯布莱德丘陵，将重要的生物学研究成果送达药剂师林度...",kw={"希尔斯布莱德","林度恩","新瘟疫","伦弗利尔","皇家药剂师协会","银松森林","希尔瓦娜斯","塔伦米尔"},ang={["faction:Horde"]="虽然兽人和牛头人通常不喜欢阴险的毒药，但帮助巩固被遗忘者在希尔斯布莱德的统治地位，能确保部落在东部王国的立足点。",["profession:Herbalism"]="伦弗利尔和林度恩进行的研究在很大程度上依赖于对洛丹伦土地上生长的剧毒变异植物的研究和采集。",["race:Undead"]="对于被遗忘者来说，传递这些研究成果是对他们种族的生存以及对活人和天灾军团复仇的直接贡献。"},sec={{t="他们自己的瘟疫",b="自摆脱巫妖王的铁腕统治以来，希尔瓦娜斯·风行者女士便怀揣着一个坚定的目标：开发一种新的瘟疫，旨在彻底根除活着的敌人和天灾军团。为了实现这一目标，皇家药剂师协会在女妖之王的严厉督促下持续运作。由于距离阻隔了他们的实验室，散布在洛丹伦各地的研究人员必须不断共享原始化学数据和实验结果，以加速他们的险恶突破。"},{t="南下之路",b="药剂师伦弗利尔在银松森林的瑟伯切尔开展工作，他指派信使将最近的研究成果送交他的同事药剂师林度恩。这段旅程向南蜿蜒，穿过阴暗的松树林，进入希尔斯布莱德丘陵开阔的起伏牧场。在那里，坐落在奥特兰克山脉脚下的是塔伦米尔——一个重要的被遗忘者枢纽和实验室基地。"}},faq={{q="伦弗利尔的研究成果里有什么？",a="伦弗利尔的研究成果包含详细记录了他对当地动物、植物和生物毒素进行实验的研究文档。它们是皇家药剂师协会为研制他们梦寐以求的“新瘟疫”而拼凑出的庞大配方的一部分。",al={"什么是研究成果","伦弗利尔的研究","我正在运送什么"}},{q="为什么皇家药剂师协会如此匆忙？",a="希尔瓦娜斯·风行者女士要求立即见到成果。在敌对人类残党、狂热的血色十字军和游荡的天灾军团包围下，被遗忘者认为只有一种决定性的生物武器才能保证他们的生存，并向阿尔萨斯复仇。",al={"为什么瘟疫要赶工","为什么压力这么大","希尔瓦娜斯的压力"}},{q="药剂师林度恩是谁？",a="药剂师林度恩是皇家药剂师协会驻扎在塔伦米尔的一名资深研究员。他深受伦弗利尔等同僚的尊敬，林度恩在希尔斯布莱德丘陵监管致命的生物实验，利用当地的资源和俘虏来改良瘟疫菌株。",al={"林度恩是谁","药剂师林度恩背景故事"}},{q="塔伦米尔在哪里？",a="塔伦米尔位于希尔斯布莱德丘陵北部，奥特兰克山脉以南，银松森林以东。从银松森林沿主路向南走，在十字路口向东转，即可直达该定居点。",al={"塔伦米尔位置","如何前往塔伦米尔","希尔斯布莱德在哪里"}},{q="为什么被遗忘者必须通过徒步信使来分享研究成果？",a="伦弗利尔请求一名旅行者将他的书面研究成果从瑟伯切尔带给塔伦米尔的林度恩。他希望协会里相距遥远的研究人员能快速分享各自的发现；他并未解释为何不使用魔法手段。",al={"为什么使用徒步信使","为什么需要信使递送"}},{q="林度恩收到研究成果后会发生什么？",a="收到包裹后，药剂师林度恩会立即开始研究伦弗利尔的笔记，将其整合到自己的配方中，并最终指派冒险者在当地人类居民身上测试改良后的菌株。",al={"交付后会发生什么","林度恩的反应"}}},fp="30,192,21.352.0,14.339.0,36.167.0,51.211.0,24.251.0,21.202.0,61.235.0,43.207.1"}
P.entries["quest:494"] = {n="进攻的时机",s="“出击之时”是一项部落侦查任务，通过将侦察兵从希尔斯布莱德丘陵边界引向塔伦米尔军事枢纽，从而推进任务进程。将亡灵哨兵莱什的加密信号传递给高级执行官达萨利亚，标志着任务重心从静默监视转向针对当地人类居民的有组织进攻行动。",h="“出击之时”是一项部落侦查任务，通过将侦察兵从希尔斯布莱德丘陵边界引向塔伦米尔军事枢纽，从而推进任务进程。将亡灵哨兵莱什的加密信号传递给高级执行官达萨利亚，标志着任务重心从静默监视转向针对当地人类居民的有组织进攻行动。",kw={"亡灵哨兵莱什","高级执行官达萨利亚","希尔斯布莱德","希尔斯布莱德丘陵","侦查","塔伦米尔","瓦里玛萨斯"},ang={["class:Rogue"]="莱什的秘密岗哨和加密通信反映了亡灵哨兵（幽暗城的精英刺客与侦察兵组织）的特工手段。",["faction:Horde"]="这封公文将非亡灵部落盟友更深地卷入了被遗忘者与南部人类定居点之间爆发的战略冲突中。",["race:Undead"]="对于被遗忘者特工来说，运送莱什的公文有助于巩固洛丹伦的东部边境，抵御人类联盟的残余势力。"},sec={{t="边界的守望者",b="亡灵哨兵莱什驻守在银松森林和希尔斯布莱德丘陵边界附近的高地上，监视着山谷中人类定居者和民兵的动向。亡灵哨兵是幽暗城的耳目，负责在任何军事部署前勘察敌方定居点。为了不放弃监视哨位，莱什委托过往的部落旅行者将收集到的情报沿路送往塔伦米尔。"},{t="加密的召唤",b="莱什发送的信息经过了刻意伪装：“来自西方的渡鸦之啼正在召唤。”这条信号沿着大路向东传递，告知高级执行官达萨利亚，希尔斯布莱德镇周围的人类防御力量十分脆弱。对于达萨利亚和恐惧魔王瓦里玛萨斯来说，这确认了调动被遗忘者部队、对希尔斯布莱德的人类守军展开攻势的时机已经到来。"}},faq={{q="亡灵哨兵莱什的消息是什么意思？",a="“来自西方的渡鸦之啼正在召唤”这句话是一条加密的侦查情报更新。它向高级执行官达萨利亚传达了一个信号：希尔斯布莱德的西方防线防御不足，正是发起突然进攻的时机。",al={"渡鸦之啼的含义","渡鸦之啼是什么意思","莱什的消息"}},{q="谁是高级执行官达萨利亚？",a="高级执行官达萨利亚是被遗忘者在希尔斯布莱德丘陵的最高军事指挥官。她在防御严密的塔伦米尔小镇坐镇，指挥针对南海镇人类的攻势，并与幽暗城的瓦里玛萨斯紧密协调战略行动。",al={"谁是达萨利亚","达萨利亚的职责"}},{q="为什么莱什不亲自去送信，而要派信使？",a="莱什正全身心投入在希尔斯布莱德西侧的一项关键侦查任务中。离开岗位会导致被遗忘者的监视出现盲区，因此她必须依靠过往的部落旅行者来传递紧急公文。",al={"为什么莱什不能离开","为什么使用信使"}},{q="这条消息要送到哪里？",a="这条消息必须沿着希尔斯布莱德丘陵的大路向东送到塔伦米尔，那是部落在该地区的主要据点。",al={"我该去哪","消息目的地"}},{q="为什么瓦里玛萨斯会卷入希尔斯布莱德的事务？",a="作为Sylvanas Windrunner的首席副官和恐惧魔王顾问，瓦里玛萨斯在幽暗城的Royal Quarter统筹着被遗忘者军事和战略规划的重要部分。高级执行官达萨利亚则负责在他的前线执行战役指令。",al={"瓦里玛萨斯与希尔斯布莱德","为什么是瓦里玛萨斯"}},{q="收到这条消息后会发生什么？",a="一旦达萨利亚确认希尔斯布莱德防线脆弱，她就会授权发动激进的攻势，派遣部落勇士去摧毁希尔斯布莱德镇的农场、民兵和基础设施。",al={"接下来会发生什么","出击之时任务后续"}}},fp="14,176,23.406.0,14.353.1,43.206.0,31.215.0,54.209.0,44.145.0,51.268.0,44.182.0"}
P.entries["quest:496"] = {n="受难药剂",s="在塔伦米尔，药剂师林度恩执行着皇家药剂师学会那冷酷的使命，即研制针对生者的致命混合药剂。为了推进他那令人毛骨悚然的实验，他招募旅者从周边的丘陵收集动物试剂。",h="在塔伦米尔，药剂师林度恩执行着皇家药剂师学会那冷酷的使命，即研制针对生者的致命混合药剂。为了推进他那令人毛骨悚然的实验，他招募旅者从周边的丘陵收集动物试剂。",kw={"药剂师林度恩","食苔蛛的毒液","受难药剂","灰熊的舌头","希尔斯布莱德丘陵","皇家药剂师学会","塔伦米尔"},ang={["faction:Horde"]="虽然其他部落盟友可能会对这种冷酷无情的生物实验望而却步，但为了保卫塔伦米尔前线对抗南海镇，必须信任被遗忘者的炼金战术。",["race:Undead"]="对于被遗忘者的特工来说，协助林度恩能够推进皇家药剂师学会的核心抱负：创造一种毁灭性的武器，以确保他们的人民在面对活人时能够生存下去。"},sec={{t="剧毒事业",b="塔伦米尔不仅是希尔斯布莱德丘陵中被遗忘者的军事堡垒，也是皇家药剂师学会的一个活跃研究站。身处这片风景如画的绿色地带，药剂师林度恩却厌恶这片纯净的乡村，并渴望看到人类定居点被毒害和征服。为了制造他的实验性“受难药剂”，他需要当地具有强效和剧毒性的生物试剂。"},{t="收集试剂",b="开发炼金瘟疫需要精确的成分。林度恩指引猎人们前往塔伦米尔周边的野外，收集当地灰熊的舌头，以及食苔蛛分泌的稀有毒液。这些有机液体在经过邪恶炼金术的提炼后，将成为一种致命混合药剂的基础，旨在消灭希尔斯布莱德境内的生者入侵者。"}},faq={{q="药剂师林度恩是谁？",a="药剂师林度恩是驻扎在塔伦米尔的皇家药剂师学会的一员。秉承被遗忘者的炼金传统，他厌恶希尔斯布莱德洁净、充满生机的景观，并将时间致力于合成强效毒药以消灭人类族群。",al={"药剂师林度恩","谁提供受难药剂任务","林度恩 塔伦米尔"}},{q="为什么林度恩需要熊舌和食苔蛛毒液？",a="林度恩正在研究剧毒杀人药剂，并将它们调制成致命的混合物。灰熊舌头的生物特性和食苔蛛的腐蚀性分泌物，为他新的受难药剂提供了所需的挥发性炼金基础。",al={"为什么需要熊舌","食苔蛛毒液有什么用","药剂成分背景知识"}},{q="这个任务接下来的走向是什么？",a="一旦基础试剂送到，林度恩就会将它们调制成原型药剂。随后，他会要求对这剂药水进行测试，以衡量其对生者的致命效力。",al={"受难药剂后续任务","完成受难药剂后会发生什么"}},{q="皇家药剂师学会在希尔斯布莱德的目标是什么？",a="该学会在Sylvanas Windrunner的指挥下运作，旨在研制出一种能够同时消灭人类和天灾军团的炼金瘟疫。塔伦米尔是一个理想的前哨基地，用于采集生物物质并针对当地的联盟部队测试原型。",al={"为什么药剂师在希尔斯布莱德","被遗忘者的毒药目标","希尔斯布莱德瘟疫"}},{q="在哪里可以找到所需的生物？",a="灰熊广泛游荡在希尔斯布莱德丘陵的中心田野和森林中，而食苔蛛则潜伏在塔伦米尔外围的灌木丛和林地中。",al={"灰熊在哪里","食苔蛛在哪里","熊和蜘蛛的位置"}},{q="为什么林度恩心情这么不好？",a="和许多被遗忘者炼金师一样，林度恩厌恶活力、清新的空气和繁茂的自然。他只在死亡、腐朽以及成功提炼出致命毒素中找到乐趣。",al={"为什么林度恩不高兴","林度恩 清新空气"}}},fp="19,147,18.366.0,18.265.0,24.187.0,51.185.0,32.157.1,62.268.0,43.145.0,32.134.0"}
P.entries["quest:4966"] = {n="保护卡纳提·灰云",s="“保护卡纳提·灰云”是千针石林白沙岗哨的一项部落任务。有情报显示半人马刺客已经盯上了牛头人卡纳提·灰云，冒险者必须与他并肩作战，击退一队加拉克刺客。",h="“保护卡纳提·灰云”是千针石林白沙岗哨的一项部落任务。有情报显示半人马刺客已经盯上了牛头人卡纳提·灰云，冒险者必须与他并肩作战，击退一队加拉克刺客。",kw={"暗杀阴谋","刺客","半人马","加拉克","卡纳提·灰云","千针石林","白沙岗哨"},ang={["faction:Horde"]="白沙岗哨是千针石林的关键制高点，让像卡纳提这样的岗哨守卫存活对于确保整个峡谷的部落行动至关重要。",["race:Tauren"]="牛头人与半人马之间的血海深仇根深蒂固，因此保护一位同胞免受卑鄙的暗杀就成了一件关乎生存与荣誉的大事。"},sec={{t="揭露的伏击",b="当牛头人卡纳提·灰云驻扎在白沙岗哨高耸的砂岩尖塔之间时，他从截获的半人马命令中得知，有一场针对他个人的暗杀阴谋。加拉克半人马部族不仅疯狂地敌视游牧的牛头人及其部落盟友，而且不满足于仅仅袭击补给路线，他们企图清除所有在峡谷中定居的人。"},{t="保卫白沙岗哨",b="意识到袭击迫在眉睫，且怀疑敌军数量超出了最初的估计，卡纳提请求岗哨里的旅者与他并肩作战。当加拉克刺客发起攻击时，卡纳提坚守阵地，依靠盟友的刀刃和法术在半人马得手前粉碎了这场伏击。"}},faq={{q="卡纳提·灰云是谁？",a="卡纳提·灰云是一位牛头人，他在千针石林的白沙岗哨建立了一个狩猎营地，那里靠近当地半人马氏族声称拥有的峡谷。",al={"卡纳提是谁","卡纳提·灰云背景故事","任务发布者是谁"}},{q="为什么半人马要暗杀他？",a="当地的加拉克半人马将牛头人及其部落营地视为侵入他们峡谷领地的敌人。通过杀死卡纳提，半人马意图将他的狩猎营地以及任何可能追随他的人从峡谷中清除出去。",al={"为什么半人马攻击卡纳提","半人马暗杀原因","暗杀阴谋起因"}},{q="这场防御战在哪里进行？",a="伏击直接发生在白沙岗哨，这是一个位于千针石林峡谷小径沿线的小型部落据点。",al={"任务在哪里","保护卡纳提地点","伏击发生在何处"}},{q="是哪个半人马氏族袭击了卡纳提·灰云？",a="这些刺客隶属于加拉克部族，这是栖息在千针石林峡谷和沟壑中的主要半人马氏族。",al={"哪个部族攻击","刺客是谁","哪种半人马"}},{q="刺客被击败后会发生什么？",a="随着加拉克刺客被消灭，卡纳提的生命得到了保全，白沙岗哨也保持了安全。卡纳提感谢了他的保卫者在突袭中与他并肩作战，成功结束了这场防御系列任务。",al={"后续会发生什么","任务后续","保护卡纳提之后"}},{q="卡纳提·灰云会参与战斗吗？",a="会。卡纳提并没有退缩或逃跑；他积极加入了战斗，与任何响应他请求的人并肩作战，拼死击退了前来终结他守望的刺客。",al={"卡纳提会帮忙吗","卡纳提战斗","卡纳提是消极的吗"}}},fx={["792f0095"]={q="袭击卡纳提·灰云的半人马是谁？",a="袭击者是加拉克半人马部族派来的刺客，他们深入白沙岗哨发动袭击。卡纳提·灰云竟敢在他们的峡谷里建立狩猎营地，这令他们勃然大怒，于是他们派出一支专门的杀手小队，打算在卡纳提的营地里杀死这名牛头人猎手，并赶走任何可能追随他的人。",al={"刺客是谁","保护卡纳提免受刺客袭击","袭击的是哪个半人马部族"}},e12a4220={q="为什么卡纳提·灰云需要你帮忙守卫岗哨？",a="卡纳提是一名身手不凡的牛头人战士，会与你并肩作战，但他意识到半人马派来的刺客数量超出了他独自应付的能力。白沙岗哨位置偏僻，几乎没有援军能及时赶到；你的加入将决定他们能否击退伏击，还是会被敌人击溃。",al={"卡纳提为什么需要帮助","为什么让我保护卡纳提","卡纳提能独自战斗吗"}}},fp="24,233,18.405.0,25.318.0,24.163.0,46.224.0,35.137.0,44.123.0,46.219.1,42.158.0"}
P.entries["quest:498"] = {n="拯救行动",s="“救援”是部落早期任务，由塔伦米尔的克鲁斯克发起，要求英雄潜入敦霍尔德城堡，解救被俘的兽人斥候。萨尔派出的斥候奉命前往敦霍尔德取回一件物品，却遭到伏击，落入残暴的人类犯罪团伙辛迪加手中。",h="“救援”是部落早期任务，由塔伦米尔的克鲁斯克发起，要求英雄潜入敦霍尔德城堡，解救被俘的兽人斥候。萨尔派出的斥候奉命前往敦霍尔德取回一件物品，却遭到伏击，落入残暴的人类犯罪团伙辛迪加手中。",kw={"德鲁尔","敦霍尔德城堡","戈德","希尔斯布莱德","克鲁斯克","辛迪加","塔伦米尔","托格萨"},ang={["class:Warrior"]="从囚禁中解救前线战友，强化了对抗无耻人类强盗的武者兄弟情谊。",["faction:Horde"]="这项任务标志着部落早期为应对辛迪加在洛丹伦争议丘陵地区的扩张所采取的行动。",["race:Orc"]="看到兽人战士被锁链困在敦霍尔德城堡内，这直接触及了痛苦的集中营历史，使得解救他们的任务具有深远的个人意义。"},sec={{t="斥候任务的失败",b="大酋长萨尔派遣一支精锐兽人战士小队前往希尔斯布莱德丘陵，命令他们秘密调查日益猖獗的辛迪加威胁，并从敦霍尔德城堡取回一件物品。在戈尔迪尔的带领下，斥候小队接近了堡垒废墟。然而，辛迪加人数众多，他们在伏击中被彻底击溃。战士克鲁斯克设法突围，跛着腿渡河返回塔伦米尔；他的同伴德鲁尔、托格萨尔和戈尔迪尔则被活捉，戴上了人类的镣铐。"},{t="废墟中的锁链",b="敦霍尔德对兽人来说有着痛苦的回忆，它曾是埃德拉斯·布莱克摩尔的集中营总部，被俘的兽人在那里被迫忍受昏睡的折磨和角斗奴隶的苦役。看到自己的战士再次被囚禁在敦霍尔德龟裂的石墙内，这对部落来说是无法忍受的羞辱。为了救出德鲁尔和托格萨，救援者必须面对持有枷锁钥匙的辛迪加狱卒，随后查明他们的指挥官戈德的下落。"}},faq={{q="兽人为何会被派往敦霍尔德城堡？",a="大酋长萨尔派遣戈尔迪尔及其斥候小队调查辛迪加匪徒，并从敦霍尔德城堡取回一件物品。",al={"他们为何出现在那里","为何是敦霍尔德","克鲁斯克的任务"}},{q="被营救的俘虏是谁？",a="德鲁尔和托格萨是部落派出的兽人斥候，受戈德指挥。他们在废墟内遭到压制，并被辛迪加强盗用镣铐锁住。",al={"德鲁尔是谁","托格萨是谁","人质是谁"}},{q="小队领队戈德在哪里？",a="当德鲁尔和托格萨被释放后，克鲁斯克发现他们的指挥官戈德已经与主力部队失散，并被辛迪加转移到了另一个未知的地点。",al={"戈德在哪里","寻找戈德","戈德发生了什么"}},{q="是谁在关押这些斥候？",a="他们被辛迪加关押。辛迪加是一个活跃于洛丹伦废墟和奥特兰克的贵族犯罪网络，直接由敦霍尔德内部的辛迪加狱卒看守。",al={"谁俘虏了他们","狱卒是谁","谁掌控着敦霍尔德"}},{q="这个任务线后续会如何发展？",a="解救斥候后，任务将直接引向追踪并潜入辛迪加，营救戈尔迪尔，最终进一步揭开辛迪加的内幕。",al={"what comes next","营救之后","营救任务链"}},{q="为什么敦霍尔德城堡对部落有特殊意义？",a="敦霍尔德是埃德拉斯·布莱克摩尔将萨尔培养成角斗士的地方，也是第二次战争后他指挥联盟集中营系统的地方，直到萨尔发动起义并摧毁了这座城堡。",al={"敦霍尔德的历史","为何部落在意敦霍尔德"}}},fp="10,203,26.400.0,19.423.1,58.125.0,35.163.0,37.153.1,34.169.0,33.174.1,58.190.0"}
P.entries["quest:499"] = {n="受难药剂",s="在塔伦米尔，药剂师林度恩调制了一种毒药，旨在推进皇家药剂师学会的邪恶工作。为了确认其致死性，他下令立即在附近他那倒霉的同伴身上进行活体试验。",h="在塔伦米尔，药剂师林度恩调制了一种毒药，旨在推进皇家药剂师学会的邪恶工作。为了确认其致死性，他下令立即在附近他那倒霉的同伴身上进行活体试验。",kw={"药剂师林度恩","受难药剂","希尔斯布莱德丘陵","毒药","皇家药剂师学会","塔伦米尔","蟾蜍","乌比"},ang={["class:Druid"]="德鲁伊可能会对以被遗忘者战争之名随意、冷酷地毒杀一只无害两栖动物的行为感到深深的不安。",["faction:Horde"]="访问塔伦米尔的盟友可以亲眼目睹皇家药剂师学会所实践的残酷炼金手段，这令人不寒而栗。",["race:Undead"]="对于被遗忘者来说，测试致命毒素是履行希尔瓦娜斯女王铲除天灾军团和生者的法令的一项重要工作。"},sec={{t="毒性测试",b="药剂师林度恩在塔伦米尔不知疲倦地工作，致力于开发能够实现黑暗女王宏伟野心的化学武器：一种能够消灭联盟中的活人以及天灾军团中的亡灵怪物的瘟疫。一旦必要的试剂被收集并浸泡完成，林度恩就会将这种邪恶的药水混合成他所称的受难药剂，并急于见证其原始效力，以便随后将其大规模部署。"},{t="乌比的命运",b="林度恩没有去寻找敌方的俘虏或逃跑的野兽，而是直接转向了他身边的生物。他指使探险者将刚调配好的毒药喂给他的助手——乌比，一只静静地蹲在他脚边的无害蟾蜍。只需一剂这种药剂就产生了迅速的灾难性后果，当场杀死了这只两栖动物，并让这位药剂师确信他的致命配方正如预期般运作。"}},faq={{q="谁是药剂师林度恩？",a="药剂师林度恩是一位代表皇家药剂师学会的炼金术士，驻扎在希尔斯布莱德丘陵的被遗忘者定居点塔伦米尔。他整日都在精炼各种毒药和炼金混合物，旨在消灭被遗忘者的敌人。",al={"林度恩","谁是林度恩","药剂师林度恩 塔伦米尔"}},{q="谁是乌比？",a="乌比是一只平凡的蟾蜍，就蹲在塔伦米尔药剂师林度恩的工作台旁边，被林度恩戏称为他的助手。",al={"乌比是什么","蟾蜍乌比","谁是助手"}},{q="受难药剂的用途是什么？",a="受难药剂是一种实验性化学武器，旨在代表希尔瓦娜斯·风行者测试用以根除活人人类和亡灵天灾军团的毒性配方。",al={"药剂有什么作用","为什么要制造受难药剂"}},{q="给乌比喂食这种药水会发生什么？",a="林度恩会要求你让乌比尝一点，看看新调配的药剂是否达到了预期的效果。测试结果将在过程中揭晓。",al={"乌比会死吗","蟾蜍怎么样了"}},{q="这项测试在哪里进行？",a="测试在希尔斯布莱德丘陵北部的被遗忘者城镇塔伦米尔内进行，就在林度恩的酿造工作台旁。",al={"林度恩在哪里","在哪里可以找到乌比"}},{q="为什么皇家药剂师学会要在小动物身上测试毒药？",a="被遗忘者药剂师习惯使用小动物和害虫进行初步试验，以验证其化合物的速度和致死性，然后再推进到针对更大目标或活体俘虏的实地测试。",al={"为什么要用蟾蜍测试","药剂师学会动物测试"}}},fp="19,151,12.377.0,16.252.1,24.211.0,12.112.0,47.168.0,46.115.1,32.112.0,68.175.0"}
P.entries["quest:5"] = {n="饥肠辘辘的基特斯",s="流浪汉基特斯被困在乌鸦岭的废墟中，终日提心吊胆。在依靠杂草和昆虫度日后，他对真正的食物感到极度渴望。他恳求路过的冒险者前往东边的夜色镇，说服厨师格鲁奥制作一份他心心念念的黑蟹蛋糕。",h="流浪汉基特斯被困在乌鸦岭的废墟中，终日提心吊胆。在依靠杂草和昆虫度日后，他对真正的食物感到极度渴望。他恳求路过的冒险者前往东边的夜色镇，说服厨师格鲁奥制作一份他心心念念的黑蟹蛋糕。",kw={"厨师格鲁奥","黑蟹蛋糕","夜色镇","咕咕作响的肚子","基特斯","乌鸦岭","scarlet raven tavern"},ang={["faction:Alliance"]="向基特斯提供援助，能让旅行者们与那些在暮色森林阴影角落中挣扎求生、苦苦坚持的定居点和幸存者建立联系。",["profession:Cooking"]="厨师格鲁奥那著名的黑蟹蛋糕展示了边境的烹饪大师们是如何在常规物资无法运抵暮色森林时，利用当地的异域食材来解决问题的。"},sec={{t="在乌鸦岭忍饥挨饿",b="乌鸦岭已成为贪婪亡灵和潜伏野兽的巢穴，性情古怪的隐士基特斯被迫躲藏起来已有数周之久。在永恒的阴霾笼罩下，他穿行于破败的棚屋之间，仅仅依靠挖掘地下的幼虫和野草为生。由于极度缺乏文明社会的慰藉，他的神经和胃都已被逼到了极限。"},{t="对蟹蛋糕的渴望",b="基特斯极度渴望寻找一丝安全的慰藉，他梦寐以求的是夜色镇的Scarlet Raven Tavern里制作的调味肉饼。他派旅行者穿过那条闹鬼的道路去寻找厨师格鲁奥，希望格鲁奥能同意做一批黑蟹蛋糕，好安抚他那咕咕作响的肚子。"}},faq={{q="基特斯是谁？",a="基特斯是一个饱受惊吓、疑神疑鬼的人，正躲在暮色森林西部的乌鸦岭废墟中。他非常害怕亡灵的侵扰，时刻生活在饥饿和被杀戮的恐惧之中。",al={"基特斯","基特斯是谁","基特斯在哪里"}},{q="我在哪里可以找到厨师格鲁奥？",a="厨师格鲁奥在Scarlet Raven Tavern的厨房工作，这家酒馆位于暮色森林东侧的夜色镇。",al={"厨师格鲁奥位置","寻找格鲁奥","scarlet raven tavern厨师"}},{q="为什么基特斯要吃幼虫？",a="由于成群结队的亡灵和凶残的狼人阻断了与文明社会的联系，基特斯已经在乌鸦岭的废墟中被困数周，除了能找到的一些昆虫和植物外，没有任何补给。",al={"基特斯吃虫子","为什么吃幼虫","乌鸦岭食物"}},{q="基特斯想吃什么菜？",a="基特斯渴望的是黑蟹蛋糕，这是厨师格鲁奥在Scarlet Raven Tavern制作的一种地区特色美食。",al={"基特斯的食物","蟹蛋糕任务","基特斯想吃什么"}},{q="和厨师格鲁奥谈话后会发生什么？",a="厨师格鲁奥愿意为基特斯烹饪这道菜，但他缺少新鲜的食材，因此委托冒险者去收集粘糊糊的蜘蛛腿，以便制作黑蟹蛋糕。",al={"基特斯的咕咕作响的肚子之后","基特斯的咕咕作响的肚子后续任务","厨师格鲁奥的任务"}},{q="部落玩家可以完成这个任务吗？",a="不能。基特斯和夜色镇都属于联盟阵营，这使得该任务仅限于联盟冒险者。",al={"基特斯是联盟专属吗","部落 基特斯的咕咕作响的肚子"}}},fp="21,182,22.324.0,21.260.0,15.171.0,28.103.0,28.184.0,28.98.0,44.137.1,38.99.0"}
P.entries["quest:500"] = {n="破碎岭食人魔",s="南海镇的治安官雷德帕斯发出警告，称碎颅食人魔已经定居在奥特兰克废墟并将其占为己有。任何愿意前往北方的奥特兰克山脉猎杀他们的人，都将获得赏金。",h="南海镇的治安官雷德帕斯发出警告，称碎颅食人魔已经定居在奥特兰克废墟并将其占为己有。任何愿意前往北方的奥特兰克山脉猎杀他们的人，都将获得赏金。",kw={"奥特兰克","赏金","碎颅","指节骨","食人魔","雷德帕斯","南海镇"},sec={{t="家门口的食人魔",b="雷德帕斯的斥候报告说，碎颅食人魔在奥特兰克山脉靠近那座废弃城市的地方挖掘了一个土堆，并占领了废墟。雷德帕斯绝不会让他们过得安稳：如果食人魔觉得安全了，就会向下移动到山麓地带，直逼南海镇。因此，雷德帕斯派遣你向北猎杀食人魔，并带回他们身上携带的肮脏的指节骨作为凭证，以换取赏金。"}},faq={{q="为什么治安官雷德帕斯要猎杀碎颅食人魔？",a="雷德帕斯担心这些食人魔会在他们的土堆和奥特兰克废墟中感到安逸，然后向下进入山麓地带，那样他们就会兵临南海镇城下。",al={"为什么要杀死碎颅食人魔","雷德帕斯的动机","悬赏食人魔的原因"}},{q="碎颅食人魔在哪里？",a="在北方的奥特兰克山脉，他们在奥特兰克废弃城市附近筑起了一个土堆。雷德帕斯的斥候说他们也占领了废墟。",al={"食人魔的位置","碎颅食人魔在哪里","在哪里可以找到指节骨"}},{q="治安官雷德帕斯想要带回什么？",a="九个肮脏的指节骨，这是碎颅食人魔携带的战利品，需带回给南海镇的雷德帕斯。",al={"我要带给雷德帕斯什么","食人魔的凭证","肮脏的指节骨"}}},fp="17,202,17.386.0,58.161.0,31.145.0,44.98.0"}
P.entries["quest:501"] = {n="痛苦药剂",s="这项任务由塔伦米尔的药剂师林度恩委派，要求部落的冒险者收集山地狮的血液来酿制一种致命的新药剂。它突显了皇家药剂师协会对于完善他们的The New Plague所表现出的阴暗执着，同时也体现了他们对希尔斯布莱德丘陵自然生命力的厌恶。",h="这项任务由塔伦米尔的药剂师林度恩委派，要求部落的冒险者收集山地狮的血液来酿制一种致命的新药剂。它突显了皇家药剂师协会对于完善他们的The New...",kw={"药剂师林度恩","痛苦药剂","希尔斯布莱德丘陵","山地狮的血液","新瘟疫","皇家药剂师协会","塔伦米尔"},ang={["faction:Horde"]="被遗忘者的盟友必须适应塔伦米尔炼金术士的阴暗手段，协助猎杀野兽，以巩固部落在希尔斯布莱德的立足点，抵御附近人类的威胁。",["race:Undead"]="对于被遗忘者的旅行者来说，为药剂师林度恩收集试剂，直接服务于黑暗女王和皇家药剂师协会在洛丹伦宣示主权的使命。"},sec={{t="塔伦米尔的苦涩前景",b="驻扎在塔伦米尔时，药剂师林度恩对周围的景观感到一丝愉悦都欠奉。他望向窗外，看着希尔斯布莱德盛开的草地和清新的山间空气，将该地区持久的生命力视为一种冒犯。与皇家药剂师协会中的许多人一样，他个人的忠诚归属于希尔瓦娜斯·风行者，以及对The New Plague的完善——这是一种旨在为生者带来死亡，为他们的敌人带来报复的工程瘟疫。"},{t="苦难的成分",b="为了研制他最新的毒药混合物，林度恩将目光投向了潜伏在丘陵地带和通往奥特兰克山脉斜坡上的当地动物。他认为山地狮的血液具有酿制他所谓的痛苦药剂所需的特定属性，因此派遣代理人进入荒野，索取十瓶血液。这些收集品成为了协会在南部前线进行化学试验的基础。"}},faq={{q="谁发布了痛苦药剂任务？",a="该任务由药剂师林度恩发布，他是一名驻扎在希尔斯布莱德丘陵塔伦米尔定居点的被遗忘者炼金术师。",al={"痛苦药剂任务发布者","谁开启痛苦药剂","药剂师林度恩任务"}},{q="为什么药剂师林度恩需要山地狮的血液？",a="林度恩的炼金研究表明，山地狮的血液是酿制一种致命新药剂的关键试剂，这种药剂旨在推进皇家药剂师协会针对生者敌人的瘟疫实验。",al={"为什么需要山地狮血液","狮血用途","血液的用途是什么"}},{q="在哪里可以找到山地狮？",a="山地狮潜伏在希尔斯布莱德丘陵开阔的田野和连绵起伏的丘陵中，以及通往奥特兰克山脉的高处悬崖边。",al={"哪里有山地狮","希尔斯布莱德山地狮位置","狮血收集"}},{q="林度恩提到的The New Plague是什么？",a="The New Plague是一种生物武器，正由被遗忘者的皇家药剂师协会在希尔瓦娜斯·风行者的命令下进行细致的研究和开发，旨在根除天灾军团和生者。",al={"什么是新瘟疫","皇家药剂师协会瘟疫","被遗忘者瘟疫"}},{q="完成此任务后会发生什么？",a="上交十瓶山地狮血液后，任务将直接导向后续任务，药剂师林度恩将开始测试他新酿造的药剂。",al={"痛苦药剂后续任务","痛苦药剂后续","痛苦药剂接下来的任务"}},{q="为什么林度恩厌恶希尔斯布莱德的风景？",a="作为黑暗女王的亡灵仆从，林度恩憎恶该地区盛开的植物群、新鲜的空气和顽强的生命力，他更希望看到活生生的世界被他协会的毒药所淹没。",al={"为什么林度恩讨厌希尔斯布莱德","为什么林度恩在沉思","林度恩窗边语录"}}},fp="14,159,31.394.0,22.395.0,35.124.0,51.185.0,38.137.0,38.194.0,44.110.0,43.183.0"}
P.entries["quest:502"] = {n="痛苦药剂",s="这项任务由塔伦米尔的药剂师林度恩委托，要求部落特工测试一种新酿造的名为痛苦药剂的生物制剂。这位被遗忘者药剂师选择了希尔斯布莱德农场雷农夫家的一只宠物狗斯坦利作为毫无防备的测试对象。",h="这项任务由塔伦米尔的药剂师林度恩委托，要求部落特工测试一种新酿造的名为痛苦药剂的生物制剂。这位被遗忘者药剂师选择了希尔斯布莱德农场雷农夫家的一只宠物狗斯坦利作为毫无防备的测试对象。",kw={"药剂师林度恩","痛苦药剂","雷农夫","希尔斯布莱德农场","皇家药剂师协会","斯坦利","塔伦米尔"},ang={["class:Hunter"]="将实验性药剂喂给农夫信任的宠物狗，显示了被遗忘者药剂师对卷入试验的生物是多么漠不关心。",["faction:Horde"]="被遗忘者的盟友被直接卷入了他们针对希尔斯布莱德邻近人类农场的残酷化学试验中。",["race:Undead"]="这个实验突显了皇家药剂师协会的无情手段，他们寻求生物武器以确保被遗忘者的生存，而不顾附带损害。"},sec={{t="药剂学",b="药剂师林度恩以塔伦米尔为基地，代表皇家药剂师协会和希尔瓦娜斯·风行者女士进行实验。林度恩利用从当地野生动物身上采集的新鲜血液，调制出一种他称为痛苦药剂的挥发性混合物。该协会不仅仅依赖理论炼金术，还需要实地经验数据来观察他们实验性毒药和诱变剂的生理效应。"},{t="测试斯坦利",b="为了在不惊动希尔斯布莱德人类守卫的情况下评估这种药剂，林度恩指引他的特工前往希尔斯布莱德农场的北部农场。那里住着斯坦利，一只雷农夫饲养的看似无害的宠物狗。特工将药剂倒在手心中接近这只毫无防备的犬类，伪装成普通的零食喂给它。"},{t="剧烈突变",b="痛苦药剂的真正本质在摄入后立即显现出来。这种混合物并非直接的致命毒素，而是一种可怕的诱变剂，它引发了瞬间的剧痛，并使斯坦利的身体剧烈扭曲，变成了一只野蛮、狂暴的狼。这头野兽开始疯狂攻击附近的一切，证明了林度恩炼金配方的挥发性效力。"}},faq={{q="痛苦药剂的目的是什么？",a="药剂师林度恩酿造痛苦药剂是皇家药剂师协会为希尔瓦娜斯和被遗忘者设计生物武器和强效诱变剂的持续努力的一部分。",al={"痛苦药剂目标","为什么要制造痛苦药剂","林度恩痛苦药剂目的"}},{q="斯坦利是谁？",a="斯坦利是雷农夫的宠物狗，住在希尔斯布莱德农场北端的大农舍外。",al={"谁是斯坦利","雷农夫的狗","狗斯坦利"}},{q="给斯坦利喂食药剂后会发生什么？",a="林度恩想看看斯坦利是否喜欢他的“零食”。当斯坦利吃下药剂后，其真正作用就会显现出来。",al={"斯坦利突变","药剂对狗有什么作用","斯坦利狼"}},{q="斯坦利在哪里？",a="斯坦利在希尔斯布莱德农场的北部农场，塔伦米尔的西南方，那座大房子外徘徊。",al={"找到斯坦利","斯坦利位置","雷农夫的狗在哪里"}},{q="是谁发布了测试药剂的任务？",a="药剂师林度恩，驻扎在希尔斯布莱德丘陵的被遗忘者定居点塔伦米尔。在你收集了必要的试剂后，他会提供这个任务。",al={"痛苦药剂任务发布者","谁给痛苦药剂任务","药剂师林度恩任务"}},{q="为什么要用农夫的狗而不是人类来测试药剂？",a="在希尔斯布莱德农场对家养宠物进行测试提供了一个安静、易于进行的试验，而不会立即惊动希尔斯布莱德的城镇民兵或武装警卫，使其察觉到炼金试验的性质。",al={"为什么在狗身上测试","为什么是斯坦利","为什么要毒害狗"}}},fp="14,151,18.309.0,18.251.0,16.258.1,42.171.0,15.110.0,46.111.1,25.107.0,39.153.0,56.153.0"}
P.entries["quest:503"] = {n="高迪尔",s="克鲁斯克已经查阅了你获得的那些文件，并推断出戈尔迪尔被关押在北方的一个大型辛迪加基地中，很有可能就在奥特兰克山脉。戈尔迪尔被囚禁的时间太长了，必须尽快救出他。",h="克鲁斯克已经查阅了你获得的那些文件，并推断出戈尔迪尔被关押在北方的一个大型辛迪加基地中，很有可能就在奥特兰克山脉。戈尔迪尔被囚禁的时间太长了，必须尽快救出他。",kw={"奥特兰克","博胡因","戈尔迪尔","钥匙","克鲁斯克","斯坦恩布莱德","辛迪加","塔伦米尔"},sec={{t="北方的线索",b="位于塔伦米尔的克鲁斯克仔细查阅了你在“渗透”任务后带回来的文件。这些文件指出戈尔迪尔被关押在北方的一个大型辛迪加基地中，很有可能就在奥特兰克山脉。克鲁斯克说，他被囚禁的时间太长了，必须尽快救出戈尔迪尔。"},{t="斯坦恩布莱德的旅店",b="戈尔迪尔被关押在斯坦恩布莱德旅店的顶层房间里，旅店里挤满了辛迪加成员。锈铁钥匙可以打开牢笼的锁，它由典狱官博胡因携带；博胡因可能出现在镇上的任何建筑里。"},{t="戈尔迪尔的话",b="一旦获救，戈尔迪尔会解释说，酋长的命令派他率领一支探险队离开杜隆塔尔，但计划出了一些差错。辛迪加一直把他关在那座城镇里，强迫他干活、搬运重物和挖掘。他对自己所受的苦难轻描淡写，因为他有重要的情报需要转达给目前该组织的领导者。"}},faq={{q="是谁囚禁了戈尔迪尔？",a="辛迪加将他关押在北方的一个大型基地中。",al={"谁抓了戈尔迪尔","谁有戈尔迪尔","戈尔迪尔的俘获者"}},{q="戈尔迪尔被关在哪里？",a="在斯坦恩布莱德旅店的顶层房间里，那里挤满了辛迪加成员。",al={"戈尔迪尔的位置","戈尔迪尔在哪","找到戈尔迪尔"}},{q="如何打开戈尔迪尔的锁？",a="使用锈铁钥匙，该钥匙由典狱官博胡因携带，他可能在斯坦恩布莱德的任何一栋建筑里。",al={"锈铁钥匙","如何解锁戈尔迪尔","戈尔迪尔的钥匙"}},{q="这个任务链的上一步是什么？",a="“渗透”，在该任务中你获得了指向戈尔迪尔关押地点的文件。",al={"上一个任务","戈尔迪尔之前的任务是什么","戈尔迪尔之前的任务线"}}},fp="7,184,20.225.0,21.188.0,17.275.1,31.57.0,28.95.0,29.107.0,40.97.0"}
P.entries["quest:504"] = {n="破碎岭好战者",s="南海镇的治安官雷德帕斯希望你能给石拳食人魔更沉重的打击。你被派往奥特兰克废墟去寻找Crushridge Warmongers，让这些蛮族远离联盟。",h="南海镇的治安官雷德帕斯希望你能给石拳食人魔更沉重的打击。你被派往奥特兰克废墟去寻找Crushridge Warmongers，让这些蛮族远离联盟。",kw={"奥特兰克","石拳","食人魔","雷德帕斯","废墟","南海镇","好战者"},sec={{t="更严厉的教训",b="在完成了Crushridge Bounty任务后，治安官雷德帕斯希望这些食人魔能真正地长点记性。雷德帕斯派你进入奥特兰克废墟寻找Crushridge Warmongers并大量消灭他们。雷德帕斯认为只有这样才能让这些蛮族不敢靠近联盟领地。"}},faq={{q="是谁派你去对付Crushridge Warmongers的？",a="南海镇的治安官雷德帕斯。",al={"谁发布了crushridge warmongers任务","crushridge warmongers任务发布者","治安官雷德帕斯任务"}},{q="Crushridge Warmongers在哪里？",a="在山上的奥特兰克废墟里。",al={"crushridge warmongers在哪里","warmonger位置","crushridge warmongers地点"}},{q="为什么治安官雷德帕斯要你消灭Warmongers？",a="雷德帕斯相信只有这样才能教会石拳食人魔远离联盟的领地。",al={"为什么要杀warmongers","crushridge warmongers任务目的","雷德帕斯对付食人魔的理由"}},{q="这个任务的前置任务是什么？",a="这是Crushridge Bounty任务的后续，那是雷德帕斯第一次要求你猎杀石拳食人魔。",al={"crushridge warmongers的前置任务","warmongers之前的任务","crushridge warmongers任务链"}}},fp="21,202,15.281.0,46.30.0,36.45.0,54.95.0,29.80.0"}
P.entries["quest:5041"] = {n="十字路口的补给品",s="“贫瘠之地的补给”是索克发布的一项部落任务，旨在找回在钢鬃野猪人袭击中丢失的必要物资。通过从多刺的营地中收回这些失落的补给箱，冒险者帮助十字路口在持续的区域冲突中维持运转。",h="“贫瘠之地的补给”是索克发布的一项部落任务，旨在找回在钢鬃野猪人袭击中丢失的必要物资。通过从多刺的营地中收回这些失落的补给箱，冒险者帮助十字路口在持续的区域冲突中维持运转。",kw={"贫瘠之地","商队","补给箱","十字路口","野猪人","钢鬃","补给","索克"},ang={["faction:Horde"]="守住十字路口对于连接杜隆塔尔和莫高雷的部落首都是至关重要的；找回被劫的货物能确保这个前哨站的补给充足。",["race:Orc"]="保护这些重要的补给线免受野猪人的偷窃，是捍卫新部落不断扩张的定居点的一项基本职责。"},sec={{t="岌岌可危的生命线",b="十字路口是部落在贫瘠之地进行旅行、贸易和防御的中心枢纽。维持这样一个枢纽的运作需要来自杜隆塔尔和莫高雷的稳定货物补给。当一支补给商队遭到伏击时，前哨站会立刻面临物资、工具和武器的短缺，而这些正是应对严酷荒野的关键。"},{t="偷窃的野猪人",b="袭击的元凶是钢鬃野猪人，这些本土的猪形野兽与部落争夺卡利姆多中部的控制权。野猪人并没有毁掉这些被偷走的货物，而是将沉重的补给箱拖回了他们加固过的荆棘营地，据为己有。索克委派受信任的勇士深入钢鬃营地，夺回本属于部落的财物。"}},faq={{q="谁发布了这个任务？",a="索克，负责监督十字路口防御和运作的部落军官，发布了这个任务。",al={"任务发布者","索克任务","谁开启贫瘠之地的补给"}},{q="补给品最初为什么会被偷走？",a="一支前往十字路口的补给商队遭到了好战的钢鬃野猪人的伏击，野猪人将补给箱运回了他们附近的营地。",al={"商队袭击","为什么被偷","补给品发生了什么"}},{q="在哪里可以找到被偷的补给箱？",a="被偷的十字路口补给箱散落在十字路口东部和东北部的钢鬃野猪人营地地面上。",al={"补给箱位置","补给品在哪里","寻找补给箱"}},{q="为什么找回这些补给对索克如此重要？",a="十字路口是一个四周充满敌意威胁的孤立而繁忙的枢纽。丢失的商队会威胁到前哨站的日常运作和安全，导致士兵和旅行者都缺少关键的必需品。",al={"为什么要在意","十字路口的重要性","补给品的重要性"}},{q="这个任务的前置任务是什么？",a="此任务紧随“干扰攻击”之后，冒险者首先需要打击钢鬃野猪人的势力，以削弱他们对部落运输路线的侵略。",al={"前置任务","上一个任务","干扰攻击"}},{q="钢鬃是谁？",a="钢鬃是一个凶猛的、具有领土意识的野猪人部落，他们是贫瘠之地的原住民，经常袭击商队，并激烈反抗部落在他们祖居地上的存在。",al={"钢鬃野猪人","谁是野猪人","钢鬃"}}},fp="27,161,22.298.0,17.267.0,21.94.0,48.118.0,37.117.0,55.158.0,29.131.0,22.158.0"}
P.entries["quest:5042"] = {n="阿迦玛甘的力量",s="阿迦玛甘的力量是一项可重复的仪式，由囚禁在陶拉祖营地的野猪人碎牙提供。通过上交在贫瘠之地各处搜集的红色血岩碎片，旅行者可以获得刺鬃部落最强战士所崇敬的强大肉体力量。这满足了碎牙对敌对刺背野猪人部落的刻骨仇恨。",h="阿迦玛甘的力量是一项可重复的仪式，由囚禁在陶拉祖营地的野猪人碎牙提供。通过上交在贫瘠之地各处搜集的红色血岩碎片，旅行者可以获得刺鬃部落最强战士所崇敬的强大肉体力量。这满足了碎牙对敌对刺背野猪人部落的刻骨仇恨。",kw={"阿迦玛甘","贫瘠之地","血岩碎片","刺背","陶拉祖营地","碎牙","野猪人","剃刀鬃"},ang={["class:Warrior"]="对于那些在卡利姆多战场上冲锋陷阵的战士来说，由碎牙引导的原始野猪神之力能提供不可小觑的肉体优势。",["faction:Horde"]="陶拉祖营地的守卫将碎牙牢牢关押，但部落指挥官们对于利用这位老萨满对敌对野猪人的复仇渴望并没有什么心理负担。",["race:Tauren"]="虽然牛头人维持着陶拉祖营地并警惕地监视着碎牙，但他们的萨满承认阿迦玛甘是这片土地的远古守护神，尽管野猪人的狂热已经扭曲了对他的记忆。"},sec={{t="巨猪之力",b="野猪人崇拜着远古的半神野猪阿迦玛甘，据传，正是他流出的血液在贫瘠之地各地形成了那些带刺的红色血岩碎片。对野猪人而言，汲取这些水晶的力量是一种神圣的仪式，能赋予他们的前线战士恐怖的肉体力量。虽然身陷陶拉祖营地的囚笼，但老剃刀鬃萨满碎牙却非常乐意将这种力量传授给部落的勇士，声称你的敌人在面对你时，会像面对剃刀鬃最可怕的战士一样感到恐惧。"},{t="苦涩萨满的复仇",b="碎牙的慷慨完全出于恶意。这名年老的野猪人被兽人和牛头人俘虏并关进笼子，他对自己的剃刀鬃部族所敌视的刺背部落怀有深仇大恨。既然他无法挣脱锁链亲手屠戮他们，他便将阿迦玛甘的远古馈赠作为筹码，以此奖励那些能够屠杀刺背部族并掠夺他们土地上神圣血岩碎片的人。"}},faq={{q="阿迦玛甘的力量能提供什么？",a="通过水晶状的血岩碎片引导半神野猪阿迦玛甘的潜在力量，这种祝福能强化接受者的肉体素质，重现剃刀鬃部族先锋们所拥有的野蛮力量。",al={"阿迦玛甘的力量有什么作用","阿迦玛甘的力量增益","贫瘠之地力量祝福"}},{q="碎牙是谁？",a="碎牙是被囚禁在南贫瘠之地陶拉祖营地笼中的一名剃刀鬃野猪人。他极其憎恨敌对的刺背部落，因此很乐意用野猪人的秘密和神圣的祝福来交换血岩碎片。",al={"碎牙是谁","陶拉祖被囚禁的野猪人","陶拉祖的囚犯"}},{q="什么是血岩碎片？",a="血岩碎片是一种在贫瘠之地各处发现的淡红色、类似矿石的晶体。野猪人的传统教义认为，这些石头是在上古之战期间，他们的守护半神——巨猪阿迦玛甘的血液滴落到大地上时形成的。",al={"什么是血岩碎片","血岩碎片背景故事","血岩碎片来源"}},{q="为什么碎牙要帮助部落？",a="碎牙的援助源于他对敌对的刺背野猪人的仇恨。他被自己的族人抛弃，并被关押在陶拉祖营地，只要你能屠杀他的对手并劫掠他们神圣的血岩碎片，他就会热切地将阿迦玛甘的祝福赐予部落勇士。",al={"为什么碎牙帮助我们","碎牙的动机","为什么帮助部落"}},{q="你能多次获得这种祝福吗？",a="可以。一旦你通过完成他的初步试炼证明了自己的实力，当你再带给他四个血岩碎片时，他就会继续为你编织阿迦玛甘的力量以及其他恩赐。",al={"阿迦玛甘的力量可以重复吗","可重复的血岩碎片","上交更多血岩碎片"}},{q="刺背部落和剃刀鬃部落有什么区别？",a="刺背和剃刀鬃是在贫瘠之地争斗的敌对野猪人派系。碎牙属于剃刀鬃，他非常鄙视刺背，并自夸剃刀鬃才是更强大的部族。",al={"刺背对比剃刀鬃","贫瘠之地的野猪人部族","碎牙为什么讨厌刺背"}}},fp="20,237,23.442.0,27.367.0,37.166.0,19.184.0,22.221.0,36.249.0,45.159.0,68.185.0"}
P.entries["quest:5043"] = {n="阿迦玛甘的敏捷",s="“阿迦玛甘的敏捷”是一项可重复进行的血岩碎片仪式，由被囚禁在陶拉祖营地的野猪人碎牙提供。通过上交从贫瘠之地大地中挖掘出的结晶状血岩碎片，旅行者们可以获得这位野猪人古代半神所赐予的精准与迅捷。",h="“阿迦玛甘的敏捷”是一项可重复进行的血岩碎片仪式，由被囚禁在陶拉祖营地的野猪人碎牙提供。通过上交从贫瘠之地大地中挖掘出的结晶状血岩碎片，旅行者们可以获得这位野猪人古代半神所赐予的精准与迅捷。",kw={"阿迦玛甘","敏捷","贫瘠之地","血岩碎片","碎牙","野猪人","陶拉祖"},ang={["class:Hunter"]="阿迦玛甘的敏捷核心在于精准的瞄准和迅速的潜行，这对于穿行在卡利姆多广袤荒野的神射手来说，是备受推崇的品格。",["class:Rogue"]="碎牙特别嘲笑非野猪人潜行者的速度，因此当利用这头野兽的神圣速度去对抗灌木丛中的部族时，这仪式便成了一种无声的昭雪。",["faction:Horde"]="陶拉祖营地的部落部队容忍碎牙的存在及其血岩碎片交易，纯粹是因为利用这位野猪半神的残留力量有助于他们在这片贫瘠之地上进行的艰苦战役。",["race:Tauren"]="牛头人尊重那些在上古之战中牺牲的古代半神的力量，尽管与陶拉祖营地中一只被囚禁的野猪人打交道是一种不安的妥协。"},sec={{t="血岩碎片的力量",b="在整个贫瘠之地，随处可见一种被称为血岩碎片的奇异深红色矿物从土壤中突起，尤其是在野猪人的营地和巨大的荆棘丛附近。野猪人的传统认为，这些晶体是由阿迦玛甘的鲜血凝结而成，这位伟大的野猪半神在上古之战中为了对抗燃烧军团而牺牲。即使被关在陶拉祖营地的木笼里，年长的野猪人碎牙依然保留着引导这种休眠神力的知识，只要有人愿意提供这些晶石，他便会施法。"},{t="野猪斥候的祝福",b="野猪人猎手和斥候以他们那残酷的精准度和在灌木丛中快如闪电的动作而自豪。作为交换四块血岩碎片的报酬，碎牙会唤醒这位陨落的半神潜藏的能量，将他们族群中最优秀的潜行者所拥有的捕食本能和柔韧优雅赋予祈求者。尽管碎牙对这些外来者嗤之以鼻，但他依然信守契约，将阿迦玛甘的力量编织成一种暂时的敏捷护甲。"}},faq={{q="谁提供“阿迦玛甘的敏捷”？",a="该任务由碎牙提供，他是一只被囚禁在南贫瘠之地陶拉祖营地牢笼中的钢鬃野猪人。尽管被部落囚禁，他仍乐意与带给他血岩碎片的冒险者进行交易。",al={"任务提供者","任务给予者","碎牙位置"}},{q="什么是血岩碎片？",a="血岩碎片是散落在整个贫瘠之地的晶体石块，主要从被杀死的野猪人身上和荆棘丛附近的矿脉中收集。野猪人的传说认为，这些碎片形成于数千年前，当时伟大的野猪半神阿迦玛甘的鲜血浸透了大地的每一寸土地。",al={"血岩碎片背景","什么是血岩碎片","贫瘠之地的红色晶体"}},{q="为什么被囚禁的野猪人会帮助部落成员？",a="碎牙忠于他的神阿迦玛甘，也忠于自己的生存。虽然他轻蔑地对待非野猪人，但他热切地用阿迦玛甘的神圣祝福交换血岩碎片，这让他即使身处敌人的牢笼中，也能掌控他所信仰神灵的神圣精华。",al={"为什么帮助我们","碎牙的动机","为什么碎牙会交谈"}},{q="这种祝福可以获得多次吗？",a="是的。该仪式完全可以重复进行。只要你向碎牙提供四块新鲜的血岩碎片，他就会为你重新唤起这位伟大野猪半神的祝福。",al={"是否可重复","能否重做任务","可重复的增益效果"}},{q="阿迦玛甘是谁？",a="阿迦玛甘是一头巨大的野猪半神，曾在上古神话时代漫步于卡利姆多。在一万年前的上古之战中，他挺身而出对抗燃烧军团的恶魔并最终陨落。他的鲜血滋养了贫瘠之地，孕育出这里无坚不摧的利刺荆棘和野猪人一族。",al={"谁是阿迦玛甘","野猪半神","伟大的野猪"}},{q="碎牙还提供其他祝福吗？",a="除了敏捷，碎牙还提供尊崇阿迦玛甘其他方面的仪式。通过交换血岩碎片，他可以施予能提升纯粹体力、智慧、奔跑速度以及如同利刃之皮般厚重护甲的祝福。",al={"其他血岩碎片任务","其他增益效果","碎牙奖励"}}},fp="19,219,25.426.0,27.381.0,31.196.0,22.269.0,48.201.0,45.141.0,18.301.0,46.204.0"}
P.entries["quest:5044"] = {n="阿迦玛甘的智慧",s="“阿迦玛甘的智慧”是一个部落的可重复任务，由被俘的野猪人碎牙在陶拉祖营地提供。通过上交在贫瘠之地收集的血岩碎片，施法者可以参与古老野猪半神阿迦玛甘的仪式魔法。",h="“阿迦玛甘的智慧”是一个部落的可重复任务，由被俘的野猪人碎牙在陶拉祖营地提供。通过上交在贫瘠之地收集的血岩碎片，施法者可以参与古老野猪半神阿迦玛甘的仪式魔法。",kw={"贫瘠之地","血岩碎片","野猪之神","陶拉祖营地","地卜师","碎牙","野猪人","阿迦玛甘的智慧"},ang={["class:Mage"]="热衷于魔法提升的法师们可以领会到通过阿迦玛甘的精华注入原始地卜力量所转化出的纯粹智力。",["class:Priest"]="研究区域信仰的牧师会发现，阿迦玛甘的神之血与精神强化仪式之间的直接联系，是原始神圣崇拜中一个引人入胜的方面。",["class:Shaman"]="野猪人的地卜术反映了萨满教的元素召唤，这使得野猪之神的碎片仪式既显得熟悉又独具狂野色彩。",["faction:Horde"]="部落在陶拉祖营地对碎牙的关押，为战士和秘法师提供了一种机会主义的方式，利用贫瘠之地的本土魔法来对抗周围的野猪人部族。"},sec={{t="血岩碎片与远古力量",b="野猪人碎牙被部落囚禁在陶拉祖营地，他用其种族的魔法秘密来换取被称为“血岩碎片”的深红色水晶。根据野猪人的信仰，这些碎片是阿迦玛甘滴落的鲜血结晶而成，这位高大的野猪半神在上古之战中牺牲。碎牙声称，他部族的地卜师和萨满依靠这些碎片将神圣力量引入他们的仪式中。"},{t="心智的祝福",b="虽然其他祭品可以从碎片中获得身体韧性或敏捷，但“智慧”仪式专门聚焦于智力和奥术能力。为了交换四块血岩碎片，碎牙会代表玩家祈求野猪半神的灵魂，祝福他们在面对冲突时变得狡黠，并在最后留下一句关于死亡的不祥提醒。"}},faq={{q="阿迦玛甘是谁？",a="阿迦玛甘是一位远古野猪半神，在万年前的上古之战中与燃烧军团作战。他倒在了贫瘠之地，他的血液渗入土壤，创造了巨大的荆棘藤蔓和水晶般的血岩碎片。",al={"阿迦玛甘背景故事","野猪之神是谁","野猪半神"}},{q="为什么碎牙愿意帮助部落？",a="碎牙是一个被囚禁在陶拉祖营地笼子里的野猪人。尽管他的部族对部落怀有强烈的仇恨，但他对血岩碎片的渴求和对生存的渴望压倒了忠诚，使他愿意以神圣的部族祝福来交换这些碎片。",al={"为什么帮助碎牙","碎牙的动机","被俘的野猪人"}},{q="什么是血岩碎片？",a="血岩碎片是在贫瘠之地野猪人领地中发现的红色矿物结构。野猪人传说声称，这些水晶是直接由半神阿迦玛甘在死亡时洒下的血液滴形成的。",al={"血岩碎片背景","什么是血岩碎片","贫瘠之地红色碎片"}},{q="这个仪式可以重复进行吗？",a="是的。一旦你在最初演示过血岩碎片后赢得了碎牙的信任，只要你想刷新祝福，他就会持续接受四块血岩碎片为一批的供奉。",al={"阿迦玛甘的智慧可以重复吗","可重复的血岩碎片","再次上交"}},{q="野猪人萨满崇拜其他神灵吗？",a="野猪人将阿迦玛甘奉为至高无上的神灵，认为自己是他的直系后裔。他们的萨满和地卜师直接从他那神话般的遗产和遗迹中汲取自然魔法和大地操纵之力。",al={"野猪人宗教","地卜师神灵","野猪人崇拜"}},{q="碎牙建议我们下次在哪里见面？",a="在完成仪式后，碎牙会告诉你，无论是在此生还是来世，只要下次见面时，就分享你狡黠的故事，以此承认贫瘠之地无休止的流血冲突。",al={"碎牙来世","碎牙对话"}}},fp="19,176,30.372.0,20.275.0,17.242.0,45.229.0,22.178.0,40.137.0,41.188.0,57.193.0"}
P.entries["quest:5045"] = {n="高涨的士气",s="升腾之灵是陶拉祖营地中的剃刀鬃岩法师碎牙所提供的仪式祝福。只要你从他的刺鬃竞争对手手中夺取血岩碎片，碎牙就会引导阿迦玛甘的远古力量，以此来激发勇士的意志力与精神韧性。",h="升腾之灵是陶拉祖营地中的剃刀鬃岩法师碎牙所提供的仪式祝福。只要你从他的刺鬃竞争对手手中夺取血岩碎片，碎牙就会引导阿迦玛甘的远古力量，以此来激发勇士的意志力与精神韧性。",kw={"阿迦玛甘","贫瘠之地","血岩碎片","刺鬃","陶拉祖营地","碎牙","剃刀鬃","升腾之灵"},ang={["class:Priest"]="牧师们会认出这种野猪人与阿迦玛甘的交流，是一种原始而纯粹的信仰与精神表达，丝毫不亚于东方教会那种组织严密的虔诚仪式。",["class:Shaman"]="萨满们理解这些古老的血统和大地矿石是如何将大地的精神与凡人战士紧密相连的。",["faction:Horde"]="对于在贫瘠之地游荡的部落成员来说，利用碎牙对刺鬃部落的深重族群仇恨，能将这个被俘虏的麻烦转变为宝贵的战术优势。"},sec={{t="剃刀鬃的意志",b="碎牙被关在陶拉祖营地的牢笼中，这位剃刀鬃长老对野猪人的地卜术和祖先魔法有着深刻的造诣。虽然其他部落可能在吹嘘他们粗野的战斗凶猛性，但碎牙对他族人向造物主——伟大的野猪之神阿迦玛甘——所展现的精神虔诚感到无比自豪。他教导人们，当力量在战斗中失效时，不屈的精神正是支撑战士生存下去的关键，能在绝望的关头推动勇士继续前进。"},{t="血岩碎片的力量",b="为了唤起这种精神升华，碎牙索要血岩碎片——这些结晶碎片浸透了阿迦玛甘在万年前渗入红土地的远古之血。通过从贫瘠之地各地收集碎片，特别是从他的刺鬃敌人身上获取碎片，你就为他提供了所需的原始精神导管，让他得以编织出鼓舞你意志的升腾之灵祝福。"}},faq={{q="碎牙是谁？",a="碎牙是一位年老的剃刀鬃野猪人，被关在陶拉祖营地的一个木笼里。尽管身陷部落的囹圄，他仍愿意通过交换血岩碎片来分享神圣的地卜仪式，并利用路过的冒险者来打击竞争对手刺鬃部落。",al={"碎牙背景故事","笼子里的野猪人是谁","陶拉祖囚犯"}},{q="什么是血岩碎片？",a="血岩碎片是远古半神阿迦玛甘流出的血液形成的红色矿物结晶，阿迦玛甘在万年前的上古之战中死于贫瘠之地。这些碎片蕴含着强大的残留魔法，野猪人的萨满和地卜师常利用它们来进行赐福和仪式。",al={"什么是血岩碎片","血岩碎片背景故事","阿迦玛甘之血"}},{q="为什么碎牙要帮助部落的冒险者？",a="碎牙对竞争对手刺鬃野猪人怀有刻骨铭心的仇恨。通过用祝福交换血岩碎片，他鼓励强大的冒险者在贫瘠之地各地屠杀刺鬃野猪人，即便自己身陷囹圄，也能推进他族群的宿怨。",al={"碎牙为何帮忙","野猪人为何帮助部落"}},{q="升腾之灵祝福有什么效果？",a="升腾之灵是碎牙给予的一种强大的祖先祝福，它能增强战士的精神和内在决心，汲取阿迦玛甘不朽的生命力，让战士在艰苦的战斗中保持希望。",al={"升腾之灵增益效果","什么是升腾之灵"}},{q="阿迦玛甘是谁？",a="阿迦玛甘是巨大的野猪之神，他在万年前的上古之战中与燃烧军团作战。野猪人尊他为造物主，认为贫瘠之地那些多刺的荆棘和红色的血岩碎片都是直接从他倒下的身躯中长出来的。",al={"阿迦玛甘","伟大的野猪之神"}},{q="这个仪式是一次性的交易吗？",a="不是。只要你带给碎牙四个血岩碎片，这位被俘的长老就愿意反复进行仪式，在你冒险重回荒野之前为你续上祝福。",al={"重复升腾之灵","升腾之灵可以重复吗"}}},fp="13,186,26.286.0,25.317.0,19.223.0,22.233.0,44.205.0,40.175.0,17.253.0,32.136.0"}
P.entries["quest:5046"] = {n="野猪之皮",s="锋锐外皮是陶拉祖营地中的被俘野猪人碎牙提供的一种可重复进行的仪式。通过向他提供注入了古老野猪半神阿迦玛甘生命精髓的血岩碎片，战士和旅者们可以在投入战斗前获得强化皮肤与韧性的强大祝福。",h="锋锐外皮是陶拉祖营地中的被俘野猪人碎牙提供的一种可重复进行的仪式。通过向他提供注入了古老野猪半神阿迦玛甘生命精髓的血岩碎片，战士和旅者们可以在投入战斗前获得强化皮肤与韧性的强大祝福。",kw={"阿迦玛甘","贫瘠之地","血岩碎片","陶拉祖营地","碎牙","野猪人","锋锐外皮"},ang={["class:Warrior"]="进入南贫瘠之地危险荆棘丛的前线战士，可以从魔法护甲和加固外皮中获益良多，这能削弱重击的威力。",["faction:Horde"]="陶拉祖营地是部落抵御野猪人不断侵袭的立足点，它将俘虏碎牙对阿迦玛甘的崇敬转化为旅行者的一项资产。",["race:Tauren"]="陶拉祖营地的猎手们密切监视着碎牙的笼子，他们意识到，虽然野猪人的仪式触及了大地母亲神圣的土地，但这些野蛮的践行者如果不收取报酬，是绝不会轻易分享秘密的。"},sec={{t="野猪之神的祝福",b="野猪人的祖先和力量直接源于阿迦玛甘，那位在数千年前对抗燃烧军团时牺牲的伟大野猪。他的血液渗入了贫瘠之地的土壤中，钙化成了至今仍搏动着古老力量的结晶血岩碎片。尽管野猪人依然是部落的死敌，但被关在陶拉祖营地笼子里的碎牙却愿意用他们的神圣知识来交换这些珍贵的碎片。"},{t="硬化外皮",b="野猪人的生理构造赋予了他们厚实的皮肤和保护性的棘刺，但部落战士会祈求阿迦玛甘的“锋锐外皮”祝福，以进一步保护自己免受敌人的利刃和爪牙伤害。通过引导四块血岩碎片，碎牙可以为外来者模仿这种部落仪式，以魔法增强冒险者的防御，让他们在荒野中骨骼不至于折断，皮肤也能抵御创伤。"}},faq={{q="谁提供锋锐外皮仪式？",a="该任务由碎牙提供，他是被关在南贫瘠之地陶拉祖营地木笼中的一名被俘野猪人。一旦你证明了你对血岩碎片的了解，他就会用各种祝福来换取更多的碎片。",al={"谁提供锋锐外皮","碎牙任务","谁开启锋锐外皮"}},{q="什么是血岩碎片？",a="血岩碎片是在贫瘠之地各处发现的结晶体。根据野猪人的信仰，它们是在上古之战期间由古老野猪阿迦玛甘流出的血液形成的，并保留了巨大的原始魔法能量。",al={"什么是血岩碎片","血岩碎片背景","阿迦玛甘之血"}},{q="为什么一个被俘的野猪人要帮助部落的旅行者？",a="碎牙是陶拉祖营地牛头人的俘虏。虽然他保留了粗野的举止和对他所信奉之神的忠诚，但他渴望血岩碎片，并愿意教导外来者野猪人的仪式以获得它们。",al={"为什么碎牙提供帮助","碎牙为什么在陶拉祖","友好的野猪人"}},{q="锋锐外皮代表什么样的保护？",a="锋锐外皮代表了野猪人在投入战斗前会祈求的部落守御。它能加厚皮肤并强化骨骼，用阿迦玛甘的超自然耐力来增强自身的防御。",al={"锋锐外皮有什么作用","锋锐外皮背景","防护祝福"}},{q="你可以多次获得锋锐外皮吗？",a="是的。就像碎牙提供的所有恩惠一样，锋锐外皮是一项可重复进行的交易。每当你带给他四块血岩碎片，他就会为你施加这一祝福。",al={"锋锐外皮可重复吗","重复锋锐外皮","锋锐外皮可以做多少次"}},{q="哪里可以找到血岩碎片？",a="血岩碎片通常是从遍布贫瘠之地的野猪人营地、荆棘丛和岩缝中的地卜师、猎手和战士身上搜刮来的。",al={"血岩碎片位置","从哪里获得血岩碎片","刷血岩碎片"}}},fp="9,189,25.365.0,18.296.0,32.203.0,22.179.0,54.187.0,49.147.0,41.85.0,32.137.0"}
P.entries["quest:505"] = {n="辛迪加刺客",s="赫尼·马雷布镇长是在前任镇长被暗杀后，新指派到南海镇的。他认为辛迪加雇佣了那些杀手。线索指向塔伦米尔以北的一处辛迪加营地，马雷布希望你能杀掉那里的成员。",h="赫尼·马雷布镇长是在前任镇长被暗杀后，新指派到南海镇的。他认为辛迪加雇佣了那些杀手。线索指向塔伦米尔以北的一处辛迪加营地，马雷布希望你能杀掉那里的成员。",kw={"奥特兰克","走卒","赫尼·马雷布","镇长","南海镇","辛迪加","塔伦米尔","盗贼"},sec={{t="遇刺的镇长",b="赫尼·马雷布镇长是南海镇的新任镇长，在前任镇长被暗杀后被指派到此。那些刺客从未被抓获，但马雷布几乎断定是辛迪加雇佣了他们。辛迪加是一个盗贼团伙，由已灭亡的奥特兰克王国的邪恶贵族所领导。马雷布的最后线索指向了塔伦米尔以北的一处辛迪加营地，那个地方现在由部落占据，马雷布请求你去杀掉在那里出没的辛迪加成员。"}},faq={{q="为什么赫尼·马雷布镇长想要消灭辛迪加？",a="南海镇的前任镇长被暗杀，马雷布几乎可以肯定辛迪加雇佣了那些至今仍未抓获的凶手。",al={"为什么杀辛迪加","辛迪加动机","谁杀了镇长"}},{q="谁领导着辛迪加？",a="由已灭亡的奥特兰克王国的邪恶贵族领导，成员皆为盗贼。",al={"谁经营辛迪加","辛迪加领袖","辛迪加奥特兰克"}},{q="辛迪加营地在哪里？",a="在塔伦米尔以北，部落占据了那里。马雷布的最后线索指向了那里。",al={"辛迪加走卒在哪里","辛迪加营地位置","去哪里找辛迪加盗贼"}}},fp="19,239,21.467.0,57.138.0,24.84.0,28.81.0"}
